#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PreprocessorInteger {
    bits: u64,
    unsigned: bool,
}

impl PreprocessorInteger {
    fn signed(value: i64) -> Self {
        Self {
            bits: value as u64,
            unsigned: false,
        }
    }

    fn unsigned(value: u64) -> Self {
        Self {
            bits: value,
            unsigned: true,
        }
    }

    fn truthy(self) -> bool {
        self.bits != 0
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SourceOrigin {
    name: String,
}

#[derive(Clone)]
struct LocatedToken {
    kind: Token,
    line: usize,
    column: usize,
    source_origin: Option<Rc<SourceOrigin>>,
    preprocessing_spelling: String,
    separated: bool,
}

impl PartialEq for LocatedToken {
    fn eq(&self, other: &Self) -> bool {
        self.kind == other.kind
            && self.line == other.line
            && self.column == other.column
            && self.source_origin == other.source_origin
    }
}

impl Eq for LocatedToken {}

impl fmt::Debug for LocatedToken {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("LocatedToken")
            .field("kind", &self.kind)
            .field("line", &self.line)
            .field("column", &self.column)
            .finish()
    }
}

impl LocatedToken {
    fn new(kind: Token, line: usize, column: usize) -> Self {
        let preprocessing_spelling = default_preprocessing_spelling(&kind);
        Self {
            kind,
            line,
            column,
            source_origin: None,
            preprocessing_spelling,
            separated: false,
        }
    }

    fn with_preprocessing_spelling(mut self, spelling: String, separated: bool) -> Self {
        self.preprocessing_spelling = spelling;
        self.separated = separated;
        self
    }

    fn source_origin_suffix(&self) -> String {
        self.source_origin
            .as_ref()
            .map_or_else(String::new, |origin| {
                format!(" in included header '{}'", origin.name)
            })
    }
}

