/// Interpret a small, safe C subset and return `main()`'s integer exit value.
///
/// Supported v0.1 syntax:
/// - `int main() { ... }` or `int main(void) { ... }`
/// - top-level `int`/`char` scalar, array, and pointer globals initialized before `main()`
/// - `int name(int param, char param, struct Point param, ...) { ... }` plus empty `void` parameter lists for function definitions/prototypes, including bounded recursion
/// - `int name = expression;` and `char name = expression;`
/// - `name = expression;`
/// - `return expression;`
/// - block statements: `{ ... }`
/// - `if (expression) statement else statement` with braced blocks, single-statement bodies, and `else if`
/// - `while (expression) statement`
/// - `do statement while (expression);`
/// - `for (initializer; condition; increment) statement`
/// - `switch (expression) { case constant: ... default: ... }` with C-style fallthrough
/// - `break;` and `continue;` inside loops
/// - empty statements (`;`) and side-effect-free expression statements (`expr;`)
/// - integer, character, and string literals (string literals are read-only NUL-terminated byte arrays)
/// - integer arithmetic/comparisons/logical operators: `+ - * / % == != < <= > >= && || !`
/// - pointer truthiness and pointer equality/inequality for null, scalar pointers, and array-backed pointers
/// - line comments (`// ...`) and C-style block comments (`/* ... */`)
pub fn interpret(source: &str) -> CustResult<i64> {
    interpret_with_options(source, InterpretOptions::default())
}

/// Execution options for interpreting a Cust source program.
#[derive(Debug, Clone, Copy, Default)]
pub struct InterpretOptions {
    pub max_loop_iterations: Option<usize>,
}

/// Interpret a Cust source program with explicit execution options.
pub fn interpret_with_options(source: &str, options: InterpretOptions) -> CustResult<i64> {
    interpret_tokens(lex(source)?, options)
}

/// Interpret a source file, allowing bounded quoted includes below its parent directory.
pub fn interpret_file(path: impl AsRef<Path>) -> CustResult<i64> {
    interpret_file_with_options(path, InterpretOptions::default())
}

/// Interpret a source file with explicit execution options and bounded quoted includes.
pub fn interpret_file_with_options(
    path: impl AsRef<Path>,
    options: InterpretOptions,
) -> CustResult<i64> {
    interpret_tokens(lex_file(path.as_ref())?, options)
}

fn interpret_tokens(tokens: Vec<LocatedToken>, options: InterpretOptions) -> CustResult<i64> {
    let mut parser = Parser::new(tokens);
    let program = parser.parse_program()?;
    let mut interpreter = Interpreter::new(options);
    interpreter.run(&program)
}

/// Format the lexer token stream for a Cust source program.
///
/// This powers the `cust --tokens <file.c>` CLI inspection mode. It intentionally
/// stops after lexing, so runtime errors such as division by zero are not
/// evaluated while inspecting tokens.
pub fn format_tokens(source: &str) -> CustResult<String> {
    Ok(format_token_stream(lex(source)?))
}

/// Format a source file's lexer tokens after resolving bounded quoted includes.
pub fn format_file_tokens(path: impl AsRef<Path>) -> CustResult<String> {
    Ok(format_token_stream(lex_file(path.as_ref())?))
}

fn format_token_stream(tokens: Vec<LocatedToken>) -> String {
    tokens
        .into_iter()
        .map(|token| match token.source_origin {
            Some(source_origin) => format!(
                "{}:{}:{} {:?}",
                source_origin.name, token.line, token.column, token.kind
            ),
            None => format!("{}:{} {:?}", token.line, token.column, token.kind),
        })
        .collect::<Vec<_>>()
        .join("\n")
        + "\n"
}

/// Format the parsed AST with deterministic function ordering.
///
/// This powers the `cust --ast <file.c>` CLI inspection mode. It intentionally
/// stops after parsing, so runtime errors such as division by zero are not
/// evaluated while inspecting the syntax tree.
pub fn format_ast(source: &str) -> CustResult<String> {
    format_ast_tokens(lex(source)?)
}

/// Format a source file's parsed AST after resolving bounded quoted includes.
pub fn format_file_ast(path: impl AsRef<Path>) -> CustResult<String> {
    format_ast_tokens(lex_file(path.as_ref())?)
}

fn format_ast_tokens(tokens: Vec<LocatedToken>) -> CustResult<String> {
    let mut parser = Parser::new(tokens);
    let program = parser.parse_program()?;
    let mut names = program.functions.keys().collect::<Vec<_>>();
    names.sort();

    let mut output = String::new();
    if !program.globals.is_empty() {
        output.push_str(&format!("globals: {:?}\n", program.globals));
    }
    for name in names {
        let function = &program.functions[name];
        output.push_str(&format!("function {name}\n"));
        output.push_str(&format!("  params: {:?}\n", function.params));
        output.push_str(&format!("  body: {:?}\n", function.body));
    }
    Ok(output)
}

fn lex(source: &str) -> CustResult<Vec<LocatedToken>> {
    lex_with_context(source, source, 1, 1, true, false, None)
}

fn lex_file(path: &Path) -> CustResult<Vec<LocatedToken>> {
    let mut source_file = open_header_file(path)
        .map_err(|err| CustError::io(format!("failed to read {}: {err}", path.display())))?;
    let source_metadata = source_file
        .metadata()
        .map_err(|err| CustError::io(format!("failed to read {}: {err}", path.display())))?;
    if !source_metadata.is_file() {
        return Err(CustError::io(format!(
            "failed to read {}: source is not a regular file",
            path.display()
        )));
    }
    #[cfg(unix)]
    let canonical_path = opened_file_identity(&source_file, path)
        .map_err(|err| CustError::io(format!("failed to read {}: {err}", path.display())))?;
    #[cfg(not(unix))]
    let canonical_path = path
        .canonicalize()
        .map_err(|err| CustError::io(format!("failed to read {}: {err}", path.display())))?;
    let source_identity = opened_source_identity(&source_file, &canonical_path)
        .map_err(|err| CustError::io(format!("failed to read {}: {err}", path.display())))?;
    let logical_project_root = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    #[cfg(target_os = "linux")]
    let (project_root, project_root_file) = {
        let file = open_header_file(logical_project_root)
            .map_err(|err| CustError::io(format!("failed to read {}: {err}", path.display())))?;
        let canonical = opened_file_identity(&file, logical_project_root)
            .map_err(|err| CustError::io(format!("failed to read {}: {err}", path.display())))?;
        (canonical, file)
    };
    #[cfg(not(target_os = "linux"))]
    let project_root = logical_project_root
        .canonicalize()
        .map_err(|err| CustError::io(format!("failed to read {}: {err}", path.display())))?;

    let file_name = path.file_name().ok_or_else(|| {
        CustError::io(format!(
            "failed to read {}: source is not a regular file",
            path.display()
        ))
    })?;
    let logical_path = project_root.join(file_name);
    let mut source = String::new();
    source_file
        .read_to_string(&mut source)
        .map_err(|err| CustError::io(format!("failed to read {}: {err}", path.display())))?;
    let chars = SplicedSourceChars::new(&source, 1, 1);
    let mut state = PreprocessorState {
        include_context: Some(IncludeContext {
            project_root,
            #[cfg(target_os = "linux")]
            project_root_file,
            stack: vec![IncludedSourcePath {
                logical: logical_path,
                identity: source_identity,
            }],
            pragma_once_headers: HashSet::new(),
            included_source_bytes: 0,
        }),
        ..PreprocessorState::default()
    };
    lex_spliced_with_state(&chars, &source, 1, 1, true, false, false, None, &mut state)
}

fn preprocessing_literal_quote_offset(chars: &[char], start: usize) -> Option<(usize, char)> {
    if chars.get(start..start + 3) == Some(&['u', '8', '"']) {
        return Some((2, '"'));
    }
    match chars.get(start).copied()? {
        quote @ ('\'' | '"') => Some((0, quote)),
        'L' | 'u' | 'U' => chars
            .get(start + 1)
            .copied()
            .filter(|quote| matches!(quote, '\'' | '"'))
            .map(|quote| (1, quote)),
        _ => None,
    }
}

fn lex_with_context(
    input: &str,
    source: &str,
    initial_line: usize,
    initial_column: usize,
    allow_preprocessor_directives: bool,
    preserve_preprocessor_integers: bool,
    token_limit: Option<(usize, &str)>,
) -> CustResult<Vec<LocatedToken>> {
    let chars = SplicedSourceChars::new(input, initial_line, initial_column);
    lex_spliced_with_context(
        &chars,
        source,
        initial_line,
        initial_column,
        allow_preprocessor_directives,
        false,
        preserve_preprocessor_integers,
        token_limit,
    )
}

#[allow(clippy::too_many_arguments)]
fn lex_spliced_with_context(
    chars: &SplicedSourceChars,
    source: &str,
    initial_line: usize,
    initial_column: usize,
    allow_preprocessor_directives: bool,
    allow_macro_hash_operator: bool,
    preserve_preprocessor_integers: bool,
    token_limit: Option<(usize, &str)>,
) -> CustResult<Vec<LocatedToken>> {
    let mut state = PreprocessorState::default();
    lex_spliced_with_state(
        chars,
        source,
        initial_line,
        initial_column,
        allow_preprocessor_directives,
        allow_macro_hash_operator,
        preserve_preprocessor_integers,
        token_limit,
        &mut state,
    )
}

#[allow(clippy::too_many_arguments)]
fn lex_spliced_with_state(
    chars: &SplicedSourceChars,
    source: &str,
    initial_line: usize,
    initial_column: usize,
    allow_preprocessor_directives: bool,
    allow_macro_hash_operator: bool,
    preserve_preprocessor_integers: bool,
    token_limit: Option<(usize, &str)>,
    state: &mut PreprocessorState,
) -> CustResult<Vec<LocatedToken>> {
    let mut tokens = Vec::new();
    let mut conditional_stack = Vec::<ConditionalFrame>::new();
    let mut i = 0;
    let mut line = initial_line;
    let mut column = initial_column;
    let mut line_has_preprocessing_token = false;
    let mut next_token_separated = false;
    let mut pending_pragma_start = None;

    while i < chars.len() {
        let c = chars[i];
        let conditional_active = conditional_stack.last().is_none_or(|frame| frame.active);
        if !conditional_active {
            match c {
                c if c.is_whitespace() => {
                    if c == '\n' {
                        line_has_preprocessing_token = false;
                    }
                    advance_position(chars, c, &mut line, &mut column, &mut i);
                }
                '/' if chars.get(i + 1) == Some(&'/') => {
                    while i < chars.len() && chars[i] != '\n' {
                        advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                    }
                }
                '/' if chars.get(i + 1) == Some(&'*') => {
                    let start_line = line;
                    let start_column = column;
                    advance_position(chars, '/', &mut line, &mut column, &mut i);
                    advance_position(chars, '*', &mut line, &mut column, &mut i);
                    let mut closed = false;
                    while i < chars.len() {
                        if chars[i] == '*' && chars.get(i + 1) == Some(&'/') {
                            advance_position(chars, '*', &mut line, &mut column, &mut i);
                            advance_position(chars, '/', &mut line, &mut column, &mut i);
                            closed = true;
                            break;
                        }
                        advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                    }
                    if !closed {
                        return Err(lexer_error_with_context(
                            "unterminated block comment",
                            source,
                            start_line,
                            start_column,
                        ));
                    }
                }
                '#' if !line_has_preprocessing_token => {
                    let consumed = process_preprocessor_directive(
                        source,
                        chars,
                        &mut i,
                        &mut line,
                        &mut column,
                        state,
                        &mut conditional_stack,
                        &mut tokens,
                    )?;
                    if !consumed {
                        skip_inactive_text_line(
                            source,
                            chars,
                            &mut i,
                            &mut line,
                            &mut column,
                            &mut line_has_preprocessing_token,
                        )?;
                    }
                }
                '%' if chars.get(i + 1) == Some(&':') && !line_has_preprocessing_token => {
                    let consumed = process_preprocessor_directive(
                        source,
                        chars,
                        &mut i,
                        &mut line,
                        &mut column,
                        state,
                        &mut conditional_stack,
                        &mut tokens,
                    )?;
                    if !consumed {
                        skip_inactive_text_line(
                            source,
                            chars,
                            &mut i,
                            &mut line,
                            &mut column,
                            &mut line_has_preprocessing_token,
                        )?;
                    }
                }
                _ => {
                    skip_inactive_text_line(
                        source,
                        chars,
                        &mut i,
                        &mut line,
                        &mut column,
                        &mut line_has_preprocessing_token,
                    )?;
                }
            }
            continue;
        }
        if c == '\n' {
            line_has_preprocessing_token = false;
        } else if !(c.is_whitespace()
            || c == '#'
            || (c == '%' && chars.get(i + 1) == Some(&':'))
            || (c == '/' && matches!(chars.get(i + 1), Some('/') | Some('*'))))
        {
            line_has_preprocessing_token = true;
        }
        let token_count_before = tokens.len();
        let token_start = i;
        let token_start_position = (line, column);
        match c {
            c if c.is_whitespace() => {
                next_token_separated = true;
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '/' if chars.get(i + 1) == Some(&'/') => {
                next_token_separated = true;
                advance_position(chars, '/', &mut line, &mut column, &mut i);
                advance_position(chars, '/', &mut line, &mut column, &mut i);
                while i < chars.len() && chars[i] != '\n' {
                    advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                }
            }
            '/' if chars.get(i + 1) == Some(&'*') => {
                next_token_separated = true;
                let start_line = line;
                let start_column = column;
                advance_position(chars, '/', &mut line, &mut column, &mut i);
                advance_position(chars, '*', &mut line, &mut column, &mut i);

                let mut closed = false;
                while i < chars.len() {
                    if chars[i] == '*' && chars.get(i + 1) == Some(&'/') {
                        advance_position(chars, '*', &mut line, &mut column, &mut i);
                        advance_position(chars, '/', &mut line, &mut column, &mut i);
                        closed = true;
                        break;
                    }
                    advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                }

                if !closed {
                    return Err(lexer_error_with_context(
                        "unterminated block comment",
                        source,
                        start_line,
                        start_column,
                    ));
                }
            }
            _ if (allow_macro_hash_operator || pending_pragma_start.is_some())
                && preprocessing_literal_quote_offset(chars, i).is_some() =>
            {
                let start = i;
                let start_line = line;
                let start_column = column;
                let (quote_offset, quote) = preprocessing_literal_quote_offset(chars, i)
                    .expect("guard requires a preprocessing literal");
                for _ in 0..quote_offset {
                    advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                }
                advance_position(chars, quote, &mut line, &mut column, &mut i);
                let mut closed = false;
                while i < chars.len() {
                    let current = chars[i];
                    if current == '\n' {
                        break;
                    }
                    advance_position(chars, current, &mut line, &mut column, &mut i);
                    if current == '\\' {
                        if i < chars.len() && chars[i] != '\n' {
                            advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                        }
                    } else if current == quote {
                        closed = true;
                        break;
                    }
                }
                if !closed {
                    let kind = if quote == '"' { "string" } else { "character" };
                    return Err(lexer_error_with_context(
                        format!("unterminated {kind} literal"),
                        source,
                        start_line,
                        start_column,
                    ));
                }
                let spelling: String = chars[start..i].iter().collect();
                tokens.push(LocatedToken::new(
                    Token::RawPreprocessor(spelling),
                    start_line,
                    start_column,
                ));
            }
            c if allow_macro_hash_operator
                && (c.is_ascii_digit()
                    || (c == '.' && chars.get(i + 1).is_some_and(char::is_ascii_digit))) =>
            {
                let start = i;
                let start_line = line;
                let start_column = column;
                advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                while i < chars.len() {
                    let current = chars[i];
                    let exponent_sign = matches!(current, '+' | '-')
                        && i > start
                        && matches!(chars[i - 1], 'e' | 'E' | 'p' | 'P');
                    if current.is_ascii_alphanumeric()
                        || matches!(current, '_' | '.')
                        || exponent_sign
                    {
                        advance_position(chars, current, &mut line, &mut column, &mut i);
                    } else {
                        break;
                    }
                }
                let spelling: String = chars[start..i].iter().collect();
                tokens.push(LocatedToken::new(
                    Token::RawPreprocessor(spelling),
                    start_line,
                    start_column,
                ));
            }
            '0'..='9' => {
                let start = i;
                let start_line = line;
                let start_column = column;
                let (digits_start, radix) = if chars[i] == '0'
                    && matches!(chars.get(i + 1), Some('x') | Some('X'))
                {
                    advance_position(chars, '0', &mut line, &mut column, &mut i);
                    let prefix = chars[i];
                    advance_position(chars, prefix, &mut line, &mut column, &mut i);
                    let digits_start = i;
                    while i < chars.len() && chars[i].is_ascii_hexdigit() {
                        advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                    }
                    if digits_start == i {
                        return Err(lexer_error_with_context(
                            "expected hexadecimal digits after integer literal prefix",
                            source,
                            start_line,
                            start_column,
                        ));
                    }
                    (digits_start, 16)
                } else if chars[i] == '0' {
                    advance_position(chars, '0', &mut line, &mut column, &mut i);
                    while i < chars.len() && chars[i].is_ascii_digit() {
                        if !matches!(chars[i], '0'..='7') {
                            return Err(lexer_error_with_context(
                                format!("invalid digit '{}' in octal integer literal", chars[i]),
                                source,
                                start_line,
                                start_column,
                            ));
                        }
                        advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                    }
                    (start, 8)
                } else {
                    while i < chars.len() && chars[i].is_ascii_digit() {
                        advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                    }
                    (start, 10)
                };
                let text: String = chars[digits_start..i].iter().collect();
                let unsigned_suffix =
                    consume_integer_suffix(source, chars, &mut line, &mut column, &mut i)?;
                let value = u64::from_str_radix(&text, radix).map_err(|_| {
                    lexer_error_with_context(
                        "integer literal out of range",
                        source,
                        start_line,
                        start_column,
                    )
                })?;
                let unsigned = unsigned_suffix || (radix != 10 && value > i64::MAX as u64);
                let token = if preserve_preprocessor_integers && unsigned {
                    Token::PreprocessorNumber(PreprocessorInteger::unsigned(value))
                } else if value <= i64::MAX as u64 {
                    Token::Number(value as i64)
                } else {
                    return Err(lexer_error_with_context(
                        "integer literal out of range",
                        source,
                        start_line,
                        start_column,
                    ));
                };
                tokens.push(LocatedToken::new(token, start_line, start_column));
            }
            '"' => {
                let start_line = line;
                let start_column = column;
                advance_position(chars, '"', &mut line, &mut column, &mut i);
                let mut values = Vec::new();

                loop {
                    let Some(next) = chars.get(i).copied() else {
                        return Err(lexer_error_with_context(
                            "unterminated string literal",
                            source,
                            start_line,
                            start_column,
                        ));
                    };
                    match next {
                        '"' => {
                            advance_position(chars, '"', &mut line, &mut column, &mut i);
                            values.push('\0' as i64);
                            tokens.push(LocatedToken::new(
                                Token::StringLiteral(values),
                                start_line,
                                start_column,
                            ));
                            break;
                        }
                        '\\' => {
                            advance_position(chars, '\\', &mut line, &mut column, &mut i);
                            let escaped = parse_escape_sequence(
                                source,
                                chars,
                                &mut line,
                                &mut column,
                                &mut i,
                                (start_line, start_column),
                                "string",
                            )?;
                            values.push(escaped);
                        }
                        '\n' => {
                            return Err(lexer_error_with_context(
                                "unterminated string literal",
                                source,
                                start_line,
                                start_column,
                            ));
                        }
                        value => {
                            advance_position(chars, value, &mut line, &mut column, &mut i);
                            values.push(value as i64);
                        }
                    }
                }
            }
            '\'' => {
                let start_line = line;
                let start_column = column;
                advance_position(chars, '\'', &mut line, &mut column, &mut i);

                let value = match chars.get(i).copied() {
                    Some('\\') => {
                        advance_position(chars, '\\', &mut line, &mut column, &mut i);
                        parse_escape_sequence(
                            source,
                            chars,
                            &mut line,
                            &mut column,
                            &mut i,
                            (start_line, start_column),
                            "character",
                        )?
                    }
                    Some('\n') | None => {
                        return Err(lexer_error_with_context(
                            "unterminated character literal",
                            source,
                            start_line,
                            start_column,
                        ));
                    }
                    Some(value) => {
                        advance_position(chars, value, &mut line, &mut column, &mut i);
                        value as i64
                    }
                };

                if chars.get(i) != Some(&'\'') {
                    return Err(lexer_error_with_context(
                        "unterminated character literal",
                        source,
                        start_line,
                        start_column,
                    ));
                }
                advance_position(chars, '\'', &mut line, &mut column, &mut i);
                tokens.push(LocatedToken::new(
                    Token::Number(value),
                    start_line,
                    start_column,
                ));
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                let start = i;
                let start_line = line;
                let start_column = column;
                while i < chars.len() && (chars[i].is_ascii_alphanumeric() || chars[i] == '_') {
                    advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                }
                let text: String = chars[start..i].iter().collect();
                if text == "__VA_ARGS__" && allow_preprocessor_directives {
                    return Err(lexer_error_with_context(
                        "'__VA_ARGS__' is only permitted in variadic function-like macro replacements",
                        source,
                        start_line,
                        start_column,
                    ));
                }
                if state.macros.contains_key(&text)
                    || (allow_preprocessor_directives && is_predefined_macro_name(&text))
                {
                    let mut input = vec![
                        LocatedToken::new(identifier_token(text.clone()), start_line, start_column)
                            .with_preprocessing_spelling(text, next_token_separated),
                    ];
                    while let Some((invocation_start, invocation_end)) =
                        macro_invocation_range(chars, i)
                    {
                        let invocation_chars = chars.slice(invocation_start, invocation_end);
                        let (invocation_line, invocation_column) = chars.position(invocation_start);
                        let mut invocation_tokens = lex_spliced_with_context(
                            &invocation_chars,
                            source,
                            invocation_line,
                            invocation_column,
                            false,
                            true,
                            true,
                            None,
                        )?;
                        invocation_tokens.pop();
                        input.extend(invocation_tokens);
                        while i < invocation_end {
                            advance_position(chars, chars[i], &mut line, &mut column, &mut i);
                        }
                    }
                    let predefined_source_name = current_predefined_source_name(state);
                    let expanded = expand_macro_tokens(
                        &input,
                        &state.macros,
                        &mut Vec::new(),
                        &mut state.macro_expansion_budget,
                        source,
                        &predefined_source_name,
                        state.predefined_line_offset,
                        false,
                        0,
                    )?;
                    let trailing_separation = expanded.trailing_separation;
                    append_expanded_tokens_with_pragmas(
                        expanded.tokens,
                        &mut tokens,
                        &mut pending_pragma_start,
                        state,
                        source,
                    )?;
                    next_token_separated = trailing_separation;
                    continue;
                }
                let kind = identifier_token(text);
                tokens.push(LocatedToken::new(kind, start_line, start_column));
            }
            '+' if chars.get(i + 1) == Some(&'+') => {
                push_token(&mut tokens, Token::PlusPlus, line, column);
                advance_position(chars, '+', &mut line, &mut column, &mut i);
                advance_position(chars, '+', &mut line, &mut column, &mut i);
            }
            '+' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::PlusAssign, line, column);
                advance_position(chars, '+', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '+' => {
                push_token(&mut tokens, Token::Plus, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '-' if chars.get(i + 1) == Some(&'-') => {
                push_token(&mut tokens, Token::MinusMinus, line, column);
                advance_position(chars, '-', &mut line, &mut column, &mut i);
                advance_position(chars, '-', &mut line, &mut column, &mut i);
            }
            '-' if chars.get(i + 1) == Some(&'>') => {
                push_token(&mut tokens, Token::Arrow, line, column);
                advance_position(chars, '-', &mut line, &mut column, &mut i);
                advance_position(chars, '>', &mut line, &mut column, &mut i);
            }
            '-' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::MinusAssign, line, column);
                advance_position(chars, '-', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '-' => {
                push_token(&mut tokens, Token::Minus, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '*' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::StarAssign, line, column);
                advance_position(chars, '*', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '*' => {
                push_token(&mut tokens, Token::Star, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '/' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::SlashAssign, line, column);
                advance_position(chars, '/', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '/' => {
                push_token(&mut tokens, Token::Slash, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '%' if allow_macro_hash_operator && chars.get(i + 1) == Some(&':') => {
                push_token(&mut tokens, Token::Hash, line, column);
                advance_position(chars, '%', &mut line, &mut column, &mut i);
                advance_position(chars, ':', &mut line, &mut column, &mut i);
            }
            '%' if chars.get(i + 1) == Some(&':') => {
                if !allow_preprocessor_directives {
                    return Err(lexer_error_with_context(
                        "macro replacement '#' operators are not supported",
                        source,
                        line,
                        column,
                    ));
                }
                if line_has_preprocessing_token {
                    return Err(lexer_error_with_context(
                        "preprocessor directives must begin on a new line",
                        source,
                        line,
                        column,
                    ));
                }
                process_preprocessor_directive(
                    source,
                    chars,
                    &mut i,
                    &mut line,
                    &mut column,
                    state,
                    &mut conditional_stack,
                    &mut tokens,
                )?;
            }
            '%' if chars.get(i + 1) == Some(&'>') => {
                push_token(&mut tokens, Token::RBrace, line, column);
                advance_position(chars, '%', &mut line, &mut column, &mut i);
                advance_position(chars, '>', &mut line, &mut column, &mut i);
            }
            '%' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::PercentAssign, line, column);
                advance_position(chars, '%', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '%' => {
                push_token(&mut tokens, Token::Percent, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '&' if chars.get(i + 1) == Some(&'&') => {
                push_token(&mut tokens, Token::AndAnd, line, column);
                advance_position(chars, '&', &mut line, &mut column, &mut i);
                advance_position(chars, '&', &mut line, &mut column, &mut i);
            }
            '&' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::AmpAssign, line, column);
                advance_position(chars, '&', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '&' => {
                push_token(&mut tokens, Token::Amp, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '|' if chars.get(i + 1) == Some(&'|') => {
                push_token(&mut tokens, Token::OrOr, line, column);
                advance_position(chars, '|', &mut line, &mut column, &mut i);
                advance_position(chars, '|', &mut line, &mut column, &mut i);
            }
            '|' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::PipeAssign, line, column);
                advance_position(chars, '|', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '|' => {
                push_token(&mut tokens, Token::Pipe, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '^' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::CaretAssign, line, column);
                advance_position(chars, '^', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '^' => {
                push_token(&mut tokens, Token::Caret, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '~' => {
                push_token(&mut tokens, Token::Tilde, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '(' => {
                push_token(&mut tokens, Token::LParen, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            ')' => {
                push_token(&mut tokens, Token::RParen, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '[' => {
                push_token(&mut tokens, Token::LBracket, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            ']' => {
                push_token(&mut tokens, Token::RBracket, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '{' => {
                push_token(&mut tokens, Token::LBrace, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '}' => {
                push_token(&mut tokens, Token::RBrace, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            ',' => {
                push_token(&mut tokens, Token::Comma, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            ';' => {
                push_token(&mut tokens, Token::Semi, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '.' => {
                push_token(&mut tokens, Token::Dot, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '?' => {
                push_token(&mut tokens, Token::Question, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            ':' if chars.get(i + 1) == Some(&'>') => {
                push_token(&mut tokens, Token::RBracket, line, column);
                advance_position(chars, ':', &mut line, &mut column, &mut i);
                advance_position(chars, '>', &mut line, &mut column, &mut i);
            }
            ':' => {
                push_token(&mut tokens, Token::Colon, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '=' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::Eq, line, column);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '!' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::Ne, line, column);
                advance_position(chars, '!', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '!' => {
                push_token(&mut tokens, Token::Bang, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '<' if chars.get(i + 1) == Some(&':') => {
                push_token(&mut tokens, Token::LBracket, line, column);
                advance_position(chars, '<', &mut line, &mut column, &mut i);
                advance_position(chars, ':', &mut line, &mut column, &mut i);
            }
            '<' if chars.get(i + 1) == Some(&'%') => {
                push_token(&mut tokens, Token::LBrace, line, column);
                advance_position(chars, '<', &mut line, &mut column, &mut i);
                advance_position(chars, '%', &mut line, &mut column, &mut i);
            }
            '<' if chars.get(i + 1) == Some(&'<') && chars.get(i + 2) == Some(&'=') => {
                push_token(&mut tokens, Token::ShiftLeftAssign, line, column);
                advance_position(chars, '<', &mut line, &mut column, &mut i);
                advance_position(chars, '<', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '<' if chars.get(i + 1) == Some(&'<') => {
                push_token(&mut tokens, Token::ShiftLeft, line, column);
                advance_position(chars, '<', &mut line, &mut column, &mut i);
                advance_position(chars, '<', &mut line, &mut column, &mut i);
            }
            '<' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::Le, line, column);
                advance_position(chars, '<', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '>' if chars.get(i + 1) == Some(&'>') && chars.get(i + 2) == Some(&'=') => {
                push_token(&mut tokens, Token::ShiftRightAssign, line, column);
                advance_position(chars, '>', &mut line, &mut column, &mut i);
                advance_position(chars, '>', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '>' if chars.get(i + 1) == Some(&'>') => {
                push_token(&mut tokens, Token::ShiftRight, line, column);
                advance_position(chars, '>', &mut line, &mut column, &mut i);
                advance_position(chars, '>', &mut line, &mut column, &mut i);
            }
            '>' if chars.get(i + 1) == Some(&'=') => {
                push_token(&mut tokens, Token::Ge, line, column);
                advance_position(chars, '>', &mut line, &mut column, &mut i);
                advance_position(chars, '=', &mut line, &mut column, &mut i);
            }
            '=' => {
                push_token(&mut tokens, Token::Assign, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '<' => {
                push_token(&mut tokens, Token::Lt, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '>' => {
                push_token(&mut tokens, Token::Gt, line, column);
                advance_position(chars, c, &mut line, &mut column, &mut i);
            }
            '#' => {
                if allow_macro_hash_operator {
                    push_token(&mut tokens, Token::Hash, line, column);
                    advance_position(chars, c, &mut line, &mut column, &mut i);
                } else {
                    if !allow_preprocessor_directives {
                        return Err(lexer_error_with_context(
                            "macro replacement '#' operators are not supported",
                            source,
                            line,
                            column,
                        ));
                    }
                    if line_has_preprocessing_token {
                        return Err(lexer_error_with_context(
                            "preprocessor directives must begin on a new line",
                            source,
                            line,
                            column,
                        ));
                    }
                    process_preprocessor_directive(
                        source,
                        chars,
                        &mut i,
                        &mut line,
                        &mut column,
                        state,
                        &mut conditional_stack,
                        &mut tokens,
                    )?;
                }
            }
            other => {
                return Err(lexer_error_with_context(
                    format!("unexpected character '{other}'"),
                    source,
                    line,
                    column,
                ));
            }
        }
        if tokens.len() == token_count_before + 1 && i > token_start {
            let token = tokens
                .last_mut()
                .expect("one emitted source token must be present");
            if (token.line, token.column) == token_start_position && token.source_origin.is_none() {
                token.preprocessing_spelling = chars[token_start..i].iter().collect();
                token.separated = next_token_separated;
                next_token_separated = false;
            }
        }
        if allow_preprocessor_directives && tokens.len() > token_count_before {
            if pending_pragma_start.is_none() {
                pending_pragma_start = tokens[token_count_before.min(tokens.len())..]
                    .iter()
                    .position(|token| preprocessor_identifier_name(&token.kind) == Some("_Pragma"))
                    .map(|offset| token_count_before + offset);
            }
            execute_pending_pragma_operators(
                &mut tokens,
                &mut pending_pragma_start,
                state,
                source,
                false,
            )?;
        }
        if let Some((directive_name, token)) = token_limit.and_then(|(limit, directive_name)| {
            tokens.get(limit).map(|token| (directive_name, token))
        }) {
            let message = if directive_name == "_Pragma" {
                "'_Pragma' payload token limit exceeded".to_string()
            } else {
                format!("'#{directive_name}' expression token limit exceeded")
            };
            return Err(lexer_error_with_context(
                message,
                source,
                token.line,
                token.column,
            ));
        }
    }

    if let Some(frame) = conditional_stack.last() {
        return Err(lexer_error_with_context(
            format!(
                "unterminated '#{}' conditional directive",
                frame.directive_name
            ),
            source,
            frame.line,
            frame.column,
        ));
    }

    execute_pending_pragma_operators(&mut tokens, &mut pending_pragma_start, state, source, true)?;

    tokens.push(LocatedToken::new(Token::Eof, line, column));
    Ok(tokens)
}

struct SplicedSourceChars {
    values: Vec<char>,
    positions: Vec<(usize, usize)>,
}

impl SplicedSourceChars {
    fn new(input: &str, mut line: usize, mut column: usize) -> Self {
        let raw: Vec<char> = input.chars().collect();
        let mut values = Vec::with_capacity(raw.len());
        let mut positions = Vec::with_capacity(raw.len() + 1);
        let mut cursor = 0;

        while cursor < raw.len() {
            if raw[cursor] == '\\' && raw.get(cursor + 1) == Some(&'\n') {
                cursor += 2;
                line += 1;
                column = 1;
                continue;
            }
            if raw[cursor] == '\\'
                && raw.get(cursor + 1) == Some(&'\r')
                && raw.get(cursor + 2) == Some(&'\n')
            {
                cursor += 3;
                line += 1;
                column = 1;
                continue;
            }

            let value = raw[cursor];
            positions.push((line, column));
            values.push(value);
            cursor += 1;
            if value == '\n' {
                line += 1;
                column = 1;
            } else {
                column += 1;
            }
        }
        positions.push((line, column));

        Self { values, positions }
    }

    fn position(&self, cursor: usize) -> (usize, usize) {
        self.positions[cursor]
    }

    fn slice(&self, start: usize, end: usize) -> Self {
        Self {
            values: self.values[start..end].to_vec(),
            positions: self.positions[start..=end].to_vec(),
        }
    }
}

impl std::ops::Deref for SplicedSourceChars {
    type Target = [char];

    fn deref(&self) -> &Self::Target {
        &self.values
    }
}

fn default_preprocessing_spelling(kind: &Token) -> String {
    match kind {
        Token::Int => "int".into(),
        Token::Char => "char".into(),
        Token::Bool => "_Bool".into(),
        Token::Float => "float".into(),
        Token::Double => "double".into(),
        Token::Complex => "_Complex".into(),
        Token::Imaginary => "_Imaginary".into(),
        Token::Signed => "signed".into(),
        Token::Unsigned => "unsigned".into(),
        Token::Long => "long".into(),
        Token::Short => "short".into(),
        Token::Const => "const".into(),
        Token::Volatile => "volatile".into(),
        Token::Restrict => "restrict".into(),
        Token::Atomic => "_Atomic".into(),
        Token::Static => "static".into(),
        Token::Extern => "extern".into(),
        Token::ThreadLocal => "_Thread_local".into(),
        Token::Inline => "inline".into(),
        Token::Noreturn => "_Noreturn".into(),
        Token::Auto => "auto".into(),
        Token::Register => "register".into(),
        Token::Void => "void".into(),
        Token::Enum => "enum".into(),
        Token::Struct => "struct".into(),
        Token::Union => "union".into(),
        Token::Typedef => "typedef".into(),
        Token::Sizeof => "sizeof".into(),
        Token::Alignof => "_Alignof".into(),
        Token::Alignas => "_Alignas".into(),
        Token::StaticAssert => "_Static_assert".into(),
        Token::Generic => "_Generic".into(),
        Token::Return => "return".into(),
        Token::If => "if".into(),
        Token::Else => "else".into(),
        Token::While => "while".into(),
        Token::Do => "do".into(),
        Token::For => "for".into(),
        Token::Switch => "switch".into(),
        Token::Case => "case".into(),
        Token::Default => "default".into(),
        Token::Break => "break".into(),
        Token::Continue => "continue".into(),
        Token::Goto => "goto".into(),
        Token::Ident(name) => name.clone(),
        Token::Number(value) => value.to_string(),
        Token::PreprocessorNumber(value) if value.unsigned => format!("{}U", value.bits),
        Token::PreprocessorNumber(value) => (value.bits as i64).to_string(),
        Token::RawPreprocessor(spelling) => spelling.clone(),
        Token::StringLiteral(values) => {
            let mut spelling = String::from("\"");
            for value in values.iter().copied().take_while(|value| *value != 0) {
                let character = char::from_u32(value as u32).unwrap_or('\u{fffd}');
                match character {
                    '\\' => spelling.push_str("\\\\"),
                    '"' => spelling.push_str("\\\""),
                    '\n' => spelling.push_str("\\n"),
                    '\r' => spelling.push_str("\\r"),
                    '\t' => spelling.push_str("\\t"),
                    other => spelling.push(other),
                }
            }
            spelling.push('"');
            spelling
        }
        Token::Plus => "+".into(),
        Token::Minus => "-".into(),
        Token::PlusPlus => "++".into(),
        Token::MinusMinus => "--".into(),
        Token::PlusAssign => "+=".into(),
        Token::MinusAssign => "-=".into(),
        Token::StarAssign => "*=".into(),
        Token::SlashAssign => "/=".into(),
        Token::PercentAssign => "%=".into(),
        Token::AmpAssign => "&=".into(),
        Token::PipeAssign => "|=".into(),
        Token::CaretAssign => "^=".into(),
        Token::ShiftLeftAssign => "<<=".into(),
        Token::ShiftRightAssign => ">>=".into(),
        Token::Star => "*".into(),
        Token::Slash => "/".into(),
        Token::Percent => "%".into(),
        Token::Amp => "&".into(),
        Token::AndAnd => "&&".into(),
        Token::Pipe => "|".into(),
        Token::OrOr => "||".into(),
        Token::Caret => "^".into(),
        Token::Tilde => "~".into(),
        Token::Bang => "!".into(),
        Token::Assign => "=".into(),
        Token::Eq => "==".into(),
        Token::Ne => "!=".into(),
        Token::Lt => "<".into(),
        Token::Le => "<=".into(),
        Token::ShiftLeft => "<<".into(),
        Token::Gt => ">".into(),
        Token::Ge => ">=".into(),
        Token::ShiftRight => ">>".into(),
        Token::LParen => "(".into(),
        Token::RParen => ")".into(),
        Token::LBracket => "[".into(),
        Token::RBracket => "]".into(),
        Token::LBrace => "{".into(),
        Token::RBrace => "}".into(),
        Token::Comma => ",".into(),
        Token::Semi => ";".into(),
        Token::Dot => ".".into(),
        Token::Arrow => "->".into(),
        Token::Question => "?".into(),
        Token::Colon => ":".into(),
        Token::Hash => "#".into(),
        Token::Eof => String::new(),
    }
}

fn identifier_token(text: String) -> Token {
    match text.as_str() {
        "int" => Token::Int,
        "char" => Token::Char,
        "_Bool" => Token::Bool,
        "float" => Token::Float,
        "double" => Token::Double,
        "_Complex" => Token::Complex,
        "_Imaginary" => Token::Imaginary,
        "signed" => Token::Signed,
        "unsigned" => Token::Unsigned,
        "long" => Token::Long,
        "short" => Token::Short,
        "const" => Token::Const,
        "volatile" => Token::Volatile,
        "restrict" => Token::Restrict,
        "_Atomic" => Token::Atomic,
        "static" => Token::Static,
        "extern" => Token::Extern,
        "_Thread_local" => Token::ThreadLocal,
        "inline" => Token::Inline,
        "_Noreturn" => Token::Noreturn,
        "auto" => Token::Auto,
        "register" => Token::Register,
        "void" => Token::Void,
        "enum" => Token::Enum,
        "struct" => Token::Struct,
        "union" => Token::Union,
        "typedef" => Token::Typedef,
        "sizeof" => Token::Sizeof,
        "_Alignof" => Token::Alignof,
        "_Alignas" => Token::Alignas,
        "_Static_assert" => Token::StaticAssert,
        "_Generic" => Token::Generic,
        "return" => Token::Return,
        "if" => Token::If,
        "else" => Token::Else,
        "while" => Token::While,
        "do" => Token::Do,
        "for" => Token::For,
        "switch" => Token::Switch,
        "case" => Token::Case,
        "default" => Token::Default,
        "break" => Token::Break,
        "continue" => Token::Continue,
        "goto" => Token::Goto,
        _ => Token::Ident(text),
    }
}

fn macro_replacement_token(token: LocatedToken, separated: bool) -> MacroReplacementToken {
    if let Some(name) = preprocessor_identifier_name(&token.kind) {
        MacroReplacementToken::Identifier {
            name: name.to_string(),
            separated,
        }
    } else {
        MacroReplacementToken::Other {
            kind: token.kind,
            spelling: token.preprocessing_spelling,
            separated,
        }
    }
}

fn macro_hash_pair_is_paste(tokens: &[LocatedToken], index: usize) -> bool {
    let Some(left) = tokens.get(index) else {
        return false;
    };
    let Some(right) = tokens.get(index + 1) else {
        return false;
    };
    left.kind == Token::Hash
        && right.kind == Token::Hash
        && !right.separated
        && matches!(
            (
                left.preprocessing_spelling.as_str(),
                right.preprocessing_spelling.as_str()
            ),
            ("#", "#") | ("%:", "%:")
        )
}

fn destringize_pragma_operator_literal(token: &LocatedToken, source: &str) -> CustResult<String> {
    if !matches!(
        token.kind,
        Token::StringLiteral(_) | Token::RawPreprocessor(_)
    ) {
        return Err(lexer_error_with_context(
            "expected string literal in '_Pragma'",
            source,
            token.line,
            token.column,
        ));
    }
    let spelling = token.preprocessing_spelling.as_str();
    let Some(quote_index) = spelling.find('"') else {
        return Err(lexer_error_with_context(
            "expected string literal in '_Pragma'",
            source,
            token.line,
            token.column,
        ));
    };
    if !matches!(&spelling[..quote_index], "" | "L" | "u" | "U" | "u8")
        || !spelling.ends_with('"')
        || spelling.len() <= quote_index + 1
    {
        return Err(lexer_error_with_context(
            "expected string literal in '_Pragma'",
            source,
            token.line,
            token.column,
        ));
    }
    let inner = &spelling[quote_index + 1..spelling.len() - 1];
    if inner.len() > MAX_PRAGMA_OPERATOR_BYTES {
        return Err(lexer_error_with_bounded_context(
            format!("'_Pragma' string literal exceeds {MAX_PRAGMA_OPERATOR_BYTES} bytes"),
            source,
            token.line,
            token.column,
        ));
    }
    let mut payload = String::with_capacity(inner.len());
    let mut characters = inner.chars().peekable();
    while let Some(character) = characters.next() {
        if character == '\\' && matches!(characters.peek(), Some('"' | '\\')) {
            payload.push(
                characters
                    .next()
                    .expect("peeked pragma string escape must be present"),
            );
        } else {
            payload.push(character);
        }
    }
    Ok(payload)
}

fn execute_pragma_operator_payload(
    payload: &str,
    operator: &LocatedToken,
    state: &mut PreprocessorState,
    source: &str,
) -> CustResult<()> {
    if payload.len()
        > MAX_PRAGMA_OPERATOR_BYTES.saturating_sub(state.macro_expansion_budget.pragma_bytes)
    {
        return Err(lexer_error_with_bounded_context(
            "'_Pragma' payload byte limit exceeded",
            source,
            operator.line,
            operator.column,
        ));
    }
    state.macro_expansion_budget.pragma_bytes += payload.len();
    let payload_chars = SplicedSourceChars::new(payload, operator.line, operator.column);
    let mut payload_tokens = lex_spliced_with_context(
        &payload_chars,
        source,
        operator.line,
        operator.column,
        false,
        true,
        true,
        Some((MAX_PREPROCESSOR_CONDITION_TOKENS, "_Pragma")),
    )
    .map_err(|error| {
        if error
            .message
            .starts_with("'_Pragma' payload token limit exceeded")
        {
            lexer_error_with_bounded_context(
                "'_Pragma' payload token limit exceeded",
                source,
                operator.line,
                operator.column,
            )
        } else {
            lexer_error_with_context(
                "malformed pragma payload in '_Pragma'",
                source,
                operator.line,
                operator.column,
            )
        }
    })?;
    payload_tokens.pop();
    let Some(pragma_name) = payload_tokens
        .first()
        .and_then(|token| preprocessor_identifier_name(&token.kind))
    else {
        return Err(lexer_error_with_context(
            "expected pragma name in '_Pragma' string literal",
            source,
            operator.line,
            operator.column,
        ));
    };
    if pragma_name != "once" {
        return Err(lexer_error_with_context(
            format!("preprocessor pragma '_Pragma({payload:?})' is not supported"),
            source,
            operator.line,
            operator.column,
        ));
    }
    if payload_tokens.len() != 1 {
        return Err(lexer_error_with_context(
            "unexpected tokens after '_Pragma(\"once\")'",
            source,
            operator.line,
            operator.column,
        ));
    }
    let context = state.include_context.as_mut().ok_or_else(|| {
        lexer_error_with_context(
            "preprocessor operator '_Pragma' is not supported",
            source,
            operator.line,
            operator.column,
        )
    })?;
    let source_identity = context
        .stack
        .last()
        .expect("file lexing keeps the current source on the include stack")
        .identity
        .clone();
    context.pragma_once_headers.insert(source_identity);
    Ok(())
}

fn append_expanded_tokens_with_pragmas(
    mut expanded: Vec<LocatedToken>,
    output: &mut Vec<LocatedToken>,
    pending_start: &mut Option<usize>,
    state: &mut PreprocessorState,
    source: &str,
) -> CustResult<()> {
    if expanded.is_empty() {
        return Ok(());
    }
    if pending_start.is_some() {
        output.append(&mut expanded);
    } else if let Some(operator_offset) = expanded
        .iter()
        .position(|token| preprocessor_identifier_name(&token.kind) == Some("_Pragma"))
    {
        let pending = expanded.split_off(operator_offset);
        output.extend(normalize_expanded_integer_tokens(expanded, source, false)?);
        *pending_start = Some(output.len());
        output.extend(pending);
    } else {
        output.extend(normalize_expanded_integer_tokens(expanded, source, false)?);
    }
    execute_pending_pragma_operators(output, pending_start, state, source, false)
}

fn execute_pending_pragma_operators(
    tokens: &mut Vec<LocatedToken>,
    pending_start: &mut Option<usize>,
    state: &mut PreprocessorState,
    source: &str,
    final_input: bool,
) -> CustResult<()> {
    let Some(mut start) = *pending_start else {
        return Ok(());
    };
    let mut pending = VecDeque::from(tokens.split_off(start));
    loop {
        let operator = pending
            .front()
            .expect("pending pragma sequence starts with an operator");
        let Some(opening) = pending.get(1) else {
            if final_input {
                return Err(lexer_error_with_context(
                    "expected '(' after '_Pragma'",
                    source,
                    operator.line,
                    operator.column,
                ));
            }
            tokens.extend(pending);
            *pending_start = Some(start);
            return Ok(());
        };
        if opening.kind != Token::LParen {
            return Err(lexer_error_with_context(
                "expected '(' after '_Pragma'",
                source,
                operator.line,
                operator.column,
            ));
        }
        let Some(literal) = pending.get(2) else {
            if final_input {
                return Err(lexer_error_with_context(
                    "expected string literal in '_Pragma'",
                    source,
                    operator.line,
                    operator.column,
                ));
            }
            tokens.extend(pending);
            *pending_start = Some(start);
            return Ok(());
        };
        let Some(closing) = pending.get(3) else {
            if final_input {
                return Err(lexer_error_with_context(
                    "expected ')' after '_Pragma' string literal",
                    source,
                    operator.line,
                    operator.column,
                ));
            }
            tokens.extend(pending);
            *pending_start = Some(start);
            return Ok(());
        };
        if closing.kind != Token::RParen {
            return Err(lexer_error_with_context(
                "expected ')' after '_Pragma' string literal",
                source,
                closing.line,
                closing.column,
            ));
        }
        let payload = destringize_pragma_operator_literal(literal, source)?;
        let operator = operator.clone();
        execute_pragma_operator_payload(&payload, &operator, state, source)?;
        for _ in 0..4 {
            pending.pop_front();
        }

        let mut ordinary = Vec::new();
        while pending
            .front()
            .is_some_and(|token| preprocessor_identifier_name(&token.kind) != Some("_Pragma"))
        {
            ordinary.push(
                pending
                    .pop_front()
                    .expect("guard requires one ordinary token"),
            );
        }
        tokens.extend(normalize_expanded_integer_tokens(ordinary, source, false)?);
        if pending.is_empty() {
            *pending_start = None;
            return Ok(());
        }
        start = tokens.len();
        *pending_start = Some(start);
    }
}

#[allow(clippy::too_many_arguments)]
fn process_preprocessor_directive(
    source: &str,
    chars: &SplicedSourceChars,
    i: &mut usize,
    current_line: &mut usize,
    column: &mut usize,
    state: &mut PreprocessorState,
    conditional_stack: &mut Vec<ConditionalFrame>,
    output_tokens: &mut Vec<LocatedToken>,
) -> CustResult<bool> {
    let directive_start = *i;
    let directive_marker_len =
        if chars.get(directive_start..directive_start + 2) == Some(&['%', ':']) {
            2
        } else {
            1
        };
    let line = *current_line;
    let directive_column = *column;
    let line_end = preprocessor_directive_line_end(chars, *i);
    let content_end = if line_end > directive_start && chars[line_end - 1] == '\r' {
        line_end - 1
    } else {
        line_end
    };
    let active = conditional_stack.last().is_none_or(|frame| frame.active);
    if !active
        && !inactive_directive_has_name_on_line(
            chars,
            directive_start + directive_marker_len,
            content_end,
        )
    {
        return Ok(false);
    }

    let mut cursor = directive_start + directive_marker_len;
    skip_preprocessor_whitespace(
        source,
        chars,
        &mut cursor,
        content_end,
        line,
        directive_start,
        directive_column,
    )?;
    if cursor == content_end {
        while *i < line_end {
            advance_position(chars, chars[*i], current_line, column, i);
        }
        return Ok(true);
    }
    let directive_name_start = cursor;
    while cursor < content_end && (chars[cursor].is_ascii_alphanumeric() || chars[cursor] == '_') {
        cursor += 1;
    }
    if directive_name_start == cursor
        || !(chars[directive_name_start].is_ascii_alphabetic()
            || chars[directive_name_start] == '_')
    {
        return Err(lexer_error_with_context(
            "expected preprocessor directive name after '#'",
            source,
            line,
            directive_column,
        ));
    }
    let directive_name: String = chars[directive_name_start..cursor].iter().collect();

    match directive_name.as_str() {
        "ifdef" | "ifndef" => {
            if conditional_stack.len() >= MAX_PREPROCESSOR_CONDITIONAL_DEPTH {
                return Err(lexer_error_with_context(
                    "preprocessor conditional nesting limit exceeded",
                    source,
                    line,
                    directive_column,
                ));
            }
            let parent_active = active;
            if !parent_active {
                conditional_stack.push(ConditionalFrame {
                    parent_active: false,
                    active: false,
                    branch_taken: false,
                    else_seen: false,
                    directive_name,
                    line,
                    column: directive_column,
                });
                return Ok(false);
            }
            let has_name_separator = skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if !has_name_separator
                || cursor >= content_end
                || !(chars[cursor].is_ascii_alphabetic() || chars[cursor] == '_')
            {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    format!("expected macro name after '#{directive_name}'"),
                    source,
                    error_line,
                    error_column,
                ));
            }
            let macro_name_start = cursor;
            cursor += 1;
            while cursor < content_end
                && (chars[cursor].is_ascii_alphanumeric() || chars[cursor] == '_')
            {
                cursor += 1;
            }
            let macro_name: String = chars[macro_name_start..cursor].iter().collect();
            if macro_name == "__VA_ARGS__" {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    macro_name_start,
                );
                return Err(lexer_error_with_context(
                    "'__VA_ARGS__' cannot be used as a macro name",
                    source,
                    error_line,
                    error_column,
                ));
            }
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if cursor < content_end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    format!("unexpected tokens after '#{directive_name}' macro name"),
                    source,
                    error_line,
                    error_column,
                ));
            }
            let is_defined = is_macro_defined(&state.macros, &macro_name);
            let condition = if directive_name == "ifndef" {
                !is_defined
            } else {
                is_defined
            };
            conditional_stack.push(ConditionalFrame {
                parent_active,
                active: parent_active && condition,
                branch_taken: parent_active && condition,
                else_seen: false,
                directive_name,
                line,
                column: directive_column,
            });
        }
        "else" => {
            let Some(frame) = conditional_stack.last_mut() else {
                return Err(lexer_error_with_context(
                    "unmatched '#else' conditional directive",
                    source,
                    line,
                    directive_column,
                ));
            };
            if frame.else_seen {
                return Err(lexer_error_with_context(
                    "duplicate '#else' conditional directive",
                    source,
                    line,
                    directive_column,
                ));
            }
            if !frame.parent_active {
                frame.else_seen = true;
                frame.active = false;
                frame.branch_taken = true;
                return Ok(false);
            }
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if cursor < content_end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "unexpected tokens after '#else'",
                    source,
                    error_line,
                    error_column,
                ));
            }
            frame.else_seen = true;
            frame.active = frame.parent_active && !frame.branch_taken;
            frame.branch_taken = true;
        }
        "endif" => {
            if conditional_stack.is_empty() {
                return Err(lexer_error_with_context(
                    "unmatched '#endif' conditional directive",
                    source,
                    line,
                    directive_column,
                ));
            }
            if conditional_stack
                .last()
                .is_some_and(|frame| !frame.parent_active)
            {
                conditional_stack.pop();
                return Ok(false);
            }
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if cursor < content_end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "unexpected tokens after '#endif'",
                    source,
                    error_line,
                    error_column,
                ));
            }
            conditional_stack.pop();
        }
        "if" => {
            if conditional_stack.len() >= MAX_PREPROCESSOR_CONDITIONAL_DEPTH {
                return Err(lexer_error_with_context(
                    "preprocessor conditional nesting limit exceeded",
                    source,
                    line,
                    directive_column,
                ));
            }
            let parent_active = active;
            if !parent_active {
                conditional_stack.push(ConditionalFrame {
                    parent_active: false,
                    active: false,
                    branch_taken: false,
                    else_seen: false,
                    directive_name,
                    line,
                    column: directive_column,
                });
                return Ok(false);
            }
            let predefined_source_name = current_predefined_source_name(state);
            let condition = evaluate_preprocessor_condition(
                source,
                chars,
                cursor,
                content_end,
                line,
                directive_start,
                directive_column,
                &state.macros,
                &mut state.macro_expansion_budget,
                &predefined_source_name,
                state.predefined_line_offset,
                "if",
            )? != 0;
            conditional_stack.push(ConditionalFrame {
                parent_active,
                active: parent_active && condition,
                branch_taken: parent_active && condition,
                else_seen: false,
                directive_name,
                line,
                column: directive_column,
            });
        }
        "elif" => {
            let Some(frame) = conditional_stack.last_mut() else {
                return Err(lexer_error_with_context(
                    "unmatched '#elif' conditional directive",
                    source,
                    line,
                    directive_column,
                ));
            };
            if frame.else_seen {
                return Err(lexer_error_with_context(
                    "'#elif' conditional directive after '#else'",
                    source,
                    line,
                    directive_column,
                ));
            }
            if !frame.parent_active {
                frame.active = false;
                return Ok(false);
            }
            let should_evaluate = !frame.branch_taken;
            let condition = if should_evaluate {
                let predefined_source_name = current_predefined_source_name(state);
                evaluate_preprocessor_condition(
                    source,
                    chars,
                    cursor,
                    content_end,
                    line,
                    directive_start,
                    directive_column,
                    &state.macros,
                    &mut state.macro_expansion_budget,
                    &predefined_source_name,
                    state.predefined_line_offset,
                    "elif",
                )? != 0
            } else {
                false
            };
            frame.active = should_evaluate && condition;
            frame.branch_taken |= frame.active;
        }
        _ if !active => return Ok(false),
        "error" => {
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            let message = normalize_preprocessor_error_message(
                source,
                chars,
                cursor,
                content_end,
                directive_start,
                line,
                directive_column,
            )?;
            let message = if message.is_empty() {
                "#error directive triggered".to_string()
            } else {
                format!("#error: {message}")
            };
            return Err(lexer_error_with_context(
                message,
                source,
                line,
                directive_column,
            ));
        }
        "line" => {
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if cursor >= content_end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "expected decimal line number after '#line'",
                    source,
                    error_line,
                    error_column,
                ));
            }
            let (operand_line, operand_column) =
                preprocessor_position_at(chars, directive_start, line, directive_column, cursor);
            let mut raw_tokens = lex_spliced_with_context(
                &chars.slice(cursor, content_end),
                source,
                operand_line,
                operand_column,
                false,
                true,
                true,
                Some((MAX_PREPROCESSOR_CONDITION_TOKENS, "line")),
            )?;
            raw_tokens.pop();
            let predefined_source_name = current_predefined_source_name(state);
            let expanded = expand_macro_tokens(
                &raw_tokens,
                &state.macros,
                &mut Vec::new(),
                &mut state.macro_expansion_budget,
                source,
                &predefined_source_name,
                state.predefined_line_offset,
                false,
                0,
            )?;
            let tokens = expanded.tokens;
            let Some(line_token) = tokens.first() else {
                return Err(lexer_error_with_context(
                    "expected decimal line number after '#line'",
                    source,
                    operand_line,
                    operand_column,
                ));
            };
            if !line_token
                .preprocessing_spelling
                .chars()
                .all(|character| character.is_ascii_digit())
            {
                return Err(lexer_error_with_context(
                    "expected decimal line number after '#line'",
                    source,
                    line_token.line,
                    line_token.column,
                ));
            }
            let presumed_line = line_token
                .preprocessing_spelling
                .parse::<u64>()
                .ok()
                .filter(|value| (1..=2_147_483_647).contains(value))
                .ok_or_else(|| {
                    lexer_error_with_context(
                        "'#line' line number must be between 1 and 2147483647",
                        source,
                        line_token.line,
                        line_token.column,
                    )
                })? as i64;
            let source_override = match tokens.get(1) {
                None => None,
                Some(token) if token.preprocessing_spelling.starts_with('"') => {
                    let values = match &token.kind {
                        Token::StringLiteral(values) => values.clone(),
                        Token::RawPreprocessor(spelling) => {
                            let mut decoded = lex_with_context(
                                spelling,
                                source,
                                token.line,
                                token.column,
                                false,
                                false,
                                None,
                            )?;
                            decoded.pop();
                            match decoded.as_slice() {
                                [
                                    LocatedToken {
                                        kind: Token::StringLiteral(values),
                                        ..
                                    },
                                ] => values.clone(),
                                _ => {
                                    return Err(lexer_error_with_context(
                                        "expected ordinary string literal after '#line' line number",
                                        source,
                                        token.line,
                                        token.column,
                                    ));
                                }
                            }
                        }
                        _ => {
                            return Err(lexer_error_with_context(
                                "expected ordinary string literal after '#line' line number",
                                source,
                                token.line,
                                token.column,
                            ));
                        }
                    };
                    let characters: String = values
                        .iter()
                        .copied()
                        .take(values.len().saturating_sub(1))
                        .map(|value| char::from_u32(value as u32).unwrap_or('\u{fffd}'))
                        .collect();
                    if characters.len() > MAX_LINE_DIRECTIVE_SOURCE_NAME_BYTES {
                        return Err(lexer_error_with_bounded_context(
                            format!(
                                "'#line' source name exceeds {MAX_LINE_DIRECTIVE_SOURCE_NAME_BYTES} bytes"
                            ),
                            source,
                            token.line,
                            token.column,
                        ));
                    }
                    Some(characters)
                }
                Some(token) => {
                    return Err(lexer_error_with_context(
                        "expected ordinary string literal after '#line' line number",
                        source,
                        token.line,
                        token.column,
                    ));
                }
            };
            if let Some(token) = tokens.get(2) {
                return Err(lexer_error_with_context(
                    "unexpected tokens after '#line' source name",
                    source,
                    token.line,
                    token.column,
                ));
            }
            let directive_end_line = chars.position(line_end).0;
            let next_physical_line = i64::try_from(directive_end_line)
                .ok()
                .and_then(|line| line.checked_add(1))
                .ok_or_else(|| {
                    lexer_error_with_context(
                        "physical line number is out of range",
                        source,
                        line,
                        directive_column,
                    )
                })?;
            state.predefined_line_offset = presumed_line - next_physical_line;
            if let Some(source_override) = source_override {
                state.predefined_source_override = Some(source_override);
            }
        }
        "pragma" => {
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if cursor >= content_end
                || !(chars[cursor].is_ascii_alphabetic() || chars[cursor] == '_')
            {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "expected pragma name after '#pragma'",
                    source,
                    error_line,
                    error_column,
                ));
            }
            let pragma_name_start = cursor;
            while cursor < content_end
                && (chars[cursor].is_ascii_alphanumeric() || chars[cursor] == '_')
            {
                cursor += 1;
            }
            let pragma_name: String = chars[pragma_name_start..cursor].iter().collect();
            if pragma_name != "once" {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    pragma_name_start,
                );
                return Err(lexer_error_with_context(
                    format!("preprocessor pragma '#pragma {pragma_name}' is not supported"),
                    source,
                    error_line,
                    error_column,
                ));
            }
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if cursor < content_end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "unexpected tokens after '#pragma once'",
                    source,
                    error_line,
                    error_column,
                ));
            }
            let context = state.include_context.as_mut().ok_or_else(|| {
                lexer_error_with_context(
                    "preprocessor directive '#pragma' is not supported",
                    source,
                    line,
                    directive_column,
                )
            })?;
            let source_identity = context
                .stack
                .last()
                .expect("file lexing keeps the current source on the include stack")
                .identity
                .clone();
            context.pragma_once_headers.insert(source_identity);
        }
        "include" => {
            if state.include_context.is_none() {
                return Err(lexer_error_with_context(
                    "include directives are not supported",
                    source,
                    line,
                    directive_column,
                ));
            }
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if cursor >= content_end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "expected quoted header name after '#include'",
                    source,
                    error_line,
                    error_column,
                ));
            }
            if chars[cursor] == '<' {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "system header includes are not supported",
                    source,
                    error_line,
                    error_column,
                ));
            }
            let header_name = if chars[cursor] == '"' {
                cursor += 1;
                let header_start = cursor;
                while cursor < content_end && chars[cursor] != '"' {
                    cursor += 1;
                }
                if cursor >= content_end || header_start == cursor {
                    let (error_line, error_column) = preprocessor_position_at(
                        chars,
                        directive_start,
                        line,
                        directive_column,
                        header_start,
                    );
                    return Err(lexer_error_with_context(
                        "expected closing quote after '#include' header name",
                        source,
                        error_line,
                        error_column,
                    ));
                }
                let header_name: String = chars[header_start..cursor].iter().collect();
                cursor += 1;
                header_name
            } else {
                let (operand_line, operand_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                let header_name = expand_quoted_header_operand(
                    &chars.slice(cursor, content_end),
                    source,
                    operand_line,
                    operand_column,
                    state,
                )?;
                cursor = content_end;
                header_name
            };
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if cursor < content_end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "unexpected tokens after '#include' header name",
                    source,
                    error_line,
                    error_column,
                ));
            }
            let included_tokens =
                lex_quoted_header(&header_name, source, line, directive_column, state)?;
            output_tokens.extend(included_tokens);
        }
        "define" => {
            let has_name_separator = skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if !has_name_separator || cursor == content_end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "expected macro name after '#define'",
                    source,
                    error_line,
                    error_column,
                ));
            }
            let macro_name_start = cursor;
            if cursor >= content_end
                || !(chars[cursor].is_ascii_alphabetic() || chars[cursor] == '_')
            {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "expected macro name after '#define'",
                    source,
                    error_line,
                    error_column,
                ));
            }
            cursor += 1;
            while cursor < content_end
                && (chars[cursor].is_ascii_alphanumeric() || chars[cursor] == '_')
            {
                cursor += 1;
            }
            let macro_name: String = chars[macro_name_start..cursor].iter().collect();
            let (macro_line, macro_column) = preprocessor_position_at(
                chars,
                directive_start,
                line,
                directive_column,
                macro_name_start,
            );
            if macro_name == "__VA_ARGS__" {
                return Err(lexer_error_with_context(
                    "'__VA_ARGS__' cannot be used as a macro name",
                    source,
                    macro_line,
                    macro_column,
                ));
            }
            if is_predefined_macro_name(&macro_name) {
                return Err(lexer_error_with_context(
                    format!("predefined macro '{macro_name}' cannot be redefined"),
                    source,
                    macro_line,
                    macro_column,
                ));
            }

            let mut variadic = false;
            let parameters = if cursor < content_end && chars[cursor] == '(' {
                cursor += 1;
                let mut parameters = Vec::new();
                skip_preprocessor_whitespace(
                    source,
                    chars,
                    &mut cursor,
                    content_end,
                    line,
                    directive_start,
                    directive_column,
                )?;
                if cursor < content_end && chars[cursor] == ')' {
                    cursor += 1;
                } else {
                    loop {
                        let parameter_start = cursor;
                        if chars.get(cursor) == Some(&'.') {
                            if chars.get(cursor..cursor + 3) != Some(&['.', '.', '.']) {
                                let (error_line, error_column) = preprocessor_position_at(
                                    chars,
                                    directive_start,
                                    line,
                                    directive_column,
                                    cursor,
                                );
                                return Err(lexer_error_with_context(
                                    "expected '...' for variadic macro parameter",
                                    source,
                                    error_line,
                                    error_column,
                                ));
                            }
                            variadic = true;
                            cursor += 3;
                            skip_preprocessor_whitespace(
                                source,
                                chars,
                                &mut cursor,
                                content_end,
                                line,
                                directive_start,
                                directive_column,
                            )?;
                            if cursor >= content_end || chars[cursor] != ')' {
                                let (error_line, error_column) = preprocessor_position_at(
                                    chars,
                                    directive_start,
                                    line,
                                    directive_column,
                                    cursor,
                                );
                                return Err(lexer_error_with_context(
                                    "variadic macro parameter must end the parameter list",
                                    source,
                                    error_line,
                                    error_column,
                                ));
                            }
                            cursor += 1;
                            break;
                        }
                        if cursor >= content_end
                            || !(chars[cursor].is_ascii_alphabetic() || chars[cursor] == '_')
                        {
                            let (error_line, error_column) = preprocessor_position_at(
                                chars,
                                directive_start,
                                line,
                                directive_column,
                                cursor,
                            );
                            return Err(lexer_error_with_context(
                                "expected parameter name in function-like macro definition",
                                source,
                                error_line,
                                error_column,
                            ));
                        }
                        cursor += 1;
                        while cursor < content_end
                            && (chars[cursor].is_ascii_alphanumeric() || chars[cursor] == '_')
                        {
                            cursor += 1;
                        }
                        let parameter: String = chars[parameter_start..cursor].iter().collect();
                        if parameter == "__VA_ARGS__" {
                            let (error_line, error_column) = preprocessor_position_at(
                                chars,
                                directive_start,
                                line,
                                directive_column,
                                parameter_start,
                            );
                            return Err(lexer_error_with_context(
                                "'__VA_ARGS__' cannot be used as a variadic macro parameter name",
                                source,
                                error_line,
                                error_column,
                            ));
                        }
                        if parameters.contains(&parameter) {
                            let (error_line, error_column) = preprocessor_position_at(
                                chars,
                                directive_start,
                                line,
                                directive_column,
                                parameter_start,
                            );
                            return Err(lexer_error_with_context(
                                format!("duplicate function-like macro parameter '{parameter}'"),
                                source,
                                error_line,
                                error_column,
                            ));
                        }
                        parameters.push(parameter);
                        skip_preprocessor_whitespace(
                            source,
                            chars,
                            &mut cursor,
                            content_end,
                            line,
                            directive_start,
                            directive_column,
                        )?;
                        if cursor < content_end && chars[cursor] == ')' {
                            cursor += 1;
                            break;
                        }
                        if cursor >= content_end || chars[cursor] != ',' {
                            let (error_line, error_column) = preprocessor_position_at(
                                chars,
                                directive_start,
                                line,
                                directive_column,
                                cursor,
                            );
                            return Err(lexer_error_with_context(
                                "expected ',' or ')' after function-like macro parameter",
                                source,
                                error_line,
                                error_column,
                            ));
                        }
                        cursor += 1;
                        skip_preprocessor_whitespace(
                            source,
                            chars,
                            &mut cursor,
                            content_end,
                            line,
                            directive_start,
                            directive_column,
                        )?;
                    }
                }
                skip_preprocessor_whitespace(
                    source,
                    chars,
                    &mut cursor,
                    content_end,
                    line,
                    directive_start,
                    directive_column,
                )?;
                Some(parameters)
            } else {
                let has_replacement_separator = skip_preprocessor_whitespace(
                    source,
                    chars,
                    &mut cursor,
                    content_end,
                    line,
                    directive_start,
                    directive_column,
                )?;
                if cursor < content_end && !has_replacement_separator {
                    let (error_line, error_column) = preprocessor_position_at(
                        chars,
                        directive_start,
                        line,
                        directive_column,
                        cursor,
                    );
                    return Err(lexer_error_with_context(
                        format!("malformed object-like macro definition for '{macro_name}'"),
                        source,
                        error_line,
                        error_column,
                    ));
                }
                None
            };

            let mut replacement_end = content_end;
            while replacement_end > cursor && chars[replacement_end - 1].is_whitespace() {
                replacement_end -= 1;
            }
            let replacement_chars = chars.slice(cursor, replacement_end);
            let (replacement_line, replacement_column) =
                preprocessor_position_at(chars, directive_start, line, directive_column, cursor);
            let replacement = if replacement_chars.is_empty() {
                Vec::new()
            } else {
                let mut replacement_tokens = lex_spliced_with_context(
                    &replacement_chars,
                    source,
                    replacement_line,
                    replacement_column,
                    false,
                    true,
                    true,
                    None,
                )?;
                replacement_tokens.pop();
                let mut replacement_index = 0;
                while replacement_index < replacement_tokens.len() {
                    if macro_hash_pair_is_paste(&replacement_tokens, replacement_index) {
                        let operator = &replacement_tokens[replacement_index];
                        if replacement_index == 0
                            || replacement_index + 2 == replacement_tokens.len()
                        {
                            return Err(lexer_error_with_context(
                                "macro token-pasting operator cannot appear at the edge of a replacement list",
                                source,
                                operator.line,
                                operator.column,
                            ));
                        }
                        if macro_hash_pair_is_paste(&replacement_tokens, replacement_index + 2) {
                            return Err(lexer_error_with_context(
                                "macro token-pasting operator requires an operand on each side",
                                source,
                                operator.line,
                                operator.column,
                            ));
                        }
                        replacement_index += 2;
                        continue;
                    }
                    let token = &replacement_tokens[replacement_index];
                    if token.kind == Token::Hash {
                        let Some(parameters) = parameters.as_ref() else {
                            return Err(lexer_error_with_context(
                                "macro stringification '#' is only supported in function-like macro replacements",
                                source,
                                token.line,
                                token.column,
                            ));
                        };
                        let target = replacement_tokens
                            .get(replacement_index + 1)
                            .and_then(|next| preprocessor_identifier_name(&next.kind));
                        let valid_target = target.is_some_and(|target| {
                            parameters.iter().any(|parameter| parameter == target)
                                || (variadic && target == "__VA_ARGS__")
                        });
                        if !valid_target {
                            return Err(lexer_error_with_context(
                                "macro stringification '#' must be followed by a macro parameter",
                                source,
                                token.line,
                                token.column,
                            ));
                        }
                    }
                    replacement_index += 1;
                }
                if !variadic
                    && let Some(token) = replacement_tokens.iter().find(|token| {
                        preprocessor_identifier_name(&token.kind) == Some("__VA_ARGS__")
                    })
                {
                    return Err(lexer_error_with_context(
                        "'__VA_ARGS__' is only permitted in variadic function-like macro replacements",
                        source,
                        token.line,
                        token.column,
                    ));
                }
                let mut spelling_cursor = 0;
                let mut spelling_line = replacement_line;
                let mut spelling_column = replacement_column;
                let mut previous_end = None;
                let mut replacement = Vec::new();
                let mut token_index = 0;
                while token_index < replacement_tokens.len() {
                    let token = &replacement_tokens[token_index];
                    while spelling_cursor < replacement_chars.len()
                        && (spelling_line, spelling_column) != (token.line, token.column)
                    {
                        advance_position(
                            &replacement_chars,
                            replacement_chars[spelling_cursor],
                            &mut spelling_line,
                            &mut spelling_column,
                            &mut spelling_cursor,
                        );
                    }
                    assert_eq!(
                        (spelling_line, spelling_column),
                        (token.line, token.column),
                        "macro replacement token location must belong to its source"
                    );
                    let separated = previous_end.is_some_and(|end| spelling_cursor > end);
                    if macro_hash_pair_is_paste(&replacement_tokens, token_index) {
                        let spelling = format!(
                            "{}{}",
                            replacement_tokens[token_index].preprocessing_spelling,
                            replacement_tokens[token_index + 1].preprocessing_spelling
                        );
                        replacement.push(MacroReplacementToken::Paste {
                            spelling,
                            separated,
                        });
                        let spelling_len = replacement_tokens[token_index]
                            .preprocessing_spelling
                            .chars()
                            .count()
                            + replacement_tokens[token_index + 1]
                                .preprocessing_spelling
                                .chars()
                                .count();
                        previous_end = Some(spelling_cursor + spelling_len);
                        token_index += 2;
                        continue;
                    }
                    let replacement_token = macro_replacement_token(token.clone(), separated);
                    let spelling_len = match &replacement_token {
                        MacroReplacementToken::Identifier { name, .. } => name.chars().count(),
                        MacroReplacementToken::Other { spelling, .. } => spelling.chars().count(),
                        MacroReplacementToken::Paste { .. } => unreachable!(),
                    };
                    previous_end = Some(spelling_cursor + spelling_len);
                    replacement.push(replacement_token);
                    token_index += 1;
                }
                replacement
            };
            let definition = MacroDefinition {
                parameters,
                variadic,
                replacement,
            };

            if let Some(existing) = state.macros.get(&macro_name) {
                if existing != &definition {
                    let kind = if definition.parameters.is_some() {
                        "function-like"
                    } else {
                        "object-like"
                    };
                    return Err(lexer_error_with_context(
                        format!("conflicting {kind} macro redefinition for '{macro_name}'"),
                        source,
                        macro_line,
                        macro_column,
                    ));
                }
            } else {
                state.macros.insert(macro_name, definition);
            }
        }
        "undef" => {
            let has_name_separator = skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            let macro_name_start = cursor;
            if !has_name_separator
                || cursor >= content_end
                || !(chars[cursor].is_ascii_alphabetic() || chars[cursor] == '_')
            {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "expected macro name after '#undef'",
                    source,
                    error_line,
                    error_column,
                ));
            }
            cursor += 1;
            while cursor < content_end
                && (chars[cursor].is_ascii_alphanumeric() || chars[cursor] == '_')
            {
                cursor += 1;
            }
            let macro_name: String = chars[macro_name_start..cursor].iter().collect();
            if macro_name == "__VA_ARGS__" {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    macro_name_start,
                );
                return Err(lexer_error_with_context(
                    "'__VA_ARGS__' cannot be used as a macro name",
                    source,
                    error_line,
                    error_column,
                ));
            }
            if is_predefined_macro_name(&macro_name) {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    macro_name_start,
                );
                return Err(lexer_error_with_context(
                    format!("predefined macro '{macro_name}' cannot be undefined"),
                    source,
                    error_line,
                    error_column,
                ));
            }
            skip_preprocessor_whitespace(
                source,
                chars,
                &mut cursor,
                content_end,
                line,
                directive_start,
                directive_column,
            )?;
            if cursor < content_end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    cursor,
                );
                return Err(lexer_error_with_context(
                    "unexpected tokens after '#undef' macro name",
                    source,
                    error_line,
                    error_column,
                ));
            }
            state.macros.remove(&macro_name);
        }
        _ => {
            return Err(lexer_error_with_context(
                format!("preprocessor directive '#{directive_name}' is not supported"),
                source,
                line,
                directive_column,
            ));
        }
    }

    while *i < line_end {
        advance_position(chars, chars[*i], current_line, column, i);
    }
    Ok(true)
}

fn open_header_file(path: &Path) -> io::Result<fs::File> {
    let mut options = fs::OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    options.custom_flags(libc::O_NONBLOCK);
    options.open(path)
}

#[cfg(target_os = "linux")]
fn open_header_file_beneath(
    project_root_file: Option<&fs::File>,
    project_root: &Path,
    logical_path: &Path,
) -> io::Result<fs::File> {
    let project_root_file = project_root_file.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::Unsupported,
            "secure quoted header inclusion is not supported on this platform",
        )
    })?;
    let canonical_path = logical_path.canonicalize()?;
    let relative_path = canonical_path
        .strip_prefix(project_root)
        .map_err(|_| io::Error::from_raw_os_error(libc::EXDEV))?;
    let relative_path = CString::new(relative_path.as_os_str().as_bytes()).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "quoted header path contains a NUL byte",
        )
    })?;

    // `open_how` is an integer-only kernel ABI structure, so all-zero is a
    // valid baseline before assigning every field used by openat2.
    let mut how: libc::open_how = unsafe { std::mem::zeroed() };
    how.flags = (libc::O_RDONLY | libc::O_CLOEXEC | libc::O_NONBLOCK) as u64;
    how.resolve = libc::RESOLVE_BENEATH | libc::RESOLVE_NO_MAGICLINKS;
    // SAFETY: the directory fd, NUL-terminated path, initialized `open_how`,
    // and structure size remain valid for the duration of the syscall.
    let fd = unsafe {
        libc::syscall(
            libc::SYS_openat2,
            project_root_file.as_raw_fd(),
            relative_path.as_ptr(),
            &how,
            std::mem::size_of::<libc::open_how>(),
        )
    };
    if fd == -1 {
        return Err(io::Error::last_os_error());
    }
    // SAFETY: a successful openat2 call returns a new owned file descriptor.
    Ok(unsafe { fs::File::from_raw_fd(fd as i32) })
}

#[cfg(not(target_os = "linux"))]
fn open_header_file_beneath(
    _project_root_file: Option<&fs::File>,
    _project_root: &Path,
    _logical_path: &Path,
) -> io::Result<fs::File> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "secure quoted header inclusion is not supported on this platform",
    ))
}

#[cfg(unix)]
fn opened_file_identity(file: &fs::File, logical_path: &Path) -> io::Result<PathBuf> {
    let canonical_path = logical_path.canonicalize()?;
    let opened_metadata = file.metadata()?;
    let current_metadata = fs::metadata(&canonical_path)?;
    if opened_metadata.dev() != current_metadata.dev()
        || opened_metadata.ino() != current_metadata.ino()
    {
        return Err(io::Error::other(
            "quoted header path changed while it was being opened",
        ));
    }
    Ok(canonical_path)
}

#[cfg(not(unix))]
fn opened_file_identity(_file: &fs::File, _logical_path: &Path) -> io::Result<PathBuf> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "secure quoted header inclusion is not supported on this platform",
    ))
}

fn opened_source_identity(
    file: &fs::File,
    _canonical_path: &Path,
) -> io::Result<OpenedSourceIdentity> {
    #[cfg(unix)]
    {
        let metadata = file.metadata()?;
        Ok(OpenedSourceIdentity {
            device: metadata.dev(),
            inode: metadata.ino(),
        })
    }
    #[cfg(not(unix))]
    {
        let _ = file;
        Ok(OpenedSourceIdentity {
            canonical: _canonical_path.to_path_buf(),
        })
    }
}

fn normalize_logical_path(path: &Path) -> PathBuf {
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            Component::Prefix(prefix) => normalized.push(prefix.as_os_str()),
            Component::RootDir => normalized.push(Path::new(std::path::MAIN_SEPARATOR_STR)),
            Component::CurDir => {}
            Component::ParentDir => {
                normalized.pop();
            }
            Component::Normal(part) => normalized.push(part),
        }
    }
    normalized
}

fn logical_source_name(project_root: &Path, logical_path: &Path) -> String {
    logical_path
        .strip_prefix(project_root)
        .unwrap_or(logical_path)
        .components()
        .filter_map(|component| match component {
            Component::Normal(part) => Some(part.to_string_lossy()),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("/")
}

fn current_predefined_source_name(state: &PreprocessorState) -> String {
    if let Some(name) = &state.predefined_source_override {
        return name.clone();
    }
    state
        .include_context
        .as_ref()
        .and_then(|context| {
            context
                .stack
                .last()
                .map(|path| logical_source_name(&context.project_root, &path.logical))
        })
        .unwrap_or_else(|| "<input>".to_string())
}

fn expand_quoted_header_operand(
    operand_chars: &SplicedSourceChars,
    source: &str,
    operand_line: usize,
    operand_column: usize,
    state: &mut PreprocessorState,
) -> CustResult<String> {
    let mut raw_tokens = lex_spliced_with_context(
        operand_chars,
        source,
        operand_line,
        operand_column,
        false,
        true,
        true,
        None,
    )?;
    let eof = raw_tokens
        .pop()
        .expect("include operand lexer always appends an EOF token");
    debug_assert_eq!(eof.kind, Token::Eof);

    let predefined_source_name = current_predefined_source_name(state);
    let expanded = expand_macro_tokens(
        &raw_tokens,
        &state.macros,
        &mut Vec::new(),
        &mut state.macro_expansion_budget,
        source,
        &predefined_source_name,
        state.predefined_line_offset,
        false,
        0,
    )?
    .tokens;
    if expanded
        .first()
        .is_some_and(|token| token.kind == Token::Lt)
        && expanded.last().is_some_and(|token| token.kind == Token::Gt)
    {
        return Err(lexer_error_with_context(
            "system header includes are not supported",
            source,
            operand_line,
            operand_column,
        ));
    }
    if expanded.len() != 1 {
        return Err(lexer_error_with_context(
            "macro-expanded include operand must expand to exactly one ordinary string literal",
            source,
            operand_line,
            operand_column,
        ));
    }

    let token = &expanded[0];
    let ordinary_string = matches!(token.kind, Token::StringLiteral(_))
        || matches!(&token.kind, Token::RawPreprocessor(spelling) if spelling.starts_with('"'));
    let spelling = &token.preprocessing_spelling;
    if !ordinary_string || !spelling.starts_with('"') || !spelling.ends_with('"') {
        return Err(lexer_error_with_context(
            "macro-expanded include operand must expand to exactly one ordinary string literal",
            source,
            operand_line,
            operand_column,
        ));
    }
    let header_name = &spelling[1..spelling.len() - 1];
    if header_name.is_empty() {
        return Err(lexer_error_with_context(
            "macro-expanded include operand must name a non-empty quoted header",
            source,
            operand_line,
            operand_column,
        ));
    }
    Ok(header_name.to_string())
}

fn lex_quoted_header(
    header_name: &str,
    including_source: &str,
    include_line: usize,
    include_column: usize,
    state: &mut PreprocessorState,
) -> CustResult<Vec<LocatedToken>> {
    let header_path = Path::new(header_name);
    if header_path.is_absolute()
        || header_path.components().any(|component| {
            !matches!(
                component,
                Component::Normal(_) | Component::CurDir | Component::ParentDir
            )
        })
    {
        return Err(lexer_error_with_context(
            format!("quoted header path '{header_name}' must stay below the project include root"),
            including_source,
            include_line,
            include_column,
        ));
    }

    let (project_root, current_directory) = {
        let context = state
            .include_context
            .as_ref()
            .expect("file lexing installs an include context");
        (
            context.project_root.clone(),
            context
                .stack
                .last()
                .and_then(|path| path.logical.parent())
                .expect("an included source file has a parent directory")
                .to_path_buf(),
        )
    };
    let mut search_roots = vec![current_directory];
    if search_roots[0] != project_root {
        search_roots.push(project_root.clone());
    }
    let mut selected_header = None;
    for root in search_roots {
        let logical_path = normalize_logical_path(&root.join(header_path));
        if !logical_path.starts_with(&project_root) {
            return Err(lexer_error_with_context(
                format!("quoted header path '{header_name}' escapes the project include root"),
                including_source,
                include_line,
                include_column,
            ));
        }
        #[cfg(target_os = "linux")]
        let project_root_file = state
            .include_context
            .as_ref()
            .map(|context| &context.project_root_file);
        #[cfg(not(target_os = "linux"))]
        let project_root_file = None;
        let file = match open_header_file_beneath(project_root_file, &project_root, &logical_path) {
            Ok(file) => file,
            Err(err) if err.kind() == io::ErrorKind::NotFound => continue,
            #[cfg(target_os = "linux")]
            Err(err) if err.raw_os_error() == Some(libc::EXDEV) => {
                return Err(lexer_error_with_context(
                    format!("quoted header path '{header_name}' escapes the project include root"),
                    including_source,
                    include_line,
                    include_column,
                ));
            }
            Err(err) => {
                return Err(lexer_error_with_context(
                    format!("failed to open quoted header '{header_name}': {err}"),
                    including_source,
                    include_line,
                    include_column,
                ));
            }
        };
        let metadata = file.metadata().map_err(|err| {
            lexer_error_with_context(
                format!("failed to inspect quoted header '{header_name}': {err}"),
                including_source,
                include_line,
                include_column,
            )
        })?;
        if !metadata.is_file() {
            return Err(lexer_error_with_context(
                format!("quoted header '{header_name}' is not a regular file"),
                including_source,
                include_line,
                include_column,
            ));
        }
        let canonical_path = opened_file_identity(&file, &logical_path).map_err(|err| {
            lexer_error_with_context(
                format!("failed to resolve quoted header '{header_name}': {err}"),
                including_source,
                include_line,
                include_column,
            )
        })?;
        if !canonical_path.starts_with(&project_root) {
            return Err(lexer_error_with_context(
                format!("quoted header path '{header_name}' escapes the project include root"),
                including_source,
                include_line,
                include_column,
            ));
        }
        let source_identity = opened_source_identity(&file, &canonical_path).map_err(|err| {
            lexer_error_with_context(
                format!("failed to identify quoted header '{header_name}': {err}"),
                including_source,
                include_line,
                include_column,
            )
        })?;
        selected_header = Some((logical_path, source_identity, file));
        break;
    }
    let Some((logical_path, source_identity, header_file)) = selected_header else {
        return Err(lexer_error_with_context(
            format!("quoted header '{header_name}' was not found below the project include root"),
            including_source,
            include_line,
            include_column,
        ));
    };

    {
        let context = state
            .include_context
            .as_ref()
            .expect("file lexing installs an include context");
        if context.pragma_once_headers.contains(&source_identity) {
            return Ok(Vec::new());
        }
        // Allow one recursive entry so conventional include guards can make the
        // repeated header inactive before rejecting an actually unguarded cycle.
        if context
            .stack
            .iter()
            .filter(|path| path.identity == source_identity)
            .count()
            >= 2
        {
            return Err(lexer_error_with_context(
                format!("quoted header include cycle detected for '{header_name}'"),
                including_source,
                include_line,
                include_column,
            ));
        }
        if context.stack.len().saturating_sub(1) >= MAX_INCLUDE_DEPTH {
            return Err(lexer_error_with_context(
                format!("quoted header include depth limit of {MAX_INCLUDE_DEPTH} exceeded"),
                including_source,
                include_line,
                include_column,
            ));
        }
    }

    let included_source_bytes = state
        .include_context
        .as_ref()
        .expect("file lexing installs an include context")
        .included_source_bytes;
    let remaining_source_bytes = MAX_INCLUDED_SOURCE_BYTES - included_source_bytes;
    let mut header_bytes = Vec::new();
    header_file
        .take(remaining_source_bytes as u64 + 1)
        .read_to_end(&mut header_bytes)
        .map_err(|err| {
            lexer_error_with_context(
                format!("failed to read quoted header '{header_name}': {err}"),
                including_source,
                include_line,
                include_column,
            )
        })?;
    if header_bytes.len() > remaining_source_bytes {
        return Err(lexer_error_with_context(
            format!("included source size limit of {MAX_INCLUDED_SOURCE_BYTES} bytes exceeded"),
            including_source,
            include_line,
            include_column,
        ));
    }
    let next_source_bytes = included_source_bytes + header_bytes.len();
    let source_name = logical_source_name(&project_root, &logical_path);
    let header_source = String::from_utf8(header_bytes).map_err(|_| {
        lexer_error_with_context(
            format!("quoted header '{header_name}' is not valid UTF-8"),
            including_source,
            include_line,
            include_column,
        )
    })?;

    {
        let context = state
            .include_context
            .as_mut()
            .expect("file lexing installs an include context");
        context.included_source_bytes = next_source_bytes;
        context.stack.push(IncludedSourcePath {
            logical: logical_path,
            identity: source_identity,
        });
    }
    let saved_source_override = state.predefined_source_override.take();
    let saved_line_offset = std::mem::replace(&mut state.predefined_line_offset, 0);
    let header_chars = SplicedSourceChars::new(&header_source, 1, 1);
    let result = lex_spliced_with_state(
        &header_chars,
        &header_source,
        1,
        1,
        true,
        false,
        false,
        None,
        state,
    );
    state.predefined_source_override = saved_source_override;
    state.predefined_line_offset = saved_line_offset;
    state
        .include_context
        .as_mut()
        .expect("file lexing installs an include context")
        .stack
        .pop();

    let mut tokens = result
        .map_err(|err| CustError::new(format!("in included header '{source_name}': {err}")))?;
    let eof = tokens
        .pop()
        .expect("included header lexer always appends an EOF token");
    debug_assert_eq!(eof.kind, Token::Eof);
    let source_origin = Rc::new(SourceOrigin { name: source_name });
    for token in &mut tokens {
        if token.source_origin.is_none() {
            token.source_origin = Some(Rc::clone(&source_origin));
        }
    }
    Ok(tokens)
}

#[allow(clippy::too_many_arguments)]
fn evaluate_preprocessor_condition(
    source: &str,
    chars: &SplicedSourceChars,
    mut cursor: usize,
    content_end: usize,
    line: usize,
    directive_start: usize,
    directive_column: usize,
    macros: &HashMap<String, MacroDefinition>,
    macro_expansion_budget: &mut MacroExpansionBudget,
    predefined_source_name: &str,
    predefined_line_offset: i64,
    directive_name: &str,
) -> CustResult<i64> {
    skip_preprocessor_whitespace(
        source,
        chars,
        &mut cursor,
        content_end,
        line,
        directive_start,
        directive_column,
    )?;
    if cursor >= content_end {
        let (error_line, error_column) =
            preprocessor_position_at(chars, directive_start, line, directive_column, cursor);
        return Err(lexer_error_with_context(
            format!("expected expression after '#{directive_name}'"),
            source,
            error_line,
            error_column,
        ));
    }

    let (condition_line, condition_column) =
        preprocessor_position_at(chars, directive_start, line, directive_column, cursor);
    let condition_chars = chars.slice(cursor, content_end);
    let raw_tokens = lex_spliced_with_context(
        &condition_chars,
        source,
        condition_line,
        condition_column,
        false,
        false,
        true,
        Some((MAX_PREPROCESSOR_CONDITION_TOKENS, directive_name)),
    )?;
    let tokens = prepare_preprocessor_condition_tokens(
        source,
        raw_tokens,
        macros,
        macro_expansion_budget,
        predefined_source_name,
        predefined_line_offset,
        directive_name,
    )?;
    PreprocessorConditionParser::new(tokens, source, directive_name).parse()
}

fn prepare_preprocessor_condition_tokens(
    source: &str,
    raw_tokens: Vec<LocatedToken>,
    macros: &HashMap<String, MacroDefinition>,
    macro_expansion_budget: &mut MacroExpansionBudget,
    predefined_source_name: &str,
    predefined_line_offset: i64,
    directive_name: &str,
) -> CustResult<Vec<LocatedToken>> {
    let mut unexpanded = Vec::new();
    let mut cursor = 0;
    while cursor < raw_tokens.len() && raw_tokens[cursor].kind != Token::Eof {
        let token = &raw_tokens[cursor];
        if preprocessor_identifier_name(&token.kind) == Some("defined") {
            let defined_token = token.clone();
            cursor += 1;
            let parenthesized = raw_tokens
                .get(cursor)
                .is_some_and(|token| token.kind == Token::LParen);
            if parenthesized {
                cursor += 1;
            }
            let Some(name_token) = raw_tokens.get(cursor) else {
                return Err(lexer_error_with_context(
                    "expected macro name after 'defined'",
                    source,
                    defined_token.line,
                    defined_token.column,
                ));
            };
            let Some(name) = preprocessor_identifier_name(&name_token.kind) else {
                return Err(lexer_error_with_context(
                    "expected macro name after 'defined'",
                    source,
                    name_token.line,
                    name_token.column,
                ));
            };
            if name == "__VA_ARGS__" {
                return Err(lexer_error_with_context(
                    "'__VA_ARGS__' cannot be used as a macro name",
                    source,
                    name_token.line,
                    name_token.column,
                ));
            }
            cursor += 1;
            if parenthesized {
                let Some(closing) = raw_tokens.get(cursor) else {
                    return Err(lexer_error_with_context(
                        "expected ')' after 'defined' macro name",
                        source,
                        name_token.line,
                        name_token.column,
                    ));
                };
                if closing.kind != Token::RParen {
                    return Err(lexer_error_with_context(
                        "expected ')' after 'defined' macro name",
                        source,
                        closing.line,
                        closing.column,
                    ));
                }
                cursor += 1;
            }
            unexpanded.push(LocatedToken::new(
                Token::Number(i64::from(is_macro_defined(macros, name))),
                defined_token.line,
                defined_token.column,
            ));
            continue;
        }
        unexpanded.push(token.clone());
        cursor += 1;
    }

    let expanded = expand_macro_tokens(
        &unexpanded,
        macros,
        &mut Vec::new(),
        macro_expansion_budget,
        source,
        predefined_source_name,
        predefined_line_offset,
        false,
        0,
    )?;
    let expanded = normalize_expanded_integer_tokens(expanded.tokens, source, true)?;
    let mut prepared = Vec::new();
    for mut token in expanded {
        if preprocessor_identifier_name(&token.kind).is_some() {
            token.kind = Token::Number(0);
        }
        push_preprocessor_condition_token(&mut prepared, token, source, directive_name)?;
    }
    let eof = raw_tokens
        .last()
        .expect("condition lexer always appends an EOF token");
    prepared.push(eof.clone());
    Ok(prepared)
}

fn push_preprocessor_condition_token(
    tokens: &mut Vec<LocatedToken>,
    token: LocatedToken,
    source: &str,
    directive_name: &str,
) -> CustResult<()> {
    if tokens.len() >= MAX_PREPROCESSOR_CONDITION_TOKENS {
        return Err(lexer_error_with_context(
            format!("'#{directive_name}' expression token limit exceeded"),
            source,
            token.line,
            token.column,
        ));
    }
    tokens.push(token);
    Ok(())
}

fn preprocessor_identifier_name(token: &Token) -> Option<&str> {
    match token {
        Token::Ident(name) => Some(name),
        Token::Int => Some("int"),
        Token::Char => Some("char"),
        Token::Bool => Some("_Bool"),
        Token::Float => Some("float"),
        Token::Double => Some("double"),
        Token::Complex => Some("_Complex"),
        Token::Imaginary => Some("_Imaginary"),
        Token::Signed => Some("signed"),
        Token::Unsigned => Some("unsigned"),
        Token::Long => Some("long"),
        Token::Short => Some("short"),
        Token::Const => Some("const"),
        Token::Volatile => Some("volatile"),
        Token::Restrict => Some("restrict"),
        Token::Atomic => Some("_Atomic"),
        Token::Static => Some("static"),
        Token::Extern => Some("extern"),
        Token::ThreadLocal => Some("_Thread_local"),
        Token::Inline => Some("inline"),
        Token::Noreturn => Some("_Noreturn"),
        Token::Auto => Some("auto"),
        Token::Register => Some("register"),
        Token::Void => Some("void"),
        Token::Enum => Some("enum"),
        Token::Struct => Some("struct"),
        Token::Union => Some("union"),
        Token::Typedef => Some("typedef"),
        Token::Sizeof => Some("sizeof"),
        Token::Alignof => Some("_Alignof"),
        Token::Alignas => Some("_Alignas"),
        Token::StaticAssert => Some("_Static_assert"),
        Token::Generic => Some("_Generic"),
        Token::Return => Some("return"),
        Token::If => Some("if"),
        Token::Else => Some("else"),
        Token::While => Some("while"),
        Token::Do => Some("do"),
        Token::For => Some("for"),
        Token::Switch => Some("switch"),
        Token::Case => Some("case"),
        Token::Default => Some("default"),
        Token::Break => Some("break"),
        Token::Continue => Some("continue"),
        Token::Goto => Some("goto"),
        _ => None,
    }
}

struct PreprocessorConditionParser<'a> {
    tokens: Vec<LocatedToken>,
    pos: usize,
    depth: usize,
    source: &'a str,
    directive_name: &'a str,
}

impl<'a> PreprocessorConditionParser<'a> {
    fn new(tokens: Vec<LocatedToken>, source: &'a str, directive_name: &'a str) -> Self {
        Self {
            tokens,
            pos: 0,
            depth: 0,
            source,
            directive_name,
        }
    }

    fn parse(mut self) -> CustResult<i64> {
        let value = self.parse_conditional(true)?;
        if self.peek().kind != Token::Eof {
            return Err(self.error_at(
                self.peek(),
                format!("unexpected token in '#{}' expression", self.directive_name),
            ));
        }
        Ok(i64::from(value.truthy()))
    }

    fn parse_conditional(&mut self, evaluate: bool) -> CustResult<PreprocessorInteger> {
        let condition = self.parse_binary(1, evaluate)?;
        if self.matches(&Token::Question) {
            self.enter_depth()?;
            let then_value = self.parse_conditional(evaluate && condition.truthy())?;
            self.leave_depth();
            if !self.matches(&Token::Colon) {
                return Err(self.error_at(
                    self.peek(),
                    format!(
                        "expected ':' in '#{}' conditional expression",
                        self.directive_name
                    ),
                ));
            }
            self.enter_depth()?;
            let else_value = self.parse_conditional(evaluate && !condition.truthy())?;
            self.leave_depth();
            let unsigned = then_value.unsigned || else_value.unsigned;
            let selected = if evaluate && condition.truthy() {
                then_value
            } else {
                else_value
            };
            return Ok(PreprocessorInteger {
                bits: if evaluate { selected.bits } else { 0 },
                unsigned,
            });
        }
        Ok(condition)
    }

    fn parse_binary(
        &mut self,
        min_precedence: u8,
        evaluate: bool,
    ) -> CustResult<PreprocessorInteger> {
        let mut value = self.parse_unary(evaluate)?;
        loop {
            let Some(precedence) = Self::binary_precedence(&self.peek().kind) else {
                break;
            };
            if precedence < min_precedence {
                break;
            }
            let operator = self.advance();
            let evaluate_rhs = match operator.kind {
                Token::AndAnd => evaluate && value.truthy(),
                Token::OrOr => evaluate && !value.truthy(),
                _ => evaluate,
            };
            let rhs = self.parse_binary(precedence + 1, evaluate_rhs)?;
            value = self.apply_binary(value, &operator, rhs, evaluate)?;
        }
        Ok(value)
    }

    fn parse_unary(&mut self, evaluate: bool) -> CustResult<PreprocessorInteger> {
        if matches!(
            self.peek().kind,
            Token::Plus | Token::Minus | Token::Tilde | Token::Bang
        ) {
            let operator = self.advance();
            self.enter_depth()?;
            let value = self.parse_unary(evaluate)?;
            self.leave_depth();
            if !evaluate {
                return Ok(PreprocessorInteger {
                    bits: 0,
                    unsigned: value.unsigned,
                });
            }
            return Ok(match operator.kind {
                Token::Plus => value,
                Token::Minus => PreprocessorInteger {
                    bits: value.bits.wrapping_neg(),
                    unsigned: value.unsigned,
                },
                Token::Tilde => PreprocessorInteger {
                    bits: !value.bits,
                    unsigned: value.unsigned,
                },
                Token::Bang => PreprocessorInteger::signed(i64::from(!value.truthy())),
                _ => unreachable!("only unary operators are consumed above"),
            });
        }
        self.parse_primary(evaluate)
    }

    fn parse_primary(&mut self, evaluate: bool) -> CustResult<PreprocessorInteger> {
        if self.matches(&Token::LParen) {
            self.enter_depth()?;
            let value = self.parse_conditional(evaluate)?;
            self.leave_depth();
            if !self.matches(&Token::RParen) {
                return Err(self.error_at(
                    self.peek(),
                    format!("expected ')' in '#{}' expression", self.directive_name),
                ));
            }
            return Ok(value);
        }
        let token = self.advance();
        match token.kind {
            Token::Number(value) => Ok(PreprocessorInteger::signed(if evaluate {
                value
            } else {
                0
            })),
            Token::PreprocessorNumber(value) => Ok(PreprocessorInteger {
                bits: if evaluate { value.bits } else { 0 },
                unsigned: value.unsigned,
            }),
            _ => Err(self.error_at(
                &token,
                format!(
                    "expected integer constant in '#{}' expression",
                    self.directive_name
                ),
            )),
        }
    }

    fn apply_binary(
        &self,
        left: PreprocessorInteger,
        operator: &LocatedToken,
        right: PreprocessorInteger,
        evaluate: bool,
    ) -> CustResult<PreprocessorInteger> {
        let common_unsigned = left.unsigned || right.unsigned;
        let result_unsigned = match operator.kind {
            Token::OrOr
            | Token::AndAnd
            | Token::Eq
            | Token::Ne
            | Token::Lt
            | Token::Le
            | Token::Gt
            | Token::Ge => false,
            Token::ShiftLeft | Token::ShiftRight => left.unsigned,
            _ => common_unsigned,
        };
        if !evaluate {
            return Ok(PreprocessorInteger {
                bits: 0,
                unsigned: result_unsigned,
            });
        }

        let boolean = |value| PreprocessorInteger::signed(i64::from(value));
        let bits = match operator.kind {
            Token::OrOr => return Ok(boolean(left.truthy() || right.truthy())),
            Token::AndAnd => return Ok(boolean(left.truthy() && right.truthy())),
            Token::Pipe => left.bits | right.bits,
            Token::Caret => left.bits ^ right.bits,
            Token::Amp => left.bits & right.bits,
            Token::Eq => return Ok(boolean(left.bits == right.bits)),
            Token::Ne => return Ok(boolean(left.bits != right.bits)),
            Token::Lt | Token::Le | Token::Gt | Token::Ge => {
                let ordering = if common_unsigned {
                    left.bits.cmp(&right.bits)
                } else {
                    (left.bits as i64).cmp(&(right.bits as i64))
                };
                let result = match operator.kind {
                    Token::Lt => ordering.is_lt(),
                    Token::Le => ordering.is_le(),
                    Token::Gt => ordering.is_gt(),
                    Token::Ge => ordering.is_ge(),
                    _ => unreachable!("only relational operators are matched above"),
                };
                return Ok(boolean(result));
            }
            Token::ShiftLeft | Token::ShiftRight => {
                if right.bits >= u64::from(i64::BITS) {
                    return Err(self.error_at(operator, "preprocessor shift count is out of range"));
                }
                let shift = right.bits as u32;
                if operator.kind == Token::ShiftLeft {
                    left.bits.wrapping_shl(shift)
                } else if left.unsigned {
                    left.bits.wrapping_shr(shift)
                } else {
                    (left.bits as i64).wrapping_shr(shift) as u64
                }
            }
            Token::Plus => left.bits.wrapping_add(right.bits),
            Token::Minus => left.bits.wrapping_sub(right.bits),
            Token::Star => left.bits.wrapping_mul(right.bits),
            Token::Slash | Token::Percent => {
                if right.bits == 0 {
                    return Err(
                        self.error_at(operator, "division by zero in preprocessor expression")
                    );
                }
                if common_unsigned {
                    if operator.kind == Token::Slash {
                        left.bits / right.bits
                    } else {
                        left.bits % right.bits
                    }
                } else if operator.kind == Token::Slash {
                    (left.bits as i64).wrapping_div(right.bits as i64) as u64
                } else {
                    (left.bits as i64).wrapping_rem(right.bits as i64) as u64
                }
            }
            _ => unreachable!("only binary operators are passed to apply_binary"),
        };
        Ok(PreprocessorInteger {
            bits,
            unsigned: result_unsigned,
        })
    }

    fn binary_precedence(token: &Token) -> Option<u8> {
        match token {
            Token::OrOr => Some(1),
            Token::AndAnd => Some(2),
            Token::Pipe => Some(3),
            Token::Caret => Some(4),
            Token::Amp => Some(5),
            Token::Eq | Token::Ne => Some(6),
            Token::Lt | Token::Le | Token::Gt | Token::Ge => Some(7),
            Token::ShiftLeft | Token::ShiftRight => Some(8),
            Token::Plus | Token::Minus => Some(9),
            Token::Star | Token::Slash | Token::Percent => Some(10),
            _ => None,
        }
    }

    fn enter_depth(&mut self) -> CustResult<()> {
        if self.depth >= MAX_PREPROCESSOR_CONDITION_DEPTH {
            return Err(self.error_at(
                self.peek(),
                format!(
                    "'#{}' expression nesting limit exceeded",
                    self.directive_name
                ),
            ));
        }
        self.depth += 1;
        Ok(())
    }

    fn leave_depth(&mut self) {
        self.depth -= 1;
    }

    fn matches(&mut self, expected: &Token) -> bool {
        if self.peek().kind == *expected {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn advance(&mut self) -> LocatedToken {
        let token = self.peek().clone();
        if token.kind != Token::Eof {
            self.pos += 1;
        }
        token
    }

    fn peek(&self) -> &LocatedToken {
        self.tokens
            .get(self.pos)
            .expect("condition lexer always appends an EOF token")
    }

    fn error_at(&self, token: &LocatedToken, message: impl Into<String>) -> CustError {
        lexer_error_with_context(message, self.source, token.line, token.column)
    }
}

fn preprocessor_directive_line_end(chars: &[char], mut cursor: usize) -> usize {
    while cursor < chars.len() {
        match chars[cursor] {
            '\n' => return cursor,
            quote @ ('\'' | '"') => {
                cursor += 1;
                while cursor < chars.len() && chars[cursor] != '\n' {
                    if chars[cursor] == '\\' && cursor + 1 < chars.len() {
                        cursor += 2;
                    } else {
                        let closes_literal = chars[cursor] == quote;
                        cursor += 1;
                        if closes_literal {
                            break;
                        }
                    }
                }
            }
            '/' if chars.get(cursor + 1) == Some(&'/') => {
                while cursor < chars.len() && chars[cursor] != '\n' {
                    cursor += 1;
                }
            }
            '/' if chars.get(cursor + 1) == Some(&'*') => {
                cursor += 2;
                while cursor + 1 < chars.len()
                    && !(chars[cursor] == '*' && chars[cursor + 1] == '/')
                {
                    cursor += 1;
                }
                cursor = (cursor + 2).min(chars.len());
            }
            _ => cursor += 1,
        }
    }
    chars.len()
}

fn macro_invocation_range(chars: &[char], mut cursor: usize) -> Option<(usize, usize)> {
    loop {
        while cursor < chars.len() && chars[cursor].is_whitespace() {
            cursor += 1;
        }
        if chars.get(cursor) == Some(&'/') && chars.get(cursor + 1) == Some(&'/') {
            cursor += 2;
            while cursor < chars.len() && chars[cursor] != '\n' {
                cursor += 1;
            }
            continue;
        }
        if chars.get(cursor) != Some(&'/') || chars.get(cursor + 1) != Some(&'*') {
            break;
        }
        cursor += 2;
        while cursor + 1 < chars.len() && !(chars[cursor] == '*' && chars[cursor + 1] == '/') {
            cursor += 1;
        }
        if cursor + 1 >= chars.len() {
            return None;
        }
        cursor += 2;
    }

    if chars.get(cursor) != Some(&'(') {
        return None;
    }
    let start = cursor;
    let mut depth = 0;
    while cursor < chars.len() {
        match chars[cursor] {
            quote @ ('\'' | '"') => {
                cursor += 1;
                while cursor < chars.len() {
                    if chars[cursor] == '\\' {
                        cursor = (cursor + 2).min(chars.len());
                    } else {
                        let closes_literal = chars[cursor] == quote;
                        cursor += 1;
                        if closes_literal {
                            break;
                        }
                    }
                }
            }
            '/' if chars.get(cursor + 1) == Some(&'/') => {
                cursor += 2;
                while cursor < chars.len() && chars[cursor] != '\n' {
                    cursor += 1;
                }
            }
            '/' if chars.get(cursor + 1) == Some(&'*') => {
                cursor += 2;
                while cursor + 1 < chars.len()
                    && !(chars[cursor] == '*' && chars[cursor + 1] == '/')
                {
                    cursor += 1;
                }
                cursor = (cursor + 2).min(chars.len());
            }
            '(' => {
                depth += 1;
                cursor += 1;
            }
            ')' => {
                depth -= 1;
                cursor += 1;
                if depth == 0 {
                    return Some((start, cursor));
                }
            }
            _ => cursor += 1,
        }
    }
    Some((start, cursor))
}

fn preprocessor_position_at(
    chars: &SplicedSourceChars,
    mut cursor: usize,
    mut line: usize,
    mut column: usize,
    target: usize,
) -> (usize, usize) {
    while cursor < target {
        advance_position(chars, chars[cursor], &mut line, &mut column, &mut cursor);
    }
    (line, column)
}

#[allow(clippy::too_many_arguments)]
fn normalize_preprocessor_error_message(
    source: &str,
    chars: &SplicedSourceChars,
    mut cursor: usize,
    end: usize,
    directive_start: usize,
    line: usize,
    directive_column: usize,
) -> CustResult<String> {
    let mut message = String::new();
    let mut separated = false;
    let push_message_char = |message: &mut String, character: char| -> CustResult<()> {
        if character.len_utf8() > MAX_PREPROCESSOR_ERROR_MESSAGE_BYTES.saturating_sub(message.len())
        {
            return Err(lexer_error_with_bounded_context(
                "preprocessor #error message byte limit exceeded",
                source,
                line,
                directive_column,
            ));
        }
        message.push(character);
        Ok(())
    };
    while cursor < end {
        if chars[cursor].is_whitespace() {
            separated = !message.is_empty();
            cursor += 1;
            continue;
        }
        if chars[cursor] == '/' && chars.get(cursor + 1) == Some(&'/') {
            break;
        }
        if chars[cursor] == '/' && chars.get(cursor + 1) == Some(&'*') {
            let comment_start = cursor;
            cursor += 2;
            while cursor + 1 < end && !(chars[cursor] == '*' && chars[cursor + 1] == '/') {
                cursor += 1;
            }
            if cursor + 1 >= end {
                let (error_line, error_column) = preprocessor_position_at(
                    chars,
                    directive_start,
                    line,
                    directive_column,
                    comment_start,
                );
                return Err(lexer_error_with_context(
                    "unterminated block comment",
                    source,
                    error_line,
                    error_column,
                ));
            }
            cursor += 2;
            separated = !message.is_empty();
            continue;
        }
        if separated {
            push_message_char(&mut message, ' ')?;
            separated = false;
        }
        let current = chars[cursor];
        push_message_char(&mut message, current)?;
        cursor += 1;
        if matches!(current, '\'' | '"') {
            while cursor < end {
                let literal_char = chars[cursor];
                push_message_char(&mut message, literal_char)?;
                cursor += 1;
                if literal_char == '\\' && cursor < end {
                    push_message_char(&mut message, chars[cursor])?;
                    cursor += 1;
                } else if literal_char == current {
                    break;
                }
            }
        }
    }
    Ok(message)
}

fn inactive_directive_has_name_on_line(chars: &[char], mut cursor: usize, end: usize) -> bool {
    loop {
        while cursor < end && matches!(chars[cursor], ' ' | '\t' | '\u{b}' | '\u{c}' | '\r') {
            cursor += 1;
        }
        if cursor + 1 >= end || chars[cursor] != '/' {
            break;
        }
        if chars[cursor + 1] == '/' {
            return false;
        }
        if chars[cursor + 1] != '*' {
            break;
        }
        cursor += 2;
        while cursor + 1 < end && !(chars[cursor] == '*' && chars[cursor + 1] == '/') {
            cursor += 1;
        }
        if cursor + 1 >= end {
            return false;
        }
        cursor += 2;
    }
    cursor < end && (chars[cursor].is_ascii_alphabetic() || chars[cursor] == '_')
}

fn skip_preprocessor_whitespace(
    source: &str,
    chars: &SplicedSourceChars,
    cursor: &mut usize,
    end: usize,
    line: usize,
    directive_start: usize,
    directive_column: usize,
) -> CustResult<bool> {
    let start = *cursor;
    loop {
        while *cursor < end && matches!(chars[*cursor], ' ' | '\t' | '\u{b}' | '\u{c}' | '\r') {
            *cursor += 1;
        }
        if *cursor + 1 < end && chars[*cursor] == '/' && chars[*cursor + 1] == '/' {
            *cursor = end;
            break;
        }
        if *cursor + 1 >= end || chars[*cursor] != '/' || chars[*cursor + 1] != '*' {
            break;
        }

        let comment_start = *cursor;
        *cursor += 2;
        while *cursor + 1 < end && !(chars[*cursor] == '*' && chars[*cursor + 1] == '/') {
            *cursor += 1;
        }
        if *cursor + 1 >= end {
            let (error_line, error_column) = preprocessor_position_at(
                chars,
                directive_start,
                line,
                directive_column,
                comment_start,
            );
            return Err(lexer_error_with_context(
                "unterminated block comment",
                source,
                error_line,
                error_column,
            ));
        }
        *cursor += 2;
    }
    Ok(*cursor != start)
}

fn skip_inactive_text_line(
    source: &str,
    chars: &SplicedSourceChars,
    i: &mut usize,
    line: &mut usize,
    column: &mut usize,
    line_has_preprocessing_token: &mut bool,
) -> CustResult<()> {
    *line_has_preprocessing_token = true;
    while *i < chars.len() && chars[*i] != '\n' {
        match chars[*i] {
            quote @ ('\'' | '"') => {
                advance_position(chars, quote, line, column, i);
                while *i < chars.len() && chars[*i] != '\n' {
                    let current = chars[*i];
                    advance_position(chars, current, line, column, i);
                    if current == '\\' && *i < chars.len() && chars[*i] != '\n' {
                        advance_position(chars, chars[*i], line, column, i);
                    } else if current == quote {
                        break;
                    }
                }
            }
            '/' if chars.get(*i + 1) == Some(&'/') => {
                while *i < chars.len() && chars[*i] != '\n' {
                    advance_position(chars, chars[*i], line, column, i);
                }
            }
            '/' if chars.get(*i + 1) == Some(&'*') => {
                let start_line = *line;
                let start_column = *column;
                advance_position(chars, '/', line, column, i);
                advance_position(chars, '*', line, column, i);
                let mut closed = false;
                while *i < chars.len() {
                    if chars[*i] == '*' && chars.get(*i + 1) == Some(&'/') {
                        advance_position(chars, '*', line, column, i);
                        advance_position(chars, '/', line, column, i);
                        closed = true;
                        break;
                    }
                    advance_position(chars, chars[*i], line, column, i);
                }
                if !closed {
                    return Err(lexer_error_with_context(
                        "unterminated block comment",
                        source,
                        start_line,
                        start_column,
                    ));
                }
                if *line != start_line {
                    return Ok(());
                }
            }
            current => advance_position(chars, current, line, column, i),
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn expand_macro_tokens(
    tokens: &[LocatedToken],
    macros: &HashMap<String, MacroDefinition>,
    expansion_stack: &mut Vec<String>,
    budget: &mut MacroExpansionBudget,
    source: &str,
    predefined_source_name: &str,
    predefined_line_offset: i64,
    count_plain_tokens: bool,
    depth: usize,
) -> CustResult<MacroExpansion> {
    let mut result = Vec::new();
    let mut cursor = 0;
    let mut pending_separation = false;
    while cursor < tokens.len() {
        let token = &tokens[cursor];
        let Some(name) = preprocessor_identifier_name(&token.kind) else {
            let mut token = token.clone();
            if pending_separation {
                token.separated = true;
                pending_separation = false;
            }
            if count_plain_tokens {
                push_expanded_macro_token(
                    &mut result,
                    token.clone(),
                    budget,
                    source,
                    token.line,
                    token.column,
                )?;
            } else {
                result.push(token);
            }
            cursor += 1;
            continue;
        };
        if name == "__VA_ARGS__" {
            return Err(lexer_error_with_context(
                "'__VA_ARGS__' is only permitted in variadic function-like macro replacements",
                source,
                token.line,
                token.column,
            ));
        }
        if is_predefined_macro_name(name) {
            let mut expanded = expand_predefined_macro(
                name,
                token,
                budget,
                source,
                predefined_source_name,
                predefined_line_offset,
                depth,
            )?;
            expanded.separated |= token.separated || pending_separation;
            pending_separation = false;
            result.push(expanded);
            cursor += 1;
            continue;
        }
        let Some(definition) = macros.get(name) else {
            let mut token = token.clone();
            if pending_separation {
                token.separated = true;
                pending_separation = false;
            }
            if count_plain_tokens {
                push_expanded_macro_token(
                    &mut result,
                    token.clone(),
                    budget,
                    source,
                    token.line,
                    token.column,
                )?;
            } else {
                result.push(token);
            }
            cursor += 1;
            continue;
        };

        let (arguments, next_cursor) = if definition.parameters.is_some()
            && tokens
                .get(cursor + 1)
                .is_some_and(|next| next.kind == Token::LParen)
        {
            let (arguments, next_cursor) = parse_macro_arguments(
                tokens,
                cursor + 1,
                name,
                definition.variadic.then_some(
                    definition
                        .parameters
                        .as_ref()
                        .expect("function-like macro requires parameters")
                        .len(),
                ),
                source,
                token.line,
                token.column,
            )?;
            (Some(arguments), next_cursor)
        } else if definition.parameters.is_some() {
            let mut token = token.clone();
            if pending_separation {
                token.separated = true;
                pending_separation = false;
            }
            if count_plain_tokens {
                push_expanded_macro_token(
                    &mut result,
                    token.clone(),
                    budget,
                    source,
                    token.line,
                    token.column,
                )?;
            } else {
                result.push(token);
            }
            cursor += 1;
            continue;
        } else {
            (None, cursor + 1)
        };

        let expanded = expand_macro(
            name,
            arguments,
            macros,
            expansion_stack,
            budget,
            source,
            predefined_source_name,
            predefined_line_offset,
            token.line,
            token.column,
            depth,
        )?;
        let mut trailing_separation = expanded.trailing_separation;
        let mut expanded = expanded.tokens;
        if let Some(first) = expanded.first_mut() {
            first.separated |= token.separated || pending_separation;
            pending_separation = false;
        }
        cursor = next_cursor;

        while tokens
            .get(cursor)
            .is_some_and(|next| next.kind == Token::LParen)
        {
            let Some(last) = expanded.last() else {
                break;
            };
            let Some(nested_name) = preprocessor_identifier_name(&last.kind) else {
                break;
            };
            if nested_name == name {
                break;
            }
            if macros
                .get(nested_name)
                .is_none_or(|nested| nested.parameters.is_none())
            {
                break;
            }
            let nested_name = nested_name.to_string();
            let nested_line = last.line;
            let nested_column = last.column;
            let nested_separated = last.separated;
            let (nested_arguments, next_cursor) = parse_macro_arguments(
                tokens,
                cursor,
                &nested_name,
                macros
                    .get(&nested_name)
                    .filter(|definition| definition.variadic)
                    .and_then(|definition| definition.parameters.as_ref().map(Vec::len)),
                source,
                nested_line,
                nested_column,
            )?;
            expanded.pop();
            let nested_expansion = expand_macro(
                &nested_name,
                Some(nested_arguments),
                macros,
                expansion_stack,
                budget,
                source,
                predefined_source_name,
                predefined_line_offset,
                nested_line,
                nested_column,
                depth + 1,
            )?;
            trailing_separation = nested_expansion.trailing_separation;
            let mut nested_expansion = nested_expansion.tokens;
            if let Some(first) = nested_expansion.first_mut() {
                first.separated |= nested_separated;
            } else {
                trailing_separation |= nested_separated;
            }
            expanded.extend(nested_expansion);
            cursor = next_cursor;
        }
        if expanded.is_empty() {
            pending_separation |= token.separated || trailing_separation;
        } else {
            result.extend(expanded);
            pending_separation |= trailing_separation;
        }
    }
    Ok(MacroExpansion {
        tokens: result,
        trailing_separation: pending_separation,
    })
}

fn ensure_macro_replacement_token_capacity(
    current_len: usize,
    additional_len: usize,
    source: &str,
    line: usize,
    column: usize,
) -> CustResult<()> {
    if additional_len > MAX_OBJECT_MACRO_EXPANSION_TOKENS.saturating_sub(current_len) {
        return Err(lexer_error_with_context(
            "macro expansion token limit exceeded",
            source,
            line,
            column,
        ));
    }
    Ok(())
}

fn stringify_macro_argument(
    argument: &[LocatedToken],
    budget: &mut MacroExpansionBudget,
    source: &str,
    line: usize,
    column: usize,
    separated: bool,
) -> CustResult<LocatedToken> {
    let mut required_bytes = 2usize;
    for (index, token) in argument.iter().enumerate() {
        if index > 0 && token.separated {
            required_bytes = required_bytes.saturating_add(1);
        }
        for character in token.preprocessing_spelling.chars() {
            required_bytes = required_bytes
                .saturating_add(character.len_utf8())
                .saturating_add(usize::from(matches!(character, '\\' | '"')));
        }
    }
    if required_bytes > MAX_MACRO_STRINGIFICATION_BYTES.saturating_sub(budget.stringified_bytes) {
        return Err(lexer_error_with_context(
            "macro stringification byte limit exceeded",
            source,
            line,
            column,
        ));
    }
    budget.stringified_bytes += required_bytes;

    let mut value = String::new();
    let mut spelling = String::from("\"");
    for (index, token) in argument.iter().enumerate() {
        if index > 0 && token.separated {
            value.push(' ');
            spelling.push(' ');
        }
        for character in token.preprocessing_spelling.chars() {
            value.push(character);
            if matches!(character, '\\' | '"') {
                spelling.push('\\');
            }
            spelling.push(character);
        }
    }
    spelling.push('"');
    let mut values = value
        .chars()
        .map(|character| character as i64)
        .collect::<Vec<_>>();
    values.push(0);
    Ok(
        LocatedToken::new(Token::StringLiteral(values), line, column)
            .with_preprocessing_spelling(spelling, separated),
    )
}

fn pasted_punctuator_token(spelling: &str) -> Option<Token> {
    match spelling {
        "<:" => Some(Token::LBracket),
        ":>" => Some(Token::RBracket),
        "<%" => Some(Token::LBrace),
        "%>" => Some(Token::RBrace),
        "%:" => Some(Token::Hash),
        "##" | "%:%:" => Some(Token::RawPreprocessor(spelling.to_string())),
        _ => None,
    }
}

fn paste_macro_tokens(
    left: LocatedToken,
    right: LocatedToken,
    budget: &mut MacroExpansionBudget,
    source: &str,
    line: usize,
    column: usize,
) -> CustResult<LocatedToken> {
    let required_bytes = left
        .preprocessing_spelling
        .len()
        .saturating_add(right.preprocessing_spelling.len());
    if required_bytes > MAX_MACRO_TOKEN_PASTING_BYTES.saturating_sub(budget.pasted_bytes) {
        return Err(lexer_error_with_context(
            "macro token-pasting byte limit exceeded",
            source,
            line,
            column,
        ));
    }
    budget.pasted_bytes += required_bytes;
    let spelling = format!(
        "{}{}",
        left.preprocessing_spelling, right.preprocessing_spelling
    );
    if let Some(kind) = pasted_punctuator_token(&spelling) {
        return Ok(LocatedToken::new(kind, line, column)
            .with_preprocessing_spelling(spelling, left.separated));
    }
    let pasted_source = SplicedSourceChars::new(&spelling, line, column);
    let pasted = lex_spliced_with_context(
        &pasted_source,
        source,
        line,
        column,
        false,
        true,
        true,
        None,
    );
    let Ok(mut pasted) = pasted else {
        return Err(lexer_error_with_context(
            format!("token pasting produced invalid preprocessing token '{spelling}'"),
            source,
            line,
            column,
        ));
    };
    pasted.pop();
    if pasted.len() != 1 {
        return Err(lexer_error_with_context(
            format!("token pasting produced invalid preprocessing token '{spelling}'"),
            source,
            line,
            column,
        ));
    }
    let mut pasted = pasted.pop().expect("one pasted token must be present");
    pasted.preprocessing_spelling = spelling;
    pasted.separated = left.separated;
    Ok(pasted)
}

fn apply_macro_token_pastes(
    items: Vec<MacroSubstitutionItem>,
    budget: &mut MacroExpansionBudget,
    source: &str,
    line: usize,
    column: usize,
) -> CustResult<(Vec<LocatedToken>, bool)> {
    let mut combined = Vec::new();
    let mut items = items.into_iter();
    while let Some(item) = items.next() {
        if !matches!(item, MacroSubstitutionItem::Paste) {
            combined.push(item);
            continue;
        }
        let left = combined
            .pop()
            .expect("validated token-pasting operator requires a left operand");
        let right = items
            .next()
            .expect("validated token-pasting operator requires a right operand");
        let pasted = match (left, right) {
            (MacroSubstitutionItem::Token(left), MacroSubstitutionItem::Token(right)) => {
                MacroSubstitutionItem::Token(paste_macro_tokens(
                    left, right, budget, source, line, column,
                )?)
            }
            (MacroSubstitutionItem::Token(token), MacroSubstitutionItem::Placemark { .. }) => {
                MacroSubstitutionItem::Token(token)
            }
            (
                MacroSubstitutionItem::Placemark { separated },
                MacroSubstitutionItem::Token(mut token),
            ) => {
                token.separated = separated;
                MacroSubstitutionItem::Token(token)
            }
            (
                MacroSubstitutionItem::Placemark { separated },
                MacroSubstitutionItem::Placemark { .. },
            ) => MacroSubstitutionItem::Placemark { separated },
            (MacroSubstitutionItem::Paste, _) | (_, MacroSubstitutionItem::Paste) => {
                return Err(lexer_error_with_context(
                    "macro token-pasting operator requires an operand on each side",
                    source,
                    line,
                    column,
                ));
            }
        };
        combined.push(pasted);
    }

    let mut tokens = Vec::new();
    let mut pending_separation = false;
    for item in combined {
        match item {
            MacroSubstitutionItem::Token(mut token) => {
                token.separated |= std::mem::take(&mut pending_separation);
                tokens.push(token);
            }
            MacroSubstitutionItem::Placemark { separated } => {
                pending_separation |= separated;
            }
            MacroSubstitutionItem::Paste => unreachable!(),
        }
    }
    Ok((tokens, pending_separation))
}

#[allow(clippy::too_many_arguments)]
fn expand_macro(
    name: &str,
    arguments: Option<Vec<Vec<LocatedToken>>>,
    macros: &HashMap<String, MacroDefinition>,
    expansion_stack: &mut Vec<String>,
    budget: &mut MacroExpansionBudget,
    source: &str,
    predefined_source_name: &str,
    predefined_line_offset: i64,
    line: usize,
    column: usize,
    depth: usize,
) -> CustResult<MacroExpansion> {
    let definition = macros
        .get(name)
        .expect("macro expansion requires a registered definition")
        .clone();
    if expansion_stack.iter().any(|expanded| expanded == name) {
        let kind = if definition.parameters.is_some() {
            "function-like"
        } else {
            "object-like"
        };
        return Err(lexer_error_with_context(
            format!("recursive {kind} macro expansion for '{name}'"),
            source,
            line,
            column,
        ));
    }
    if depth >= MAX_OBJECT_MACRO_EXPANSION_DEPTH {
        let kind = if definition.parameters.is_some() {
            "function-like"
        } else {
            "object-like"
        };
        return Err(lexer_error_with_context(
            format!("{kind} macro expansion depth limit exceeded"),
            source,
            line,
            column,
        ));
    }
    if budget.work >= MAX_OBJECT_MACRO_EXPANSION_WORK {
        return Err(lexer_error_with_context(
            "macro expansion work limit exceeded",
            source,
            line,
            column,
        ));
    }
    budget.work += 1;

    let mut raw_arguments = Vec::new();
    let mut expanded_arguments = Vec::new();
    if let Some(parameters) = &definition.parameters {
        let mut arguments = arguments.expect("function-like macro expansion requires arguments");
        if !parameters.is_empty() && arguments.is_empty() {
            arguments.push(Vec::new());
        }
        let expected_arguments = parameters.len() + usize::from(definition.variadic);
        if arguments.len() != expected_arguments {
            let expectation = if definition.variadic {
                format!("at least {}", parameters.len() + 1)
            } else {
                parameters.len().to_string()
            };
            return Err(lexer_error_with_context(
                format!(
                    "function-like macro '{name}' expects {expectation} arguments but got {}",
                    arguments.len()
                ),
                source,
                line,
                column,
            ));
        }
        if let Some(token) = arguments
            .iter()
            .flatten()
            .find(|token| preprocessor_identifier_name(&token.kind) == Some("__VA_ARGS__"))
        {
            return Err(lexer_error_with_context(
                "'__VA_ARGS__' is only permitted in variadic function-like macro replacements",
                source,
                token.line,
                token.column,
            ));
        }
        for (index, argument) in arguments.into_iter().enumerate() {
            let parameter_name = parameters.get(index).map(String::as_str).or_else(|| {
                (definition.variadic && index == parameters.len()).then_some("__VA_ARGS__")
            });
            let is_substituted = parameter_name.is_some_and(|parameter_name| {
                definition
                    .replacement
                    .iter()
                    .enumerate()
                    .any(|(index, token)| {
                        matches!(
                            token,
                            MacroReplacementToken::Identifier { name, .. }
                                if name == parameter_name
                        ) && !index.checked_sub(1).is_some_and(|previous_index| {
                            matches!(
                                definition.replacement.get(previous_index),
                                Some(
                                    MacroReplacementToken::Other {
                                        kind: Token::Hash,
                                        ..
                                    } | MacroReplacementToken::Paste { .. }
                                )
                            )
                        }) && !matches!(
                            definition.replacement.get(index + 1),
                            Some(MacroReplacementToken::Paste { .. })
                        )
                    })
            });
            let expanded = if is_substituted {
                let mut prescan_argument = argument.clone();
                if let Some(first) = prescan_argument.first_mut() {
                    first.separated = false;
                }
                Some(expand_macro_tokens(
                    &prescan_argument,
                    macros,
                    expansion_stack,
                    budget,
                    source,
                    predefined_source_name,
                    predefined_line_offset,
                    false,
                    depth + 1,
                )?)
            } else {
                None
            };
            raw_arguments.push(argument);
            expanded_arguments.push(expanded);
        }
    }

    expansion_stack.push(name.to_string());
    let mut replacement_items = Vec::new();
    let mut pending_separation = false;
    let mut replacement_index = 0;
    while replacement_index < definition.replacement.len() {
        let replacement_token = &definition.replacement[replacement_index];
        match replacement_token {
            MacroReplacementToken::Identifier {
                name: token_name,
                separated,
            } => {
                let argument_index = definition
                    .parameters
                    .as_ref()
                    .and_then(|parameters| parameters.iter().position(|name| name == token_name))
                    .or_else(|| {
                        (definition.variadic && token_name == "__VA_ARGS__").then(|| {
                            definition
                                .parameters
                                .as_ref()
                                .expect("variadic macro requires a parameter list")
                                .len()
                        })
                    });
                if let Some(argument_index) = argument_index {
                    let adjacent_to_paste = matches!(
                        replacement_index
                            .checked_sub(1)
                            .and_then(|index| definition.replacement.get(index)),
                        Some(MacroReplacementToken::Paste { .. })
                    ) || matches!(
                        definition.replacement.get(replacement_index + 1),
                        Some(MacroReplacementToken::Paste { .. })
                    );
                    if adjacent_to_paste {
                        let mut tokens = raw_arguments[argument_index].clone();
                        ensure_macro_replacement_token_capacity(
                            replacement_items.len(),
                            tokens.len().max(1),
                            source,
                            line,
                            column,
                        )?;
                        let separated = *separated | std::mem::take(&mut pending_separation);
                        if let Some(first) = tokens.first_mut() {
                            first.separated = separated;
                            replacement_items
                                .extend(tokens.into_iter().map(MacroSubstitutionItem::Token));
                        } else {
                            replacement_items.push(MacroSubstitutionItem::Placemark { separated });
                        }
                    } else {
                        let argument = expanded_arguments[argument_index]
                            .as_ref()
                            .expect("ordinary substituted macro argument requires prescan");
                        ensure_macro_replacement_token_capacity(
                            replacement_items.len(),
                            argument.tokens.len(),
                            source,
                            line,
                            column,
                        )?;
                        let mut tokens = argument.tokens.clone();
                        if let Some(first) = tokens.first_mut() {
                            first.separated |= *separated || pending_separation;
                            pending_separation = argument.trailing_separation;
                        } else {
                            pending_separation |= *separated || argument.trailing_separation;
                        }
                        replacement_items
                            .extend(tokens.into_iter().map(MacroSubstitutionItem::Token));
                    }
                } else {
                    ensure_macro_replacement_token_capacity(
                        replacement_items.len(),
                        1,
                        source,
                        line,
                        column,
                    )?;
                    replacement_items.push(MacroSubstitutionItem::Token(
                        LocatedToken::new(identifier_token(token_name.clone()), line, column)
                            .with_preprocessing_spelling(
                                token_name.clone(),
                                *separated | std::mem::take(&mut pending_separation),
                            ),
                    ));
                }
            }
            MacroReplacementToken::Other {
                kind: Token::Hash,
                separated,
                ..
            } => {
                let target = definition
                    .replacement
                    .get(replacement_index + 1)
                    .and_then(|token| match token {
                        MacroReplacementToken::Identifier { name, .. } => Some(name.as_str()),
                        MacroReplacementToken::Other { .. }
                        | MacroReplacementToken::Paste { .. } => None,
                    })
                    .expect("validated macro stringification requires a following parameter");
                let argument_index = definition
                    .parameters
                    .as_ref()
                    .and_then(|parameters| parameters.iter().position(|name| name == target))
                    .or_else(|| {
                        (definition.variadic && target == "__VA_ARGS__").then(|| {
                            definition
                                .parameters
                                .as_ref()
                                .expect("variadic macro requires parameters")
                                .len()
                        })
                    })
                    .expect("validated stringification target must be a macro parameter");
                ensure_macro_replacement_token_capacity(
                    replacement_items.len(),
                    1,
                    source,
                    line,
                    column,
                )?;
                replacement_items.push(MacroSubstitutionItem::Token(stringify_macro_argument(
                    &raw_arguments[argument_index],
                    budget,
                    source,
                    line,
                    column,
                    *separated | std::mem::take(&mut pending_separation),
                )?));
                replacement_index += 1;
            }
            MacroReplacementToken::Other {
                kind,
                spelling,
                separated,
            } => {
                ensure_macro_replacement_token_capacity(
                    replacement_items.len(),
                    1,
                    source,
                    line,
                    column,
                )?;
                replacement_items.push(MacroSubstitutionItem::Token(
                    LocatedToken::new(kind.clone(), line, column).with_preprocessing_spelling(
                        spelling.clone(),
                        *separated | std::mem::take(&mut pending_separation),
                    ),
                ));
            }
            MacroReplacementToken::Paste { .. } => {
                replacement_items.push(MacroSubstitutionItem::Paste);
            }
        }
        replacement_index += 1;
    }
    let (replacement, paste_trailing_separation) =
        apply_macro_token_pastes(replacement_items, budget, source, line, column)?;
    pending_separation |= paste_trailing_separation;
    let mut expanded = expand_macro_tokens(
        &replacement,
        macros,
        expansion_stack,
        budget,
        source,
        predefined_source_name,
        predefined_line_offset,
        true,
        depth + 1,
    )?;
    expanded.trailing_separation |= pending_separation;
    expansion_stack.pop();
    Ok(expanded)
}

fn parse_macro_arguments(
    tokens: &[LocatedToken],
    opening: usize,
    name: &str,
    variadic_fixed_count: Option<usize>,
    source: &str,
    line: usize,
    column: usize,
) -> CustResult<(Vec<Vec<LocatedToken>>, usize)> {
    let mut arguments = Vec::new();
    let mut argument = Vec::new();
    let mut depth = 1;
    let mut cursor = opening + 1;
    if tokens
        .get(cursor)
        .is_some_and(|token| token.kind == Token::RParen)
    {
        if variadic_fixed_count == Some(0) {
            arguments.push(Vec::new());
        }
        return Ok((arguments, cursor + 1));
    }
    while let Some(token) = tokens.get(cursor) {
        match token.kind {
            Token::LParen => {
                depth += 1;
                argument.push(token.clone());
            }
            Token::RParen => {
                depth -= 1;
                if depth == 0 {
                    arguments.push(argument);
                    return Ok((arguments, cursor + 1));
                }
                argument.push(token.clone());
            }
            Token::Comma
                if depth == 1
                    && variadic_fixed_count.is_none_or(|fixed| arguments.len() < fixed) =>
            {
                arguments.push(std::mem::take(&mut argument));
            }
            _ => argument.push(token.clone()),
        }
        cursor += 1;
    }
    Err(lexer_error_with_context(
        format!("unterminated invocation of function-like macro '{name}'"),
        source,
        line,
        column,
    ))
}

fn push_expanded_macro_token(
    expanded: &mut Vec<LocatedToken>,
    token: LocatedToken,
    budget: &mut MacroExpansionBudget,
    source: &str,
    line: usize,
    column: usize,
) -> CustResult<()> {
    if budget.emitted_tokens >= MAX_OBJECT_MACRO_EXPANSION_TOKENS {
        return Err(lexer_error_with_context(
            "macro expansion token limit exceeded",
            source,
            line,
            column,
        ));
    }
    budget.emitted_tokens += 1;
    expanded.push(token);
    Ok(())
}

fn is_predefined_macro_name(name: &str) -> bool {
    matches!(name, "__FILE__" | "__LINE__")
}

fn is_macro_defined(macros: &HashMap<String, MacroDefinition>, name: &str) -> bool {
    is_predefined_macro_name(name) || macros.contains_key(name)
}

fn preprocessing_string_literal_spelling(value: &str) -> String {
    let mut spelling = String::from("\"");
    for character in value.chars() {
        match character {
            '\\' => spelling.push_str("\\\\"),
            '"' => spelling.push_str("\\\""),
            '\u{7}' => spelling.push_str("\\a"),
            '\u{8}' => spelling.push_str("\\b"),
            '\t' => spelling.push_str("\\t"),
            '\n' => spelling.push_str("\\n"),
            '\u{b}' => spelling.push_str("\\v"),
            '\u{c}' => spelling.push_str("\\f"),
            '\r' => spelling.push_str("\\r"),
            control if control.is_control() && (control as u32) <= 0o777 => {
                spelling.push_str(&format!("\\{:03o}", control as u32));
            }
            ordinary => spelling.push(ordinary),
        }
    }
    spelling.push('"');
    spelling
}

fn expand_predefined_macro(
    name: &str,
    invocation: &LocatedToken,
    budget: &mut MacroExpansionBudget,
    source: &str,
    predefined_source_name: &str,
    predefined_line_offset: i64,
    depth: usize,
) -> CustResult<LocatedToken> {
    if depth >= MAX_OBJECT_MACRO_EXPANSION_DEPTH {
        return Err(lexer_error_with_context(
            "predefined macro expansion depth limit exceeded",
            source,
            invocation.line,
            invocation.column,
        ));
    }
    if budget.work >= MAX_OBJECT_MACRO_EXPANSION_WORK {
        return Err(lexer_error_with_context(
            "macro expansion work limit exceeded",
            source,
            invocation.line,
            invocation.column,
        ));
    }
    if budget.emitted_tokens >= MAX_OBJECT_MACRO_EXPANSION_TOKENS {
        return Err(lexer_error_with_context(
            "macro expansion token limit exceeded",
            source,
            invocation.line,
            invocation.column,
        ));
    }
    budget.work += 1;
    budget.emitted_tokens += 1;

    let (kind, spelling) = match name {
        "__LINE__" => {
            let physical_line = i64::try_from(invocation.line).map_err(|_| {
                lexer_error_with_context(
                    "predefined line number is out of range",
                    source,
                    invocation.line,
                    invocation.column,
                )
            })?;
            let line = physical_line
                .checked_add(predefined_line_offset)
                .ok_or_else(|| {
                    lexer_error_with_context(
                        "predefined line number is out of range",
                        source,
                        invocation.line,
                        invocation.column,
                    )
                })?;
            (Token::Number(line), line.to_string())
        }
        "__FILE__" => {
            let spelling = preprocessing_string_literal_spelling(predefined_source_name);
            let mut value = predefined_source_name
                .chars()
                .map(|character| character as i64)
                .collect::<Vec<_>>();
            value.push(0);
            (Token::StringLiteral(value), spelling)
        }
        _ => unreachable!("predefined macro expansion requires a predefined name"),
    };
    let mut token = LocatedToken::new(kind, invocation.line, invocation.column)
        .with_preprocessing_spelling(spelling, invocation.separated);
    token.source_origin = invocation.source_origin.clone();
    Ok(token)
}

fn normalize_expanded_integer_tokens(
    mut tokens: Vec<LocatedToken>,
    source: &str,
    preserve_preprocessor_integers: bool,
) -> CustResult<Vec<LocatedToken>> {
    for token in &mut tokens {
        match token.kind.clone() {
            Token::PreprocessorNumber(value) => {
                if preserve_preprocessor_integers {
                    continue;
                }
                if value.bits > i64::MAX as u64 {
                    return Err(lexer_error_with_context(
                        "integer literal out of range",
                        source,
                        token.line,
                        token.column,
                    ));
                }
                token.kind = Token::Number(value.bits as i64);
            }
            Token::RawPreprocessor(spelling) => {
                let mut decoded = lex_with_context(
                    &spelling,
                    source,
                    token.line,
                    token.column,
                    false,
                    preserve_preprocessor_integers,
                    None,
                )?;
                decoded.pop();
                if decoded.len() != 1 {
                    return Err(lexer_error_with_context(
                        format!("preprocessing token '{spelling}' is not supported"),
                        source,
                        token.line,
                        token.column,
                    ));
                }
                token.kind = decoded
                    .pop()
                    .expect("one decoded preprocessing token is required")
                    .kind;
            }
            _ => {}
        }
    }
    Ok(tokens)
}

fn lexer_error_with_context(
    message: impl Into<String>,
    source: &str,
    line: usize,
    column: usize,
) -> CustError {
    let source_line = source.lines().nth(line.saturating_sub(1)).unwrap_or("");
    let caret_padding = " ".repeat(column.saturating_sub(1));
    CustError::new(format!(
        "{} at line {line}, column {column}\n{source_line}\n{caret_padding}^",
        message.into()
    ))
}

fn lexer_error_with_bounded_context(
    message: impl Into<String>,
    source: &str,
    line: usize,
    column: usize,
) -> CustError {
    const MAX_CONTEXT_CHARS: usize = 256;
    const CONTEXT_BEFORE_TARGET: usize = 64;

    let source_line = source.lines().nth(line.saturating_sub(1)).unwrap_or("");
    let target = column.saturating_sub(1);
    let context_start = target.saturating_sub(CONTEXT_BEFORE_TARGET);
    let mut source_chars = source_line.chars().skip(context_start);
    let mut context: String = source_chars.by_ref().take(MAX_CONTEXT_CHARS).collect();
    let truncated_after = source_chars.next().is_some();
    let truncated_before = context_start > 0;
    if truncated_before {
        context.insert_str(0, "...");
    }
    if truncated_after {
        context.push_str("...");
    }
    let caret_column = usize::from(truncated_before) * 3 + target.saturating_sub(context_start);
    let caret_padding = " ".repeat(caret_column);
    CustError::new(format!(
        "{} at line {line}, column {column}\n{context}\n{caret_padding}^",
        message.into()
    ))
}

fn push_token(tokens: &mut Vec<LocatedToken>, kind: Token, line: usize, column: usize) {
    tokens.push(LocatedToken::new(kind, line, column));
}

fn parse_escape_sequence(
    source: &str,
    chars: &SplicedSourceChars,
    line: &mut usize,
    column: &mut usize,
    i: &mut usize,
    literal_start: (usize, usize),
    literal_kind: &str,
) -> CustResult<i64> {
    let (literal_start_line, literal_start_column) = literal_start;
    let Some(escape_char) = chars.get(*i).copied() else {
        return Err(lexer_error_with_context(
            format!("unterminated {literal_kind} literal"),
            source,
            literal_start_line,
            literal_start_column,
        ));
    };

    match escape_char {
        'a' => {
            advance_position(chars, 'a', line, column, i);
            Ok(0x07)
        }
        'b' => {
            advance_position(chars, 'b', line, column, i);
            Ok(0x08)
        }
        'f' => {
            advance_position(chars, 'f', line, column, i);
            Ok(0x0c)
        }
        'n' => {
            advance_position(chars, 'n', line, column, i);
            Ok('\n' as i64)
        }
        'r' => {
            advance_position(chars, 'r', line, column, i);
            Ok('\r' as i64)
        }
        't' => {
            advance_position(chars, 't', line, column, i);
            Ok('\t' as i64)
        }
        'v' => {
            advance_position(chars, 'v', line, column, i);
            Ok(0x0b)
        }
        '\\' => {
            advance_position(chars, '\\', line, column, i);
            Ok('\\' as i64)
        }
        '\'' => {
            advance_position(chars, '\'', line, column, i);
            Ok('\'' as i64)
        }
        '"' => {
            advance_position(chars, '"', line, column, i);
            Ok('"' as i64)
        }
        '?' => {
            advance_position(chars, '?', line, column, i);
            Ok('?' as i64)
        }
        'x' => {
            advance_position(chars, 'x', line, column, i);
            let digits_start = *i;
            let mut value = 0i64;
            while let Some(digit) = chars.get(*i).copied().filter(char::is_ascii_hexdigit) {
                let digit_value = digit.to_digit(16).expect("hex digit should have value") as i64;
                value = value
                    .checked_mul(16)
                    .and_then(|base| base.checked_add(digit_value))
                    .ok_or_else(|| {
                        lexer_error_with_context(
                            "escape sequence value out of range",
                            source,
                            literal_start_line,
                            literal_start_column,
                        )
                    })?;
                advance_position(chars, digit, line, column, i);
            }
            if *i == digits_start {
                return Err(lexer_error_with_context(
                    "hex escape sequence requires at least one digit",
                    source,
                    literal_start_line,
                    literal_start_column,
                ));
            }
            Ok(value)
        }
        '0'..='7' => {
            let mut value = 0i64;
            for _ in 0..3 {
                let Some(digit) = chars.get(*i).copied() else {
                    break;
                };
                if !matches!(digit, '0'..='7') {
                    break;
                }
                let digit_value = digit.to_digit(8).expect("octal digit should have value") as i64;
                value = value * 8 + digit_value;
                advance_position(chars, digit, line, column, i);
            }
            Ok(value)
        }
        other => Err(lexer_error_with_context(
            format!("unsupported {literal_kind} escape '\\{other}'"),
            source,
            literal_start_line,
            literal_start_column,
        )),
    }
}

fn consume_integer_suffix(
    source: &str,
    chars: &SplicedSourceChars,
    line: &mut usize,
    column: &mut usize,
    i: &mut usize,
) -> CustResult<bool> {
    let suffix_start = *i;
    let suffix_line = *line;
    let suffix_column = *column;
    while chars
        .get(*i)
        .is_some_and(|character| character.is_ascii_alphanumeric() || *character == '_')
    {
        let character = chars[*i];
        advance_position(chars, character, line, column, i);
    }
    if suffix_start == *i {
        return Ok(false);
    }

    let suffix: String = chars[suffix_start..*i].iter().collect();
    let is_unsigned = |part: &str| matches!(part, "u" | "U");
    let is_long = |part: &str| matches!(part, "l" | "L" | "ll" | "LL");
    let valid = is_unsigned(&suffix)
        || is_long(&suffix)
        || suffix
            .get(1..)
            .is_some_and(|long| is_unsigned(&suffix[..1]) && is_long(long))
        || suffix
            .get(..suffix.len().saturating_sub(1))
            .is_some_and(|long| is_long(long) && is_unsigned(&suffix[suffix.len() - 1..]));
    if !valid {
        return Err(lexer_error_with_context(
            "invalid integer literal suffix",
            source,
            suffix_line,
            suffix_column,
        ));
    }
    Ok(suffix.contains(['u', 'U']))
}

fn advance_position(
    chars: &SplicedSourceChars,
    _c: char,
    line: &mut usize,
    column: &mut usize,
    i: &mut usize,
) {
    *i += 1;
    (*line, *column) = chars.position(*i);
}

struct Parser {
    tokens: Vec<LocatedToken>,
    pos: usize,
    struct_types: HashMap<String, StructTypeDef>,
    aggregate_type_scopes: Vec<HashMap<String, String>>,
    enum_type_scopes: Vec<HashSet<String>>,
    enum_constant_scopes: Vec<HashMap<String, i64>>,
    type_alias_scopes: Vec<HashMap<String, TypeAlias>>,
    const_type_alias_scopes: Vec<HashSet<String>>,
    qualified_type_alias_scopes: Vec<HashSet<String>>,
    next_static_local_id: usize,
    next_aggregate_type_id: usize,
    last_decl_had_initializer: bool,
    pending_inline_enum_constants: Option<Vec<EnumConstant>>,
    parsing_function_body: bool,
}

impl Parser {
    fn new(tokens: Vec<LocatedToken>) -> Self {
        Self {
            tokens,
            pos: 0,
            struct_types: HashMap::new(),
            aggregate_type_scopes: vec![HashMap::new()],
            enum_type_scopes: vec![HashSet::new()],
            enum_constant_scopes: vec![HashMap::new()],
            type_alias_scopes: vec![HashMap::new()],
            const_type_alias_scopes: vec![HashSet::new()],
            qualified_type_alias_scopes: vec![HashSet::new()],
            next_static_local_id: 0,
            next_aggregate_type_id: 0,
            last_decl_had_initializer: false,
            pending_inline_enum_constants: None,
            parsing_function_body: false,
        }
    }

    fn parse_program(&mut self) -> CustResult<Program> {
        let mut globals = Vec::new();
        let mut functions = HashMap::new();
        let mut prototypes = HashMap::new();
        while !self.check(&Token::Eof) {
            if self.check(&Token::RBrace) {
                return Err(Self::error_at(
                    "unmatched '}' at top level".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::RParen) {
                return Err(Self::error_at(
                    "unmatched ')' at top level".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::RBracket) {
                return Err(Self::error_at(
                    "unmatched ']' at top level".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::StaticAssert) {
                globals.push(self.parse_static_assert()?);
                continue;
            }
            if self.check(&Token::Return) {
                return Err(Self::error_at(
                    "return outside function".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::Break) {
                return Err(Self::error_at(
                    "break outside loop or switch".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::Continue) {
                return Err(Self::error_at(
                    "continue outside loop".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::If) {
                return Err(Self::error_at(
                    "if statement outside function".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::Else) {
                return Err(Self::error_at(
                    "else without matching if".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::While) {
                return Err(Self::error_at(
                    "while loop outside function".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::Do) {
                return Err(Self::error_at(
                    "do loop outside function".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::For) {
                return Err(Self::error_at(
                    "for loop outside function".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::Switch) {
                return Err(Self::error_at(
                    "switch statement outside function".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::Case) {
                return Err(Self::error_at(
                    "case label outside switch".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::Default) {
                return Err(Self::error_at(
                    "default label outside switch".to_string(),
                    self.peek_located(),
                ));
            }
            let _has_alignment_specifier = self.consume_alignment_specifiers()?;
            let leading_function_specifier = self.consume_function_specifiers();
            self.consume_thread_local_specifiers();
            let is_extern = self.matches(&Token::Extern);
            let _is_static = !is_extern && self.matches(&Token::Static);
            self.consume_thread_local_specifiers();
            self.consume_alignment_specifiers()?;
            let has_function_specifier =
                leading_function_specifier || self.consume_function_specifiers();
            if let Some(token) = self.anonymous_aggregate_return_type_token() {
                return Err(Self::error_at(
                    "anonymous aggregate return types are not supported".to_string(),
                    token,
                ));
            }
            if let Some(token) = self.void_pointer_star_token_at_current() {
                return Err(Self::error_at(
                    "void pointers are not supported".to_string(),
                    token,
                ));
            }
            if self.check(&Token::Void) && !self.starts_function_definition() {
                return Err(Self::error_at(
                    "void object declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            if self.starts_function_definition()
                || self.starts_struct_function_declaration()
                || self.starts_alias_function_declaration()
                || self.starts_malformed_function_definition()
                || self.check(&Token::Void)
            {
                let (name, top_level_function, inline_return_enum_decl) =
                    self.parse_function_declaration()?;
                if let Some(stmt) = inline_return_enum_decl {
                    globals.push(stmt);
                }
                match top_level_function {
                    TopLevelFunction::Definition(function) => {
                        let signature = FunctionSignature::from_function(&function);
                        match prototypes.get(&name) {
                            Some(prototype) if prototype != &signature => {
                                return Err(CustError::new(format!(
                                    "function definition for '{name}' conflicts with previous prototype"
                                )));
                            }
                            _ => {}
                        }
                        if functions.insert(name.clone(), function).is_some() {
                            return Err(CustError::new(format!(
                                "function '{name}' already defined"
                            )));
                        }
                    }
                    TopLevelFunction::Prototype(signature) => {
                        match functions.get(&name) {
                            Some(function)
                                if FunctionSignature::from_function(function) != signature =>
                            {
                                return Err(CustError::new(format!(
                                    "function prototype for '{name}' conflicts with previous definition"
                                )));
                            }
                            _ => {}
                        }
                        if let Some(previous) = prototypes.get(&name) {
                            if previous != &signature {
                                return Err(CustError::new(format!(
                                    "function prototype for '{name}' conflicts with previous declaration"
                                )));
                            }
                        } else {
                            prototypes.insert(name, signature);
                        }
                    }
                }
            } else if has_function_specifier {
                return Err(Self::error_at(
                    "function specifiers are only supported on function declarations".to_string(),
                    self.peek_located(),
                ));
            } else if self.starts_qualified_aggregate_declaration() {
                let global = self.parse_aggregate_var_decl()?;
                if !is_extern || self.last_decl_had_initializer {
                    globals.push(global);
                }
            } else if matches!(
                self.peek(),
                Token::Int
                    | Token::Char
                    | Token::Bool
                    | Token::Float
                    | Token::Double
                    | Token::Complex
                    | Token::Imaginary
                    | Token::Signed
                    | Token::Unsigned
                    | Token::Long
                    | Token::Short
                    | Token::Const
                    | Token::Volatile
                    | Token::Restrict
                    | Token::Atomic
            ) || self.current_alias().is_some()
            {
                let global = self.parse_var_decl()?;
                if !is_extern || self.last_decl_had_initializer {
                    globals.push(global);
                }
            } else if self.check(&Token::Typedef) {
                if let Some(stmt) = self.parse_typedef_decl()? {
                    globals.push(stmt);
                }
            } else if self.check(&Token::Enum) {
                if self.starts_typedef_enum_definition()
                    && self.enum_definition_followed_by_semicolon()
                {
                    globals.push(self.parse_enum_decl()?);
                } else {
                    let global = self.parse_var_decl()?;
                    if !is_extern || self.last_decl_had_initializer {
                        globals.push(global);
                    }
                }
            } else if matches!(self.peek(), Token::Struct | Token::Union) {
                if self.is_aggregate_definition() {
                    if let Some(stmt) = self.parse_aggregate_definition()? {
                        globals.push(stmt);
                    }
                } else if self.is_aggregate_forward_declaration() {
                    let keyword = match self.peek() {
                        Token::Struct => "struct",
                        Token::Union => "union",
                        _ => unreachable!("checked aggregate keyword above"),
                    };
                    return Err(Self::error_at(
                        format!("forward {keyword} declarations are not supported"),
                        self.tokens
                            .get(self.pos + 2)
                            .expect("forward aggregate declaration has a semicolon"),
                    ));
                } else {
                    let global = self.parse_aggregate_var_decl()?;
                    if !is_extern || self.last_decl_had_initializer {
                        globals.push(global);
                    }
                }
            } else {
                let found = self.peek_located().clone();
                if matches!(
                    found.kind,
                    Token::LBrace | Token::Comma | Token::Question | Token::Dot | Token::Arrow
                ) {
                    return Err(Self::error_at(
                        format!("expected top-level declaration, found {:?}", found.kind),
                        &found,
                    ));
                }
                return Err(Self::error_at(
                    format!("unexpected token at top level: {:?}", found.kind),
                    &found,
                ));
            }
        }
        self.expect(Token::Eof)?;
        if !functions.contains_key("main") {
            return Err(CustError::new("missing main() function"));
        }
        Ok(Program {
            globals,
            functions,
            prototypes,
            struct_types: self.struct_types.clone(),
        })
    }

    fn consume_function_specifiers(&mut self) -> bool {
        let mut consumed = false;
        while matches!(self.peek(), Token::Inline | Token::Noreturn) {
            self.advance();
            consumed = true;
        }
        consumed
    }

    fn consume_thread_local_specifiers(&mut self) -> bool {
        let mut consumed = false;
        while self.matches(&Token::ThreadLocal) {
            consumed = true;
        }
        consumed
    }

    fn consume_alignment_specifiers(&mut self) -> CustResult<bool> {
        let mut consumed = false;
        while self.matches(&Token::Alignas) {
            consumed = true;
            self.expect_opening_paren_after("_Alignas")?;
            self.reject_missing_alignas_argument()?;
            if self.is_type_name_start() {
                self.parse_sizeof_like_type_name("_Alignas")?;
            } else {
                self.parse_assignment_expr()?;
            }
            self.expect_closing_paren_after("_Alignas specifier")?;
        }
        Ok(consumed)
    }

    fn reject_missing_alignas_argument(&self) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::Comma
                | Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::RParen
                | Token::RBracket
                | Token::Semi
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!("expected _Alignas argument, found {:?}", self.peek()),
                self.peek_located(),
            ));
        }
        match self.integer_constant_invalid_start_or_selector_label() {
            Some(label) if !self.is_type_name_start() => {
                return Err(Self::error_at(
                    format!("expected _Alignas argument before '{label}'"),
                    self.peek_located(),
                ));
            }
            _ => {}
        }
        Ok(())
    }

    fn is_aggregate_definition(&self) -> bool {
        if !matches!(
            (
                self.peek(),
                self.tokens.get(self.pos + 1).map(|token| &token.kind),
                self.tokens.get(self.pos + 2).map(|token| &token.kind)
            ),
            (
                Token::Struct | Token::Union,
                Some(Token::Ident(_)),
                Some(Token::LBrace)
            )
        ) {
            return false;
        }

        self.aggregate_definition_body_followed_by_semicolon(self.pos + 2)
    }

    fn aggregate_definition_body_followed_by_semicolon(&self, opening_brace: usize) -> bool {
        let mut cursor = opening_brace;
        let mut depth = 0;
        while let Some(token) = self.tokens.get(cursor) {
            match &token.kind {
                Token::LBrace => depth += 1,
                Token::RBrace => {
                    depth -= 1;
                    if depth == 0 {
                        return matches!(
                            self.tokens.get(cursor + 1).map(|token| &token.kind),
                            Some(Token::Semi)
                        );
                    }
                }
                Token::Eof => return false,
                _ => {}
            }
            cursor += 1;
        }
        false
    }

    fn is_aggregate_forward_declaration(&self) -> bool {
        matches!(
            (
                self.peek(),
                self.tokens.get(self.pos + 1).map(|token| &token.kind),
                self.tokens.get(self.pos + 2).map(|token| &token.kind)
            ),
            (
                Token::Struct | Token::Union,
                Some(Token::Ident(_)),
                Some(Token::Semi)
            )
        )
    }

    fn starts_struct_function_declaration(&self) -> bool {
        if !matches!(self.peek(), Token::Struct | Token::Union) {
            return false;
        }
        let Some(mut index) = self.skip_aggregate_type_specifier_at(self.pos) else {
            return false;
        };
        index = self.skip_type_qualifiers_at(index);
        while matches!(
            self.tokens.get(index).map(|token| &token.kind),
            Some(Token::Star)
        ) || self.type_qualifier_at(index)
        {
            index += 1;
        }
        matches!(
            (
                self.tokens.get(index).map(|token| &token.kind),
                self.tokens.get(index + 1).map(|token| &token.kind)
            ),
            (Some(Token::Ident(_)), Some(Token::LParen))
        )
    }

    fn starts_alias_function_declaration(&self) -> bool {
        self.current_alias().is_some()
            && matches!(
                (
                    self.tokens.get(self.pos + 1).map(|token| &token.kind),
                    self.tokens.get(self.pos + 2).map(|token| &token.kind)
                ),
                (Some(Token::Ident(_)), Some(Token::LParen))
            )
    }

    fn anonymous_aggregate_return_type_token(&self) -> Option<&LocatedToken> {
        let index = self.skip_type_qualifiers_at(self.pos);
        if !matches!(
            self.tokens.get(index).map(|token| &token.kind),
            Some(Token::Struct | Token::Union)
        ) || !matches!(
            self.tokens.get(index + 1).map(|token| &token.kind),
            Some(Token::LBrace)
        ) {
            return None;
        }

        let mut cursor = index + 2;
        let mut depth = 1usize;
        while let Some(token) = self.tokens.get(cursor) {
            match token.kind {
                Token::LBrace => depth += 1,
                Token::RBrace => {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
                Token::Eof => return None,
                _ => {}
            }
            cursor += 1;
        }
        if depth != 0 {
            return None;
        }

        let mut after = self.skip_type_qualifiers_at(cursor + 1);
        while matches!(
            self.tokens.get(after).map(|token| &token.kind),
            Some(Token::Star)
        ) || self.type_qualifier_at(after)
        {
            after += 1;
        }

        if matches!(
            (
                self.tokens.get(after).map(|token| &token.kind),
                self.tokens.get(after + 1).map(|token| &token.kind)
            ),
            (Some(Token::Ident(_)), Some(Token::LParen))
        ) {
            self.tokens.get(index)
        } else {
            None
        }
    }

    fn current_alias(&self) -> Option<&TypeAlias> {
        match self.peek() {
            Token::Ident(name) => self.lookup_type_alias(name),
            _ => None,
        }
    }

    fn alias_at_index(&self, index: usize) -> Option<&TypeAlias> {
        match self.tokens.get(index).map(|token| &token.kind) {
            Some(Token::Ident(name)) => self.lookup_type_alias(name),
            _ => None,
        }
    }

    fn lookup_type_alias(&self, name: &str) -> Option<&TypeAlias> {
        self.type_alias_scopes
            .iter()
            .rev()
            .find_map(|scope| scope.get(name))
    }

    fn type_alias_is_const(&self, name: &str) -> bool {
        self.type_alias_scopes
            .iter()
            .zip(&self.const_type_alias_scopes)
            .rev()
            .find_map(|(aliases, const_aliases)| {
                aliases
                    .contains_key(name)
                    .then(|| const_aliases.contains(name))
            })
            .unwrap_or(false)
    }

    fn type_alias_is_qualified(&self, name: &str) -> bool {
        self.type_alias_scopes
            .iter()
            .zip(&self.qualified_type_alias_scopes)
            .rev()
            .find_map(|(aliases, qualified_aliases)| {
                aliases
                    .contains_key(name)
                    .then(|| qualified_aliases.contains(name))
            })
            .unwrap_or(false)
    }

    fn enum_type_is_declared(&self, name: &str) -> bool {
        self.enum_type_scopes
            .iter()
            .rev()
            .any(|scope| scope.contains(name))
    }

    fn lookup_enum_constant(&self, name: &str) -> Option<i64> {
        self.enum_constant_scopes
            .iter()
            .rev()
            .find_map(|scope| scope.get(name).copied())
    }

    fn resolve_aggregate_type(&self, name: &str) -> Option<String> {
        self.aggregate_type_scopes
            .iter()
            .rev()
            .find_map(|scope| scope.get(name).cloned())
    }

    fn parse_decl_type(&mut self, context: &str) -> CustResult<DeclType> {
        let (_, decl_type) = self.parse_decl_type_with_embedded_qualifiers(context)?;
        Ok(decl_type)
    }

    fn leading_restrict_qualifier_token(&self) -> Option<&LocatedToken> {
        let mut offset = 0;
        loop {
            match self.tokens.get(self.pos + offset).map(|token| &token.kind) {
                Some(Token::Restrict) => return self.tokens.get(self.pos + offset),
                Some(Token::Const | Token::Volatile) => offset += 1,
                Some(Token::Atomic) if self.bare_atomic_qualifier_at(self.pos + offset) => {
                    offset += 1;
                }
                _ => return None,
            }
        }
    }

    fn reject_leading_restrict_qualifier(&self) -> CustResult<()> {
        if let Some(token) = self.leading_restrict_qualifier_token() {
            return Err(Self::error_at(
                "restrict qualifiers are only supported on pointer declarators".to_string(),
                token,
            ));
        }
        Ok(())
    }

    fn reject_floating_point_type_specifier(&self, token: &LocatedToken) -> CustResult<()> {
        if matches!(token.kind, Token::Float | Token::Double) {
            return Err(Self::error_at(
                "floating-point types are not supported".to_string(),
                token,
            ));
        }
        Ok(())
    }

    fn reject_complex_type_specifier(&self, token: &LocatedToken) -> CustResult<()> {
        if matches!(token.kind, Token::Complex | Token::Imaginary) {
            return Err(Self::error_at(
                "complex types are not supported".to_string(),
                token,
            ));
        }
        Ok(())
    }

    fn parse_decl_type_with_embedded_qualifiers(
        &mut self,
        context: &str,
    ) -> CustResult<(bool, DeclType)> {
        self.reject_leading_restrict_qualifier()?;
        let found = self.advance();
        self.reject_floating_point_type_specifier(&found)?;
        self.reject_complex_type_specifier(&found)?;
        let mut saw_const = false;
        match found.kind.clone() {
            Token::Int
            | Token::Char
            | Token::Bool
            | Token::Signed
            | Token::Unsigned
            | Token::Long
            | Token::Short => self.parse_scalar_decl_type_specifiers(found),
            Token::Atomic => {
                self.expect_opening_paren_after("_Atomic")?;
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        "expected _Atomic type before '['".to_string(),
                        self.peek_located(),
                    ));
                }
                if self.check(&Token::Question) {
                    return Err(Self::error_at(
                        "expected _Atomic type before '?'".to_string(),
                        self.peek_located(),
                    ));
                }
                if self.check(&Token::LBrace) {
                    return Err(Self::error_at(
                        "expected _Atomic type before '{'".to_string(),
                        self.peek_located(),
                    ));
                }
                match self.integer_constant_invalid_start_or_selector_label() {
                    Some(label) if !self.is_type_name_start() => {
                        return Err(Self::error_at(
                            format!("expected _Atomic type before '{label}'"),
                            self.peek_located(),
                        ));
                    }
                    _ => {}
                }
                if matches!(
                    self.peek(),
                    Token::Comma
                        | Token::RParen
                        | Token::RBracket
                        | Token::Semi
                        | Token::RBrace
                        | Token::Eof
                ) {
                    let found = self.peek_located().clone();
                    return Err(Self::error_at(
                        format!("expected _Atomic type, found {:?}", found.kind),
                        &found,
                    ));
                }
                self.reject_leading_restrict_qualifier()?;
                if self.check(&Token::Atomic) {
                    return Err(Self::error_at(
                        "nested _Atomic type specifiers are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                let atomic_leading_qualifier = self.leading_type_qualifier_token();
                let atomic_leading_const = self.consume_type_qualifiers();
                let atomic_type_token = self.peek_located().clone();
                let atomic_alias_is_qualified = match &atomic_type_token.kind {
                    Token::Ident(name) => self.type_alias_is_qualified(name),
                    _ => false,
                };
                let atomic_alias_is_const = match &atomic_type_token.kind {
                    Token::Ident(name) => self.type_alias_is_const(name),
                    _ => false,
                };
                let atomic_nested_start = self.pos;
                let (mut nested_const, mut decl_type) =
                    self.parse_decl_type_with_embedded_qualifiers("_Atomic type name")?;
                nested_const |= atomic_alias_is_const;
                let atomic_nested_qualifier = self.tokens[atomic_nested_start..self.pos]
                    .iter()
                    .find(|token| {
                        matches!(
                            token.kind,
                            Token::Const | Token::Volatile | Token::Restrict | Token::Atomic
                        )
                    })
                    .cloned();
                nested_const |= atomic_leading_const;
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        "array _Atomic types are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                if !self.check(&Token::Star) {
                    if atomic_alias_is_qualified {
                        return Err(Self::error_at(
                            "qualified _Atomic types are not supported".to_string(),
                            &atomic_type_token,
                        ));
                    }
                    if let Some(qualifier) = atomic_leading_qualifier.or(atomic_nested_qualifier) {
                        return Err(Self::error_at(
                            "qualified _Atomic types are not supported".to_string(),
                            &qualifier,
                        ));
                    }
                    if nested_const {
                        return Err(Self::error_at(
                            "qualified _Atomic types are not supported".to_string(),
                            &atomic_type_token,
                        ));
                    }
                }
                if self.matches(&Token::Star) {
                    let pointee = match decl_type {
                        DeclType::Scalar(ty) => PointeeType::Scalar(ty),
                        DeclType::Struct(type_name) => PointeeType::Struct(type_name),
                        DeclType::Pointer { .. } | DeclType::Array2DPointer { .. } => {
                            return Err(Self::error_at(
                                "pointer-to-pointer _Atomic types are not supported".to_string(),
                                self.previous(),
                            ));
                        }
                        DeclType::Array(_, _) | DeclType::Array2D(_, _, _) => {
                            return Err(Self::error_at(
                                "pointer-to-array _Atomic types are not supported".to_string(),
                                self.previous(),
                            ));
                        }
                    };
                    let pointer_qualifier = self.leading_type_qualifier_token();
                    saw_const |= self.consume_type_qualifiers();
                    if let Some(qualifier) = pointer_qualifier {
                        return Err(Self::error_at(
                            "qualified _Atomic types are not supported".to_string(),
                            &qualifier,
                        ));
                    }
                    if self.check(&Token::Star) {
                        return Err(Self::error_at(
                            "pointer-to-pointer _Atomic types are not supported".to_string(),
                            self.peek_located(),
                        ));
                    }
                    if self.check(&Token::LBracket) {
                        return Err(Self::error_at(
                            "pointer array _Atomic types are not supported".to_string(),
                            self.peek_located(),
                        ));
                    }
                    decl_type = DeclType::Pointer {
                        pointee,
                        points_to_const: nested_const,
                    };
                } else {
                    if matches!(
                        decl_type,
                        DeclType::Array(_, _) | DeclType::Array2D(_, _, _)
                    ) {
                        return Err(Self::error_at(
                            "array _Atomic types are not supported".to_string(),
                            &atomic_type_token,
                        ));
                    }
                    saw_const |= nested_const;
                }
                self.reject_function_type_suffix("function _Atomic types")?;
                self.expect_closing_paren_after("_Atomic type")?;
                saw_const |= self.consume_type_qualifiers();
                Ok((saw_const, decl_type))
            }
            Token::Struct | Token::Union => {
                let kind = if matches!(found.kind, Token::Union) {
                    AggregateKind::Union
                } else {
                    AggregateKind::Struct
                };
                let keyword = kind.keyword();
                if self.check(&Token::LBrace)
                    || matches!(
                        (
                            self.peek(),
                            self.tokens.get(self.pos + 1).map(|token| &token.kind)
                        ),
                        (Token::Ident(_), Some(Token::LBrace))
                    )
                {
                    let allow_anonymous = self.check(&Token::LBrace);
                    let (internal_type_name, _, _) = self
                        .parse_aggregate_definition_body_after_keyword(
                            kind,
                            false,
                            allow_anonymous,
                        )?;
                    saw_const |= self.consume_type_qualifiers();
                    return Ok((saw_const, DeclType::Struct(internal_type_name)));
                }
                let type_name = self.expect_ident_after(context)?;
                saw_const |= self.consume_type_qualifiers();
                let Some(internal_type_name) = self.resolve_aggregate_type(&type_name) else {
                    return Err(CustError::new(format!(
                        "undefined {keyword} type '{type_name}'"
                    )));
                };
                Ok((saw_const, DeclType::Struct(internal_type_name)))
            }
            Token::Enum => {
                if self.starts_enum_definition_after_keyword() {
                    let constants = self.parse_enum_decl_body_after_keyword(false)?;
                    self.push_pending_inline_enum_constants(constants);
                    saw_const |= self.consume_type_qualifiers();
                    return Ok((saw_const, DeclType::Scalar(CType::Int)));
                }
                let type_name_token = self.advance();
                let type_name = match type_name_token.kind.clone() {
                    Token::Ident(type_name) => type_name,
                    token => {
                        return Err(Self::error_at(
                            format!("expected enum type name, found {token:?}"),
                            &type_name_token,
                        ));
                    }
                };
                saw_const |= self.consume_type_qualifiers();
                if self.check(&Token::Semi) {
                    return Err(Self::error_at(
                        "forward enum declarations are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                if !self.enum_type_is_declared(&type_name) {
                    return Err(Self::error_at(
                        format!("undefined enum type '{type_name}'"),
                        &type_name_token,
                    ));
                }
                Ok((saw_const, DeclType::Scalar(CType::Int)))
            }
            Token::Ident(name) => match self.lookup_type_alias(&name).cloned() {
                Some(TypeAlias::Scalar(ty)) => {
                    saw_const |= self.consume_type_qualifiers();
                    Ok((saw_const, DeclType::Scalar(ty)))
                }
                Some(TypeAlias::Struct(type_name)) => {
                    saw_const |= self.consume_type_qualifiers();
                    Ok((saw_const, DeclType::Struct(type_name)))
                }
                Some(TypeAlias::Pointer {
                    pointee,
                    points_to_const,
                }) => {
                    saw_const |= self.consume_type_qualifiers();
                    Ok((
                        saw_const,
                        DeclType::Pointer {
                            pointee,
                            points_to_const,
                        },
                    ))
                }
                Some(TypeAlias::Array(pointee, len)) => {
                    saw_const |= self.consume_type_qualifiers();
                    Ok((saw_const, DeclType::Array(pointee, len)))
                }
                Some(TypeAlias::Array2D(ty, rows, columns)) => {
                    saw_const |= self.consume_type_qualifiers();
                    Ok((saw_const, DeclType::Array2D(ty, rows, columns)))
                }
                Some(TypeAlias::Array2DPointer {
                    elem_type,
                    columns,
                    points_to_const,
                }) => {
                    saw_const |= self.consume_type_qualifiers();
                    Ok((
                        saw_const,
                        DeclType::Array2DPointer {
                            elem_type,
                            columns,
                            points_to_const,
                        },
                    ))
                }
                None => Err(Self::error_at(
                    format!("expected {context}, found Ident(\"{name}\")"),
                    &found,
                )),
            },
            token => Err(Self::error_at(
                format!("expected type, found {token:?}"),
                &found,
            )),
        }
    }

    fn parse_scalar_decl_type_specifiers(
        &mut self,
        first: LocatedToken,
    ) -> CustResult<(bool, DeclType)> {
        let mut saw_const = false;
        let mut saw_char = false;
        let mut saw_bool = false;
        let mut saw_int = false;
        let mut saw_short = false;
        let mut long_count = 0;
        let mut sign_count = 0;
        let mut specifiers = vec![first.clone()];

        Self::record_scalar_type_specifier(
            first.kind,
            &mut saw_char,
            &mut saw_bool,
            &mut saw_int,
            &mut saw_short,
            &mut long_count,
            &mut sign_count,
        );
        saw_const |= self.consume_type_qualifiers();

        while Self::scalar_type_specifier_token(self.peek()) {
            let specifier = self.advance();
            specifiers.push(specifier.clone());
            Self::record_scalar_type_specifier(
                specifier.kind,
                &mut saw_char,
                &mut saw_bool,
                &mut saw_int,
                &mut saw_short,
                &mut long_count,
                &mut sign_count,
            );
            saw_const |= self.consume_type_qualifiers();
        }

        if sign_count > 1
            || long_count > 2
            || (saw_short && long_count > 0)
            || (saw_char && (saw_int || saw_short || long_count > 0 || saw_bool))
            || (saw_bool && (saw_int || saw_short || long_count > 0 || sign_count > 0))
        {
            let token = Self::invalid_scalar_type_specifier_token(&specifiers);
            return Err(Self::error_at(
                "invalid scalar type specifier combination".to_string(),
                token,
            ));
        }

        let ty = if saw_char {
            CType::Char
        } else if saw_bool {
            CType::Bool
        } else {
            CType::Int
        };
        Ok((saw_const, DeclType::Scalar(ty)))
    }

    fn invalid_scalar_type_specifier_token(specifiers: &[LocatedToken]) -> &LocatedToken {
        let mut saw_char = false;
        let mut saw_bool = false;
        let mut saw_int = false;
        let mut saw_short = false;
        let mut long_count = 0;
        let mut sign_count = 0;

        for specifier in specifiers {
            Self::record_scalar_type_specifier(
                specifier.kind.clone(),
                &mut saw_char,
                &mut saw_bool,
                &mut saw_int,
                &mut saw_short,
                &mut long_count,
                &mut sign_count,
            );

            if sign_count > 1
                || long_count > 2
                || (saw_short && long_count > 0)
                || (saw_char && (saw_int || saw_short || long_count > 0 || saw_bool))
                || (saw_bool && (saw_int || saw_short || long_count > 0 || sign_count > 0))
            {
                return specifier;
            }
        }

        specifiers
            .last()
            .expect("at least one scalar type specifier is present")
    }

    fn scalar_type_specifier_token(token: &Token) -> bool {
        matches!(
            token,
            Token::Int
                | Token::Char
                | Token::Bool
                | Token::Signed
                | Token::Unsigned
                | Token::Long
                | Token::Short
        )
    }

    fn record_scalar_type_specifier(
        specifier: Token,
        saw_char: &mut bool,
        saw_bool: &mut bool,
        saw_int: &mut bool,
        saw_short: &mut bool,
        long_count: &mut usize,
        sign_count: &mut usize,
    ) {
        match specifier {
            Token::Char => *saw_char = true,
            Token::Bool => *saw_bool = true,
            Token::Int => *saw_int = true,
            Token::Short => *saw_short = true,
            Token::Long => *long_count += 1,
            Token::Signed | Token::Unsigned => *sign_count += 1,
            _ => unreachable!("caller only passes scalar type specifier tokens"),
        }
    }

    fn leading_type_qualifier_token(&self) -> Option<LocatedToken> {
        if matches!(
            self.peek(),
            Token::Const | Token::Volatile | Token::Restrict
        ) || self.bare_atomic_qualifier_at(self.pos)
        {
            Some(self.peek_located().clone())
        } else {
            None
        }
    }

    fn type_qualifier_label(token: &Token) -> &'static str {
        match token {
            Token::Const => "const",
            Token::Volatile => "volatile",
            Token::Restrict => "restrict",
            Token::Atomic => "_Atomic",
            _ => "<unknown>",
        }
    }

    fn consume_type_qualifiers(&mut self) -> bool {
        self.consume_type_qualifiers_with_last().0
    }

    fn consume_type_qualifiers_with_last(&mut self) -> (bool, Option<LocatedToken>) {
        let mut saw_const = false;
        let mut last_qualifier = None;
        while matches!(
            self.peek(),
            Token::Const | Token::Volatile | Token::Restrict
        ) || self.bare_atomic_qualifier_at(self.pos)
        {
            let qualifier = self.peek_located().clone();
            if self.matches(&Token::Const) {
                saw_const = true;
            } else if self.matches(&Token::Restrict) {
                // `restrict` is accepted as parser-level C syntax over Cust's
                // existing interpreter-owned pointer model. It does not change
                // runtime aliasing behavior.
            } else if self.matches(&Token::Atomic) {
                // Bare `_Atomic` is accepted as parser-level C syntax over Cust's
                // deterministic storage model. The `_Atomic(type-name)` form is
                // parsed as a type specifier by parse_decl_type.
            } else {
                self.expect(Token::Volatile)
                    .expect("peek confirmed volatile token");
            }
            last_qualifier = Some(qualifier);
        }
        (saw_const, last_qualifier)
    }

    fn declaration_type_context(context: &str) -> &str {
        match context {
            "struct type name" => "declaration type",
            "typedef struct type name" => "typedef alias type",
            "struct return type name" => "function return type",
            _ => context,
        }
    }

    fn reject_missing_type_after_qualifier(
        &self,
        context: &str,
        qualifier: Option<&LocatedToken>,
    ) -> CustResult<()> {
        if let (Some(qualifier), false) = (qualifier, self.is_type_name_start()) {
            return Err(Self::error_at(
                format!(
                    "expected {} after type qualifier '{}', found {:?}",
                    Self::declaration_type_context(context),
                    Self::type_qualifier_label(&qualifier.kind),
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn bare_atomic_qualifier_at(&self, index: usize) -> bool {
        matches!(
            self.tokens.get(index).map(|token| &token.kind),
            Some(Token::Atomic)
        ) && !matches!(
            self.tokens.get(index + 1).map(|token| &token.kind),
            Some(Token::LParen)
        )
    }

    fn starts_qualified_aggregate_declaration(&self) -> bool {
        let mut offset = 0;
        let mut saw_qualifier = false;
        while matches!(
            self.tokens.get(self.pos + offset).map(|token| &token.kind),
            Some(Token::Const | Token::Volatile | Token::Restrict)
        ) || self.bare_atomic_qualifier_at(self.pos + offset)
        {
            saw_qualifier = true;
            offset += 1;
        }
        saw_qualifier
            && matches!(
                self.tokens.get(self.pos + offset).map(|token| &token.kind),
                Some(Token::Struct | Token::Union)
            )
    }

    fn parse_const_qualified_decl_type(&mut self, context: &str) -> CustResult<(bool, DeclType)> {
        self.reject_leading_restrict_qualifier()?;
        let (leading_const, last_qualifier) = self.consume_type_qualifiers_with_last();
        self.reject_missing_type_after_qualifier(context, last_qualifier.as_ref())?;
        let alias_const = match self.peek() {
            Token::Ident(name) => self.type_alias_is_const(name),
            _ => false,
        };
        let (embedded_const, decl_type) = self.parse_decl_type_with_embedded_qualifiers(context)?;
        Ok((leading_const || embedded_const || alias_const, decl_type))
    }

    fn decl_type_to_return_type(decl_type: DeclType) -> ReturnType {
        match decl_type {
            DeclType::Scalar(ty) => ReturnType::Scalar(ty),
            DeclType::Struct(type_name) => ReturnType::Struct(type_name),
            DeclType::Pointer {
                pointee,
                points_to_const,
            } => ReturnType::Pointer {
                ty: pointee,
                points_to_const,
            },
            DeclType::Array2DPointer {
                elem_type,
                columns,
                points_to_const,
            } => ReturnType::Array2DPointer {
                elem_type,
                columns,
                points_to_const,
            },
            DeclType::Array(_, _) | DeclType::Array2D(_, _, _) => {
                unreachable!("array aliases are not valid return types")
            }
        }
    }

    fn decl_type_to_param_type(decl_type: &DeclType) -> ParamType {
        match decl_type {
            DeclType::Scalar(ty) => ParamType::Scalar(*ty),
            DeclType::Struct(type_name) => ParamType::Struct(type_name.clone()),
            DeclType::Pointer { pointee, .. } => match pointee {
                PointeeType::Scalar(ty) => ParamType::Scalar(*ty),
                PointeeType::Struct(type_name) => ParamType::Struct(type_name.clone()),
            },
            DeclType::Array(pointee, _) => match pointee {
                PointeeType::Scalar(ty) => ParamType::Scalar(*ty),
                PointeeType::Struct(type_name) => ParamType::Struct(type_name.clone()),
            },
            DeclType::Array2D(ty, _, columns) => ParamType::Array2D(*ty, *columns),
            DeclType::Array2DPointer {
                elem_type, columns, ..
            } => ParamType::Array2D(*elem_type, *columns),
        }
    }

    fn decl_type_to_pointee_type(decl_type: &DeclType) -> PointeeType {
        match decl_type {
            DeclType::Scalar(ty) => PointeeType::Scalar(*ty),
            DeclType::Struct(type_name) => PointeeType::Struct(type_name.clone()),
            DeclType::Pointer { pointee, .. } => pointee.clone(),
            DeclType::Array(pointee, _) => pointee.clone(),
            DeclType::Array2D(_, _, _) | DeclType::Array2DPointer { .. } => {
                unreachable!("two-dimensional arrays do not decay to scalar pointers")
            }
        }
    }

    fn decl_type_points_to_const(decl_type: &DeclType) -> bool {
        match decl_type {
            DeclType::Pointer {
                points_to_const, ..
            }
            | DeclType::Array2DPointer {
                points_to_const, ..
            } => *points_to_const,
            _ => false,
        }
    }

    fn parse_typedef_decl(&mut self) -> CustResult<Option<Stmt>> {
        self.expect(Token::Typedef)?;
        self.pending_inline_enum_constants = None;
        let mut enum_constants = None;
        let base_start = self.pos;
        let inherited_base_qualified = match self.peek() {
            Token::Ident(name) => self.type_alias_is_qualified(name),
            _ => false,
        };
        let (base_type, alias_context, anonymous_aggregate, leading_const) = if self
            .starts_typedef_aggregate_definition()
        {
            let (type_name, _, is_anonymous) = self.parse_aggregate_definition_body(false, true)?;
            (
                DeclType::Struct(type_name),
                "typedef alias name after aggregate definition",
                is_anonymous,
                false,
            )
        } else if self.starts_typedef_enum_definition() {
            let constants = self.parse_enum_decl_body(false)?;
            enum_constants = Some(constants);
            (
                DeclType::Scalar(CType::Int),
                "typedef alias name after enum definition",
                false,
                false,
            )
        } else if self.check(&Token::Void) {
            return Err(Self::error_at(
                "void typedef aliases are not supported".to_string(),
                self.peek_located(),
            ));
        } else {
            let (leading_const, base_type) =
                self.parse_const_qualified_decl_type("typedef alias type")?;
            (
                base_type,
                "typedef alias name after type",
                false,
                leading_const,
            )
        };
        let base_is_qualified = inherited_base_qualified
            || self.tokens[base_start..self.pos].iter().any(|token| {
                matches!(
                    token.kind,
                    Token::Const | Token::Volatile | Token::Restrict | Token::Atomic
                )
            });

        loop {
            let (alias_name, alias, alias_is_const, alias_is_qualified) = self
                .parse_typedef_declarator(
                    base_type.clone(),
                    leading_const,
                    base_is_qualified,
                    alias_context,
                )?;
            self.register_typedef_alias(
                alias_name,
                alias,
                alias_is_const,
                alias_is_qualified,
                anonymous_aggregate,
            )?;
            if !self.matches(&Token::Comma) {
                break;
            }
        }
        self.expect_semicolon_after("typedef declaration")?;
        let mut stmts = Vec::new();
        if let Some(constants) = enum_constants {
            stmts.push(Stmt::EnumDecl { constants });
        }
        if let Some(stmt) = self.take_pending_inline_enum_decl() {
            stmts.push(stmt);
        }
        Ok(match stmts.len() {
            0 => None,
            1 => stmts.pop(),
            _ => Some(Stmt::Many(stmts)),
        })
    }

    fn parse_typedef_declarator(
        &mut self,
        base_type: DeclType,
        leading_const: bool,
        base_is_qualified: bool,
        alias_context: &str,
    ) -> CustResult<(String, TypeAlias, bool, bool)> {
        if self.check(&Token::LParen) && matches!(self.peek_next(), Token::Star) {
            if self.parenthesized_pointer_declarator_is_function_at(self.pos) {
                return Err(Self::error_at(
                    "function pointer typedef aliases are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            if let DeclType::Scalar(elem_type) = base_type {
                self.expect(Token::LParen)?;
                self.expect(Token::Star)?;
                let post_star_qualified = self.leading_type_qualifier_token().is_some();
                let post_star_const = self.consume_type_qualifiers();
                let alias_name = self.parse_declarator_name(alias_context)?;
                self.expect_closing_paren_after("pointer-to-row typedef declarator")?;
                self.expect(Token::LBracket)?;
                let columns = self.expect_array_len()?;
                self.expect_closing_bracket_after("pointer-to-row typedef width")?;
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        "pointer-to-row typedef aliases with more than two dimensions are not supported"
                            .to_string(),
                        self.peek_located(),
                    ));
                }
                return Ok((
                    alias_name,
                    TypeAlias::Array2DPointer {
                        elem_type,
                        columns,
                        points_to_const: leading_const,
                    },
                    post_star_const,
                    post_star_qualified,
                ));
            }
            return Err(Self::error_at(
                "parenthesized pointer typedef aliases are not supported".to_string(),
                self.peek_located(),
            ));
        }
        let explicit_star_token = if self.matches(&Token::Star) {
            Some(self.previous().clone())
        } else {
            None
        };
        let has_explicit_star = explicit_star_token.is_some();
        if matches!(
            base_type,
            DeclType::Pointer { .. } | DeclType::Array2DPointer { .. }
        ) && has_explicit_star
        {
            return Err(Self::error_at(
                "pointer-to-pointer typedef aliases are not supported".to_string(),
                self.previous(),
            ));
        }
        if has_explicit_star && self.check(&Token::Star) {
            return Err(Self::error_at(
                "pointer-to-pointer typedef aliases are not supported".to_string(),
                self.peek_located(),
            ));
        }
        let post_star_qualified =
            has_explicit_star && self.leading_type_qualifier_token().is_some();
        let post_star_const = has_explicit_star && self.consume_type_qualifiers();
        let alias_name = self.parse_declarator_name(alias_context)?;
        let mut alias = if has_explicit_star {
            match base_type {
                DeclType::Scalar(ty) => TypeAlias::Pointer {
                    pointee: PointeeType::Scalar(ty),
                    points_to_const: leading_const,
                },
                DeclType::Struct(type_name) => TypeAlias::Pointer {
                    pointee: PointeeType::Struct(type_name),
                    points_to_const: leading_const,
                },
                DeclType::Pointer { .. } | DeclType::Array2DPointer { .. } => {
                    unreachable!("pointer aliases with stars return above")
                }
                DeclType::Array(_, _) | DeclType::Array2D(_, _, _) => {
                    return Err(Self::error_at(
                        "pointer-to-array typedef aliases are not supported".to_string(),
                        explicit_star_token
                            .as_ref()
                            .expect("explicit star exists in pointer typedef branch"),
                    ));
                }
            }
        } else {
            match base_type {
                DeclType::Scalar(ty) => TypeAlias::Scalar(ty),
                DeclType::Struct(type_name) => TypeAlias::Struct(type_name),
                DeclType::Pointer {
                    pointee,
                    points_to_const,
                } => TypeAlias::Pointer {
                    pointee,
                    points_to_const,
                },
                DeclType::Array(pointee, len) => TypeAlias::Array(pointee, len),
                DeclType::Array2D(ty, rows, columns) => TypeAlias::Array2D(ty, rows, columns),
                DeclType::Array2DPointer {
                    elem_type,
                    columns,
                    points_to_const,
                } => TypeAlias::Array2DPointer {
                    elem_type,
                    columns,
                    points_to_const,
                },
            }
        };
        let alias_is_const = if has_explicit_star {
            post_star_const
        } else {
            leading_const
        };

        if self.matches(&Token::LBracket) {
            let len = self.expect_array_len()?;
            self.expect_closing_bracket_after("typedef array length")?;
            alias = match alias {
                TypeAlias::Scalar(ty) if self.matches(&Token::LBracket) => {
                    let columns = self.expect_array_len()?;
                    self.expect_closing_bracket_after("second typedef array dimension")?;
                    if self.check(&Token::LBracket) {
                        return Err(Self::error_at(
                            "array typedef aliases with more than two dimensions are not supported"
                                .to_string(),
                            self.peek_located(),
                        ));
                    }
                    TypeAlias::Array2D(ty, len, columns)
                }
                TypeAlias::Scalar(ty) => TypeAlias::Array(PointeeType::Scalar(ty), len),
                TypeAlias::Struct(type_name) => {
                    if self.check(&Token::LBracket) {
                        return Err(Self::error_at(
                            "multidimensional aggregate array typedef aliases are not supported"
                                .to_string(),
                            self.peek_located(),
                        ));
                    }
                    TypeAlias::Array(PointeeType::Struct(type_name), len)
                }
                TypeAlias::Pointer { .. } | TypeAlias::Array2DPointer { .. } => {
                    return Err(Self::error_at(
                        "pointer array typedef aliases are not supported".to_string(),
                        self.previous(),
                    ));
                }
                TypeAlias::Array(_, _) => {
                    return Err(Self::error_at(
                        "multidimensional array typedef aliases are not supported".to_string(),
                        self.previous(),
                    ));
                }
                TypeAlias::Array2D(_, _, _) => {
                    return Err(Self::error_at(
                        "array typedef aliases with more than two dimensions are not supported"
                            .to_string(),
                        self.previous(),
                    ));
                }
            };
        }
        if self.check(&Token::LParen) {
            return Err(Self::error_at(
                "function typedef aliases are not supported".to_string(),
                self.peek_located(),
            ));
        }
        let alias_is_qualified = if has_explicit_star {
            post_star_qualified
        } else {
            base_is_qualified
        };
        Ok((alias_name, alias, alias_is_const, alias_is_qualified))
    }

    fn register_typedef_alias(
        &mut self,
        alias_name: String,
        alias: TypeAlias,
        alias_is_const: bool,
        alias_is_qualified: bool,
        anonymous_aggregate: bool,
    ) -> CustResult<()> {
        let anonymous_type_name = match (anonymous_aggregate, &alias) {
            (true, TypeAlias::Struct(type_name)) => Some(type_name.clone()),
            _ => None,
        };
        if let Some(struct_type) = anonymous_type_name
            .as_ref()
            .and_then(|type_name| self.struct_types.get_mut(type_name))
        {
            struct_type.display_name = alias_name.clone();
        }
        let current_scope = self
            .type_alias_scopes
            .last_mut()
            .expect("parser always has a typedef scope");
        if current_scope.insert(alias_name.clone(), alias).is_some() {
            return Err(CustError::new(format!(
                "typedef alias '{alias_name}' already declared"
            )));
        }
        if alias_is_const {
            let const_scope = self
                .const_type_alias_scopes
                .last_mut()
                .expect("parser always has a const typedef scope");
            const_scope.insert(alias_name.clone());
        }
        if alias_is_qualified {
            let qualified_scope = self
                .qualified_type_alias_scopes
                .last_mut()
                .expect("parser always has a qualified typedef scope");
            qualified_scope.insert(alias_name);
        }
        Ok(())
    }

    fn starts_function_definition(&self) -> bool {
        let mut index = self.skip_type_qualifiers_at(self.pos);
        match self.tokens.get(index).map(|token| &token.kind) {
            Some(Token::Void) => {
                index += 1;
                index = self.skip_type_qualifiers_at(index);
            }
            Some(token) if Self::scalar_type_specifier_token(token) => {
                let Some(next_index) = self.skip_scalar_type_specifiers_at(index) else {
                    return false;
                };
                index = next_index;
            }
            Some(Token::Enum) => {
                let Some(next_index) = self.skip_enum_type_specifier_at(index) else {
                    return false;
                };
                index = next_index;
                index = self.skip_type_qualifiers_at(index);
            }
            Some(Token::Struct | Token::Union) => {
                let Some(next_index) = self.skip_aggregate_type_specifier_at(index) else {
                    return false;
                };
                index = next_index;
                index = self.skip_type_qualifiers_at(index);
            }
            Some(Token::Atomic) => {
                let Some(next_index) = self.skip_atomic_type_specifier_at(index) else {
                    return false;
                };
                index = self.skip_type_qualifiers_at(next_index);
            }
            Some(Token::Ident(_)) if self.alias_at_index(index).is_some() => {
                index += 1;
                index = self.skip_type_qualifiers_at(index);
            }
            _ => return false,
        }
        while matches!(
            self.tokens.get(index).map(|token| &token.kind),
            Some(Token::Star)
        ) || self.type_qualifier_at(index)
        {
            index += 1;
        }

        if matches!(
            (
                self.tokens.get(index).map(|token| &token.kind),
                self.tokens.get(index + 1).map(|token| &token.kind)
            ),
            (Some(Token::Ident(_)), Some(Token::LParen))
        ) {
            return true;
        }

        if matches!(
            (
                self.tokens.get(index).map(|token| &token.kind),
                self.tokens.get(index + 1).map(|token| &token.kind),
                self.tokens.get(index + 2).map(|token| &token.kind),
                self.tokens.get(index + 3).map(|token| &token.kind)
            ),
            (
                Some(Token::LParen),
                Some(Token::Star),
                Some(Token::Ident(_)),
                Some(Token::LParen)
            )
        ) {
            return true;
        }

        matches!(
            (
                self.tokens.get(index).map(|token| &token.kind),
                self.tokens.get(index + 1).map(|token| &token.kind),
                self.tokens.get(index + 2).map(|token| &token.kind),
                self.tokens.get(index + 3).map(|token| &token.kind)
            ),
            (
                Some(Token::LParen),
                Some(Token::Ident(_)),
                Some(Token::RParen),
                Some(Token::LParen)
            )
        )
    }

    fn skip_type_qualifiers_at(&self, mut index: usize) -> usize {
        while self.type_qualifier_at(index) {
            index += 1;
        }
        index
    }

    fn skip_scalar_type_specifiers_at(&self, mut index: usize) -> Option<usize> {
        if !self
            .tokens
            .get(index)
            .is_some_and(|token| Self::scalar_type_specifier_token(&token.kind))
        {
            return None;
        }
        while self
            .tokens
            .get(index)
            .is_some_and(|token| Self::scalar_type_specifier_token(&token.kind))
        {
            index += 1;
            index = self.skip_type_qualifiers_at(index);
        }
        Some(index)
    }

    fn skip_enum_type_specifier_at(&self, index: usize) -> Option<usize> {
        if !matches!(
            self.tokens.get(index).map(|token| &token.kind),
            Some(Token::Enum)
        ) {
            return None;
        }

        let mut cursor = index + 1;
        if matches!(
            self.tokens.get(cursor).map(|token| &token.kind),
            Some(Token::Ident(_))
        ) {
            cursor += 1;
        }

        if matches!(
            self.tokens.get(cursor).map(|token| &token.kind),
            Some(Token::LBrace)
        ) {
            let mut depth = 0usize;
            while let Some(token) = self.tokens.get(cursor) {
                match &token.kind {
                    Token::LBrace => depth += 1,
                    Token::RBrace => {
                        depth -= 1;
                        if depth == 0 {
                            return Some(cursor + 1);
                        }
                    }
                    Token::Eof => return None,
                    _ => {}
                }
                cursor += 1;
            }
            None
        } else if cursor > index + 1 {
            Some(cursor)
        } else {
            None
        }
    }

    fn skip_aggregate_type_specifier_at(&self, index: usize) -> Option<usize> {
        if !matches!(
            self.tokens.get(index).map(|token| &token.kind),
            Some(Token::Struct | Token::Union)
        ) {
            return None;
        }

        let mut cursor = index + 1;
        if !matches!(
            self.tokens.get(cursor).map(|token| &token.kind),
            Some(Token::Ident(_))
        ) {
            return None;
        }
        cursor += 1;

        if matches!(
            self.tokens.get(cursor).map(|token| &token.kind),
            Some(Token::LBrace)
        ) {
            let mut depth = 0usize;
            while let Some(token) = self.tokens.get(cursor) {
                match &token.kind {
                    Token::LBrace => depth += 1,
                    Token::RBrace => {
                        depth -= 1;
                        if depth == 0 {
                            return Some(cursor + 1);
                        }
                    }
                    Token::Eof => return None,
                    _ => {}
                }
                cursor += 1;
            }
            None
        } else {
            Some(cursor)
        }
    }

    fn type_qualifier_at(&self, index: usize) -> bool {
        matches!(
            self.tokens.get(index).map(|token| &token.kind),
            Some(Token::Const | Token::Volatile | Token::Restrict)
        ) || self.bare_atomic_qualifier_at(index)
    }

    fn skip_atomic_type_specifier_at(&self, index: usize) -> Option<usize> {
        if !matches!(
            self.tokens.get(index).map(|token| &token.kind),
            Some(Token::Atomic)
        ) || !matches!(
            self.tokens.get(index + 1).map(|token| &token.kind),
            Some(Token::LParen)
        ) {
            return None;
        }

        let mut depth = 1;
        let mut cursor = index + 2;
        while let Some(token) = self.tokens.get(cursor) {
            match &token.kind {
                Token::LParen => depth += 1,
                Token::RParen => {
                    depth -= 1;
                    if depth == 0 {
                        return Some(cursor + 1);
                    }
                }
                Token::Eof => return None,
                _ => {}
            }
            cursor += 1;
        }
        None
    }

    fn parenthesized_pointer_declarator_is_function_at(&self, index: usize) -> bool {
        if !matches!(
            (
                self.tokens.get(index).map(|token| &token.kind),
                self.tokens.get(index + 1).map(|token| &token.kind)
            ),
            (Some(Token::LParen), Some(Token::Star))
        ) {
            return false;
        }

        let mut cursor = self.skip_type_qualifiers_at(index + 2);
        if !matches!(
            self.tokens.get(cursor).map(|token| &token.kind),
            Some(Token::Ident(_))
        ) {
            return false;
        }
        cursor += 1;
        cursor = self.skip_type_qualifiers_at(cursor);

        matches!(
            (
                self.tokens.get(cursor).map(|token| &token.kind),
                self.tokens.get(cursor + 1).map(|token| &token.kind)
            ),
            (Some(Token::RParen), Some(Token::LParen))
        )
    }

    fn starts_malformed_function_definition(&self) -> bool {
        let type_start = self.skip_type_qualifiers_at(self.pos);
        if let Some(mut index) = self
            .skip_scalar_type_specifiers_at(type_start)
            .filter(|index| {
                matches!(
                    (
                        self.tokens.get(*index).map(|token| &token.kind),
                        self.tokens.get(*index + 1).map(|token| &token.kind)
                    ),
                    (Some(Token::LParen), Some(Token::Star))
                )
            })
        {
            index = self.skip_type_qualifiers_at(index + 2);
            if matches!(
                (
                    self.tokens.get(index).map(|token| &token.kind),
                    self.tokens.get(index + 1).map(|token| &token.kind),
                    self.tokens.get(index + 2).map(|token| &token.kind)
                ),
                (
                    Some(Token::Ident(_)),
                    Some(Token::RParen),
                    Some(Token::LBracket)
                )
            ) {
                return false;
            }
        }
        if !matches!(
            self.peek(),
            Token::Int
                | Token::Char
                | Token::Bool
                | Token::Signed
                | Token::Unsigned
                | Token::Long
                | Token::Short
        ) {
            return false;
        }

        matches!(
            (
                self.tokens.get(self.pos + 1).map(|token| &token.kind),
                self.tokens.get(self.pos + 2).map(|token| &token.kind)
            ),
            (Some(Token::LParen), _) | (Some(Token::Ident(_)), Some(Token::LBrace))
        )
    }

    fn parse_function_declaration(
        &mut self,
    ) -> CustResult<(String, TopLevelFunction, Option<Stmt>)> {
        self.pending_inline_enum_constants = None;
        let (mut return_type, leading_return_const) = self.parse_function_return_type()?;
        let inline_return_enum_decl = self.take_pending_inline_enum_decl();
        let row_pointer_return = self.check(&Token::LParen)
            && matches!(self.peek_next(), Token::Star)
            && matches!(
                self.tokens.get(self.pos + 2).map(|token| &token.kind),
                Some(Token::Ident(_))
            )
            && matches!(
                self.tokens.get(self.pos + 3).map(|token| &token.kind),
                Some(Token::LParen)
            );
        let name = if row_pointer_return {
            self.advance();
            self.advance();
            let name = self.expect_ident_after("row-pointer function name after '*'")?;
            self.expect_opening_paren_after("row-pointer function name")?;
            name
        } else {
            if self.check(&Token::LParen) && matches!(self.peek_next(), Token::Star) {
                return Err(Self::error_at(
                    "function pointer declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let name = self.parse_function_declarator_name()?;
            self.expect_opening_paren_after("function name")?;
            name
        };
        let allow_unnamed_params = self.parameter_list_is_prototype();
        self.aggregate_type_scopes.push(HashMap::new());
        let parsed = (|| {
            let params = self.parse_params(allow_unnamed_params)?;
            let inline_param_enum_decl = self.take_pending_inline_enum_decl();
            self.expect_closing_paren_after("function parameters")?;
            if row_pointer_return {
                self.expect_closing_paren_after("row-pointer function declarator")?;
                self.expect(Token::LBracket)?;
                let columns = self.expect_array_len()?;
                self.expect_closing_bracket_after("row-pointer function return type")?;
                let ReturnType::Scalar(elem_type) = return_type else {
                    return Err(Self::error_at(
                        "row-pointer function returns require a scalar element type".to_string(),
                        self.previous(),
                    ));
                };
                return_type = ReturnType::Array2DPointer {
                    elem_type,
                    columns,
                    points_to_const: leading_return_const,
                };
            } else if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "array return types are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            if self.matches(&Token::Semi) {
                return Ok((
                    name,
                    TopLevelFunction::Prototype(FunctionSignature::new(return_type, &params)),
                    inline_return_enum_decl,
                ));
            }
            let previous_parsing_function_body = self.parsing_function_body;
            self.parsing_function_body = true;
            let body_result = self.parse_block_after("function header");
            self.parsing_function_body = previous_parsing_function_body;
            let mut body = body_result?;
            if let Some(stmt) = inline_param_enum_decl {
                body.insert(0, stmt);
            }
            Ok((
                name,
                TopLevelFunction::Definition(Function {
                    return_type,
                    params,
                    body,
                }),
                inline_return_enum_decl,
            ))
        })();
        self.aggregate_type_scopes.pop();
        parsed
    }

    fn parse_function_declarator_name(&mut self) -> CustResult<String> {
        if self.check(&Token::LParen) && matches!(self.peek_next(), Token::Ident(_)) {
            self.advance();
            let name = self.expect_ident_after("function name after return type")?;
            self.expect_closing_paren_after("parenthesized function name")?;
            return Ok(name);
        }

        self.expect_ident_after("function name after return type")
    }

    fn parse_declarator_name(&mut self, context: &str) -> CustResult<String> {
        if self.check(&Token::LParen) && matches!(self.peek_next(), Token::Ident(_)) {
            self.advance();
            let name = self.expect_ident_after(context)?;
            self.expect_closing_paren_after("parenthesized declarator name")?;
            return Ok(name);
        }

        self.expect_ident_after(context)
    }

    fn parameter_list_is_prototype(&self) -> bool {
        let mut cursor = self.pos;
        let mut depth = 0usize;
        while let Some(token) = self.tokens.get(cursor) {
            match token.kind {
                Token::LParen => {
                    depth += 1;
                    cursor += 1;
                }
                Token::RParen if depth > 0 => {
                    depth -= 1;
                    cursor += 1;
                }
                Token::RParen => {
                    if matches!(
                        self.tokens.get(cursor + 1).map(|next| &next.kind),
                        Some(Token::Semi)
                    ) {
                        return true;
                    }
                    if matches!(
                        (
                            self.tokens.get(cursor + 1).map(|next| &next.kind),
                            self.tokens.get(cursor + 2).map(|next| &next.kind)
                        ),
                        (Some(Token::RParen), Some(Token::LBracket))
                    ) {
                        let mut suffix = cursor + 3;
                        while let Some(token) = self.tokens.get(suffix) {
                            match token.kind {
                                Token::RBracket => {
                                    return matches!(
                                        self.tokens.get(suffix + 1).map(|next| &next.kind),
                                        Some(Token::Semi)
                                    );
                                }
                                Token::Eof => return false,
                                _ => suffix += 1,
                            }
                        }
                    }
                    return false;
                }
                Token::Eof => return false,
                _ => cursor += 1,
            }
        }
        false
    }

    fn parse_function_return_type(&mut self) -> CustResult<(ReturnType, bool)> {
        if self.check(&Token::Void) {
            if let Some(token) = self.void_pointer_star_token_at_current() {
                return Err(Self::error_at(
                    "void pointers are not supported".to_string(),
                    token,
                ));
            }
            self.advance();
            return Ok((ReturnType::Void, false));
        }
        let (leading_const, decl_type) =
            self.parse_const_qualified_decl_type("function return type")?;
        if self.matches(&Token::Star) {
            if matches!(decl_type, DeclType::Pointer { .. }) || self.check(&Token::Star) {
                return Err(Self::error_at(
                    "pointer-to-pointer return types are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            self.consume_type_qualifiers();
            return Ok((
                ReturnType::Pointer {
                    ty: Self::decl_type_to_pointee_type(&decl_type),
                    points_to_const: leading_const,
                },
                false,
            ));
        }
        if let DeclType::Pointer {
            pointee,
            points_to_const,
        } = decl_type
        {
            return Ok((
                ReturnType::Pointer {
                    ty: pointee,
                    points_to_const: leading_const || points_to_const,
                },
                false,
            ));
        }
        if matches!(decl_type, DeclType::Array(_, _)) {
            return Err(Self::error_at(
                "array return types are not supported".to_string(),
                self.previous(),
            ));
        }
        Ok((Self::decl_type_to_return_type(decl_type), leading_const))
    }

    fn anonymous_aggregate_parameter_token(&self) -> Option<&LocatedToken> {
        let index = self.skip_type_qualifiers_at(self.pos);
        if matches!(
            self.tokens.get(index).map(|token| &token.kind),
            Some(Token::Struct | Token::Union)
        ) && matches!(
            self.tokens.get(index + 1).map(|token| &token.kind),
            Some(Token::LBrace)
        ) {
            return self.tokens.get(index);
        }
        None
    }

    fn old_style_parameter_token(&self) -> Option<&LocatedToken> {
        let Token::Ident(name) = self.peek() else {
            return None;
        };
        if self.lookup_type_alias(name).is_some() {
            return None;
        }
        if !matches!(self.peek_next(), Token::Comma | Token::RParen) {
            return None;
        }
        let closing_paren = (self.pos..self.tokens.len())
            .find(|&index| matches!(self.tokens[index].kind, Token::RParen))?;
        let after_params = self.tokens.get(closing_paren + 1).map(|token| &token.kind);
        if matches!(
            after_params,
            Some(
                Token::Int
                    | Token::Char
                    | Token::Bool
                    | Token::Signed
                    | Token::Unsigned
                    | Token::Long
                    | Token::Short
                    | Token::Const
                    | Token::Volatile
                    | Token::Atomic
                    | Token::Static
                    | Token::Extern
                    | Token::Auto
                    | Token::Register
                    | Token::Struct
                    | Token::Union
                    | Token::Enum
            )
        ) {
            return Some(self.peek_located());
        }
        None
    }

    fn parse_params(&mut self, allow_unnamed: bool) -> CustResult<Vec<Param>> {
        let mut params = Vec::new();
        if self.check(&Token::RParen) {
            return Ok(params);
        }
        if self.check(&Token::Void) {
            if let Some(token) = self.void_pointer_star_token_at_current() {
                return Err(Self::error_at(
                    "void pointers are not supported".to_string(),
                    token,
                ));
            }
            let void_token = self.advance();
            if self.check(&Token::RParen) {
                return Ok(params);
            }
            return Err(Self::error_at(
                "void parameter lists must be empty".to_string(),
                &void_token,
            ));
        }
        if self.starts_ellipsis() {
            return Err(Self::error_at(
                "variadic function parameters are not supported".to_string(),
                self.peek_located(),
            ));
        }
        if matches!(
            self.peek(),
            Token::Comma
                | Token::Semi
                | Token::Colon
                | Token::RBracket
                | Token::LBracket
                | Token::Question
                | Token::LBrace
                | Token::Dot
                | Token::Arrow
        ) {
            return Err(Self::error_at(
                format!("expected function parameter, found {:?}", self.peek()),
                self.peek_located(),
            ));
        }
        if let (Some(label), false) = (
            self.integer_constant_invalid_start_label(),
            self.is_type_name_start(),
        ) {
            return Err(Self::error_at(
                format!("expected function parameter before '{label}'"),
                self.peek_located(),
            ));
        }

        loop {
            if self.starts_ellipsis() {
                return Err(Self::error_at(
                    "variadic function parameters are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            if let Some(token) = self.anonymous_aggregate_parameter_token() {
                return Err(Self::error_at(
                    "anonymous aggregate parameters are not supported".to_string(),
                    token,
                ));
            }
            if let Some(token) = self.old_style_parameter_token() {
                return Err(Self::error_at(
                    "old-style function parameter lists are not supported".to_string(),
                    token,
                ));
            }
            let (leading_const, decl_type) =
                self.parse_const_qualified_decl_type("parameter type")?;
            let mut array_2d_param_type = match &decl_type {
                DeclType::Array2D(ty, _, columns) => Some((*ty, *columns)),
                DeclType::Array2DPointer {
                    elem_type, columns, ..
                } => Some((*elem_type, *columns)),
                _ => None,
            };
            let row_pointer_alias_points_to_const = match &decl_type {
                DeclType::Array2DPointer {
                    points_to_const, ..
                } => Some(*points_to_const),
                _ => None,
            };
            let mut explicit_row_pointer_param = None;
            if matches!(decl_type, DeclType::Scalar(_))
                && self.check(&Token::LParen)
                && matches!(self.peek_next(), Token::Star)
                && !self.parenthesized_pointer_declarator_is_function_at(self.pos)
            {
                let DeclType::Scalar(elem_type) = &decl_type else {
                    unreachable!("guard requires scalar row pointer parameter type")
                };
                self.expect(Token::LParen)?;
                self.expect(Token::Star)?;
                let pointer_is_const = self.consume_type_qualifiers();
                let name = if allow_unnamed && self.check(&Token::RParen) {
                    format!("__cust_prototype_param_{}", params.len())
                } else {
                    self.parse_declarator_name("row pointer parameter name after '*'")?
                };
                self.expect_closing_paren_after("two-dimensional row pointer parameter")?;
                self.expect(Token::LBracket)?;
                let columns = self.expect_array_len()?;
                self.expect_closing_bracket_after("two-dimensional row pointer parameter width")?;
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        "row pointer parameters with more than two dimensions are not supported"
                            .to_string(),
                        self.peek_located(),
                    ));
                }
                array_2d_param_type = Some((*elem_type, columns));
                explicit_row_pointer_param = Some((name, pointer_is_const));
            }
            let has_explicit_star = self.matches(&Token::Star);
            let post_star_const = has_explicit_star && self.consume_type_qualifiers();
            if matches!(decl_type, DeclType::Pointer { .. }) && has_explicit_star {
                return Err(Self::error_at(
                    "pointer-to-pointer parameters are not supported".to_string(),
                    self.previous(),
                ));
            }
            if matches!(
                decl_type,
                DeclType::Array(_, _) | DeclType::Array2D(_, _, _)
            ) && has_explicit_star
            {
                return Err(Self::error_at(
                    "pointer-to-array parameters are not supported".to_string(),
                    self.previous(),
                ));
            }
            if has_explicit_star && self.check(&Token::Star) {
                return Err(Self::error_at(
                    "pointer-to-pointer parameters are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            if !has_explicit_star
                && self.check(&Token::LParen)
                && matches!(self.peek_next(), Token::Star)
            {
                if self.parenthesized_pointer_declarator_is_function_at(self.pos) {
                    return Err(Self::error_at(
                        "function pointer parameters are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                return Err(Self::error_at(
                    "parenthesized pointer parameters are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let is_pointer = has_explicit_star
                || matches!(
                    decl_type,
                    DeclType::Pointer { .. }
                        | DeclType::Array(_, _)
                        | DeclType::Array2DPointer { .. }
                );
            let name = if let Some((name, _)) = &explicit_row_pointer_param {
                name.clone()
            } else if allow_unnamed
                && matches!(self.peek(), Token::Comma | Token::RParen | Token::LBracket)
            {
                format!("__cust_prototype_param_{}", params.len())
            } else if has_explicit_star {
                match &decl_type {
                    DeclType::Scalar(_) => {
                        self.parse_declarator_name("parameter name after '*'")?
                    }
                    DeclType::Struct(_) => {
                        self.parse_declarator_name("struct pointer parameter name after '*'")?
                    }
                    DeclType::Pointer { .. } => {
                        unreachable!("pointer aliases with explicit stars return above")
                    }
                    DeclType::Array(_, _) => {
                        unreachable!("array aliases with explicit stars return above")
                    }
                    DeclType::Array2D(_, _, _) => {
                        unreachable!("two-dimensional array aliases return above")
                    }
                    DeclType::Array2DPointer { .. } => {
                        unreachable!("row pointer aliases with explicit stars return above")
                    }
                }
            } else {
                match &decl_type {
                    DeclType::Scalar(_) => {
                        self.parse_declarator_name("parameter name after type")?
                    }
                    DeclType::Struct(_) => {
                        self.parse_declarator_name("struct parameter name after type")?
                    }
                    DeclType::Pointer { .. } => {
                        self.parse_declarator_name("pointer parameter name after type")?
                    }
                    DeclType::Array(_, _) => {
                        self.parse_declarator_name("array parameter name after type")?
                    }
                    DeclType::Array2D(_, _, _) => self
                        .parse_declarator_name("two-dimensional array parameter name after type")?,
                    DeclType::Array2DPointer { .. } => {
                        self.parse_declarator_name("row pointer parameter name after type")?
                    }
                }
            };
            let mut array_parameter_const = false;
            let kind = if array_2d_param_type.is_some() {
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        "array parameters with more than two dimensions are not supported"
                            .to_string(),
                        self.peek_located(),
                    ));
                }
                ParamKind::Array2D
            } else if is_pointer {
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        "pointer array parameters are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                ParamKind::Pointer
            } else if matches!(decl_type, DeclType::Struct(_)) {
                if self.matches(&Token::LBracket) {
                    array_parameter_const = self.parse_array_parameter_length_and_qualifiers()?;
                    self.expect_closing_bracket_after("array parameter length")?;
                    if self.check(&Token::LBracket) {
                        return Err(Self::error_at(
                            "multidimensional array parameters are not supported".to_string(),
                            self.peek_located(),
                        ));
                    }
                    ParamKind::Pointer
                } else {
                    ParamKind::Struct
                }
            } else if self.matches(&Token::LBracket) {
                array_parameter_const = self.parse_array_parameter_length_and_qualifiers()?;
                self.expect_closing_bracket_after("array parameter length")?;
                if self.matches(&Token::LBracket) {
                    let columns = self.expect_array_len()?;
                    self.expect_closing_bracket_after("second array parameter length")?;
                    if self.check(&Token::LBracket) {
                        return Err(Self::error_at(
                            "array parameters with more than two dimensions are not supported"
                                .to_string(),
                            self.peek_located(),
                        ));
                    }
                    let DeclType::Scalar(ty) = &decl_type else {
                        unreachable!("scalar array parameters have scalar declaration types")
                    };
                    array_2d_param_type = Some((*ty, columns));
                    ParamKind::Array2D
                } else {
                    ParamKind::Pointer
                }
            } else {
                ParamKind::Scalar
            };
            let (is_const, points_to_const) = if matches!(kind, ParamKind::Pointer) {
                if has_explicit_star {
                    (post_star_const, leading_const)
                } else if matches!(decl_type, DeclType::Array(_, _)) {
                    (false, leading_const)
                } else if is_pointer {
                    (leading_const, Self::decl_type_points_to_const(&decl_type))
                } else {
                    (array_parameter_const, leading_const)
                }
            } else if matches!(kind, ParamKind::Array2D) {
                if let Some(points_to_const) = row_pointer_alias_points_to_const {
                    (leading_const, points_to_const)
                } else {
                    (
                        explicit_row_pointer_param
                            .as_ref()
                            .is_some_and(|(_, is_const)| *is_const),
                        leading_const,
                    )
                }
            } else {
                (leading_const, false)
            };
            let param_type = array_2d_param_type
                .map(|(ty, columns)| ParamType::Array2D(ty, columns))
                .unwrap_or_else(|| Self::decl_type_to_param_type(&decl_type));
            params.push(Param {
                ty: param_type,
                name,
                kind,
                is_const,
                points_to_const,
            });

            if self.matches(&Token::Comma) {
                if self.starts_ellipsis() {
                    return Err(Self::error_at(
                        "variadic function parameters are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                if matches!(
                    self.peek(),
                    Token::Comma
                        | Token::RParen
                        | Token::RBracket
                        | Token::LBracket
                        | Token::Question
                        | Token::Semi
                        | Token::Colon
                        | Token::LBrace
                        | Token::RBrace
                        | Token::Dot
                        | Token::Arrow
                        | Token::Eof
                ) {
                    return Err(Self::error_at(
                        format!(
                            "expected function parameter after ',', found {:?}",
                            self.peek()
                        ),
                        self.peek_located(),
                    ));
                }
                if let (Some(label), false) = (
                    self.integer_constant_invalid_start_label(),
                    self.is_type_name_start(),
                ) {
                    return Err(Self::error_at(
                        format!("expected function parameter after ',' before '{label}'"),
                        self.peek_located(),
                    ));
                }
            } else if matches!(
                self.peek(),
                Token::RParen | Token::Semi | Token::LBrace | Token::RBrace | Token::Eof
            ) {
                break;
            } else {
                return Err(Self::error_at(
                    format!(
                        "expected ',' or ')' after function parameter, found {:?}",
                        self.peek()
                    ),
                    self.peek_located(),
                ));
            }
        }
        Ok(params)
    }

    fn starts_ellipsis(&self) -> bool {
        matches!(
            (
                self.peek(),
                self.tokens.get(self.pos + 1).map(|token| &token.kind),
                self.tokens.get(self.pos + 2).map(|token| &token.kind)
            ),
            (Token::Dot, Some(Token::Dot), Some(Token::Dot))
        )
    }

    fn reject_array_range_designator(&self) -> CustResult<()> {
        if self.starts_ellipsis() {
            return Err(Self::error_at(
                "array range designators are not supported".to_string(),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn void_pointer_star_token_at_current(&self) -> Option<&LocatedToken> {
        if matches!(self.peek(), Token::Void)
            && matches!(
                self.tokens.get(self.pos + 1).map(|token| &token.kind),
                Some(Token::Star)
            )
        {
            return self.tokens.get(self.pos + 1);
        }
        None
    }

    fn parenthesized_pointer_star_token_at_current(&self) -> Option<&LocatedToken> {
        if matches!(self.peek(), Token::LParen)
            && matches!(
                self.tokens.get(self.pos + 1).map(|token| &token.kind),
                Some(Token::Star)
            )
        {
            return self.tokens.get(self.pos + 1);
        }
        None
    }

    fn parse_array_parameter_length_and_qualifiers(&mut self) -> CustResult<bool> {
        let mut pointer_slot_const = false;
        loop {
            if self.matches(&Token::Const) {
                pointer_slot_const = true;
            } else if matches!(
                self.peek(),
                Token::Volatile | Token::Restrict | Token::Atomic | Token::Static
            ) {
                self.advance();
            } else {
                break;
            }
        }

        if !self.check(&Token::RBracket) {
            self.expect_array_len()?;
            loop {
                if self.matches(&Token::Const) {
                    pointer_slot_const = true;
                } else if matches!(
                    self.peek(),
                    Token::Volatile | Token::Restrict | Token::Atomic
                ) {
                    self.advance();
                } else {
                    break;
                }
            }
        }

        Ok(pointer_slot_const)
    }

    fn parse_block_after(&mut self, context: &str) -> CustResult<Vec<Stmt>> {
        self.expect_opening_brace_after(context)?;
        self.type_alias_scopes.push(HashMap::new());
        self.const_type_alias_scopes.push(HashSet::new());
        self.qualified_type_alias_scopes.push(HashSet::new());
        self.enum_type_scopes.push(HashSet::new());
        self.enum_constant_scopes.push(HashMap::new());
        self.aggregate_type_scopes.push(HashMap::new());
        let mut statements = Vec::new();
        let result = (|| {
            while !self.check(&Token::RBrace) {
                if self.check(&Token::Eof) {
                    let eof = self.peek_located().clone();
                    return Err(Self::error_at(
                        format!("unterminated block after {context}"),
                        &eof,
                    ));
                }
                statements.push(self.parse_stmt()?);
            }
            self.expect(Token::RBrace)?;
            Ok(statements)
        })();
        self.aggregate_type_scopes.pop();
        self.enum_constant_scopes.pop();
        self.enum_type_scopes.pop();
        self.qualified_type_alias_scopes.pop();
        self.const_type_alias_scopes.pop();
        self.type_alias_scopes.pop();
        result
    }

    fn parse_control_body_after(&mut self, context: &str) -> CustResult<Vec<Stmt>> {
        if self.check(&Token::LBrace) {
            Ok(vec![Stmt::Block(self.parse_block_after(context)?)])
        } else {
            Ok(vec![self.parse_stmt()?])
        }
    }

    fn parse_stmt(&mut self) -> CustResult<Stmt> {
        if let Some(token) = self.anonymous_aggregate_return_type_token() {
            return Err(Self::error_at(
                "anonymous aggregate return types are not supported".to_string(),
                token,
            ));
        }
        if let Some(token) = self.void_pointer_star_token_at_current() {
            return Err(Self::error_at(
                "void pointers are not supported".to_string(),
                token,
            ));
        }
        if self.check(&Token::Void) && !self.starts_function_definition() {
            return Err(Self::error_at(
                "void object declarations are not supported".to_string(),
                self.peek_located(),
            ));
        }
        if self.starts_local_function_declaration() {
            return self.parse_local_function_prototype_decl();
        }
        if self.starts_qualified_aggregate_declaration() {
            return self.parse_aggregate_var_decl();
        }
        match self.peek() {
            Token::Semi => self.parse_empty(),
            Token::Static => self.parse_static_local_decl(),
            Token::ThreadLocal => self.parse_thread_local_local_decl(),
            Token::Extern => self.parse_extern_local_decl(),
            Token::Auto | Token::Register => self.parse_auto_register_local_decl(),
            Token::Alignas => self.parse_aligned_decl(),
            Token::Int
            | Token::Char
            | Token::Bool
            | Token::Float
            | Token::Double
            | Token::Complex
            | Token::Imaginary
            | Token::Signed
            | Token::Unsigned
            | Token::Long
            | Token::Short
            | Token::Const
            | Token::Volatile
            | Token::Restrict
            | Token::Atomic => self.parse_var_decl(),
            Token::Ident(_) if self.current_alias().is_some() => self.parse_var_decl(),
            Token::Typedef => match self.parse_typedef_decl()? {
                Some(stmt) => Ok(stmt),
                None => Ok(Stmt::Empty),
            },
            Token::Enum => {
                if self.starts_typedef_enum_definition()
                    && self.enum_definition_followed_by_semicolon()
                {
                    self.parse_enum_decl()
                } else {
                    self.parse_var_decl()
                }
            }
            Token::Struct | Token::Union => {
                if self.is_aggregate_definition() {
                    Ok(self.parse_aggregate_definition()?.unwrap_or(Stmt::Empty))
                } else if self.is_aggregate_forward_declaration() {
                    let keyword = match self.peek() {
                        Token::Struct => "struct",
                        Token::Union => "union",
                        _ => unreachable!("checked aggregate keyword above"),
                    };
                    Err(Self::error_at(
                        format!("forward {keyword} declarations are not supported"),
                        self.tokens
                            .get(self.pos + 2)
                            .expect("forward aggregate declaration has a semicolon"),
                    ))
                } else {
                    self.parse_aggregate_var_decl()
                }
            }
            Token::Return => self.parse_return(),
            Token::LBrace => Ok(Stmt::Block(self.parse_block_after("block statement")?)),
            Token::If => self.parse_if(),
            Token::While => self.parse_while(),
            Token::Do => self.parse_do_while(),
            Token::For => self.parse_for(),
            Token::Switch => self.parse_switch(),
            Token::Break => self.parse_break(),
            Token::Continue => self.parse_continue(),
            Token::Else => Err(Self::error_at(
                "else without matching if".to_string(),
                self.peek_located(),
            )),
            Token::Goto => Err(Self::error_at(
                "goto statements are not supported".to_string(),
                self.peek_located(),
            )),
            Token::StaticAssert => self.parse_static_assert(),
            Token::Case => Err(Self::error_at(
                "case label outside switch".to_string(),
                self.peek_located(),
            )),
            Token::Default => Err(Self::error_at(
                "default label outside switch".to_string(),
                self.peek_located(),
            )),
            Token::Star
                if self.starts_deref_assignment_stmt()
                    || self.starts_missing_deref_assignment_operator_stmt() =>
            {
                self.parse_deref_assign()
            }
            Token::Ident(_) if matches!(self.peek_next(), Token::Colon) => Err(Self::error_at(
                "labels are not supported".to_string(),
                self.peek_located(),
            )),
            Token::Ident(_)
                if self.starts_assignment_stmt()
                    || self.starts_missing_assignment_operator_stmt() =>
            {
                self.parse_assign()
            }
            Token::Ident(_)
            | Token::Number(_)
            | Token::PreprocessorNumber(_)
            | Token::StringLiteral(_)
            | Token::Plus
            | Token::Minus
            | Token::PlusPlus
            | Token::MinusMinus
            | Token::Bang
            | Token::Sizeof
            | Token::Alignof
            | Token::Star
            | Token::Amp
            | Token::LParen => self.parse_expr_stmt_with_semi(true),
            Token::Comma
            | Token::Colon
            | Token::Dot
            | Token::Arrow
            | Token::LBracket
            | Token::Question => Err(Self::error_at(
                format!("expected expression statement, found {:?}", self.peek()),
                self.peek_located(),
            )),
            Token::RParen => Err(Self::error_at(
                "unmatched ')' in statement".to_string(),
                self.peek_located(),
            )),
            Token::RBracket => Err(Self::error_at(
                "unmatched ']' in statement".to_string(),
                self.peek_located(),
            )),
            token => Err(Self::error_at(
                format!("unexpected token in statement: {token:?}"),
                self.peek_located(),
            )),
        }
    }

    fn parse_empty(&mut self) -> CustResult<Stmt> {
        self.expect(Token::Semi)?;
        Ok(Stmt::Empty)
    }

    fn starts_local_function_declaration(&self) -> bool {
        self.starts_function_definition()
            || self.starts_struct_function_declaration()
            || self.starts_alias_function_declaration()
            || self.check(&Token::Void)
    }

    fn parse_local_function_prototype_decl(&mut self) -> CustResult<Stmt> {
        let declaration_start = self.peek_located().clone();
        let (_, declaration, _) = self.parse_function_declaration()?;
        match declaration {
            TopLevelFunction::Prototype(_) => Ok(Stmt::Empty),
            TopLevelFunction::Definition(_) => Err(Self::error_at(
                "function definitions are not supported inside blocks".to_string(),
                &declaration_start,
            )),
        }
    }

    fn parse_static_assert(&mut self) -> CustResult<Stmt> {
        self.expect(Token::StaticAssert)?;
        self.expect_opening_paren_after("_Static_assert")?;
        if matches!(
            self.peek(),
            Token::Comma
                | Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::RParen
                | Token::RBracket
                | Token::Semi
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!("expected _Static_assert condition, found {:?}", self.peek()),
                self.peek_located(),
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_or_selector_label() {
            return Err(Self::error_at(
                format!("expected _Static_assert condition before '{label}'"),
                self.peek_located(),
            ));
        }
        let condition = self.parse_assignment_expr()?;
        if !self.matches(&Token::Comma) {
            return Err(Self::error_at(
                format!(
                    "expected ',' after _Static_assert condition, found {:?}",
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        let message = match self.advance().kind.clone() {
            Token::StringLiteral(values) => Self::static_assert_message(values),
            token => {
                return Err(Self::error_at(
                    format!(
                        "expected string literal after _Static_assert condition, found {token:?}"
                    ),
                    self.previous(),
                ));
            }
        };
        self.expect_closing_paren_after("_Static_assert message")?;
        self.expect_semicolon_after("_Static_assert")?;
        Ok(self.with_pending_inline_enum_decl(Stmt::StaticAssert { condition, message }))
    }

    fn static_assert_message(values: Vec<i64>) -> String {
        values
            .into_iter()
            .take_while(|value| *value != 0)
            .map(|value| char::from_u32(value as u32).unwrap_or('\u{FFFD}'))
            .collect()
    }

    fn parse_static_local_decl(&mut self) -> CustResult<Stmt> {
        self.expect(Token::Static)?;
        let id = self.next_static_local_id;
        self.consume_thread_local_specifiers();
        self.consume_alignment_specifiers()?;
        if self.starts_qualified_aggregate_declaration() {
            let decl = self.parse_aggregate_var_decl()?;
            let mut next_id = id;
            let wrapped = Self::wrap_static_local_declarations(decl, &mut next_id)?;
            self.next_static_local_id = next_id;
            return Ok(wrapped);
        }
        let decl = match self.peek() {
            Token::Int
            | Token::Char
            | Token::Bool
            | Token::Signed
            | Token::Unsigned
            | Token::Long
            | Token::Short
            | Token::Const
            | Token::Volatile
            | Token::Restrict
            | Token::Atomic
            | Token::Enum => self.parse_var_decl()?,
            Token::Ident(_) if self.current_alias().is_some() => self.parse_var_decl()?,
            Token::Struct | Token::Union => self.parse_aggregate_var_decl()?,
            token => {
                return Err(Self::error_at(
                    format!("expected declaration after static, found {token:?}"),
                    self.peek_located(),
                ));
            }
        };
        let mut next_id = id;
        let wrapped = Self::wrap_static_local_declarations(decl, &mut next_id)?;
        self.next_static_local_id = next_id;
        Ok(wrapped)
    }

    fn wrap_static_local_declarations(stmt: Stmt, next_id: &mut usize) -> CustResult<Stmt> {
        match stmt {
            Stmt::Many(declarations) => Ok(Stmt::Many(
                declarations
                    .into_iter()
                    .map(|declaration| Self::wrap_static_local_declarations(declaration, next_id))
                    .collect::<CustResult<Vec<_>>>()?,
            )),
            Stmt::EnumDecl { constants } => Ok(Stmt::EnumDecl { constants }),
            declaration @ (Stmt::VarDecl { .. }
            | Stmt::PointerDecl { .. }
            | Stmt::Array2DPointerDecl { .. }
            | Stmt::ArrayDecl { .. }
            | Stmt::Array2DDecl { .. }
            | Stmt::StructVarDecl { .. }
            | Stmt::StructArrayDecl { .. }) => {
                let id = *next_id;
                *next_id += 1;
                Ok(Stmt::StaticLocal {
                    id,
                    decl: Box::new(declaration),
                })
            }
            _ => Err(CustError::new(
                "static local declarations must declare variables",
            )),
        }
    }

    fn parse_thread_local_local_decl(&mut self) -> CustResult<Stmt> {
        self.consume_thread_local_specifiers();
        if self.check(&Token::Static) {
            return self.parse_static_local_decl();
        }
        self.consume_alignment_specifiers()?;
        if self.starts_qualified_aggregate_declaration() {
            return self.parse_aggregate_var_decl();
        }
        match self.peek() {
            Token::Int
            | Token::Char
            | Token::Bool
            | Token::Signed
            | Token::Unsigned
            | Token::Long
            | Token::Short
            | Token::Const
            | Token::Volatile
            | Token::Restrict
            | Token::Atomic
            | Token::Enum => self.parse_var_decl(),
            Token::Ident(_) if self.current_alias().is_some() => self.parse_var_decl(),
            Token::Struct | Token::Union => self.parse_aggregate_var_decl(),
            token => Err(Self::error_at(
                format!("expected declaration after _Thread_local, found {token:?}"),
                self.peek_located(),
            )),
        }
    }

    fn parse_extern_local_decl(&mut self) -> CustResult<Stmt> {
        self.expect(Token::Extern)?;
        self.consume_alignment_specifiers()?;
        if self.starts_local_function_declaration() {
            return self.parse_local_function_prototype_decl();
        }
        let parsed_decl = match self.peek() {
            Token::Int
            | Token::Char
            | Token::Bool
            | Token::Signed
            | Token::Unsigned
            | Token::Long
            | Token::Short
            | Token::Const
            | Token::Volatile
            | Token::Restrict
            | Token::Atomic => self.parse_var_decl()?,
            Token::Ident(_) if self.current_alias().is_some() => self.parse_var_decl()?,
            Token::Enum => self.parse_var_decl()?,
            Token::Struct | Token::Union => self.parse_aggregate_var_decl()?,
            token => {
                return Err(Self::error_at(
                    format!("expected declaration after extern, found {token:?}"),
                    self.peek_located(),
                ));
            }
        };
        if self.last_decl_had_initializer {
            return Err(CustError::new(
                "extern local declarations cannot have initializers",
            ));
        }
        drop(parsed_decl);
        Ok(Stmt::Empty)
    }

    fn parse_auto_register_local_decl(&mut self) -> CustResult<Stmt> {
        let specifier = match self.peek() {
            Token::Auto => "auto",
            Token::Register => "register",
            _ => unreachable!("caller checked storage-class token"),
        };
        self.advance();
        self.consume_alignment_specifiers()?;
        if self.starts_qualified_aggregate_declaration() {
            return self.parse_aggregate_var_decl();
        }
        match self.peek() {
            Token::Int
            | Token::Char
            | Token::Bool
            | Token::Signed
            | Token::Unsigned
            | Token::Long
            | Token::Short
            | Token::Const
            | Token::Volatile
            | Token::Restrict
            | Token::Atomic
            | Token::Enum => self.parse_var_decl(),
            Token::Ident(_) if self.current_alias().is_some() => self.parse_var_decl(),
            Token::Struct | Token::Union => self.parse_aggregate_var_decl(),
            token => Err(Self::error_at(
                format!("expected declaration after {specifier}, found {token:?}"),
                self.peek_located(),
            )),
        }
    }

    fn parse_var_decl(&mut self) -> CustResult<Stmt> {
        self.pending_inline_enum_constants = None;
        let stmt = self.parse_var_decl_with_semi(true)?;
        Ok(self.with_pending_inline_enum_decl(stmt))
    }

    fn push_pending_inline_enum_constants(&mut self, constants: Vec<EnumConstant>) {
        match &mut self.pending_inline_enum_constants {
            Some(existing) => existing.extend(constants),
            None => self.pending_inline_enum_constants = Some(constants),
        }
    }

    fn take_pending_inline_enum_decl(&mut self) -> Option<Stmt> {
        self.pending_inline_enum_constants
            .take()
            .map(|constants| Stmt::EnumDecl { constants })
    }

    fn with_pending_inline_enum_decl(&mut self, stmt: Stmt) -> Stmt {
        Self::prepend_optional_stmt(self.take_pending_inline_enum_decl(), stmt)
    }

    fn prepend_optional_stmt(prefix: Option<Stmt>, stmt: Stmt) -> Stmt {
        match prefix {
            Some(prefix) => Stmt::Many(vec![prefix, stmt]),
            None => stmt,
        }
    }

    fn split_leading_enum_decl(stmt: Stmt) -> (Option<Stmt>, Stmt) {
        match stmt {
            Stmt::Many(mut stmts) if matches!(stmts.first(), Some(Stmt::EnumDecl { .. })) => {
                let enum_decl = stmts.remove(0);
                let stmt = match stmts.len() {
                    0 => Stmt::Empty,
                    1 => stmts.remove(0),
                    _ => Stmt::Many(stmts),
                };
                (Some(enum_decl), stmt)
            }
            stmt => (None, stmt),
        }
    }

    fn append_optional_stmts(
        init: Option<Box<Stmt>>,
        optional_stmts: impl IntoIterator<Item = Option<Stmt>>,
    ) -> Option<Box<Stmt>> {
        let mut stmts = init.map(|stmt| vec![*stmt]).unwrap_or_default();
        stmts.extend(optional_stmts.into_iter().flatten());
        match stmts.len() {
            0 => None,
            1 => Some(Box::new(stmts.remove(0))),
            _ => Some(Box::new(Stmt::Many(stmts))),
        }
    }

    fn parse_aligned_decl(&mut self) -> CustResult<Stmt> {
        self.consume_alignment_specifiers()?;
        if self.starts_qualified_aggregate_declaration() {
            return self.parse_aggregate_var_decl();
        }
        match self.peek() {
            Token::Int
            | Token::Char
            | Token::Bool
            | Token::Signed
            | Token::Unsigned
            | Token::Long
            | Token::Short
            | Token::Const
            | Token::Volatile
            | Token::Restrict
            | Token::Atomic
            | Token::Enum => self.parse_var_decl(),
            Token::Ident(_) if self.current_alias().is_some() => self.parse_var_decl(),
            Token::Struct | Token::Union => self.parse_aggregate_var_decl(),
            token => Err(Self::error_at(
                format!("expected declaration after _Alignas specifier, found {token:?}"),
                self.peek_located(),
            )),
        }
    }

    fn parse_var_decl_with_semi(&mut self, require_semi: bool) -> CustResult<Stmt> {
        self.last_decl_had_initializer = false;
        self.consume_alignment_specifiers()?;
        let (leading_const, decl_type) =
            self.parse_const_qualified_decl_type("declaration type")?;
        if self.check(&Token::LParen) && matches!(self.peek_next(), Token::Star) {
            if self.parenthesized_pointer_declarator_is_function_at(self.pos) {
                return Err(Self::error_at(
                    "function pointer declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            if let DeclType::Scalar(elem_type) = &decl_type {
                return self.parse_two_dimensional_row_pointer_decl(
                    *elem_type,
                    leading_const,
                    require_semi,
                );
            }
            return Err(Self::error_at(
                "parenthesized pointer declarations are not supported".to_string(),
                self.peek_located(),
            ));
        }
        let has_explicit_star = self.matches(&Token::Star);
        let post_star_const = has_explicit_star && self.consume_type_qualifiers();
        if matches!(
            decl_type,
            DeclType::Pointer { .. } | DeclType::Array2DPointer { .. }
        ) && has_explicit_star
        {
            return Err(Self::error_at(
                "pointer-to-pointer declarations are not supported".to_string(),
                self.previous(),
            ));
        }
        if has_explicit_star && self.check(&Token::Star) {
            return Err(Self::error_at(
                "pointer-to-pointer declarations are not supported".to_string(),
                self.peek_located(),
            ));
        }
        if !has_explicit_star
            && self.check(&Token::LParen)
            && matches!(self.peek_next(), Token::Star)
        {
            if self.parenthesized_pointer_declarator_is_function_at(self.pos) {
                return Err(Self::error_at(
                    "function pointer declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            return Err(Self::error_at(
                "parenthesized pointer declarations are not supported".to_string(),
                self.peek_located(),
            ));
        }
        let is_pointer = has_explicit_star
            || matches!(
                decl_type,
                DeclType::Pointer { .. } | DeclType::Array2DPointer { .. }
            );
        let name = if has_explicit_star {
            match &decl_type {
                DeclType::Scalar(_) => self.parse_declarator_name("pointer name after '*'")?,
                DeclType::Struct(_) => {
                    self.parse_declarator_name("struct pointer name after '*'")?
                }
                DeclType::Array(_, _) | DeclType::Array2D(_, _, _) => {
                    return Err(Self::error_at(
                        "pointer-to-array declarations are not supported".to_string(),
                        self.previous(),
                    ));
                }
                DeclType::Pointer { .. } => {
                    unreachable!("pointer aliases with explicit stars return above")
                }
                DeclType::Array2DPointer { .. } => {
                    unreachable!("row pointer aliases with explicit stars return above")
                }
            }
        } else {
            match &decl_type {
                DeclType::Scalar(_) => self.parse_declarator_name("variable name after type")?,
                DeclType::Struct(_) => self.parse_declarator_name("struct variable name")?,
                DeclType::Pointer { .. } => {
                    self.parse_declarator_name("pointer name after type")?
                }
                DeclType::Array2DPointer { .. } => {
                    self.parse_declarator_name("row pointer name after type")?
                }
                DeclType::Array(_, _) | DeclType::Array2D(_, _, _) => {
                    self.parse_declarator_name("array name after type")?
                }
            }
        };
        if let DeclType::Array2DPointer {
            elem_type,
            columns,
            points_to_const,
        } = decl_type.clone()
        {
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "row pointer array declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let stmt = self.parse_two_dimensional_row_pointer_alias_decl_tail(
                name,
                elem_type,
                columns,
                leading_const,
                points_to_const,
            )?;
            if require_semi && self.matches(&Token::Comma) {
                return self.parse_declarator_list_tail(stmt, decl_type, leading_const);
            }
            if require_semi {
                self.expect_semicolon_after("two-dimensional row pointer declaration")?;
            }
            return Ok(stmt);
        }
        if let DeclType::Array2D(ty, rows, columns) = decl_type.clone() {
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "arrays with more than two dimensions are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let init = if self.matches(&Token::Assign) {
                self.last_decl_had_initializer = true;
                self.parse_two_dimensional_array_initializer(&name, rows, columns)?
            } else {
                Vec::new()
            };
            let stmt = Stmt::Array2DDecl {
                name,
                elem_type: ty,
                rows,
                columns,
                init,
                is_const: leading_const,
            };
            if require_semi && self.matches(&Token::Comma) {
                return self.parse_declarator_list_tail(
                    stmt,
                    DeclType::Array2D(ty, rows, columns),
                    leading_const,
                );
            }
            if require_semi {
                self.expect_semicolon_after("two-dimensional array declaration")?;
            }
            return Ok(stmt);
        }
        if let DeclType::Array(pointee, len) = decl_type.clone() {
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "multidimensional array declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            match pointee {
                PointeeType::Scalar(ty) => {
                    let init = if self.matches(&Token::Assign) {
                        self.last_decl_had_initializer = true;
                        self.parse_array_initializer_or_string(&name, len, ty)?
                    } else {
                        Vec::new()
                    };
                    let stmt = Stmt::ArrayDecl {
                        name,
                        elem_type: ty,
                        len,
                        init,
                        is_const: leading_const,
                    };
                    if require_semi && self.matches(&Token::Comma) {
                        return self.parse_declarator_list_tail(
                            stmt,
                            DeclType::Array(PointeeType::Scalar(ty), len),
                            leading_const,
                        );
                    }
                    if require_semi {
                        self.expect_semicolon_after("array declaration")?;
                    }
                    return Ok(stmt);
                }
                PointeeType::Struct(type_name) => {
                    let init = if self.matches(&Token::Assign) {
                        self.last_decl_had_initializer = true;
                        self.parse_struct_array_initializer(&name, &type_name, len)?
                    } else {
                        Vec::new()
                    };
                    let stmt = Stmt::StructArrayDecl {
                        type_name: type_name.clone(),
                        name,
                        len,
                        init,
                        is_const: leading_const,
                    };
                    if require_semi && self.matches(&Token::Comma) {
                        return self.parse_declarator_list_tail(
                            stmt,
                            DeclType::Array(PointeeType::Struct(type_name), len),
                            leading_const,
                        );
                    }
                    if require_semi {
                        self.expect_semicolon_after("struct array declaration")?;
                    }
                    return Ok(stmt);
                }
            }
        }
        if is_pointer {
            let (is_const, points_to_const) = if has_explicit_star {
                (post_star_const, leading_const)
            } else {
                (leading_const, Self::decl_type_points_to_const(&decl_type))
            };
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "pointer array declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let expr = if self.matches(&Token::Assign) {
                self.last_decl_had_initializer = true;
                self.reject_missing_declaration_initializer_expr("pointer declaration")?;
                self.parse_assignment_expr()?
            } else if matches!(self.peek(), Token::Semi | Token::Comma) {
                Expr::Number(0)
            } else {
                let context = match &decl_type {
                    DeclType::Scalar(_)
                    | DeclType::Pointer {
                        pointee: PointeeType::Scalar(_),
                        ..
                    } => "pointer declaration",
                    DeclType::Struct(_)
                    | DeclType::Pointer {
                        pointee: PointeeType::Struct(_),
                        ..
                    } => "struct pointer declaration",
                    DeclType::Array(_, _)
                    | DeclType::Array2D(_, _, _)
                    | DeclType::Array2DPointer { .. } => {
                        unreachable!("array aliases return before pointer declarations")
                    }
                };
                self.expect_assign_after(context)?;
                unreachable!("expect_assign_after only returns Ok after consuming '='")
            };
            let stmt = Stmt::PointerDecl {
                name,
                ty: Self::decl_type_to_pointee_type(&decl_type),
                expr,
                is_const,
                points_to_const,
            };
            if require_semi && self.matches(&Token::Comma) {
                return self.parse_declarator_list_tail(stmt, decl_type, leading_const);
            }
            if require_semi {
                let context = match &decl_type {
                    DeclType::Scalar(_)
                    | DeclType::Pointer {
                        pointee: PointeeType::Scalar(_),
                        ..
                    } => "pointer declaration",
                    DeclType::Struct(_)
                    | DeclType::Pointer {
                        pointee: PointeeType::Struct(_),
                        ..
                    } => "struct pointer declaration",
                    DeclType::Array(_, _)
                    | DeclType::Array2D(_, _, _)
                    | DeclType::Array2DPointer { .. } => {
                        unreachable!("array aliases return before pointer declarations")
                    }
                };
                self.expect_semicolon_after(context)?;
            }
            return Ok(stmt);
        }
        if matches!(decl_type, DeclType::Struct(_)) {
            if self.matches(&Token::LBracket) {
                let DeclType::Struct(type_name) = &decl_type else {
                    unreachable!("struct declarations return above")
                };
                let (len, init) = if self.matches(&Token::RBracket) {
                    if !self.matches(&Token::Assign) {
                        self.expect_assign_after("inferred aggregate array declaration")?;
                        unreachable!("expect_assign_after only returns Ok after consuming '='")
                    }
                    self.last_decl_had_initializer = true;
                    self.reject_missing_declaration_initializer_expr(
                        "inferred aggregate array declaration",
                    )?;
                    let init = self.parse_aggregate_array_compound_initializer(type_name, None)?;
                    let len = Self::infer_struct_array_initializer_len(&init);
                    (len, init)
                } else {
                    let len = self.expect_array_len()?;
                    self.expect_closing_bracket_after("struct array length")?;
                    if self.check(&Token::LBracket) {
                        return Err(Self::error_at(
                            "multidimensional array declarations are not supported".to_string(),
                            self.peek_located(),
                        ));
                    }
                    let init = if self.matches(&Token::Assign) {
                        self.last_decl_had_initializer = true;
                        self.parse_struct_array_initializer(&name, type_name, len)?
                    } else {
                        Vec::new()
                    };
                    (len, init)
                };
                if let DeclType::Struct(type_name) = decl_type {
                    let stmt = Stmt::StructArrayDecl {
                        type_name: type_name.clone(),
                        name,
                        len,
                        init,
                        is_const: leading_const,
                    };
                    if require_semi && self.matches(&Token::Comma) {
                        return self.parse_declarator_list_tail(
                            stmt,
                            DeclType::Struct(type_name),
                            leading_const,
                        );
                    }
                    if require_semi {
                        self.expect_semicolon_after("struct array declaration")?;
                    }
                    return Ok(stmt);
                }
            }
            let init = if self.matches(&Token::Assign) {
                self.last_decl_had_initializer = true;
                let DeclType::Struct(type_name) = &decl_type else {
                    unreachable!("struct declarations return above")
                };
                if self.check(&Token::LBrace) {
                    Some(StructVarInitializer::Fields(
                        self.parse_struct_initializer(type_name)?,
                    ))
                } else {
                    self.reject_missing_declaration_initializer_expr(
                        "struct variable declaration",
                    )?;
                    Some(StructVarInitializer::Expr(self.parse_assignment_expr()?))
                }
            } else {
                None
            };
            if let DeclType::Struct(type_name) = decl_type {
                let stmt = Stmt::StructVarDecl {
                    type_name: type_name.clone(),
                    name,
                    init,
                    is_const: leading_const,
                };
                if require_semi && self.matches(&Token::Comma) {
                    return self.parse_declarator_list_tail(
                        stmt,
                        DeclType::Struct(type_name),
                        leading_const,
                    );
                }
                if require_semi {
                    self.expect_semicolon_after("struct variable declaration")?;
                }
                return Ok(stmt);
            }
        }
        let DeclType::Scalar(ty) = decl_type else {
            unreachable!("struct declarations return above")
        };
        if self.matches(&Token::LBracket) {
            let (len, init) = if self.matches(&Token::RBracket) {
                if !self.matches(&Token::Assign) {
                    self.expect_assign_after("inferred array declaration")?;
                    unreachable!("expect_assign_after only returns Ok after consuming '='")
                }
                self.last_decl_had_initializer = true;
                self.reject_missing_declaration_initializer_expr("inferred array declaration")?;
                let init = self.parse_inferred_array_initializer_or_string(&name, ty)?;
                let len = Self::infer_array_initializer_len(&init);
                (len, init)
            } else {
                let len = self.expect_array_len()?;
                self.expect_closing_bracket_after("array length")?;
                if self.matches(&Token::LBracket) {
                    let columns = self.expect_array_len()?;
                    self.expect_closing_bracket_after("second array dimension")?;
                    if self.check(&Token::LBracket) {
                        return Err(Self::error_at(
                            "arrays with more than two dimensions are not supported".to_string(),
                            self.peek_located(),
                        ));
                    }
                    let init = if self.matches(&Token::Assign) {
                        self.last_decl_had_initializer = true;
                        self.parse_two_dimensional_array_initializer(&name, len, columns)?
                    } else {
                        Vec::new()
                    };
                    let stmt = Stmt::Array2DDecl {
                        name,
                        elem_type: ty,
                        rows: len,
                        columns,
                        init,
                        is_const: leading_const,
                    };
                    if require_semi && self.matches(&Token::Comma) {
                        return self.parse_declarator_list_tail(
                            stmt,
                            DeclType::Scalar(ty),
                            leading_const,
                        );
                    }
                    if require_semi {
                        self.expect_semicolon_after("two-dimensional array declaration")?;
                    }
                    return Ok(stmt);
                }
                let init = if self.matches(&Token::Assign) {
                    self.last_decl_had_initializer = true;
                    self.parse_array_initializer_or_string(&name, len, ty)?
                } else {
                    Vec::new()
                };
                (len, init)
            };
            let stmt = Stmt::ArrayDecl {
                name,
                elem_type: ty,
                len,
                init,
                is_const: leading_const,
            };
            if require_semi && self.matches(&Token::Comma) {
                return self.parse_declarator_list_tail(stmt, DeclType::Scalar(ty), leading_const);
            }
            if require_semi {
                self.expect_semicolon_after("array declaration")?;
            }
            return Ok(stmt);
        }
        let first_decl = self.parse_scalar_declarator_tail(name, ty, leading_const)?;
        if require_semi && self.matches(&Token::Comma) {
            return self.parse_declarator_list_tail(
                first_decl,
                DeclType::Scalar(ty),
                leading_const,
            );
        }
        if require_semi {
            self.expect_semicolon_after("variable declaration")?;
        }
        Ok(first_decl)
    }

    fn parse_two_dimensional_row_pointer_alias_decl_tail(
        &mut self,
        name: String,
        elem_type: CType,
        columns: usize,
        is_const: bool,
        points_to_const: bool,
    ) -> CustResult<Stmt> {
        let expr = if self.matches(&Token::Assign) {
            self.last_decl_had_initializer = true;
            self.reject_missing_declaration_initializer_expr(
                "two-dimensional row pointer declaration",
            )?;
            self.parse_assignment_expr()?
        } else if matches!(self.peek(), Token::Semi | Token::Comma) {
            Expr::Number(0)
        } else {
            self.expect_assign_after("two-dimensional row pointer declaration")?;
            unreachable!("expect_assign_after only returns Ok after consuming '='")
        };
        Ok(Stmt::Array2DPointerDecl {
            name,
            elem_type,
            columns,
            expr,
            is_const,
            points_to_const,
        })
    }

    fn parse_two_dimensional_row_pointer_decl(
        &mut self,
        elem_type: CType,
        points_to_const: bool,
        require_semi: bool,
    ) -> CustResult<Stmt> {
        self.expect(Token::LParen)?;
        self.expect(Token::Star)?;
        let is_const = self.consume_type_qualifiers();
        let name = self.parse_declarator_name("row pointer name after '*'")?;
        self.expect_closing_paren_after("two-dimensional row pointer declarator")?;
        self.expect(Token::LBracket)?;
        let columns = self.expect_array_len()?;
        self.expect_closing_bracket_after("two-dimensional row pointer width")?;
        if self.check(&Token::LBracket) {
            return Err(Self::error_at(
                "row pointers with more than two dimensions are not supported".to_string(),
                self.peek_located(),
            ));
        }
        let expr = if self.matches(&Token::Assign) {
            self.last_decl_had_initializer = true;
            self.reject_missing_declaration_initializer_expr(
                "two-dimensional row pointer declaration",
            )?;
            self.parse_assignment_expr()?
        } else if matches!(self.peek(), Token::Semi) {
            Expr::Number(0)
        } else {
            self.expect_assign_after("two-dimensional row pointer declaration")?;
            unreachable!("expect_assign_after only returns Ok after consuming '='")
        };
        if require_semi {
            self.expect_semicolon_after("two-dimensional row pointer declaration")?;
        }
        Ok(Stmt::Array2DPointerDecl {
            name,
            elem_type,
            columns,
            expr,
            is_const,
            points_to_const,
        })
    }

    fn parse_declarator_list_tail(
        &mut self,
        first_decl: Stmt,
        base_type: DeclType,
        leading_const: bool,
    ) -> CustResult<Stmt> {
        let mut declarations = vec![first_decl];
        loop {
            declarations.push(self.parse_additional_declarator(base_type.clone(), leading_const)?);
            if !self.matches(&Token::Comma) {
                break;
            }
        }
        self.expect_semicolon_after("declaration list")?;
        Ok(Stmt::Many(declarations))
    }

    fn parse_additional_declarator(
        &mut self,
        base_type: DeclType,
        leading_const: bool,
    ) -> CustResult<Stmt> {
        if self.check(&Token::LParen) && matches!(self.peek_next(), Token::Star) {
            if self.parenthesized_pointer_declarator_is_function_at(self.pos) {
                return Err(Self::error_at(
                    "function pointer declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            return Err(Self::error_at(
                "parenthesized pointer declarations are not supported".to_string(),
                self.peek_located(),
            ));
        }
        let has_explicit_star = self.matches(&Token::Star);
        let post_star_const = has_explicit_star && self.consume_type_qualifiers();
        if matches!(
            base_type,
            DeclType::Pointer { .. } | DeclType::Array2DPointer { .. }
        ) && has_explicit_star
        {
            return Err(Self::error_at(
                "pointer-to-pointer declarations are not supported".to_string(),
                self.previous(),
            ));
        }
        if has_explicit_star && self.check(&Token::Star) {
            return Err(Self::error_at(
                "pointer-to-pointer declarations are not supported".to_string(),
                self.peek_located(),
            ));
        }
        let is_pointer = has_explicit_star
            || matches!(
                base_type,
                DeclType::Pointer { .. } | DeclType::Array2DPointer { .. }
            );
        let name = if has_explicit_star {
            match &base_type {
                DeclType::Scalar(_) => self.parse_declarator_name("pointer name after '*'")?,
                DeclType::Struct(_) => {
                    self.parse_declarator_name("struct pointer name after '*'")?
                }
                DeclType::Array(_, _) => {
                    return Err(Self::error_at(
                        "pointer-to-array declarations are not supported".to_string(),
                        self.previous(),
                    ));
                }
                DeclType::Array2D(_, _, _) => {
                    return Err(Self::error_at(
                        "pointer-to-array declarations are not supported".to_string(),
                        self.previous(),
                    ));
                }
                DeclType::Pointer { .. } => unreachable!("pointer aliases with stars return above"),
                DeclType::Array2DPointer { .. } => {
                    unreachable!("row pointer aliases with stars return above")
                }
            }
        } else {
            match &base_type {
                DeclType::Scalar(_) => self.parse_declarator_name("variable name after ','")?,
                DeclType::Struct(_) => {
                    self.parse_declarator_name("struct variable name after ','")?
                }
                DeclType::Pointer { .. } => self.parse_declarator_name("pointer name after ','")?,
                DeclType::Array2DPointer { .. } => {
                    self.parse_declarator_name("row pointer name after ','")?
                }
                DeclType::Array(_, _) => self.parse_declarator_name("array name after ','")?,
                DeclType::Array2D(_, _, _) => self.parse_declarator_name("array name after ','")?,
            }
        };

        if let DeclType::Array2DPointer {
            elem_type,
            columns,
            points_to_const,
        } = base_type.clone()
        {
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "row pointer array declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            return self.parse_two_dimensional_row_pointer_alias_decl_tail(
                name,
                elem_type,
                columns,
                leading_const,
                points_to_const,
            );
        }

        if let DeclType::Array(pointee, len) = base_type.clone() {
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "multidimensional array declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            return match pointee {
                PointeeType::Scalar(ty) => {
                    let init = if self.matches(&Token::Assign) {
                        self.last_decl_had_initializer = true;
                        self.parse_array_initializer_or_string(&name, len, ty)?
                    } else {
                        Vec::new()
                    };
                    Ok(Stmt::ArrayDecl {
                        name,
                        elem_type: ty,
                        len,
                        init,
                        is_const: leading_const,
                    })
                }
                PointeeType::Struct(type_name) => {
                    let init = if self.matches(&Token::Assign) {
                        self.last_decl_had_initializer = true;
                        self.parse_struct_array_initializer(&name, &type_name, len)?
                    } else {
                        Vec::new()
                    };
                    Ok(Stmt::StructArrayDecl {
                        type_name,
                        name,
                        len,
                        init,
                        is_const: leading_const,
                    })
                }
            };
        }

        if let DeclType::Array2D(ty, rows, columns) = base_type.clone() {
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "arrays with more than two dimensions are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let init = if self.matches(&Token::Assign) {
                self.last_decl_had_initializer = true;
                self.parse_two_dimensional_array_initializer(&name, rows, columns)?
            } else {
                Vec::new()
            };
            return Ok(Stmt::Array2DDecl {
                name,
                elem_type: ty,
                rows,
                columns,
                init,
                is_const: leading_const,
            });
        }

        if is_pointer {
            let (is_const, points_to_const) = if has_explicit_star {
                (post_star_const, leading_const)
            } else {
                (leading_const, Self::decl_type_points_to_const(&base_type))
            };
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "pointer array declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let expr = if self.matches(&Token::Assign) {
                self.last_decl_had_initializer = true;
                self.reject_missing_declaration_initializer_expr("pointer declaration")?;
                self.parse_assignment_expr()?
            } else if matches!(self.peek(), Token::Semi | Token::Comma) {
                Expr::Number(0)
            } else {
                let context = match &base_type {
                    DeclType::Scalar(_)
                    | DeclType::Pointer {
                        pointee: PointeeType::Scalar(_),
                        ..
                    } => "pointer declaration",
                    DeclType::Struct(_)
                    | DeclType::Pointer {
                        pointee: PointeeType::Struct(_),
                        ..
                    } => "struct pointer declaration",
                    DeclType::Array(_, _)
                    | DeclType::Array2D(_, _, _)
                    | DeclType::Array2DPointer { .. } => {
                        unreachable!("array aliases return before pointer declarations")
                    }
                };
                self.expect_assign_after(context)?;
                unreachable!("expect_assign_after only returns Ok after consuming '='")
            };
            return Ok(Stmt::PointerDecl {
                name,
                ty: Self::decl_type_to_pointee_type(&base_type),
                expr,
                is_const,
                points_to_const,
            });
        }

        match base_type {
            DeclType::Scalar(ty) => {
                if self.matches(&Token::LBracket) {
                    let (len, init) = if self.matches(&Token::RBracket) {
                        if !self.matches(&Token::Assign) {
                            self.expect_assign_after("inferred array declaration")?;
                            unreachable!("expect_assign_after only returns Ok after consuming '='")
                        }
                        self.last_decl_had_initializer = true;
                        self.reject_missing_declaration_initializer_expr(
                            "inferred array declaration",
                        )?;
                        let init = self.parse_inferred_array_initializer_or_string(&name, ty)?;
                        let len = Self::infer_array_initializer_len(&init);
                        (len, init)
                    } else {
                        let len = self.expect_array_len()?;
                        self.expect_closing_bracket_after("array length")?;
                        if self.matches(&Token::LBracket) {
                            let columns = self.expect_array_len()?;
                            self.expect_closing_bracket_after("second array dimension")?;
                            if self.check(&Token::LBracket) {
                                return Err(Self::error_at(
                                    "arrays with more than two dimensions are not supported"
                                        .to_string(),
                                    self.peek_located(),
                                ));
                            }
                            let init = if self.matches(&Token::Assign) {
                                self.last_decl_had_initializer = true;
                                self.parse_two_dimensional_array_initializer(&name, len, columns)?
                            } else {
                                Vec::new()
                            };
                            return Ok(Stmt::Array2DDecl {
                                name,
                                elem_type: ty,
                                rows: len,
                                columns,
                                init,
                                is_const: leading_const,
                            });
                        }
                        let init = if self.matches(&Token::Assign) {
                            self.last_decl_had_initializer = true;
                            self.parse_array_initializer_or_string(&name, len, ty)?
                        } else {
                            Vec::new()
                        };
                        (len, init)
                    };
                    Ok(Stmt::ArrayDecl {
                        name,
                        elem_type: ty,
                        len,
                        init,
                        is_const: leading_const,
                    })
                } else {
                    self.parse_scalar_declarator_tail(name, ty, leading_const)
                }
            }
            DeclType::Struct(type_name) => {
                if self.matches(&Token::LBracket) {
                    let (len, init) = if self.matches(&Token::RBracket) {
                        if !self.matches(&Token::Assign) {
                            self.expect_assign_after("inferred aggregate array declaration")?;
                            unreachable!("expect_assign_after only returns Ok after consuming '='")
                        }
                        self.last_decl_had_initializer = true;
                        self.reject_missing_declaration_initializer_expr(
                            "inferred aggregate array declaration",
                        )?;
                        let init =
                            self.parse_aggregate_array_compound_initializer(&type_name, None)?;
                        let len = Self::infer_struct_array_initializer_len(&init);
                        (len, init)
                    } else {
                        let len = self.expect_array_len()?;
                        self.expect_closing_bracket_after("struct array length")?;
                        if self.check(&Token::LBracket) {
                            return Err(Self::error_at(
                                "multidimensional array declarations are not supported".to_string(),
                                self.peek_located(),
                            ));
                        }
                        let init = if self.matches(&Token::Assign) {
                            self.last_decl_had_initializer = true;
                            self.parse_struct_array_initializer(&name, &type_name, len)?
                        } else {
                            Vec::new()
                        };
                        (len, init)
                    };
                    Ok(Stmt::StructArrayDecl {
                        type_name,
                        name,
                        len,
                        init,
                        is_const: leading_const,
                    })
                } else {
                    let init = if self.matches(&Token::Assign) {
                        self.last_decl_had_initializer = true;
                        if self.check(&Token::LBrace) {
                            Some(StructVarInitializer::Fields(
                                self.parse_struct_initializer(&type_name)?,
                            ))
                        } else {
                            self.reject_missing_declaration_initializer_expr(
                                "struct variable declaration",
                            )?;
                            Some(StructVarInitializer::Expr(self.parse_assignment_expr()?))
                        }
                    } else {
                        None
                    };
                    Ok(Stmt::StructVarDecl {
                        type_name,
                        name,
                        init,
                        is_const: leading_const,
                    })
                }
            }
            DeclType::Pointer { .. }
            | DeclType::Array(_, _)
            | DeclType::Array2D(_, _, _)
            | DeclType::Array2DPointer { .. } => {
                unreachable!("handled above")
            }
        }
    }

    fn parse_scalar_declarator_tail(
        &mut self,
        name: String,
        ty: CType,
        is_const: bool,
    ) -> CustResult<Stmt> {
        let expr = if self.matches(&Token::Assign) {
            self.last_decl_had_initializer = true;
            self.reject_missing_declaration_initializer_expr("variable declaration")?;
            self.parse_scalar_initializer_expr(&format!("variable '{name}'"))?
        } else if matches!(self.peek(), Token::Semi | Token::Comma) {
            Expr::Number(0)
        } else {
            self.expect_assign_after("variable declaration")?;
            unreachable!("expect_assign_after only returns Ok after consuming '='")
        };
        Ok(Stmt::VarDecl {
            name,
            ty,
            expr,
            is_const,
        })
    }

    fn reject_missing_declaration_initializer_expr(&self, context: &str) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::Comma
                | Token::Colon
                | Token::LBracket
                | Token::Question
                | Token::RParen
                | Token::RBracket
                | Token::Semi
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!(
                    "expected initializer expression after '=' in {context}, found {:?}",
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!("expected initializer expression after '=' in {context} before '{label}'"),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn reject_missing_braced_initializer_element(&self, context: &str) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::Comma
                | Token::Colon
                | Token::Question
                | Token::Semi
                | Token::RParen
                | Token::RBracket
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!(
                    "expected initializer element in {context}, found {:?}",
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!("expected initializer element in {context} before '{label}'"),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn reject_invalid_braced_initializer_selector_element(
        &self,
        context: &str,
        allow_dot_designator: bool,
    ) -> CustResult<()> {
        if matches!(self.peek(), Token::Arrow) || (!allow_dot_designator && self.check(&Token::Dot))
        {
            return Err(Self::error_at(
                format!(
                    "expected initializer element in {context}, found {:?}",
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn reject_invalid_braced_initializer_value(&self, context: &str) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::Comma
                | Token::Colon
                | Token::LBracket
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::Semi
                | Token::RParen
                | Token::RBracket
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!(
                    "expected initializer element in {context}, found {:?}",
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!("expected initializer element in {context} before '{label}'"),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn parse_array_initializer_or_string(
        &mut self,
        name: &str,
        len: usize,
        elem_type: CType,
    ) -> CustResult<Vec<ArrayInitializer>> {
        self.reject_missing_declaration_initializer_expr("array declaration")?;
        if let Some(init) = self.parse_string_literal_array_initializer(name, len, elem_type)? {
            return Ok(init);
        }

        self.parse_array_initializer(name, len)
    }

    fn parse_two_dimensional_array_initializer(
        &mut self,
        name: &str,
        rows: usize,
        columns: usize,
    ) -> CustResult<Array2DInitializer> {
        self.expect_opening_brace_after("two-dimensional array initializer")?;
        let mut values = Vec::new();
        if self.matches(&Token::RBrace) {
            return Ok(values);
        }
        loop {
            if values.len() == rows {
                return Err(Self::error_at(
                    format!("too many row initializers for array '{name}'"),
                    self.peek_located(),
                ));
            }
            if !self.check(&Token::LBrace) {
                return Err(Self::error_at(
                    format!("expected nested row initializer for array '{name}'"),
                    self.peek_located(),
                ));
            }
            let row_name = format!("{name}[{}]", values.len());
            values.push(self.parse_array_initializer(&row_name, columns)?);
            if self.matches(&Token::RBrace) {
                break;
            }
            if self.matches(&Token::Comma) {
                if self.matches(&Token::RBrace) {
                    break;
                }
                continue;
            }
            self.expect_closing_brace_after("two-dimensional array initializer")?;
        }
        Ok(values)
    }

    fn parse_inferred_array_initializer_or_string(
        &mut self,
        name: &str,
        elem_type: CType,
    ) -> CustResult<Vec<ArrayInitializer>> {
        let token = self.peek_located().clone();
        if let Token::StringLiteral(values) = token.kind.clone() {
            self.advance();
            let values = self.concatenate_adjacent_string_literals(values);
            if elem_type != CType::Char {
                return Err(Self::error_at(
                    format!("string literal initializer requires char array '{name}'"),
                    &token,
                ));
            }
            return Ok(vec![ArrayInitializer::StringLiteral(values)]);
        }

        self.parse_array_compound_initializer(None, elem_type)
    }

    fn parse_string_literal_array_initializer(
        &mut self,
        name: &str,
        len: usize,
        elem_type: CType,
    ) -> CustResult<Option<Vec<ArrayInitializer>>> {
        let token = self.peek_located().clone();
        let Token::StringLiteral(values) = token.kind.clone() else {
            return Ok(None);
        };
        self.advance();
        let values = self.concatenate_adjacent_string_literals(values);
        if elem_type != CType::Char {
            return Err(Self::error_at(
                format!("string literal initializer requires char array '{name}'"),
                &token,
            ));
        }
        let too_long =
            values.len() > len && !(values.len() == len + 1 && values.last() == Some(&0));
        if too_long {
            return Err(Self::error_at(
                format!("initializer string for char array '{name}' is too long"),
                &token,
            ));
        }
        Ok(Some(vec![ArrayInitializer::StringLiteral(values)]))
    }

    fn parse_array_initializer(
        &mut self,
        name: &str,
        len: usize,
    ) -> CustResult<Vec<ArrayInitializer>> {
        self.expect_opening_brace_after("array initializer")?;
        let mut values = Vec::new();
        let mut next_positional_index = 0usize;
        if self.matches(&Token::RBrace) {
            return Ok(values);
        }
        loop {
            let context = format!("array '{name}' initializer");
            self.reject_missing_braced_initializer_element(&context)?;
            self.reject_invalid_braced_initializer_selector_element(&context, false)?;
            if self.check(&Token::LBracket) {
                let index = self.parse_array_designator_index(name, len)?;
                self.expect_assign_after("array designator")?;
                self.reject_invalid_braced_initializer_value(&context)?;
                let value =
                    self.parse_scalar_initializer_expr(&format!("array '{name}' element"))?;
                next_positional_index = index + 1;
                values.push(ArrayInitializer::Designated { index, value });
            } else {
                if next_positional_index == len {
                    let token = self.peek_located().clone();
                    return Err(Self::error_at(
                        format!("too many initializers for array '{name}'"),
                        &token,
                    ));
                }
                values.push(ArrayInitializer::Expr(self.parse_scalar_initializer_expr(
                    &format!("array '{name}' element"),
                )?));
                next_positional_index += 1;
            }
            if self.matches(&Token::RBrace) {
                break;
            }
            if self.matches(&Token::Comma) {
                if self.matches(&Token::RBrace) {
                    break;
                }
                continue;
            }
            self.expect_closing_brace_after("array initializer")?;
        }
        Ok(values)
    }

    fn parse_array_compound_initializer(
        &mut self,
        len: Option<usize>,
        elem_type: CType,
    ) -> CustResult<Vec<ArrayInitializer>> {
        self.expect_opening_brace_after("array compound literal initializer")?;
        let mut values = Vec::new();
        let mut next_positional_index = 0usize;
        if self.matches(&Token::RBrace) {
            return Ok(values);
        }
        loop {
            self.reject_missing_braced_initializer_element("array compound literal initializer")?;
            self.reject_invalid_braced_initializer_selector_element(
                "array compound literal initializer",
                false,
            )?;
            if self.check(&Token::LBracket) {
                let index = match len {
                    Some(len) => self
                        .parse_array_designator_index_with_context("array compound literal", len)?,
                    None => self.parse_unbounded_array_designator_index()?,
                };
                self.expect_assign_after("array designator")?;
                self.reject_invalid_braced_initializer_value("array compound literal initializer")?;
                let value = self.parse_scalar_initializer_expr("array compound literal element")?;
                next_positional_index = index + 1;
                values.push(ArrayInitializer::Designated { index, value });
            } else if let Token::StringLiteral(string_values) = self.peek().clone() {
                let token = self.peek_located().clone();
                self.advance();
                let string_values = self.concatenate_adjacent_string_literals(string_values);
                if elem_type != CType::Char {
                    return Err(Self::error_at(
                        "string literal initializer requires char array compound literal"
                            .to_string(),
                        &token,
                    ));
                }
                let too_long = len.is_some_and(|len| {
                    string_values.len() > len
                        && !(string_values.len() == len + 1 && string_values.last() == Some(&0))
                });
                if too_long {
                    return Err(Self::error_at(
                        "initializer string for char array compound literal is too long"
                            .to_string(),
                        &token,
                    ));
                }
                next_positional_index = string_values.len();
                values.push(ArrayInitializer::StringLiteral(string_values));
            } else {
                if matches!(len, Some(len) if next_positional_index == len) {
                    let token = self.peek_located().clone();
                    return Err(Self::error_at(
                        "too many initializers for array compound literal".to_string(),
                        &token,
                    ));
                }
                values.push(ArrayInitializer::Expr(
                    self.parse_scalar_initializer_expr("array compound literal element")?,
                ));
                next_positional_index += 1;
            }
            if self.matches(&Token::RBrace) {
                break;
            }
            if self.matches(&Token::Comma) {
                if self.matches(&Token::RBrace) {
                    break;
                }
                continue;
            }
            self.expect_closing_brace_after("array compound literal initializer")?;
        }
        Ok(values)
    }

    fn parse_unbounded_array_designator_index(&mut self) -> CustResult<usize> {
        self.expect(Token::LBracket)?;
        if self.check(&Token::RBracket) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before ']'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Semi) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before ';'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Comma) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before ','".to_string(),
                &found,
            ));
        }
        if self.check(&Token::RBrace) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before '}'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::LBracket) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before '['".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Question) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before '?'".to_string(),
                &found,
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_or_selector_label() {
            let found = self.advance();
            return Err(Self::error_at(
                format!("expected array designator index before '{label}'"),
                &found,
            ));
        }
        let (value, first_token) =
            self.parse_integer_constant_expr(&HashMap::new(), "expected array designator index")?;
        let index = Self::array_designator_value_to_index(value, &first_token)?;
        self.reject_array_range_designator()?;
        if self.check(&Token::Comma) {
            let comma = self.peek_located().clone();
            return Err(Self::error_at(
                "comma operator is not allowed in integer constant expression".to_string(),
                &comma,
            ));
        }
        self.expect_closing_bracket_after("array designator")?;
        self.reject_multidimensional_array_designator()?;
        Ok(index)
    }

    fn parse_array_designator_index(&mut self, name: &str, len: usize) -> CustResult<usize> {
        self.parse_array_designator_index_with_context(&format!("array '{name}'"), len)
    }

    fn parse_array_designator_index_with_context(
        &mut self,
        context: &str,
        len: usize,
    ) -> CustResult<usize> {
        self.expect(Token::LBracket)?;
        if self.check(&Token::RBracket) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before ']'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Semi) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before ';'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Comma) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before ','".to_string(),
                &found,
            ));
        }
        if self.check(&Token::RBrace) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before '}'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::LBracket) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before '['".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Question) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array designator index before '?'".to_string(),
                &found,
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_or_selector_label() {
            let found = self.advance();
            return Err(Self::error_at(
                format!("expected array designator index before '{label}'"),
                &found,
            ));
        }
        let (value, first_token) =
            self.parse_integer_constant_expr(&HashMap::new(), "expected array designator index")?;
        let index = Self::array_designator_value_to_index(value, &first_token)?;
        self.reject_array_range_designator()?;
        if self.check(&Token::Comma) {
            let comma = self.peek_located().clone();
            return Err(Self::error_at(
                "comma operator is not allowed in integer constant expression".to_string(),
                &comma,
            ));
        }
        self.expect_closing_bracket_after("array designator")?;
        self.reject_multidimensional_array_designator()?;
        if index >= len {
            return Err(CustError::new(format!(
                "array designator index {index} out of bounds for {context}"
            )));
        }
        Ok(index)
    }

    fn reject_multidimensional_array_designator(&mut self) -> CustResult<()> {
        if self.check(&Token::LBracket) {
            let found = self.advance();
            return Err(Self::error_at(
                "multidimensional array designators are not supported".to_string(),
                &found,
            ));
        }
        Ok(())
    }

    fn array_designator_value_to_index(value: i64, token: &LocatedToken) -> CustResult<usize> {
        if value < 0 {
            return Err(Self::error_at(
                "array designator index must be non-negative".to_string(),
                token,
            ));
        }
        usize::try_from(value)
            .map_err(|_| Self::error_at("array designator index is too large".to_string(), token))
    }

    fn parse_struct_initializer(&mut self, type_name: &str) -> CustResult<Vec<StructInitializer>> {
        let struct_type = self
            .struct_types
            .get(type_name)
            .cloned()
            .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'")))?;
        let fields = struct_type.fields.clone();
        let aggregate_keyword = struct_type.kind.keyword();
        self.expect_opening_brace_after(&format!("{aggregate_keyword} initializer"))?;
        let mut values = Vec::new();
        let mut next_positional_index = 0usize;
        if self.matches(&Token::RBrace) {
            return Ok(values);
        }
        loop {
            let context = format!("{aggregate_keyword} '{type_name}' initializer");
            self.reject_missing_braced_initializer_element(&context)?;
            self.reject_invalid_braced_initializer_selector_element(&context, true)?;
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    format!("expected initializer element in {context}, found LBracket"),
                    self.peek_located(),
                ));
            }
            if self.matches(&Token::Dot) {
                let (field_index, field_name, value) =
                    self.parse_struct_designator_after_dot(type_name, &fields)?;
                next_positional_index = field_index + 1;
                values.push(StructInitializer::Designated {
                    field: field_name,
                    value: Box::new(value),
                });
            } else {
                if next_positional_index == fields.len()
                    || (struct_type.kind == AggregateKind::Union && next_positional_index > 0)
                {
                    let token = self.peek_located().clone();
                    return Err(Self::error_at(
                        format!("too many initializers for {aggregate_keyword} '{type_name}'"),
                        &token,
                    ));
                }
                let field = &fields[next_positional_index];
                let value = self.parse_struct_initializer_value(field)?;
                values.push(StructInitializer::Designated {
                    field: field.name.clone(),
                    value: Box::new(value),
                });
                next_positional_index += 1;
            }
            if self.matches(&Token::RBrace) {
                break;
            }
            if self.matches(&Token::Comma) {
                if self.matches(&Token::RBrace) {
                    break;
                }
                continue;
            }
            self.expect_closing_brace_after("struct initializer")?;
        }
        Ok(values)
    }

    fn parse_struct_designator_after_dot(
        &mut self,
        type_name: &str,
        fields: &[StructFieldDef],
    ) -> CustResult<(usize, String, StructInitializer)> {
        let field_name = self.expect_ident_after("struct field name after '.'")?;
        let field_index = fields
            .iter()
            .position(|field| field.name == field_name)
            .ok_or_else(|| {
                CustError::new(format!("struct '{type_name}' has no field '{field_name}'"))
            })?;
        let field = &fields[field_index];
        let value = if self.matches(&Token::Dot) {
            match &field.ty {
                StructFieldType::Struct(nested_type) => {
                    let nested_fields = self
                        .struct_types
                        .get(nested_type)
                        .map(|struct_type| struct_type.fields.clone())
                        .ok_or_else(|| {
                            CustError::new(format!("undefined struct type '{nested_type}'"))
                        })?;
                    let (_, nested_field, nested_value) =
                        self.parse_struct_designator_after_dot(nested_type, &nested_fields)?;
                    StructInitializer::Struct(vec![StructInitializer::Designated {
                        field: nested_field,
                        value: Box::new(nested_value),
                    }])
                }
                _ => {
                    return Err(CustError::new(format!(
                        "field '{}' is not a struct for path designator",
                        field.name
                    )));
                }
            }
        } else if self.check(&Token::LBracket) {
            match &field.ty {
                StructFieldType::Array(_, len) => {
                    let index = self.parse_array_designator_index_with_context(
                        &format!("array field '{}'", field.name),
                        *len,
                    )?;
                    self.expect_assign_after("array designator")?;
                    self.reject_invalid_braced_initializer_value(&format!(
                        "struct '{type_name}' initializer"
                    ))?;
                    StructInitializer::Array(vec![ArrayInitializer::Designated {
                        index,
                        value: self.parse_scalar_initializer_expr(&format!(
                            "array field '{}' element",
                            field.name
                        ))?,
                    }])
                }
                StructFieldType::StructArray(element_type, len) => {
                    let index = self.parse_array_designator_index_with_context(
                        &format!("array field '{}'", field.name),
                        *len,
                    )?;
                    if self.matches(&Token::Dot) {
                        let nested_fields = self
                            .struct_types
                            .get(element_type)
                            .map(|struct_type| struct_type.fields.clone())
                            .ok_or_else(|| {
                                CustError::new(format!("undefined struct type '{element_type}'"))
                            })?;
                        let (_, nested_field, nested_value) =
                            self.parse_struct_designator_after_dot(element_type, &nested_fields)?;
                        StructInitializer::StructArray(vec![StructArrayInitializer::Designated {
                            index,
                            value: vec![StructInitializer::Designated {
                                field: nested_field,
                                value: Box::new(nested_value),
                            }],
                        }])
                    } else {
                        self.expect_assign_after("array designator")?;
                        self.reject_missing_braced_initializer_element(&format!(
                            "struct array field '{}' initializer",
                            field.name
                        ))?;
                        StructInitializer::StructArray(vec![StructArrayInitializer::Designated {
                            index,
                            value: self.parse_struct_initializer(element_type)?,
                        }])
                    }
                }
                _ => {
                    return Err(CustError::new(format!(
                        "field '{}' is not an array for path designator",
                        field.name
                    )));
                }
            }
        } else {
            self.expect_assign_after("struct field designator")?;
            self.reject_invalid_braced_initializer_value(&format!(
                "struct '{type_name}' initializer"
            ))?;
            self.parse_struct_initializer_value(field)?
        };
        Ok((field_index, field_name, value))
    }

    fn parse_struct_initializer_value(
        &mut self,
        field: &StructFieldDef,
    ) -> CustResult<StructInitializer> {
        match &field.ty {
            StructFieldType::Array2D(elem_type, rows, columns) if self.check(&Token::LBrace) => {
                Ok(StructInitializer::Array2D(
                    self.parse_two_dimensional_array_initializer(&field.name, *rows, *columns)?,
                ))
            }
            StructFieldType::Array(elem_type, len) if self.check(&Token::LBrace) => Ok(
                StructInitializer::Array(self.parse_array_initializer(&field.name, *len)?),
            ),
            StructFieldType::Array(elem_type, len)
                if matches!(self.peek(), Token::StringLiteral(_)) =>
            {
                let init = self
                    .parse_string_literal_array_initializer(&field.name, *len, *elem_type)?
                    .expect("string literal token was checked before parsing");
                Ok(StructInitializer::Array(init))
            }
            StructFieldType::Struct(nested_type) if self.check(&Token::LBrace) => Ok(
                StructInitializer::Struct(self.parse_struct_initializer(nested_type)?),
            ),
            StructFieldType::StructArray(type_name, len) if self.check(&Token::LBrace) => {
                Ok(StructInitializer::StructArray(
                    self.parse_struct_array_initializer(&field.name, type_name, *len)?,
                ))
            }
            StructFieldType::Scalar(_) if self.check(&Token::LBrace) => {
                Ok(StructInitializer::Expr(
                    self.parse_scalar_initializer_expr(&format!("struct field '{}'", field.name))?,
                ))
            }
            _ => Ok(StructInitializer::Expr(self.parse_assignment_expr()?)),
        }
    }

    fn parse_scalar_initializer_expr(&mut self, context: &str) -> CustResult<Expr> {
        if !self.check(&Token::LBrace) {
            return self.parse_assignment_expr();
        }
        self.expect_opening_brace_after(context)?;
        self.reject_invalid_braced_initializer_value(&format!(
            "braced scalar initializer for {context}"
        ))?;
        let expr = self.parse_assignment_expr()?;
        if self.matches(&Token::Comma) {
            if self.matches(&Token::RBrace) {
                return Ok(expr);
            }
            let token = self.peek_located().clone();
            return Err(Self::error_at(
                format!("too many initializers for {context}"),
                &token,
            ));
        }
        self.expect_closing_brace_after(context)?;
        Ok(expr)
    }

    fn parse_struct_array_initializer(
        &mut self,
        name: &str,
        type_name: &str,
        len: usize,
    ) -> CustResult<Vec<StructArrayInitializer>> {
        self.reject_missing_declaration_initializer_expr("struct array declaration")?;
        self.expect_opening_brace_after("struct array initializer")?;
        let mut values = Vec::new();
        let mut next_positional_index = 0usize;
        if self.matches(&Token::RBrace) {
            return Ok(values);
        }
        loop {
            let context = format!("struct array '{name}' initializer");
            self.reject_missing_braced_initializer_element(&context)?;
            self.reject_invalid_braced_initializer_selector_element(&context, false)?;
            if self.check(&Token::LBracket) {
                let index = self.parse_array_designator_index_with_context(
                    &format!("struct array '{name}'"),
                    len,
                )?;
                self.expect_assign_after("array designator")?;
                self.reject_missing_braced_initializer_element(&context)?;
                values.push(StructArrayInitializer::Designated {
                    index,
                    value: self.parse_struct_initializer(type_name)?,
                });
                next_positional_index = index + 1;
            } else {
                if next_positional_index == len {
                    let token = self.peek_located().clone();
                    return Err(Self::error_at(
                        format!("too many initializers for struct array '{name}'"),
                        &token,
                    ));
                }
                values.push(StructArrayInitializer::Element(
                    self.parse_struct_initializer(type_name)?,
                ));
                next_positional_index += 1;
            }
            if self.matches(&Token::RBrace) {
                break;
            }
            if self.matches(&Token::Comma) {
                if self.matches(&Token::RBrace) {
                    break;
                }
                continue;
            }
            self.expect_closing_brace_after("struct array initializer")?;
        }
        Ok(values)
    }

    fn parse_aggregate_array_compound_initializer(
        &mut self,
        type_name: &str,
        len: Option<usize>,
    ) -> CustResult<Vec<StructArrayInitializer>> {
        self.expect_opening_brace_after("aggregate array compound literal initializer")?;
        let mut values = Vec::new();
        let mut next_positional_index = 0usize;
        if self.matches(&Token::RBrace) {
            return Ok(values);
        }
        loop {
            self.reject_missing_braced_initializer_element(
                "aggregate array compound literal initializer",
            )?;
            self.reject_invalid_braced_initializer_selector_element(
                "aggregate array compound literal initializer",
                false,
            )?;
            if self.check(&Token::LBracket) {
                let index = match len {
                    Some(len) => self.parse_array_designator_index_with_context(
                        "aggregate array compound literal",
                        len,
                    )?,
                    None => self.parse_unbounded_array_designator_index()?,
                };
                self.expect_assign_after("array designator")?;
                self.reject_missing_braced_initializer_element(
                    "aggregate array compound literal initializer",
                )?;
                values.push(StructArrayInitializer::Designated {
                    index,
                    value: self.parse_struct_initializer(type_name)?,
                });
                next_positional_index = index + 1;
            } else {
                if matches!(len, Some(len) if next_positional_index == len) {
                    let token = self.peek_located().clone();
                    return Err(Self::error_at(
                        "too many initializers for aggregate array compound literal".to_string(),
                        &token,
                    ));
                }
                values.push(StructArrayInitializer::Element(
                    self.parse_struct_initializer(type_name)?,
                ));
                next_positional_index += 1;
            }
            if self.matches(&Token::RBrace) {
                break;
            }
            if self.matches(&Token::Comma) {
                if self.matches(&Token::RBrace) {
                    break;
                }
                continue;
            }
            self.expect_closing_brace_after("aggregate array compound literal initializer")?;
        }
        Ok(values)
    }

    fn parse_aggregate_definition(&mut self) -> CustResult<Option<Stmt>> {
        self.pending_inline_enum_constants = None;
        self.parse_aggregate_definition_body(true, false)?;
        Ok(self.take_pending_inline_enum_decl())
    }

    fn starts_typedef_aggregate_definition(&self) -> bool {
        matches!(
            (
                self.peek(),
                self.tokens.get(self.pos + 1).map(|token| &token.kind),
                self.tokens.get(self.pos + 2).map(|token| &token.kind)
            ),
            (Token::Struct | Token::Union, Some(Token::LBrace), _)
                | (
                    Token::Struct | Token::Union,
                    Some(Token::Ident(_)),
                    Some(Token::LBrace)
                )
        )
    }

    fn starts_typedef_enum_definition(&self) -> bool {
        matches!(
            (
                self.peek(),
                self.tokens.get(self.pos + 1).map(|token| &token.kind),
                self.tokens.get(self.pos + 2).map(|token| &token.kind)
            ),
            (Token::Enum, Some(Token::LBrace), _)
                | (Token::Enum, Some(Token::Ident(_)), Some(Token::LBrace))
        )
    }

    fn starts_enum_definition_after_keyword(&self) -> bool {
        matches!(
            (
                self.peek(),
                self.tokens.get(self.pos + 1).map(|token| &token.kind)
            ),
            (Token::LBrace, _) | (Token::Ident(_), Some(Token::LBrace))
        )
    }

    fn enum_definition_followed_by_semicolon(&self) -> bool {
        if !self.starts_typedef_enum_definition() {
            return false;
        }
        let mut cursor = if matches!(
            self.tokens.get(self.pos + 1).map(|token| &token.kind),
            Some(Token::Ident(_))
        ) {
            self.pos + 2
        } else {
            self.pos + 1
        };
        if !matches!(
            self.tokens.get(cursor).map(|token| &token.kind),
            Some(Token::LBrace)
        ) {
            return false;
        }
        let mut depth = 0;
        while let Some(token) = self.tokens.get(cursor) {
            match &token.kind {
                Token::LBrace => depth += 1,
                Token::RBrace => {
                    depth -= 1;
                    if depth == 0 {
                        return matches!(
                            self.tokens.get(cursor + 1).map(|token| &token.kind),
                            Some(Token::Semi)
                        );
                    }
                }
                Token::Eof => return false,
                _ => {}
            }
            cursor += 1;
        }
        false
    }

    fn parse_aggregate_definition_body(
        &mut self,
        require_semicolon: bool,
        allow_anonymous: bool,
    ) -> CustResult<(String, AggregateKind, bool)> {
        let kind = match self.advance().kind {
            Token::Struct => AggregateKind::Struct,
            Token::Union => AggregateKind::Union,
            token => unreachable!("expected aggregate keyword, found {token:?}"),
        };
        self.parse_aggregate_definition_body_after_keyword(kind, require_semicolon, allow_anonymous)
    }

    fn parse_aggregate_definition_body_after_keyword(
        &mut self,
        kind: AggregateKind,
        require_semicolon: bool,
        allow_anonymous: bool,
    ) -> CustResult<(String, AggregateKind, bool)> {
        let keyword = kind.keyword();
        let (type_name, is_anonymous) = if allow_anonymous && self.check(&Token::LBrace) {
            let anonymous_id = self.next_aggregate_type_id;
            self.next_aggregate_type_id += 1;
            (format!("__anonymous_{keyword}#{anonymous_id}"), true)
        } else {
            (self.expect_ident_after(&format!("{keyword} name"))?, false)
        };
        let opening_brace_context = if is_anonymous {
            "anonymous aggregate typedef".to_string()
        } else {
            format!("{keyword} name")
        };
        self.expect_opening_brace_after(&opening_brace_context)?;
        let internal_type_name = if is_anonymous {
            type_name.clone()
        } else {
            if self
                .aggregate_type_scopes
                .last()
                .expect("parser always has an aggregate type scope")
                .contains_key(&type_name)
            {
                return Err(CustError::new(format!(
                    "{keyword} '{type_name}' already declared"
                )));
            }
            if self.struct_types.contains_key(&type_name) {
                let name = format!("{}#{}", type_name, self.next_aggregate_type_id);
                self.next_aggregate_type_id += 1;
                name
            } else {
                type_name.clone()
            }
        };
        if !is_anonymous {
            self.aggregate_type_scopes
                .last_mut()
                .expect("parser always has an aggregate type scope")
                .insert(type_name.clone(), internal_type_name.clone());
        }
        let mut fields = Vec::new();
        let mut names = HashSet::new();
        while !self.check(&Token::RBrace) {
            if self.check(&Token::Eof) {
                return Err(Self::error_at(
                    format!("unterminated {keyword} declaration for '{type_name}'"),
                    self.peek_located(),
                ));
            }
            self.consume_alignment_specifiers()?;
            self.reject_leading_restrict_qualifier()?;
            if self.check(&Token::Void) {
                return Err(Self::error_at(
                    "void object declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let (leading_const, last_qualifier) = self.consume_type_qualifiers_with_last();
            self.reject_missing_type_after_qualifier(
                &format!("{keyword} field type"),
                last_qualifier.as_ref(),
            )?;
            let alias_const = match self.peek() {
                Token::Ident(name) => self.type_alias_is_const(name),
                _ => false,
            };
            let leading_const = leading_const || alias_const;
            let decl_type = if matches!(self.peek(), Token::Struct | Token::Union) {
                if matches!(self.peek_next(), Token::LBrace)
                    || matches!(
                        self.tokens.get(self.pos + 2).map(|token| &token.kind),
                        Some(Token::LBrace)
                    )
                {
                    let (field_internal_type_name, _, _) =
                        self.parse_aggregate_definition_body(false, true)?;
                    DeclType::Struct(field_internal_type_name)
                } else {
                    let field_kind = match self.advance().kind {
                        Token::Struct => AggregateKind::Struct,
                        Token::Union => AggregateKind::Union,
                        token => unreachable!("expected aggregate field type, found {token:?}"),
                    };
                    let field_keyword = field_kind.keyword();
                    let field_type_name =
                        self.expect_ident_after(&format!("{field_keyword} field type"))?;
                    let Some(field_internal_type_name) =
                        self.resolve_aggregate_type(&field_type_name)
                    else {
                        return Err(CustError::new(format!(
                            "undefined {field_keyword} type '{field_type_name}'"
                        )));
                    };
                    DeclType::Struct(field_internal_type_name)
                }
            } else {
                self.parse_decl_type(&format!("{keyword} field type"))?
            };
            loop {
                let has_explicit_star = self.matches(&Token::Star);
                let post_star_const = has_explicit_star && self.consume_type_qualifiers();
                if has_explicit_star && self.check(&Token::Star) {
                    return Err(Self::error_at(
                        format!("pointer-to-pointer {keyword} fields are not supported"),
                        self.peek_located(),
                    ));
                }
                let is_pointer = has_explicit_star || matches!(decl_type, DeclType::Pointer { .. });
                let (is_const, points_to_const) = if is_pointer {
                    if has_explicit_star {
                        (post_star_const, leading_const)
                    } else {
                        (leading_const, Self::decl_type_points_to_const(&decl_type))
                    }
                } else {
                    (leading_const, false)
                };
                let ty = match decl_type.clone() {
                    DeclType::Scalar(ty) if has_explicit_star => {
                        StructFieldType::Pointer(PointeeType::Scalar(ty))
                    }
                    DeclType::Struct(type_name) if has_explicit_star => {
                        StructFieldType::Pointer(PointeeType::Struct(type_name))
                    }
                    DeclType::Pointer { .. } if has_explicit_star => {
                        return Err(Self::error_at(
                            format!("pointer-to-pointer {keyword} fields are not supported"),
                            self.previous(),
                        ));
                    }
                    DeclType::Pointer { pointee, .. } => StructFieldType::Pointer(pointee),
                    DeclType::Array(PointeeType::Scalar(ty), len) => {
                        StructFieldType::Array(ty, len)
                    }
                    DeclType::Array(PointeeType::Struct(type_name), len) => {
                        StructFieldType::StructArray(type_name, len)
                    }
                    DeclType::Array2D(ty, rows, columns) => {
                        StructFieldType::Array2D(ty, rows, columns)
                    }
                    DeclType::Array2DPointer { .. } => {
                        return Err(Self::error_at(
                            "pointer-to-row aggregate fields are not supported".to_string(),
                            self.previous(),
                        ));
                    }
                    DeclType::Scalar(ty) => StructFieldType::Scalar(ty),
                    DeclType::Struct(type_name) => StructFieldType::Struct(type_name),
                };
                if !has_explicit_star
                    && self.check(&Token::LParen)
                    && matches!(self.peek_next(), Token::Star)
                {
                    if self.parenthesized_pointer_declarator_is_function_at(self.pos) {
                        return Err(Self::error_at(
                            "function pointer aggregate fields are not supported".to_string(),
                            self.peek_located(),
                        ));
                    }
                    return Err(Self::error_at(
                        "parenthesized pointer aggregate fields are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                let name =
                    self.parse_declarator_name(&format!("{keyword} field name after type"))?;
                if self.check(&Token::Colon) {
                    return Err(Self::error_at(
                        "bit-field aggregate fields are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                if !names.insert(name.clone()) {
                    return Err(Self::error_at(
                        format!("duplicate {keyword} field '{name}'"),
                        self.previous(),
                    ));
                }
                let ty = if self.matches(&Token::LBracket) {
                    if self.check(&Token::RBracket) {
                        return Err(Self::error_at(
                            "flexible array aggregate fields are not supported".to_string(),
                            self.peek_located(),
                        ));
                    }
                    match ty {
                        StructFieldType::Scalar(elem_type) => {
                            let rows = self.expect_array_len()?;
                            self.expect_closing_bracket_after("struct array field length")?;
                            if self.matches(&Token::LBracket) {
                                let columns = self.expect_array_len()?;
                                self.expect_closing_bracket_after(
                                    "second struct array field dimension",
                                )?;
                                if self.check(&Token::LBracket) {
                                    return Err(Self::error_at(
                                        format!(
                                            "array {keyword} fields with more than two dimensions are not supported"
                                        ),
                                        self.peek_located(),
                                    ));
                                }
                                StructFieldType::Array2D(elem_type, rows, columns)
                            } else {
                                StructFieldType::Array(elem_type, rows)
                            }
                        }
                        StructFieldType::Struct(type_name) => {
                            let len = self.expect_array_len()?;
                            self.expect_closing_bracket_after("struct array field length")?;
                            if self.check(&Token::LBracket) {
                                return Err(Self::error_at(
                                    format!(
                                        "multidimensional array {keyword} fields are not supported"
                                    ),
                                    self.peek_located(),
                                ));
                            }
                            StructFieldType::StructArray(type_name, len)
                        }
                        StructFieldType::Pointer(_) => {
                            return Err(Self::error_at(
                                format!("pointer array {keyword} fields are not supported"),
                                self.previous(),
                            ));
                        }
                        StructFieldType::Array(_, _)
                        | StructFieldType::Array2D(_, _, _)
                        | StructFieldType::StructArray(_, _) => {
                            unreachable!("array field not built yet")
                        }
                    }
                } else {
                    ty
                };
                fields.push(StructFieldDef {
                    name,
                    ty,
                    is_const,
                    points_to_const,
                });
                if !self.matches(&Token::Comma) {
                    break;
                }
            }
            self.expect_semicolon_after("struct field declaration")?;
        }
        self.expect(Token::RBrace)?;
        if require_semicolon {
            self.expect_semicolon_after(&format!("{keyword} declaration"))?;
        }
        self.struct_types.insert(
            internal_type_name.clone(),
            StructTypeDef {
                fields,
                kind,
                display_name: type_name.clone(),
            },
        );
        Ok((internal_type_name, kind, is_anonymous))
    }

    fn parse_aggregate_var_decl(&mut self) -> CustResult<Stmt> {
        self.pending_inline_enum_constants = None;
        self.last_decl_had_initializer = false;
        self.consume_alignment_specifiers()?;
        let leading_const = self.consume_type_qualifiers();
        if matches!(
            (
                self.peek(),
                self.tokens.get(self.pos + 1).map(|token| &token.kind)
            ),
            (Token::Struct | Token::Union, Some(Token::LBrace))
        ) {
            let (type_name, kind, _) = self.parse_aggregate_definition_body(false, true)?;
            let points_to_const = leading_const || self.consume_type_qualifiers();
            let stmt =
                self.parse_aggregate_var_decl_after_type(kind, type_name, points_to_const)?;
            return Ok(self.with_pending_inline_enum_decl(stmt));
        }

        if matches!(
            (
                self.peek(),
                self.tokens.get(self.pos + 1).map(|token| &token.kind),
                self.tokens.get(self.pos + 2).map(|token| &token.kind)
            ),
            (
                Token::Struct | Token::Union,
                Some(Token::Ident(_)),
                Some(Token::LBrace)
            )
        ) {
            let (type_name, kind, _) = self.parse_aggregate_definition_body(false, false)?;
            let points_to_const = leading_const || self.consume_type_qualifiers();
            let stmt =
                self.parse_aggregate_var_decl_after_type(kind, type_name, points_to_const)?;
            return Ok(self.with_pending_inline_enum_decl(stmt));
        }

        let kind = match self.advance().kind {
            Token::Struct => AggregateKind::Struct,
            Token::Union => AggregateKind::Union,
            token => unreachable!("expected aggregate keyword, found {token:?}"),
        };
        let keyword = kind.keyword();
        let type_name = self.expect_ident_after(&format!("{keyword} type name"))?;
        let Some(internal_type_name) = self.resolve_aggregate_type(&type_name) else {
            return Err(CustError::new(format!(
                "undefined {keyword} type '{type_name}'"
            )));
        };
        let points_to_const = leading_const || self.consume_type_qualifiers();
        let stmt =
            self.parse_aggregate_var_decl_after_type(kind, internal_type_name, points_to_const)?;
        Ok(self.with_pending_inline_enum_decl(stmt))
    }

    fn parse_aggregate_var_decl_after_type(
        &mut self,
        kind: AggregateKind,
        type_name: String,
        points_to_const: bool,
    ) -> CustResult<Stmt> {
        let keyword = kind.keyword();
        if self.matches(&Token::Star) {
            let is_const = self.consume_type_qualifiers();
            if self.check(&Token::Star) {
                return Err(Self::error_at(
                    "pointer-to-pointer declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let name = self.parse_declarator_name(&format!("{keyword} pointer name after '*'"))?;
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "pointer array declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            let expr = if self.matches(&Token::Assign) {
                self.last_decl_had_initializer = true;
                self.reject_missing_declaration_initializer_expr(&format!(
                    "{keyword} pointer declaration"
                ))?;
                self.parse_assignment_expr()?
            } else if matches!(self.peek(), Token::Semi | Token::Comma) {
                Expr::Number(0)
            } else {
                self.expect_assign_after(&format!("{keyword} pointer declaration"))?;
                unreachable!("expect_assign_after only returns Ok after consuming '='")
            };
            let stmt = Stmt::PointerDecl {
                name,
                ty: PointeeType::Struct(type_name.clone()),
                expr,
                is_const,
                points_to_const,
            };
            if self.matches(&Token::Comma) {
                return self.parse_declarator_list_tail(
                    stmt,
                    DeclType::Struct(type_name),
                    points_to_const,
                );
            }
            self.expect_semicolon_after(&format!("{keyword} pointer declaration"))?;
            return Ok(stmt);
        }
        if self.check(&Token::LParen) && matches!(self.peek_next(), Token::Star) {
            if self.parenthesized_pointer_declarator_is_function_at(self.pos) {
                return Err(Self::error_at(
                    "function pointer declarations are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            return Err(Self::error_at(
                "parenthesized pointer declarations are not supported".to_string(),
                self.peek_located(),
            ));
        }
        let name = self.parse_declarator_name(&format!("{keyword} variable name"))?;
        if self.matches(&Token::LBracket) {
            let (len, init) = if self.matches(&Token::RBracket) {
                if !self.matches(&Token::Assign) {
                    self.expect_assign_after("inferred aggregate array declaration")?;
                    unreachable!("expect_assign_after only returns Ok after consuming '='")
                }
                self.last_decl_had_initializer = true;
                self.reject_missing_declaration_initializer_expr(
                    "inferred aggregate array declaration",
                )?;
                let init = self.parse_aggregate_array_compound_initializer(&type_name, None)?;
                let len = Self::infer_struct_array_initializer_len(&init);
                (len, init)
            } else {
                let len = self.expect_array_len()?;
                self.expect_closing_bracket_after("struct array length")?;
                let init = if self.matches(&Token::Assign) {
                    self.last_decl_had_initializer = true;
                    self.parse_struct_array_initializer(&name, &type_name, len)?
                } else {
                    Vec::new()
                };
                (len, init)
            };
            let stmt = Stmt::StructArrayDecl {
                type_name: type_name.clone(),
                name,
                len,
                init,
                is_const: points_to_const,
            };
            if self.matches(&Token::Comma) {
                return self.parse_declarator_list_tail(
                    stmt,
                    DeclType::Struct(type_name),
                    points_to_const,
                );
            }
            self.expect_semicolon_after(&format!("{keyword} array declaration"))?;
            return Ok(stmt);
        }
        let init = if self.matches(&Token::Assign) {
            self.last_decl_had_initializer = true;
            if self.check(&Token::LBrace) {
                Some(StructVarInitializer::Fields(
                    self.parse_struct_initializer(&type_name)?,
                ))
            } else {
                self.reject_missing_declaration_initializer_expr(&format!(
                    "{keyword} variable declaration"
                ))?;
                Some(StructVarInitializer::Expr(self.parse_assignment_expr()?))
            }
        } else {
            None
        };
        let stmt = Stmt::StructVarDecl {
            type_name: type_name.clone(),
            name,
            init,
            is_const: points_to_const,
        };
        if self.matches(&Token::Comma) {
            return self.parse_declarator_list_tail(
                stmt,
                DeclType::Struct(type_name),
                points_to_const,
            );
        }
        self.expect_semicolon_after(&format!("{keyword} variable declaration"))?;
        Ok(stmt)
    }

    fn parse_enum_decl(&mut self) -> CustResult<Stmt> {
        let constants = self.parse_enum_decl_body(true)?;
        Ok(Stmt::EnumDecl { constants })
    }

    fn parse_enum_decl_body(&mut self, require_semicolon: bool) -> CustResult<Vec<EnumConstant>> {
        self.expect(Token::Enum)?;
        self.parse_enum_decl_body_after_keyword(require_semicolon)
    }

    fn parse_enum_decl_body_after_keyword(
        &mut self,
        require_semicolon: bool,
    ) -> CustResult<Vec<EnumConstant>> {
        let enum_tag = if let Token::Ident(name) = self.peek().clone() {
            self.advance();
            Some(name)
        } else {
            None
        };
        self.expect_opening_brace_after("enum")?;

        let mut constants = Vec::new();
        let mut local_constants = HashMap::new();
        let mut names = HashSet::new();
        let mut next_value = 0;
        while !self.check(&Token::RBrace) {
            if self.check(&Token::Eof) {
                let eof = self.peek_located().clone();
                return Err(Self::error_at(
                    "unterminated enum declaration".to_string(),
                    &eof,
                ));
            }

            let name_token = self.advance();
            let name = match name_token.kind.clone() {
                Token::Ident(name) => name,
                token => {
                    return Err(Self::error_at(
                        format!("expected enum constant name, found {token:?}"),
                        &name_token,
                    ));
                }
            };
            if !names.insert(name.clone()) {
                return Err(Self::error_at(
                    format!("duplicate enum constant '{name}'"),
                    &name_token,
                ));
            }

            let value = if self.matches(&Token::Assign) {
                self.last_decl_had_initializer = true;
                self.parse_enum_constant_value(&local_constants)?
            } else {
                next_value
            };
            next_value = value + 1;
            local_constants.insert(name.clone(), value);
            constants.push(EnumConstant { name, value });

            if self.matches(&Token::Comma) {
                if self.check(&Token::RBrace) {
                    break;
                }
            } else if self.check(&Token::RBrace) {
                break;
            } else {
                return Err(Self::error_at(
                    format!(
                        "expected ',' or '}}' after enum constant, found {:?}",
                        self.peek()
                    ),
                    self.peek_located(),
                ));
            }
        }
        self.expect(Token::RBrace)?;
        if require_semicolon {
            self.expect_semicolon_after("enum declaration")?;
        }
        match enum_tag {
            Some(enum_tag)
                if !self
                    .enum_type_scopes
                    .last_mut()
                    .expect("parser always has an enum type scope")
                    .insert(enum_tag.clone()) =>
            {
                return Err(CustError::new(format!(
                    "enum '{enum_tag}' already declared"
                )));
            }
            _ => {}
        }
        self.enum_constant_scopes
            .last_mut()
            .expect("parser always has an enum constant scope")
            .extend(local_constants);
        Ok(constants)
    }

    fn parse_enum_constant_value(
        &mut self,
        local_constants: &HashMap<String, i64>,
    ) -> CustResult<i64> {
        if self.check(&Token::LBracket) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected integer constant after enum constant '=' before '['".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Question) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected integer constant after enum constant '=' before '?'".to_string(),
                &found,
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_or_selector_label() {
            let found = self.advance();
            return Err(Self::error_at(
                format!("expected integer constant after enum constant '=' before '{label}'"),
                &found,
            ));
        }
        let (value, _) = self.parse_integer_constant_expr(
            local_constants,
            "expected integer constant after enum constant '='",
        )?;
        Ok(value)
    }

    fn parse_integer_constant_expr(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        self.parse_integer_constant_conditional(local_constants, context)
    }

    fn parse_integer_constant_conditional(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (condition, first_token) =
            self.parse_integer_constant_logical_or(local_constants, context)?;
        if self.matches(&Token::Question) {
            let (then_value, _) = self.parse_integer_constant_expr(
                local_constants,
                "expected integer constant in conditional expression",
            )?;
            self.expect_colon_after("conditional expression")?;
            let (else_value, _) = self.parse_integer_constant_conditional(
                local_constants,
                "expected integer constant in conditional expression",
            )?;
            return Ok((
                if condition != 0 {
                    then_value
                } else {
                    else_value
                },
                first_token,
            ));
        }
        Ok((condition, first_token))
    }

    fn parse_integer_constant_logical_or(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_logical_and(local_constants, context)?;
        while self.matches(&Token::OrOr) {
            let (rhs, _) = self.parse_integer_constant_logical_and(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            value = i64::from(value != 0 || rhs != 0);
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_logical_and(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_bitwise_or(local_constants, context)?;
        while self.matches(&Token::AndAnd) {
            let (rhs, _) = self.parse_integer_constant_bitwise_or(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            value = i64::from(value != 0 && rhs != 0);
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_bitwise_or(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_bitwise_xor(local_constants, context)?;
        while self.matches(&Token::Pipe) {
            let (rhs, _) = self.parse_integer_constant_bitwise_xor(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            value |= rhs;
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_bitwise_xor(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_bitwise_and(local_constants, context)?;
        while self.matches(&Token::Caret) {
            let (rhs, _) = self.parse_integer_constant_bitwise_and(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            value ^= rhs;
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_bitwise_and(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_equality(local_constants, context)?;
        while self.matches(&Token::Amp) {
            let (rhs, _) = self.parse_integer_constant_equality(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            value &= rhs;
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_equality(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_relational(local_constants, context)?;
        while self.matches(&Token::Eq) || self.matches(&Token::Ne) {
            let op = self.previous().kind.clone();
            let (rhs, _) = self.parse_integer_constant_relational(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            value = match op {
                Token::Eq => i64::from(value == rhs),
                Token::Ne => i64::from(value != rhs),
                _ => unreachable!("only equality operators are matched above"),
            };
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_relational(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_shift(local_constants, context)?;
        while self.matches(&Token::Lt)
            || self.matches(&Token::Le)
            || self.matches(&Token::Gt)
            || self.matches(&Token::Ge)
        {
            let op = self.previous().kind.clone();
            let (rhs, _) = self.parse_integer_constant_shift(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            value = match op {
                Token::Lt => i64::from(value < rhs),
                Token::Le => i64::from(value <= rhs),
                Token::Gt => i64::from(value > rhs),
                Token::Ge => i64::from(value >= rhs),
                _ => unreachable!("only relational operators are matched above"),
            };
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_shift(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_additive(local_constants, context)?;
        while self.matches(&Token::ShiftLeft) || self.matches(&Token::ShiftRight) {
            let op = self.previous().kind.clone();
            let op_token = self.previous().clone();
            let (rhs, _) = self.parse_integer_constant_additive(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            if rhs < 0 {
                return Err(Self::error_at(
                    "shift count must be non-negative".to_string(),
                    &op_token,
                ));
            }
            match op {
                Token::ShiftLeft => value <<= rhs,
                Token::ShiftRight => value >>= rhs,
                _ => unreachable!("only shift operators are matched above"),
            }
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_additive(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_multiplicative(local_constants, context)?;
        while self.matches(&Token::Plus) || self.matches(&Token::Minus) {
            let op = self.previous().kind.clone();
            let (rhs, _) = self.parse_integer_constant_multiplicative(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            match op {
                Token::Plus => value += rhs,
                Token::Minus => value -= rhs,
                _ => unreachable!("only plus/minus are matched above"),
            }
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_multiplicative(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        let (mut value, first_token) =
            self.parse_integer_constant_unary(local_constants, context)?;
        while self.matches(&Token::Star)
            || self.matches(&Token::Slash)
            || self.matches(&Token::Percent)
        {
            let op = self.previous().kind.clone();
            let op_token = self.previous().clone();
            let (rhs, _) = self.parse_integer_constant_unary(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            match op {
                Token::Star => value *= rhs,
                Token::Slash => {
                    if rhs == 0 {
                        return Err(Self::error_at("division by zero".to_string(), &op_token));
                    }
                    value /= rhs;
                }
                Token::Percent => {
                    if rhs == 0 {
                        return Err(Self::error_at("division by zero".to_string(), &op_token));
                    }
                    value %= rhs;
                }
                _ => unreachable!("only multiplicative operators are matched above"),
            }
        }
        Ok((value, first_token))
    }

    fn parse_integer_constant_unary(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        if self.matches(&Token::Plus)
            || self.matches(&Token::Minus)
            || self.matches(&Token::Tilde)
            || self.matches(&Token::Bang)
        {
            let op_token = self.previous().clone();
            self.reject_missing_integer_constant_unary_operand(&op_token)?;
            let (value, _) = self.parse_integer_constant_unary(
                local_constants,
                "expected integer constant in integer constant expression",
            )?;
            let value = match op_token.kind {
                Token::Plus => value,
                Token::Minus => -value,
                Token::Tilde => !value,
                Token::Bang => i64::from(value == 0),
                _ => unreachable!("only unary constant operators are matched above"),
            };
            return Ok((value, op_token));
        }
        if self.matches(&Token::Sizeof) {
            return self.parse_integer_constant_sizeof(local_constants);
        }
        if self.matches(&Token::Alignof) {
            return self.parse_integer_constant_alignof();
        }
        if self.check(&Token::LParen) && self.starts_cast_type_after_lparen() {
            return self.parse_integer_constant_cast(local_constants);
        }
        self.parse_integer_constant_primary(local_constants, context)
    }

    fn parse_integer_constant_cast(
        &mut self,
        local_constants: &HashMap<String, i64>,
    ) -> CustResult<(i64, LocatedToken)> {
        let opening = self.advance();
        self.consume_type_qualifiers();
        let type_token = self.peek_located().clone();
        let decl_type = self.parse_decl_type("integer constant expression cast type")?;
        match decl_type {
            DeclType::Scalar(_) => {}
            DeclType::Struct(_) => {
                return Err(Self::error_at(
                    "aggregate casts are not supported".to_string(),
                    &type_token,
                ));
            }
            DeclType::Pointer { .. }
            | DeclType::Array(_, _)
            | DeclType::Array2D(_, _, _)
            | DeclType::Array2DPointer { .. } => {
                return Err(Self::error_at(
                    "pointer casts are not supported".to_string(),
                    &type_token,
                ));
            }
        }
        self.expect_closing_paren_after("integer constant expression cast type")?;
        self.reject_missing_integer_constant_cast_operand()?;
        let (value, _) = self.parse_integer_constant_unary(
            local_constants,
            "expected integer constant in integer constant expression",
        )?;
        Ok((value, opening))
    }

    fn reject_missing_integer_constant_cast_operand(&self) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::RParen
                | Token::RBracket
                | Token::RBrace
                | Token::Semi
                | Token::Colon
                | Token::Comma
                | Token::LBracket
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::Eof
        ) || self.integer_constant_invalid_start_label().is_some()
        {
            return Err(Self::error_at(
                format!(
                    "expected integer constant after cast, found {:?}",
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn reject_missing_integer_constant_unary_operand(
        &self,
        operator: &LocatedToken,
    ) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::RParen
                | Token::RBracket
                | Token::RBrace
                | Token::Semi
                | Token::Colon
                | Token::Comma
                | Token::LBracket
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::Eof
        ) || self.integer_constant_invalid_start_label().is_some()
        {
            return Err(Self::error_at(
                format!(
                    "expected integer constant after unary operator '{}', found {:?}",
                    Self::unary_operator_label(&operator.kind),
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn infer_array_initializer_len(init: &[ArrayInitializer]) -> usize {
        let mut len = 0usize;
        let mut next_positional_index = 0usize;
        for initializer in init {
            match initializer {
                ArrayInitializer::Expr(_) => {
                    len = len.max(next_positional_index + 1);
                    next_positional_index += 1;
                }
                ArrayInitializer::Designated { index, .. } => {
                    len = len.max(index + 1);
                    next_positional_index = index + 1;
                }
                ArrayInitializer::StringLiteral(values) => {
                    len = len.max(values.len());
                    next_positional_index = values.len();
                }
            }
        }
        len
    }

    fn infer_struct_array_initializer_len(init: &[StructArrayInitializer]) -> usize {
        let mut len = 0usize;
        let mut next_positional_index = 0usize;
        for initializer in init {
            match initializer {
                StructArrayInitializer::Element(_) => {
                    len = len.max(next_positional_index + 1);
                    next_positional_index += 1;
                }
                StructArrayInitializer::Designated { index, .. } => {
                    len = len.max(index + 1);
                    next_positional_index = index + 1;
                }
            }
        }
        len
    }

    fn parse_integer_constant_sizeof(
        &mut self,
        local_constants: &HashMap<String, i64>,
    ) -> CustResult<(i64, LocatedToken)> {
        let operator = self.previous().clone();
        if self.matches(&Token::LParen) {
            if self.is_type_name_start() {
                let sizeof_type = self.parse_sizeof_like_type_name("sizeof")?;
                self.expect_closing_paren_after("sizeof type")?;
                let value = sizeof_type
                    .size(&self.struct_types)
                    .map_err(|err| Self::error_at(err.to_string(), &operator))?;
                return Ok((value, operator));
            }
            let expr = self.parse_expr()?;
            self.expect_closing_paren_after("sizeof expression")?;
            let value = self
                .sizeof_integer_constant_expr(&expr, local_constants)
                .map_err(|err| Self::error_at(err.to_string(), &operator))?;
            return Ok((value, operator));
        }

        let expr = self.parse_unary()?;
        let value = self
            .sizeof_integer_constant_expr(&expr, local_constants)
            .map_err(|err| Self::error_at(err.to_string(), &operator))?;
        Ok((value, operator))
    }

    fn sizeof_integer_constant_expr(
        &self,
        expr: &Expr,
        local_constants: &HashMap<String, i64>,
    ) -> CustResult<i64> {
        match expr {
            Expr::Number(_) => Ok(INT_SIZE),
            Expr::StringLiteral(values) => Ok(values.len() as i64 * CHAR_SIZE),
            Expr::SizeOfType(sizeof_type) => sizeof_type.size(&self.struct_types),
            Expr::SizeOfValue(inner) => self.sizeof_integer_constant_expr(inner, local_constants),
            Expr::AlignOfType(_) => Ok(INT_SIZE),
            Expr::Var(name) => {
                if local_constants.contains_key(name) || self.lookup_enum_constant(name).is_some() {
                    Ok(INT_SIZE)
                } else {
                    Err(CustError::new(format!(
                        "unsupported sizeof expression in integer constant expression: variable '{name}'"
                    )))
                }
            }
            Expr::UnaryPlus(inner)
            | Expr::UnaryMinus(inner)
            | Expr::BitwiseNot(inner)
            | Expr::LogicalNot(inner)
            | Expr::Cast { expr: inner, .. } => {
                self.sizeof_integer_constant_expr(inner, local_constants)?;
                Ok(INT_SIZE)
            }
            Expr::Binary(left, _, right) | Expr::Comma(left, right) => {
                self.sizeof_integer_constant_expr(left, local_constants)?;
                self.sizeof_integer_constant_expr(right, local_constants)?;
                Ok(INT_SIZE)
            }
            Expr::Conditional {
                cond,
                then_expr,
                else_expr,
            } => {
                self.sizeof_integer_constant_expr(cond, local_constants)?;
                self.sizeof_integer_constant_expr(then_expr, local_constants)?;
                self.sizeof_integer_constant_expr(else_expr, local_constants)?;
                Ok(INT_SIZE)
            }
            Expr::ScalarLiteral { ty, init }
            | Expr::ScalarLiteralSet { ty, init, .. }
            | Expr::ScalarLiteralCompoundSet { ty, init, .. } => {
                self.sizeof_integer_constant_expr(init, local_constants)?;
                Ok(ty.size())
            }
            Expr::ArrayLiteral {
                elem_type,
                len,
                init,
                ..
            } => {
                let len = len.unwrap_or_else(|| Self::infer_array_initializer_len(init));
                Ok(len as i64 * elem_type.size())
            }
            Expr::AggregateLiteral { type_name, .. } => self
                .struct_types
                .get(type_name)
                .map(|struct_type| struct_type.size(&self.struct_types))
                .transpose()?
                .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
            Expr::AggregateArrayLiteral {
                type_name,
                len,
                init,
                ..
            } => {
                let len = len.unwrap_or_else(|| Self::infer_struct_array_initializer_len(init));
                let element_size = self
                    .struct_types
                    .get(type_name)
                    .map(|struct_type| struct_type.size(&self.struct_types))
                    .transpose()?
                    .ok_or_else(|| {
                        CustError::new(format!("undefined struct type '{type_name}'"))
                    })?;
                Ok(len as i64 * element_size)
            }
            _ => Err(CustError::new(
                "unsupported sizeof expression in integer constant expression",
            )),
        }
    }

    fn parse_integer_constant_alignof(&mut self) -> CustResult<(i64, LocatedToken)> {
        let operator = self.previous().clone();
        self.expect_opening_paren_after("_Alignof")?;
        self.reject_missing_alignof_type()?;
        let alignof_type = self.parse_sizeof_like_type_name("_Alignof")?;
        self.expect_closing_paren_after("_Alignof type")?;
        let value = alignof_type
            .alignment(&self.struct_types)
            .map_err(|err| Self::error_at(err.to_string(), &operator))?;
        Ok((value, operator))
    }

    fn parse_integer_constant_primary(
        &mut self,
        local_constants: &HashMap<String, i64>,
        context: &str,
    ) -> CustResult<(i64, LocatedToken)> {
        if self.matches(&Token::LParen) {
            let opening = self.previous().clone();
            let context = "expected integer constant in parenthesized integer constant expression";
            if let Some(label) = self.parenthesized_integer_constant_invalid_start_label() {
                let found = self.advance();
                return Err(Self::error_at(
                    format!("{context} before '{label}'"),
                    &found,
                ));
            }
            let (value, _) = self.parse_integer_constant_expr(local_constants, context)?;
            if self.check(&Token::Comma) {
                let comma = self.peek_located().clone();
                return Err(Self::error_at(
                    "comma operator is not allowed in integer constant expression".to_string(),
                    &comma,
                ));
            }
            self.expect_closing_paren_after("integer constant expression")?;
            return Ok((value, opening));
        }

        let found = self.advance();
        match &found.kind {
            Token::Number(value) => Ok((*value, found)),
            Token::PreprocessorNumber(value) if value.bits <= i64::MAX as u64 => {
                Ok((value.bits as i64, found))
            }
            Token::PreprocessorNumber(_) => Err(Self::error_at(
                "integer literal out of range".to_string(),
                &found,
            )),
            Token::Ident(name) => local_constants
                .get(name)
                .copied()
                .or_else(|| self.lookup_enum_constant(name))
                .map(|value| (value, found.clone()))
                .ok_or_else(|| {
                    if context == "expected array length" {
                        Self::error_at(
                            "array length must be an integer constant expression".to_string(),
                            &found,
                        )
                    } else {
                        Self::error_at(format!("{context}, found {:?}", found.kind), &found)
                    }
                }),
            token => Err(Self::error_at(
                format!("{context}, found {token:?}"),
                &found,
            )),
        }
    }

    fn parenthesized_integer_constant_invalid_start_label(&self) -> Option<&'static str> {
        match self.peek() {
            Token::RParen => Some(")"),
            Token::Comma => Some(","),
            Token::Colon => Some(":"),
            Token::RBracket => Some("]"),
            Token::RBrace => Some("}"),
            Token::Semi => Some(";"),
            Token::LBracket => Some("["),
            Token::Question => Some("?"),
            Token::Dot => Some("."),
            Token::Arrow => Some("->"),
            _ => self.integer_constant_invalid_start_label(),
        }
    }

    fn integer_constant_invalid_start_label(&self) -> Option<&'static str> {
        match self.peek() {
            Token::Int => Some("int"),
            Token::Char => Some("char"),
            Token::Bool => Some("_Bool"),
            Token::Float => Some("float"),
            Token::Double => Some("double"),
            Token::Complex => Some("_Complex"),
            Token::Imaginary => Some("_Imaginary"),
            Token::Signed => Some("signed"),
            Token::Unsigned => Some("unsigned"),
            Token::Long => Some("long"),
            Token::Short => Some("short"),
            Token::Const => Some("const"),
            Token::Volatile => Some("volatile"),
            Token::Restrict => Some("restrict"),
            Token::Atomic => Some("_Atomic"),
            Token::Static => Some("static"),
            Token::Extern => Some("extern"),
            Token::ThreadLocal => Some("_Thread_local"),
            Token::Inline => Some("inline"),
            Token::Noreturn => Some("_Noreturn"),
            Token::Auto => Some("auto"),
            Token::Register => Some("register"),
            Token::Void => Some("void"),
            Token::Enum => Some("enum"),
            Token::Struct => Some("struct"),
            Token::Union => Some("union"),
            Token::Typedef => Some("typedef"),
            Token::Alignas => Some("_Alignas"),
            Token::StaticAssert => Some("_Static_assert"),
            Token::Generic => Some("_Generic"),
            Token::Return => Some("return"),
            Token::If => Some("if"),
            Token::Else => Some("else"),
            Token::While => Some("while"),
            Token::Do => Some("do"),
            Token::For => Some("for"),
            Token::Switch => Some("switch"),
            Token::Case => Some("case"),
            Token::Default => Some("default"),
            Token::Break => Some("break"),
            Token::Continue => Some("continue"),
            Token::Goto => Some("goto"),
            _ => None,
        }
    }

    fn integer_constant_invalid_start_or_selector_label(&self) -> Option<&'static str> {
        match self.peek() {
            Token::LBrace => Some("{"),
            Token::Colon => Some(":"),
            Token::Dot => Some("."),
            Token::Arrow => Some("->"),
            _ => self.integer_constant_invalid_start_label(),
        }
    }

    fn expect_array_len(&mut self) -> CustResult<usize> {
        if self.check(&Token::RBracket) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array length before ']'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::RParen) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array length before ')'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Semi) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array length before ';'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::RBrace) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array length before '}'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Question) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array length before '?'".to_string(),
                &found,
            ));
        }
        if self.check(&Token::LBracket) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected array length before '['".to_string(),
                &found,
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_or_selector_label() {
            let found = self.advance();
            return Err(Self::error_at(
                format!("expected array length before '{label}'"),
                &found,
            ));
        }
        if self.check(&Token::Star) {
            let found = self.advance();
            return Err(Self::error_at(
                "variable length array declarators are not supported".to_string(),
                &found,
            ));
        }

        let (value, first_token) =
            self.parse_integer_constant_expr(&HashMap::new(), "expected array length")?;
        if self.check(&Token::Comma) {
            let comma = self.peek_located().clone();
            return Err(Self::error_at(
                "comma operator is not allowed in integer constant expression".to_string(),
                &comma,
            ));
        }
        if value <= 0 {
            return Err(Self::error_at(
                "array length must be positive".to_string(),
                &first_token,
            ));
        }
        usize::try_from(value)
            .map_err(|_| Self::error_at("array length is too large".to_string(), &first_token))
    }

    fn parse_assign(&mut self) -> CustResult<Stmt> {
        self.parse_assign_with_semi(true)
    }

    fn parse_deref_assign(&mut self) -> CustResult<Stmt> {
        self.expect(Token::Star)?;
        let pointer = self.parse_unary()?;
        if let Some(op) = self.compound_assignment_op() {
            let operator = self.advance();
            self.reject_missing_assignment_rhs(&operator)?;
            let value = self.parse_expr()?;
            self.expect_semicolon_after("assignment")?;
            return Ok(
                self.with_pending_inline_enum_decl(Stmt::Expr(Expr::DerefCompoundSet {
                    pointer: Box::new(pointer),
                    op,
                    value: Box::new(value),
                })),
            );
        }
        let equals = self.expect_assignment_operator_after("assignment")?;
        self.reject_missing_assignment_rhs(&equals)?;
        let value = self.parse_expr()?;
        self.expect_semicolon_after("assignment")?;
        Ok(self.with_pending_inline_enum_decl(Stmt::DerefAssign { pointer, value }))
    }

    fn parse_assign_with_semi(&mut self, require_semi: bool) -> CustResult<Stmt> {
        let name = self.expect_ident()?;
        if self.matches(&Token::Dot) {
            let mut fields = vec![self.expect_ident_after("struct field name after '.'")?];
            while self.matches(&Token::Dot) {
                fields.push(self.expect_ident_after("struct field name after '.'")?);
            }
            if self.matches(&Token::LBracket) {
                let index = self.parse_index_expr()?;
                self.expect_closing_bracket_after("array index")?;
                if let Some(op) = self.compound_assignment_op() {
                    let operator = self.advance();
                    self.reject_missing_assignment_rhs(&operator)?;
                    let value = self.parse_expr()?;
                    if require_semi {
                        self.expect_semicolon_after("assignment")?;
                    }
                    return Ok(self.with_pending_inline_enum_decl(Stmt::Expr(
                        Expr::StructArrayCompoundSet {
                            name,
                            fields,
                            index: Box::new(index),
                            op,
                            value: Box::new(value),
                        },
                    )));
                }
                let equals =
                    self.expect_assignment_operator_after("struct array field assignment")?;
                self.reject_missing_assignment_rhs(&equals)?;
                let value = self.parse_expr()?;
                if require_semi {
                    self.expect_semicolon_after("assignment")?;
                }
                return Ok(
                    self.with_pending_inline_enum_decl(Stmt::Expr(Expr::StructArraySet {
                        name,
                        fields,
                        index: Box::new(index),
                        value: Box::new(value),
                    })),
                );
            }
            if let Some(op) = self.compound_assignment_op() {
                let operator = self.advance();
                self.reject_missing_assignment_rhs(&operator)?;
                let value = self.parse_expr()?;
                if require_semi {
                    self.expect_semicolon_after("assignment")?;
                }
                return Ok(self.with_pending_inline_enum_decl(Stmt::Expr(
                    Expr::StructCompoundSet {
                        name,
                        fields,
                        op,
                        value: Box::new(value),
                    },
                )));
            }
            let equals = self.expect_assignment_operator_after("struct field assignment")?;
            self.reject_missing_assignment_rhs(&equals)?;
            let value = self.parse_expr()?;
            if require_semi {
                self.expect_semicolon_after("assignment")?;
            }
            return Ok(self.with_pending_inline_enum_decl(Stmt::StructAssign {
                name,
                fields,
                value,
            }));
        }
        if self.matches(&Token::LBracket) {
            let index = self.parse_index_expr()?;
            self.expect_closing_bracket_after("array index")?;
            if let Some(op) = self.compound_assignment_op() {
                let operator = self.advance();
                self.reject_missing_assignment_rhs(&operator)?;
                let value = self.parse_expr()?;
                if require_semi {
                    self.expect_semicolon_after("assignment")?;
                }
                return Ok(self.with_pending_inline_enum_decl(Stmt::Expr(
                    Expr::ArrayCompoundSet {
                        name,
                        index: Box::new(index),
                        op,
                        value: Box::new(value),
                    },
                )));
            }
            let equals = self.expect_assignment_operator_after("assignment")?;
            self.reject_missing_assignment_rhs(&equals)?;
            let value = self.parse_expr()?;
            if require_semi {
                self.expect_semicolon_after("assignment")?;
            }
            return Ok(self.with_pending_inline_enum_decl(Stmt::ArrayAssign {
                name,
                index,
                value,
            }));
        }
        if let Some(op) = self.compound_assignment_op() {
            let operator = self.advance();
            self.reject_missing_assignment_rhs(&operator)?;
            let value = self.parse_expr()?;
            if require_semi {
                self.expect_semicolon_after("assignment")?;
            }
            return Ok(
                self.with_pending_inline_enum_decl(Stmt::Expr(Expr::CompoundAssign {
                    name,
                    op,
                    value: Box::new(value),
                })),
            );
        }
        let equals = self.expect_assignment_operator_after("assignment")?;
        self.reject_missing_assignment_rhs(&equals)?;
        let expr = self.parse_expr()?;
        if require_semi {
            self.expect_semicolon_after("assignment")?;
        }
        Ok(self.with_pending_inline_enum_decl(Stmt::Assign(name, expr)))
    }

    fn parse_expr_stmt_with_semi(&mut self, require_semi: bool) -> CustResult<Stmt> {
        let expr = self.parse_expr()?;
        if require_semi {
            self.expect_semicolon_after("expression statement")?;
        }
        Ok(self.with_pending_inline_enum_decl(Stmt::Expr(expr)))
    }

    fn parse_return(&mut self) -> CustResult<Stmt> {
        self.expect(Token::Return)?;
        if self.matches(&Token::Semi) {
            return Ok(Stmt::Return(None));
        }
        self.reject_missing_return_expr()?;
        let expr = self.parse_expr()?;
        self.expect_semicolon_after("return statement")?;
        Ok(self.with_pending_inline_enum_decl(Stmt::Return(Some(expr))))
    }

    fn reject_missing_return_expr(&self) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::Comma
                | Token::Colon
                | Token::RParen
                | Token::RBracket
                | Token::RBrace
                | Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!("expected expression after return, found {:?}", self.peek()),
                self.peek_located(),
            ));
        }
        self.reject_keyword_start_expression("return")?;
        Ok(())
    }

    fn reject_missing_control_condition_expr(&self, keyword: &str) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::RParen
                | Token::Semi
                | Token::Colon
                | Token::RBrace
                | Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!(
                    "expected expression after {keyword}, found {:?}",
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        self.reject_keyword_start_expression(keyword)?;
        Ok(())
    }

    fn reject_keyword_start_expression(&self, context: &str) -> CustResult<()> {
        if self.check(&Token::Generic) {
            return Ok(());
        }
        if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!("expected expression after {context} before '{label}'"),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn parse_break(&mut self) -> CustResult<Stmt> {
        let token = self.advance();
        self.expect_semicolon_after("break statement")?;
        Ok(Stmt::Break(Box::new(token)))
    }

    fn parse_continue(&mut self) -> CustResult<Stmt> {
        let token = self.advance();
        self.expect_semicolon_after("continue statement")?;
        Ok(Stmt::Continue(Box::new(token)))
    }

    fn parse_if(&mut self) -> CustResult<Stmt> {
        self.expect(Token::If)?;
        self.expect_opening_paren_after("if")?;
        self.reject_missing_control_condition_expr("if")?;
        let cond = self.parse_expr()?;
        self.expect_closing_paren_after("if condition")?;
        let inline_enum_decl = self.take_pending_inline_enum_decl();
        let then_branch = self.parse_control_body_after("if condition")?;
        let else_branch = if self.matches(&Token::Else) {
            self.parse_control_body_after("else")?
        } else {
            Vec::new()
        };
        let stmt = Stmt::If {
            cond,
            then_branch,
            else_branch,
        };
        Ok(Self::prepend_optional_stmt(inline_enum_decl, stmt))
    }

    fn parse_while(&mut self) -> CustResult<Stmt> {
        self.expect(Token::While)?;
        self.expect_opening_paren_after("while")?;
        self.reject_missing_control_condition_expr("while")?;
        let cond = self.parse_expr()?;
        self.expect_closing_paren_after("while condition")?;
        let inline_enum_decl = self.take_pending_inline_enum_decl();
        let body = self.parse_control_body_after("while condition")?;
        Ok(Self::prepend_optional_stmt(
            inline_enum_decl,
            Stmt::While { cond, body },
        ))
    }

    fn parse_do_while(&mut self) -> CustResult<Stmt> {
        self.expect(Token::Do)?;
        let body = self.parse_control_body_after("do")?;
        self.expect_keyword_after(&Token::While, "do body")?;
        self.expect_opening_paren_after("do-while")?;
        self.reject_missing_control_condition_expr("do-while")?;
        let cond = self.parse_expr()?;
        self.expect_closing_paren_after("do-while condition")?;
        self.expect_semicolon_after("do-while condition")?;
        let inline_enum_decl = self.take_pending_inline_enum_decl();
        Ok(Self::prepend_optional_stmt(
            inline_enum_decl,
            Stmt::DoWhile { body, cond },
        ))
    }

    fn parse_for(&mut self) -> CustResult<Stmt> {
        self.expect(Token::For)?;
        self.expect_opening_paren_after("for")?;

        let init = if self.matches(&Token::Semi) {
            None
        } else if matches!(self.peek(), Token::Auto | Token::Register) {
            Some(Box::new(self.parse_auto_register_local_decl()?))
        } else if self.starts_qualified_aggregate_declaration()
            || matches!(self.peek(), Token::Struct | Token::Union)
        {
            Some(Box::new(self.parse_aggregate_var_decl()?))
        } else if matches!(
            self.peek(),
            Token::Int
                | Token::Char
                | Token::Bool
                | Token::Signed
                | Token::Unsigned
                | Token::Long
                | Token::Short
                | Token::Const
                | Token::Volatile
                | Token::Restrict
                | Token::Atomic
                | Token::Enum
                | Token::Alignas
        ) || self.current_alias().is_some()
        {
            Some(Box::new(self.parse_var_decl()?))
        } else if self.starts_assignment_stmt() {
            Some(Box::new(self.parse_assign()?))
        } else if self.starts_expr() {
            Some(Box::new(self.parse_expr_stmt_with_semi(true)?))
        } else if matches!(
            self.peek(),
            Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Comma
                | Token::Colon
                | Token::Dot
                | Token::Arrow
        ) {
            return Err(Self::error_at(
                format!(
                    "expected expression after for initializer, found {:?}",
                    self.peek()
                ),
                self.peek_located(),
            ));
        } else if let Some(message) = self.statement_only_control_flow_error("for initializer") {
            return Err(Self::error_at(message, self.peek_located()));
        } else {
            return Err(Self::error_at(
                format!("unexpected token in for initializer: {:?}", self.peek()),
                self.peek_located(),
            ));
        };

        let cond = if self.matches(&Token::Semi) {
            None
        } else {
            self.reject_missing_control_condition_expr("for condition")?;
            let expr = self.parse_expr()?;
            self.expect_semicolon_after("for condition")?;
            Some(expr)
        };
        let cond_inline_enum_decl = self.take_pending_inline_enum_decl();

        let increment = if self.check(&Token::RParen) {
            None
        } else if self.starts_assignment_stmt() {
            Some(Box::new(self.parse_assign_with_semi(false)?))
        } else if self.starts_expr() {
            Some(Box::new(self.parse_expr_stmt_with_semi(false)?))
        } else if matches!(
            self.peek(),
            Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Colon
                | Token::Dot
                | Token::Arrow
        ) {
            return Err(Self::error_at(
                format!(
                    "expected expression after for increment, found {:?}",
                    self.peek()
                ),
                self.peek_located(),
            ));
        } else if let Some(message) = self.statement_only_control_flow_error("for increment") {
            return Err(Self::error_at(message, self.peek_located()));
        } else if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!("expected expression after for increment before '{label}'"),
                self.peek_located(),
            ));
        } else {
            return Err(Self::error_at(
                format!("unexpected token in for increment: {:?}", self.peek()),
                self.peek_located(),
            ));
        };
        let (increment_inline_enum_decl, increment) = match increment {
            Some(increment) => {
                let (inline_enum_decl, increment) = Self::split_leading_enum_decl(*increment);
                (inline_enum_decl, Some(Box::new(increment)))
            }
            None => (None, None),
        };
        self.expect_closing_paren_after("for clauses")?;

        let body = self.parse_control_body_after("for clauses")?;
        let init =
            Self::append_optional_stmts(init, [cond_inline_enum_decl, increment_inline_enum_decl]);
        Ok(Stmt::For {
            init,
            cond,
            increment,
            body,
        })
    }

    fn parse_switch(&mut self) -> CustResult<Stmt> {
        self.expect(Token::Switch)?;
        self.expect_opening_paren_after("switch")?;
        self.reject_missing_switch_expr()?;
        let expr = self.parse_expr()?;
        self.expect_closing_paren_after("switch expression")?;
        let inline_enum_decl = self.take_pending_inline_enum_decl();
        self.expect_opening_brace_after("switch expression")?;

        let mut sections = Vec::new();
        let mut seen_cases = HashSet::new();
        let mut seen_default = false;
        while !self.check(&Token::RBrace) {
            if self.check(&Token::Eof) {
                let eof = self.peek_located().clone();
                return Err(Self::error_at(
                    "unterminated block after switch expression".to_string(),
                    &eof,
                ));
            }

            let label = if self.matches(&Token::Case) {
                let (value, value_token) = self.parse_switch_case_value()?;
                if !seen_cases.insert(value) {
                    return Err(Self::error_at(
                        format!("duplicate switch case label {value}"),
                        &value_token,
                    ));
                }
                if self.check(&Token::Comma) {
                    let comma = self.peek_located().clone();
                    return Err(Self::error_at(
                        "comma operator is not allowed in integer constant expression".to_string(),
                        &comma,
                    ));
                }
                self.expect_colon_after("switch case label")?;
                SwitchLabel::Case(value)
            } else if self.matches(&Token::Default) {
                let default_token = self.previous().clone();
                if seen_default {
                    return Err(Self::error_at(
                        "duplicate switch default label".to_string(),
                        &default_token,
                    ));
                }
                seen_default = true;
                self.expect_colon_after("switch default label")?;
                SwitchLabel::Default
            } else {
                return Err(Self::error_at(
                    format!(
                        "expected switch case or default label, found {:?}",
                        self.peek()
                    ),
                    self.peek_located(),
                ));
            };

            let label_inline_enum_decl = self.take_pending_inline_enum_decl();
            let mut statements = Vec::new();
            if let Some(inline_enum_decl) = label_inline_enum_decl {
                statements.push(inline_enum_decl);
            }
            while !matches!(
                self.peek(),
                Token::Case | Token::Default | Token::RBrace | Token::Eof
            ) {
                statements.push(self.parse_stmt()?);
            }
            sections.push(SwitchSection { label, statements });
        }

        self.expect(Token::RBrace)?;
        Ok(Self::prepend_optional_stmt(
            inline_enum_decl,
            Stmt::Switch { expr, sections },
        ))
    }

    fn parse_switch_case_value(&mut self) -> CustResult<(i64, LocatedToken)> {
        if self.check(&Token::LBracket) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected integer constant after switch case before '['".to_string(),
                &found,
            ));
        }
        if self.check(&Token::Question) {
            let found = self.advance();
            return Err(Self::error_at(
                "expected integer constant after switch case before '?'".to_string(),
                &found,
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_or_selector_label() {
            let found = self.advance();
            return Err(Self::error_at(
                format!("expected integer constant after switch case before '{label}'"),
                &found,
            ));
        }
        let empty_constants = HashMap::new();
        self.parse_integer_constant_expr(
            &empty_constants,
            "expected integer constant after switch case",
        )
    }

    fn reject_missing_switch_expr(&self) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::RParen
                | Token::Semi
                | Token::Colon
                | Token::RBrace
                | Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!("expected expression after switch, found {:?}", self.peek()),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn parse_expr(&mut self) -> CustResult<Expr> {
        self.parse_comma_expr()
    }

    fn parse_comma_expr(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_assignment_expr()?;
        while self.matches(&Token::Comma) {
            if matches!(
                self.peek(),
                Token::LBracket
                    | Token::LBrace
                    | Token::Question
                    | Token::Dot
                    | Token::Arrow
                    | Token::RParen
                    | Token::RBracket
                    | Token::Semi
                    | Token::RBrace
                    | Token::Eof
            ) {
                return Err(Self::error_at(
                    format!(
                        "expected expression after comma operator, found {:?}",
                        self.peek()
                    ),
                    self.peek_located(),
                ));
            }
            if let Some(label) = self.integer_constant_invalid_start_label() {
                return Err(Self::error_at(
                    format!("expected expression after comma operator before '{label}'"),
                    self.peek_located(),
                ));
            }
            let rhs = self.parse_assignment_expr()?;
            expr = Expr::Comma(Box::new(expr), Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_index_expr(&mut self) -> CustResult<Expr> {
        self.reject_missing_index_expr("array index expression")?;
        let preserve_missing_bracket_diagnostic =
            matches!(self.peek(), Token::Number(_) | Token::PreprocessorNumber(_))
                && Self::is_assignment_operator(self.peek_next());
        let mut expr = if preserve_missing_bracket_diagnostic {
            self.parse_logical_or()?
        } else {
            self.parse_assignment_expr()?
        };
        while self.matches(&Token::Comma) {
            if matches!(
                self.peek(),
                Token::RParen | Token::RBracket | Token::Semi | Token::RBrace | Token::Eof
            ) {
                return Err(Self::error_at(
                    format!(
                        "expected expression after comma operator, found {:?}",
                        self.peek()
                    ),
                    self.peek_located(),
                ));
            }
            if let Some(label) = self.integer_constant_invalid_start_label() {
                return Err(Self::error_at(
                    format!("expected expression after comma operator before '{label}'"),
                    self.peek_located(),
                ));
            }
            expr = Expr::Comma(Box::new(expr), Box::new(self.parse_assignment_expr()?));
        }
        Ok(expr)
    }

    fn reject_missing_index_expr(&self, context: &str) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::LBracket
                | Token::LBrace
                | Token::Colon
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::RBracket
                | Token::RParen
                | Token::Semi
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!("expected {context}, found {:?}", self.peek()),
                self.peek_located(),
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!("expected {context} before '{label}'"),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn parse_assignment_expr(&mut self) -> CustResult<Expr> {
        let target = self.parse_conditional_expr()?;
        if let Some(op) = self.compound_assignment_op() {
            let operator = self.advance();
            self.reject_missing_assignment_rhs(&operator)?;
            let value = self.parse_assignment_expr()?;
            match target {
                Expr::Var(name) => Ok(Expr::CompoundAssign {
                    name,
                    op,
                    value: Box::new(value),
                }),
                Expr::ArrayGet { name, index } => Ok(Expr::ArrayCompoundSet {
                    name,
                    index,
                    op,
                    value: Box::new(value),
                }),
                Expr::Array2DGet { name, row, column } => Ok(Expr::Array2DCompoundSet {
                    name,
                    row,
                    column,
                    op,
                    value: Box::new(value),
                }),
                Expr::StructArray2DGet {
                    target,
                    row,
                    column,
                } => Ok(Expr::StructArray2DCompoundSet {
                    target,
                    row,
                    column,
                    op,
                    value: Box::new(value),
                }),
                Expr::StructArrayGet {
                    name,
                    fields,
                    index,
                } => Ok(Expr::StructArrayCompoundSet {
                    name,
                    fields,
                    index,
                    op,
                    value: Box::new(value),
                }),
                Expr::StructFieldArrayElementGet {
                    name,
                    array_fields,
                    index,
                    fields,
                } => Ok(Expr::StructFieldArrayElementCompoundSet {
                    name,
                    array_fields,
                    index,
                    fields,
                    op,
                    value: Box::new(value),
                }),
                Expr::StructElementGet {
                    name,
                    index,
                    fields,
                } => Ok(Expr::StructElementCompoundSet {
                    name,
                    index,
                    fields,
                    op,
                    value: Box::new(value),
                }),
                Expr::StructElementArrayGet {
                    name,
                    index,
                    fields,
                    array_index,
                } => Ok(Expr::StructElementArrayCompoundSet {
                    name,
                    index,
                    fields,
                    array_index,
                    op,
                    value: Box::new(value),
                }),
                Expr::StructPtrArrayGet {
                    pointer,
                    fields,
                    index,
                } => Ok(Expr::DerefCompoundSet {
                    pointer: Box::new(Expr::AddressOfStructPtrArrayField {
                        pointer,
                        fields,
                        index,
                    }),
                    op,
                    value: Box::new(value),
                }),
                Expr::Deref(pointer) => Ok(Expr::DerefCompoundSet {
                    pointer,
                    op,
                    value: Box::new(value),
                }),
                Expr::StructGet { name, fields } => Ok(Expr::StructCompoundSet {
                    name,
                    fields,
                    op,
                    value: Box::new(value),
                }),
                Expr::StructPtrGet { pointer, fields } => Ok(Expr::StructPtrCompoundSet {
                    pointer,
                    fields,
                    op,
                    value: Box::new(value),
                }),
                Expr::ScalarLiteral { ty, init } => Ok(Expr::ScalarLiteralCompoundSet {
                    ty,
                    init,
                    op,
                    value: Box::new(value),
                }),
                Expr::AggregateFieldGet { aggregate, fields } => {
                    Ok(Expr::AggregateFieldCompoundSet {
                        aggregate,
                        fields,
                        op,
                        value: Box::new(value),
                    })
                }
                _ => Err(Self::error_at(
                    "invalid compound assignment target".to_string(),
                    &operator,
                )),
            }
        } else if self.check(&Token::Assign) {
            let equals = self.advance();
            self.reject_missing_assignment_rhs(&equals)?;
            let value = self.parse_assignment_expr()?;
            match target {
                Expr::Var(name) => Ok(Expr::Assign {
                    name,
                    value: Box::new(value),
                }),
                Expr::ArrayGet { name, index } => Ok(Expr::ArraySet {
                    name,
                    index,
                    value: Box::new(value),
                }),
                Expr::Array2DGet { name, row, column } => Ok(Expr::Array2DSet {
                    name,
                    row,
                    column,
                    value: Box::new(value),
                }),
                Expr::StructArray2DGet {
                    target,
                    row,
                    column,
                } => Ok(Expr::StructArray2DSet {
                    target,
                    row,
                    column,
                    value: Box::new(value),
                }),
                Expr::StructArrayGet {
                    name,
                    fields,
                    index,
                } => Ok(Expr::StructArraySet {
                    name,
                    fields,
                    index,
                    value: Box::new(value),
                }),
                Expr::StructFieldArrayElementGet {
                    name,
                    array_fields,
                    index,
                    fields,
                } => Ok(Expr::StructFieldArrayElementSet {
                    name,
                    array_fields,
                    index,
                    fields,
                    value: Box::new(value),
                }),
                Expr::StructElementGet {
                    name,
                    index,
                    fields,
                } => Ok(Expr::StructElementSet {
                    name,
                    index,
                    fields,
                    value: Box::new(value),
                }),
                Expr::StructElementArrayGet {
                    name,
                    index,
                    fields,
                    array_index,
                } => Ok(Expr::StructElementArraySet {
                    name,
                    index,
                    fields,
                    array_index,
                    value: Box::new(value),
                }),
                Expr::StructPtrArrayGet {
                    pointer,
                    fields,
                    index,
                } => Ok(Expr::DerefSet {
                    pointer: Box::new(Expr::AddressOfStructPtrArrayField {
                        pointer,
                        fields,
                        index,
                    }),
                    value: Box::new(value),
                }),
                Expr::Deref(pointer) => Ok(Expr::DerefSet {
                    pointer,
                    value: Box::new(value),
                }),
                Expr::StructGet { name, fields } => Ok(Expr::StructSet {
                    name,
                    fields,
                    value: Box::new(value),
                }),
                Expr::StructPtrGet { pointer, fields } => Ok(Expr::StructPtrSet {
                    pointer,
                    fields,
                    value: Box::new(value),
                }),
                Expr::ScalarLiteral { ty, init } => Ok(Expr::ScalarLiteralSet {
                    ty,
                    init,
                    value: Box::new(value),
                }),
                Expr::AggregateFieldGet { aggregate, fields } => Ok(Expr::AggregateFieldSet {
                    aggregate,
                    fields,
                    value: Box::new(value),
                }),
                _ => Err(Self::error_at(
                    "invalid assignment target".to_string(),
                    &equals,
                )),
            }
        } else {
            Ok(target)
        }
    }

    fn reject_missing_assignment_rhs(&self, operator: &LocatedToken) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::Comma
                | Token::Colon
                | Token::RParen
                | Token::RBracket
                | Token::Semi
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!(
                    "expected expression after assignment operator '{}', found {:?}",
                    Self::assignment_operator_label(&operator.kind),
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!(
                    "expected expression after assignment operator '{}' before '{label}'",
                    Self::assignment_operator_label(&operator.kind),
                ),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn assignment_operator_label(token: &Token) -> &'static str {
        match token {
            Token::Assign => "=",
            Token::PlusAssign => "+=",
            Token::MinusAssign => "-=",
            Token::StarAssign => "*=",
            Token::SlashAssign => "/=",
            Token::PercentAssign => "%=",
            Token::AmpAssign => "&=",
            Token::PipeAssign => "|=",
            Token::CaretAssign => "^=",
            Token::ShiftLeftAssign => "<<=",
            Token::ShiftRightAssign => ">>=",
            _ => "<unknown>",
        }
    }

    fn parse_conditional_expr(&mut self) -> CustResult<Expr> {
        let cond = self.parse_logical_or()?;
        if self.matches(&Token::Question) {
            self.reject_missing_conditional_operand("?", |token| {
                matches!(
                    token,
                    Token::LBracket
                        | Token::LBrace
                        | Token::Question
                        | Token::Colon
                        | Token::Dot
                        | Token::Arrow
                )
            })?;
            let then_expr = self.parse_expr()?;
            self.expect_colon_after("conditional then-expression")?;
            self.reject_missing_conditional_operand(":", |token| {
                matches!(
                    token,
                    Token::LBracket
                        | Token::LBrace
                        | Token::Question
                        | Token::RParen
                        | Token::RBracket
                        | Token::Semi
                        | Token::RBrace
                        | Token::Dot
                        | Token::Arrow
                        | Token::Eof
                )
            })?;
            let else_expr = self.parse_conditional_expr()?;
            Ok(Expr::Conditional {
                cond: Box::new(cond),
                then_expr: Box::new(then_expr),
                else_expr: Box::new(else_expr),
            })
        } else {
            Ok(cond)
        }
    }

    fn reject_missing_conditional_operand(
        &self,
        marker: &str,
        is_missing_operand_delimiter: impl FnOnce(&Token) -> bool,
    ) -> CustResult<()> {
        if is_missing_operand_delimiter(self.peek()) {
            return Err(Self::error_at(
                format!(
                    "expected expression after '{}' in conditional operator, found {:?}",
                    marker,
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!(
                    "expected expression after '{marker}' in conditional operator before '{label}'"
                ),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn parse_logical_or(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_logical_and()?;
        while let Some(operator) = self.match_binary_operator(&Token::OrOr) {
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_logical_and()?;
            expr = Expr::Binary(Box::new(expr), BinaryOp::LogicalOr, Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_logical_and(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_bitwise_or()?;
        while let Some(operator) = self.match_binary_operator(&Token::AndAnd) {
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_bitwise_or()?;
            expr = Expr::Binary(Box::new(expr), BinaryOp::LogicalAnd, Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_bitwise_or(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_bitwise_xor()?;
        while let Some(operator) = self.match_binary_operator(&Token::Pipe) {
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_bitwise_xor()?;
            expr = Expr::Binary(Box::new(expr), BinaryOp::BitOr, Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_bitwise_xor(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_bitwise_and()?;
        while let Some(operator) = self.match_binary_operator(&Token::Caret) {
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_bitwise_and()?;
            expr = Expr::Binary(Box::new(expr), BinaryOp::BitXor, Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_bitwise_and(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_equality()?;
        while let Some(operator) = self.match_binary_operator(&Token::Amp) {
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_equality()?;
            expr = Expr::Binary(Box::new(expr), BinaryOp::BitAnd, Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_equality(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_comparison()?;
        loop {
            let (op, operator) = if let Some(operator) = self.match_binary_operator(&Token::Eq) {
                (BinaryOp::Eq, operator)
            } else if let Some(operator) = self.match_binary_operator(&Token::Ne) {
                (BinaryOp::Ne, operator)
            } else {
                break;
            };
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_comparison()?;
            expr = Expr::Binary(Box::new(expr), op, Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_comparison(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_shift()?;
        loop {
            let (op, operator) = if let Some(operator) = self.match_binary_operator(&Token::Lt) {
                (BinaryOp::Lt, operator)
            } else if let Some(operator) = self.match_binary_operator(&Token::Le) {
                (BinaryOp::Le, operator)
            } else if let Some(operator) = self.match_binary_operator(&Token::Gt) {
                (BinaryOp::Gt, operator)
            } else if let Some(operator) = self.match_binary_operator(&Token::Ge) {
                (BinaryOp::Ge, operator)
            } else {
                break;
            };
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_shift()?;
            expr = Expr::Binary(Box::new(expr), op, Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_shift(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_term()?;
        loop {
            let (op, operator) =
                if let Some(operator) = self.match_binary_operator(&Token::ShiftLeft) {
                    (BinaryOp::ShiftLeft, operator)
                } else if let Some(operator) = self.match_binary_operator(&Token::ShiftRight) {
                    (BinaryOp::ShiftRight, operator)
                } else {
                    break;
                };
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_term()?;
            expr = Expr::Binary(Box::new(expr), op, Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_term(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_factor()?;
        loop {
            let (op, operator) = if let Some(operator) = self.match_binary_operator(&Token::Plus) {
                (BinaryOp::Add, operator)
            } else if let Some(operator) = self.match_binary_operator(&Token::Minus) {
                (BinaryOp::Sub, operator)
            } else {
                break;
            };
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_factor()?;
            expr = Expr::Binary(Box::new(expr), op, Box::new(rhs));
        }
        Ok(expr)
    }

    fn parse_factor(&mut self) -> CustResult<Expr> {
        let mut expr = self.parse_unary()?;
        loop {
            let (op, operator) = if let Some(operator) = self.match_binary_operator(&Token::Star) {
                (BinaryOp::Mul, operator)
            } else if let Some(operator) = self.match_binary_operator(&Token::Slash) {
                (BinaryOp::Div, operator)
            } else if let Some(operator) = self.match_binary_operator(&Token::Percent) {
                (BinaryOp::Rem, operator)
            } else {
                break;
            };
            self.reject_missing_binary_rhs(&operator)?;
            let rhs = self.parse_unary()?;
            expr = Expr::Binary(Box::new(expr), op, Box::new(rhs));
        }
        Ok(expr)
    }

    fn match_binary_operator(&mut self, token: &Token) -> Option<LocatedToken> {
        if self.check(token) {
            Some(self.advance())
        } else {
            None
        }
    }

    fn reject_missing_binary_rhs(&self, operator: &LocatedToken) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::Comma
                | Token::Colon
                | Token::RParen
                | Token::RBracket
                | Token::Semi
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!(
                    "expected expression after binary operator '{}', found {:?}",
                    Self::binary_operator_label(&operator.kind),
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!(
                    "expected expression after binary operator '{}' before '{label}'",
                    Self::binary_operator_label(&operator.kind),
                ),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn binary_operator_label(token: &Token) -> &'static str {
        match token {
            Token::OrOr => "||",
            Token::AndAnd => "&&",
            Token::Pipe => "|",
            Token::Caret => "^",
            Token::Amp => "&",
            Token::Eq => "==",
            Token::Ne => "!=",
            Token::Lt => "<",
            Token::Le => "<=",
            Token::Gt => ">",
            Token::Ge => ">=",
            Token::ShiftLeft => "<<",
            Token::ShiftRight => ">>",
            Token::Plus => "+",
            Token::Minus => "-",
            Token::Star => "*",
            Token::Slash => "/",
            Token::Percent => "%",
            _ => "<unknown>",
        }
    }

    fn parse_unary(&mut self) -> CustResult<Expr> {
        if self.matches(&Token::PlusPlus) {
            let operator = self.previous().clone();
            self.reject_missing_unary_operand(&operator)?;
            let target = self.parse_unary()?;
            Self::increment_expr(target, IncrementOp::Inc, true, &operator)
        } else if self.matches(&Token::MinusMinus) {
            let operator = self.previous().clone();
            self.reject_missing_unary_operand(&operator)?;
            let target = self.parse_unary()?;
            Self::increment_expr(target, IncrementOp::Dec, true, &operator)
        } else if self.matches(&Token::Plus) {
            let operator = self.previous().clone();
            self.reject_missing_unary_operand(&operator)?;
            Ok(Expr::UnaryPlus(Box::new(self.parse_unary()?)))
        } else if self.matches(&Token::Minus) {
            let operator = self.previous().clone();
            self.reject_missing_unary_operand(&operator)?;
            Ok(Expr::UnaryMinus(Box::new(self.parse_unary()?)))
        } else if self.matches(&Token::Tilde) {
            let operator = self.previous().clone();
            self.reject_missing_unary_operand(&operator)?;
            Ok(Expr::BitwiseNot(Box::new(self.parse_unary()?)))
        } else if self.matches(&Token::Bang) {
            let operator = self.previous().clone();
            self.reject_missing_unary_operand(&operator)?;
            Ok(Expr::LogicalNot(Box::new(self.parse_unary()?)))
        } else if self.matches(&Token::Sizeof) {
            self.parse_sizeof()
        } else if self.matches(&Token::Alignof) {
            self.parse_alignof()
        } else if self.matches(&Token::Star) {
            let operator = self.previous().clone();
            self.reject_missing_unary_operand(&operator)?;
            Ok(Expr::Deref(Box::new(self.parse_unary()?)))
        } else if self.matches(&Token::Amp) {
            let operator = self.previous().clone();
            self.reject_missing_unary_operand(&operator)?;
            let target = self.parse_unary()?;
            Self::address_of_expr(target, &operator)
        } else if self.check(&Token::LParen) && self.starts_cast_type_after_lparen() {
            let expr = self.parse_cast()?;
            self.parse_postfix_suffix(expr)
        } else {
            self.parse_postfix()
        }
    }

    fn reject_missing_unary_operand(&self, operator: &LocatedToken) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::Comma
                | Token::Colon
                | Token::LBracket
                | Token::LBrace
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::RParen
                | Token::RBracket
                | Token::Semi
                | Token::RBrace
                | Token::Int
                | Token::Char
                | Token::Bool
                | Token::Float
                | Token::Double
                | Token::Complex
                | Token::Imaginary
                | Token::Signed
                | Token::Unsigned
                | Token::Long
                | Token::Short
                | Token::Const
                | Token::Volatile
                | Token::Restrict
                | Token::Atomic
                | Token::Static
                | Token::Extern
                | Token::ThreadLocal
                | Token::Inline
                | Token::Noreturn
                | Token::Auto
                | Token::Register
                | Token::Void
                | Token::Enum
                | Token::Struct
                | Token::Union
                | Token::Typedef
                | Token::Alignas
                | Token::StaticAssert
                | Token::Return
                | Token::If
                | Token::Else
                | Token::While
                | Token::Do
                | Token::For
                | Token::Switch
                | Token::Case
                | Token::Default
                | Token::Break
                | Token::Continue
                | Token::Goto
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!(
                    "expected expression after unary operator '{}', found {:?}",
                    Self::unary_operator_label(&operator.kind),
                    self.peek()
                ),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn unary_operator_label(token: &Token) -> &'static str {
        match token {
            Token::PlusPlus => "++",
            Token::MinusMinus => "--",
            Token::Plus => "+",
            Token::Minus => "-",
            Token::Tilde => "~",
            Token::Bang => "!",
            Token::Star => "*",
            Token::Amp => "&",
            _ => "<unknown>",
        }
    }

    fn starts_cast_type_after_lparen(&self) -> bool {
        match self.tokens.get(self.pos + 1).map(|token| &token.kind) {
            Some(
                Token::Int
                | Token::Char
                | Token::Bool
                | Token::Float
                | Token::Double
                | Token::Complex
                | Token::Imaginary
                | Token::Signed
                | Token::Unsigned
                | Token::Long
                | Token::Short
                | Token::Struct
                | Token::Union
                | Token::Enum
                | Token::Void
                | Token::Const
                | Token::Volatile
                | Token::Restrict
                | Token::Atomic,
            ) => true,
            Some(Token::Ident(name)) => self.lookup_type_alias(name).is_some(),
            _ => false,
        }
    }

    fn parse_cast(&mut self) -> CustResult<Expr> {
        self.expect(Token::LParen)?;
        self.reject_leading_restrict_qualifier()?;
        let leading_qualifier = self.leading_type_qualifier_token();
        let leading_const = self.consume_type_qualifiers();
        match leading_qualifier.as_ref() {
            Some(qualifier) if !self.is_type_name_start() => {
                return Err(Self::error_at(
                    format!(
                        "expected cast type after type qualifier '{}', found {:?}",
                        Self::type_qualifier_label(&qualifier.kind),
                        self.peek()
                    ),
                    self.peek_located(),
                ));
            }
            _ => {}
        }
        let type_token = self.peek_located().clone();
        if matches!(self.peek(), Token::Struct | Token::Union)
            && matches!(self.peek_next(), Token::LBrace)
        {
            let (type_name, _, _) = self.parse_aggregate_definition_body(false, true)?;
            self.reject_function_type_suffix("function casts")?;
            if self.matches(&Token::Star) {
                self.consume_type_qualifiers();
                if self.check(&Token::Star) {
                    return Err(Self::error_at(
                        "pointer-to-pointer casts are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        "pointer array casts are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                self.reject_function_type_suffix("function casts")?;
                self.expect_closing_paren_after("cast type")?;
                self.reject_missing_cast_operand()?;
                return Ok(Expr::PointerCast {
                    pointee: PointeeType::Struct(type_name),
                    points_to_const: leading_const,
                    expr: Box::new(self.parse_unary()?),
                });
            }
            if self.matches(&Token::LBracket) {
                let len = if self.check(&Token::RBracket) {
                    None
                } else {
                    Some(self.expect_array_len()?)
                };
                self.expect_closing_bracket_after("aggregate array compound literal type")?;
                self.reject_multidimensional_array_cast_suffix()?;
                self.reject_pointer_to_array_cast_suffix()?;
                self.reject_function_type_suffix("function casts")?;
                self.expect_closing_paren_after("cast type")?;
                return Ok(Expr::AggregateArrayLiteral {
                    init: self.parse_aggregate_array_compound_initializer(&type_name, len)?,
                    len,
                    type_name,
                    read_only: leading_const,
                });
            }
            self.expect_closing_paren_after("cast type")?;
            if !self.check(&Token::LBrace) {
                return Err(Self::error_at(
                    "aggregate casts are not supported".to_string(),
                    &type_token,
                ));
            }
            return Ok(Expr::AggregateLiteral {
                init: self.parse_struct_initializer(&type_name)?,
                type_name,
                read_only: leading_const,
            });
        }
        if self.matches(&Token::Void) {
            if self.check(&Token::Star) {
                return Err(Self::error_at(
                    "void pointers are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            self.reject_function_type_suffix("function casts")?;
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "void array casts are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            self.expect_closing_paren_after("cast type")?;
            self.reject_missing_cast_operand()?;
            return Ok(Expr::VoidCast(Box::new(self.parse_unary()?)));
        }
        let alias_const = match &type_token.kind {
            Token::Ident(name) => self.type_alias_is_const(name),
            _ => false,
        };
        let compound_literal_read_only = leading_const || alias_const;
        let decl_type = self.parse_decl_type("cast type")?;
        self.reject_function_type_suffix("function casts")?;
        if let Some(token) = self.parenthesized_pointer_star_token_at_current() {
            return Err(Self::error_at(
                "parenthesized pointer casts are not supported".to_string(),
                token,
            ));
        }
        if self.matches(&Token::Star) {
            let pointee = match decl_type {
                DeclType::Scalar(ty) => PointeeType::Scalar(ty),
                DeclType::Struct(type_name) => PointeeType::Struct(type_name),
                DeclType::Pointer { .. } | DeclType::Array2DPointer { .. } => {
                    return Err(Self::error_at(
                        "pointer-to-pointer casts are not supported".to_string(),
                        self.previous(),
                    ));
                }
                DeclType::Array(_, _) | DeclType::Array2D(_, _, _) => {
                    return Err(Self::error_at(
                        "pointer-to-array casts are not supported".to_string(),
                        self.previous(),
                    ));
                }
            };
            self.consume_type_qualifiers();
            if self.check(&Token::Star) {
                return Err(Self::error_at(
                    "pointer-to-pointer casts are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    "pointer array casts are not supported".to_string(),
                    self.peek_located(),
                ));
            }
            self.reject_function_type_suffix("function casts")?;
            self.expect_closing_paren_after("cast type")?;
            self.reject_missing_cast_operand()?;
            return Ok(Expr::PointerCast {
                pointee,
                points_to_const: leading_const,
                expr: Box::new(self.parse_unary()?),
            });
        }
        let ty = match decl_type {
            DeclType::Scalar(ty) => ty,
            DeclType::Struct(_) => {
                let DeclType::Struct(type_name) = decl_type else {
                    unreachable!("decl_type was already matched as aggregate")
                };
                if self.matches(&Token::LBracket) {
                    let len = if self.check(&Token::RBracket) {
                        None
                    } else {
                        Some(self.expect_array_len()?)
                    };
                    self.expect_closing_bracket_after("aggregate array compound literal type")?;
                    self.reject_multidimensional_array_cast_suffix()?;
                    self.reject_pointer_to_array_cast_suffix()?;
                    self.reject_function_type_suffix("function casts")?;
                    self.expect_closing_paren_after("cast type")?;
                    return Ok(Expr::AggregateArrayLiteral {
                        init: self.parse_aggregate_array_compound_initializer(&type_name, len)?,
                        len,
                        type_name,
                        read_only: compound_literal_read_only,
                    });
                }
                self.expect_closing_paren_after("cast type")?;
                if !self.check(&Token::LBrace) {
                    return Err(Self::error_at(
                        "aggregate casts are not supported".to_string(),
                        &type_token,
                    ));
                }
                return Ok(Expr::AggregateLiteral {
                    init: self.parse_struct_initializer(&type_name)?,
                    type_name,
                    read_only: compound_literal_read_only,
                });
            }
            DeclType::Pointer {
                pointee,
                points_to_const,
            } => {
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        "pointer array casts are not supported".to_string(),
                        self.peek_located(),
                    ));
                }
                self.reject_function_type_suffix("function casts")?;
                self.expect_closing_paren_after("cast type")?;
                self.reject_missing_cast_operand()?;
                return Ok(Expr::PointerCast {
                    pointee,
                    points_to_const: leading_const || points_to_const,
                    expr: Box::new(self.parse_unary()?),
                });
            }
            DeclType::Array(pointee, len) => {
                self.reject_multidimensional_array_cast_suffix()?;
                self.reject_pointer_to_array_cast_suffix()?;
                self.reject_function_type_suffix("function casts")?;
                self.expect_closing_paren_after("cast type")?;
                if !self.check(&Token::LBrace) {
                    return Err(Self::error_at(
                        "pointer casts are not supported".to_string(),
                        &type_token,
                    ));
                }
                return match pointee {
                    PointeeType::Scalar(elem_type) => Ok(Expr::ArrayLiteral {
                        elem_type,
                        len: Some(len),
                        init: self.parse_array_compound_initializer(Some(len), elem_type)?,
                        read_only: compound_literal_read_only,
                    }),
                    PointeeType::Struct(type_name) => Ok(Expr::AggregateArrayLiteral {
                        init: self
                            .parse_aggregate_array_compound_initializer(&type_name, Some(len))?,
                        len: Some(len),
                        type_name,
                        read_only: compound_literal_read_only,
                    }),
                };
            }
            DeclType::Array2D(_, _, _) => {
                return Err(Self::error_at(
                    "multidimensional array casts are not supported".to_string(),
                    &type_token,
                ));
            }
            DeclType::Array2DPointer { .. } => {
                return Err(Self::error_at(
                    "pointer-to-row casts are not supported".to_string(),
                    &type_token,
                ));
            }
        };
        if self.matches(&Token::LBracket) {
            let len = if self.check(&Token::RBracket) {
                None
            } else {
                Some(self.expect_array_len()?)
            };
            self.expect_closing_bracket_after("array compound literal type")?;
            self.reject_multidimensional_array_cast_suffix()?;
            self.reject_pointer_to_array_cast_suffix()?;
            self.reject_function_type_suffix("function casts")?;
            self.expect_closing_paren_after("cast type")?;
            return Ok(Expr::ArrayLiteral {
                elem_type: ty,
                len,
                init: self.parse_array_compound_initializer(len, ty)?,
                read_only: compound_literal_read_only,
            });
        }
        self.expect_closing_paren_after("cast type")?;
        if self.check(&Token::LBrace) {
            return Ok(Expr::ScalarLiteral {
                ty,
                init: Box::new(self.parse_scalar_initializer_expr("scalar compound literal")?),
            });
        }
        Ok(Expr::Cast {
            ty,
            expr: {
                self.reject_missing_cast_operand()?;
                Box::new(self.parse_unary()?)
            },
        })
    }

    fn reject_missing_cast_operand(&self) -> CustResult<()> {
        if matches!(
            self.peek(),
            Token::Comma
                | Token::Colon
                | Token::LBracket
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::RParen
                | Token::RBracket
                | Token::Semi
                | Token::RBrace
                | Token::Int
                | Token::Char
                | Token::Bool
                | Token::Float
                | Token::Double
                | Token::Complex
                | Token::Imaginary
                | Token::Signed
                | Token::Unsigned
                | Token::Long
                | Token::Short
                | Token::Const
                | Token::Volatile
                | Token::Restrict
                | Token::Atomic
                | Token::Static
                | Token::Extern
                | Token::ThreadLocal
                | Token::Inline
                | Token::Noreturn
                | Token::Auto
                | Token::Register
                | Token::Void
                | Token::Enum
                | Token::Struct
                | Token::Union
                | Token::Typedef
                | Token::Alignas
                | Token::StaticAssert
                | Token::Return
                | Token::If
                | Token::Else
                | Token::While
                | Token::Do
                | Token::For
                | Token::Switch
                | Token::Case
                | Token::Default
                | Token::Break
                | Token::Continue
                | Token::Goto
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!("expected expression after cast, found {:?}", self.peek()),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn reject_multidimensional_array_cast_suffix(&self) -> CustResult<()> {
        if self.check(&Token::LBracket) {
            return Err(Self::error_at(
                "multidimensional array casts are not supported".to_string(),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn reject_pointer_to_array_cast_suffix(&self) -> CustResult<()> {
        if self.check(&Token::Star) {
            return Err(Self::error_at(
                "pointer-to-array casts are not supported".to_string(),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn address_of_expr(target: Expr, operator: &LocatedToken) -> CustResult<Expr> {
        match target {
            Expr::Var(name) => Ok(Expr::AddressOf(name)),
            Expr::ArrayGet { name, index } => Ok(Expr::AddressOfArray { name, index }),
            Expr::StructGet { name, fields } => Ok(Expr::AddressOfStructField { name, fields }),
            Expr::StructElementGet {
                name,
                index,
                fields,
            } => Ok(Expr::AddressOfStructElementField {
                name,
                index,
                fields,
            }),
            Expr::StructArrayGet {
                name,
                fields,
                index,
            } => Ok(Expr::AddressOfStructArrayField {
                name,
                fields,
                index,
            }),
            Expr::StructElementArrayGet {
                name,
                index,
                fields,
                array_index,
            } => Ok(Expr::AddressOfStructElementArrayField {
                name,
                index,
                fields,
                array_index,
            }),
            Expr::StructPtrArrayGet {
                pointer,
                fields,
                index,
            } => Ok(Expr::AddressOfStructPtrArrayField {
                pointer,
                fields,
                index,
            }),
            Expr::StructFieldArrayElementGet {
                name,
                array_fields,
                index,
                fields,
            } => Ok(Expr::AddressOfStructPtrField {
                pointer: Box::new(Expr::AddressOfStructArrayField {
                    name,
                    fields: array_fields,
                    index,
                }),
                fields,
            }),
            Expr::StructPtrGet { pointer, fields } => {
                Ok(Expr::AddressOfStructPtrField { pointer, fields })
            }
            Expr::ScalarLiteral { ty, init } => Ok(Expr::AddressOfScalarLiteral { ty, init }),
            Expr::AggregateLiteral {
                type_name,
                init,
                read_only,
            } => Ok(Expr::AddressOfAggregateLiteral {
                type_name,
                init,
                read_only,
            }),
            Expr::AggregateFieldGet { aggregate, fields } => {
                Ok(Expr::AddressOfAggregateField { aggregate, fields })
            }
            Expr::StringGet { values, index } => Ok(Expr::Binary(
                Box::new(Expr::StringLiteral(values)),
                BinaryOp::Add,
                index,
            )),
            Expr::Deref(pointer) => Ok(*pointer),
            _ => Err(Self::error_at(
                "invalid address-of target".to_string(),
                operator,
            )),
        }
    }

    fn parse_sizeof(&mut self) -> CustResult<Expr> {
        if self.matches(&Token::LParen) {
            self.reject_missing_sizeof_operand(true)?;
            if self.is_type_name_start() {
                let sizeof_type = self.parse_sizeof_like_type_name("sizeof")?;
                self.expect_closing_paren_after("sizeof type")?;
                Ok(Expr::SizeOfType(sizeof_type))
            } else {
                let expr = self.parse_expr()?;
                self.expect_closing_paren_after("sizeof expression")?;
                Ok(Expr::SizeOfValue(Box::new(expr)))
            }
        } else {
            self.reject_missing_sizeof_operand(false)?;
            Ok(Expr::SizeOfValue(Box::new(self.parse_unary()?)))
        }
    }

    fn reject_missing_sizeof_operand(&self, allow_type_name_start: bool) -> CustResult<()> {
        match self.peek() {
            Token::LBracket => {
                return Err(Self::error_at(
                    "expected sizeof operand before '['".to_string(),
                    self.peek_located(),
                ));
            }
            Token::Question => {
                return Err(Self::error_at(
                    "expected sizeof operand before '?'".to_string(),
                    self.peek_located(),
                ));
            }
            _ => {}
        }
        match self.integer_constant_invalid_start_or_selector_label() {
            Some(label) if !allow_type_name_start || !self.is_type_name_start() => {
                return Err(Self::error_at(
                    format!("expected sizeof operand before '{label}'"),
                    self.peek_located(),
                ));
            }
            _ => {}
        }
        if matches!(
            self.peek(),
            Token::Comma
                | Token::RParen
                | Token::RBracket
                | Token::Semi
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!("expected sizeof operand, found {:?}", self.peek()),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn parse_alignof(&mut self) -> CustResult<Expr> {
        self.expect_opening_paren_after("_Alignof")?;
        self.reject_missing_alignof_type()?;
        let alignof_type = self.parse_sizeof_like_type_name("_Alignof")?;
        self.expect_closing_paren_after("_Alignof type")?;
        Ok(Expr::AlignOfType(alignof_type))
    }

    fn reject_missing_alignof_type(&self) -> CustResult<()> {
        if self.check(&Token::LBracket) {
            return Err(Self::error_at(
                "expected _Alignof type before '['".to_string(),
                self.peek_located(),
            ));
        }
        if self.check(&Token::LBrace) {
            return Err(Self::error_at(
                "expected _Alignof type before '{'".to_string(),
                self.peek_located(),
            ));
        }
        if self.check(&Token::Question) {
            return Err(Self::error_at(
                "expected _Alignof type before '?'".to_string(),
                self.peek_located(),
            ));
        }
        if self.check(&Token::Dot) {
            return Err(Self::error_at(
                "expected _Alignof type before '.'".to_string(),
                self.peek_located(),
            ));
        }
        if self.check(&Token::Arrow) {
            return Err(Self::error_at(
                "expected _Alignof type before '->'".to_string(),
                self.peek_located(),
            ));
        }
        match self.integer_constant_invalid_start_label() {
            Some(label) if !self.is_type_name_start() => {
                return Err(Self::error_at(
                    format!("expected _Alignof type before '{label}'"),
                    self.peek_located(),
                ));
            }
            _ => {}
        }
        if !self.is_type_name_start() {
            let found = self.peek_located().clone();
            return Err(Self::error_at(
                format!("expected _Alignof type, found {:?}", found.kind),
                &found,
            ));
        }
        Ok(())
    }

    fn is_type_name_start(&self) -> bool {
        matches!(
            self.peek(),
            Token::Int
                | Token::Char
                | Token::Bool
                | Token::Float
                | Token::Double
                | Token::Complex
                | Token::Imaginary
                | Token::Signed
                | Token::Unsigned
                | Token::Long
                | Token::Short
                | Token::Struct
                | Token::Union
                | Token::Enum
                | Token::Const
                | Token::Volatile
                | Token::Restrict
                | Token::Atomic
                | Token::Void
        ) || self.current_alias().is_some()
    }

    fn parse_sizeof_like_type_name(&mut self, operator: &str) -> CustResult<SizeOfType> {
        self.reject_leading_restrict_qualifier()?;
        let first_qualifier = if matches!(
            self.peek(),
            Token::Const | Token::Volatile | Token::Restrict
        ) || self.bare_atomic_qualifier_at(self.pos)
        {
            Some(self.peek_located().clone())
        } else {
            None
        };
        let is_const_qualified = self.consume_type_qualifiers();
        match first_qualifier.as_ref() {
            Some(qualifier) if !self.is_type_name_start() => {
                return Err(Self::error_at(
                    format!(
                        "expected {operator} type after type qualifier '{}', found {:?}",
                        Self::type_qualifier_label(&qualifier.kind),
                        self.peek()
                    ),
                    self.peek_located(),
                ));
            }
            _ => {}
        }
        if self.check(&Token::Void) {
            if let Some(token) = self.void_pointer_star_token_at_current() {
                return Err(Self::error_at(
                    "void pointers are not supported".to_string(),
                    token,
                ));
            }
            self.advance();
            self.reject_function_type_suffix(&format!("function {operator} types"))?;
            if self.check(&Token::LBracket) {
                return Err(Self::error_at(
                    format!("void array {operator} types are not supported"),
                    self.peek_located(),
                ));
            }
            return Err(Self::error_at(
                format!("{operator}(void) is not supported"),
                self.previous(),
            ));
        }
        if is_const_qualified
            && !matches!(
                self.peek(),
                Token::Int
                    | Token::Char
                    | Token::Bool
                    | Token::Signed
                    | Token::Unsigned
                    | Token::Long
                    | Token::Short
                    | Token::Struct
                    | Token::Union
                    | Token::Enum
            )
            && self.current_alias().is_none()
        {
            let found = self.peek_located().clone();
            return Err(Self::error_at(
                format!(
                    "expected {operator} type after const, found {:?}",
                    found.kind
                ),
                &found,
            ));
        }
        if matches!(
            (
                self.peek(),
                self.tokens.get(self.pos + 1).map(|token| &token.kind)
            ),
            (Token::Struct | Token::Union, Some(Token::LBrace))
        ) {
            let (type_name, _, _) = self.parse_aggregate_definition_body(false, true)?;
            self.reject_function_type_suffix(&format!("function {operator} types"))?;
            if self.matches(&Token::Star) {
                self.consume_type_qualifiers();
                if self.check(&Token::Star) {
                    return Err(Self::error_at(
                        format!("pointer-to-pointer {operator} types are not supported"),
                        self.peek_located(),
                    ));
                }
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        format!("pointer array {operator} types are not supported"),
                        self.peek_located(),
                    ));
                }
                self.reject_function_type_suffix(&format!("function {operator} types"))?;
                return Ok(SizeOfType::Pointer);
            }
            if let Some(len) = self.parse_sizeof_array_type_len(operator)? {
                self.reject_function_type_suffix(&format!("function {operator} types"))?;
                return Ok(SizeOfType::Array(PointeeType::Struct(type_name), len));
            }
            let struct_type = self.struct_types.get(&type_name).cloned().ok_or_else(|| {
                CustError::new(format!("undefined anonymous aggregate type '{type_name}'"))
            })?;
            return Ok(SizeOfType::AnonymousAggregate(struct_type));
        }

        let decl_type = self.parse_decl_type(&format!("{operator} struct type name"))?;
        self.reject_function_type_suffix(&format!("function {operator} types"))?;
        if let Some(token) = self.parenthesized_pointer_star_token_at_current() {
            return Err(Self::error_at(
                format!("parenthesized pointer {operator} types are not supported"),
                token,
            ));
        }

        match decl_type {
            DeclType::Scalar(ty) => {
                if self.matches(&Token::Star) {
                    self.consume_type_qualifiers();
                    if self.check(&Token::Star) {
                        return Err(Self::error_at(
                            format!("pointer-to-pointer {operator} types are not supported"),
                            self.peek_located(),
                        ));
                    }
                    if self.check(&Token::LBracket) {
                        return Err(Self::error_at(
                            format!("pointer array {operator} types are not supported"),
                            self.peek_located(),
                        ));
                    }
                    self.reject_function_type_suffix(&format!("function {operator} types"))?;
                    Ok(SizeOfType::Pointer)
                } else if let Some(len) = self.parse_sizeof_array_type_len(operator)? {
                    self.reject_function_type_suffix(&format!("function {operator} types"))?;
                    Ok(SizeOfType::Array(PointeeType::Scalar(ty), len))
                } else {
                    Ok(SizeOfType::Scalar(ty))
                }
            }
            DeclType::Struct(type_name) => {
                if self.matches(&Token::Star) {
                    self.consume_type_qualifiers();
                    if self.check(&Token::Star) {
                        return Err(Self::error_at(
                            format!("pointer-to-pointer {operator} types are not supported"),
                            self.peek_located(),
                        ));
                    }
                    if self.check(&Token::LBracket) {
                        return Err(Self::error_at(
                            format!("pointer array {operator} types are not supported"),
                            self.peek_located(),
                        ));
                    }
                    self.reject_function_type_suffix(&format!("function {operator} types"))?;
                    Ok(SizeOfType::Pointer)
                } else if let Some(len) = self.parse_sizeof_array_type_len(operator)? {
                    self.reject_function_type_suffix(&format!("function {operator} types"))?;
                    Ok(SizeOfType::Array(PointeeType::Struct(type_name), len))
                } else {
                    Ok(SizeOfType::Struct(type_name))
                }
            }
            DeclType::Pointer { .. } | DeclType::Array2DPointer { .. } => {
                if self.matches(&Token::Star) {
                    return Err(Self::error_at(
                        format!("pointer-to-pointer {operator} types are not supported"),
                        self.previous(),
                    ));
                }
                if self.matches(&Token::LBracket) {
                    return Err(Self::error_at(
                        format!("pointer array {operator} types are not supported"),
                        self.previous(),
                    ));
                }
                self.reject_function_type_suffix(&format!("function {operator} types"))?;
                Ok(SizeOfType::Pointer)
            }
            DeclType::Array(element_type, len) => {
                if self.matches(&Token::Star) {
                    return Err(Self::error_at(
                        format!("pointer-to-array {operator} types are not supported"),
                        self.previous(),
                    ));
                }
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        format!("multidimensional {operator} array types are not supported"),
                        self.peek_located(),
                    ));
                }
                Ok(SizeOfType::Array(element_type, len))
            }
            DeclType::Array2D(element_type, rows, columns) => {
                if self.matches(&Token::Star) {
                    return Err(Self::error_at(
                        format!("pointer-to-array {operator} types are not supported"),
                        self.previous(),
                    ));
                }
                if self.check(&Token::LBracket) {
                    return Err(Self::error_at(
                        format!(
                            "{operator} array types with more than two dimensions are not supported"
                        ),
                        self.peek_located(),
                    ));
                }
                Ok(SizeOfType::Array2D(element_type, rows, columns))
            }
        }
    }

    fn reject_function_type_suffix(&self, description: &str) -> CustResult<()> {
        if self.check(&Token::LParen) && !matches!(self.peek_next(), Token::Star) {
            return Err(Self::error_at(
                format!("{description} are not supported"),
                self.peek_located(),
            ));
        }
        Ok(())
    }

    fn parse_sizeof_array_type_len(&mut self, operator: &str) -> CustResult<Option<usize>> {
        if !self.matches(&Token::LBracket) {
            return Ok(None);
        }
        let len = self.expect_array_len()?;
        self.expect_closing_bracket_after(&format!("{operator} array type"))?;
        if self.check(&Token::LBracket) {
            return Err(Self::error_at(
                format!("multidimensional {operator} array types are not supported"),
                self.peek_located(),
            ));
        }
        if self.check(&Token::Star) {
            return Err(Self::error_at(
                format!("pointer-to-array {operator} types are not supported"),
                self.peek_located(),
            ));
        }
        Ok(Some(len))
    }

    fn parse_postfix(&mut self) -> CustResult<Expr> {
        let expr = self.parse_primary()?;
        self.parse_postfix_suffix(expr)
    }

    fn parse_postfix_suffix(&mut self, mut expr: Expr) -> CustResult<Expr> {
        loop {
            if self.matches(&Token::LBracket) {
                let index = self.parse_index_expr()?;
                self.expect_closing_bracket_after("array index")?;
                expr = match expr {
                    Expr::Var(name) => Expr::ArrayGet {
                        name,
                        index: Box::new(index),
                    },
                    Expr::ArrayGet { name, index: row } => Expr::Array2DGet {
                        name,
                        row,
                        column: Box::new(index),
                    },
                    Expr::Array2DGet { .. } | Expr::StructArray2DGet { .. } => {
                        return Err(Self::error_at(
                            "array expressions with more than two dimensions are not supported"
                                .to_string(),
                            self.previous(),
                        ));
                    }
                    Expr::StructArrayGet {
                        name,
                        fields,
                        index: row,
                    } => Expr::StructArray2DGet {
                        target: Array2DFieldTarget::Direct { name, fields },
                        row,
                        column: Box::new(index),
                    },
                    Expr::StructElementArrayGet {
                        name,
                        index: element_index,
                        fields,
                        array_index: row,
                    } => Expr::StructArray2DGet {
                        target: Array2DFieldTarget::Element {
                            name,
                            index: element_index,
                            fields,
                        },
                        row,
                        column: Box::new(index),
                    },
                    Expr::StructPtrArrayGet {
                        pointer,
                        fields,
                        index: row,
                    } => Expr::StructArray2DGet {
                        target: Array2DFieldTarget::Pointer { pointer, fields },
                        row,
                        column: Box::new(index),
                    },
                    Expr::StructGet { name, fields } => Expr::StructArrayGet {
                        name,
                        fields,
                        index: Box::new(index),
                    },
                    Expr::StructElementGet {
                        name,
                        index: element_index,
                        fields,
                    } => Expr::StructElementArrayGet {
                        name,
                        index: element_index,
                        fields,
                        array_index: Box::new(index),
                    },
                    Expr::StructPtrGet { pointer, fields } => Expr::StructPtrArrayGet {
                        pointer,
                        fields,
                        index: Box::new(index),
                    },
                    Expr::AggregateFieldGet { .. } => Expr::Deref(Box::new(Expr::Binary(
                        Box::new(expr),
                        BinaryOp::Add,
                        Box::new(index),
                    ))),
                    _ => Expr::Deref(Box::new(Expr::Binary(
                        Box::new(expr),
                        BinaryOp::Add,
                        Box::new(index),
                    ))),
                };
            } else if self.matches(&Token::Dot) {
                let field = self.expect_ident_after("struct field name after '.'")?;
                expr = match expr {
                    Expr::Var(name) => Expr::StructGet {
                        name,
                        fields: vec![field],
                    },
                    Expr::StructGet { name, mut fields } => {
                        fields.push(field);
                        Expr::StructGet { name, fields }
                    }
                    Expr::ArrayGet { name, index } => Expr::StructElementGet {
                        name,
                        index,
                        fields: vec![field],
                    },
                    Expr::StructElementGet {
                        name,
                        index,
                        mut fields,
                    } => {
                        fields.push(field);
                        Expr::StructElementGet {
                            name,
                            index,
                            fields,
                        }
                    }
                    Expr::StructArrayGet {
                        name,
                        fields: array_fields,
                        index,
                    } => Expr::StructFieldArrayElementGet {
                        name,
                        array_fields,
                        index,
                        fields: vec![field],
                    },
                    Expr::StructFieldArrayElementGet {
                        name,
                        array_fields,
                        index,
                        mut fields,
                    } => {
                        fields.push(field);
                        Expr::StructFieldArrayElementGet {
                            name,
                            array_fields,
                            index,
                            fields,
                        }
                    }
                    Expr::Deref(pointer) => Expr::StructPtrGet {
                        pointer,
                        fields: vec![field],
                    },
                    Expr::StructPtrGet {
                        pointer,
                        mut fields,
                    } => {
                        fields.push(field);
                        Expr::StructPtrGet { pointer, fields }
                    }
                    Expr::StructElementArrayGet {
                        name,
                        index,
                        fields,
                        array_index,
                    } => Expr::StructPtrGet {
                        pointer: Box::new(Expr::StructElementArrayGet {
                            name,
                            index,
                            fields,
                            array_index,
                        }),
                        fields: vec![field],
                    },
                    Expr::StructPtrArrayGet {
                        pointer,
                        fields,
                        index,
                    } => Expr::StructPtrGet {
                        pointer: Box::new(Expr::StructPtrArrayGet {
                            pointer,
                            fields,
                            index,
                        }),
                        fields: vec![field],
                    },
                    Expr::AggregateLiteral { .. }
                    | Expr::Assign { .. }
                    | Expr::ArraySet { .. }
                    | Expr::StructArraySet { .. }
                    | Expr::StructElementArraySet { .. }
                    | Expr::StructSet { .. }
                    | Expr::StructPtrSet { .. }
                    | Expr::DerefSet { .. }
                    | Expr::Conditional { .. }
                    | Expr::Comma(_, _)
                    | Expr::Call { .. } => Expr::AggregateFieldGet {
                        aggregate: Box::new(expr),
                        fields: vec![field],
                    },
                    Expr::AggregateFieldGet {
                        aggregate,
                        mut fields,
                    } => {
                        fields.push(field);
                        Expr::AggregateFieldGet { aggregate, fields }
                    }
                    _ => {
                        return Err(Self::error_at(
                            "invalid struct field access target".to_string(),
                            self.previous(),
                        ));
                    }
                };
            } else if self.matches(&Token::Arrow) {
                let field = self.expect_ident_after("struct field name after '->'")?;
                expr = Expr::StructPtrGet {
                    pointer: Box::new(expr),
                    fields: vec![field],
                };
            } else if self.matches(&Token::PlusPlus) {
                let operator = self.previous().clone();
                expr = Self::increment_expr(expr, IncrementOp::Inc, false, &operator)?;
            } else if self.matches(&Token::MinusMinus) {
                let operator = self.previous().clone();
                expr = Self::increment_expr(expr, IncrementOp::Dec, false, &operator)?;
            } else {
                break;
            }
        }
        Ok(expr)
    }

    fn increment_expr(
        target: Expr,
        op: IncrementOp,
        prefix: bool,
        operator: &LocatedToken,
    ) -> CustResult<Expr> {
        match target {
            Expr::Var(_)
            | Expr::ArrayGet { .. }
            | Expr::Array2DGet { .. }
            | Expr::StructArray2DGet { .. }
            | Expr::StructArrayGet { .. }
            | Expr::StructFieldArrayElementGet { .. }
            | Expr::StructElementGet { .. }
            | Expr::StructElementArrayGet { .. }
            | Expr::StructPtrArrayGet { .. }
            | Expr::Deref(_)
            | Expr::StructGet { .. }
            | Expr::StructPtrGet { .. }
            | Expr::ScalarLiteral { .. }
            | Expr::AggregateFieldGet { .. } => Ok(Expr::Increment {
                target: Box::new(target),
                op,
                prefix,
            }),
            _ => Err(Self::error_at(
                "invalid increment/decrement target".to_string(),
                operator,
            )),
        }
    }

    fn parse_primary(&mut self) -> CustResult<Expr> {
        let found = self.advance();
        match found.kind.clone() {
            Token::Number(value) => Ok(Expr::Number(value)),
            Token::PreprocessorNumber(value) if value.bits <= i64::MAX as u64 => {
                Ok(Expr::Number(value.bits as i64))
            }
            Token::PreprocessorNumber(_) => Err(Self::error_at(
                "integer literal out of range".to_string(),
                &found,
            )),
            Token::StringLiteral(values) => {
                let values = self.concatenate_adjacent_string_literals(values);
                if self.matches(&Token::LBracket) {
                    let index = self.parse_index_expr()?;
                    self.expect_closing_bracket_after("string literal index")?;
                    Ok(Expr::StringGet {
                        values,
                        index: Box::new(index),
                    })
                } else {
                    Ok(Expr::StringLiteral(values))
                }
            }
            Token::Ident(name) => {
                if name == "__func__" && !self.parsing_function_body {
                    return Err(Self::error_at(
                        "predefined identifier '__func__' is only available inside function bodies"
                            .to_string(),
                        &found,
                    ));
                }
                if self.matches(&Token::LParen) {
                    let args = self.parse_call_args()?;
                    self.expect_closing_paren_after("function call arguments")?;
                    Ok(Expr::Call { name, args })
                } else if self.matches(&Token::LBracket) {
                    let index = self.parse_index_expr()?;
                    self.expect_closing_bracket_after("array index")?;
                    Ok(Expr::ArrayGet {
                        name,
                        index: Box::new(index),
                    })
                } else if self.matches(&Token::Dot) {
                    let field = self.expect_ident_after("struct field name after '.'")?;
                    Ok(Expr::StructGet {
                        name,
                        fields: vec![field],
                    })
                } else {
                    Ok(Expr::Var(name))
                }
            }
            Token::LParen => {
                if matches!(
                    self.peek(),
                    Token::Comma
                        | Token::Colon
                        | Token::RParen
                        | Token::RBracket
                        | Token::LBracket
                        | Token::LBrace
                        | Token::Question
                        | Token::Dot
                        | Token::Arrow
                        | Token::Semi
                        | Token::RBrace
                        | Token::Eof
                ) {
                    return Err(Self::error_at(
                        format!("expected grouped expression, found {:?}", self.peek()),
                        self.peek_located(),
                    ));
                }
                if let Some(label) = self.integer_constant_invalid_start_label() {
                    return Err(Self::error_at(
                        format!("expected grouped expression before '{label}'"),
                        self.peek_located(),
                    ));
                }
                let expr = self.parse_expr()?;
                self.expect_closing_paren_after("grouped expression")?;
                Ok(expr)
            }
            Token::Generic => Err(Self::error_at(
                "generic selections are not supported".to_string(),
                &found,
            )),
            token => Err(Self::error_at(
                format!("expected expression, found {token:?}"),
                &found,
            )),
        }
    }

    fn concatenate_adjacent_string_literals(&mut self, mut values: Vec<i64>) -> Vec<i64> {
        while let Token::StringLiteral(next_values) = self.peek().clone() {
            self.advance();
            if values.last() == Some(&0) {
                values.pop();
            }
            values.extend(next_values);
        }
        values
    }

    fn parse_call_args(&mut self) -> CustResult<Vec<Expr>> {
        let mut args = Vec::new();
        if self.check(&Token::RParen) {
            return Ok(args);
        }
        if matches!(
            self.peek(),
            Token::Comma
                | Token::Colon
                | Token::RBracket
                | Token::LBracket
                | Token::Question
                | Token::Dot
                | Token::Arrow
                | Token::Semi
                | Token::LBrace
                | Token::RBrace
                | Token::Eof
        ) {
            return Err(Self::error_at(
                format!("expected function call argument, found {:?}", self.peek()),
                self.peek_located(),
            ));
        }
        if let Some(label) = self.integer_constant_invalid_start_label() {
            return Err(Self::error_at(
                format!("expected function call argument before '{label}'"),
                self.peek_located(),
            ));
        }

        loop {
            args.push(self.parse_assignment_expr()?);

            if self.matches(&Token::Comma) {
                if matches!(
                    self.peek(),
                    Token::RParen
                        | Token::RBracket
                        | Token::Colon
                        | Token::LBracket
                        | Token::Question
                        | Token::Dot
                        | Token::Arrow
                        | Token::Semi
                        | Token::LBrace
                        | Token::RBrace
                        | Token::Eof
                ) {
                    return Err(Self::error_at(
                        format!(
                            "expected function call argument after ',', found {:?}",
                            self.peek()
                        ),
                        self.peek_located(),
                    ));
                }
                if let Some(label) = self.integer_constant_invalid_start_label() {
                    return Err(Self::error_at(
                        format!("expected function call argument after ',' before '{label}'"),
                        self.peek_located(),
                    ));
                }
            } else if matches!(
                self.peek(),
                Token::RParen | Token::Semi | Token::LBrace | Token::RBrace | Token::Eof
            ) {
                break;
            } else {
                return Err(Self::error_at(
                    format!(
                        "expected ',' or ')' after function call argument, found {:?}",
                        self.peek()
                    ),
                    self.peek_located(),
                ));
            }
        }
        Ok(args)
    }

    fn expect(&mut self, expected: Token) -> CustResult<()> {
        let found = self.advance();
        if found.kind == expected {
            Ok(())
        } else {
            Err(Self::error_at(
                format!("expected {expected:?}, found {:?}", found.kind),
                &found,
            ))
        }
    }

    fn expect_opening_paren_after(&mut self, context: &str) -> CustResult<()> {
        let found = self.advance();
        if found.kind == Token::LParen {
            Ok(())
        } else {
            Err(Self::error_at(
                format!("expected '(' after {context}, found {:?}", found.kind),
                &found,
            ))
        }
    }

    fn expect_keyword_after(&mut self, expected: &Token, context: &str) -> CustResult<()> {
        let found = self.advance();
        if &found.kind == expected {
            Ok(())
        } else {
            Err(Self::error_at(
                format!(
                    "expected {expected:?} after {context}, found {:?}",
                    found.kind
                ),
                &found,
            ))
        }
    }

    fn expect_opening_brace_after(&mut self, context: &str) -> CustResult<()> {
        let found = self.advance();
        if found.kind == Token::LBrace {
            Ok(())
        } else {
            Err(Self::error_at(
                format!("expected '{{' after {context}, found {:?}", found.kind),
                &found,
            ))
        }
    }

    fn expect_closing_bracket_after(&mut self, context: &str) -> CustResult<()> {
        let found = self.advance();
        if found.kind == Token::RBracket {
            Ok(())
        } else {
            Err(Self::error_at(
                format!("expected ']' after {context}, found {:?}", found.kind),
                &found,
            ))
        }
    }

    fn expect_closing_brace_after(&mut self, context: &str) -> CustResult<()> {
        let found = self.advance();
        if found.kind == Token::RBrace {
            Ok(())
        } else {
            Err(Self::error_at(
                format!("expected '}}' after {context}, found {:?}", found.kind),
                &found,
            ))
        }
    }

    fn expect_closing_paren_after(&mut self, context: &str) -> CustResult<()> {
        let found = self.advance();
        if found.kind == Token::RParen {
            Ok(())
        } else {
            Err(Self::error_at(
                format!("expected ')' after {context}, found {:?}", found.kind),
                &found,
            ))
        }
    }

    fn expect_semicolon_after(&mut self, context: &str) -> CustResult<()> {
        let found = self.advance();
        if found.kind == Token::Semi {
            Ok(())
        } else {
            Err(Self::error_at(
                format!("expected ';' after {context}, found {:?}", found.kind),
                &found,
            ))
        }
    }

    fn expect_assign_after(&mut self, context: &str) -> CustResult<()> {
        self.expect_assignment_operator_after(context).map(|_| ())
    }

    fn expect_assignment_operator_after(&mut self, context: &str) -> CustResult<LocatedToken> {
        let found = self.advance();
        if found.kind == Token::Assign {
            Ok(found)
        } else {
            Err(Self::error_at(
                format!("expected '=' after {context}, found {:?}", found.kind),
                &found,
            ))
        }
    }

    fn expect_colon_after(&mut self, context: &str) -> CustResult<()> {
        let found = self.advance();
        if found.kind == Token::Colon {
            Ok(())
        } else {
            Err(Self::error_at(
                format!("expected ':' after {context}, found {:?}", found.kind),
                &found,
            ))
        }
    }

    fn expect_ident(&mut self) -> CustResult<String> {
        let found = self.advance();
        match found.kind.clone() {
            Token::Ident(name) => Ok(name),
            token => Err(Self::error_at(
                format!("expected identifier, found {token:?}"),
                &found,
            )),
        }
    }

    fn expect_ident_after(&mut self, context: &str) -> CustResult<String> {
        let found = self.advance();
        match found.kind.clone() {
            Token::Ident(name) => Ok(name),
            token => Err(Self::error_at(
                format!("expected {context}, found {token:?}"),
                &found,
            )),
        }
    }

    fn matches(&mut self, expected: &Token) -> bool {
        if self.check(expected) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn check(&self, expected: &Token) -> bool {
        self.peek() == expected
    }

    fn compound_assignment_op(&self) -> Option<CompoundOp> {
        match self.peek() {
            Token::PlusAssign => Some(CompoundOp::Add),
            Token::MinusAssign => Some(CompoundOp::Sub),
            Token::StarAssign => Some(CompoundOp::Mul),
            Token::SlashAssign => Some(CompoundOp::Div),
            Token::PercentAssign => Some(CompoundOp::Rem),
            Token::AmpAssign => Some(CompoundOp::BitAnd),
            Token::PipeAssign => Some(CompoundOp::BitOr),
            Token::CaretAssign => Some(CompoundOp::BitXor),
            Token::ShiftLeftAssign => Some(CompoundOp::ShiftLeft),
            Token::ShiftRightAssign => Some(CompoundOp::ShiftRight),
            _ => None,
        }
    }

    fn is_assignment_operator(token: &Token) -> bool {
        matches!(
            token,
            Token::Assign
                | Token::PlusAssign
                | Token::MinusAssign
                | Token::StarAssign
                | Token::SlashAssign
                | Token::PercentAssign
                | Token::AmpAssign
                | Token::PipeAssign
                | Token::CaretAssign
                | Token::ShiftLeftAssign
                | Token::ShiftRightAssign
        )
    }

    fn peek(&self) -> &Token {
        &self.peek_located().kind
    }

    fn peek_next(&self) -> &Token {
        &self
            .tokens
            .get(self.pos + 1)
            .unwrap_or_else(|| self.peek_located())
            .kind
    }

    fn starts_expr(&self) -> bool {
        Self::is_expr_start_token(self.peek())
    }

    fn is_expr_start_token(token: &Token) -> bool {
        matches!(
            token,
            Token::Ident(_)
                | Token::Number(_)
                | Token::PreprocessorNumber(_)
                | Token::StringLiteral(_)
                | Token::Plus
                | Token::Minus
                | Token::PlusPlus
                | Token::MinusMinus
                | Token::Bang
                | Token::Sizeof
                | Token::Star
                | Token::Amp
                | Token::LParen
        )
    }

    fn is_primary_assignment_value_start(token: &Token) -> bool {
        matches!(
            token,
            Token::Ident(_)
                | Token::Number(_)
                | Token::PreprocessorNumber(_)
                | Token::StringLiteral(_)
                | Token::Star
                | Token::Amp
                | Token::LParen
        )
    }

    fn starts_deref_assignment_stmt(&self) -> bool {
        let mut paren_depth = 0usize;
        let mut bracket_depth = 0usize;

        for token in self.tokens.iter().skip(self.pos + 1) {
            match &token.kind {
                Token::LParen => paren_depth += 1,
                Token::RParen => paren_depth = paren_depth.saturating_sub(1),
                Token::LBracket => bracket_depth += 1,
                Token::RBracket => bracket_depth = bracket_depth.saturating_sub(1),
                token
                    if paren_depth == 0
                        && bracket_depth == 0
                        && Self::is_assignment_operator(token) =>
                {
                    return true;
                }
                Token::Semi | Token::Eof if paren_depth == 0 && bracket_depth == 0 => return false,
                _ => {}
            }
        }

        false
    }

    fn starts_assignment_stmt(&self) -> bool {
        if !matches!(self.peek(), Token::Ident(_)) {
            return false;
        }
        if self.peek_next() == &Token::Dot {
            let mut index = self.pos + 1;
            while self
                .tokens
                .get(index)
                .is_some_and(|token| token.kind == Token::Dot)
            {
                if !self
                    .tokens
                    .get(index + 1)
                    .is_some_and(|token| matches!(token.kind, Token::Ident(_)))
                {
                    return false;
                }
                index += 2;
            }
            return self
                .tokens
                .get(index)
                .is_some_and(|token| Self::is_assignment_operator(&token.kind));
        }
        if Self::is_assignment_operator(self.peek_next()) {
            return true;
        }
        if self.peek_next() != &Token::LBracket {
            return false;
        }

        let mut depth = 0usize;
        for index in (self.pos + 1)..self.tokens.len() {
            match &self.tokens[index].kind {
                Token::LBracket => depth += 1,
                Token::RBracket => {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        return self.tokens.get(index + 1).is_some_and(|candidate| {
                            Self::is_assignment_operator(&candidate.kind)
                        });
                    }
                }
                Token::Eof if depth > 0 => return false,
                _ => {}
            }
        }
        false
    }

    fn starts_missing_assignment_operator_stmt(&self) -> bool {
        if !matches!(self.peek(), Token::Ident(_)) {
            return false;
        }

        if self.peek_next() != &Token::LParen
            && Self::is_primary_assignment_value_start(self.peek_next())
        {
            return true;
        }

        if self.peek_next() != &Token::LBracket {
            return false;
        }

        let mut depth = 0usize;
        for index in (self.pos + 1)..self.tokens.len() {
            match &self.tokens[index].kind {
                Token::LBracket => depth += 1,
                Token::RBracket => {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        return self.tokens.get(index + 1).is_some_and(|candidate| {
                            Self::is_primary_assignment_value_start(&candidate.kind)
                        });
                    }
                }
                Token::Semi | Token::Eof if depth == 0 => return false,
                Token::Eof if depth > 0 => return false,
                _ => {}
            }
        }
        false
    }

    fn starts_missing_deref_assignment_operator_stmt(&self) -> bool {
        match self.tokens.get(self.pos + 1).map(|token| &token.kind) {
            Some(Token::Ident(_)) => {
                let after_target = if self
                    .tokens
                    .get(self.pos + 2)
                    .is_some_and(|token| token.kind == Token::LBracket)
                {
                    self.index_after_balanced_brackets(self.pos + 2)
                        .map(|index| index + 1)
                } else {
                    Some(self.pos + 2)
                };
                after_target
                    .and_then(|index| self.tokens.get(index))
                    .is_some_and(|token| Self::is_primary_assignment_value_start(&token.kind))
            }
            Some(Token::LParen) => self
                .index_after_balanced_parens(self.pos + 1)
                .and_then(|index| self.tokens.get(index + 1))
                .is_some_and(|token| Self::is_primary_assignment_value_start(&token.kind)),
            _ => false,
        }
    }

    fn index_after_balanced_brackets(&self, start: usize) -> Option<usize> {
        let mut depth = 0usize;
        for index in start..self.tokens.len() {
            match &self.tokens[index].kind {
                Token::LBracket => depth += 1,
                Token::RBracket => {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        return Some(index);
                    }
                }
                Token::Eof => return None,
                _ => {}
            }
        }
        None
    }

    fn index_after_balanced_parens(&self, start: usize) -> Option<usize> {
        let mut depth = 0usize;
        for index in start..self.tokens.len() {
            match &self.tokens[index].kind {
                Token::LParen => depth += 1,
                Token::RParen => {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        return Some(index);
                    }
                }
                Token::Eof => return None,
                _ => {}
            }
        }
        None
    }

    fn statement_only_control_flow_error(&self, context: &str) -> Option<String> {
        match self.peek() {
            Token::Return => Some(format!("return is not allowed in {context}")),
            Token::Break | Token::Continue => Some(format!(
                "{} is not allowed in {context}",
                self.loop_control_keyword()
            )),
            Token::If => Some(format!("if statement is not allowed in {context}")),
            Token::Else => Some("else without matching if".to_string()),
            Token::While => Some(format!("while loop is not allowed in {context}")),
            Token::Do => Some(format!("do loop is not allowed in {context}")),
            Token::For => Some(format!("for loop is not allowed in {context}")),
            Token::Switch => Some(format!("switch statement is not allowed in {context}")),
            Token::Case => Some("case label outside switch".to_string()),
            Token::Default => Some("default label outside switch".to_string()),
            _ => None,
        }
    }

    fn loop_control_keyword(&self) -> &'static str {
        match self.peek() {
            Token::Break => "break",
            Token::Continue => "continue",
            _ => "loop control statement",
        }
    }

    fn peek_located(&self) -> &LocatedToken {
        self.tokens
            .get(self.pos)
            .expect("lexer always appends an EOF token")
    }

    fn previous(&self) -> &LocatedToken {
        self.tokens
            .get(self.pos.saturating_sub(1))
            .expect("previous token exists after a successful match")
    }

    fn advance(&mut self) -> LocatedToken {
        let token = self.peek_located().clone();
        if !matches!(token.kind, Token::Eof) {
            self.pos += 1;
        }
        token
    }

    fn error_at(message: String, token: &LocatedToken) -> CustError {
        let origin = token
            .source_origin
            .as_ref()
            .map_or_else(String::new, |origin| {
                format!(" in included header '{}'", origin.name)
            });
        CustError::new(format!(
            "{message} at line {}, column {}{origin}",
            token.line, token.column
        ))
    }
}

// Interpreted calls recurse through Rust; keep deterministic headroom on the
// test harness's smaller worker-thread stack as interpreter frames evolve.
const MAX_CALL_DEPTH: usize = 24;
const MAX_INTEGER_STRING_BYTES: usize = 4096;

struct Interpreter {
    scopes: Vec<Scope>,
    static_locals: HashMap<usize, StaticLocalStorage>,
    live_scope_ids: HashSet<usize>,
    next_scope_id: usize,
    functions: HashMap<String, Function>,
    prototypes: HashMap<String, FunctionSignature>,
    struct_types: HashMap<String, StructTypeDef>,
    call_depth: usize,
    return_type_stack: Vec<ReturnType>,
    max_loop_iterations: Option<usize>,
    loop_iterations: usize,
    next_compound_literal_id: usize,
    function_name_arrays: HashMap<String, Rc<RefCell<ArrayValue>>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Scope {
    id: usize,
    values: HashMap<String, Value>,
    static_local_ids: HashMap<String, usize>,
    enum_constants: HashMap<String, i64>,
    const_variables: HashSet<String>,
    array2d_pointer_types: HashMap<String, (CType, usize)>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct StaticLocalStorage {
    scope_id: usize,
    name: String,
    value: Value,
    is_const: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ExecFlow {
    None,
    Return(Option<ReturnValue>),
    Break(LocatedToken),
    Continue(LocatedToken),
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ReturnValue {
    Scalar(i64),
    Pointer {
        pointer: PointerValue,
        ty: PointeeType,
        points_to_const: bool,
    },
    Struct {
        type_name: String,
        fields: HashMap<String, StructFieldValue>,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Value {
    Scalar {
        value: i64,
        ty: CType,
    },
    Array(Rc<RefCell<ArrayValue>>),
    Pointer {
        pointer: PointerValue,
        ty: PointeeType,
        points_to_const: bool,
    },
    Struct {
        type_name: String,
        fields: HashMap<String, StructFieldValue>,
    },
    StructArray {
        type_name: String,
        elements: Vec<HashMap<String, StructFieldValue>>,
        read_only: bool,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum StructFieldValue {
    Scalar {
        value: i64,
        ty: CType,
        is_const: bool,
    },
    Array {
        value: Rc<RefCell<ArrayValue>>,
        is_const: bool,
    },
    Struct {
        type_name: String,
        fields: HashMap<String, StructFieldValue>,
        is_const: bool,
    },
    StructArray {
        type_name: String,
        elements: Vec<HashMap<String, StructFieldValue>>,
        is_const: bool,
    },
    Pointer {
        pointer: PointerValue,
        ty: PointeeType,
        is_const: bool,
        points_to_const: bool,
    },
}

impl StructFieldValue {
    fn is_const(&self) -> bool {
        match self {
            StructFieldValue::Scalar { is_const, .. }
            | StructFieldValue::Array { is_const, .. }
            | StructFieldValue::Struct { is_const, .. }
            | StructFieldValue::StructArray { is_const, .. }
            | StructFieldValue::Pointer { is_const, .. } => *is_const,
        }
    }

    fn deep_clone(&self) -> Self {
        match self {
            StructFieldValue::Scalar {
                value,
                ty,
                is_const,
            } => StructFieldValue::Scalar {
                value: *value,
                ty: *ty,
                is_const: *is_const,
            },
            StructFieldValue::Array { value, is_const } => StructFieldValue::Array {
                value: Rc::new(RefCell::new(value.borrow().clone())),
                is_const: *is_const,
            },
            StructFieldValue::Struct {
                type_name,
                fields,
                is_const,
            } => StructFieldValue::Struct {
                type_name: type_name.clone(),
                fields: Self::deep_clone_fields(fields),
                is_const: *is_const,
            },
            StructFieldValue::StructArray {
                type_name,
                elements,
                is_const,
            } => StructFieldValue::StructArray {
                type_name: type_name.clone(),
                elements: elements.iter().map(Self::deep_clone_fields).collect(),
                is_const: *is_const,
            },
            StructFieldValue::Pointer {
                pointer,
                ty,
                is_const,
                points_to_const,
            } => StructFieldValue::Pointer {
                pointer: pointer.clone(),
                ty: ty.clone(),
                is_const: *is_const,
                points_to_const: *points_to_const,
            },
        }
    }

    fn deep_clone_fields(
        fields: &HashMap<String, StructFieldValue>,
    ) -> HashMap<String, StructFieldValue> {
        fields
            .iter()
            .map(|(name, value)| (name.clone(), value.deep_clone()))
            .collect()
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum PointerValue {
    Null,
    Scalar {
        scope_id: usize,
        name: String,
    },
    Struct {
        scope_id: usize,
        name: String,
    },
    StructElement {
        scope_id: usize,
        name: String,
        index: usize,
    },
    StructFieldElement {
        scope_id: usize,
        name: String,
        element_index: Option<usize>,
        fields: Vec<String>,
        index: usize,
    },
    NestedStructArrayElement {
        pointer: Box<PointerValue>,
        fields: Vec<String>,
        index: usize,
    },
    StructField {
        scope_id: usize,
        name: String,
        element_index: Option<usize>,
        fields: Vec<String>,
    },
    StructFieldElementField {
        scope_id: usize,
        name: String,
        element_index: Option<usize>,
        array_fields: Vec<String>,
        index: usize,
        fields: Vec<String>,
    },
    ArrayBase {
        array: Rc<RefCell<ArrayValue>>,
        source_name: Option<String>,
        owner: Option<ArrayPointerOwner>,
    },
    ArrayElement {
        array: Rc<RefCell<ArrayValue>>,
        source_name: Option<String>,
        index: usize,
        owner: Option<ArrayPointerOwner>,
    },
    Array2DRow {
        array: Rc<RefCell<ArrayValue>>,
        source_name: Option<String>,
        row: usize,
        owner: Option<ArrayPointerOwner>,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ArrayPointerOwner {
    scope_id: usize,
    name: String,
}

type CheckedArrayPointerIndex = (
    Rc<RefCell<ArrayValue>>,
    Option<String>,
    usize,
    Option<ArrayPointerOwner>,
);

#[derive(Debug, Clone, PartialEq, Eq)]
struct ArrayValue {
    elements: Vec<i64>,
    elem_type: CType,
    read_only: bool,
    dimensions: Option<(usize, usize)>,
}

impl ArrayValue {
    fn mutable_zeroed(len: usize, elem_type: CType) -> Self {
        Self {
            elements: vec![0; len],
            elem_type,
            read_only: false,
            dimensions: None,
        }
    }

    fn mutable_zeroed_2d(rows: usize, columns: usize, elem_type: CType) -> Self {
        Self {
            elements: vec![0; rows * columns],
            elem_type,
            read_only: false,
            dimensions: Some((rows, columns)),
        }
    }

    fn read_only(elements: Vec<i64>) -> Self {
        Self {
            elements,
            elem_type: CType::Char,
            read_only: true,
            dimensions: None,
        }
    }
}

impl Interpreter {
    fn new(options: InterpretOptions) -> Self {
        Self {
            scopes: Vec::new(),
            static_locals: HashMap::new(),
            live_scope_ids: HashSet::new(),
            next_scope_id: 0,
            functions: HashMap::new(),
            prototypes: HashMap::new(),
            struct_types: HashMap::new(),
            call_depth: 0,
            return_type_stack: Vec::new(),
            max_loop_iterations: options.max_loop_iterations,
            loop_iterations: 0,
            next_compound_literal_id: 0,
            function_name_arrays: HashMap::new(),
        }
    }

    fn eval_scalar_conversion(&mut self, ty: CType, expr: &Expr) -> CustResult<i64> {
        if ty == CType::Bool && self.expr_is_pointer_value(expr) {
            return Ok(i64::from(Self::pointer_truthy(&self.eval_pointer(expr)?)));
        }
        Ok(ty.normalize(self.eval(expr)?))
    }

    fn aggregate_kind_label(&self, type_name: &str) -> &'static str {
        self.struct_types
            .get(type_name)
            .map(|aggregate| aggregate.kind.keyword())
            .unwrap_or("struct")
    }

    fn break_outside_loop_or_switch_error(token: &LocatedToken) -> CustError {
        CustError::new(format!(
            "break outside loop or switch at line {}, column {}{}",
            token.line,
            token.column,
            token.source_origin_suffix()
        ))
    }

    fn continue_outside_loop_error(token: &LocatedToken) -> CustError {
        CustError::new(format!(
            "continue outside loop at line {}, column {}{}",
            token.line,
            token.column,
            token.source_origin_suffix()
        ))
    }

    fn run(&mut self, program: &Program) -> CustResult<i64> {
        self.functions = program.functions.clone();
        self.prototypes = program.prototypes.clone();
        self.struct_types = program.struct_types.clone();
        self.push_scope();
        for global in &program.globals {
            match self.exec_stmt(global)? {
                ExecFlow::None => {}
                ExecFlow::Return(_) => return Err(CustError::new("return outside function")),
                ExecFlow::Break(token) => {
                    return Err(Self::break_outside_loop_or_switch_error(&token));
                }
                ExecFlow::Continue(token) => return Err(Self::continue_outside_loop_error(&token)),
            }
        }

        let result = match self.call_function("main", &[])? {
            Some(ReturnValue::Scalar(value)) => Ok(value),
            Some(ReturnValue::Pointer { .. }) => Err(CustError::new(
                "pointer function 'main' used as program entry point",
            )),
            Some(ReturnValue::Struct { .. }) => Err(CustError::new(
                "struct function 'main' used as program entry point",
            )),
            None => Err(CustError::new(
                "int function 'main' returned without a value",
            )),
        };
        self.pop_scope();
        result
    }

    fn call_function(&mut self, name: &str, arg_exprs: &[Expr]) -> CustResult<Option<ReturnValue>> {
        let Some(function) = self.functions.get(name).cloned() else {
            if self.has_integer_absolute_value_prototype(name) {
                return self.call_integer_absolute_value_function(name, arg_exprs);
            }
            if self.has_integer_string_conversion_prototype(name) {
                return self.call_integer_string_conversion_function(name, arg_exprs);
            }
            if self.has_string_comparison_prototype(name) {
                return self.call_string_comparison_function(name, arg_exprs);
            }
            if self.has_string_prefix_comparison_prototype(name) {
                return self.call_string_prefix_comparison_function(name, arg_exprs);
            }
            if self.has_string_length_prototype(name) {
                return self.call_string_length_function(name, arg_exprs);
            }
            if self.has_character_search_prototype(name) {
                return self.call_character_search_function(name, arg_exprs);
            }
            if self.has_character_set_search_prototype(name) {
                return self.call_character_set_search_function(name, arg_exprs);
            }
            if self.has_string_copy_prototype(name) {
                return self.call_string_copy_function(name, arg_exprs);
            }
            if self.has_string_span_prototype(name) {
                return self.call_string_span_function(name, arg_exprs);
            }
            if matches!(name, "abs" | "labs" | "llabs") && self.prototypes.contains_key(name) {
                return Err(CustError::new(format!(
                    "standard library function '{name}' has an unsupported declaration; expected one integer parameter and an integer return type"
                )));
            }
            if matches!(name, "atoi" | "atol" | "atoll") && self.prototypes.contains_key(name) {
                return Err(CustError::new(format!(
                    "standard library function '{name}' has an unsupported declaration; expected one pointer-to-const-character parameter and an integer return type"
                )));
            }
            if name == "strcmp" && self.prototypes.contains_key(name) {
                return Err(CustError::new(
                    "standard library function 'strcmp' has an unsupported declaration; expected two pointer-to-const-character parameters and an integer return type",
                ));
            }
            if name == "strncmp" && self.prototypes.contains_key(name) {
                return Err(CustError::new(
                    "standard library function 'strncmp' has an unsupported declaration; expected two pointer-to-const-character parameters, one integer count, and an integer return type",
                ));
            }
            if name == "strlen" && self.prototypes.contains_key(name) {
                return Err(CustError::new(
                    "standard library function 'strlen' has an unsupported declaration; expected one pointer-to-const-character parameter and an integer return type",
                ));
            }
            if matches!(name, "strchr" | "strrchr") && self.prototypes.contains_key(name) {
                return Err(CustError::new(format!(
                    "standard library function '{name}' has an unsupported declaration; expected one pointer-to-const-character parameter, one integer search value, and a pointer-to-character return type"
                )));
            }
            if matches!(name, "strpbrk" | "strstr") && self.prototypes.contains_key(name) {
                return Err(CustError::new(format!(
                    "standard library function '{name}' has an unsupported declaration; expected two pointer-to-const-character parameters and a pointer-to-character return type"
                )));
            }
            if name == "strcpy" && self.prototypes.contains_key(name) {
                return Err(CustError::new(
                    "standard library function 'strcpy' has an unsupported declaration; expected one pointer-to-character destination parameter, one pointer-to-const-character source parameter, and a pointer-to-character return type",
                ));
            }
            if matches!(name, "strspn" | "strcspn") && self.prototypes.contains_key(name) {
                return Err(CustError::new(format!(
                    "standard library function '{name}' has an unsupported declaration; expected two pointer-to-const-character parameters and an integer return type"
                )));
            }
            return Err(CustError::new(format!("undefined function '{name}'")));
        };

        if function.params.len() != arg_exprs.len() {
            return Err(CustError::new(format!(
                "function '{name}' expected {} arguments, got {}",
                function.params.len(),
                arg_exprs.len()
            )));
        }

        if self.call_depth >= MAX_CALL_DEPTH {
            return Err(CustError::new(format!(
                "function call depth limit exceeded while calling '{name}'"
            )));
        }

        let function_name_array = Rc::clone(
            self.function_name_arrays
                .entry(name.to_string())
                .or_insert_with(|| {
                    let mut bytes = name.bytes().map(i64::from).collect::<Vec<_>>();
                    bytes.push(0);
                    Rc::new(RefCell::new(ArrayValue::read_only(bytes)))
                }),
        );
        let mut param_scope =
            HashMap::from([("__func__".to_string(), Value::Array(function_name_array))]);
        let mut const_params = HashSet::new();
        for (param, arg_expr) in function.params.iter().zip(arg_exprs) {
            let arg = match param.kind {
                ParamKind::Scalar => {
                    let ParamType::Scalar(ty) = &param.ty else {
                        return Err(CustError::new("internal scalar parameter type mismatch"));
                    };
                    let ty = *ty;
                    Value::Scalar {
                        value: self.eval_scalar_conversion(ty, arg_expr)?,
                        ty,
                    }
                }
                ParamKind::Pointer => {
                    let ty = match &param.ty {
                        ParamType::Scalar(ty) => PointeeType::Scalar(*ty),
                        ParamType::Struct(type_name) => PointeeType::Struct(type_name.clone()),
                        ParamType::Array2D(_, _) => {
                            return Err(CustError::new("internal pointer parameter type mismatch"));
                        }
                    };
                    self.ensure_pointer_conversion_preserves_const(
                        param.points_to_const,
                        arg_expr,
                    )?;
                    let pointer = self.eval_pointer(arg_expr)?;
                    self.ensure_pointer_type_matches(&ty, &pointer)?;
                    Value::Pointer {
                        pointer,
                        ty,
                        points_to_const: param.points_to_const,
                    }
                }
                ParamKind::Struct => {
                    let ParamType::Struct(type_name) = &param.ty else {
                        return Err(CustError::new("internal struct parameter type mismatch"));
                    };
                    self.eval_struct_argument(name, &param.name, type_name, arg_expr)?
                }
                ParamKind::Array2D => {
                    let ParamType::Array2D(expected_type, expected_columns) = &param.ty else {
                        return Err(CustError::new(
                            "internal two-dimensional array parameter type mismatch",
                        ));
                    };
                    if !self.expr_is_pointer_value(arg_expr) {
                        return Err(CustError::new(format!(
                            "function '{name}' parameter '{}' requires a two-dimensional array argument",
                            param.name
                        )));
                    }
                    let pointer = self.eval_pointer(arg_expr)?;
                    let pointer = self.attach_array_pointer_owner(pointer);
                    let PointerValue::Array2DRow {
                        array,
                        source_name,
                        row,
                        owner,
                    } = pointer
                    else {
                        return Err(CustError::new(format!(
                            "function '{name}' parameter '{}' requires a two-dimensional array argument",
                            param.name
                        )));
                    };
                    let (actual_type, actual_columns, read_only) = {
                        let array = array.borrow();
                        let Some((_, columns)) = array.dimensions else {
                            return Err(CustError::new(format!(
                                "function '{name}' parameter '{}' requires a two-dimensional array argument",
                                param.name
                            )));
                        };
                        (array.elem_type, columns, array.read_only)
                    };
                    let argument_points_to_const =
                        read_only || self.pointer_expr_points_to_const(arg_expr);
                    if argument_points_to_const && !param.points_to_const {
                        let argument_label = source_name
                            .as_deref()
                            .or(match arg_expr {
                                Expr::Var(argument_name) => Some(argument_name.as_str()),
                                _ => None,
                            })
                            .unwrap_or("expression");
                        return Err(CustError::new(format!(
                            "cannot discard const qualifier from two-dimensional array argument '{argument_label}'"
                        )));
                    }
                    if actual_type != *expected_type || actual_columns != *expected_columns {
                        let expected_label = match expected_type {
                            CType::Int => "int",
                            CType::Char => "char",
                            CType::Bool => "_Bool",
                        };
                        return Err(CustError::new(format!(
                            "function '{name}' parameter '{}' expected a two-dimensional {expected_label} array with {expected_columns} columns",
                            param.name
                        )));
                    }
                    Value::Pointer {
                        pointer: PointerValue::Array2DRow {
                            array,
                            source_name,
                            row,
                            owner,
                        },
                        ty: PointeeType::Scalar(*expected_type),
                        points_to_const: param.points_to_const,
                    }
                }
            };
            if param_scope.insert(param.name.clone(), arg).is_some() {
                return Err(CustError::new(format!(
                    "parameter '{}' already declared in this function",
                    param.name
                )));
            }
            if param.is_const || (matches!(param.kind, ParamKind::Array2D) && param.points_to_const)
            {
                const_params.insert(param.name.clone());
            }
        }

        self.call_depth += 1;
        self.return_type_stack.push(function.return_type.clone());
        self.push_scope_with_values_and_consts(param_scope, const_params);
        for param in &function.params {
            if let (ParamKind::Array2D, ParamType::Array2D(elem_type, columns)) =
                (&param.kind, &param.ty)
            {
                self.mark_current_array2d_pointer_type(&param.name, *elem_type, *columns);
            }
        }
        let result = match self.exec_block(&function.body) {
            Ok(ExecFlow::Return(value)) => {
                self.validate_return_value(name, &function.return_type, value)
            }
            Ok(ExecFlow::None) => match &function.return_type {
                ReturnType::Scalar(_) => Err(CustError::new(format!(
                    "function '{name}' finished without return"
                ))),
                ReturnType::Pointer { .. } | ReturnType::Array2DPointer { .. } => Err(
                    CustError::new(format!("function '{name}' finished without return")),
                ),
                ReturnType::Struct(_) => Err(CustError::new(format!(
                    "function '{name}' finished without return"
                ))),
                ReturnType::Void => Ok(None),
            },
            Ok(ExecFlow::Break(token)) => Err(Self::break_outside_loop_or_switch_error(&token)),
            Ok(ExecFlow::Continue(token)) => Err(Self::continue_outside_loop_error(&token)),
            Err(error) => Err(error),
        };
        self.pop_scope();
        self.return_type_stack.pop();
        self.call_depth -= 1;
        result
    }

    fn has_integer_absolute_value_prototype(&self, name: &str) -> bool {
        if !matches!(name, "abs" | "labs" | "llabs") {
            return false;
        }
        let expected = FunctionSignature {
            return_type: ReturnType::Scalar(CType::Int),
            params: vec![ParamSignature {
                ty: ParamType::Scalar(CType::Int),
                kind: ParamKind::Scalar,
                points_to_const: false,
            }],
        };
        self.prototypes.get(name) == Some(&expected)
    }

    fn call_integer_absolute_value_function(
        &mut self,
        name: &str,
        arg_exprs: &[Expr],
    ) -> CustResult<Option<ReturnValue>> {
        if arg_exprs.len() != 1 {
            return Err(CustError::new(format!(
                "function '{name}' expected 1 arguments, got {}",
                arg_exprs.len()
            )));
        }
        let value = self.eval_scalar_conversion(CType::Int, &arg_exprs[0])?;
        let value = value.checked_abs().ok_or_else(|| {
            CustError::new(format!(
                "integer absolute value overflow in function '{name}'"
            ))
        })?;
        Ok(Some(ReturnValue::Scalar(value)))
    }

    fn has_integer_string_conversion_prototype(&self, name: &str) -> bool {
        if !matches!(name, "atoi" | "atol" | "atoll") {
            return false;
        }
        let expected = FunctionSignature {
            return_type: ReturnType::Scalar(CType::Int),
            params: vec![ParamSignature {
                ty: ParamType::Scalar(CType::Char),
                kind: ParamKind::Pointer,
                points_to_const: true,
            }],
        };
        self.prototypes.get(name) == Some(&expected)
    }

    fn call_integer_string_conversion_function(
        &mut self,
        name: &str,
        arg_exprs: &[Expr],
    ) -> CustResult<Option<ReturnValue>> {
        if arg_exprs.len() != 1 {
            return Err(CustError::new(format!(
                "function '{name}' expected 1 arguments, got {}",
                arg_exprs.len()
            )));
        }
        let pointer = self.eval_pointer(&arg_exprs[0])?;
        if matches!(pointer, PointerValue::Null) {
            return Err(CustError::new(format!(
                "null character pointer passed to function '{name}'"
            )));
        }
        self.ensure_pointer_type_matches(&PointeeType::Scalar(CType::Char), &pointer)?;
        let value = match &pointer {
            PointerValue::ArrayBase { array, .. } => {
                let array = array.borrow();
                Self::parse_bounded_integer_string(name, &array.elements)?
            }
            PointerValue::ArrayElement { array, index, .. } => {
                let array = array.borrow();
                Self::parse_bounded_integer_string(name, &array.elements[*index..])?
            }
            PointerValue::Scalar { .. }
            | PointerValue::StructField { .. }
            | PointerValue::StructFieldElementField { .. } => {
                Self::parse_bounded_integer_string(name, &[self.deref_pointer(&pointer)?])?
            }
            PointerValue::Null
            | PointerValue::Struct { .. }
            | PointerValue::StructElement { .. }
            | PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. }
            | PointerValue::Array2DRow { .. } => {
                return Err(CustError::new(format!(
                    "function '{name}' requires a pointer to character storage"
                )));
            }
        };
        Ok(Some(ReturnValue::Scalar(value)))
    }

    fn parse_bounded_integer_string(name: &str, bytes: &[i64]) -> CustResult<i64> {
        let mut sign = 1_i64;
        let mut value = 0_i64;
        let mut saw_sign = false;
        let mut saw_digit = false;
        let mut conversion_finished = false;
        let mut overflowed = false;

        for (offset, byte) in bytes.iter().copied().enumerate() {
            if byte == 0 {
                if overflowed {
                    return Err(CustError::new(format!(
                        "integer string conversion overflow in function '{name}'"
                    )));
                }
                return Ok(if saw_digit { value } else { 0 });
            }
            if offset >= MAX_INTEGER_STRING_BYTES {
                return Err(CustError::new(format!(
                    "function '{name}' exceeded maximum input length of {MAX_INTEGER_STRING_BYTES} bytes"
                )));
            }
            if conversion_finished {
                continue;
            }
            if !saw_sign && !saw_digit && matches!(byte, 9..=13 | 32) {
                continue;
            }
            if !saw_sign && !saw_digit && matches!(byte, 43 | 45) {
                saw_sign = true;
                if byte == 45 {
                    sign = -1;
                }
                continue;
            }
            if (48..=57).contains(&byte) {
                saw_digit = true;
                if overflowed {
                    continue;
                }
                let digit = byte - 48;
                let next = if sign < 0 {
                    value
                        .checked_mul(10)
                        .and_then(|value| value.checked_sub(digit))
                } else {
                    value
                        .checked_mul(10)
                        .and_then(|value| value.checked_add(digit))
                };
                match next {
                    Some(next) => value = next,
                    None => overflowed = true,
                }
            } else {
                conversion_finished = true;
            }
        }

        Err(CustError::new(format!(
            "unterminated character sequence passed to function '{name}'"
        )))
    }

    fn sizeof_integer_string_conversion_call(&self, name: &str, args: &[Expr]) -> CustResult<i64> {
        if args.len() != 1 {
            return Err(CustError::new(format!(
                "function '{name}' expected 1 arguments, got {}",
                args.len()
            )));
        }
        if matches!(args[0], Expr::Number(0)) {
            return Ok(INT_SIZE);
        }
        match self.pointer_expr_pointee_type(&args[0])? {
            Some(PointeeType::Scalar(CType::Char)) => Ok(INT_SIZE),
            Some(actual) => Err(CustError::new(format!(
                "cannot convert pointer to {} to pointer to char",
                self.pointee_label(&actual)
            ))),
            None => Err(CustError::new(format!(
                "function '{name}' requires a pointer to character storage"
            ))),
        }
    }

    fn has_string_comparison_prototype(&self, name: &str) -> bool {
        if name != "strcmp" {
            return false;
        }
        let character_pointer = ParamSignature {
            ty: ParamType::Scalar(CType::Char),
            kind: ParamKind::Pointer,
            points_to_const: true,
        };
        let expected = FunctionSignature {
            return_type: ReturnType::Scalar(CType::Int),
            params: vec![character_pointer.clone(), character_pointer],
        };
        self.prototypes.get(name) == Some(&expected)
    }

    fn call_string_comparison_function(
        &mut self,
        name: &str,
        arg_exprs: &[Expr],
    ) -> CustResult<Option<ReturnValue>> {
        if arg_exprs.len() != 2 {
            return Err(CustError::new(format!(
                "function '{name}' expected 2 arguments, got {}",
                arg_exprs.len()
            )));
        }

        let left = self.eval_pointer(&arg_exprs[0])?;
        let right = self.eval_pointer(&arg_exprs[1])?;
        self.validate_character_pointer_argument(name, 1, &left)?;
        self.validate_character_pointer_argument(name, 2, &right)?;

        let left = self.read_bounded_character_sequence(name, 1, &left)?;
        let right = self.read_bounded_character_sequence(name, 2, &right)?;
        let result = match left.cmp(&right) {
            std::cmp::Ordering::Less => -1,
            std::cmp::Ordering::Equal => 0,
            std::cmp::Ordering::Greater => 1,
        };
        Ok(Some(ReturnValue::Scalar(result)))
    }

    fn validate_character_pointer_argument(
        &self,
        name: &str,
        argument: usize,
        pointer: &PointerValue,
    ) -> CustResult<()> {
        if matches!(pointer, PointerValue::Null) {
            return Err(CustError::new(format!(
                "null character pointer passed as argument {argument} to function '{name}'"
            )));
        }
        if matches!(pointer, PointerValue::ArrayBase { array, .. } if array.borrow().dimensions.is_some())
        {
            return Err(CustError::new(format!(
                "function '{name}' requires character storage for argument {argument}"
            )));
        }
        self.ensure_pointer_type_matches(&PointeeType::Scalar(CType::Char), pointer)
    }

    fn read_bounded_character_sequence(
        &self,
        name: &str,
        argument: usize,
        pointer: &PointerValue,
    ) -> CustResult<Vec<u8>> {
        let scalar;
        let bytes = match pointer {
            PointerValue::ArrayBase { array, .. } => {
                let array = array.borrow();
                return Self::copy_bounded_character_sequence(name, argument, &array.elements);
            }
            PointerValue::ArrayElement { array, index, .. } => {
                let array = array.borrow();
                let end = Self::character_sequence_array_end(&array, *index);
                return Self::copy_bounded_character_sequence(
                    name,
                    argument,
                    &array.elements[*index..end],
                );
            }
            PointerValue::Scalar { .. }
            | PointerValue::StructField { .. }
            | PointerValue::StructFieldElementField { .. } => {
                scalar = [self.deref_pointer(pointer)?];
                &scalar
            }
            PointerValue::Null
            | PointerValue::Struct { .. }
            | PointerValue::StructElement { .. }
            | PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. }
            | PointerValue::Array2DRow { .. } => {
                return Err(CustError::new(format!(
                    "function '{name}' requires character storage for argument {argument}"
                )));
            }
        };
        Self::copy_bounded_character_sequence(name, argument, bytes)
    }

    fn character_sequence_array_end(array: &ArrayValue, index: usize) -> usize {
        match array.dimensions {
            Some((_, columns)) => index
                .checked_div(columns)
                .and_then(|row| row.checked_add(1))
                .and_then(|row| row.checked_mul(columns))
                .unwrap_or(array.elements.len())
                .min(array.elements.len()),
            None => array.elements.len(),
        }
    }

    fn copy_bounded_character_sequence(
        name: &str,
        argument: usize,
        bytes: &[i64],
    ) -> CustResult<Vec<u8>> {
        let mut result = Vec::with_capacity(bytes.len().min(MAX_INTEGER_STRING_BYTES));
        for (offset, byte) in bytes.iter().copied().enumerate() {
            let byte = byte.rem_euclid(256) as u8;
            if byte == 0 {
                return Ok(result);
            }
            if offset >= MAX_INTEGER_STRING_BYTES {
                return Err(CustError::new(format!(
                    "argument {argument} to function '{name}' exceeded maximum input length of {MAX_INTEGER_STRING_BYTES} bytes"
                )));
            }
            result.push(byte);
        }
        Err(CustError::new(format!(
            "unterminated character sequence passed as argument {argument} to function '{name}'"
        )))
    }

    fn sizeof_string_comparison_call(&self, name: &str, args: &[Expr]) -> CustResult<i64> {
        if args.len() != 2 {
            return Err(CustError::new(format!(
                "function '{name}' expected 2 arguments, got {}",
                args.len()
            )));
        }
        for argument in args {
            if matches!(argument, Expr::Number(0)) {
                continue;
            }
            match self.pointer_expr_pointee_type(argument)? {
                Some(PointeeType::Scalar(CType::Char)) => {}
                Some(actual) => {
                    return Err(CustError::new(format!(
                        "cannot convert pointer to {} to pointer to char",
                        self.pointee_label(&actual)
                    )));
                }
                None => {
                    return Err(CustError::new(format!(
                        "function '{name}' requires pointers to character storage"
                    )));
                }
            }
        }
        Ok(INT_SIZE)
    }

    fn has_string_prefix_comparison_prototype(&self, name: &str) -> bool {
        if name != "strncmp" {
            return false;
        }
        let character_pointer = ParamSignature {
            ty: ParamType::Scalar(CType::Char),
            kind: ParamKind::Pointer,
            points_to_const: true,
        };
        let expected = FunctionSignature {
            return_type: ReturnType::Scalar(CType::Int),
            params: vec![
                character_pointer.clone(),
                character_pointer,
                ParamSignature {
                    ty: ParamType::Scalar(CType::Int),
                    kind: ParamKind::Scalar,
                    points_to_const: false,
                },
            ],
        };
        self.prototypes.get(name) == Some(&expected)
    }

    fn call_string_prefix_comparison_function(
        &mut self,
        name: &str,
        arg_exprs: &[Expr],
    ) -> CustResult<Option<ReturnValue>> {
        if arg_exprs.len() != 3 {
            return Err(CustError::new(format!(
                "function '{name}' expected 3 arguments, got {}",
                arg_exprs.len()
            )));
        }

        let left = self.eval_pointer(&arg_exprs[0])?;
        let right = self.eval_pointer(&arg_exprs[1])?;
        let count = self.eval_scalar_conversion(CType::Int, &arg_exprs[2])?;
        self.validate_character_pointer_argument(name, 1, &left)?;
        self.validate_character_pointer_argument(name, 2, &right)?;
        if count < 0 {
            return Err(CustError::new(format!(
                "function '{name}' requires a nonnegative count, got {count}"
            )));
        }
        let count = usize::try_from(count).map_err(|_| {
            CustError::new(format!(
                "function '{name}' count exceeds maximum comparison length of {MAX_INTEGER_STRING_BYTES} bytes"
            ))
        })?;
        if count > MAX_INTEGER_STRING_BYTES {
            return Err(CustError::new(format!(
                "function '{name}' count {count} exceeds maximum comparison length of {MAX_INTEGER_STRING_BYTES} bytes"
            )));
        }

        for offset in 0..count {
            let left = self.read_character_comparison_byte(name, 1, &left, offset, count)?;
            let right = self.read_character_comparison_byte(name, 2, &right, offset, count)?;
            match left.cmp(&right) {
                std::cmp::Ordering::Less => return Ok(Some(ReturnValue::Scalar(-1))),
                std::cmp::Ordering::Greater => return Ok(Some(ReturnValue::Scalar(1))),
                std::cmp::Ordering::Equal if left == 0 => {
                    return Ok(Some(ReturnValue::Scalar(0)));
                }
                std::cmp::Ordering::Equal => {}
            }
        }
        Ok(Some(ReturnValue::Scalar(0)))
    }

    fn read_character_comparison_byte(
        &self,
        name: &str,
        argument: usize,
        pointer: &PointerValue,
        offset: usize,
        count: usize,
    ) -> CustResult<u8> {
        let byte = match pointer {
            PointerValue::ArrayBase { array, .. } => array.borrow().elements.get(offset).copied(),
            PointerValue::ArrayElement { array, index, .. } => index
                .checked_add(offset)
                .and_then(|index| array.borrow().elements.get(index).copied()),
            PointerValue::Scalar { .. }
            | PointerValue::StructField { .. }
            | PointerValue::StructFieldElementField { .. } => {
                if offset == 0 {
                    Some(self.deref_pointer(pointer)?)
                } else {
                    None
                }
            }
            PointerValue::Null
            | PointerValue::Struct { .. }
            | PointerValue::StructElement { .. }
            | PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. }
            | PointerValue::Array2DRow { .. } => {
                return Err(CustError::new(format!(
                    "function '{name}' requires character storage for argument {argument}"
                )));
            }
        };
        byte.map(|byte| byte.rem_euclid(256) as u8)
            .ok_or_else(|| {
                CustError::new(format!(
                    "unterminated character sequence passed as argument {argument} to function '{name}' before requested count {count}"
                ))
            })
    }

    fn sizeof_string_prefix_comparison_call(&self, name: &str, args: &[Expr]) -> CustResult<i64> {
        if args.len() != 3 {
            return Err(CustError::new(format!(
                "function '{name}' expected 3 arguments, got {}",
                args.len()
            )));
        }
        self.sizeof_string_comparison_call(name, &args[..2])?;
        if self.expr_is_pointer_value(&args[2])
            || self.aggregate_expr_type_name(&args[2]).is_ok()
            || self.expr_is_void_value(&args[2])
        {
            return Err(CustError::new(format!(
                "function '{name}' requires an integer count"
            )));
        }
        self.sizeof_expr(&args[2])?;
        Ok(INT_SIZE)
    }

    fn has_string_length_prototype(&self, name: &str) -> bool {
        if name != "strlen" {
            return false;
        }
        let expected = FunctionSignature {
            return_type: ReturnType::Scalar(CType::Int),
            params: vec![ParamSignature {
                ty: ParamType::Scalar(CType::Char),
                kind: ParamKind::Pointer,
                points_to_const: true,
            }],
        };
        self.prototypes.get(name) == Some(&expected)
    }

    fn call_string_length_function(
        &mut self,
        name: &str,
        arg_exprs: &[Expr],
    ) -> CustResult<Option<ReturnValue>> {
        if arg_exprs.len() != 1 {
            return Err(CustError::new(format!(
                "function '{name}' expected 1 arguments, got {}",
                arg_exprs.len()
            )));
        }

        let pointer = self.eval_pointer(&arg_exprs[0])?;
        self.validate_character_pointer_argument(name, 1, &pointer)?;
        let length = self
            .read_bounded_character_sequence(name, 1, &pointer)?
            .len() as i64;
        Ok(Some(ReturnValue::Scalar(length)))
    }

    fn sizeof_string_length_call(&self, name: &str, args: &[Expr]) -> CustResult<i64> {
        self.sizeof_integer_string_conversion_call(name, args)
    }

    fn has_character_search_prototype(&self, name: &str) -> bool {
        if !matches!(name, "strchr" | "strrchr") {
            return false;
        }
        let expected = FunctionSignature {
            return_type: ReturnType::Pointer {
                ty: PointeeType::Scalar(CType::Char),
                points_to_const: false,
            },
            params: vec![
                ParamSignature {
                    ty: ParamType::Scalar(CType::Char),
                    kind: ParamKind::Pointer,
                    points_to_const: true,
                },
                ParamSignature {
                    ty: ParamType::Scalar(CType::Int),
                    kind: ParamKind::Scalar,
                    points_to_const: false,
                },
            ],
        };
        self.prototypes.get(name) == Some(&expected)
    }

    fn call_character_search_function(
        &mut self,
        name: &str,
        arg_exprs: &[Expr],
    ) -> CustResult<Option<ReturnValue>> {
        if arg_exprs.len() != 2 {
            return Err(CustError::new(format!(
                "function '{name}' expected 2 arguments, got {}",
                arg_exprs.len()
            )));
        }

        let pointer = self.eval_pointer(&arg_exprs[0])?;
        let search_expr = &arg_exprs[1];
        if self.expr_is_pointer_value(search_expr) {
            self.eval_pointer(search_expr)?;
            return Err(CustError::new(format!(
                "function '{name}' requires an integer search value"
            )));
        }
        if self.aggregate_expr_type_name(search_expr).is_ok() {
            self.eval_struct_expr(search_expr)?;
            return Err(CustError::new(format!(
                "function '{name}' requires an integer search value"
            )));
        }
        if self.expr_is_void_value(search_expr) {
            self.eval_discard(search_expr)?;
            return Err(CustError::new(format!(
                "function '{name}' requires an integer search value"
            )));
        }
        let search = self
            .eval_scalar_conversion(CType::Int, search_expr)?
            .rem_euclid(256) as u8;
        self.validate_character_pointer_argument(name, 1, &pointer)?;
        let mut last_match = None;

        for offset in 0.. {
            let byte = match &pointer {
                PointerValue::ArrayBase { array, .. } => {
                    array.borrow().elements.get(offset).copied()
                }
                PointerValue::ArrayElement { array, index, .. } => index
                    .checked_add(offset)
                    .and_then(|index| array.borrow().elements.get(index).copied()),
                _ if offset == 0 => Some(self.deref_pointer(&pointer)?),
                _ => None,
            }
            .map(|byte| byte.rem_euclid(256) as u8)
            .ok_or_else(|| {
                CustError::new(format!(
                    "unterminated character sequence passed as argument 1 to function '{name}'"
                ))
            })?;

            if byte == 0 {
                let matched_offset = if search == 0 {
                    Some(offset)
                } else {
                    last_match
                };
                let result = match matched_offset {
                    Some(0) => pointer.clone(),
                    Some(offset) => self.offset_array_pointer(&pointer, offset as i64)?,
                    None => PointerValue::Null,
                };
                return Ok(Some(ReturnValue::Pointer {
                    pointer: result,
                    ty: PointeeType::Scalar(CType::Char),
                    points_to_const: false,
                }));
            }
            if offset >= MAX_INTEGER_STRING_BYTES {
                return Err(CustError::new(format!(
                    "argument 1 to function '{name}' exceeded maximum input length of {MAX_INTEGER_STRING_BYTES} bytes"
                )));
            }
            if byte == search {
                if name == "strchr" {
                    let result = if offset == 0 {
                        pointer.clone()
                    } else {
                        self.offset_array_pointer(&pointer, offset as i64)?
                    };
                    return Ok(Some(ReturnValue::Pointer {
                        pointer: result,
                        ty: PointeeType::Scalar(CType::Char),
                        points_to_const: false,
                    }));
                }
                last_match = Some(offset);
            }
        }
        unreachable!("bounded character search always returns or errors")
    }

    fn sizeof_character_search_call(&self, name: &str, args: &[Expr]) -> CustResult<i64> {
        if args.len() != 2 {
            return Err(CustError::new(format!(
                "function '{name}' expected 2 arguments, got {}",
                args.len()
            )));
        }
        self.sizeof_integer_string_conversion_call(name, &args[..1])?;
        if self.expr_is_pointer_value(&args[1])
            || self.aggregate_expr_type_name(&args[1]).is_ok()
            || self.expr_is_void_value(&args[1])
        {
            return Err(CustError::new(format!(
                "function '{name}' requires an integer search value"
            )));
        }
        self.sizeof_expr(&args[1])?;
        Ok(POINTER_SIZE)
    }

    fn has_character_set_search_prototype(&self, name: &str) -> bool {
        if !matches!(name, "strpbrk" | "strstr") {
            return false;
        }
        let character_pointer = ParamSignature {
            ty: ParamType::Scalar(CType::Char),
            kind: ParamKind::Pointer,
            points_to_const: true,
        };
        let expected = FunctionSignature {
            return_type: ReturnType::Pointer {
                ty: PointeeType::Scalar(CType::Char),
                points_to_const: false,
            },
            params: vec![character_pointer.clone(), character_pointer],
        };
        self.prototypes.get(name) == Some(&expected)
    }

    fn call_character_set_search_function(
        &mut self,
        name: &str,
        arg_exprs: &[Expr],
    ) -> CustResult<Option<ReturnValue>> {
        if arg_exprs.len() != 2 {
            return Err(CustError::new(format!(
                "function '{name}' expected 2 arguments, got {}",
                arg_exprs.len()
            )));
        }

        let text_pointer = self.eval_pointer(&arg_exprs[0])?;
        let accept_pointer = self.eval_pointer(&arg_exprs[1])?;
        self.validate_character_pointer_argument(name, 1, &text_pointer)?;
        self.validate_character_pointer_argument(name, 2, &accept_pointer)?;
        let text = self.read_bounded_character_sequence(name, 1, &text_pointer)?;
        let accept = self.read_bounded_character_sequence(name, 2, &accept_pointer)?;

        let matched_offset = if name == "strstr" {
            if accept.is_empty() {
                Some(0)
            } else {
                text.windows(accept.len())
                    .position(|window| window == accept)
            }
        } else {
            text.iter().position(|byte| accept.contains(byte))
        };
        let result = match matched_offset {
            Some(0) => text_pointer,
            Some(offset) => self.offset_array_pointer(&text_pointer, offset as i64)?,
            None => PointerValue::Null,
        };
        Ok(Some(ReturnValue::Pointer {
            pointer: result,
            ty: PointeeType::Scalar(CType::Char),
            points_to_const: false,
        }))
    }

    fn sizeof_character_set_search_call(&self, name: &str, args: &[Expr]) -> CustResult<i64> {
        self.sizeof_string_comparison_call(name, args)?;
        Ok(POINTER_SIZE)
    }

    fn has_string_copy_prototype(&self, name: &str) -> bool {
        if name != "strcpy" {
            return false;
        }
        let expected = FunctionSignature {
            return_type: ReturnType::Pointer {
                ty: PointeeType::Scalar(CType::Char),
                points_to_const: false,
            },
            params: vec![
                ParamSignature {
                    ty: ParamType::Scalar(CType::Char),
                    kind: ParamKind::Pointer,
                    points_to_const: false,
                },
                ParamSignature {
                    ty: ParamType::Scalar(CType::Char),
                    kind: ParamKind::Pointer,
                    points_to_const: true,
                },
            ],
        };
        self.prototypes.get(name) == Some(&expected)
    }

    fn call_string_copy_function(
        &mut self,
        name: &str,
        arg_exprs: &[Expr],
    ) -> CustResult<Option<ReturnValue>> {
        if arg_exprs.len() != 2 {
            return Err(CustError::new(format!(
                "function '{name}' expected 2 arguments, got {}",
                arg_exprs.len()
            )));
        }

        let destination = self.eval_pointer(&arg_exprs[0])?;
        let source = self.eval_pointer(&arg_exprs[1])?;
        for (index, argument) in arg_exprs.iter().enumerate() {
            if self.array2d_row_pointer_element_type(argument).is_some() {
                return Err(CustError::new(format!(
                    "function '{name}' requires character storage for argument {}",
                    index + 1
                )));
            }
        }
        self.ensure_pointer_conversion_preserves_const(false, &arg_exprs[0])?;
        self.validate_character_pointer_argument(name, 1, &destination)?;
        self.validate_character_pointer_argument(name, 2, &source)?;

        let mut bytes = self.read_bounded_character_sequence(name, 2, &source)?;
        bytes.push(0);
        let current = self.deref_pointer(&destination)?;
        self.assign_deref_pointer(&destination, current)?;
        self.ensure_string_copy_destination_capacity(name, &destination, bytes.len())?;
        self.ensure_string_copy_ranges_do_not_overlap(name, &destination, &source, bytes.len())?;
        for (offset, byte) in bytes.into_iter().enumerate() {
            if offset == 0 {
                self.assign_deref_pointer(&destination, i64::from(byte))?;
            } else {
                self.assign_pointer_index(&destination, offset as i64, i64::from(byte))?;
            }
        }

        Ok(Some(ReturnValue::Pointer {
            pointer: destination,
            ty: PointeeType::Scalar(CType::Char),
            points_to_const: false,
        }))
    }

    fn ensure_string_copy_destination_capacity(
        &self,
        name: &str,
        destination: &PointerValue,
        required: usize,
    ) -> CustResult<()> {
        let available = match destination {
            PointerValue::ArrayBase { array, .. } => array.borrow().elements.len(),
            PointerValue::ArrayElement { array, index, .. } => {
                let array = array.borrow();
                Self::character_sequence_array_end(&array, *index).saturating_sub(*index)
            }
            PointerValue::Scalar { .. }
            | PointerValue::StructField { .. }
            | PointerValue::StructFieldElementField { .. } => 1,
            PointerValue::Null
            | PointerValue::Struct { .. }
            | PointerValue::StructElement { .. }
            | PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. }
            | PointerValue::Array2DRow { .. } => {
                return Err(CustError::new(format!(
                    "function '{name}' requires character storage for argument 1"
                )));
            }
        };
        if required > available {
            return Err(CustError::new(format!(
                "destination argument 1 to function '{name}' requires {required} bytes, but only {available} bytes are available"
            )));
        }
        Ok(())
    }

    fn ensure_string_copy_ranges_do_not_overlap(
        &self,
        name: &str,
        destination: &PointerValue,
        source: &PointerValue,
        len: usize,
    ) -> CustResult<()> {
        let overlaps = match (
            Self::character_array_pointer_position(destination),
            Self::character_array_pointer_position(source),
        ) {
            (Some((destination_array, destination_start)), Some((source_array, source_start))) => {
                Rc::ptr_eq(destination_array, source_array)
                    && destination_start < source_start.saturating_add(len)
                    && source_start < destination_start.saturating_add(len)
            }
            _ => Self::pointer_eq(destination, source),
        };
        if overlaps {
            return Err(CustError::new(format!(
                "overlapping source and destination ranges passed to function '{name}'"
            )));
        }
        Ok(())
    }

    fn character_array_pointer_position(
        pointer: &PointerValue,
    ) -> Option<(&Rc<RefCell<ArrayValue>>, usize)> {
        match pointer {
            PointerValue::ArrayBase { array, .. } => Some((array, 0)),
            PointerValue::ArrayElement { array, index, .. } => Some((array, *index)),
            _ => None,
        }
    }

    fn sizeof_string_copy_call(&self, name: &str, args: &[Expr]) -> CustResult<i64> {
        if args.len() != 2 {
            return Err(CustError::new(format!(
                "function '{name}' expected 2 arguments, got {}",
                args.len()
            )));
        }
        if args
            .iter()
            .any(|argument| self.array2d_row_pointer_element_type(argument).is_some())
        {
            return Err(CustError::new(format!(
                "function '{name}' requires pointers to character storage"
            )));
        }
        self.sizeof_string_comparison_call(name, args)?;
        if !matches!(args[0], Expr::Number(0)) && self.pointer_expr_points_to_const(&args[0]) {
            return Err(CustError::new(
                "cannot discard const qualifier from pointer target",
            ));
        }
        Ok(POINTER_SIZE)
    }

    fn has_string_span_prototype(&self, name: &str) -> bool {
        if !matches!(name, "strspn" | "strcspn") {
            return false;
        }
        let character_pointer = ParamSignature {
            ty: ParamType::Scalar(CType::Char),
            kind: ParamKind::Pointer,
            points_to_const: true,
        };
        let expected = FunctionSignature {
            return_type: ReturnType::Scalar(CType::Int),
            params: vec![character_pointer.clone(), character_pointer],
        };
        self.prototypes.get(name) == Some(&expected)
    }

    fn call_string_span_function(
        &mut self,
        name: &str,
        arg_exprs: &[Expr],
    ) -> CustResult<Option<ReturnValue>> {
        if arg_exprs.len() != 2 {
            return Err(CustError::new(format!(
                "function '{name}' expected 2 arguments, got {}",
                arg_exprs.len()
            )));
        }

        let text_pointer = self.eval_pointer(&arg_exprs[0])?;
        let accept_pointer = self.eval_pointer(&arg_exprs[1])?;
        self.validate_character_pointer_argument(name, 1, &text_pointer)?;
        self.validate_character_pointer_argument(name, 2, &accept_pointer)?;
        let text = self.read_bounded_character_sequence(name, 1, &text_pointer)?;
        let accept = self.read_bounded_character_sequence(name, 2, &accept_pointer)?;
        let length = text
            .iter()
            .take_while(|byte| accept.contains(byte) == (name == "strspn"))
            .count() as i64;

        Ok(Some(ReturnValue::Scalar(length)))
    }

    fn sizeof_string_span_call(&self, name: &str, args: &[Expr]) -> CustResult<i64> {
        self.sizeof_string_comparison_call(name, args)
    }

    fn validate_nested_string_intrinsic_calls(&self, expr: &Expr) -> CustResult<()> {
        match expr {
            Expr::Call { name, args } => {
                if matches!(name.as_str(), "strpbrk" | "strstr")
                    && !self.functions.contains_key(name)
                {
                    if self.has_character_set_search_prototype(name) {
                        self.sizeof_character_set_search_call(name, args)?;
                    } else if self.prototypes.contains_key(name) {
                        return Err(CustError::new(format!(
                            "standard library function '{name}' has an unsupported declaration; expected two pointer-to-const-character parameters and a pointer-to-character return type"
                        )));
                    } else {
                        return Err(CustError::new(format!("undefined function '{name}'")));
                    }
                }
                if name == "strcpy" && !self.functions.contains_key(name) {
                    if self.has_string_copy_prototype(name) {
                        self.sizeof_string_copy_call(name, args)?;
                    } else if self.prototypes.contains_key(name) {
                        return Err(CustError::new(
                            "standard library function 'strcpy' has an unsupported declaration; expected one pointer-to-character destination parameter, one pointer-to-const-character source parameter, and a pointer-to-character return type",
                        ));
                    } else {
                        return Err(CustError::new("undefined function 'strcpy'"));
                    }
                }
                if matches!(name.as_str(), "strspn" | "strcspn")
                    && !self.functions.contains_key(name)
                {
                    if self.has_string_span_prototype(name) {
                        self.sizeof_string_span_call(name, args)?;
                    } else if self.prototypes.contains_key(name) {
                        return Err(CustError::new(format!(
                            "standard library function '{name}' has an unsupported declaration; expected two pointer-to-const-character parameters and an integer return type"
                        )));
                    } else {
                        return Err(CustError::new(format!("undefined function '{name}'")));
                    }
                }
                for arg in args {
                    self.validate_nested_string_intrinsic_calls(arg)?;
                }
            }
            Expr::Number(_)
            | Expr::StringLiteral(_)
            | Expr::SizeOfType(_)
            | Expr::AlignOfType(_)
            | Expr::Var(_)
            | Expr::StructGet { .. }
            | Expr::AddressOf(_)
            | Expr::AddressOfStructField { .. } => {}
            Expr::SizeOfValue(inner)
            | Expr::Deref(inner)
            | Expr::VoidCast(inner)
            | Expr::UnaryPlus(inner)
            | Expr::UnaryMinus(inner)
            | Expr::BitwiseNot(inner)
            | Expr::LogicalNot(inner)
            | Expr::Cast { expr: inner, .. }
            | Expr::PointerCast { expr: inner, .. }
            | Expr::ScalarLiteral { init: inner, .. }
            | Expr::AddressOfScalarLiteral { init: inner, .. }
            | Expr::Increment { target: inner, .. }
            | Expr::StructPtrGet { pointer: inner, .. }
            | Expr::AddressOfStructPtrField { pointer: inner, .. }
            | Expr::AggregateFieldGet {
                aggregate: inner, ..
            }
            | Expr::AddressOfAggregateField {
                aggregate: inner, ..
            } => self.validate_nested_string_intrinsic_calls(inner)?,
            Expr::StructArrayGet { index, .. }
            | Expr::StructFieldArrayElementGet { index, .. }
            | Expr::StructElementGet { index, .. }
            | Expr::ArrayGet { index, .. }
            | Expr::StringGet { index, .. }
            | Expr::AddressOfArray { index, .. }
            | Expr::AddressOfStructElementField { index, .. }
            | Expr::AddressOfStructArrayField { index, .. } => {
                self.validate_nested_string_intrinsic_calls(index)?;
            }
            Expr::Assign { value, .. }
            | Expr::StructSet { value, .. }
            | Expr::CompoundAssign { value, .. }
            | Expr::StructCompoundSet { value, .. } => {
                self.validate_nested_string_intrinsic_calls(value)?;
            }
            Expr::StructPtrArrayGet { pointer, index, .. }
            | Expr::AddressOfStructPtrArrayField { pointer, index, .. } => {
                self.validate_nested_string_intrinsic_calls(pointer)?;
                self.validate_nested_string_intrinsic_calls(index)?;
            }
            Expr::StructFieldArrayElementSet { index, value, .. }
            | Expr::StructFieldArrayElementCompoundSet { index, value, .. }
            | Expr::ArraySet { index, value, .. }
            | Expr::StructArraySet { index, value, .. }
            | Expr::StructElementSet { index, value, .. }
            | Expr::ArrayCompoundSet { index, value, .. }
            | Expr::StructArrayCompoundSet { index, value, .. }
            | Expr::StructElementCompoundSet { index, value, .. } => {
                self.validate_nested_string_intrinsic_calls(index)?;
                self.validate_nested_string_intrinsic_calls(value)?;
            }
            Expr::DerefSet { pointer, value }
            | Expr::StructPtrSet { pointer, value, .. }
            | Expr::DerefCompoundSet { pointer, value, .. }
            | Expr::StructPtrCompoundSet { pointer, value, .. } => {
                self.validate_nested_string_intrinsic_calls(pointer)?;
                self.validate_nested_string_intrinsic_calls(value)?;
            }
            Expr::StructElementArrayGet {
                index, array_index, ..
            }
            | Expr::AddressOfStructElementArrayField {
                index, array_index, ..
            } => {
                self.validate_nested_string_intrinsic_calls(index)?;
                self.validate_nested_string_intrinsic_calls(array_index)?;
            }
            Expr::StructElementArraySet {
                index,
                array_index,
                value,
                ..
            }
            | Expr::StructElementArrayCompoundSet {
                index,
                array_index,
                value,
                ..
            } => {
                self.validate_nested_string_intrinsic_calls(index)?;
                self.validate_nested_string_intrinsic_calls(array_index)?;
                self.validate_nested_string_intrinsic_calls(value)?;
            }
            Expr::Array2DGet { row, column, .. } => {
                self.validate_nested_string_intrinsic_calls(row)?;
                self.validate_nested_string_intrinsic_calls(column)?;
            }
            Expr::Array2DSet {
                row, column, value, ..
            }
            | Expr::Array2DCompoundSet {
                row, column, value, ..
            } => {
                self.validate_nested_string_intrinsic_calls(row)?;
                self.validate_nested_string_intrinsic_calls(column)?;
                self.validate_nested_string_intrinsic_calls(value)?;
            }
            Expr::StructArray2DGet {
                target,
                row,
                column,
                ..
            } => {
                self.validate_string_span_array_2d_target(target)?;
                self.validate_nested_string_intrinsic_calls(row)?;
                self.validate_nested_string_intrinsic_calls(column)?;
            }
            Expr::StructArray2DSet {
                target,
                row,
                column,
                value,
                ..
            }
            | Expr::StructArray2DCompoundSet {
                target,
                row,
                column,
                value,
                ..
            } => {
                self.validate_string_span_array_2d_target(target)?;
                self.validate_nested_string_intrinsic_calls(row)?;
                self.validate_nested_string_intrinsic_calls(column)?;
                self.validate_nested_string_intrinsic_calls(value)?;
            }
            Expr::ScalarLiteralSet { init, value, .. }
            | Expr::ScalarLiteralCompoundSet { init, value, .. }
            | Expr::AggregateFieldSet {
                aggregate: init,
                value,
                ..
            }
            | Expr::AggregateFieldCompoundSet {
                aggregate: init,
                value,
                ..
            } => {
                self.validate_nested_string_intrinsic_calls(init)?;
                self.validate_nested_string_intrinsic_calls(value)?;
            }
            Expr::AggregateLiteral { init, .. } | Expr::AddressOfAggregateLiteral { init, .. } => {
                self.validate_string_span_struct_initializers(init)?;
            }
            Expr::ArrayLiteral { init, .. } => {
                self.validate_string_span_array_initializers(init)?;
            }
            Expr::AggregateArrayLiteral { init, .. } => {
                self.validate_string_span_struct_array_initializers(init)?;
            }
            Expr::Conditional {
                cond,
                then_expr,
                else_expr,
            } => {
                self.validate_nested_string_intrinsic_calls(cond)?;
                self.validate_nested_string_intrinsic_calls(then_expr)?;
                self.validate_nested_string_intrinsic_calls(else_expr)?;
            }
            Expr::Binary(left, _, right) | Expr::Comma(left, right) => {
                self.validate_nested_string_intrinsic_calls(left)?;
                self.validate_nested_string_intrinsic_calls(right)?;
            }
        }
        Ok(())
    }

    fn validate_string_span_array_2d_target(&self, target: &Array2DFieldTarget) -> CustResult<()> {
        match target {
            Array2DFieldTarget::Direct { .. } => Ok(()),
            Array2DFieldTarget::Element { index, .. } => {
                self.validate_nested_string_intrinsic_calls(index)
            }
            Array2DFieldTarget::Pointer { pointer, .. } => {
                self.validate_nested_string_intrinsic_calls(pointer)
            }
        }
    }

    fn validate_string_span_array_initializers(
        &self,
        initializers: &[ArrayInitializer],
    ) -> CustResult<()> {
        for initializer in initializers {
            match initializer {
                ArrayInitializer::Expr(expr) | ArrayInitializer::Designated { value: expr, .. } => {
                    self.validate_nested_string_intrinsic_calls(expr)?;
                }
                ArrayInitializer::StringLiteral(_) => {}
            }
        }
        Ok(())
    }

    fn validate_string_span_struct_initializers(
        &self,
        initializers: &[StructInitializer],
    ) -> CustResult<()> {
        for initializer in initializers {
            match initializer {
                StructInitializer::Expr(expr) => {
                    self.validate_nested_string_intrinsic_calls(expr)?
                }
                StructInitializer::Array(values) => {
                    self.validate_string_span_array_initializers(values)?;
                }
                StructInitializer::Array2D(rows) => {
                    for row in rows {
                        self.validate_string_span_array_initializers(row)?;
                    }
                }
                StructInitializer::Struct(values) => {
                    self.validate_string_span_struct_initializers(values)?;
                }
                StructInitializer::StructArray(values) => {
                    self.validate_string_span_struct_array_initializers(values)?;
                }
                StructInitializer::Designated { value, .. } => {
                    self.validate_string_span_struct_initializers(std::slice::from_ref(value))?;
                }
            }
        }
        Ok(())
    }

    fn validate_string_span_struct_array_initializers(
        &self,
        initializers: &[StructArrayInitializer],
    ) -> CustResult<()> {
        for initializer in initializers {
            match initializer {
                StructArrayInitializer::Element(values)
                | StructArrayInitializer::Designated { value: values, .. } => {
                    self.validate_string_span_struct_initializers(values)?;
                }
            }
        }
        Ok(())
    }

    fn validate_return_value(
        &self,
        function_name: &str,
        return_type: &ReturnType,
        value: Option<ReturnValue>,
    ) -> CustResult<Option<ReturnValue>> {
        match (return_type, value) {
            (ReturnType::Scalar(_), Some(ReturnValue::Scalar(value))) => {
                Ok(Some(ReturnValue::Scalar(value)))
            }
            (ReturnType::Scalar(return_type), None) => Err(CustError::new(format!(
                "{} function '{function_name}' returned without a value",
                ReturnType::Scalar(*return_type).value_return_label()
            ))),
            (ReturnType::Scalar(_), Some(ReturnValue::Struct { .. })) => Err(CustError::new(
                format!("struct value returned from scalar function '{function_name}'"),
            )),
            (ReturnType::Scalar(_), Some(ReturnValue::Pointer { .. })) => Err(CustError::new(
                format!("pointer value returned from scalar function '{function_name}'"),
            )),
            (
                ReturnType::Pointer {
                    ty: expected_ty,
                    points_to_const: expected_const,
                },
                Some(ReturnValue::Pointer {
                    pointer,
                    ty,
                    points_to_const,
                }),
            ) if &ty == expected_ty && (!points_to_const || *expected_const) => {
                Ok(Some(ReturnValue::Pointer {
                    pointer,
                    ty,
                    points_to_const,
                }))
            }
            (
                ReturnType::Pointer {
                    ty: expected_ty, ..
                },
                Some(ReturnValue::Pointer { ty, .. }),
            ) if &ty != expected_ty => Err(CustError::new(format!(
                "cannot convert pointer to {} to pointer to {}",
                self.pointee_label(&ty),
                self.pointee_label(expected_ty)
            ))),
            (ReturnType::Pointer { .. }, Some(ReturnValue::Pointer { .. })) => Err(CustError::new(
                "cannot discard const qualifier from pointer target",
            )),
            (ReturnType::Pointer { .. }, Some(ReturnValue::Scalar(_))) => Err(CustError::new(
                format!("pointer function '{function_name}' requires a pointer return value"),
            )),
            (ReturnType::Pointer { .. }, Some(ReturnValue::Struct { .. })) => Err(CustError::new(
                format!("pointer function '{function_name}' requires a pointer return value"),
            )),
            (ReturnType::Pointer { .. }, None) => Err(CustError::new(format!(
                "pointer function '{function_name}' returned without a value"
            ))),
            (
                ReturnType::Array2DPointer {
                    elem_type,
                    columns,
                    points_to_const: expected_const,
                },
                Some(ReturnValue::Pointer {
                    pointer,
                    ty,
                    points_to_const,
                }),
            ) if ty == PointeeType::Scalar(*elem_type) && (!points_to_const || *expected_const) => {
                self.ensure_two_dimensional_row_pointer_type_matches(
                    *elem_type, *columns, &pointer,
                )?;
                Ok(Some(ReturnValue::Pointer {
                    pointer,
                    ty,
                    points_to_const,
                }))
            }
            (ReturnType::Array2DPointer { .. }, Some(ReturnValue::Pointer { .. })) => Err(
                CustError::new("cannot return an incompatible two-dimensional row pointer"),
            ),
            (ReturnType::Array2DPointer { .. }, Some(ReturnValue::Scalar(_)))
            | (ReturnType::Array2DPointer { .. }, Some(ReturnValue::Struct { .. })) => {
                Err(CustError::new(format!(
                    "pointer function '{function_name}' requires a pointer return value"
                )))
            }
            (ReturnType::Array2DPointer { .. }, None) => Err(CustError::new(format!(
                "pointer function '{function_name}' returned without a value"
            ))),
            (
                ReturnType::Struct(expected_type),
                Some(ReturnValue::Struct { type_name, fields }),
            ) if &type_name == expected_type => Ok(Some(ReturnValue::Struct { type_name, fields })),
            (ReturnType::Struct(expected_type), Some(ReturnValue::Struct { type_name, .. })) => {
                Err(CustError::new(format!(
                    "struct function '{function_name}' expected return struct '{}', got struct '{}'",
                    self.aggregate_label(expected_type),
                    self.aggregate_label(&type_name)
                )))
            }
            (ReturnType::Struct(_), Some(ReturnValue::Scalar(_))) => Err(CustError::new(format!(
                "struct function '{function_name}' requires a struct return value"
            ))),
            (ReturnType::Struct(_), Some(ReturnValue::Pointer { .. })) => Err(CustError::new(
                format!("struct function '{function_name}' requires a struct return value"),
            )),
            (ReturnType::Struct(_), None) => Err(CustError::new(format!(
                "struct function '{function_name}' returned without a value"
            ))),
            (ReturnType::Void, Some(_)) => Err(CustError::new(format!(
                "void function '{function_name}' returned a value"
            ))),
            (ReturnType::Void, None) => Ok(None),
        }
    }

    fn eval_struct_argument(
        &mut self,
        function_name: &str,
        param_name: &str,
        expected_type: &str,
        arg_expr: &Expr,
    ) -> CustResult<Value> {
        let struct_value = match arg_expr {
            Expr::Var(arg_name) => match self.find_variable(arg_name).cloned() {
                Some(Value::Struct { type_name, fields }) => Some((type_name, fields)),
                Some(_) => None,
                None => return Err(CustError::new(format!("undefined variable '{arg_name}'"))),
            },
            Expr::StructGet { name, fields: path } => match self.find_variable(name).cloned() {
                Some(Value::Struct { type_name, fields }) => {
                    let (_, field_value) = Self::nested_field_value(&type_name, &fields, path)?;
                    match field_value {
                        StructFieldValue::Struct {
                            type_name, fields, ..
                        } => Some((
                            type_name.clone(),
                            StructFieldValue::deep_clone_fields(fields),
                        )),
                        StructFieldValue::Scalar { .. }
                        | StructFieldValue::Array { .. }
                        | StructFieldValue::Pointer { .. }
                        | StructFieldValue::StructArray { .. } => None,
                    }
                }
                Some(_) => None,
                None => return Err(CustError::new(format!("undefined variable '{name}'"))),
            },
            Expr::ArrayGet { name, index } => {
                if let Some((type_name, fields)) = self.indexed_struct_pointer_value(name, index)? {
                    Some((type_name, fields))
                } else {
                    let index = self.checked_struct_element_index(name, index)?;
                    match self.find_variable(name).cloned() {
                        Some(Value::StructArray {
                            type_name,
                            elements,
                            ..
                        }) => Some((
                            type_name,
                            StructFieldValue::deep_clone_fields(&elements[index]),
                        )),
                        Some(_) => None,
                        None => return Err(CustError::new(format!("undefined variable '{name}'"))),
                    }
                }
            }
            Expr::Deref(_)
            | Expr::DerefSet { .. }
            | Expr::Assign { .. }
            | Expr::StructSet { .. }
            | Expr::StructPtrSet { .. }
            | Expr::ArraySet { .. }
            | Expr::StructArraySet { .. }
            | Expr::StructElementArrayGet { .. }
            | Expr::StructElementArraySet { .. }
            | Expr::Call { .. }
            | Expr::Conditional { .. }
            | Expr::Comma(_, _)
            | Expr::AggregateLiteral { .. }
            | Expr::AggregateFieldGet { .. } => match self.eval_struct_expr(arg_expr)? {
                ReturnValue::Struct { type_name, fields } => Some((type_name, fields)),
                ReturnValue::Scalar(_) | ReturnValue::Pointer { .. } => None,
            },
            _ => None,
        };

        match struct_value {
            Some((type_name, fields)) if type_name == expected_type => {
                Ok(Value::Struct { type_name, fields })
            }
            Some((type_name, _)) => Err(CustError::new(format!(
                "function '{function_name}' struct parameter '{param_name}' expected struct '{}', got struct '{}'",
                self.aggregate_label(expected_type),
                self.aggregate_label(&type_name)
            ))),
            None => Err(CustError::new(format!(
                "function '{function_name}' struct parameter '{param_name}' requires a struct argument"
            ))),
        }
    }

    fn exec_block(&mut self, statements: &[Stmt]) -> CustResult<ExecFlow> {
        self.push_scope();
        for stmt in statements {
            match self.exec_stmt(stmt) {
                Ok(ExecFlow::None) => {}
                Ok(flow) => {
                    self.pop_scope();
                    return Ok(flow);
                }
                Err(error) => {
                    self.pop_scope();
                    return Err(error);
                }
            }
        }
        self.pop_scope();
        Ok(ExecFlow::None)
    }

    fn exec_control_body(&mut self, statements: &[Stmt]) -> CustResult<ExecFlow> {
        if statements.len() == 1 {
            self.exec_stmt(&statements[0])
        } else {
            self.exec_block(statements)
        }
    }

    fn push_scope(&mut self) {
        self.push_scope_with_values(HashMap::new());
    }

    fn push_scope_with_values(&mut self, values: HashMap<String, Value>) {
        self.push_scope_with_values_and_consts(values, HashSet::new());
    }

    fn push_scope_with_values_and_consts(
        &mut self,
        values: HashMap<String, Value>,
        const_variables: HashSet<String>,
    ) {
        let id = self.next_scope_id;
        self.next_scope_id += 1;
        self.live_scope_ids.insert(id);
        self.scopes.push(Scope {
            id,
            values,
            static_local_ids: HashMap::new(),
            enum_constants: HashMap::new(),
            const_variables,
            array2d_pointer_types: HashMap::new(),
        });
    }

    fn mark_current_variable_const(&mut self, name: &str) {
        self.scopes
            .last_mut()
            .expect("exec_block always creates a current scope")
            .const_variables
            .insert(name.to_string());
    }

    fn is_const_variable(&self, name: &str) -> bool {
        self.scopes
            .iter()
            .rev()
            .find_map(|scope| {
                if scope.values.contains_key(name) {
                    Some(scope.const_variables.contains(name))
                } else {
                    scope.static_local_ids.get(name).map(|id| {
                        self.static_locals
                            .get(id)
                            .is_some_and(|storage| storage.is_const)
                    })
                }
            })
            .unwrap_or(false)
    }

    fn ensure_variable_mutable(&self, name: &str) -> CustResult<()> {
        if self.is_const_variable(name) {
            Err(CustError::new(format!(
                "cannot assign to const variable '{name}'"
            )))
        } else {
            Ok(())
        }
    }

    fn pointer_variable_points_to_const(&self, name: &str) -> bool {
        match self.find_variable(name) {
            Some(Value::Pointer {
                points_to_const, ..
            }) => *points_to_const,
            Some(Value::Array(array)) => array.borrow().read_only,
            Some(Value::StructArray { read_only, .. }) => *read_only,
            _ => false,
        }
    }

    fn ensure_pointer_variable_pointee_mutable(&self, name: &str) -> CustResult<()> {
        if self.pointer_variable_points_to_const(name) {
            Err(CustError::new("cannot assign through pointer to const"))
        } else {
            Ok(())
        }
    }

    fn aggregate_literal_field_metadata(
        &self,
        aggregate: &Expr,
        path: &[String],
    ) -> CustResult<Option<(StructFieldType, bool, bool)>> {
        let Expr::AggregateLiteral {
            type_name,
            read_only,
            ..
        } = aggregate
        else {
            return Ok(None);
        };
        let mut current_type_name = type_name;
        for (index, field_name) in path.iter().enumerate() {
            let Some(struct_type) = self.struct_types.get(current_type_name) else {
                return Err(CustError::new(format!(
                    "undefined struct type '{current_type_name}'"
                )));
            };
            let Some(field) = struct_type
                .fields
                .iter()
                .find(|field| field.name == *field_name)
            else {
                return Ok(None);
            };
            if index + 1 == path.len() {
                return Ok(Some((
                    field.ty.clone(),
                    field.is_const || *read_only,
                    field.points_to_const,
                )));
            }
            match &field.ty {
                StructFieldType::Struct(nested_type) => current_type_name = nested_type,
                _ => return Ok(None),
            }
        }
        Ok(None)
    }

    fn pointer_expr_pointee_type(&self, expr: &Expr) -> CustResult<Option<PointeeType>> {
        match expr {
            Expr::Var(name) | Expr::Assign { name, .. } | Expr::CompoundAssign { name, .. } => {
                match self.find_variable(name) {
                    Some(Value::Pointer { ty, .. }) => Ok(Some(ty.clone())),
                    Some(Value::Array(array)) => {
                        Ok(Some(PointeeType::Scalar(array.borrow().elem_type)))
                    }
                    Some(Value::StructArray { type_name, .. }) => {
                        Ok(Some(PointeeType::Struct(type_name.clone())))
                    }
                    _ => Ok(None),
                }
            }
            Expr::AddressOf(name) => match self.find_variable(name) {
                Some(Value::Scalar { ty, .. }) => Ok(Some(PointeeType::Scalar(*ty))),
                Some(Value::Struct { type_name, .. }) => {
                    Ok(Some(PointeeType::Struct(type_name.clone())))
                }
                _ => Ok(None),
            },
            Expr::AddressOfScalarLiteral { ty, .. } => Ok(Some(PointeeType::Scalar(*ty))),
            Expr::AddressOfAggregateLiteral { type_name, .. } => {
                Ok(Some(PointeeType::Struct(type_name.clone())))
            }
            Expr::AddressOfAggregateField { aggregate, fields } => {
                match self.aggregate_literal_field_metadata(aggregate, fields)? {
                    Some((StructFieldType::Scalar(ty), _, _)) => Ok(Some(PointeeType::Scalar(ty))),
                    Some((StructFieldType::Array(elem_type, _), _, _)) => {
                        Ok(Some(PointeeType::Scalar(elem_type)))
                    }
                    Some((StructFieldType::Array2D(_, _, _), _, _)) => Ok(None),
                    Some((StructFieldType::Struct(type_name), _, _)) => {
                        Ok(Some(PointeeType::Struct(type_name)))
                    }
                    Some((StructFieldType::StructArray(type_name, _), _, _)) => {
                        Ok(Some(PointeeType::Struct(type_name)))
                    }
                    Some((StructFieldType::Pointer(ty), _, _)) => Ok(Some(ty)),
                    None => Ok(None),
                }
            }
            Expr::AggregateFieldGet { aggregate, fields }
            | Expr::AggregateFieldSet {
                aggregate, fields, ..
            }
            | Expr::AggregateFieldCompoundSet {
                aggregate, fields, ..
            } => match self.aggregate_literal_field_metadata(aggregate, fields)? {
                Some((StructFieldType::Pointer(ty), _, _)) => Ok(Some(ty)),
                Some((StructFieldType::Array(elem_type, _), _, _)) => {
                    Ok(Some(PointeeType::Scalar(elem_type)))
                }
                Some((StructFieldType::StructArray(type_name, _), _, _)) => {
                    Ok(Some(PointeeType::Struct(type_name)))
                }
                _ => Ok(None),
            },
            Expr::AddressOfArray { name, .. } => match self.find_variable(name) {
                Some(Value::Array(array)) => {
                    Ok(Some(PointeeType::Scalar(array.borrow().elem_type)))
                }
                Some(Value::Pointer { ty, .. }) => Ok(Some(ty.clone())),
                Some(Value::Scalar { .. }) => {
                    let Expr::AddressOfArray { index, .. } = expr else {
                        unreachable!()
                    };
                    self.pointer_expr_pointee_type(index)
                }
                _ => Ok(None),
            },
            Expr::AddressOfStructField { name, fields }
            | Expr::AddressOfStructArrayField { name, fields, .. }
            | Expr::StructGet { name, fields }
            | Expr::StructSet { name, fields, .. }
            | Expr::StructCompoundSet { name, fields, .. } => match self.find_variable(name) {
                Some(Value::Struct {
                    type_name,
                    fields: field_map,
                }) => match Self::nested_field_value(type_name, field_map, fields)? {
                    (_, StructFieldValue::Scalar { ty, .. }) => Ok(Some(PointeeType::Scalar(*ty))),
                    (_, StructFieldValue::Array { value, .. }) => {
                        Ok(Some(PointeeType::Scalar(value.borrow().elem_type)))
                    }
                    (_, StructFieldValue::Struct { type_name, .. }) => {
                        Ok(Some(PointeeType::Struct(type_name.clone())))
                    }
                    (_, StructFieldValue::Pointer { ty, .. }) => Ok(Some(ty.clone())),
                    (_, StructFieldValue::StructArray { type_name, .. }) => {
                        Ok(Some(PointeeType::Struct(type_name.clone())))
                    }
                },
                _ => Ok(None),
            },
            Expr::AddressOfStructElementField { name, fields, .. }
            | Expr::AddressOfStructElementArrayField { name, fields, .. }
            | Expr::StructElementGet { name, fields, .. }
            | Expr::StructElementArrayGet { name, fields, .. }
            | Expr::StructElementSet { name, fields, .. }
            | Expr::StructElementCompoundSet { name, fields, .. } => {
                match self.struct_element_field_metadata(name, fields)? {
                    Some((StructFieldType::Scalar(ty), _, _)) => Ok(Some(PointeeType::Scalar(ty))),
                    Some((StructFieldType::Array(elem_type, _), _, _)) => {
                        Ok(Some(PointeeType::Scalar(elem_type)))
                    }
                    Some((StructFieldType::Array2D(_, _, _), _, _)) => Ok(None),
                    Some((StructFieldType::Struct(type_name), _, _)) => {
                        Ok(Some(PointeeType::Struct(type_name)))
                    }
                    Some((StructFieldType::Pointer(ty), _, _)) => Ok(Some(ty)),
                    Some((StructFieldType::StructArray(type_name, _), _, _)) => {
                        Ok(Some(PointeeType::Struct(type_name)))
                    }
                    None => Ok(None),
                }
            }
            Expr::StructPtrGet { pointer, fields }
            | Expr::StructPtrSet {
                pointer, fields, ..
            }
            | Expr::StructPtrCompoundSet {
                pointer, fields, ..
            }
            | Expr::AddressOfStructPtrField { pointer, fields }
            | Expr::AddressOfStructPtrArrayField {
                pointer, fields, ..
            }
            | Expr::StructPtrArrayGet {
                pointer, fields, ..
            } => {
                let Some(PointeeType::Struct(mut current_type_name)) =
                    self.pointer_expr_pointee_type(pointer)?
                else {
                    return Ok(None);
                };
                for (index, field_name) in fields.iter().enumerate() {
                    let Some(struct_type) = self.struct_types.get(&current_type_name) else {
                        return Ok(None);
                    };
                    let Some(field) = struct_type
                        .fields
                        .iter()
                        .find(|field| field.name == *field_name)
                    else {
                        return Ok(None);
                    };
                    let is_last = index + 1 == fields.len();
                    match &field.ty {
                        StructFieldType::Scalar(ty) if is_last => {
                            return Ok(Some(PointeeType::Scalar(*ty)));
                        }
                        StructFieldType::Array(elem_type, _) if is_last => {
                            return Ok(Some(PointeeType::Scalar(*elem_type)));
                        }
                        StructFieldType::Struct(nested_type) if is_last => {
                            return Ok(Some(PointeeType::Struct(nested_type.clone())));
                        }
                        StructFieldType::Struct(nested_type) => {
                            current_type_name = nested_type.clone();
                        }
                        StructFieldType::StructArray(type_name, _) if is_last => {
                            return Ok(Some(PointeeType::Struct(type_name.clone())));
                        }
                        StructFieldType::Pointer(ty) if is_last => return Ok(Some(ty.clone())),
                        _ => return Ok(None),
                    }
                }
                Ok(None)
            }
            Expr::StructFieldArrayElementGet {
                name,
                array_fields,
                index,
                fields,
            }
            | Expr::StructFieldArrayElementSet {
                name,
                array_fields,
                index,
                fields,
                ..
            }
            | Expr::StructFieldArrayElementCompoundSet {
                name,
                array_fields,
                index,
                fields,
                ..
            } => match self.struct_field_array_element_field_metadata(
                name,
                array_fields,
                index,
                fields,
            )? {
                Some((StructFieldType::Pointer(ty), _, _)) => Ok(Some(ty)),
                Some((StructFieldType::Array2D(elem_type, _, _), _, _)) => {
                    Ok(Some(PointeeType::Scalar(elem_type)))
                }
                _ => Ok(None),
            },
            Expr::StringLiteral(_) => Ok(Some(PointeeType::Scalar(CType::Char))),
            Expr::ArrayLiteral { elem_type, .. } => Ok(Some(PointeeType::Scalar(*elem_type))),
            Expr::AggregateArrayLiteral { type_name, .. } => {
                Ok(Some(PointeeType::Struct(type_name.clone())))
            }
            Expr::PointerCast { pointee, .. } => Ok(Some(pointee.clone())),
            Expr::Deref(pointer) => Ok(self
                .array2d_row_pointer_element_type(pointer)
                .map(PointeeType::Scalar)),
            Expr::Call { name, args } if self.has_character_search_prototype(name) => {
                self.sizeof_character_search_call(name, args)?;
                Ok(Some(PointeeType::Scalar(CType::Char)))
            }
            Expr::Call { name, args } if self.has_character_set_search_prototype(name) => {
                self.sizeof_character_set_search_call(name, args)?;
                Ok(Some(PointeeType::Scalar(CType::Char)))
            }
            Expr::Call { name, args }
                if self.has_string_copy_prototype(name) && !self.functions.contains_key(name) =>
            {
                self.sizeof_string_copy_call(name, args)?;
                Ok(Some(PointeeType::Scalar(CType::Char)))
            }
            Expr::Call { name, .. }
                if matches!(name.as_str(), "strpbrk" | "strstr")
                    && !self.functions.contains_key(name) =>
            {
                if self.prototypes.contains_key(name) {
                    Err(CustError::new(format!(
                        "standard library function '{name}' has an unsupported declaration; expected two pointer-to-const-character parameters and a pointer-to-character return type"
                    )))
                } else {
                    Err(CustError::new(format!("undefined function '{name}'")))
                }
            }
            Expr::Call { name, .. } if name == "strcpy" && !self.functions.contains_key(name) => {
                if self.prototypes.contains_key(name) {
                    Err(CustError::new(
                        "standard library function 'strcpy' has an unsupported declaration; expected one pointer-to-character destination parameter, one pointer-to-const-character source parameter, and a pointer-to-character return type",
                    ))
                } else {
                    Err(CustError::new("undefined function 'strcpy'"))
                }
            }
            Expr::Call { name, .. } => match self
                .functions
                .get(name)
                .map(|function| &function.return_type)
            {
                Some(ReturnType::Pointer { ty, .. }) => Ok(Some(ty.clone())),
                Some(ReturnType::Array2DPointer { elem_type, .. }) => {
                    Ok(Some(PointeeType::Scalar(*elem_type)))
                }
                _ => Ok(None),
            },
            Expr::Conditional {
                then_expr,
                else_expr,
                ..
            } => {
                let then_type = self.pointer_expr_pointee_type(then_expr)?;
                let else_type = self.pointer_expr_pointee_type(else_expr)?;
                Ok(then_type.or(else_type))
            }
            Expr::Comma(_, right) => self.pointer_expr_pointee_type(right),
            Expr::Binary(left, BinaryOp::Add, right) => {
                let left_type = self.pointer_expr_pointee_type(left)?;
                if left_type.is_some() {
                    Ok(left_type)
                } else {
                    self.pointer_expr_pointee_type(right)
                }
            }
            Expr::Binary(left, BinaryOp::Sub, right) => {
                let left_type = self.pointer_expr_pointee_type(left)?;
                let right_type = self.pointer_expr_pointee_type(right)?;
                if left_type.is_some() && right_type.is_none() {
                    Ok(left_type)
                } else {
                    Ok(None)
                }
            }
            Expr::Increment { target, .. } => self.pointer_expr_pointee_type(target),
            _ => Ok(None),
        }
    }

    fn array2d_row_pointer_element_type(&self, expr: &Expr) -> Option<CType> {
        match expr {
            Expr::Var(name) => {
                if self.enum_constant_shadows_variable(name) {
                    None
                } else {
                    self.array2d_pointer_variable_type(name)
                        .map(|(elem_type, _)| elem_type)
                        .or_else(|| match self.find_variable(name) {
                            Some(Value::Array(array)) if array.borrow().dimensions.is_some() => {
                                Some(array.borrow().elem_type)
                            }
                            Some(Value::Pointer {
                                pointer: PointerValue::Array2DRow { array, .. },
                                ..
                            }) => Some(array.borrow().elem_type),
                            _ => None,
                        })
                }
            }
            Expr::AddressOfArray { name, .. } => self
                .array2d_pointer_variable_type(name)
                .map(|(elem_type, _)| elem_type)
                .or_else(|| match self.find_variable(name) {
                    Some(Value::Array(array)) if array.borrow().dimensions.is_some() => {
                        Some(array.borrow().elem_type)
                    }
                    _ => None,
                }),
            Expr::StructGet { name, fields }
            | Expr::AddressOfStructField { name, fields }
            | Expr::AddressOfStructArrayField { name, fields, .. } => {
                match self.find_variable(name) {
                    Some(Value::Struct {
                        type_name,
                        fields: field_map,
                    }) => Self::nested_field_value(type_name, field_map, fields)
                        .ok()
                        .and_then(|(_, field)| match field {
                            StructFieldValue::Array { value, .. }
                                if value.borrow().dimensions.is_some() =>
                            {
                                Some(value.borrow().elem_type)
                            }
                            _ => None,
                        }),
                    _ => None,
                }
            }
            Expr::StructElementGet { name, fields, .. }
            | Expr::AddressOfStructElementField { name, fields, .. }
            | Expr::AddressOfStructElementArrayField { name, fields, .. } => self
                .struct_element_field_metadata(name, fields)
                .ok()
                .flatten()
                .and_then(|(field_type, _, _)| match field_type {
                    StructFieldType::Array2D(elem_type, _, _) => Some(elem_type),
                    _ => None,
                }),
            Expr::StructPtrGet { pointer, fields }
            | Expr::AddressOfStructPtrField { pointer, fields }
            | Expr::AddressOfStructPtrArrayField {
                pointer, fields, ..
            } => self
                .struct_pointer_expr_field_metadata(pointer, fields)
                .ok()
                .flatten()
                .and_then(|(field_type, _, _)| match field_type {
                    StructFieldType::Array2D(elem_type, _, _) => Some(elem_type),
                    _ => None,
                }),
            Expr::AggregateFieldGet { aggregate, fields }
            | Expr::AddressOfAggregateField { aggregate, fields } => self
                .aggregate_literal_field_metadata(aggregate, fields)
                .ok()
                .flatten()
                .and_then(|(field_type, _, _)| match field_type {
                    StructFieldType::Array2D(elem_type, _, _) => Some(elem_type),
                    _ => None,
                }),
            Expr::StructFieldArrayElementGet {
                name,
                array_fields,
                index,
                fields,
            } => self
                .struct_field_array_element_field_metadata(name, array_fields, index, fields)
                .ok()
                .flatten()
                .and_then(|(field_type, _, _)| match field_type {
                    StructFieldType::Array2D(elem_type, _, _) => Some(elem_type),
                    _ => None,
                }),
            Expr::Assign { name, value } => self
                .array2d_pointer_variable_type(name)
                .map(|(elem_type, _)| elem_type)
                .or_else(|| self.array2d_row_pointer_element_type(value)),
            Expr::CompoundAssign { name, .. } => self
                .array2d_pointer_variable_type(name)
                .map(|(elem_type, _)| elem_type),
            Expr::StructSet { value, .. }
            | Expr::StructPtrSet { value, .. }
            | Expr::StructElementSet { value, .. }
            | Expr::StructFieldArrayElementSet { value, .. }
            | Expr::AggregateFieldSet { value, .. }
            | Expr::PointerCast { expr: value, .. } => self.array2d_row_pointer_element_type(value),
            Expr::Increment { target, .. } => self.array2d_row_pointer_element_type(target),
            Expr::Call { name, .. } => self.functions.get(name).and_then(|function| {
                if let ReturnType::Array2DPointer { elem_type, .. } = function.return_type {
                    Some(elem_type)
                } else {
                    None
                }
            }),
            Expr::Conditional {
                then_expr,
                else_expr,
                ..
            } => self
                .array2d_row_pointer_element_type(then_expr)
                .or_else(|| self.array2d_row_pointer_element_type(else_expr)),
            Expr::Comma(_, right) => self.array2d_row_pointer_element_type(right),
            Expr::Binary(left, BinaryOp::Add, right) => self
                .array2d_row_pointer_element_type(left)
                .or_else(|| self.array2d_row_pointer_element_type(right)),
            Expr::Binary(left, BinaryOp::Sub, right)
                if self.array2d_row_pointer_element_type(right).is_none() =>
            {
                self.array2d_row_pointer_element_type(left)
            }
            _ => None,
        }
    }

    fn struct_pointer_expr_field_metadata(
        &self,
        pointer: &Expr,
        path: &[String],
    ) -> CustResult<Option<(StructFieldType, bool, bool)>> {
        let Some(PointeeType::Struct(mut current_type_name)) =
            self.pointer_expr_pointee_type(pointer)?
        else {
            return Ok(None);
        };
        for (index, field_name) in path.iter().enumerate() {
            let Some(struct_type) = self.struct_types.get(&current_type_name) else {
                return Ok(None);
            };
            let Some(field) = struct_type
                .fields
                .iter()
                .find(|field| field.name == *field_name)
            else {
                return Ok(None);
            };
            if index + 1 == path.len() {
                return Ok(Some((
                    field.ty.clone(),
                    field.is_const,
                    field.points_to_const,
                )));
            }
            match &field.ty {
                StructFieldType::Struct(nested_type) => {
                    current_type_name = nested_type.clone();
                }
                _ => return Ok(None),
            }
        }
        Ok(None)
    }

    fn aggregate_type_field_metadata(
        &self,
        type_name: &str,
        path: &[String],
    ) -> CustResult<Option<(StructFieldType, bool, bool)>> {
        let mut current_type_name = type_name.to_string();
        for (index, field_name) in path.iter().enumerate() {
            let Some(struct_type) = self.struct_types.get(&current_type_name) else {
                return Ok(None);
            };
            let Some(field) = struct_type
                .fields
                .iter()
                .find(|field| field.name == *field_name)
            else {
                return Ok(None);
            };
            if index + 1 == path.len() {
                return Ok(Some((
                    field.ty.clone(),
                    field.is_const,
                    field.points_to_const,
                )));
            }
            match &field.ty {
                StructFieldType::Struct(nested_type) => {
                    current_type_name = nested_type.clone();
                }
                _ => return Ok(None),
            }
        }
        Ok(None)
    }

    fn struct_field_array_element_field_metadata(
        &self,
        name: &str,
        array_fields: &[String],
        pointer_expr: &Expr,
        fields: &[String],
    ) -> CustResult<Option<(StructFieldType, bool, bool)>> {
        if let Some(PointeeType::Struct(type_name)) =
            self.scalar_field_reverse_subscript_pointee_type(name, array_fields, pointer_expr)?
        {
            return self.aggregate_type_field_metadata(&type_name, fields);
        }

        let Some(Value::Struct {
            type_name,
            fields: field_map,
        }) = self.find_variable(name)
        else {
            return Ok(None);
        };
        let (_, array_value) = Self::nested_field_value(type_name, field_map, array_fields)?;
        let StructFieldValue::StructArray {
            type_name: element_type,
            ..
        } = array_value
        else {
            return Ok(None);
        };
        self.aggregate_type_field_metadata(element_type, fields)
    }

    fn pointer_expr_points_to_const(&self, expr: &Expr) -> bool {
        match expr {
            Expr::Var(name) => self.pointer_variable_points_to_const(name),
            Expr::AddressOf(name) => self.is_const_variable(name),
            Expr::AddressOfStructField { name, fields } => self
                .find_variable_scope_id(name)
                .and_then(|scope_id| {
                    self.struct_field_points_to_const(scope_id, name, None, fields)
                        .ok()
                })
                .unwrap_or(false),
            Expr::AddressOfStructArrayField { name, fields, .. } => {
                if self.struct_field_is_pointer(name, fields) {
                    self.struct_pointer_field_points_to_const(name, fields)
                } else {
                    self.direct_struct_array_field_points_to_const(name, fields)
                }
            }
            Expr::AddressOfStructElementField { name, fields, .. } => self
                .find_variable_scope_id(name)
                .and_then(|scope_id| {
                    self.struct_field_points_to_const(scope_id, name, Some(0), fields)
                        .ok()
                })
                .unwrap_or(false),
            Expr::AddressOfStructElementArrayField { name, fields, .. } => self
                .struct_element_field_metadata(name, fields)
                .ok()
                .flatten()
                .map(|(field_type, is_const, points_to_const)| match field_type {
                    StructFieldType::Pointer(_) => points_to_const,
                    StructFieldType::Array(_, _)
                    | StructFieldType::Array2D(_, _, _)
                    | StructFieldType::StructArray(_, _) => {
                        self.struct_array_element_field_points_to_const(name, fields) || is_const
                    }
                    StructFieldType::Scalar(_) | StructFieldType::Struct(_) => false,
                })
                .unwrap_or(false),
            Expr::StructGet { name, fields } => {
                self.direct_struct_array_field_points_to_const(name, fields)
                    || self.struct_pointer_field_points_to_const(name, fields)
            }
            Expr::AggregateFieldGet { aggregate, fields } => self
                .aggregate_literal_field_metadata(aggregate, fields)
                .ok()
                .flatten()
                .map(|(field_type, is_const, points_to_const)| match field_type {
                    StructFieldType::Array(_, _)
                    | StructFieldType::Array2D(_, _, _)
                    | StructFieldType::StructArray(_, _) => is_const,
                    StructFieldType::Pointer(_) => points_to_const,
                    StructFieldType::Scalar(_) | StructFieldType::Struct(_) => false,
                })
                .unwrap_or(false),
            Expr::AggregateFieldSet {
                aggregate,
                fields,
                value,
            } => self
                .aggregate_literal_field_metadata(aggregate, fields)
                .ok()
                .flatten()
                .is_some_and(|(field_type, _, points_to_const)| {
                    matches!(field_type, StructFieldType::Pointer(_))
                        && (points_to_const || self.pointer_expr_points_to_const(value))
                }),
            Expr::AggregateFieldCompoundSet {
                aggregate, fields, ..
            } => self
                .aggregate_literal_field_metadata(aggregate, fields)
                .ok()
                .flatten()
                .is_some_and(|(field_type, _, points_to_const)| {
                    matches!(field_type, StructFieldType::Pointer(_)) && points_to_const
                }),
            Expr::AddressOfAggregateField { aggregate, fields } => self
                .aggregate_literal_field_metadata(aggregate, fields)
                .ok()
                .flatten()
                .map(|(field_type, is_const, points_to_const)| match field_type {
                    StructFieldType::Array(_, _)
                    | StructFieldType::Array2D(_, _, _)
                    | StructFieldType::StructArray(_, _) => is_const,
                    StructFieldType::Pointer(_) => points_to_const,
                    StructFieldType::Scalar(_) | StructFieldType::Struct(_) => is_const,
                })
                .unwrap_or(false),
            Expr::AddressOfAggregateLiteral { read_only, .. } => *read_only,
            Expr::StructElementGet { name, fields, .. } => self
                .struct_element_field_metadata(name, fields)
                .ok()
                .flatten()
                .map(|(field_type, is_const, points_to_const)| match field_type {
                    StructFieldType::Pointer(_) => points_to_const,
                    StructFieldType::Array(_, _)
                    | StructFieldType::Array2D(_, _, _)
                    | StructFieldType::StructArray(_, _) => {
                        self.struct_array_element_field_points_to_const(name, fields) || is_const
                    }
                    StructFieldType::Scalar(_) | StructFieldType::Struct(_) => false,
                })
                .unwrap_or(false),
            Expr::StructElementArrayGet { name, fields, .. } => self
                .struct_element_field_metadata(name, fields)
                .ok()
                .flatten()
                .map(|(field_type, is_const, points_to_const)| match field_type {
                    StructFieldType::Pointer(_) => points_to_const,
                    StructFieldType::Array(_, _)
                    | StructFieldType::Array2D(_, _, _)
                    | StructFieldType::StructArray(_, _) => {
                        self.struct_array_element_field_points_to_const(name, fields) || is_const
                    }
                    StructFieldType::Scalar(_) | StructFieldType::Struct(_) => false,
                })
                .unwrap_or(false),
            Expr::StructElementSet {
                name,
                fields,
                value,
                ..
            } => self
                .struct_element_field_metadata(name, fields)
                .ok()
                .flatten()
                .is_some_and(|(field_type, _, points_to_const)| {
                    matches!(field_type, StructFieldType::Pointer(_))
                        && (points_to_const || self.pointer_expr_points_to_const(value))
                }),
            Expr::StructElementCompoundSet { name, fields, .. } => self
                .struct_element_field_metadata(name, fields)
                .ok()
                .flatten()
                .is_some_and(|(field_type, _, points_to_const)| {
                    matches!(field_type, StructFieldType::Pointer(_)) && points_to_const
                }),
            Expr::StructPtrGet { pointer, fields } => {
                match self.struct_pointer_expr_field_metadata(pointer, fields) {
                    Ok(Some((StructFieldType::Pointer(_), _, points_to_const))) => points_to_const,
                    Ok(Some((
                        StructFieldType::Array(_, _)
                        | StructFieldType::Array2D(_, _, _)
                        | StructFieldType::StructArray(_, _),
                        is_const,
                        _,
                    ))) => self.pointer_expr_points_to_const(pointer) || is_const,
                    _ => false,
                }
            }
            Expr::AddressOfStructPtrField { pointer, fields } => {
                self.pointer_expr_points_to_const(pointer)
                    || self
                        .struct_pointer_expr_field_metadata(pointer, fields)
                        .ok()
                        .flatten()
                        .is_some_and(|(_, is_const, _)| is_const)
            }
            Expr::StructPtrArrayGet {
                pointer, fields, ..
            } => {
                self.pointer_expr_points_to_const(pointer)
                    || self
                        .const_aggregate_field_label_for_struct_pointer_expr(pointer, fields)
                        .is_some()
            }
            Expr::AddressOfStructPtrArrayField {
                pointer, fields, ..
            } => match self.struct_pointer_expr_field_metadata(pointer, fields) {
                Ok(Some((StructFieldType::Pointer(_), _, points_to_const))) => points_to_const,
                Ok(Some((
                    StructFieldType::Array(_, _)
                    | StructFieldType::Array2D(_, _, _)
                    | StructFieldType::StructArray(_, _),
                    is_const,
                    _,
                ))) => self.pointer_expr_points_to_const(pointer) || is_const,
                _ => false,
            },
            Expr::AddressOfArray { name, index } => match self.find_variable(name) {
                Some(Value::Array(array)) => array.borrow().read_only,
                Some(Value::Pointer {
                    points_to_const, ..
                }) => *points_to_const,
                Some(Value::Scalar { .. }) => self.pointer_expr_points_to_const(index),
                _ => false,
            },
            Expr::ArrayLiteral { read_only, .. }
            | Expr::AggregateArrayLiteral { read_only, .. } => *read_only,
            Expr::Comma(_, right) => self.pointer_expr_points_to_const(right),
            Expr::PointerCast {
                points_to_const,
                expr,
                ..
            } => *points_to_const || self.pointer_expr_points_to_const(expr),
            Expr::Deref(pointer) if self.array2d_row_pointer_element_type(pointer).is_some() => {
                self.pointer_expr_points_to_const(pointer)
            }
            Expr::Conditional {
                then_expr,
                else_expr,
                ..
            } => {
                self.pointer_expr_points_to_const(then_expr)
                    || self.pointer_expr_points_to_const(else_expr)
            }
            Expr::Binary(left, BinaryOp::Add, right) => {
                if self.expr_is_pointer_value(left) {
                    self.pointer_expr_points_to_const(left)
                } else {
                    self.pointer_expr_points_to_const(right)
                }
            }
            Expr::Binary(left, BinaryOp::Sub, right) => {
                self.expr_is_pointer_value(left)
                    && !self.expr_is_pointer_value(right)
                    && self.pointer_expr_points_to_const(left)
            }
            Expr::Assign { name, value } => {
                self.pointer_variable_points_to_const(name)
                    || self.pointer_expr_points_to_const(value)
            }
            Expr::Call { name, .. } => self
                .functions
                .get(name)
                .and_then(|function| match function.return_type {
                    ReturnType::Pointer {
                        points_to_const, ..
                    }
                    | ReturnType::Array2DPointer {
                        points_to_const, ..
                    } => Some(points_to_const),
                    _ => None,
                })
                .unwrap_or(false),
            Expr::StructSet {
                name,
                fields,
                value,
            } => {
                self.struct_pointer_field_points_to_const(name, fields)
                    || self.pointer_expr_points_to_const(value)
            }
            Expr::StructCompoundSet { name, fields, .. } => {
                self.struct_pointer_field_points_to_const(name, fields)
            }
            Expr::StructPtrSet {
                pointer,
                fields,
                value,
            } => self
                .struct_pointer_expr_field_metadata(pointer, fields)
                .ok()
                .flatten()
                .is_some_and(|(field_type, _, points_to_const)| {
                    matches!(field_type, StructFieldType::Pointer(_))
                        && (points_to_const || self.pointer_expr_points_to_const(value))
                }),
            Expr::StructPtrCompoundSet {
                pointer, fields, ..
            } => self
                .struct_pointer_expr_field_metadata(pointer, fields)
                .ok()
                .flatten()
                .is_some_and(|(field_type, _, points_to_const)| {
                    matches!(field_type, StructFieldType::Pointer(_)) && points_to_const
                }),
            Expr::StructFieldArrayElementGet {
                name,
                array_fields,
                index,
                fields,
            } => self
                .struct_field_array_element_field_metadata(name, array_fields, index, fields)
                .ok()
                .flatten()
                .is_some_and(|(field_type, _, points_to_const)| {
                    matches!(field_type, StructFieldType::Pointer(_)) && points_to_const
                }),
            Expr::StructFieldArrayElementSet {
                name,
                array_fields,
                index,
                fields,
                value,
            } => self
                .struct_field_array_element_field_metadata(name, array_fields, index, fields)
                .ok()
                .flatten()
                .is_some_and(|(field_type, _, points_to_const)| {
                    matches!(field_type, StructFieldType::Pointer(_))
                        && (points_to_const || self.pointer_expr_points_to_const(value))
                }),
            Expr::StructFieldArrayElementCompoundSet {
                name,
                array_fields,
                index,
                fields,
                ..
            } => self
                .struct_field_array_element_field_metadata(name, array_fields, index, fields)
                .ok()
                .flatten()
                .is_some_and(|(field_type, _, points_to_const)| {
                    matches!(field_type, StructFieldType::Pointer(_)) && points_to_const
                }),
            Expr::CompoundAssign { name, .. } => self.pointer_variable_points_to_const(name),
            Expr::Increment { target, .. } => self.pointer_expr_points_to_const(target),
            _ => false,
        }
    }

    fn ensure_pointer_conversion_preserves_const(
        &self,
        target_points_to_const: bool,
        value: &Expr,
    ) -> CustResult<()> {
        if !target_points_to_const && self.pointer_expr_points_to_const(value) {
            return Err(CustError::new(
                "cannot discard const qualifier from pointer target",
            ));
        }
        Ok(())
    }

    fn aggregate_label(&self, type_name: &str) -> String {
        Self::aggregate_label_from(&self.struct_types, type_name)
    }

    fn aggregate_label_from(
        struct_types: &HashMap<String, StructTypeDef>,
        type_name: &str,
    ) -> String {
        struct_types
            .get(type_name)
            .map(|aggregate| aggregate.display_name.clone())
            .unwrap_or_else(|| type_name.to_string())
    }

    fn pointee_label(&self, ty: &PointeeType) -> String {
        match ty {
            PointeeType::Scalar(CType::Int) => "int".to_string(),
            PointeeType::Scalar(CType::Char) => "char".to_string(),
            PointeeType::Scalar(CType::Bool) => "_Bool".to_string(),
            PointeeType::Struct(type_name) => {
                let aggregate = self.struct_types.get(type_name);
                let keyword = aggregate
                    .map(|aggregate| aggregate.kind.keyword())
                    .unwrap_or("struct");
                let display_name = aggregate
                    .map(|aggregate| aggregate.display_name.as_str())
                    .unwrap_or(type_name);
                format!("{keyword} '{display_name}'")
            }
        }
    }

    fn fields_contain_array(
        fields: &HashMap<String, StructFieldValue>,
        target: &Rc<RefCell<ArrayValue>>,
    ) -> bool {
        fields.values().any(|field| match field {
            StructFieldValue::Array { value, .. } => Rc::ptr_eq(value, target),
            StructFieldValue::Struct { fields, .. } => Self::fields_contain_array(fields, target),
            StructFieldValue::StructArray { elements, .. } => elements
                .iter()
                .any(|fields| Self::fields_contain_array(fields, target)),
            StructFieldValue::Scalar { .. } | StructFieldValue::Pointer { .. } => false,
        })
    }

    fn value_contains_array(value: &Value, target: &Rc<RefCell<ArrayValue>>) -> bool {
        match value {
            Value::Array(array) => Rc::ptr_eq(array, target),
            Value::Struct { fields, .. } => Self::fields_contain_array(fields, target),
            Value::StructArray { elements, .. } => elements
                .iter()
                .any(|fields| Self::fields_contain_array(fields, target)),
            Value::Scalar { .. } | Value::Pointer { .. } => false,
        }
    }

    fn find_array_pointer_owner(
        &self,
        array: &Rc<RefCell<ArrayValue>>,
    ) -> Option<ArrayPointerOwner> {
        if self
            .function_name_arrays
            .values()
            .any(|function_name| Rc::ptr_eq(function_name, array))
        {
            return None;
        }
        for scope in self.scopes.iter().rev() {
            if let Some((name, _)) = scope
                .values
                .iter()
                .find(|(_, value)| Self::value_contains_array(value, array))
            {
                return Some(ArrayPointerOwner {
                    scope_id: scope.id,
                    name: name.clone(),
                });
            }
        }
        self.static_locals.values().find_map(|storage| {
            Self::value_contains_array(&storage.value, array).then(|| ArrayPointerOwner {
                scope_id: storage.scope_id,
                name: storage.name.clone(),
            })
        })
    }

    fn attach_array_pointer_owner(&self, pointer: PointerValue) -> PointerValue {
        match pointer {
            PointerValue::ArrayBase {
                array,
                source_name,
                owner: None,
            } => {
                let owner = self.find_array_pointer_owner(&array);
                PointerValue::ArrayBase {
                    array,
                    source_name,
                    owner,
                }
            }
            PointerValue::ArrayElement {
                array,
                source_name,
                index,
                owner: None,
            } => {
                let owner = self.find_array_pointer_owner(&array);
                PointerValue::ArrayElement {
                    array,
                    source_name,
                    index,
                    owner,
                }
            }
            PointerValue::Array2DRow {
                array,
                source_name,
                row,
                owner: None,
            } => {
                let owner = self.find_array_pointer_owner(&array);
                PointerValue::Array2DRow {
                    array,
                    source_name,
                    row,
                    owner,
                }
            }
            pointer => pointer,
        }
    }

    fn ensure_array_pointer_owner_live(&self, owner: Option<&ArrayPointerOwner>) -> CustResult<()> {
        match owner {
            Some(owner) if !self.live_scope_ids.contains(&owner.scope_id) => Err(CustError::new(
                format!("pointer to out-of-scope variable '{}'", owner.name),
            )),
            Some(_) | None => Ok(()),
        }
    }

    fn pointer_value_type(&self, pointer: &PointerValue) -> CustResult<Option<PointeeType>> {
        match pointer {
            PointerValue::Null => Ok(None),
            PointerValue::Scalar { scope_id, name } => {
                let value = self
                    .scopes
                    .iter()
                    .find(|scope| scope.id == *scope_id)
                    .and_then(|scope| scope.values.get(name))
                    .or_else(|| self.static_value_by_scope(*scope_id, name));
                match value {
                    Some(Value::Scalar { ty, .. }) => Ok(Some(PointeeType::Scalar(*ty))),
                    _ => Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    ))),
                }
            }
            PointerValue::ArrayBase { array, owner, .. }
            | PointerValue::ArrayElement { array, owner, .. } => {
                self.ensure_array_pointer_owner_live(owner.as_ref())?;
                Ok(Some(PointeeType::Scalar(array.borrow().elem_type)))
            }
            PointerValue::Array2DRow {
                source_name, owner, ..
            } => {
                self.ensure_array_pointer_owner_live(owner.as_ref())?;
                Err(CustError::new(match source_name {
                    Some(name) => {
                        format!("two-dimensional array '{name}' does not decay to a scalar pointer")
                    }
                    None => "pointer to two-dimensional array row cannot convert to scalar pointer"
                        .to_string(),
                }))
            }
            PointerValue::Struct { scope_id, name } => {
                let value = self
                    .scopes
                    .iter()
                    .find(|scope| scope.id == *scope_id)
                    .and_then(|scope| scope.values.get(name))
                    .or_else(|| self.static_value_by_scope(*scope_id, name));
                match value {
                    Some(Value::Struct { type_name, .. }) => {
                        Ok(Some(PointeeType::Struct(type_name.clone())))
                    }
                    _ => Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    ))),
                }
            }
            PointerValue::StructElement {
                scope_id,
                name,
                index: _,
            } => {
                let value = self
                    .scopes
                    .iter()
                    .find(|scope| scope.id == *scope_id)
                    .and_then(|scope| scope.values.get(name))
                    .or_else(|| self.static_value_by_scope(*scope_id, name));
                match value {
                    Some(Value::StructArray { type_name, .. }) => {
                        Ok(Some(PointeeType::Struct(type_name.clone())))
                    }
                    _ => Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    ))),
                }
            }
            PointerValue::StructFieldElement {
                scope_id,
                name,
                element_index,
                fields,
                ..
            } => match self.struct_field_by_scope(*scope_id, name, *element_index, fields)? {
                StructFieldValue::StructArray { type_name, .. } => {
                    Ok(Some(PointeeType::Struct(type_name.clone())))
                }
                _ => Ok(None),
            },
            PointerValue::NestedStructArrayElement {
                pointer, fields, ..
            } => {
                let (_, field_map) = self.find_struct_pointer_fields(pointer)?;
                match Self::nested_field_value("", field_map, fields)?.1 {
                    StructFieldValue::StructArray { type_name, .. } => {
                        Ok(Some(PointeeType::Struct(type_name.clone())))
                    }
                    _ => Ok(None),
                }
            }
            PointerValue::StructFieldElementField {
                scope_id,
                name,
                element_index,
                array_fields,
                index,
                fields,
            } => {
                let (type_name, element_fields) = self.struct_field_array_element_fields(
                    *scope_id,
                    name,
                    *element_index,
                    array_fields,
                    *index,
                )?;
                match Self::nested_field_value(&type_name, element_fields, fields)?.1 {
                    StructFieldValue::Scalar { ty, .. } => Ok(Some(PointeeType::Scalar(*ty))),
                    StructFieldValue::Array { value, .. } => {
                        Ok(Some(PointeeType::Scalar(value.borrow().elem_type)))
                    }
                    StructFieldValue::Struct { type_name, .. } => {
                        Ok(Some(PointeeType::Struct(type_name.clone())))
                    }
                    StructFieldValue::Pointer { ty, .. } => Ok(Some(ty.clone())),
                    StructFieldValue::StructArray { type_name, .. } => {
                        Ok(Some(PointeeType::Struct(type_name.clone())))
                    }
                }
            }
            PointerValue::StructField {
                scope_id,
                name,
                element_index,
                fields,
            } => match self.struct_field_by_scope(*scope_id, name, *element_index, fields)? {
                StructFieldValue::Scalar { ty, .. } => Ok(Some(PointeeType::Scalar(*ty))),
                StructFieldValue::Array { value, .. } => {
                    Ok(Some(PointeeType::Scalar(value.borrow().elem_type)))
                }
                StructFieldValue::Struct { type_name, .. } => {
                    Ok(Some(PointeeType::Struct(type_name.clone())))
                }
                StructFieldValue::Pointer { ty, .. } => Ok(Some(ty.clone())),
                StructFieldValue::StructArray { type_name, .. } => {
                    Ok(Some(PointeeType::Struct(type_name.clone())))
                }
            },
        }
    }

    fn ensure_pointer_type_matches(
        &self,
        expected: &PointeeType,
        pointer: &PointerValue,
    ) -> CustResult<()> {
        let Some(actual) = self.pointer_value_type(pointer)? else {
            return Ok(());
        };
        if &actual != expected {
            return Err(CustError::new(format!(
                "cannot convert pointer to {} to pointer to {}",
                self.pointee_label(&actual),
                self.pointee_label(expected)
            )));
        }
        Ok(())
    }

    fn ensure_pointer_slot_type_matches(
        &self,
        current: &PointerValue,
        expected: &PointeeType,
        replacement: &PointerValue,
    ) -> CustResult<()> {
        if let PointerValue::Array2DRow { array, .. } = current {
            let array = array.borrow();
            let Some((_, columns)) = array.dimensions else {
                return Err(CustError::new(
                    "internal two-dimensional row pointer storage mismatch",
                ));
            };
            self.ensure_two_dimensional_row_pointer_type_matches(
                array.elem_type,
                columns,
                replacement,
            )
        } else {
            self.ensure_pointer_type_matches(expected, replacement)
        }
    }

    fn ensure_two_dimensional_row_pointer_type_matches(
        &self,
        expected_type: CType,
        expected_columns: usize,
        pointer: &PointerValue,
    ) -> CustResult<()> {
        match pointer {
            PointerValue::Null => Ok(()),
            PointerValue::Array2DRow { array, owner, .. } => {
                self.ensure_array_pointer_owner_live(owner.as_ref())?;
                let array = array.borrow();
                let Some((_, actual_columns)) = array.dimensions else {
                    return Err(CustError::new(
                        "pointer does not reference a two-dimensional array row",
                    ));
                };
                if array.elem_type != expected_type || actual_columns != expected_columns {
                    let expected_label = match expected_type {
                        CType::Int => "int",
                        CType::Char => "char",
                        CType::Bool => "_Bool",
                    };
                    return Err(CustError::new(format!(
                        "row pointer expected a two-dimensional {expected_label} array with {expected_columns} columns"
                    )));
                }
                Ok(())
            }
            _ => Err(CustError::new(
                "pointer does not reference a two-dimensional array row",
            )),
        }
    }

    fn ensure_pointer_expr_pointee_mutable(&self, expr: &Expr) -> CustResult<()> {
        if self.pointer_expr_points_to_const(expr) {
            if let Some(field_label) = self.const_aggregate_field_label_in_pointer_expr(expr) {
                return Err(CustError::new(format!(
                    "cannot assign to const struct field '{field_label}'"
                )));
            }
            Err(CustError::new("cannot assign through pointer to const"))
        } else {
            Ok(())
        }
    }

    fn const_aggregate_field_label_in_pointer_expr(&self, expr: &Expr) -> Option<String> {
        match expr {
            Expr::AggregateFieldGet { aggregate, fields } => {
                let Expr::AggregateLiteral { type_name, .. } = aggregate.as_ref() else {
                    return None;
                };
                self.const_aggregate_field_label_for_path(type_name, fields)
            }
            Expr::StructPtrArrayGet {
                pointer, fields, ..
            }
            | Expr::AddressOfStructPtrArrayField {
                pointer, fields, ..
            } => self.const_aggregate_field_label_for_struct_pointer_expr(pointer, fields),
            Expr::Binary(left, BinaryOp::Add | BinaryOp::Sub, right) => self
                .const_aggregate_field_label_in_pointer_expr(left)
                .or_else(|| self.const_aggregate_field_label_in_pointer_expr(right)),
            _ => None,
        }
    }

    fn const_aggregate_field_label_for_struct_pointer_expr(
        &self,
        pointer: &Expr,
        fields: &[String],
    ) -> Option<String> {
        let Some(PointeeType::Struct(type_name)) = self.pointer_expr_pointee_type(pointer).ok()?
        else {
            return None;
        };
        self.const_aggregate_field_label_for_path(&type_name, fields)
    }

    fn const_aggregate_field_label_for_path(
        &self,
        type_name: &str,
        path: &[String],
    ) -> Option<String> {
        let mut current_type = type_name;
        let mut traversed = Vec::new();
        for field_name in path {
            let struct_type = self.struct_types.get(current_type)?;
            let field = struct_type
                .fields
                .iter()
                .find(|field| field.name == *field_name)?;
            traversed.push(field_name.clone());
            if field.is_const {
                return Some(Self::field_path_label(&traversed).to_string());
            }
            match &field.ty {
                StructFieldType::Struct(nested_type) => current_type = nested_type,
                StructFieldType::Scalar(_)
                | StructFieldType::Array(_, _)
                | StructFieldType::Array2D(_, _, _)
                | StructFieldType::StructArray(_, _)
                | StructFieldType::Pointer(_) => return None,
            }
        }
        None
    }

    fn ensure_struct_pointer_target_mutable(&self, pointer: &PointerValue) -> CustResult<()> {
        match pointer {
            PointerValue::Struct { scope_id, name }
                if self
                    .scopes
                    .iter()
                    .find(|scope| scope.id == *scope_id)
                    .is_some_and(|scope| scope.const_variables.contains(name))
                    || self.static_locals.values().any(|storage| {
                        storage.scope_id == *scope_id && storage.name == *name && storage.is_const
                    }) =>
            {
                Err(CustError::new("cannot assign through pointer to const"))
            }
            _ => Ok(()),
        }
    }

    fn pop_scope(&mut self) {
        if let Some(scope) = self.scopes.pop() {
            self.live_scope_ids.remove(&scope.id);
        }
    }

    fn current_scope_mut(&mut self) -> &mut HashMap<String, Value> {
        &mut self
            .scopes
            .last_mut()
            .expect("exec_block always creates a current scope")
            .values
    }

    fn mark_current_array2d_pointer_type(&mut self, name: &str, elem_type: CType, columns: usize) {
        self.scopes
            .last_mut()
            .expect("exec_block always creates a current scope")
            .array2d_pointer_types
            .insert(name.to_string(), (elem_type, columns));
    }

    fn array2d_pointer_variable_type(&self, name: &str) -> Option<(CType, usize)> {
        for scope in self.scopes.iter().rev() {
            if scope.values.contains_key(name)
                || scope.static_local_ids.contains_key(name)
                || scope.enum_constants.contains_key(name)
            {
                return scope.array2d_pointer_types.get(name).copied();
            }
        }
        None
    }

    fn enum_constant_shadows_variable(&self, name: &str) -> bool {
        for scope in self.scopes.iter().rev() {
            if scope.enum_constants.contains_key(name) {
                return true;
            }
            if scope.values.contains_key(name) || scope.static_local_ids.contains_key(name) {
                return false;
            }
        }
        false
    }

    fn current_scope_has_identifier(&self, name: &str) -> bool {
        let scope = self
            .scopes
            .last()
            .expect("exec_block always creates a current scope");
        scope.values.contains_key(name)
            || scope.static_local_ids.contains_key(name)
            || scope.enum_constants.contains_key(name)
    }

    fn insert_enum_constant(&mut self, name: String, value: i64) -> CustResult<()> {
        if self.current_scope_has_identifier(&name) {
            return Err(CustError::new(format!(
                "variable '{name}' already declared in this scope"
            )));
        }
        self.scopes
            .last_mut()
            .expect("exec_block always creates a current scope")
            .enum_constants
            .insert(name, value);
        Ok(())
    }

    fn find_enum_constant(&self, name: &str) -> Option<i64> {
        self.scopes
            .iter()
            .rev()
            .find_map(|scope| scope.enum_constants.get(name).copied())
    }

    fn find_variable(&self, name: &str) -> Option<&Value> {
        self.scopes.iter().rev().find_map(|scope| {
            scope.values.get(name).or_else(|| {
                scope
                    .static_local_ids
                    .get(name)
                    .and_then(|id| self.static_locals.get(id))
                    .map(|storage| &storage.value)
            })
        })
    }

    fn find_variable_mut(&mut self, name: &str) -> Option<&mut Value> {
        let mut static_id = None;
        for scope in self.scopes.iter().rev() {
            if scope.values.contains_key(name) {
                break;
            }
            if let Some(id) = scope.static_local_ids.get(name) {
                static_id = Some(*id);
                break;
            }
        }
        if let Some(id) = static_id {
            return self
                .static_locals
                .get_mut(&id)
                .map(|storage| &mut storage.value);
        }
        self.scopes
            .iter_mut()
            .rev()
            .find_map(|scope| scope.values.get_mut(name))
    }

    fn find_scalar(&self, name: &str) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::Scalar { value, .. }) => Ok(*value),
            Some(Value::Array(_)) => Err(CustError::new(format!("array '{name}' used as scalar"))),
            Some(Value::Pointer { .. }) => {
                Err(CustError::new(format!("pointer '{name}' used as scalar")))
            }
            Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => Err(CustError::new(
                format!("struct variable '{name}' used as scalar"),
            )),
            None => self
                .find_enum_constant(name)
                .ok_or_else(|| CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn find_array(&self, name: &str) -> CustResult<Rc<RefCell<ArrayValue>>> {
        match self.find_variable(name) {
            Some(Value::Array(values)) => Ok(Rc::clone(values)),
            Some(Value::Scalar { .. }) => {
                Err(CustError::new(format!("variable '{name}' is not an array")))
            }
            Some(Value::Pointer { .. }) => {
                Err(CustError::new(format!("pointer '{name}' is not an array")))
            }
            Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => Err(CustError::new(
                format!("struct variable '{name}' is not an array"),
            )),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn make_array_value(
        &mut self,
        len: usize,
        elem_type: CType,
        init: &[ArrayInitializer],
        read_only: bool,
    ) -> CustResult<Value> {
        let mut array = ArrayValue::mutable_zeroed(len, elem_type);
        let mut next_positional_index = 0usize;
        for initializer in init {
            match initializer {
                ArrayInitializer::Expr(expr) => {
                    array.elements[next_positional_index] =
                        self.eval_scalar_conversion(elem_type, expr)?;
                    next_positional_index += 1;
                }
                ArrayInitializer::Designated { index, value } => {
                    array.elements[*index] = self.eval_scalar_conversion(elem_type, value)?;
                    next_positional_index = *index + 1;
                }
                ArrayInitializer::StringLiteral(values) => {
                    for (index, value) in values.iter().take(len).enumerate() {
                        array.elements[index] = *value;
                    }
                    next_positional_index = values.len().min(len);
                }
            }
        }
        array.read_only = read_only;
        Ok(Value::Array(Rc::new(RefCell::new(array))))
    }

    fn make_two_dimensional_array_value(
        &mut self,
        rows: usize,
        columns: usize,
        elem_type: CType,
        init: &Array2DInitializer,
        read_only: bool,
    ) -> CustResult<Value> {
        let mut array = ArrayValue::mutable_zeroed_2d(rows, columns, elem_type);
        for (row_index, row) in init.iter().enumerate() {
            let mut next_column = 0usize;
            for initializer in row {
                match initializer {
                    ArrayInitializer::Expr(expr) => {
                        array.elements[row_index * columns + next_column] =
                            self.eval_scalar_conversion(elem_type, expr)?;
                        next_column += 1;
                    }
                    ArrayInitializer::Designated { index, value } => {
                        array.elements[row_index * columns + *index] =
                            self.eval_scalar_conversion(elem_type, value)?;
                        next_column = *index + 1;
                    }
                    ArrayInitializer::StringLiteral(values) => {
                        for (column, value) in values.iter().take(columns).enumerate() {
                            array.elements[row_index * columns + column] = *value;
                        }
                        next_column = values.len().min(columns);
                    }
                }
            }
        }
        array.read_only = read_only;
        Ok(Value::Array(Rc::new(RefCell::new(array))))
    }

    fn make_array_compound_literal(
        &mut self,
        len: Option<usize>,
        elem_type: CType,
        init: &[ArrayInitializer],
        read_only: bool,
    ) -> CustResult<Rc<RefCell<ArrayValue>>> {
        let len = len.unwrap_or_else(|| Self::infer_array_initializer_len(init));
        let Value::Array(array) = self.make_array_value(len, elem_type, init, read_only)? else {
            unreachable!("make_array_value always returns Value::Array")
        };
        Ok(array)
    }

    fn infer_array_initializer_len(init: &[ArrayInitializer]) -> usize {
        let mut len = 0usize;
        let mut next_positional_index = 0usize;
        for initializer in init {
            match initializer {
                ArrayInitializer::Expr(_) => {
                    len = len.max(next_positional_index + 1);
                    next_positional_index += 1;
                }
                ArrayInitializer::Designated { index, .. } => {
                    len = len.max(index + 1);
                    next_positional_index = index + 1;
                }
                ArrayInitializer::StringLiteral(values) => {
                    len = len.max(values.len());
                    next_positional_index = values.len();
                }
            }
        }
        len
    }

    fn infer_struct_array_initializer_len(init: &[StructArrayInitializer]) -> usize {
        let mut len = 0usize;
        let mut next_positional_index = 0usize;
        for initializer in init {
            match initializer {
                StructArrayInitializer::Element(_) => {
                    len = len.max(next_positional_index + 1);
                    next_positional_index += 1;
                }
                StructArrayInitializer::Designated { index, .. } => {
                    len = len.max(index + 1);
                    next_positional_index = index + 1;
                }
            }
        }
        len
    }

    fn make_struct_value(
        &mut self,
        type_name: &str,
        init: Option<&StructVarInitializer>,
    ) -> CustResult<Value> {
        let fields = match init {
            Some(StructVarInitializer::Fields(init)) => self.make_struct_fields(type_name, init)?,
            Some(StructVarInitializer::Expr(expr)) => match self.eval_struct_expr(expr)? {
                ReturnValue::Struct {
                    type_name: rhs_type,
                    fields,
                } if rhs_type == type_name => fields,
                ReturnValue::Struct {
                    type_name: rhs_type,
                    ..
                } => {
                    return Err(CustError::new(format!(
                        "cannot assign struct '{}' to struct '{}'",
                        self.aggregate_label(&rhs_type),
                        self.aggregate_label(type_name)
                    )));
                }
                ReturnValue::Scalar(_) => {
                    return Err(CustError::new("struct initializer requires struct value"));
                }
                ReturnValue::Pointer { .. } => {
                    return Err(CustError::new("struct initializer requires struct value"));
                }
            },
            None => self.make_struct_fields(type_name, &[])?,
        };
        Ok(Value::Struct {
            type_name: type_name.to_string(),
            fields,
        })
    }

    fn make_struct_array_value(
        &mut self,
        type_name: &str,
        len: usize,
        init: &[StructArrayInitializer],
        read_only: bool,
    ) -> CustResult<Value> {
        let mut elements = Vec::with_capacity(len);
        for _ in 0..len {
            elements.push(self.make_struct_fields(type_name, &[])?);
        }
        let mut next_positional_index = 0usize;
        for initializer in init {
            match initializer {
                StructArrayInitializer::Element(element_init) => {
                    if next_positional_index == len {
                        return Err(CustError::new("too many initializers for struct array"));
                    }
                    elements[next_positional_index] =
                        self.make_struct_fields(type_name, element_init.as_slice())?;
                    next_positional_index += 1;
                }
                StructArrayInitializer::Designated { index, value } => {
                    elements[*index] = self.make_struct_fields(type_name, value.as_slice())?;
                    next_positional_index = index + 1;
                }
            }
        }
        Ok(Value::StructArray {
            type_name: type_name.to_string(),
            elements,
            read_only,
        })
    }

    fn make_aggregate_array_compound_literal(
        &mut self,
        type_name: &str,
        len: Option<usize>,
        init: &[StructArrayInitializer],
        read_only: bool,
    ) -> CustResult<PointerValue> {
        let len = len.unwrap_or_else(|| Self::infer_struct_array_initializer_len(init));
        let value = self.make_struct_array_value(type_name, len, init, read_only)?;
        let scope_id = self
            .scopes
            .last()
            .expect("compound literal evaluation requires a current scope")
            .id;
        let name = format!(
            "__cust_compound_aggregate_array#{}",
            self.next_compound_literal_id
        );
        self.next_compound_literal_id += 1;
        self.current_scope_mut().insert(name.clone(), value);
        Ok(PointerValue::StructElement {
            scope_id,
            name,
            index: 0,
        })
    }

    fn make_scalar_compound_literal_pointer(
        &mut self,
        ty: CType,
        init: &Expr,
    ) -> CustResult<PointerValue> {
        let value = self.eval_scalar_conversion(ty, init)?;
        let scope_id = self
            .scopes
            .last()
            .expect("compound literal evaluation requires a current scope")
            .id;
        let name = format!("__cust_compound_scalar#{}", self.next_compound_literal_id);
        self.next_compound_literal_id += 1;
        self.current_scope_mut()
            .insert(name.clone(), Value::Scalar { value, ty });
        Ok(PointerValue::Scalar { scope_id, name })
    }

    fn make_aggregate_compound_literal_pointer(
        &mut self,
        type_name: &str,
        init: &[StructInitializer],
    ) -> CustResult<PointerValue> {
        let fields = self.make_struct_fields(type_name, init)?;
        let scope_id = self
            .scopes
            .last()
            .expect("compound literal evaluation requires a current scope")
            .id;
        let name = format!(
            "__cust_compound_aggregate#{}",
            self.next_compound_literal_id
        );
        self.next_compound_literal_id += 1;
        self.current_scope_mut().insert(
            name.clone(),
            Value::Struct {
                type_name: type_name.to_string(),
                fields,
            },
        );
        Ok(PointerValue::Struct { scope_id, name })
    }

    fn make_aggregate_compound_literal_field_pointer(
        &mut self,
        aggregate: &Expr,
        fields: &[String],
    ) -> CustResult<PointerValue> {
        let Expr::AggregateLiteral {
            type_name, init, ..
        } = aggregate
        else {
            return Err(CustError::new(
                "invalid address-of target for aggregate expression field",
            ));
        };
        match self.make_aggregate_compound_literal_pointer(type_name, init)? {
            PointerValue::Struct { scope_id, name } => {
                match self.struct_field_by_scope(scope_id, &name, None, fields)? {
                    StructFieldValue::Scalar { .. } | StructFieldValue::Struct { .. } => {
                        Ok(PointerValue::StructField {
                            scope_id,
                            name,
                            element_index: None,
                            fields: fields.to_vec(),
                        })
                    }
                    StructFieldValue::Array { value, .. } => Ok(PointerValue::ArrayBase {
                        array: Rc::clone(value),
                        source_name: Some(Self::field_path_label(fields).to_string()),
                        owner: None,
                    }),
                    StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                        "struct field '{}' requires indexed field access",
                        Self::field_path_label(fields)
                    ))),
                    StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                        "pointer field '{}' cannot be addressed in this pointer milestone",
                        Self::field_path_label(fields)
                    ))),
                }
            }
            _ => Err(CustError::new(
                "aggregate compound literal did not produce a struct pointer",
            )),
        }
    }

    fn make_struct_fields(
        &mut self,
        type_name: &str,
        init: &[StructInitializer],
    ) -> CustResult<HashMap<String, StructFieldValue>> {
        let struct_type = self
            .struct_types
            .get(type_name)
            .cloned()
            .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'")))?;
        let mut fields = HashMap::new();
        for field in &struct_type.fields {
            fields.insert(field.name.clone(), self.default_struct_field_value(field)?);
        }
        for initializer in init {
            let StructInitializer::Designated { field, value } = initializer else {
                unreachable!("struct initializer parsing resolves positional entries to fields")
            };
            let field_def = struct_type
                .fields
                .iter()
                .find(|field_def| field_def.name == *field)
                .ok_or_else(|| {
                    CustError::new(format!("struct '{type_name}' has no field '{field}'"))
                })?;
            self.apply_struct_field_initializer(&mut fields, field_def, value)?;
            if struct_type.kind == AggregateKind::Union {
                Self::sync_union_scalar_fields_from_active(&mut fields, field)?;
            }
        }
        Ok(fields)
    }

    fn sync_union_scalar_fields_from_active(
        fields: &mut HashMap<String, StructFieldValue>,
        active_field: &str,
    ) -> CustResult<()> {
        let active_value = match fields.get(active_field) {
            Some(StructFieldValue::Scalar { value, .. }) => Some(*value),
            Some(_) => None,
            None => {
                return Err(CustError::new(format!(
                    "missing union field '{active_field}'"
                )));
            }
        };
        if let Some(active_value) = active_value {
            for field_value in fields.values_mut() {
                if let StructFieldValue::Scalar { value, .. } = field_value {
                    *value = active_value;
                }
            }
        }
        Ok(())
    }

    fn default_struct_field_value(
        &mut self,
        field: &StructFieldDef,
    ) -> CustResult<StructFieldValue> {
        match &field.ty {
            StructFieldType::Scalar(ty) => Ok(StructFieldValue::Scalar {
                value: 0,
                ty: *ty,
                is_const: field.is_const,
            }),
            StructFieldType::Array(elem_type, len) => {
                let mut array = ArrayValue::mutable_zeroed(*len, *elem_type);
                array.read_only = field.is_const;
                Ok(StructFieldValue::Array {
                    value: Rc::new(RefCell::new(array)),
                    is_const: field.is_const,
                })
            }
            StructFieldType::Array2D(elem_type, rows, columns) => {
                let mut array = ArrayValue::mutable_zeroed_2d(*rows, *columns, *elem_type);
                array.read_only = field.is_const;
                Ok(StructFieldValue::Array {
                    value: Rc::new(RefCell::new(array)),
                    is_const: field.is_const,
                })
            }
            StructFieldType::Struct(nested_type) => Ok(StructFieldValue::Struct {
                type_name: nested_type.clone(),
                fields: self.make_struct_fields(nested_type, &[])?,
                is_const: field.is_const,
            }),
            StructFieldType::StructArray(nested_type, len) => {
                let mut elements = Vec::with_capacity(*len);
                for _ in 0..*len {
                    elements.push(self.make_struct_fields(nested_type, &[])?);
                }
                Ok(StructFieldValue::StructArray {
                    type_name: nested_type.clone(),
                    elements,
                    is_const: field.is_const,
                })
            }
            StructFieldType::Pointer(pointee) => Ok(StructFieldValue::Pointer {
                pointer: PointerValue::Null,
                ty: pointee.clone(),
                is_const: field.is_const,
                points_to_const: field.points_to_const,
            }),
        }
    }

    fn apply_struct_field_initializer(
        &mut self,
        fields: &mut HashMap<String, StructFieldValue>,
        field: &StructFieldDef,
        initializer: &StructInitializer,
    ) -> CustResult<()> {
        let field_value = fields
            .get_mut(&field.name)
            .ok_or_else(|| CustError::new(format!("missing struct field '{}'", field.name)))?;
        match (&field.ty, field_value, initializer) {
            (
                StructFieldType::Scalar(ty),
                StructFieldValue::Scalar { value, .. },
                StructInitializer::Expr(expr),
            ) => {
                *value = self.eval_scalar_conversion(*ty, expr)?;
            }
            (
                StructFieldType::Scalar(_),
                _,
                StructInitializer::Array(_) | StructInitializer::Struct(_),
            ) => {
                return Err(CustError::new(format!(
                    "nested initializer for scalar field '{}' is not supported",
                    field.name
                )));
            }
            (
                StructFieldType::Array2D(elem_type, _, columns),
                StructFieldValue::Array { value, .. },
                StructInitializer::Array2D(array_init),
            ) => {
                let mut array = value.borrow_mut();
                for (row_index, row) in array_init.iter().enumerate() {
                    let mut next_column = 0usize;
                    for initializer in row {
                        match initializer {
                            ArrayInitializer::Expr(expr) => {
                                array.elements[row_index * *columns + next_column] =
                                    self.eval_scalar_conversion(*elem_type, expr)?;
                                next_column += 1;
                            }
                            ArrayInitializer::Designated { index, value } => {
                                array.elements[row_index * *columns + *index] =
                                    self.eval_scalar_conversion(*elem_type, value)?;
                                next_column = *index + 1;
                            }
                            ArrayInitializer::StringLiteral(values) => {
                                for (column, value) in values.iter().take(*columns).enumerate() {
                                    array.elements[row_index * *columns + column] = *value;
                                }
                                next_column = values.len().min(*columns);
                            }
                        }
                    }
                }
            }
            (
                StructFieldType::Array2D(_, _, _),
                _,
                StructInitializer::Expr(_)
                | StructInitializer::Array(_)
                | StructInitializer::Struct(_),
            ) => {
                return Err(CustError::new(format!(
                    "expected two-dimensional array initializer for struct field '{}'",
                    field.name
                )));
            }
            (
                StructFieldType::Array(elem_type, _),
                StructFieldValue::Array { value, .. },
                StructInitializer::Array(array_init),
            ) => {
                let mut array = value.borrow_mut();
                let mut next_positional_index = 0usize;
                for initializer in array_init {
                    match initializer {
                        ArrayInitializer::Expr(expr) => {
                            array.elements[next_positional_index] =
                                self.eval_scalar_conversion(*elem_type, expr)?;
                            next_positional_index += 1;
                        }
                        ArrayInitializer::Designated { index, value } => {
                            array.elements[*index] =
                                self.eval_scalar_conversion(*elem_type, value)?;
                            next_positional_index = *index + 1;
                        }
                        ArrayInitializer::StringLiteral(values) => {
                            for (index, value) in
                                values.iter().take(array.elements.len()).enumerate()
                            {
                                array.elements[index] = *value;
                            }
                            next_positional_index = values.len().min(array.elements.len());
                        }
                    }
                }
            }
            (
                StructFieldType::Array(_, _),
                _,
                StructInitializer::Expr(_) | StructInitializer::Struct(_),
            ) => {
                return Err(CustError::new(format!(
                    "expected array initializer for struct field '{}'",
                    field.name
                )));
            }
            (
                StructFieldType::Struct(nested_type),
                StructFieldValue::Struct {
                    fields: nested_fields,
                    ..
                },
                StructInitializer::Struct(nested_init),
            ) => {
                let nested_type_def =
                    self.struct_types.get(nested_type).cloned().ok_or_else(|| {
                        CustError::new(format!("undefined struct type '{nested_type}'"))
                    })?;
                for nested_initializer in nested_init {
                    let StructInitializer::Designated { field, value } = nested_initializer else {
                        unreachable!(
                            "nested struct initializer parsing resolves positional entries to fields"
                        )
                    };
                    let nested_field_def = nested_type_def
                        .fields
                        .iter()
                        .find(|field_def| field_def.name == *field)
                        .ok_or_else(|| {
                            CustError::new(format!("struct '{nested_type}' has no field '{field}'"))
                        })?;
                    self.apply_struct_field_initializer(nested_fields, nested_field_def, value)?;
                    if nested_type_def.kind == AggregateKind::Union {
                        Self::sync_union_scalar_fields_from_active(nested_fields, field)?;
                    }
                }
            }
            (StructFieldType::Struct(_), _, StructInitializer::Array(_)) => {
                return Err(CustError::new(format!(
                    "array initializer for struct field '{}' is not supported",
                    field.name
                )));
            }
            (
                StructFieldType::StructArray(type_name, len),
                StructFieldValue::StructArray { elements, .. },
                StructInitializer::StructArray(init),
            ) => {
                let nested_type_def =
                    self.struct_types.get(type_name).cloned().ok_or_else(|| {
                        CustError::new(format!("undefined struct type '{type_name}'"))
                    })?;
                let mut next_positional_index = 0usize;
                for initializer in init {
                    match initializer {
                        StructArrayInitializer::Element(element_init) => {
                            if next_positional_index == *len {
                                return Err(CustError::new(
                                    "too many initializers for struct array",
                                ));
                            }
                            elements[next_positional_index] =
                                self.make_struct_fields(type_name, element_init.as_slice())?;
                            next_positional_index += 1;
                        }
                        StructArrayInitializer::Designated { index, value } => {
                            for nested_initializer in value {
                                let StructInitializer::Designated { field, value } =
                                    nested_initializer
                                else {
                                    unreachable!(
                                        "nested struct array initializer parsing resolves positional entries to fields"
                                    )
                                };
                                let nested_field_def = nested_type_def
                                    .fields
                                    .iter()
                                    .find(|field_def| field_def.name == *field)
                                    .ok_or_else(|| {
                                        CustError::new(format!(
                                            "struct '{type_name}' has no field '{field}'"
                                        ))
                                    })?;
                                self.apply_struct_field_initializer(
                                    &mut elements[*index],
                                    nested_field_def,
                                    value,
                                )?;
                                if nested_type_def.kind == AggregateKind::Union {
                                    Self::sync_union_scalar_fields_from_active(
                                        &mut elements[*index],
                                        field,
                                    )?;
                                }
                            }
                            next_positional_index = index + 1;
                        }
                    }
                }
            }
            (
                StructFieldType::StructArray(_, _),
                _,
                StructInitializer::Expr(_)
                | StructInitializer::Array(_)
                | StructInitializer::Struct(_),
            ) => {
                return Err(CustError::new(format!(
                    "expected struct array initializer for struct field '{}'",
                    field.name
                )));
            }
            (StructFieldType::Struct(nested_type), field_value, StructInitializer::Expr(expr)) => {
                match self.eval_struct_expr(expr)? {
                    ReturnValue::Struct { type_name, fields } if type_name == *nested_type => {
                        *field_value = StructFieldValue::Struct {
                            type_name,
                            fields,
                            is_const: field.is_const,
                        };
                    }
                    ReturnValue::Struct { type_name, .. } => {
                        return Err(CustError::new(format!(
                            "cannot initialize struct field '{}' of type '{}' with struct '{}'",
                            field.name, nested_type, type_name
                        )));
                    }
                    ReturnValue::Scalar(_) => {
                        unreachable!("eval_struct_expr only returns struct values or errors")
                    }
                    ReturnValue::Pointer { .. } => {
                        unreachable!("eval_struct_expr only returns struct values or errors")
                    }
                }
            }
            (
                StructFieldType::Pointer(_),
                StructFieldValue::Pointer { pointer, .. },
                StructInitializer::Expr(expr),
            ) => {
                self.ensure_pointer_conversion_preserves_const(field.points_to_const, expr)?;
                let assigned = self.eval_pointer(expr)?;
                let assigned = self.attach_array_pointer_owner(assigned);
                if let StructFieldType::Pointer(expected_ty) = &field.ty {
                    self.ensure_pointer_type_matches(expected_ty, &assigned)?;
                }
                *pointer = assigned;
            }
            (
                StructFieldType::Pointer(_),
                _,
                StructInitializer::Array(_) | StructInitializer::Struct(_),
            ) => {
                return Err(CustError::new(format!(
                    "nested initializer for pointer field '{}' is not supported",
                    field.name
                )));
            }
            (_, _, StructInitializer::Designated { .. }) => {
                unreachable!("designated struct initializers are resolved before evaluation")
            }
            _ => unreachable!("struct field definition and value variants must match"),
        }
        Ok(())
    }

    fn field_path_label(fields: &[String]) -> &str {
        fields.last().map(String::as_str).unwrap_or("<missing>")
    }

    fn nested_field_value<'a>(
        type_name: &'a str,
        fields_map: &'a HashMap<String, StructFieldValue>,
        path: &[String],
    ) -> CustResult<(&'a str, &'a StructFieldValue)> {
        let Some((field, rest)) = path.split_first() else {
            return Err(CustError::new("expected struct field"));
        };
        let value = fields_map.get(field).ok_or_else(|| {
            CustError::new(format!("struct '{type_name}' has no field '{field}'"))
        })?;
        if rest.is_empty() {
            return Ok((type_name, value));
        }
        match value {
            StructFieldValue::Struct {
                type_name, fields, ..
            } => Self::nested_field_value(type_name, fields, rest),
            StructFieldValue::Scalar { .. }
            | StructFieldValue::Array { .. }
            | StructFieldValue::StructArray { .. }
            | StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                "struct field '{field}' is not a struct"
            ))),
        }
    }

    fn nested_field_value_mut<'a>(
        type_name: &'a str,
        fields_map: &'a mut HashMap<String, StructFieldValue>,
        path: &[String],
    ) -> CustResult<(&'a str, &'a mut StructFieldValue)> {
        let Some((field, rest)) = path.split_first() else {
            return Err(CustError::new("expected struct field"));
        };
        let value = fields_map.get_mut(field).ok_or_else(|| {
            CustError::new(format!("struct '{type_name}' has no field '{field}'"))
        })?;
        if rest.is_empty() {
            return Ok((type_name, value));
        }
        match value {
            StructFieldValue::Struct {
                type_name, fields, ..
            } => Self::nested_field_value_mut(type_name, fields, rest),
            StructFieldValue::Scalar { .. }
            | StructFieldValue::Array { .. }
            | StructFieldValue::StructArray { .. }
            | StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                "struct field '{field}' is not a struct"
            ))),
        }
    }

    fn nested_struct_field<'a>(
        type_name: &str,
        fields_map: &'a HashMap<String, StructFieldValue>,
        path: &[String],
    ) -> CustResult<(String, &'a HashMap<String, StructFieldValue>)> {
        let Some((field, rest)) = path.split_first() else {
            return Err(CustError::new("expected struct field"));
        };
        let value = fields_map.get(field).ok_or_else(|| {
            CustError::new(format!("struct '{type_name}' has no field '{field}'"))
        })?;
        match value {
            StructFieldValue::Struct {
                type_name, fields, ..
            } if rest.is_empty() => Ok((type_name.clone(), fields)),
            StructFieldValue::Struct {
                type_name, fields, ..
            } => Self::nested_struct_field(type_name, fields, rest),
            StructFieldValue::Scalar { .. }
            | StructFieldValue::Array { .. }
            | StructFieldValue::StructArray { .. }
            | StructFieldValue::Pointer { .. } => {
                if rest.is_empty() {
                    Err(CustError::new("pointer does not reference a struct"))
                } else {
                    Err(CustError::new(format!(
                        "struct field '{field}' is not a struct"
                    )))
                }
            }
        }
    }

    fn nested_struct_field_mut<'a>(
        type_name: &str,
        fields_map: &'a mut HashMap<String, StructFieldValue>,
        path: &[String],
    ) -> CustResult<(String, &'a mut HashMap<String, StructFieldValue>)> {
        let Some((field, rest)) = path.split_first() else {
            return Err(CustError::new("expected struct field"));
        };
        let value = fields_map.get_mut(field).ok_or_else(|| {
            CustError::new(format!("struct '{type_name}' has no field '{field}'"))
        })?;
        if rest.is_empty() {
            return match value {
                StructFieldValue::Struct {
                    type_name, fields, ..
                } => Ok((type_name.clone(), fields)),
                StructFieldValue::Scalar { .. }
                | StructFieldValue::Array { .. }
                | StructFieldValue::StructArray { .. }
                | StructFieldValue::Pointer { .. } => {
                    Err(CustError::new("pointer does not reference a struct"))
                }
            };
        }
        match value {
            StructFieldValue::Struct {
                type_name, fields, ..
            } => Self::nested_struct_field_mut(type_name, fields, rest),
            StructFieldValue::Scalar { .. }
            | StructFieldValue::Array { .. }
            | StructFieldValue::StructArray { .. }
            | StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                "struct field '{field}' is not a struct"
            ))),
        }
    }

    fn read_struct_field(&self, name: &str, path: &[String]) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::Struct { type_name, fields }) => {
                let (_, field_value) = Self::nested_field_value(type_name, fields, path)?;
                match field_value {
                    StructFieldValue::Scalar { value, .. } => Ok(*value),
                    StructFieldValue::Array { .. } => Err(CustError::new(format!(
                        "struct field '{}' is an array",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct '{type_name}'",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct array",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                        "pointer field '{}' used as scalar",
                        Self::field_path_label(path)
                    ))),
                }
            }
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn assign_scalar_field_in_map(
        struct_types: &HashMap<String, StructTypeDef>,
        type_name: &str,
        fields_map: &mut HashMap<String, StructFieldValue>,
        path: &[String],
        value: i64,
    ) -> CustResult<()> {
        let Some((field, rest)) = path.split_first() else {
            return Err(CustError::new("expected struct field"));
        };
        if rest.is_empty() {
            let field_value = fields_map.get_mut(field).ok_or_else(|| {
                CustError::new(format!("struct '{type_name}' has no field '{field}'"))
            })?;
            if field_value.is_const() {
                return Err(CustError::new(format!(
                    "cannot assign to const struct field '{}'",
                    Self::field_path_label(path)
                )));
            }
            match field_value {
                StructFieldValue::Scalar {
                    value: slot, ty, ..
                } => {
                    *slot = ty.normalize(value);
                    if struct_types
                        .get(type_name)
                        .is_some_and(|aggregate| aggregate.kind == AggregateKind::Union)
                    {
                        Self::sync_union_scalar_fields_from_active(fields_map, field)?;
                    }
                    Ok(())
                }
                StructFieldValue::Array { .. } => Err(CustError::new(format!(
                    "struct field '{}' is an array",
                    Self::field_path_label(path)
                ))),
                StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                    "struct field '{}' is a struct '{type_name}'",
                    Self::field_path_label(path)
                ))),
                StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                    "struct field '{}' is a struct array",
                    Self::field_path_label(path)
                ))),
                StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                    "pointer field '{}' used as scalar",
                    Self::field_path_label(path)
                ))),
            }
        } else {
            let field_value = fields_map.get_mut(field).ok_or_else(|| {
                CustError::new(format!("struct '{type_name}' has no field '{field}'"))
            })?;
            if field_value.is_const() {
                return Err(CustError::new(format!(
                    "cannot assign to const struct field '{field}'"
                )));
            }
            match field_value {
                StructFieldValue::Struct {
                    type_name: nested_type,
                    fields: nested_fields,
                    ..
                } => Self::assign_scalar_field_in_map(
                    struct_types,
                    nested_type,
                    nested_fields,
                    rest,
                    value,
                ),
                StructFieldValue::Scalar { .. }
                | StructFieldValue::Array { .. }
                | StructFieldValue::StructArray { .. }
                | StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                    "struct field '{field}' is not a struct"
                ))),
            }
        }
    }

    fn assign_struct_field(&mut self, name: &str, path: &[String], value: i64) -> CustResult<()> {
        self.ensure_variable_mutable(name)?;
        let struct_types = self.struct_types.clone();
        match self.find_variable_mut(name) {
            Some(Value::Struct { type_name, fields }) => {
                Self::assign_scalar_field_in_map(&struct_types, type_name, fields, path, value)
            }
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn nested_field_path_is_const(
        fields_map: &HashMap<String, StructFieldValue>,
        path: &[String],
    ) -> CustResult<bool> {
        let Some((field, rest)) = path.split_first() else {
            return Err(CustError::new("expected struct field"));
        };
        let value = fields_map
            .get(field)
            .ok_or_else(|| CustError::new(format!("struct has no field '{field}'")))?;
        if value.is_const() {
            return Ok(true);
        }
        if rest.is_empty() {
            return Ok(false);
        }
        match value {
            StructFieldValue::Struct { fields, .. } => {
                Self::nested_field_path_is_const(fields, rest)
            }
            StructFieldValue::Scalar { .. }
            | StructFieldValue::Array { .. }
            | StructFieldValue::StructArray { .. }
            | StructFieldValue::Pointer { .. } => Ok(false),
        }
    }

    fn direct_struct_array_field_points_to_const(&self, name: &str, path: &[String]) -> bool {
        let root_is_const = self.is_const_variable(name);
        match self.find_variable(name) {
            Some(Value::Struct { fields, .. }) => {
                root_is_const || Self::nested_field_path_is_const(fields, path).unwrap_or(false)
            }
            _ => false,
        }
    }

    fn struct_array_element_field_points_to_const(&self, name: &str, path: &[String]) -> bool {
        match self.find_variable(name) {
            Some(Value::StructArray {
                elements,
                read_only,
                ..
            }) => {
                *read_only
                    || elements.first().is_some_and(|fields| {
                        Self::nested_field_path_is_const(fields, path).unwrap_or(false)
                    })
            }
            Some(Value::Pointer {
                ty: PointeeType::Struct(type_name),
                points_to_const,
                ..
            }) => {
                *points_to_const
                    || self
                        .const_aggregate_field_label_for_path(type_name, path)
                        .is_some()
            }
            _ => false,
        }
    }

    fn struct_pointer_field_points_to_const(&self, name: &str, path: &[String]) -> bool {
        match self.find_variable(name) {
            Some(Value::Struct { type_name, fields }) => {
                match Self::nested_field_value(type_name, fields, path) {
                    Ok((
                        _,
                        StructFieldValue::Pointer {
                            points_to_const, ..
                        },
                    )) => *points_to_const,
                    _ => false,
                }
            }
            _ => false,
        }
    }

    fn struct_field_is_pointer(&self, name: &str, path: &[String]) -> bool {
        matches!(
            self.find_variable(name),
            Some(Value::Struct { type_name, fields })
                if matches!(
                    Self::nested_field_value(type_name, fields, path),
                    Ok((_, StructFieldValue::Pointer { .. }))
                )
        )
    }

    fn struct_field_decays_to_pointer(&self, name: &str, path: &[String]) -> bool {
        matches!(
            self.find_variable(name),
            Some(Value::Struct { type_name, fields })
                if matches!(
                    Self::nested_field_value(type_name, fields, path),
                    Ok((_, StructFieldValue::Pointer { .. } | StructFieldValue::Array { .. } | StructFieldValue::StructArray { .. }))
                )
        )
    }

    fn struct_element_field_decays_to_pointer(&self, name: &str, path: &[String]) -> bool {
        matches!(
            self.struct_element_field_metadata(name, path),
            Ok(Some((
                StructFieldType::Pointer(_)
                    | StructFieldType::Array(_, _)
                    | StructFieldType::Array2D(_, _, _)
                    | StructFieldType::StructArray(_, _),
                _,
                _
            )))
        )
    }

    fn struct_element_field_metadata(
        &self,
        name: &str,
        path: &[String],
    ) -> CustResult<Option<(StructFieldType, bool, bool)>> {
        let type_name = match self.find_variable(name) {
            Some(Value::StructArray { type_name, .. })
            | Some(Value::Pointer {
                ty: PointeeType::Struct(type_name),
                ..
            }) => type_name,
            _ => return Ok(None),
        };
        self.aggregate_type_field_metadata(type_name, path)
    }

    fn struct_pointer_field_decays_to_pointer(&self, pointer: &Expr, path: &[String]) -> bool {
        let Ok(Some(PointeeType::Struct(mut current_type_name))) =
            self.pointer_expr_pointee_type(pointer)
        else {
            return false;
        };
        for (index, field_name) in path.iter().enumerate() {
            let Some(struct_type) = self.struct_types.get(&current_type_name) else {
                return false;
            };
            let Some(field) = struct_type
                .fields
                .iter()
                .find(|field| field.name == *field_name)
            else {
                return false;
            };
            let is_last = index + 1 == path.len();
            match &field.ty {
                StructFieldType::Pointer(_)
                | StructFieldType::Array(_, _)
                | StructFieldType::Array2D(_, _, _)
                | StructFieldType::StructArray(_, _)
                    if is_last =>
                {
                    return true;
                }
                StructFieldType::Struct(nested_type) if !is_last => {
                    current_type_name = nested_type.clone();
                }
                _ => return false,
            }
        }
        false
    }

    fn read_direct_struct_pointer_field(
        &self,
        name: &str,
        path: &[String],
    ) -> CustResult<PointerValue> {
        match self.find_variable(name) {
            Some(Value::Struct { type_name, fields }) => {
                let (_, field_value) = Self::nested_field_value(type_name, fields, path)?;
                match field_value {
                    StructFieldValue::Pointer { pointer, .. } => Ok(pointer.clone()),
                    StructFieldValue::Scalar { .. } => Err(CustError::new(format!(
                        "struct field '{}' is not a pointer",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Array { .. } => Err(CustError::new(format!(
                        "struct field '{}' is an array",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct '{type_name}'",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct array",
                        Self::field_path_label(path)
                    ))),
                }
            }
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn direct_struct_pointer_field_index_pointer(
        &mut self,
        name: &str,
        path: &[String],
        index: &Expr,
    ) -> CustResult<PointerValue> {
        let field_pointer = self.read_direct_struct_pointer_field(name, path)?;
        let index_value = self.eval(index)?;
        if matches!(
            self.direct_struct_pointer_field_type(name, path)?,
            Some(PointeeType::Struct(_))
        ) {
            return self.offset_array_pointer(&field_pointer, index_value);
        }
        let (array, source_name, index, owner) =
            self.checked_pointer_value_index(&field_pointer, index_value)?;
        Ok(PointerValue::ArrayElement {
            array,
            source_name,
            index,
            owner,
        })
    }

    fn assign_direct_struct_pointer_field(
        &mut self,
        name: &str,
        path: &[String],
        value: PointerValue,
    ) -> CustResult<()> {
        self.ensure_variable_mutable(name)?;
        let value = self.attach_array_pointer_owner(value);
        if let Some(expected) = self.direct_struct_pointer_field_type(name, path)? {
            self.ensure_pointer_type_matches(&expected, &value)?;
        }
        match self.find_variable_mut(name) {
            Some(Value::Struct { type_name, fields }) => {
                let (_, field_value) = Self::nested_field_value_mut(type_name, fields, path)?;
                if field_value.is_const() {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(path)
                    )));
                }
                match field_value {
                    StructFieldValue::Pointer { pointer, .. } => {
                        *pointer = value;
                        Ok(())
                    }
                    StructFieldValue::Scalar { .. } => Err(CustError::new(format!(
                        "struct field '{}' is not a pointer",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Array { .. } => Err(CustError::new(format!(
                        "struct field '{}' is an array",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct '{type_name}'",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct array",
                        Self::field_path_label(path)
                    ))),
                }
            }
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn direct_struct_pointer_field_type(
        &self,
        name: &str,
        path: &[String],
    ) -> CustResult<Option<PointeeType>> {
        match self.find_variable(name) {
            Some(Value::Struct { type_name, fields }) => {
                let (_, field_value) = Self::nested_field_value(type_name, fields, path)?;
                match field_value {
                    StructFieldValue::Pointer { ty, .. } => Ok(Some(ty.clone())),
                    _ => Ok(None),
                }
            }
            Some(_) => Ok(None),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn offset_direct_struct_pointer_field(
        &mut self,
        name: &str,
        path: &[String],
        offset: i64,
    ) -> CustResult<(PointerValue, PointerValue)> {
        let current = self.read_direct_struct_pointer_field(name, path)?;
        let updated = self.offset_array_pointer(&current, offset)?;
        self.assign_direct_struct_pointer_field(name, path, updated.clone())?;
        Ok((current, updated))
    }

    fn compound_assign_direct_struct_pointer_field(
        &mut self,
        name: &str,
        path: &[String],
        op: CompoundOp,
        value: &Expr,
    ) -> CustResult<PointerValue> {
        let offset = self.eval(value)?;
        let offset = match op {
            CompoundOp::Add => offset,
            CompoundOp::Sub => -offset,
            CompoundOp::Mul
            | CompoundOp::Div
            | CompoundOp::Rem
            | CompoundOp::BitAnd
            | CompoundOp::BitOr
            | CompoundOp::BitXor
            | CompoundOp::ShiftLeft
            | CompoundOp::ShiftRight => return Err(Self::pointer_compound_error(op)),
        };
        let (_, updated) = self.offset_direct_struct_pointer_field(name, path, offset)?;
        Ok(updated)
    }

    fn increment_direct_struct_pointer_field(
        &mut self,
        name: &str,
        path: &[String],
        op: IncrementOp,
        prefix: bool,
    ) -> CustResult<PointerValue> {
        let offset = match op {
            IncrementOp::Inc => 1,
            IncrementOp::Dec => -1,
        };
        let (current, updated) = self.offset_direct_struct_pointer_field(name, path, offset)?;
        if prefix { Ok(updated) } else { Ok(current) }
    }

    fn find_struct_array_field(
        &self,
        name: &str,
        path: &[String],
    ) -> CustResult<Rc<RefCell<ArrayValue>>> {
        match self.find_variable(name) {
            Some(Value::Struct { type_name, fields }) => {
                let (_, field_value) = Self::nested_field_value(type_name, fields, path)?;
                match field_value {
                    StructFieldValue::Array { value, .. } => Ok(Rc::clone(value)),
                    StructFieldValue::Scalar { .. } => Err(CustError::new(format!(
                        "struct field '{}' is not an array",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct '{type_name}'",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct array",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                        "struct field '{}' is not an array",
                        Self::field_path_label(path)
                    ))),
                }
            }
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn checked_struct_array_index(
        &mut self,
        name: &str,
        fields: &[String],
        index: &Expr,
    ) -> CustResult<(Rc<RefCell<ArrayValue>>, usize)> {
        let index_value = self.eval(index)?;
        let array = self.find_struct_array_field(name, fields)?;
        let len = array.borrow().elements.len();
        let Ok(index) = usize::try_from(index_value) else {
            return Err(CustError::new(format!(
                "array '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        };
        if index >= len {
            return Err(CustError::new(format!(
                "array '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        }
        Ok((array, index))
    }

    fn read_struct_field_array_element_field(
        &mut self,
        name: &str,
        array_fields: &[String],
        index: &Expr,
        fields: &[String],
    ) -> CustResult<i64> {
        let index_value = self.eval(index)?;
        match self.find_variable(name) {
            Some(Value::Struct {
                type_name,
                fields: field_map,
            }) => {
                let (_, array_value) =
                    Self::nested_field_value(type_name, field_map, array_fields)?;
                let StructFieldValue::StructArray {
                    type_name: element_type,
                    elements,
                    ..
                } = array_value
                else {
                    return Err(CustError::new(format!(
                        "struct field '{}' is not a struct array",
                        Self::field_path_label(array_fields)
                    )));
                };
                let len = elements.len();
                let Ok(index) = usize::try_from(index_value) else {
                    return Err(CustError::new(format!(
                        "struct array field '{}' index {index_value} out of bounds for length {len}",
                        Self::field_path_label(array_fields)
                    )));
                };
                let element = elements.get(index).ok_or_else(|| {
                    CustError::new(format!(
                        "struct array field '{}' index {index_value} out of bounds for length {len}",
                        Self::field_path_label(array_fields)
                    ))
                })?;
                let (_, field_value) = Self::nested_field_value(element_type, element, fields)?;
                match field_value {
                    StructFieldValue::Scalar { value, .. } => Ok(*value),
                    StructFieldValue::Array { .. } => Err(CustError::new(format!(
                        "struct field '{}' is an array",
                        Self::field_path_label(fields)
                    ))),
                    StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct '{type_name}'",
                        Self::field_path_label(fields)
                    ))),
                    StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct array",
                        Self::field_path_label(fields)
                    ))),
                    StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                        "pointer field '{}' used as scalar",
                        Self::field_path_label(fields)
                    ))),
                }
            }
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn struct_field_array_element_pointer(
        &mut self,
        name: &str,
        array_fields: &[String],
        index: &Expr,
    ) -> CustResult<PointerValue> {
        if let Some(pointer) =
            self.scalar_field_reverse_subscript_pointer(name, array_fields, index)?
        {
            return Ok(pointer);
        }
        self.find_struct_array_field_pointer(name, array_fields, index)
    }

    fn struct_field_array_element_assignment_pointer(
        &mut self,
        name: &str,
        array_fields: &[String],
        index: &Expr,
    ) -> CustResult<PointerValue> {
        if let Some(pointer) =
            self.scalar_field_reverse_subscript_pointer(name, array_fields, index)?
        {
            match index {
                Expr::Var(pointer_name)
                    if matches!(
                        self.find_variable(pointer_name),
                        Some(Value::StructArray { .. })
                    ) =>
                {
                    self.ensure_variable_mutable(pointer_name)?;
                }
                _ => {}
            }
            self.ensure_reverse_subscript_pointee_mutable(index)?;
            return Ok(pointer);
        }

        if self.struct_field_is_pointer(name, array_fields) {
            if self.struct_pointer_field_points_to_const(name, array_fields) {
                return Err(CustError::new("cannot assign through pointer to const"));
            }
            return self.find_struct_array_field_pointer(name, array_fields, index);
        }

        self.ensure_variable_mutable(name)?;
        if self.direct_struct_array_field_points_to_const(name, array_fields) {
            return Err(CustError::new(format!(
                "cannot assign to const struct field '{}'",
                Self::field_path_label(array_fields)
            )));
        }
        self.find_struct_array_field_pointer(name, array_fields, index)
    }

    fn find_struct_array_field_pointer(
        &mut self,
        name: &str,
        fields: &[String],
        index: &Expr,
    ) -> CustResult<PointerValue> {
        if self.struct_field_is_pointer(name, fields) {
            return self.direct_struct_pointer_field_index_pointer(name, fields, index);
        }
        if self
            .direct_struct_aggregate_array_field_type(name, fields)?
            .is_some()
        {
            let index =
                self.checked_struct_aggregate_array_field_index(name, None, fields, index)?;
            let scope_id = self
                .find_variable_scope_id(name)
                .ok_or_else(|| CustError::new(format!("undefined variable '{name}'")))?;
            return Ok(PointerValue::StructFieldElement {
                scope_id,
                name: name.to_string(),
                element_index: None,
                fields: fields.to_vec(),
                index,
            });
        }
        let (array, index) = self.checked_struct_array_index(name, fields, index)?;
        Ok(PointerValue::ArrayElement {
            array,
            source_name: Some(Self::field_path_label(fields).to_string()),
            owner: None,
            index,
        })
    }

    fn find_struct_array_field_base_pointer(
        &self,
        name: &str,
        fields: &[String],
    ) -> CustResult<PointerValue> {
        if self
            .direct_struct_aggregate_array_field_type(name, fields)?
            .is_some()
        {
            let scope_id = self
                .find_variable_scope_id(name)
                .ok_or_else(|| CustError::new(format!("undefined variable '{name}'")))?;
            return Ok(PointerValue::StructFieldElement {
                scope_id,
                name: name.to_string(),
                element_index: None,
                fields: fields.to_vec(),
                index: 0,
            });
        }
        let array = self.find_struct_array_field(name, fields)?;
        let source_name = Some(Self::field_path_label(fields).to_string());
        if array.borrow().dimensions.is_some() {
            return Ok(PointerValue::Array2DRow {
                array,
                source_name,
                row: 0,
                owner: None,
            });
        }
        Ok(PointerValue::ArrayBase {
            array,
            source_name,
            owner: None,
        })
    }

    fn find_struct_element_array_field_base_pointer(
        &mut self,
        name: &str,
        index: &Expr,
        fields: &[String],
    ) -> CustResult<PointerValue> {
        let element_pointer = self.indexed_struct_element_pointer(name, index)?;
        self.find_struct_pointer_array_field_base_pointer(&element_pointer, fields)
    }

    fn direct_struct_aggregate_array_field_type(
        &self,
        name: &str,
        fields: &[String],
    ) -> CustResult<Option<String>> {
        let Some(scope_id) = self.find_variable_scope_id(name) else {
            return Err(CustError::new(format!("undefined variable '{name}'")));
        };
        match self.struct_field_by_scope(scope_id, name, None, fields)? {
            StructFieldValue::StructArray { type_name, .. } => Ok(Some(type_name.clone())),
            _ => Ok(None),
        }
    }

    fn checked_struct_aggregate_array_field_index(
        &mut self,
        name: &str,
        element_index: Option<usize>,
        fields: &[String],
        index: &Expr,
    ) -> CustResult<usize> {
        let scope_id = self
            .find_variable_scope_id(name)
            .ok_or_else(|| CustError::new(format!("undefined variable '{name}'")))?;
        let index_value = self.eval(index)?;
        let len = match self.struct_field_by_scope(scope_id, name, element_index, fields)? {
            StructFieldValue::StructArray { elements, .. } => elements.len(),
            _ => {
                return Err(CustError::new(format!(
                    "struct field '{}' is not a struct array",
                    Self::field_path_label(fields)
                )));
            }
        };
        let Ok(index) = usize::try_from(index_value) else {
            return Err(CustError::new(format!(
                "struct array field '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        };
        if index >= len {
            return Err(CustError::new(format!(
                "struct array field '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        }
        Ok(index)
    }

    fn struct_field_array_pointer_at(
        &self,
        scope_id: usize,
        name: &str,
        element_index: Option<usize>,
        fields: &[String],
        index: i64,
    ) -> CustResult<PointerValue> {
        let field_value = self.struct_field_by_scope(scope_id, name, element_index, fields)?;
        let len = match field_value {
            StructFieldValue::StructArray { elements, .. } => elements.len(),
            _ => {
                return Err(CustError::new(format!(
                    "struct field '{}' is not a struct array",
                    Self::field_path_label(fields)
                )));
            }
        };
        let Ok(index_usize) = usize::try_from(index) else {
            return Err(CustError::new(format!(
                "struct array field pointer index {index} out of bounds for length {len}"
            )));
        };
        if index_usize >= len {
            return Err(CustError::new(format!(
                "struct array field pointer index {index} out of bounds for length {len}"
            )));
        }
        Ok(PointerValue::StructFieldElement {
            scope_id,
            name: name.to_string(),
            element_index,
            fields: fields.to_vec(),
            index: index_usize,
        })
    }

    fn struct_field_array_element_fields(
        &self,
        scope_id: usize,
        name: &str,
        element_index: Option<usize>,
        fields: &[String],
        index: usize,
    ) -> CustResult<(String, &HashMap<String, StructFieldValue>)> {
        match self.struct_field_by_scope(scope_id, name, element_index, fields)? {
            StructFieldValue::StructArray {
                type_name,
                elements,
                ..
            } => elements
                .get(index)
                .map(|element| (type_name.clone(), element))
                .ok_or_else(|| {
                    CustError::new(format!(
                        "struct array field pointer index {index} out of bounds for length {}",
                        elements.len()
                    ))
                }),
            _ => Err(CustError::new(format!(
                "struct field '{}' is not a struct array",
                Self::field_path_label(fields)
            ))),
        }
    }

    fn struct_field_array_element_fields_mut(
        &mut self,
        scope_id: usize,
        name: &str,
        element_index: Option<usize>,
        fields: &[String],
        index: usize,
    ) -> CustResult<(String, &mut HashMap<String, StructFieldValue>)> {
        match self.struct_field_by_scope_mut(scope_id, name, element_index, fields)? {
            StructFieldValue::StructArray {
                type_name,
                elements,
                ..
            } => {
                let len = elements.len();
                elements
                    .get_mut(index)
                    .map(|element| (type_name.clone(), element))
                    .ok_or_else(|| {
                        CustError::new(format!(
                            "struct array field pointer index {index} out of bounds for length {len}"
                        ))
                    })
            }
            _ => Err(CustError::new(format!(
                "struct field '{}' is not a struct array",
                Self::field_path_label(fields)
            ))),
        }
    }

    fn find_struct_pointer_array_field(
        &self,
        pointer: &PointerValue,
        fields: &[String],
    ) -> CustResult<Rc<RefCell<ArrayValue>>> {
        let (type_name, field_map) = self.find_struct_pointer_fields(pointer)?;
        let (_, field_value) = Self::nested_field_value(&type_name, field_map, fields)?;
        match field_value {
            StructFieldValue::Array { value, .. } => Ok(Rc::clone(value)),
            StructFieldValue::Scalar { .. } | StructFieldValue::Pointer { .. } => {
                Err(CustError::new(format!(
                    "struct field '{}' is not an array",
                    Self::field_path_label(fields)
                )))
            }
            StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                "struct field '{}' is a struct '{type_name}'",
                Self::field_path_label(fields)
            ))),
            StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                "struct field '{}' is a struct array",
                Self::field_path_label(fields)
            ))),
        }
    }

    fn struct_pointer_source(
        pointer: &PointerValue,
    ) -> CustResult<Option<(usize, String, Option<usize>)>> {
        match pointer {
            PointerValue::Struct { scope_id, name } => Ok(Some((*scope_id, name.clone(), None))),
            PointerValue::StructElement {
                scope_id,
                name,
                index,
            } => Ok(Some((*scope_id, name.clone(), Some(*index)))),
            PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. } => Ok(None),
            PointerValue::Null => Err(CustError::new("null pointer dereference")),
            _ => Err(CustError::new("pointer does not reference a struct")),
        }
    }

    fn find_struct_pointer_aggregate_array_field_base_pointer(
        &self,
        pointer: &PointerValue,
        fields: &[String],
    ) -> CustResult<Option<PointerValue>> {
        let Some((scope_id, name, element_index)) = Self::struct_pointer_source(pointer)? else {
            let (type_name, field_map) = self.find_struct_pointer_fields(pointer)?;
            return match Self::nested_field_value(&type_name, field_map, fields)?.1 {
                StructFieldValue::StructArray { .. } => {
                    Ok(Some(PointerValue::NestedStructArrayElement {
                        pointer: Box::new(pointer.clone()),
                        fields: fields.to_vec(),
                        index: 0,
                    }))
                }
                _ => Ok(None),
            };
        };
        match self.struct_field_by_scope(scope_id, &name, element_index, fields)? {
            StructFieldValue::StructArray { .. } => Ok(Some(PointerValue::StructFieldElement {
                scope_id,
                name,
                element_index,
                fields: fields.to_vec(),
                index: 0,
            })),
            _ => Ok(None),
        }
    }

    fn find_struct_pointer_aggregate_array_field_pointer(
        &mut self,
        pointer: &PointerValue,
        fields: &[String],
        index: &Expr,
    ) -> CustResult<Option<PointerValue>> {
        let Some((scope_id, name, element_index)) = Self::struct_pointer_source(pointer)? else {
            let (type_name, field_map) = self.find_struct_pointer_fields(pointer)?;
            let len = match Self::nested_field_value(&type_name, field_map, fields)?.1 {
                StructFieldValue::StructArray { elements, .. } => elements.len(),
                _ => return Ok(None),
            };
            let index_value = self.eval(index)?;
            let Ok(index) = usize::try_from(index_value) else {
                return Err(CustError::new(format!(
                    "struct array field '{}' index {index_value} out of bounds for length {len}",
                    Self::field_path_label(fields)
                )));
            };
            if index >= len {
                return Err(CustError::new(format!(
                    "struct array field '{}' index {index_value} out of bounds for length {len}",
                    Self::field_path_label(fields)
                )));
            }
            return Ok(Some(PointerValue::NestedStructArrayElement {
                pointer: Box::new(pointer.clone()),
                fields: fields.to_vec(),
                index,
            }));
        };
        let len = match self.struct_field_by_scope(scope_id, &name, element_index, fields)? {
            StructFieldValue::StructArray { elements, .. } => elements.len(),
            _ => return Ok(None),
        };
        let index_value = self.eval(index)?;
        let Ok(index) = usize::try_from(index_value) else {
            return Err(CustError::new(format!(
                "struct array field '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        };
        if index >= len {
            return Err(CustError::new(format!(
                "struct array field '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        }
        Ok(Some(PointerValue::StructFieldElement {
            scope_id,
            name,
            element_index,
            fields: fields.to_vec(),
            index,
        }))
    }

    fn checked_struct_pointer_array_index(
        &mut self,
        pointer: &PointerValue,
        fields: &[String],
        index: &Expr,
    ) -> CustResult<(Rc<RefCell<ArrayValue>>, usize)> {
        let index_value = self.eval(index)?;
        let array = self.find_struct_pointer_array_field(pointer, fields)?;
        let len = array.borrow().elements.len();
        let Ok(index) = usize::try_from(index_value) else {
            return Err(CustError::new(format!(
                "array '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        };
        if index >= len {
            return Err(CustError::new(format!(
                "array '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        }
        Ok((array, index))
    }

    fn find_struct_pointer_array_field_pointer(
        &mut self,
        pointer: &PointerValue,
        fields: &[String],
        index: &Expr,
    ) -> CustResult<PointerValue> {
        if let Some(pointer) =
            self.find_struct_pointer_aggregate_array_field_pointer(pointer, fields, index)?
        {
            return Ok(pointer);
        }
        let (array, index) = self.checked_struct_pointer_array_index(pointer, fields, index)?;
        Ok(PointerValue::ArrayElement {
            array,
            source_name: Some(Self::field_path_label(fields).to_string()),
            owner: None,
            index,
        })
    }

    fn find_struct_pointer_array_field_base_pointer(
        &self,
        pointer: &PointerValue,
        fields: &[String],
    ) -> CustResult<PointerValue> {
        if let Some(pointer) =
            self.find_struct_pointer_aggregate_array_field_base_pointer(pointer, fields)?
        {
            return Ok(pointer);
        }
        let array = self.find_struct_pointer_array_field(pointer, fields)?;
        let source_name = Some(Self::field_path_label(fields).to_string());
        if array.borrow().dimensions.is_some() {
            return Ok(PointerValue::Array2DRow {
                array,
                source_name,
                row: 0,
                owner: None,
            });
        }
        Ok(PointerValue::ArrayBase {
            array,
            source_name,
            owner: None,
        })
    }

    fn checked_struct_element_index(&mut self, name: &str, index: &Expr) -> CustResult<usize> {
        let index_value = self.eval(index)?;
        let len = match self.find_variable(name) {
            Some(Value::StructArray { elements, .. }) => elements.len(),
            Some(_) => {
                return Err(CustError::new(format!(
                    "variable '{name}' is not a struct array"
                )));
            }
            None => return Err(CustError::new(format!("undefined variable '{name}'"))),
        };
        let Ok(index) = usize::try_from(index_value) else {
            return Err(CustError::new(format!(
                "struct array '{name}' index {index_value} out of bounds for length {len}"
            )));
        };
        if index >= len {
            return Err(CustError::new(format!(
                "struct array '{name}' index {index_value} out of bounds for length {len}"
            )));
        }
        Ok(index)
    }

    fn indexed_struct_pointer(
        &mut self,
        name: &str,
        index: &Expr,
    ) -> CustResult<Option<PointerValue>> {
        if let Some(pointer) = self.scalar_variable_reverse_subscript_pointer(name, index)? {
            return match pointer {
                PointerValue::StructElement { .. }
                | PointerValue::StructFieldElement { .. }
                | PointerValue::NestedStructArrayElement { .. } => Ok(Some(pointer)),
                _ => Err(CustError::new(
                    "subscript pointer does not reference a struct",
                )),
            };
        }
        let Some(Value::Pointer { pointer, ty, .. }) = self.find_variable(name).cloned() else {
            return Ok(None);
        };
        if !matches!(ty, PointeeType::Struct(_)) {
            return Ok(None);
        }
        let index_value = self.eval(index)?;
        let pointer = self.offset_array_pointer(&pointer, index_value)?;
        match pointer {
            PointerValue::StructElement { .. }
            | PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. } => Ok(Some(pointer)),
            _ => Err(CustError::new("struct pointer is not indexable")),
        }
    }

    fn indexed_struct_pointer_value(
        &mut self,
        name: &str,
        index: &Expr,
    ) -> CustResult<Option<(String, HashMap<String, StructFieldValue>)>> {
        let Some(pointer) = self.indexed_struct_pointer(name, index)? else {
            return Ok(None);
        };
        let (type_name, fields) = self.find_struct_pointer_fields(&pointer)?;
        Ok(Some((
            type_name,
            StructFieldValue::deep_clone_fields(fields),
        )))
    }

    fn find_variable_scope_id(&self, name: &str) -> Option<usize> {
        for scope in self.scopes.iter().rev() {
            if scope.values.contains_key(name) {
                return Some(scope.id);
            }
            if let Some(storage) = scope
                .static_local_ids
                .get(name)
                .and_then(|id| self.static_locals.get(id))
            {
                return Some(storage.scope_id);
            }
        }
        None
    }

    fn find_struct_element_pointer(
        &mut self,
        name: &str,
        index: &Expr,
    ) -> CustResult<PointerValue> {
        let index = self.checked_struct_element_index(name, index)?;
        let scope_id = self
            .find_variable_scope_id(name)
            .ok_or_else(|| CustError::new(format!("undefined variable '{name}'")))?;
        Ok(PointerValue::StructElement {
            scope_id,
            name: name.to_string(),
            index,
        })
    }

    fn indexed_struct_element_pointer(
        &mut self,
        name: &str,
        index: &Expr,
    ) -> CustResult<PointerValue> {
        match self.indexed_struct_pointer(name, index)? {
            Some(pointer) => Ok(pointer),
            None => self.find_struct_element_pointer(name, index),
        }
    }

    fn find_struct_element_assignment_pointer(
        &mut self,
        name: &str,
        index: &Expr,
    ) -> CustResult<PointerValue> {
        if matches!(self.find_variable(name), Some(Value::Pointer { .. })) {
            if self.pointer_variable_points_to_const(name) {
                return Err(CustError::new("cannot assign through pointer to const"));
            }
            return self.indexed_struct_pointer(name, index)?.ok_or_else(|| {
                CustError::new(format!("variable '{name}' is not a struct pointer"))
            });
        }
        self.ensure_variable_mutable(name)?;
        self.find_struct_element_pointer(name, index)
    }

    fn struct_field_points_to_const(
        &self,
        scope_id: usize,
        name: &str,
        element_index: Option<usize>,
        path: &[String],
    ) -> CustResult<bool> {
        let root_is_const = self
            .scopes
            .iter()
            .find(|scope| scope.id == scope_id)
            .is_some_and(|scope| scope.const_variables.contains(name))
            || self.static_locals.values().any(|storage| {
                storage.scope_id == scope_id && storage.name == name && storage.is_const
            });
        let field_is_const =
            match self.struct_field_by_scope(scope_id, name, element_index, path)? {
                StructFieldValue::Scalar { is_const, .. }
                | StructFieldValue::Array { is_const, .. }
                | StructFieldValue::Struct { is_const, .. }
                | StructFieldValue::StructArray { is_const, .. }
                | StructFieldValue::Pointer { is_const, .. } => *is_const,
            };
        Ok(root_is_const || field_is_const)
    }

    fn find_struct_field_pointer(
        &mut self,
        name: &str,
        fields: &[String],
    ) -> CustResult<PointerValue> {
        let scope_id = self
            .find_variable_scope_id(name)
            .ok_or_else(|| CustError::new(format!("undefined variable '{name}'")))?;
        match self.struct_field_by_scope(scope_id, name, None, fields)? {
            StructFieldValue::Scalar { .. } => Ok(PointerValue::StructField {
                scope_id,
                name: name.to_string(),
                element_index: None,
                fields: fields.to_vec(),
            }),
            StructFieldValue::Array { value, .. } => Ok(PointerValue::ArrayBase {
                array: Rc::clone(value),
                source_name: Some(Self::field_path_label(fields).to_string()),
                owner: None,
            }),
            StructFieldValue::Struct { .. } => Err(CustError::new(format!(
                "struct field '{}' requires field access",
                Self::field_path_label(fields)
            ))),
            StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                "struct field '{}' requires indexed field access",
                Self::field_path_label(fields)
            ))),
            StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                "pointer field '{}' cannot be addressed in this pointer milestone",
                Self::field_path_label(fields)
            ))),
        }
    }

    fn find_struct_element_field_pointer(
        &mut self,
        name: &str,
        index: &Expr,
        fields: &[String],
    ) -> CustResult<PointerValue> {
        if let Some(pointer) = self.indexed_struct_pointer(name, index)? {
            return self.find_struct_pointer_field_pointer(&pointer, fields);
        }
        let index = self.checked_struct_element_index(name, index)?;
        let scope_id = self
            .find_variable_scope_id(name)
            .ok_or_else(|| CustError::new(format!("undefined variable '{name}'")))?;
        match self.struct_field_by_scope(scope_id, name, Some(index), fields)? {
            StructFieldValue::Scalar { .. } | StructFieldValue::Struct { .. } => {
                Ok(PointerValue::StructField {
                    scope_id,
                    name: name.to_string(),
                    element_index: Some(index),
                    fields: fields.to_vec(),
                })
            }
            StructFieldValue::Array { value, .. } => Ok(PointerValue::ArrayBase {
                array: Rc::clone(value),
                source_name: Some(Self::field_path_label(fields).to_string()),
                owner: None,
            }),
            StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                "struct field '{}' requires indexed field access",
                Self::field_path_label(fields)
            ))),
            StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                "pointer field '{}' cannot be addressed in this pointer milestone",
                Self::field_path_label(fields)
            ))),
        }
    }

    fn append_field_path(base: &[String], suffix: &[String]) -> Vec<String> {
        base.iter()
            .chain(suffix.iter())
            .cloned()
            .collect::<Vec<_>>()
    }

    fn find_struct_pointer_field_pointer(
        &mut self,
        pointer: &PointerValue,
        fields: &[String],
    ) -> CustResult<PointerValue> {
        let (scope_id, name, element_index, field_path) = match pointer {
            PointerValue::Struct { scope_id, name } => {
                (*scope_id, name.clone(), None, fields.to_vec())
            }
            PointerValue::StructElement {
                scope_id,
                name,
                index,
            } => (*scope_id, name.clone(), Some(*index), fields.to_vec()),
            PointerValue::StructField {
                scope_id,
                name,
                element_index,
                fields: base_fields,
            } => (
                *scope_id,
                name.clone(),
                *element_index,
                Self::append_field_path(base_fields, fields),
            ),
            PointerValue::StructFieldElement {
                scope_id,
                name,
                element_index,
                fields: array_fields,
                index,
            } => {
                let (type_name, element_fields) = self.struct_field_array_element_fields(
                    *scope_id,
                    name,
                    *element_index,
                    array_fields,
                    *index,
                )?;
                match Self::nested_field_value(&type_name, element_fields, fields)?.1 {
                    StructFieldValue::Scalar { .. } | StructFieldValue::Struct { .. } => {
                        return Ok(PointerValue::StructFieldElementField {
                            scope_id: *scope_id,
                            name: name.clone(),
                            element_index: *element_index,
                            array_fields: array_fields.clone(),
                            index: *index,
                            fields: fields.to_vec(),
                        });
                    }
                    StructFieldValue::Array { value, .. } => {
                        return Ok(PointerValue::ArrayBase {
                            array: Rc::clone(value),
                            source_name: Some(Self::field_path_label(fields).to_string()),
                            owner: None,
                        });
                    }
                    StructFieldValue::StructArray { .. } => {
                        return Err(CustError::new(format!(
                            "struct field '{}' requires indexed field access",
                            Self::field_path_label(fields)
                        )));
                    }
                    StructFieldValue::Pointer { .. } => {
                        return Err(CustError::new(format!(
                            "pointer field '{}' cannot be addressed in this pointer milestone",
                            Self::field_path_label(fields)
                        )));
                    }
                }
            }
            PointerValue::Null => return Err(CustError::new("null pointer dereference")),
            _ => return Err(CustError::new("pointer does not reference a struct")),
        };

        match self.struct_field_by_scope(scope_id, &name, element_index, &field_path)? {
            StructFieldValue::Scalar { .. } | StructFieldValue::Struct { .. } => {
                Ok(PointerValue::StructField {
                    scope_id,
                    name,
                    element_index,
                    fields: field_path,
                })
            }
            StructFieldValue::Array { value, .. } => Ok(PointerValue::ArrayBase {
                array: Rc::clone(value),
                source_name: Some(Self::field_path_label(&field_path).to_string()),
                owner: None,
            }),
            StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                "struct field '{}' requires indexed field access",
                Self::field_path_label(&field_path)
            ))),
            StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                "pointer field '{}' cannot be addressed in this pointer milestone",
                Self::field_path_label(&field_path)
            ))),
        }
    }

    fn struct_field_by_scope(
        &self,
        scope_id: usize,
        name: &str,
        element_index: Option<usize>,
        path: &[String],
    ) -> CustResult<&StructFieldValue> {
        if !self.live_scope_ids.contains(&scope_id) {
            return Err(CustError::new(format!(
                "pointer to out-of-scope variable '{name}'"
            )));
        }
        let value = self
            .scopes
            .iter()
            .find(|scope| scope.id == scope_id)
            .and_then(|scope| scope.values.get(name))
            .or_else(|| self.static_value_by_scope(scope_id, name));
        match (value, element_index) {
            (Some(Value::Struct { type_name, fields }), None) => {
                Self::nested_field_value(type_name, fields, path).map(|(_, field)| field)
            }
            (
                Some(Value::StructArray {
                    type_name,
                    elements,
                    ..
                }),
                Some(index),
            ) => {
                Self::nested_field_value(type_name, &elements[index], path).map(|(_, field)| field)
            }
            _ => Err(CustError::new(format!(
                "pointer to out-of-scope variable '{name}'"
            ))),
        }
    }

    fn struct_field_by_scope_mut(
        &mut self,
        scope_id: usize,
        name: &str,
        element_index: Option<usize>,
        path: &[String],
    ) -> CustResult<&mut StructFieldValue> {
        if !self.live_scope_ids.contains(&scope_id) {
            return Err(CustError::new(format!(
                "pointer to out-of-scope variable '{name}'"
            )));
        }
        if let Some(pos) = self.scopes.iter().position(|scope| scope.id == scope_id) {
            let value = self.scopes[pos].values.get_mut(name);
            return match (value, element_index) {
                (Some(Value::Struct { type_name, fields }), None) => {
                    Self::nested_field_value_mut(type_name, fields, path).map(|(_, field)| field)
                }
                (
                    Some(Value::StructArray {
                        type_name,
                        elements,
                        ..
                    }),
                    Some(index),
                ) => Self::nested_field_value_mut(type_name, &mut elements[index], path)
                    .map(|(_, field)| field),
                _ => Err(CustError::new(format!(
                    "pointer to out-of-scope variable '{name}'"
                ))),
            };
        }
        match (
            self.static_value_by_scope_mut(scope_id, name),
            element_index,
        ) {
            (Some(Value::Struct { type_name, fields }), None) => {
                Self::nested_field_value_mut(type_name, fields, path).map(|(_, field)| field)
            }
            (
                Some(Value::StructArray {
                    type_name,
                    elements,
                    ..
                }),
                Some(index),
            ) => Self::nested_field_value_mut(type_name, &mut elements[index], path)
                .map(|(_, field)| field),
            _ => Err(CustError::new(format!(
                "pointer to out-of-scope variable '{name}'"
            ))),
        }
    }

    fn read_struct_field_pointer(
        &self,
        scope_id: usize,
        name: &str,
        element_index: Option<usize>,
        fields: &[String],
    ) -> CustResult<i64> {
        match self.struct_field_by_scope(scope_id, name, element_index, fields)? {
            StructFieldValue::Scalar { value, .. } => Ok(*value),
            _ => Err(CustError::new(format!(
                "struct field '{}' used as non-scalar pointer target",
                Self::field_path_label(fields)
            ))),
        }
    }

    fn assign_struct_field_pointer(
        &mut self,
        scope_id: usize,
        name: &str,
        element_index: Option<usize>,
        fields: &[String],
        value: i64,
    ) -> CustResult<()> {
        if self.struct_field_points_to_const(scope_id, name, element_index, fields)? {
            return Err(CustError::new("cannot assign through pointer to const"));
        }
        match self.struct_field_by_scope_mut(scope_id, name, element_index, fields)? {
            StructFieldValue::Scalar {
                value: slot, ty, ..
            } => {
                *slot = ty.normalize(value);
                Ok(())
            }
            _ => Err(CustError::new(format!(
                "struct field '{}' used as non-scalar pointer target",
                Self::field_path_label(fields)
            ))),
        }
    }

    fn read_struct_field_element_field_pointer(
        &self,
        scope_id: usize,
        name: &str,
        element_index: Option<usize>,
        array_fields: &[String],
        index: usize,
        fields: &[String],
    ) -> CustResult<i64> {
        let (type_name, element_fields) = self.struct_field_array_element_fields(
            scope_id,
            name,
            element_index,
            array_fields,
            index,
        )?;
        match Self::nested_field_value(&type_name, element_fields, fields)?.1 {
            StructFieldValue::Scalar { value, .. } => Ok(*value),
            _ => Err(CustError::new(format!(
                "struct field '{}' used as non-scalar pointer target",
                Self::field_path_label(fields)
            ))),
        }
    }

    fn assign_struct_field_element_field_pointer(
        &mut self,
        pointer: &PointerValue,
        value: i64,
    ) -> CustResult<()> {
        let PointerValue::StructFieldElementField {
            scope_id,
            name,
            element_index,
            array_fields,
            index,
            fields,
        } = pointer
        else {
            return Err(CustError::new(
                "pointer does not reference an embedded struct field",
            ));
        };
        if self.struct_field_points_to_const(*scope_id, name, *element_index, array_fields)? {
            return Err(CustError::new("cannot assign through pointer to const"));
        }
        let (type_name, element_fields) = self.struct_field_array_element_fields_mut(
            *scope_id,
            name,
            *element_index,
            array_fields,
            *index,
        )?;
        match Self::nested_field_value_mut(&type_name, element_fields, fields)?.1 {
            StructFieldValue::Scalar {
                value: slot,
                ty,
                is_const,
            } => {
                if *is_const {
                    return Err(CustError::new("cannot assign through pointer to const"));
                }
                *slot = ty.normalize(value);
                Ok(())
            }
            _ => Err(CustError::new(format!(
                "struct field '{}' used as non-scalar pointer target",
                Self::field_path_label(fields)
            ))),
        }
    }

    fn read_struct_element_field(
        &mut self,
        name: &str,
        index: &Expr,
        path: &[String],
    ) -> CustResult<i64> {
        if let Some(pointer) = self.indexed_struct_pointer(name, index)? {
            return self.read_struct_pointer_field(&pointer, path);
        }
        let index = self.checked_struct_element_index(name, index)?;
        match self.find_variable(name) {
            Some(Value::StructArray {
                type_name,
                elements,
                ..
            }) => {
                let (_, field_value) = Self::nested_field_value(type_name, &elements[index], path)?;
                match field_value {
                    StructFieldValue::Scalar { value, .. } => Ok(*value),
                    StructFieldValue::Array { .. } => Err(CustError::new(format!(
                        "struct field '{}' is an array",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct '{type_name}'",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct array",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                        "pointer field '{}' used as scalar",
                        Self::field_path_label(path)
                    ))),
                }
            }
            Some(_) => Err(CustError::new(format!(
                "variable '{name}' is not a struct array"
            ))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn assign_struct_element_field(
        &mut self,
        name: &str,
        index: &Expr,
        path: &[String],
        value: i64,
    ) -> CustResult<()> {
        if let Some(pointer) = self.indexed_struct_pointer(name, index)? {
            if matches!(self.find_variable(name), Some(Value::Scalar { .. })) {
                let direct_const_array = match index {
                    Expr::Var(pointer_name)
                        if matches!(
                            self.find_variable(pointer_name),
                            Some(Value::StructArray {
                                read_only: true,
                                ..
                            })
                        ) =>
                    {
                        Some(pointer_name)
                    }
                    _ => None,
                };
                if let Some(pointer_name) = direct_const_array {
                    return Err(CustError::new(format!(
                        "cannot assign to const variable '{pointer_name}'"
                    )));
                }
                if self.pointer_expr_points_to_const(index) {
                    return Err(CustError::new("cannot assign through pointer to const"));
                }
            } else if self.pointer_variable_points_to_const(name) {
                return Err(CustError::new("cannot assign through pointer to const"));
            }
            return self.assign_struct_pointer_field(&pointer, path, value);
        }
        self.ensure_variable_mutable(name)?;
        let index = self.checked_struct_element_index(name, index)?;
        let struct_types = self.struct_types.clone();
        match self.find_variable_mut(name) {
            Some(Value::StructArray {
                type_name,
                elements,
                read_only,
            }) => {
                if *read_only {
                    return Err(CustError::new(format!(
                        "cannot assign to const variable '{name}'"
                    )));
                }
                Self::assign_scalar_field_in_map(
                    &struct_types,
                    type_name,
                    &mut elements[index],
                    path,
                    value,
                )
            }
            Some(_) => Err(CustError::new(format!(
                "variable '{name}' is not a struct array"
            ))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn find_struct_element_array_field(
        &mut self,
        name: &str,
        index: &Expr,
        path: &[String],
    ) -> CustResult<Rc<RefCell<ArrayValue>>> {
        if let Some(pointer) = self.indexed_struct_pointer(name, index)? {
            let (type_name, fields) = self.find_struct_pointer_fields(&pointer)?;
            let (_, field_value) = Self::nested_field_value(&type_name, fields, path)?;
            return match field_value {
                StructFieldValue::Array { value, .. } => Ok(Rc::clone(value)),
                _ => Err(CustError::new(format!(
                    "struct field '{}' is not an array",
                    Self::field_path_label(path)
                ))),
            };
        }
        let index = self.checked_struct_element_index(name, index)?;
        match self.find_variable(name) {
            Some(Value::StructArray {
                type_name,
                elements,
                ..
            }) => {
                let (_, field_value) = Self::nested_field_value(type_name, &elements[index], path)?;
                match field_value {
                    StructFieldValue::Array { value, .. } => Ok(Rc::clone(value)),
                    _ => Err(CustError::new(format!(
                        "struct field '{}' is not an array",
                        Self::field_path_label(path)
                    ))),
                }
            }
            Some(_) => Err(CustError::new(format!(
                "variable '{name}' is not a struct array"
            ))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn ensure_struct_element_array_field_mutable(
        &self,
        name: &str,
        path: &[String],
    ) -> CustResult<()> {
        match self.find_variable(name) {
            Some(Value::Pointer {
                ty: PointeeType::Struct(type_name),
                points_to_const,
                ..
            }) if *points_to_const
                || self
                    .const_aggregate_field_label_for_path(type_name, path)
                    .is_some() =>
            {
                Err(CustError::new("cannot assign through pointer to const"))
            }
            _ => Ok(()),
        }
    }

    fn checked_struct_element_array_index(
        &mut self,
        name: &str,
        index: &Expr,
        fields: &[String],
        array_index: &Expr,
    ) -> CustResult<(Rc<RefCell<ArrayValue>>, usize)> {
        let array = self.find_struct_element_array_field(name, index, fields)?;
        let index_value = self.eval(array_index)?;
        let len = array.borrow().elements.len();
        let Ok(index) = usize::try_from(index_value) else {
            return Err(CustError::new(format!(
                "array '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        };
        if index >= len {
            return Err(CustError::new(format!(
                "array '{}' index {index_value} out of bounds for length {len}",
                Self::field_path_label(fields)
            )));
        }
        Ok((array, index))
    }

    fn eval_struct_array_set(
        &mut self,
        name: &str,
        fields: &[String],
        index: &Expr,
        value: &Expr,
    ) -> CustResult<i64> {
        if let Some(pointer) = self.scalar_field_reverse_subscript_pointer(name, fields, index)? {
            self.ensure_reverse_subscript_pointee_mutable(index)?;
            let value = self.eval(value)?;
            self.assign_deref_pointer(&pointer, value)?;
            return Ok(value);
        }
        self.ensure_variable_mutable(name)?;
        let (array, index) = self.checked_struct_array_index(name, fields, index)?;
        let elem_type = array.borrow().elem_type;
        let value = self.eval_scalar_conversion(elem_type, value)?;
        let mut array = array.borrow_mut();
        if array.read_only {
            return Err(CustError::new(format!(
                "cannot modify read-only array '{}'",
                Self::field_path_label(fields)
            )));
        }
        array.elements[index] = value;
        Ok(value)
    }

    fn eval_struct_array_compound_set(
        &mut self,
        name: &str,
        fields: &[String],
        index: &Expr,
        op: CompoundOp,
        value: &Expr,
    ) -> CustResult<i64> {
        if let Some(pointer) = self.scalar_field_reverse_subscript_pointer(name, fields, index)? {
            self.ensure_reverse_subscript_pointee_mutable(index)?;
            let current = self.deref_pointer(&pointer)?;
            let rhs = self.eval(value)?;
            let result = Self::apply_compound_op(current, op, rhs)?;
            self.assign_deref_pointer(&pointer, result)?;
            return Ok(result);
        }
        self.ensure_variable_mutable(name)?;
        let (array, index) = self.checked_struct_array_index(name, fields, index)?;
        let current = array.borrow().elements[index];
        let rhs = self.eval(value)?;
        let elem_type = array.borrow().elem_type;
        let result = elem_type.normalize(Self::apply_compound_op(current, op, rhs)?);
        let mut array = array.borrow_mut();
        if array.read_only {
            return Err(CustError::new(format!(
                "cannot modify read-only array '{}'",
                Self::field_path_label(fields)
            )));
        }
        array.elements[index] = result;
        Ok(result)
    }

    fn static_value_by_scope(&self, scope_id: usize, name: &str) -> Option<&Value> {
        self.static_locals.values().find_map(|storage| {
            (storage.scope_id == scope_id && storage.name == name).then_some(&storage.value)
        })
    }

    fn static_value_by_scope_mut(&mut self, scope_id: usize, name: &str) -> Option<&mut Value> {
        self.static_locals.values_mut().find_map(|storage| {
            (storage.scope_id == scope_id && storage.name == name).then_some(&mut storage.value)
        })
    }

    fn find_struct_pointer_fields(
        &self,
        pointer: &PointerValue,
    ) -> CustResult<(String, &HashMap<String, StructFieldValue>)> {
        match pointer {
            PointerValue::Null => Err(CustError::new("null pointer dereference")),
            PointerValue::Struct { scope_id, name } => {
                if !self.live_scope_ids.contains(scope_id) {
                    return Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    )));
                }
                let value = self
                    .scopes
                    .iter()
                    .find(|scope| scope.id == *scope_id)
                    .and_then(|scope| scope.values.get(name))
                    .or_else(|| self.static_value_by_scope(*scope_id, name));
                match value {
                    Some(Value::Struct { type_name, fields }) => Ok((type_name.clone(), fields)),
                    _ => Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    ))),
                }
            }
            PointerValue::StructElement {
                scope_id,
                name,
                index,
            } => {
                if !self.live_scope_ids.contains(scope_id) {
                    return Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    )));
                }
                let value = self
                    .scopes
                    .iter()
                    .find(|scope| scope.id == *scope_id)
                    .and_then(|scope| scope.values.get(name))
                    .or_else(|| self.static_value_by_scope(*scope_id, name));
                match value {
                    Some(Value::StructArray {
                        type_name,
                        elements,
                        ..
                    }) => Ok((type_name.clone(), &elements[*index])),
                    _ => Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    ))),
                }
            }
            PointerValue::StructFieldElement {
                scope_id,
                name,
                element_index,
                fields,
                index,
            } => self.struct_field_array_element_fields(
                *scope_id,
                name,
                *element_index,
                fields,
                *index,
            ),
            PointerValue::NestedStructArrayElement {
                pointer,
                fields,
                index,
            } => {
                let (_, field_map) = self.find_struct_pointer_fields(pointer)?;
                match Self::nested_field_value("", field_map, fields)?.1 {
                    StructFieldValue::StructArray {
                        type_name,
                        elements,
                        ..
                    } => Ok((type_name.clone(), &elements[*index])),
                    _ => Err(CustError::new("pointer does not reference a struct array")),
                }
            }
            PointerValue::StructField {
                scope_id,
                name,
                element_index,
                fields,
            } => match self.struct_field_by_scope(*scope_id, name, *element_index, fields)? {
                StructFieldValue::Struct {
                    type_name, fields, ..
                } => Ok((type_name.clone(), fields)),
                _ => Err(CustError::new("pointer does not reference a struct")),
            },
            PointerValue::StructFieldElementField {
                scope_id,
                name,
                element_index,
                array_fields,
                index,
                fields,
            } => {
                let (element_type_name, element_fields) = self.struct_field_array_element_fields(
                    *scope_id,
                    name,
                    *element_index,
                    array_fields,
                    *index,
                )?;
                Self::nested_struct_field(&element_type_name, element_fields, fields)
            }
            _ => Err(CustError::new("pointer does not reference a struct")),
        }
    }

    fn find_struct_pointer_fields_mut(
        &mut self,
        pointer: &PointerValue,
    ) -> CustResult<(String, &mut HashMap<String, StructFieldValue>)> {
        match pointer {
            PointerValue::Null => Err(CustError::new("null pointer dereference")),
            PointerValue::Struct { scope_id, name } => {
                if !self.live_scope_ids.contains(scope_id) {
                    return Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    )));
                }
                if let Some(pos) = self.scopes.iter().position(|scope| scope.id == *scope_id) {
                    return match self.scopes[pos].values.get_mut(name) {
                        Some(Value::Struct { type_name, fields }) => {
                            Ok((type_name.clone(), fields))
                        }
                        _ => Err(CustError::new(format!(
                            "pointer to out-of-scope variable '{name}'"
                        ))),
                    };
                }
                match self.static_value_by_scope_mut(*scope_id, name) {
                    Some(Value::Struct { type_name, fields }) => Ok((type_name.clone(), fields)),
                    _ => Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    ))),
                }
            }
            PointerValue::StructElement {
                scope_id,
                name,
                index,
            } => {
                if !self.live_scope_ids.contains(scope_id) {
                    return Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    )));
                }
                if let Some(pos) = self.scopes.iter().position(|scope| scope.id == *scope_id) {
                    return match self.scopes[pos].values.get_mut(name) {
                        Some(Value::StructArray {
                            type_name,
                            elements,
                            ..
                        }) => Ok((type_name.clone(), &mut elements[*index])),
                        _ => Err(CustError::new(format!(
                            "pointer to out-of-scope variable '{name}'"
                        ))),
                    };
                }
                match self.static_value_by_scope_mut(*scope_id, name) {
                    Some(Value::StructArray {
                        type_name,
                        elements,
                        ..
                    }) => Ok((type_name.clone(), &mut elements[*index])),
                    _ => Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    ))),
                }
            }
            PointerValue::StructFieldElement {
                scope_id,
                name,
                element_index,
                fields,
                index,
            } => self.struct_field_array_element_fields_mut(
                *scope_id,
                name,
                *element_index,
                fields,
                *index,
            ),
            PointerValue::NestedStructArrayElement {
                pointer,
                fields,
                index,
            } => {
                let (_, field_map) = self.find_struct_pointer_fields_mut(pointer)?;
                match Self::nested_field_value_mut("", field_map, fields)?.1 {
                    StructFieldValue::StructArray {
                        type_name,
                        elements,
                        ..
                    } => Ok((type_name.clone(), &mut elements[*index])),
                    _ => Err(CustError::new("pointer does not reference a struct array")),
                }
            }
            PointerValue::StructField {
                scope_id,
                name,
                element_index,
                fields,
            } => match self.struct_field_by_scope_mut(*scope_id, name, *element_index, fields)? {
                StructFieldValue::Struct {
                    type_name, fields, ..
                } => Ok((type_name.clone(), fields)),
                _ => Err(CustError::new("pointer does not reference a struct")),
            },
            PointerValue::StructFieldElementField {
                scope_id,
                name,
                element_index,
                array_fields,
                index,
                fields,
            } => {
                let (element_type_name, element_fields) = self
                    .struct_field_array_element_fields_mut(
                        *scope_id,
                        name,
                        *element_index,
                        array_fields,
                        *index,
                    )?;
                Self::nested_struct_field_mut(&element_type_name, element_fields, fields)
            }
            _ => Err(CustError::new("pointer does not reference a struct")),
        }
    }

    fn read_struct_pointer_field(
        &self,
        pointer: &PointerValue,
        path: &[String],
    ) -> CustResult<i64> {
        let (type_name, fields) = self.find_struct_pointer_fields(pointer)?;
        let (_, field_value) = Self::nested_field_value(&type_name, fields, path)?;
        match field_value {
            StructFieldValue::Scalar { value, .. } => Ok(*value),
            StructFieldValue::Array { .. } => Err(CustError::new(format!(
                "struct field '{}' is an array",
                Self::field_path_label(path)
            ))),
            StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                "struct field '{}' is a struct '{type_name}'",
                Self::field_path_label(path)
            ))),
            StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                "struct field '{}' is a struct array",
                Self::field_path_label(path)
            ))),
            StructFieldValue::Pointer { .. } => Err(CustError::new(format!(
                "pointer field '{}' used as scalar",
                Self::field_path_label(path)
            ))),
        }
    }

    fn read_struct_pointer_pointer_field(
        &self,
        pointer: &PointerValue,
        path: &[String],
    ) -> CustResult<PointerValue> {
        let (type_name, fields) = self.find_struct_pointer_fields(pointer)?;
        let (_, field_value) = Self::nested_field_value(&type_name, fields, path)?;
        match field_value {
            StructFieldValue::Pointer { pointer, .. } => Ok(pointer.clone()),
            StructFieldValue::Scalar { .. } => Err(CustError::new(format!(
                "struct field '{}' is not a pointer",
                Self::field_path_label(path)
            ))),
            StructFieldValue::Array { .. } => Err(CustError::new(format!(
                "struct field '{}' is an array",
                Self::field_path_label(path)
            ))),
            StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                "struct field '{}' is a struct '{type_name}'",
                Self::field_path_label(path)
            ))),
            StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                "struct field '{}' is a struct array",
                Self::field_path_label(path)
            ))),
        }
    }

    fn struct_pointer_pointer_field_index_pointer(
        &mut self,
        pointer: &PointerValue,
        path: &[String],
        index: &Expr,
    ) -> CustResult<PointerValue> {
        let field_pointer = self.read_struct_pointer_pointer_field(pointer, path)?;
        let index_value = self.eval(index)?;
        if matches!(
            self.struct_pointer_pointer_field_type(pointer, path)?,
            Some(PointeeType::Struct(_))
        ) {
            return self.offset_array_pointer(&field_pointer, index_value);
        }
        let (array, source_name, index, owner) =
            self.checked_pointer_value_index(&field_pointer, index_value)?;
        Ok(PointerValue::ArrayElement {
            array,
            source_name,
            index,
            owner,
        })
    }

    fn struct_pointer_pointer_field_points_to_const(
        &self,
        pointer: &PointerValue,
        path: &[String],
    ) -> CustResult<bool> {
        let (type_name, fields) = self.find_struct_pointer_fields(pointer)?;
        let (_, field_value) = Self::nested_field_value(&type_name, fields, path)?;
        match field_value {
            StructFieldValue::Pointer {
                points_to_const, ..
            } => Ok(*points_to_const),
            _ => Ok(false),
        }
    }

    fn struct_pointer_pointer_field_type(
        &self,
        pointer: &PointerValue,
        path: &[String],
    ) -> CustResult<Option<PointeeType>> {
        let (type_name, fields) = self.find_struct_pointer_fields(pointer)?;
        let (_, field_value) = Self::nested_field_value(&type_name, fields, path)?;
        match field_value {
            StructFieldValue::Pointer { ty, .. } => Ok(Some(ty.clone())),
            _ => Ok(None),
        }
    }

    fn assign_struct_pointer_pointer_field(
        &mut self,
        pointer: &PointerValue,
        path: &[String],
        value: PointerValue,
    ) -> CustResult<()> {
        self.ensure_struct_pointer_target_mutable(pointer)?;
        let value = self.attach_array_pointer_owner(value);
        if let Some(expected) = self.struct_pointer_pointer_field_type(pointer, path)? {
            self.ensure_pointer_type_matches(&expected, &value)?;
        }
        let (type_name, fields) = self.find_struct_pointer_fields_mut(pointer)?;
        let (_, field_value) = Self::nested_field_value_mut(&type_name, fields, path)?;
        if field_value.is_const() {
            return Err(CustError::new(format!(
                "cannot assign to const struct field '{}'",
                Self::field_path_label(path)
            )));
        }
        match field_value {
            StructFieldValue::Pointer { pointer, .. } => {
                *pointer = value;
                Ok(())
            }
            StructFieldValue::Scalar { .. } => Err(CustError::new(format!(
                "struct field '{}' is not a pointer",
                Self::field_path_label(path)
            ))),
            StructFieldValue::Array { .. } => Err(CustError::new(format!(
                "struct field '{}' is an array",
                Self::field_path_label(path)
            ))),
            StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                "struct field '{}' is a struct '{type_name}'",
                Self::field_path_label(path)
            ))),
            StructFieldValue::StructArray { .. } => Err(CustError::new(format!(
                "struct field '{}' is a struct array",
                Self::field_path_label(path)
            ))),
        }
    }

    fn offset_struct_pointer_pointer_field(
        &mut self,
        pointer: &PointerValue,
        path: &[String],
        offset: i64,
    ) -> CustResult<(PointerValue, PointerValue)> {
        let current = self.read_struct_pointer_pointer_field(pointer, path)?;
        let updated = self.offset_array_pointer(&current, offset)?;
        self.assign_struct_pointer_pointer_field(pointer, path, updated.clone())?;
        Ok((current, updated))
    }

    fn assign_struct_pointer_field(
        &mut self,
        pointer: &PointerValue,
        path: &[String],
        value: i64,
    ) -> CustResult<()> {
        self.ensure_struct_pointer_target_mutable(pointer)?;
        let struct_types = self.struct_types.clone();
        let (type_name, fields) = self.find_struct_pointer_fields_mut(pointer)?;
        Self::assign_scalar_field_in_map(&struct_types, &type_name, fields, path, value)
    }

    fn struct_pointer_scalar_field_type(
        &self,
        pointer: &PointerValue,
        path: &[String],
    ) -> CustResult<Option<CType>> {
        let (type_name, fields) = self.find_struct_pointer_fields(pointer)?;
        let (_, field_value) = Self::nested_field_value(&type_name, fields, path)?;
        match field_value {
            StructFieldValue::Scalar { ty, .. } => Ok(Some(*ty)),
            _ => Ok(None),
        }
    }

    fn eval_struct_ptr_set(
        &mut self,
        pointer: &Expr,
        path: &[String],
        value: &Expr,
    ) -> CustResult<i64> {
        self.ensure_pointer_expr_pointee_mutable(pointer)?;
        let pointer = self.eval_pointer(pointer)?;
        let value = match self.struct_pointer_scalar_field_type(&pointer, path)? {
            Some(ty) => self.eval_scalar_conversion(ty, value)?,
            None => self.eval(value)?,
        };
        self.assign_struct_pointer_field(&pointer, path, value)?;
        self.read_struct_pointer_field(&pointer, path)
    }

    fn eval_struct_ptr_compound_set(
        &mut self,
        pointer: &Expr,
        path: &[String],
        op: CompoundOp,
        value: &Expr,
    ) -> CustResult<i64> {
        self.ensure_pointer_expr_pointee_mutable(pointer)?;
        let pointer = self.eval_pointer(pointer)?;
        let current = self.read_struct_pointer_field(&pointer, path)?;
        let rhs = self.eval(value)?;
        let result = Self::apply_compound_op(current, op, rhs)?;
        self.assign_struct_pointer_field(&pointer, path, result)?;
        self.read_struct_pointer_field(&pointer, path)
    }

    fn assign_struct_copy(&mut self, name: &str, rhs: &Expr) -> CustResult<()> {
        self.eval_struct_assignment_expr(name, rhs).map(|_| ())
    }

    fn eval_struct_assignment_expr(&mut self, name: &str, rhs: &Expr) -> CustResult<ReturnValue> {
        self.ensure_variable_mutable(name)?;
        let (rhs_type, rhs_fields) = match self.eval_struct_expr(rhs)? {
            ReturnValue::Struct { type_name, fields } => (type_name, fields),
            ReturnValue::Scalar(_) | ReturnValue::Pointer { .. } => {
                return Err(CustError::new("struct assignment requires struct value"));
            }
        };

        let struct_types = self.struct_types.clone();
        match self.find_variable_mut(name) {
            Some(Value::Struct { type_name, fields }) if *type_name == rhs_type => {
                if fields.values().any(StructFieldValue::is_const) {
                    return Err(CustError::new(format!(
                        "cannot assign to struct '{type_name}' with const fields"
                    )));
                }
                *fields = StructFieldValue::deep_clone_fields(&rhs_fields);
                Ok(ReturnValue::Struct {
                    type_name: rhs_type,
                    fields: rhs_fields,
                })
            }
            Some(Value::Struct { type_name, .. }) => Err(CustError::new(format!(
                "cannot assign struct '{}' to struct '{}'",
                Self::aggregate_label_from(&struct_types, &rhs_type),
                Self::aggregate_label_from(&struct_types, type_name)
            ))),
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn assign_aggregate_field_in_map(
        struct_types: &HashMap<String, StructTypeDef>,
        root_type_name: &str,
        fields: &mut HashMap<String, StructFieldValue>,
        path: &[String],
        rhs_type: String,
        rhs_fields: HashMap<String, StructFieldValue>,
    ) -> CustResult<ReturnValue> {
        let (_, target) = Self::nested_field_value_mut(root_type_name, fields, path)?;
        match target {
            StructFieldValue::Struct {
                type_name,
                fields,
                is_const,
            } if *type_name == rhs_type => {
                if *is_const {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(path)
                    )));
                }
                if fields.values().any(StructFieldValue::is_const) {
                    return Err(CustError::new(format!(
                        "cannot assign to struct '{type_name}' with const fields"
                    )));
                }
                *fields = StructFieldValue::deep_clone_fields(&rhs_fields);
                Ok(ReturnValue::Struct {
                    type_name: rhs_type,
                    fields: rhs_fields,
                })
            }
            StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                "cannot assign struct '{}' to struct '{}'",
                Self::aggregate_label_from(struct_types, &rhs_type),
                Self::aggregate_label_from(struct_types, type_name)
            ))),
            StructFieldValue::Scalar { .. }
            | StructFieldValue::Array { .. }
            | StructFieldValue::StructArray { .. }
            | StructFieldValue::Pointer { .. } => {
                Err(CustError::new("struct assignment requires struct value"))
            }
        }
    }

    fn eval_struct_field_assignment_expr(
        &mut self,
        name: &str,
        path: &[String],
        rhs: &Expr,
    ) -> CustResult<ReturnValue> {
        self.ensure_variable_mutable(name)?;
        let (rhs_type, rhs_fields) = match self.eval_struct_expr(rhs)? {
            ReturnValue::Struct { type_name, fields } => (type_name, fields),
            ReturnValue::Scalar(_) | ReturnValue::Pointer { .. } => {
                return Err(CustError::new("struct assignment requires struct value"));
            }
        };

        let struct_types = self.struct_types.clone();
        match self.find_variable_mut(name) {
            Some(Value::Struct { type_name, fields }) => Self::assign_aggregate_field_in_map(
                &struct_types,
                type_name,
                fields,
                path,
                rhs_type,
                rhs_fields,
            ),
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn eval_struct_pointer_field_assignment_expr(
        &mut self,
        pointer: &Expr,
        path: &[String],
        rhs: &Expr,
    ) -> CustResult<ReturnValue> {
        self.ensure_pointer_expr_pointee_mutable(pointer)?;
        let pointer = self.eval_pointer(pointer)?;
        self.ensure_struct_pointer_target_mutable(&pointer)?;
        let (rhs_type, rhs_fields) = match self.eval_struct_expr(rhs)? {
            ReturnValue::Struct { type_name, fields } => (type_name, fields),
            ReturnValue::Scalar(_) | ReturnValue::Pointer { .. } => {
                return Err(CustError::new("struct assignment requires struct value"));
            }
        };

        let struct_types = self.struct_types.clone();
        let (target_type, target_fields) = self.find_struct_pointer_fields_mut(&pointer)?;
        Self::assign_aggregate_field_in_map(
            &struct_types,
            &target_type,
            target_fields,
            path,
            rhs_type,
            rhs_fields,
        )
    }

    fn eval_struct_index_assignment_expr(
        &mut self,
        name: &str,
        index: &Expr,
        rhs: &Expr,
    ) -> CustResult<ReturnValue> {
        let (rhs_type, rhs_fields) = match self.eval_struct_expr(rhs)? {
            ReturnValue::Struct { type_name, fields } => (type_name, fields),
            ReturnValue::Scalar(_) | ReturnValue::Pointer { .. } => {
                return Err(CustError::new("struct assignment requires struct value"));
            }
        };

        if matches!(
            self.find_variable(name),
            Some(Value::Pointer {
                ty: PointeeType::Struct(_),
                ..
            })
        ) {
            self.ensure_pointer_variable_pointee_mutable(name)?;
            let Some(pointer) = self.indexed_struct_pointer(name, index)? else {
                return Err(CustError::new(format!(
                    "pointer '{name}' is not a struct pointer"
                )));
            };
            self.ensure_struct_pointer_target_mutable(&pointer)?;
            let struct_types = self.struct_types.clone();
            let (target_type, target_fields) = self.find_struct_pointer_fields_mut(&pointer)?;
            if target_type != rhs_type {
                return Err(CustError::new(format!(
                    "cannot assign struct '{}' to struct '{}'",
                    Self::aggregate_label_from(&struct_types, &rhs_type),
                    Self::aggregate_label_from(&struct_types, &target_type)
                )));
            }
            if target_fields.values().any(StructFieldValue::is_const) {
                return Err(CustError::new(format!(
                    "cannot assign to struct '{target_type}' with const fields"
                )));
            }
            *target_fields = StructFieldValue::deep_clone_fields(&rhs_fields);
            return Ok(ReturnValue::Struct {
                type_name: rhs_type,
                fields: rhs_fields,
            });
        }

        self.ensure_variable_mutable(name)?;
        let index = self.checked_struct_element_index(name, index)?;
        let struct_types = self.struct_types.clone();
        match self.find_variable_mut(name) {
            Some(Value::StructArray {
                type_name,
                elements,
                read_only,
            }) if *type_name == rhs_type => {
                if *read_only {
                    return Err(CustError::new(format!(
                        "cannot modify read-only struct array '{name}'"
                    )));
                }
                if elements[index].values().any(StructFieldValue::is_const) {
                    return Err(CustError::new(format!(
                        "cannot assign to struct '{type_name}' with const fields"
                    )));
                }
                elements[index] = StructFieldValue::deep_clone_fields(&rhs_fields);
                Ok(ReturnValue::Struct {
                    type_name: rhs_type,
                    fields: rhs_fields,
                })
            }
            Some(Value::StructArray { type_name, .. }) => Err(CustError::new(format!(
                "cannot assign struct '{}' to struct '{}'",
                Self::aggregate_label_from(&struct_types, &rhs_type),
                Self::aggregate_label_from(&struct_types, type_name)
            ))),
            Some(_) => Err(CustError::new(format!(
                "variable '{name}' is not a struct array"
            ))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn eval_struct_field_array_element_assignment_expr(
        &mut self,
        name: &str,
        fields: &[String],
        index: &Expr,
        rhs: &Expr,
    ) -> CustResult<ReturnValue> {
        let (rhs_type, rhs_fields) = match self.eval_struct_expr(rhs)? {
            ReturnValue::Struct { type_name, fields } => (type_name, fields),
            ReturnValue::Scalar(_) | ReturnValue::Pointer { .. } => {
                return Err(CustError::new("struct assignment requires struct value"));
            }
        };

        self.ensure_variable_mutable(name)?;
        let scope_id = self
            .find_variable_scope_id(name)
            .ok_or_else(|| CustError::new(format!("undefined variable '{name}'")))?;
        let index = self.checked_struct_aggregate_array_field_index(name, None, fields, index)?;
        let field_label = Self::field_path_label(fields).to_string();
        let struct_types = self.struct_types.clone();

        match self.struct_field_by_scope(scope_id, name, None, fields)? {
            StructFieldValue::StructArray { is_const, .. } if *is_const => {
                return Err(CustError::new(format!(
                    "cannot assign to const struct field '{field_label}'"
                )));
            }
            StructFieldValue::StructArray { .. } => {}
            _ => {
                return Err(CustError::new(format!(
                    "struct field '{field_label}' is not a struct array"
                )));
            }
        }

        let (target_type, target_fields) =
            self.struct_field_array_element_fields_mut(scope_id, name, None, fields, index)?;
        if target_type != rhs_type {
            return Err(CustError::new(format!(
                "cannot assign struct '{}' to struct '{}'",
                Self::aggregate_label_from(&struct_types, &rhs_type),
                Self::aggregate_label_from(&struct_types, &target_type)
            )));
        }
        if target_fields.values().any(StructFieldValue::is_const) {
            return Err(CustError::new(format!(
                "cannot assign to struct '{target_type}' with const fields"
            )));
        }
        *target_fields = StructFieldValue::deep_clone_fields(&rhs_fields);
        Ok(ReturnValue::Struct {
            type_name: rhs_type,
            fields: rhs_fields,
        })
    }

    fn assign_struct_pointer_copy(&mut self, pointer: &Expr, rhs: &Expr) -> CustResult<()> {
        self.eval_struct_pointer_assignment_expr(pointer, rhs)
            .map(|_| ())
    }

    fn eval_struct_pointer_assignment_expr(
        &mut self,
        pointer: &Expr,
        rhs: &Expr,
    ) -> CustResult<ReturnValue> {
        self.ensure_pointer_expr_pointee_mutable(pointer)?;
        let pointer = self.eval_pointer(pointer)?;
        let (rhs_type, rhs_fields) = match self.eval_struct_expr(rhs)? {
            ReturnValue::Struct { type_name, fields } => (type_name, fields),
            ReturnValue::Scalar(_) | ReturnValue::Pointer { .. } => {
                return Err(CustError::new("struct assignment requires struct value"));
            }
        };

        self.ensure_struct_pointer_target_mutable(&pointer)?;
        let struct_types = self.struct_types.clone();
        let (target_type, target_fields) = self.find_struct_pointer_fields_mut(&pointer)?;
        if target_type != rhs_type {
            return Err(CustError::new(format!(
                "cannot assign struct '{}' to struct '{}'",
                Self::aggregate_label_from(&struct_types, &rhs_type),
                Self::aggregate_label_from(&struct_types, &target_type)
            )));
        }
        if target_fields.values().any(StructFieldValue::is_const) {
            return Err(CustError::new(format!(
                "cannot assign to struct '{target_type}' with const fields"
            )));
        }
        *target_fields = StructFieldValue::deep_clone_fields(&rhs_fields);
        Ok(ReturnValue::Struct {
            type_name: rhs_type,
            fields: rhs_fields,
        })
    }

    fn scalar_array_element_type(&self, name: &str) -> Option<CType> {
        match self.find_variable(name) {
            Some(Value::Array(array)) => Some(array.borrow().elem_type),
            Some(Value::Pointer {
                ty: PointeeType::Scalar(ty),
                ..
            }) => Some(*ty),
            _ => None,
        }
    }

    fn eval_struct_set(&mut self, name: &str, fields: &[String], value: &Expr) -> CustResult<i64> {
        if self.struct_field_is_pointer(name, fields) {
            return Err(CustError::new("pointer value used as scalar"));
        }
        let ty = match self.find_variable(name) {
            Some(Value::Struct { type_name, .. }) => self
                .aggregate_type_field_metadata(type_name, fields)?
                .and_then(|(field_type, _, _)| match field_type {
                    StructFieldType::Scalar(ty) => Some(ty),
                    _ => None,
                }),
            _ => None,
        };
        let value = match ty {
            Some(ty) => self.eval_scalar_conversion(ty, value)?,
            None => self.eval(value)?,
        };
        self.assign_struct_field(name, fields, value)?;
        Ok(value)
    }

    fn eval_struct_compound_set(
        &mut self,
        name: &str,
        fields: &[String],
        op: CompoundOp,
        value: &Expr,
    ) -> CustResult<i64> {
        let current = self.read_struct_field(name, fields)?;
        let rhs = self.eval(value)?;
        let result = Self::apply_compound_op(current, op, rhs)?;
        self.assign_struct_field(name, fields, result)?;
        self.read_struct_field(name, fields)
    }

    fn address_of_scalar(&self, name: &str) -> CustResult<PointerValue> {
        for scope in self.scopes.iter().rev() {
            if let Some(value) = scope.values.get(name) {
                return match value {
                    Value::Scalar { .. } => Ok(PointerValue::Scalar {
                        scope_id: scope.id,
                        name: name.to_string(),
                    }),
                    Value::Array(_) => Err(CustError::new(format!(
                        "array '{name}' requires indexed address-of"
                    ))),
                    Value::Pointer { .. } => Err(CustError::new(format!(
                        "pointer '{name}' cannot be addressed in this pointer milestone"
                    ))),
                    Value::Struct { .. } => Ok(PointerValue::Struct {
                        scope_id: scope.id,
                        name: name.to_string(),
                    }),
                    Value::StructArray { .. } => Err(CustError::new(format!(
                        "struct array '{name}' requires indexed field access"
                    ))),
                };
            }
            if let Some(storage) = scope
                .static_local_ids
                .get(name)
                .and_then(|id| self.static_locals.get(id))
            {
                return match &storage.value {
                    Value::Scalar { .. } => Ok(PointerValue::Scalar {
                        scope_id: storage.scope_id,
                        name: name.to_string(),
                    }),
                    Value::Array(_) => Err(CustError::new(format!(
                        "array '{name}' requires indexed address-of"
                    ))),
                    Value::Pointer { .. } => Err(CustError::new(format!(
                        "pointer '{name}' cannot be addressed in this pointer milestone"
                    ))),
                    Value::Struct { .. } => Ok(PointerValue::Struct {
                        scope_id: storage.scope_id,
                        name: name.to_string(),
                    }),
                    Value::StructArray { .. } => Err(CustError::new(format!(
                        "struct array '{name}' requires indexed field access"
                    ))),
                };
            }
        }
        Err(CustError::new(format!("undefined variable '{name}'")))
    }

    fn eval_pointer(&mut self, expr: &Expr) -> CustResult<PointerValue> {
        match expr {
            Expr::Number(0) => Ok(PointerValue::Null),
            Expr::Deref(pointer) if self.array2d_row_pointer_element_type(pointer).is_some() => {
                let pointer = self.eval_pointer(pointer)?;
                let PointerValue::Array2DRow {
                    array,
                    source_name,
                    row,
                    owner,
                } = pointer
                else {
                    return Err(CustError::new(
                        "pointer does not reference a two-dimensional array row",
                    ));
                };
                self.ensure_array_pointer_owner_live(owner.as_ref())?;
                let columns = array
                    .borrow()
                    .dimensions
                    .map(|(_, columns)| columns)
                    .ok_or_else(|| {
                        CustError::new("pointer does not reference a two-dimensional array row")
                    })?;
                Ok(PointerValue::ArrayElement {
                    array,
                    source_name,
                    index: row * columns,
                    owner,
                })
            }
            Expr::PointerCast { expr, .. } => {
                if self.expr_is_pointer_value(expr) {
                    self.eval_pointer(expr)
                } else if self.eval(expr)? == 0 {
                    Ok(PointerValue::Null)
                } else {
                    Err(CustError::new("expected pointer expression"))
                }
            }
            Expr::Conditional {
                cond,
                then_expr,
                else_expr,
            } => {
                if self.eval_truthy(cond)? {
                    self.eval_pointer(then_expr)
                } else {
                    self.eval_pointer(else_expr)
                }
            }
            Expr::Comma(left, right) => {
                self.eval_discard(left)?;
                self.eval_pointer(right)
            }
            Expr::AddressOf(name) => self.address_of_scalar(name),
            Expr::AddressOfArray { name, index } => {
                if let Some(pointer) =
                    self.scalar_variable_reverse_subscript_pointer(name, index)?
                {
                    Ok(pointer)
                } else if let Some(Value::StructArray { .. }) = self.find_variable(name) {
                    self.find_struct_element_pointer(name, index)
                } else if let Some(pointer) = self.indexed_struct_pointer(name, index)? {
                    Ok(pointer)
                } else if let Some(Value::Pointer { pointer, .. }) =
                    self.find_variable(name).cloned()
                {
                    let index_value = self.eval(index)?;
                    let (array, source_name, index, owner) =
                        self.checked_pointer_value_index(&pointer, index_value)?;
                    Ok(PointerValue::ArrayElement {
                        array,
                        source_name,
                        index,
                        owner,
                    })
                } else {
                    let (array, index) = self.checked_array_index(name, index)?;
                    Ok(PointerValue::ArrayElement {
                        array,
                        source_name: Some(name.clone()),
                        owner: None,
                        index,
                    })
                }
            }
            Expr::AddressOfStructField { name, fields } => {
                self.find_struct_field_pointer(name, fields)
            }
            Expr::AddressOfStructElementField {
                name,
                index,
                fields,
            } => self.find_struct_element_field_pointer(name, index, fields),
            Expr::AddressOfStructArrayField {
                name,
                fields,
                index,
            } => {
                if let Some(pointer) =
                    self.scalar_field_reverse_subscript_pointer(name, fields, index)?
                {
                    Ok(pointer)
                } else {
                    self.find_struct_array_field_pointer(name, fields, index)
                }
            }
            Expr::AddressOfStructElementArrayField {
                name,
                index,
                fields,
                array_index,
            } => {
                let element_pointer = self.indexed_struct_element_pointer(name, index)?;
                if self
                    .struct_pointer_pointer_field_type(&element_pointer, fields)?
                    .is_some()
                {
                    self.struct_pointer_pointer_field_index_pointer(
                        &element_pointer,
                        fields,
                        array_index,
                    )
                } else {
                    self.find_struct_pointer_array_field_pointer(
                        &element_pointer,
                        fields,
                        array_index,
                    )
                }
            }
            Expr::AddressOfStructPtrArrayField {
                pointer,
                fields,
                index,
            } => {
                let pointer = self.eval_pointer(pointer)?;
                if self
                    .struct_pointer_pointer_field_type(&pointer, fields)?
                    .is_some()
                {
                    self.struct_pointer_pointer_field_index_pointer(&pointer, fields, index)
                } else {
                    self.find_struct_pointer_array_field_pointer(&pointer, fields, index)
                }
            }
            Expr::AddressOfStructPtrField { pointer, fields } => {
                let pointer = self.eval_pointer(pointer)?;
                self.find_struct_pointer_field_pointer(&pointer, fields)
            }
            Expr::AddressOfScalarLiteral { ty, init } => {
                self.make_scalar_compound_literal_pointer(*ty, init)
            }
            Expr::AddressOfAggregateLiteral {
                type_name, init, ..
            } => self.make_aggregate_compound_literal_pointer(type_name, init),
            Expr::AddressOfAggregateField { aggregate, fields } => {
                self.make_aggregate_compound_literal_field_pointer(aggregate, fields)
            }
            Expr::StringLiteral(values) => Ok(PointerValue::ArrayBase {
                array: Rc::new(RefCell::new(ArrayValue::read_only(values.clone()))),
                source_name: None,
                owner: None,
            }),
            Expr::ArrayLiteral {
                elem_type,
                len,
                init,
                read_only,
            } => Ok(PointerValue::ArrayBase {
                array: self.make_array_compound_literal(*len, *elem_type, init, *read_only)?,
                source_name: None,
                owner: None,
            }),
            Expr::AggregateArrayLiteral {
                type_name,
                len,
                init,
                read_only,
            } => self.make_aggregate_array_compound_literal(type_name, *len, init, *read_only),
            Expr::AggregateFieldGet { aggregate, fields } => {
                self.eval_aggregate_literal_field_pointer(aggregate, fields)
            }
            Expr::AggregateFieldSet {
                aggregate,
                fields,
                value,
            } => {
                let (_, expected_ty, is_const, points_to_const) =
                    self.eval_aggregate_literal_pointer_field_metadata(aggregate, fields)?;
                if is_const {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(fields)
                    )));
                }
                self.ensure_pointer_conversion_preserves_const(points_to_const, value)?;
                let pointer = self.eval_pointer(value)?;
                self.ensure_pointer_type_matches(&expected_ty, &pointer)?;
                Ok(pointer)
            }
            Expr::AggregateFieldCompoundSet {
                aggregate,
                fields,
                op,
                value,
            } => {
                let (current, _, is_const, _) =
                    self.eval_aggregate_literal_pointer_field_metadata(aggregate, fields)?;
                if is_const {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(fields)
                    )));
                }
                let offset = self.eval(value)?;
                let offset = match op {
                    CompoundOp::Add => offset,
                    CompoundOp::Sub => -offset,
                    CompoundOp::Mul
                    | CompoundOp::Div
                    | CompoundOp::Rem
                    | CompoundOp::BitAnd
                    | CompoundOp::BitOr
                    | CompoundOp::BitXor
                    | CompoundOp::ShiftLeft
                    | CompoundOp::ShiftRight => return Err(Self::pointer_compound_error(*op)),
                };
                self.offset_array_pointer(&current, offset)
            }
            Expr::Call { name, args } => match self.call_function(name, args)? {
                Some(ReturnValue::Pointer { pointer, .. }) => Ok(pointer),
                Some(ReturnValue::Scalar(_)) => Err(CustError::new(format!(
                    "scalar function '{name}' used as pointer expression"
                ))),
                Some(ReturnValue::Struct { .. }) => Err(CustError::new(format!(
                    "struct function '{name}' used as pointer expression"
                ))),
                None => Err(CustError::new(format!(
                    "void function '{name}' used as pointer expression"
                ))),
            },
            Expr::Assign { name, value } => match self.find_variable(name).cloned() {
                Some(Value::Pointer {
                    pointer: current_pointer,
                    ty,
                    points_to_const,
                }) => {
                    self.ensure_variable_mutable(name)?;
                    self.ensure_pointer_conversion_preserves_const(points_to_const, value)?;
                    let pointer = self.eval_pointer(value)?;
                    let pointer = self.attach_array_pointer_owner(pointer);
                    self.ensure_pointer_slot_type_matches(&current_pointer, &ty, &pointer)?;
                    if let Some(Value::Pointer { pointer: slot, .. }) = self.find_variable_mut(name)
                    {
                        *slot = pointer.clone();
                    }
                    Ok(pointer)
                }
                Some(Value::Scalar { .. }) => Err(CustError::new(format!(
                    "variable '{name}' is not a pointer"
                ))),
                Some(Value::Array(_)) => Err(CustError::new(format!(
                    "array '{name}' requires indexed address-of"
                ))),
                Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => Err(
                    CustError::new(format!("struct variable '{name}' used as pointer")),
                ),
                None => Err(CustError::new(format!(
                    "assignment to undeclared variable '{name}'"
                ))),
            },
            Expr::Var(name) => match self.find_variable(name) {
                Some(Value::Pointer { pointer, .. }) => Ok(pointer.clone()),
                Some(Value::Array(array)) if array.borrow().dimensions.is_some() => {
                    Ok(PointerValue::Array2DRow {
                        array: Rc::clone(array),
                        source_name: Some(name.clone()),
                        row: 0,
                        owner: None,
                    })
                }
                Some(Value::Array(array)) => Ok(PointerValue::ArrayBase {
                    array: Rc::clone(array),
                    source_name: Some(name.clone()),
                    owner: None,
                }),
                Some(Value::StructArray { .. }) => {
                    let scope_id = self
                        .find_variable_scope_id(name)
                        .ok_or_else(|| CustError::new(format!("undefined variable '{name}'")))?;
                    Ok(PointerValue::StructElement {
                        scope_id,
                        name: name.clone(),
                        index: 0,
                    })
                }
                Some(Value::Scalar { .. }) => Err(CustError::new(format!(
                    "variable '{name}' is not a pointer"
                ))),
                Some(Value::Struct { .. }) => Err(CustError::new(format!(
                    "struct variable '{name}' used as pointer"
                ))),
                None => Err(CustError::new(format!("undefined variable '{name}'"))),
            },
            Expr::StructGet { name, fields } => {
                match self.find_struct_array_field_base_pointer(name, fields) {
                    Ok(pointer) => Ok(pointer),
                    Err(_) => self.read_direct_struct_pointer_field(name, fields),
                }
            }
            Expr::StructElementGet {
                name,
                index,
                fields,
            } => {
                if matches!(
                    self.struct_element_field_metadata(name, fields)?,
                    Some((StructFieldType::Pointer(_), _, _))
                ) {
                    let element_pointer = self.indexed_struct_element_pointer(name, index)?;
                    self.read_struct_pointer_pointer_field(&element_pointer, fields)
                } else {
                    self.find_struct_element_array_field_base_pointer(name, index, fields)
                        .map_err(|_| {
                            CustError::new(format!(
                                "struct field '{}' is not a pointer",
                                Self::field_path_label(fields)
                            ))
                        })
                }
            }
            Expr::StructElementArrayGet {
                name,
                index,
                fields,
                array_index,
            } => {
                let element_pointer = self.indexed_struct_element_pointer(name, index)?;
                if self
                    .struct_pointer_pointer_field_type(&element_pointer, fields)?
                    .is_some()
                {
                    self.struct_pointer_pointer_field_index_pointer(
                        &element_pointer,
                        fields,
                        array_index,
                    )
                } else {
                    self.find_struct_pointer_array_field_pointer(
                        &element_pointer,
                        fields,
                        array_index,
                    )
                }
            }
            Expr::StructPtrGet { pointer, fields } => {
                let pointer = self.eval_pointer(pointer)?;
                match self.find_struct_pointer_array_field_base_pointer(&pointer, fields) {
                    Ok(pointer) => Ok(pointer),
                    Err(_) => self.read_struct_pointer_pointer_field(&pointer, fields),
                }
            }
            Expr::StructFieldArrayElementGet {
                name,
                array_fields,
                index,
                fields,
            } => {
                let target_pointer =
                    self.struct_field_array_element_pointer(name, array_fields, index)?;
                match self.find_struct_pointer_array_field_base_pointer(&target_pointer, fields) {
                    Ok(pointer) => Ok(pointer),
                    Err(_) => self.read_struct_pointer_pointer_field(&target_pointer, fields),
                }
            }
            Expr::StructPtrArrayGet {
                pointer,
                fields,
                index,
            } => {
                let pointer = self.eval_pointer(pointer)?;
                if self
                    .struct_pointer_pointer_field_type(&pointer, fields)?
                    .is_some()
                {
                    self.struct_pointer_pointer_field_index_pointer(&pointer, fields, index)
                } else {
                    self.find_struct_pointer_array_field_pointer(&pointer, fields, index)
                }
            }
            Expr::StructSet {
                name,
                fields,
                value,
            } => {
                self.ensure_pointer_conversion_preserves_const(
                    self.struct_pointer_field_points_to_const(name, fields),
                    value,
                )?;
                let pointer = self.eval_pointer(value)?;
                self.assign_direct_struct_pointer_field(name, fields, pointer.clone())?;
                Ok(pointer)
            }
            Expr::StructPtrSet {
                pointer,
                fields,
                value,
            } => {
                let target_pointer = self.eval_pointer(pointer)?;
                let target_points_to_const =
                    self.struct_pointer_pointer_field_points_to_const(&target_pointer, fields)?;
                self.ensure_pointer_conversion_preserves_const(target_points_to_const, value)?;
                let value_pointer = self.eval_pointer(value)?;
                self.assign_struct_pointer_pointer_field(
                    &target_pointer,
                    fields,
                    value_pointer.clone(),
                )?;
                Ok(value_pointer)
            }
            Expr::StructFieldArrayElementSet {
                name,
                array_fields,
                index,
                fields,
                value,
            } => {
                let metadata = self.struct_field_array_element_field_metadata(
                    name,
                    array_fields,
                    index,
                    fields,
                )?;
                let Some((StructFieldType::Pointer(_), _, points_to_const)) = metadata else {
                    return Err(CustError::new("expected pointer expression"));
                };
                self.ensure_pointer_conversion_preserves_const(points_to_const, value)?;
                let value_pointer = self.eval_pointer(value)?;
                let target_pointer =
                    self.struct_field_array_element_assignment_pointer(name, array_fields, index)?;
                self.assign_struct_pointer_pointer_field(
                    &target_pointer,
                    fields,
                    value_pointer.clone(),
                )?;
                Ok(value_pointer)
            }
            Expr::StructElementSet {
                name,
                index,
                fields,
                value,
            } => {
                let Some((StructFieldType::Pointer(_), _, points_to_const)) =
                    self.struct_element_field_metadata(name, fields)?
                else {
                    return Err(CustError::new("expected pointer expression"));
                };
                self.ensure_pointer_conversion_preserves_const(points_to_const, value)?;
                let value_pointer = self.eval_pointer(value)?;
                let element_pointer = self.find_struct_element_assignment_pointer(name, index)?;
                self.assign_struct_pointer_pointer_field(
                    &element_pointer,
                    fields,
                    value_pointer.clone(),
                )?;
                Ok(value_pointer)
            }
            Expr::StructElementCompoundSet {
                name,
                index,
                fields,
                op,
                value,
            } => {
                let offset = self.eval(value)?;
                let offset = match op {
                    CompoundOp::Add => offset,
                    CompoundOp::Sub => -offset,
                    CompoundOp::Mul
                    | CompoundOp::Div
                    | CompoundOp::Rem
                    | CompoundOp::BitAnd
                    | CompoundOp::BitOr
                    | CompoundOp::BitXor
                    | CompoundOp::ShiftLeft
                    | CompoundOp::ShiftRight => return Err(Self::pointer_compound_error(*op)),
                };
                let element_pointer = self.find_struct_element_assignment_pointer(name, index)?;
                let (_, updated) =
                    self.offset_struct_pointer_pointer_field(&element_pointer, fields, offset)?;
                Ok(updated)
            }
            Expr::StructFieldArrayElementCompoundSet {
                name,
                array_fields,
                index,
                fields,
                op,
                value,
            } => {
                let offset = self.eval(value)?;
                let offset = match op {
                    CompoundOp::Add => offset,
                    CompoundOp::Sub => -offset,
                    CompoundOp::Mul
                    | CompoundOp::Div
                    | CompoundOp::Rem
                    | CompoundOp::BitAnd
                    | CompoundOp::BitOr
                    | CompoundOp::BitXor
                    | CompoundOp::ShiftLeft
                    | CompoundOp::ShiftRight => return Err(Self::pointer_compound_error(*op)),
                };
                let target_pointer =
                    self.struct_field_array_element_assignment_pointer(name, array_fields, index)?;
                let (_, updated) =
                    self.offset_struct_pointer_pointer_field(&target_pointer, fields, offset)?;
                Ok(updated)
            }
            Expr::StructCompoundSet {
                name,
                fields,
                op,
                value,
            } => self.compound_assign_direct_struct_pointer_field(name, fields, *op, value),
            Expr::StructPtrCompoundSet {
                pointer,
                fields,
                op,
                value,
            } => {
                let offset = self.eval(value)?;
                let offset = match op {
                    CompoundOp::Add => offset,
                    CompoundOp::Sub => -offset,
                    CompoundOp::Mul
                    | CompoundOp::Div
                    | CompoundOp::Rem
                    | CompoundOp::BitAnd
                    | CompoundOp::BitOr
                    | CompoundOp::BitXor
                    | CompoundOp::ShiftLeft
                    | CompoundOp::ShiftRight => return Err(Self::pointer_compound_error(*op)),
                };
                let target_pointer = self.eval_pointer(pointer)?;
                let (_, updated) =
                    self.offset_struct_pointer_pointer_field(&target_pointer, fields, offset)?;
                Ok(updated)
            }
            Expr::CompoundAssign { name, op, value } => {
                let pointer = match self.find_variable(name).cloned() {
                    Some(Value::Pointer { pointer, .. }) => pointer,
                    Some(Value::Scalar { .. }) => {
                        return Err(CustError::new(format!(
                            "variable '{name}' is not a pointer"
                        )));
                    }
                    Some(Value::Array(_)) => {
                        return Err(CustError::new(format!("array '{name}' is not a pointer")));
                    }
                    Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => {
                        return Err(CustError::new(format!(
                            "struct variable '{name}' used as pointer"
                        )));
                    }
                    None => return Err(CustError::new(format!("undefined variable '{name}'"))),
                };
                let offset = self.eval(value)?;
                self.ensure_variable_mutable(name)?;
                let pointer = match op {
                    CompoundOp::Add => self.offset_array_pointer(&pointer, offset)?,
                    CompoundOp::Sub => self.offset_array_pointer(&pointer, -offset)?,
                    CompoundOp::Mul
                    | CompoundOp::Div
                    | CompoundOp::Rem
                    | CompoundOp::BitAnd
                    | CompoundOp::BitOr
                    | CompoundOp::BitXor
                    | CompoundOp::ShiftLeft
                    | CompoundOp::ShiftRight => return Err(Self::pointer_compound_error(*op)),
                };
                if let Some(Value::Pointer { pointer: slot, .. }) = self.find_variable_mut(name) {
                    *slot = pointer.clone();
                }
                Ok(pointer)
            }
            Expr::Increment { target, op, prefix } => match target.as_ref() {
                Expr::StructGet { name, fields } => {
                    self.increment_direct_struct_pointer_field(name, fields, *op, *prefix)
                }
                Expr::StructPtrGet { pointer, fields } => {
                    let target_pointer = self.eval_pointer(pointer)?;
                    let offset = match op {
                        IncrementOp::Inc => 1,
                        IncrementOp::Dec => -1,
                    };
                    let (current, updated) =
                        self.offset_struct_pointer_pointer_field(&target_pointer, fields, offset)?;
                    if *prefix { Ok(updated) } else { Ok(current) }
                }
                Expr::AggregateFieldGet { aggregate, fields } => {
                    let (current, _, is_const, _) =
                        self.eval_aggregate_literal_pointer_field_metadata(aggregate, fields)?;
                    if is_const {
                        return Err(CustError::new(format!(
                            "cannot assign to const struct field '{}'",
                            Self::field_path_label(fields)
                        )));
                    }
                    let offset = match op {
                        IncrementOp::Inc => 1,
                        IncrementOp::Dec => -1,
                    };
                    let updated = self.offset_array_pointer(&current, offset)?;
                    if *prefix { Ok(updated) } else { Ok(current) }
                }
                Expr::StructElementGet {
                    name,
                    index,
                    fields,
                } => {
                    let element_pointer =
                        self.find_struct_element_assignment_pointer(name, index)?;
                    let offset = match op {
                        IncrementOp::Inc => 1,
                        IncrementOp::Dec => -1,
                    };
                    let (current, updated) =
                        self.offset_struct_pointer_pointer_field(&element_pointer, fields, offset)?;
                    if *prefix { Ok(updated) } else { Ok(current) }
                }
                Expr::StructFieldArrayElementGet {
                    name,
                    array_fields,
                    index,
                    fields,
                } => {
                    let target_pointer = self.struct_field_array_element_assignment_pointer(
                        name,
                        array_fields,
                        index,
                    )?;
                    let offset = match op {
                        IncrementOp::Inc => 1,
                        IncrementOp::Dec => -1,
                    };
                    let (current, updated) =
                        self.offset_struct_pointer_pointer_field(&target_pointer, fields, offset)?;
                    if *prefix { Ok(updated) } else { Ok(current) }
                }
                Expr::Var(name) => {
                    let pointer = match self.find_variable(name).cloned() {
                        Some(Value::Pointer { pointer, .. }) => pointer,
                        Some(Value::Scalar { .. }) => {
                            return Err(CustError::new(format!(
                                "variable '{name}' is not a pointer"
                            )));
                        }
                        Some(Value::Array(_)) => {
                            return Err(CustError::new(format!("array '{name}' is not a pointer")));
                        }
                        Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => {
                            return Err(CustError::new(format!(
                                "struct variable '{name}' used as pointer"
                            )));
                        }
                        None => return Err(CustError::new(format!("undefined variable '{name}'"))),
                    };
                    self.ensure_variable_mutable(name)?;
                    let offset = match op {
                        IncrementOp::Inc => 1,
                        IncrementOp::Dec => -1,
                    };
                    let updated = self.offset_array_pointer(&pointer, offset)?;
                    if let Some(Value::Pointer { pointer: slot, .. }) = self.find_variable_mut(name)
                    {
                        *slot = updated.clone();
                    }
                    if *prefix { Ok(updated) } else { Ok(pointer) }
                }
                _ => Err(CustError::new("invalid increment/decrement target")),
            },
            Expr::Binary(left, op @ (BinaryOp::Add | BinaryOp::Sub), right) => {
                self.eval_pointer_arithmetic(left, *op, right)
            }
            _ => Err(CustError::new("expected pointer expression")),
        }
    }

    fn eval_ordering(&mut self, left: &Expr, op: &BinaryOp, right: &Expr) -> CustResult<i64> {
        let left_is_pointer = self.expr_is_pointer_value(left);
        let right_is_pointer = self.expr_is_pointer_value(right);

        match (left_is_pointer, right_is_pointer) {
            (false, false) => {
                let lhs = self.eval(left)?;
                let rhs = self.eval(right)?;
                let result = match op {
                    BinaryOp::Lt => lhs < rhs,
                    BinaryOp::Le => lhs <= rhs,
                    BinaryOp::Gt => lhs > rhs,
                    BinaryOp::Ge => lhs >= rhs,
                    _ => unreachable!("only ordering operators use eval_ordering"),
                };
                Ok(result as i64)
            }
            (true, true) => {
                let left_pointer = self.eval_pointer(left)?;
                let right_pointer = self.eval_pointer(right)?;
                self.pointer_ordering(&left_pointer, *op, &right_pointer)
            }
            (true, false) | (false, true) => Err(CustError::new(
                "pointer ordering comparisons are not supported",
            )),
        }
    }

    fn eval_pointer_arithmetic(
        &mut self,
        left: &Expr,
        op: BinaryOp,
        right: &Expr,
    ) -> CustResult<PointerValue> {
        let left_is_pointer = self.expr_is_pointer_value(left);
        let right_is_pointer = self.expr_is_pointer_value(right);

        match (left_is_pointer, right_is_pointer) {
            (true, false) => {
                let pointer = self.eval_pointer(left)?;
                let offset = self.eval(right)?;
                match op {
                    BinaryOp::Add => self.offset_array_pointer(&pointer, offset),
                    BinaryOp::Sub => self.offset_array_pointer(&pointer, -offset),
                    _ => unreachable!("only pointer add/sub reach pointer arithmetic"),
                }
            }
            (false, true) if op == BinaryOp::Add => {
                let offset = self.eval(left)?;
                let pointer = self.eval_pointer(right)?;
                self.offset_array_pointer(&pointer, offset)
            }
            (true, true) if op == BinaryOp::Add => Err(CustError::new("cannot add two pointers")),
            (true, true) | (false, true) | (false, false) => {
                Err(CustError::new("expected pointer expression"))
            }
        }
    }

    fn offset_array_pointer(
        &self,
        pointer: &PointerValue,
        offset: i64,
    ) -> CustResult<PointerValue> {
        match pointer {
            PointerValue::Null => Err(CustError::new("null pointer arithmetic is not supported")),
            PointerValue::Scalar { .. }
            | PointerValue::Struct { .. }
            | PointerValue::StructField { .. }
            | PointerValue::StructFieldElementField { .. } => {
                Err(CustError::new("scalar pointer arithmetic is not supported"))
            }
            PointerValue::StructElement {
                scope_id,
                name,
                index,
            } => self.struct_array_pointer_at(*scope_id, name, *index as i64 + offset),
            PointerValue::StructFieldElement {
                scope_id,
                name,
                element_index,
                fields,
                index,
            } => self.struct_field_array_pointer_at(
                *scope_id,
                name,
                *element_index,
                fields,
                *index as i64 + offset,
            ),
            PointerValue::NestedStructArrayElement {
                pointer,
                fields,
                index,
            } => self.nested_struct_array_pointer_at(pointer, fields, *index as i64 + offset),
            PointerValue::ArrayBase {
                array,
                source_name,
                owner,
            } => self.array_pointer_at(array, source_name.clone(), owner.clone(), offset),
            PointerValue::ArrayElement {
                array,
                source_name,
                index,
                owner,
            } => {
                let next_index = (*index as i64).checked_add(offset).ok_or_else(|| {
                    CustError::new("array pointer index overflow during pointer arithmetic")
                })?;
                if let Some((_, columns)) = array.borrow().dimensions {
                    let row = *index / columns;
                    let row_start = row * columns;
                    let row_end = row_start + columns;
                    if next_index < row_start as i64 || next_index >= row_end as i64 {
                        return Err(CustError::new(format!(
                            "two-dimensional array row pointer index {next_index} out of bounds for row {row} with length {columns}"
                        )));
                    }
                }
                self.array_pointer_at(array, source_name.clone(), owner.clone(), next_index)
            }
            PointerValue::Array2DRow {
                array,
                source_name,
                row,
                owner,
            } => self.two_dimensional_array_row_pointer_at(
                array,
                source_name.clone(),
                owner.clone(),
                *row as i64 + offset,
            ),
        }
    }

    fn two_dimensional_array_row_pointer_at(
        &self,
        array: &Rc<RefCell<ArrayValue>>,
        source_name: Option<String>,
        owner: Option<ArrayPointerOwner>,
        row: i64,
    ) -> CustResult<PointerValue> {
        self.ensure_array_pointer_owner_live(owner.as_ref())?;
        let rows = array
            .borrow()
            .dimensions
            .map(|(rows, _)| rows)
            .ok_or_else(|| CustError::new("pointer does not reference a two-dimensional array"))?;
        let Ok(row_index) = usize::try_from(row) else {
            return Err(CustError::new(format!(
                "two-dimensional array row pointer index {row} out of bounds for length {rows}"
            )));
        };
        if row_index >= rows {
            return Err(CustError::new(format!(
                "two-dimensional array row pointer index {row} out of bounds for length {rows}"
            )));
        }
        Ok(PointerValue::Array2DRow {
            array: Rc::clone(array),
            source_name,
            row: row_index,
            owner,
        })
    }

    fn nested_struct_array_pointer_at(
        &self,
        pointer: &PointerValue,
        fields: &[String],
        index: i64,
    ) -> CustResult<PointerValue> {
        let (type_name, field_map) = self.find_struct_pointer_fields(pointer)?;
        let len = match Self::nested_field_value(&type_name, field_map, fields)?.1 {
            StructFieldValue::StructArray { elements, .. } => elements.len(),
            _ => return Err(CustError::new("pointer does not reference a struct array")),
        };
        let Ok(index_usize) = usize::try_from(index) else {
            return Err(CustError::new(format!(
                "struct array field pointer index {index} out of bounds for length {len}"
            )));
        };
        if index_usize >= len {
            return Err(CustError::new(format!(
                "struct array field pointer index {index} out of bounds for length {len}"
            )));
        }
        Ok(PointerValue::NestedStructArrayElement {
            pointer: Box::new(pointer.clone()),
            fields: fields.to_vec(),
            index: index_usize,
        })
    }

    fn struct_array_pointer_at(
        &self,
        scope_id: usize,
        name: &str,
        index: i64,
    ) -> CustResult<PointerValue> {
        if !self.live_scope_ids.contains(&scope_id) {
            return Err(CustError::new(format!(
                "pointer to out-of-scope variable '{name}'"
            )));
        }
        let value = self
            .scopes
            .iter()
            .find(|scope| scope.id == scope_id)
            .and_then(|scope| scope.values.get(name))
            .or_else(|| self.static_value_by_scope(scope_id, name));
        let len = match value {
            Some(Value::StructArray { elements, .. }) => elements.len(),
            _ => {
                return Err(CustError::new(format!(
                    "pointer to out-of-scope variable '{name}'"
                )));
            }
        };
        let Ok(index_usize) = usize::try_from(index) else {
            return Err(CustError::new(format!(
                "struct array pointer index {index} out of bounds for length {len}"
            )));
        };
        if index_usize >= len {
            return Err(CustError::new(format!(
                "struct array pointer index {index} out of bounds for length {len}"
            )));
        }
        Ok(PointerValue::StructElement {
            scope_id,
            name: name.to_string(),
            index: index_usize,
        })
    }

    fn array_pointer_at(
        &self,
        array: &Rc<RefCell<ArrayValue>>,
        source_name: Option<String>,
        owner: Option<ArrayPointerOwner>,
        index: i64,
    ) -> CustResult<PointerValue> {
        self.ensure_array_pointer_owner_live(owner.as_ref())?;
        let len = array.borrow().elements.len();
        let Ok(index_usize) = usize::try_from(index) else {
            return Err(CustError::new(format!(
                "array pointer index {index} out of bounds for length {len}"
            )));
        };
        if index_usize >= len {
            return Err(CustError::new(format!(
                "array pointer index {index} out of bounds for length {len}"
            )));
        }
        Ok(PointerValue::ArrayElement {
            array: Rc::clone(array),
            source_name,
            index: index_usize,
            owner,
        })
    }

    fn deref_pointer(&self, pointer: &PointerValue) -> CustResult<i64> {
        match pointer {
            PointerValue::Null => Err(CustError::new("null pointer dereference")),
            PointerValue::Scalar { scope_id, name } => {
                if !self.live_scope_ids.contains(scope_id) {
                    return Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    )));
                }
                let value = self
                    .scopes
                    .iter()
                    .find(|scope| scope.id == *scope_id)
                    .and_then(|scope| scope.values.get(name))
                    .or_else(|| self.static_value_by_scope(*scope_id, name));
                match value {
                    Some(Value::Scalar { value, .. }) => Ok(*value),
                    _ => Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    ))),
                }
            }
            PointerValue::Struct { .. }
            | PointerValue::StructElement { .. }
            | PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. } => {
                Err(CustError::new("struct pointer used as scalar"))
            }
            PointerValue::StructFieldElementField {
                scope_id,
                name,
                element_index,
                array_fields,
                index,
                fields,
            } => self.read_struct_field_element_field_pointer(
                *scope_id,
                name,
                *element_index,
                array_fields,
                *index,
                fields,
            ),
            PointerValue::StructField {
                scope_id,
                name,
                element_index,
                fields,
            } => self.read_struct_field_pointer(*scope_id, name, *element_index, fields),
            PointerValue::ArrayBase { array, owner, .. } => {
                self.ensure_array_pointer_owner_live(owner.as_ref())?;
                let array = array.borrow();
                array.elements.first().copied().ok_or_else(|| {
                    CustError::new("array pointer index 0 out of bounds for length 0")
                })
            }
            PointerValue::ArrayElement {
                array,
                index,
                owner,
                ..
            } => {
                self.ensure_array_pointer_owner_live(owner.as_ref())?;
                Ok(array.borrow().elements[*index])
            }
            PointerValue::Array2DRow { .. } => Err(CustError::new(
                "two-dimensional array row pointer used as scalar",
            )),
        }
    }

    fn assign_deref_pointer(&mut self, pointer: &PointerValue, value: i64) -> CustResult<()> {
        match pointer {
            PointerValue::Null => Err(CustError::new("null pointer dereference")),
            PointerValue::Scalar { scope_id, name } => {
                if !self.live_scope_ids.contains(scope_id) {
                    return Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    )));
                }
                if let Some(scope) = self.scopes.iter().find(|scope| scope.id == *scope_id) {
                    if scope.const_variables.contains(name) {
                        return Err(CustError::new(format!(
                            "cannot assign to const variable '{name}'"
                        )));
                    }
                } else if self.static_locals.values().any(|storage| {
                    storage.scope_id == *scope_id && storage.name == *name && storage.is_const
                }) {
                    return Err(CustError::new(format!(
                        "cannot assign to const variable '{name}'"
                    )));
                }
                match self
                    .scopes
                    .iter_mut()
                    .find(|scope| scope.id == *scope_id)
                    .and_then(|scope| scope.values.get_mut(name))
                {
                    Some(Value::Scalar {
                        value: slot, ty, ..
                    }) => {
                        *slot = ty.normalize(value);
                        Ok(())
                    }
                    Some(_) => Err(CustError::new(format!(
                        "pointer to out-of-scope variable '{name}'"
                    ))),
                    None => match self.static_value_by_scope_mut(*scope_id, name) {
                        Some(Value::Scalar {
                            value: slot, ty, ..
                        }) => {
                            *slot = ty.normalize(value);
                            Ok(())
                        }
                        _ => Err(CustError::new(format!(
                            "pointer to out-of-scope variable '{name}'"
                        ))),
                    },
                }
            }
            PointerValue::ArrayBase { .. } | PointerValue::ArrayElement { .. } => {
                self.assign_pointer_index(pointer, 0, value)
            }
            PointerValue::Array2DRow { .. } => Err(CustError::new(
                "cannot assign a scalar through a two-dimensional array row pointer",
            )),
            PointerValue::Struct { .. }
            | PointerValue::StructElement { .. }
            | PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. } => {
                Err(CustError::new("struct pointer used as scalar"))
            }
            PointerValue::StructFieldElementField { .. } => {
                self.assign_struct_field_element_field_pointer(pointer, value)
            }
            PointerValue::StructField {
                scope_id,
                name,
                element_index,
                fields,
            } => self.assign_struct_field_pointer(*scope_id, name, *element_index, fields, value),
        }
    }

    fn checked_pointer_index(
        &mut self,
        name: &str,
        index: &Expr,
    ) -> CustResult<(Rc<RefCell<ArrayValue>>, Option<String>, usize)> {
        let index_value = self.eval(index)?;
        let pointer = match self.find_variable(name) {
            Some(Value::Pointer { pointer, .. }) => pointer.clone(),
            Some(Value::Scalar { .. }) => {
                return Err(CustError::new(format!(
                    "variable '{name}' is not a pointer"
                )));
            }
            Some(Value::Array(_)) => {
                return Err(CustError::new(format!("array '{name}' is not a pointer")));
            }
            Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => {
                return Err(CustError::new(format!(
                    "struct variable '{name}' used as pointer"
                )));
            }
            None => return Err(CustError::new(format!("undefined variable '{name}'"))),
        };
        let (array, source_name, index, _) =
            self.checked_pointer_value_index(&pointer, index_value)?;
        Ok((array, source_name, index))
    }

    fn scalar_variable_reverse_subscript_pointer(
        &mut self,
        name: &str,
        pointer_expr: &Expr,
    ) -> CustResult<Option<PointerValue>> {
        let offset = match self.find_variable(name) {
            Some(Value::Scalar { value, .. }) => *value,
            Some(_) | None => return Ok(None),
        };

        self.reverse_subscript_pointer_from_offset(offset, pointer_expr)
            .map(Some)
    }

    fn scalar_field_reverse_subscript_pointer(
        &mut self,
        name: &str,
        fields: &[String],
        pointer_expr: &Expr,
    ) -> CustResult<Option<PointerValue>> {
        let offset = match self.find_variable(name) {
            Some(Value::Struct {
                type_name,
                fields: field_map,
            }) => match Self::nested_field_value(type_name, field_map, fields)?.1 {
                StructFieldValue::Scalar { value, .. } => *value,
                StructFieldValue::Array { .. }
                | StructFieldValue::Struct { .. }
                | StructFieldValue::StructArray { .. }
                | StructFieldValue::Pointer { .. } => return Ok(None),
            },
            Some(_) | None => return Ok(None),
        };

        self.reverse_subscript_pointer_from_offset(offset, pointer_expr)
            .map(Some)
    }

    fn reverse_subscript_pointer_from_offset(
        &mut self,
        offset: i64,
        pointer_expr: &Expr,
    ) -> CustResult<PointerValue> {
        if !self.expr_is_pointer_value(pointer_expr) {
            return Err(CustError::new(
                "subscript requires one pointer operand and one scalar operand",
            ));
        }

        if let Expr::Var(pointer_name) = pointer_expr {
            match self.find_variable(pointer_name) {
                Some(Value::Array(_)) => {
                    let (array, index) =
                        self.checked_array_index(pointer_name, &Expr::Number(offset))?;
                    return Ok(PointerValue::ArrayElement {
                        array,
                        source_name: Some(pointer_name.clone()),
                        owner: None,
                        index,
                    });
                }
                Some(Value::StructArray { .. }) => {
                    return self.find_struct_element_pointer(pointer_name, &Expr::Number(offset));
                }
                Some(Value::Pointer { .. }) | None => {}
                Some(Value::Scalar { .. } | Value::Struct { .. }) => {
                    return Err(CustError::new(
                        "subscript requires one pointer operand and one scalar operand",
                    ));
                }
            }
        }

        let pointer = self.eval_pointer(pointer_expr)?;
        self.offset_array_pointer(&pointer, offset)
    }

    fn ensure_reverse_subscript_pointee_mutable(&self, pointer_expr: &Expr) -> CustResult<()> {
        let directly_names_array = match pointer_expr {
            Expr::Var(name) => matches!(
                self.find_variable(name),
                Some(Value::Array(_) | Value::StructArray { .. })
            ),
            _ => false,
        };
        if directly_names_array {
            return Ok(());
        }
        self.ensure_pointer_expr_pointee_mutable(pointer_expr)
    }

    fn checked_pointer_value_index(
        &self,
        pointer: &PointerValue,
        index_value: i64,
    ) -> CustResult<CheckedArrayPointerIndex> {
        match pointer {
            PointerValue::Null => Err(CustError::new("null pointer dereference")),
            PointerValue::Scalar { .. }
            | PointerValue::StructField { .. }
            | PointerValue::StructFieldElementField { .. } => {
                Err(CustError::new("scalar pointer is not indexable"))
            }
            PointerValue::Struct { .. }
            | PointerValue::StructElement { .. }
            | PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. } => {
                Err(CustError::new("struct pointer is not indexable"))
            }
            PointerValue::ArrayBase {
                array,
                source_name,
                owner,
            } => {
                self.ensure_array_pointer_owner_live(owner.as_ref())?;
                let len = array.borrow().elements.len();
                let Ok(index) = usize::try_from(index_value) else {
                    return Err(CustError::new(format!(
                        "array pointer index {index_value} out of bounds for length {len}"
                    )));
                };
                if index >= len {
                    return Err(CustError::new(format!(
                        "array pointer index {index_value} out of bounds for length {len}"
                    )));
                }
                Ok((Rc::clone(array), source_name.clone(), index, owner.clone()))
            }
            PointerValue::ArrayElement {
                array,
                source_name,
                index: base_index,
                owner,
            } => {
                self.ensure_array_pointer_owner_live(owner.as_ref())?;
                let len = array.borrow().elements.len();
                let candidate = *base_index as i64 + index_value;
                let Ok(index) = usize::try_from(candidate) else {
                    return Err(CustError::new(format!(
                        "array pointer index {candidate} out of bounds for length {len}"
                    )));
                };
                if index >= len {
                    return Err(CustError::new(format!(
                        "array pointer index {candidate} out of bounds for length {len}"
                    )));
                }
                Ok((Rc::clone(array), source_name.clone(), index, owner.clone()))
            }
            PointerValue::Array2DRow { .. } => Err(CustError::new(
                "two-dimensional array row pointer requires two-dimensional indexing",
            )),
        }
    }

    fn assign_pointer_index(
        &mut self,
        pointer: &PointerValue,
        index_value: i64,
        value: i64,
    ) -> CustResult<()> {
        let (array, source_name, index, _) =
            self.checked_pointer_value_index(pointer, index_value)?;
        let mut array = array.borrow_mut();
        if array.read_only {
            return Err(CustError::new(match source_name {
                Some(name) => format!("cannot modify read-only array '{name}'"),
                None => "cannot modify read-only array through pointer".to_string(),
            }));
        }
        array.elements[index] = array.elem_type.normalize(value);
        Ok(())
    }

    fn checked_array_index(
        &mut self,
        name: &str,
        index: &Expr,
    ) -> CustResult<(Rc<RefCell<ArrayValue>>, usize)> {
        let index_value = self.eval(index)?;
        let array = self.find_array(name)?;
        if array.borrow().dimensions.is_some() {
            return Err(CustError::new(format!(
                "two-dimensional array '{name}' requires a second index"
            )));
        }
        let len = array.borrow().elements.len();
        let Ok(index) = usize::try_from(index_value) else {
            return Err(CustError::new(format!(
                "array '{name}' index {index_value} out of bounds for length {len}"
            )));
        };
        if index >= len {
            return Err(CustError::new(format!(
                "array '{name}' index {index_value} out of bounds for length {len}"
            )));
        }
        Ok((array, index))
    }

    fn checked_two_dimensional_array_index(
        &mut self,
        name: &str,
        row: &Expr,
        column: &Expr,
    ) -> CustResult<(Rc<RefCell<ArrayValue>>, usize)> {
        let row_value = self.eval(row)?;
        let column_value = self.eval(column)?;
        let (array, base_row, owner) = match self.find_variable(name) {
            Some(Value::Array(array)) => (Rc::clone(array), 0, None),
            Some(Value::Pointer {
                pointer:
                    PointerValue::Array2DRow {
                        array, row, owner, ..
                    },
                ..
            }) => (Rc::clone(array), *row, owner.clone()),
            Some(Value::Pointer { .. }) => {
                return Err(CustError::new(format!(
                    "pointer '{name}' does not reference a two-dimensional array"
                )));
            }
            Some(_) => {
                return Err(CustError::new(format!(
                    "variable '{name}' is not a two-dimensional array"
                )));
            }
            None => return Err(CustError::new(format!("undefined variable '{name}'"))),
        };
        self.ensure_array_pointer_owner_live(owner.as_ref())?;
        let (rows, columns) = array
            .borrow()
            .dimensions
            .ok_or_else(|| CustError::new(format!("array '{name}' is not two-dimensional")))?;
        let Ok(relative_row) = usize::try_from(row_value) else {
            return Err(CustError::new(format!(
                "array '{name}' first dimension index {row_value} out of bounds for length {}",
                rows - base_row
            )));
        };
        let Some(row_index) = base_row.checked_add(relative_row) else {
            return Err(CustError::new(format!(
                "array '{name}' first dimension index {row_value} out of bounds for length {}",
                rows - base_row
            )));
        };
        if row_index >= rows {
            return Err(CustError::new(format!(
                "array '{name}' first dimension index {row_value} out of bounds for length {}",
                rows - base_row
            )));
        }
        let Ok(column_index) = usize::try_from(column_value) else {
            return Err(CustError::new(format!(
                "array '{name}' second dimension index {column_value} out of bounds for length {columns}"
            )));
        };
        if column_index >= columns {
            return Err(CustError::new(format!(
                "array '{name}' second dimension index {column_value} out of bounds for length {columns}"
            )));
        }
        Ok((array, row_index * columns + column_index))
    }

    fn ensure_two_dimensional_array_mutable(&self, name: &str) -> CustResult<()> {
        let is_read_only = match self.find_variable(name) {
            Some(Value::Pointer {
                pointer: PointerValue::Array2DRow { .. },
                points_to_const,
                ..
            }) => *points_to_const,
            _ => self.is_const_variable(name),
        };
        if is_read_only {
            return Err(CustError::new(format!(
                "cannot modify read-only array '{name}'"
            )));
        }
        Ok(())
    }

    fn checked_two_dimensional_struct_field_index(
        &mut self,
        target: &Array2DFieldTarget,
        row: &Expr,
        column: &Expr,
    ) -> CustResult<(Rc<RefCell<ArrayValue>>, usize)> {
        let (array, label) = match target {
            Array2DFieldTarget::Direct { name, fields } => (
                self.find_struct_array_field(name, fields)?,
                Self::field_path_label(fields).to_string(),
            ),
            Array2DFieldTarget::Element {
                name,
                index,
                fields,
            } => (
                self.find_struct_element_array_field(name, index, fields)?,
                Self::field_path_label(fields).to_string(),
            ),
            Array2DFieldTarget::Pointer { pointer, fields } => {
                let pointer = self.eval_pointer(pointer)?;
                (
                    self.find_struct_pointer_array_field(&pointer, fields)?,
                    Self::field_path_label(fields).to_string(),
                )
            }
        };
        let row_value = self.eval(row)?;
        let column_value = self.eval(column)?;
        let (rows, columns) = array.borrow().dimensions.ok_or_else(|| {
            CustError::new(format!("array field '{label}' is not two-dimensional"))
        })?;
        let Ok(row_index) = usize::try_from(row_value) else {
            return Err(CustError::new(format!(
                "array field '{label}' first dimension index {row_value} out of bounds for length {rows}"
            )));
        };
        if row_index >= rows {
            return Err(CustError::new(format!(
                "array field '{label}' first dimension index {row_value} out of bounds for length {rows}"
            )));
        }
        let Ok(column_index) = usize::try_from(column_value) else {
            return Err(CustError::new(format!(
                "array field '{label}' second dimension index {column_value} out of bounds for length {columns}"
            )));
        };
        if column_index >= columns {
            return Err(CustError::new(format!(
                "array field '{label}' second dimension index {column_value} out of bounds for length {columns}"
            )));
        }
        Ok((array, row_index * columns + column_index))
    }

    fn ensure_two_dimensional_struct_field_target_mutable(
        &self,
        target: &Array2DFieldTarget,
    ) -> CustResult<()> {
        match target {
            Array2DFieldTarget::Direct { name, fields } => {
                self.ensure_variable_mutable(name)?;
                if self.direct_struct_array_field_points_to_const(name, fields) {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(fields)
                    )));
                }
            }
            Array2DFieldTarget::Element { name, fields, .. } => {
                match self.find_variable(name) {
                    Some(Value::StructArray {
                        read_only: true, ..
                    }) => {
                        return Err(CustError::new(format!(
                            "cannot assign to const variable '{name}'"
                        )));
                    }
                    Some(Value::Pointer {
                        points_to_const: true,
                        ..
                    }) => return Err(CustError::new("cannot assign through pointer to const")),
                    _ => {}
                }
                if self.struct_array_element_field_points_to_const(name, fields) {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(fields)
                    )));
                }
            }
            Array2DFieldTarget::Pointer { pointer, fields } => {
                let field_is_const = self
                    .struct_pointer_expr_field_metadata(pointer, fields)?
                    .is_some_and(|(_, is_const, _)| is_const);
                if self.pointer_expr_points_to_const(pointer) || field_is_const {
                    return Err(CustError::new("cannot assign through pointer to const"));
                }
            }
        }
        Ok(())
    }

    fn consume_loop_iteration(&mut self) -> CustResult<()> {
        match self.max_loop_iterations {
            Some(max) if self.loop_iterations >= max => {
                return Err(CustError::new(format!(
                    "execution step limit exceeded after {max} loop iterations"
                )));
            }
            Some(_) | None => {}
        }
        self.loop_iterations += 1;
        Ok(())
    }

    fn pointer_truthy(pointer: &PointerValue) -> bool {
        !matches!(pointer, PointerValue::Null)
    }

    fn expr_is_pointer_value(&self, expr: &Expr) -> bool {
        match expr {
            Expr::Number(_) => false,
            Expr::AddressOf(_)
            | Expr::AddressOfArray { .. }
            | Expr::AddressOfStructField { .. }
            | Expr::AddressOfStructElementField { .. }
            | Expr::AddressOfStructArrayField { .. }
            | Expr::AddressOfStructElementArrayField { .. }
            | Expr::AddressOfStructPtrField { .. }
            | Expr::AddressOfStructPtrArrayField { .. }
            | Expr::AddressOfScalarLiteral { .. }
            | Expr::AddressOfAggregateLiteral { .. }
            | Expr::AddressOfAggregateField { .. }
            | Expr::StringLiteral(_)
            | Expr::ArrayLiteral { .. }
            | Expr::AggregateArrayLiteral { .. }
            | Expr::PointerCast { .. } => true,
            Expr::Var(name) | Expr::Assign { name, .. } | Expr::CompoundAssign { name, .. } => {
                matches!(
                    self.find_variable(name),
                    Some(Value::Pointer { .. } | Value::Array(_) | Value::StructArray { .. })
                )
            }
            Expr::StructGet { name, fields } => self.struct_field_decays_to_pointer(name, fields),
            Expr::StructElementGet { name, fields, .. } => {
                self.struct_element_field_decays_to_pointer(name, fields)
            }
            Expr::StructElementSet { name, fields, .. }
            | Expr::StructElementCompoundSet { name, fields, .. } => matches!(
                self.struct_element_field_metadata(name, fields),
                Ok(Some((StructFieldType::Pointer(_), _, _)))
            ),
            Expr::StructPtrGet { pointer, fields } => {
                self.struct_pointer_field_decays_to_pointer(pointer, fields)
            }
            Expr::AggregateFieldGet { aggregate, fields } => matches!(
                self.aggregate_literal_field_metadata(aggregate, fields),
                Ok(Some((
                    StructFieldType::Pointer(_)
                        | StructFieldType::Array(_, _)
                        | StructFieldType::Array2D(_, _, _)
                        | StructFieldType::StructArray(_, _),
                    _,
                    _
                )))
            ),
            Expr::AggregateFieldSet {
                aggregate, fields, ..
            }
            | Expr::AggregateFieldCompoundSet {
                aggregate, fields, ..
            } => matches!(
                self.aggregate_literal_field_metadata(aggregate, fields),
                Ok(Some((StructFieldType::Pointer(_), _, _)))
            ),
            Expr::StructSet { name, fields, .. } | Expr::StructCompoundSet { name, fields, .. } => {
                self.struct_field_is_pointer(name, fields)
            }
            Expr::StructPtrSet {
                pointer, fields, ..
            }
            | Expr::StructPtrCompoundSet {
                pointer, fields, ..
            } => self.struct_pointer_field_decays_to_pointer(pointer, fields),
            Expr::StructFieldArrayElementGet {
                name,
                array_fields,
                index,
                fields,
            } => matches!(
                self.struct_field_array_element_field_metadata(name, array_fields, index, fields),
                Ok(Some((
                    StructFieldType::Pointer(_)
                        | StructFieldType::Array(_, _)
                        | StructFieldType::Array2D(_, _, _)
                        | StructFieldType::StructArray(_, _),
                    _,
                    _
                )))
            ),
            Expr::StructFieldArrayElementSet {
                name,
                array_fields,
                index,
                fields,
                ..
            }
            | Expr::StructFieldArrayElementCompoundSet {
                name,
                array_fields,
                index,
                fields,
                ..
            } => matches!(
                self.struct_field_array_element_field_metadata(name, array_fields, index, fields),
                Ok(Some((StructFieldType::Pointer(_), _, _)))
            ),
            Expr::Increment { target, .. } => self.expr_is_pointer_value(target),
            Expr::Deref(pointer) => self.array2d_row_pointer_element_type(pointer).is_some(),
            Expr::Call { name, .. } => {
                self.has_character_search_prototype(name)
                    || self.has_character_set_search_prototype(name)
                    || self.has_string_copy_prototype(name)
                    || matches!(
                        self.functions
                            .get(name)
                            .map(|function| &function.return_type),
                        Some(ReturnType::Pointer { .. } | ReturnType::Array2DPointer { .. })
                    )
            }
            Expr::Conditional {
                then_expr,
                else_expr,
                ..
            } => self.expr_is_pointer_value(then_expr) || self.expr_is_pointer_value(else_expr),
            Expr::Comma(_, right) => self.expr_is_pointer_value(right),
            Expr::Binary(left, BinaryOp::Add, right) => {
                self.expr_is_pointer_value(left) || self.expr_is_pointer_value(right)
            }
            Expr::Binary(left, BinaryOp::Sub, right) => {
                self.expr_is_pointer_value(left) && !self.expr_is_pointer_value(right)
            }
            _ => false,
        }
    }

    fn pointer_eq(left: &PointerValue, right: &PointerValue) -> bool {
        match (left, right) {
            (PointerValue::Null, PointerValue::Null) => true,
            (PointerValue::Null, _) | (_, PointerValue::Null) => false,
            (
                PointerValue::Scalar {
                    scope_id: left_scope,
                    name: left_name,
                },
                PointerValue::Scalar {
                    scope_id: right_scope,
                    name: right_name,
                },
            ) => left_scope == right_scope && left_name == right_name,
            (
                PointerValue::Struct {
                    scope_id: left_scope,
                    name: left_name,
                },
                PointerValue::Struct {
                    scope_id: right_scope,
                    name: right_name,
                },
            ) => left_scope == right_scope && left_name == right_name,
            (
                PointerValue::StructElement {
                    scope_id: left_scope,
                    name: left_name,
                    index: left_index,
                },
                PointerValue::StructElement {
                    scope_id: right_scope,
                    name: right_name,
                    index: right_index,
                },
            ) => left_scope == right_scope && left_name == right_name && left_index == right_index,
            (
                PointerValue::NestedStructArrayElement {
                    pointer: left_pointer,
                    fields: left_fields,
                    index: left_index,
                },
                PointerValue::NestedStructArrayElement {
                    pointer: right_pointer,
                    fields: right_fields,
                    index: right_index,
                },
            ) => {
                Self::pointer_eq(left_pointer, right_pointer)
                    && left_fields == right_fields
                    && left_index == right_index
            }
            (
                PointerValue::StructFieldElement {
                    scope_id: left_scope,
                    name: left_name,
                    element_index: left_element,
                    fields: left_fields,
                    index: left_index,
                },
                PointerValue::StructFieldElement {
                    scope_id: right_scope,
                    name: right_name,
                    element_index: right_element,
                    fields: right_fields,
                    index: right_index,
                },
            ) => {
                left_scope == right_scope
                    && left_name == right_name
                    && left_element == right_element
                    && left_fields == right_fields
                    && left_index == right_index
            }
            (
                PointerValue::StructField {
                    scope_id: left_scope,
                    name: left_name,
                    element_index: left_element,
                    fields: left_fields,
                },
                PointerValue::StructField {
                    scope_id: right_scope,
                    name: right_name,
                    element_index: right_element,
                    fields: right_fields,
                },
            ) => {
                left_scope == right_scope
                    && left_name == right_name
                    && left_element == right_element
                    && left_fields == right_fields
            }
            (
                PointerValue::StructFieldElementField {
                    scope_id: left_scope,
                    name: left_name,
                    element_index: left_element,
                    array_fields: left_array_fields,
                    index: left_index,
                    fields: left_fields,
                },
                PointerValue::StructFieldElementField {
                    scope_id: right_scope,
                    name: right_name,
                    element_index: right_element,
                    array_fields: right_array_fields,
                    index: right_index,
                    fields: right_fields,
                },
            ) => {
                left_scope == right_scope
                    && left_name == right_name
                    && left_element == right_element
                    && left_array_fields == right_array_fields
                    && left_index == right_index
                    && left_fields == right_fields
            }
            (PointerValue::Struct { .. }, PointerValue::StructElement { .. })
            | (PointerValue::StructElement { .. }, PointerValue::Struct { .. })
            | (PointerValue::Struct { .. }, PointerValue::StructField { .. })
            | (PointerValue::StructField { .. }, PointerValue::Struct { .. })
            | (PointerValue::StructElement { .. }, PointerValue::StructField { .. })
            | (PointerValue::StructField { .. }, PointerValue::StructElement { .. }) => false,
            (
                PointerValue::ArrayBase { array: left, .. },
                PointerValue::ArrayBase { array: right, .. },
            ) => Rc::ptr_eq(left, right),
            (
                PointerValue::ArrayBase { array: left, .. },
                PointerValue::ArrayElement {
                    array: right,
                    index,
                    ..
                },
            )
            | (
                PointerValue::ArrayElement {
                    array: right,
                    index,
                    ..
                },
                PointerValue::ArrayBase { array: left, .. },
            ) => *index == 0 && Rc::ptr_eq(left, right),
            (
                PointerValue::ArrayElement {
                    array: left,
                    index: left_index,
                    ..
                },
                PointerValue::ArrayElement {
                    array: right,
                    index: right_index,
                    ..
                },
            ) => left_index == right_index && Rc::ptr_eq(left, right),
            (
                PointerValue::Array2DRow {
                    array: left,
                    row: left_row,
                    ..
                },
                PointerValue::Array2DRow {
                    array: right,
                    row: right_row,
                    ..
                },
            ) => left_row == right_row && Rc::ptr_eq(left, right),
            (PointerValue::Scalar { .. }, PointerValue::ArrayBase { .. })
            | (PointerValue::Scalar { .. }, PointerValue::ArrayElement { .. })
            | (PointerValue::Scalar { .. }, PointerValue::Struct { .. })
            | (PointerValue::ArrayBase { .. }, PointerValue::Scalar { .. })
            | (PointerValue::ArrayElement { .. }, PointerValue::Scalar { .. })
            | (PointerValue::ArrayBase { .. }, PointerValue::Struct { .. })
            | (PointerValue::ArrayElement { .. }, PointerValue::Struct { .. })
            | (PointerValue::Struct { .. }, PointerValue::Scalar { .. })
            | (PointerValue::Struct { .. }, PointerValue::ArrayBase { .. })
            | (PointerValue::Struct { .. }, PointerValue::ArrayElement { .. }) => false,
            _ => false,
        }
    }

    fn array_pointer_index(pointer: &PointerValue) -> CustResult<(&Rc<RefCell<ArrayValue>>, i64)> {
        match pointer {
            PointerValue::ArrayBase { array, .. } => Ok((array, 0)),
            PointerValue::ArrayElement { array, index, .. } => Ok((array, *index as i64)),
            PointerValue::Array2DRow { array, row, .. } => Ok((array, *row as i64)),
            PointerValue::Null => Err(CustError::new("null pointer arithmetic is not supported")),
            PointerValue::Scalar { .. }
            | PointerValue::Struct { .. }
            | PointerValue::StructElement { .. }
            | PointerValue::StructFieldElement { .. }
            | PointerValue::NestedStructArrayElement { .. }
            | PointerValue::StructField { .. }
            | PointerValue::StructFieldElementField { .. } => {
                Err(CustError::new("scalar pointer arithmetic is not supported"))
            }
        }
    }

    fn pointer_ordering(
        &self,
        left: &PointerValue,
        op: BinaryOp,
        right: &PointerValue,
    ) -> CustResult<i64> {
        let difference = self.pointer_difference(left, right).map_err(|error| {
            let message = error.to_string();
            if message == "cannot subtract pointers to different arrays" {
                CustError::new("cannot compare pointers to different arrays")
            } else if message == "scalar pointer arithmetic is not supported"
                || message == "null pointer arithmetic is not supported"
            {
                CustError::new("pointer ordering comparisons are not supported")
            } else {
                error
            }
        })?;
        let ordering = difference.cmp(&0);
        let result = match op {
            BinaryOp::Lt => ordering.is_lt(),
            BinaryOp::Le => !ordering.is_gt(),
            BinaryOp::Gt => ordering.is_gt(),
            BinaryOp::Ge => !ordering.is_lt(),
            _ => unreachable!("only ordering operators reach pointer_ordering"),
        };
        Ok(result as i64)
    }

    fn pointer_difference(&self, left: &PointerValue, right: &PointerValue) -> CustResult<i64> {
        match (left, right) {
            (
                PointerValue::Array2DRow {
                    array: left_array,
                    row: left_row,
                    owner: left_owner,
                    ..
                },
                PointerValue::Array2DRow {
                    array: right_array,
                    row: right_row,
                    owner: right_owner,
                    ..
                },
            ) => {
                self.ensure_array_pointer_owner_live(left_owner.as_ref())?;
                self.ensure_array_pointer_owner_live(right_owner.as_ref())?;
                if !Rc::ptr_eq(left_array, right_array) {
                    return Err(CustError::new(
                        "cannot subtract pointers to different arrays",
                    ));
                }
                Ok(*left_row as i64 - *right_row as i64)
            }
            (PointerValue::Array2DRow { .. }, _) | (_, PointerValue::Array2DRow { .. }) => Err(
                CustError::new("cannot subtract pointers to different arrays"),
            ),
            (
                PointerValue::NestedStructArrayElement {
                    pointer: left_pointer,
                    fields: left_fields,
                    index: left_index,
                },
                PointerValue::NestedStructArrayElement {
                    pointer: right_pointer,
                    fields: right_fields,
                    index: right_index,
                },
            ) => {
                if !Self::pointer_eq(left_pointer, right_pointer) || left_fields != right_fields {
                    return Err(CustError::new(
                        "cannot subtract pointers to different arrays",
                    ));
                }
                self.nested_struct_array_pointer_at(left_pointer, left_fields, *left_index as i64)?;
                self.nested_struct_array_pointer_at(
                    right_pointer,
                    right_fields,
                    *right_index as i64,
                )?;
                Ok(*left_index as i64 - *right_index as i64)
            }
            (PointerValue::NestedStructArrayElement { .. }, _)
            | (_, PointerValue::NestedStructArrayElement { .. }) => Err(CustError::new(
                "cannot subtract pointers to different arrays",
            )),
            (
                PointerValue::StructFieldElement {
                    scope_id: left_scope,
                    name: left_name,
                    element_index: left_element_index,
                    fields: left_fields,
                    index: left_index,
                },
                PointerValue::StructFieldElement {
                    scope_id: right_scope,
                    name: right_name,
                    element_index: right_element_index,
                    fields: right_fields,
                    index: right_index,
                },
            ) => {
                if left_scope != right_scope
                    || left_name != right_name
                    || left_element_index != right_element_index
                    || left_fields != right_fields
                {
                    return Err(CustError::new(
                        "cannot subtract pointers to different arrays",
                    ));
                }
                self.struct_field_array_pointer_at(
                    *left_scope,
                    left_name,
                    *left_element_index,
                    left_fields,
                    *left_index as i64,
                )?;
                self.struct_field_array_pointer_at(
                    *right_scope,
                    right_name,
                    *right_element_index,
                    right_fields,
                    *right_index as i64,
                )?;
                Ok(*left_index as i64 - *right_index as i64)
            }
            (PointerValue::StructFieldElement { .. }, _)
            | (_, PointerValue::StructFieldElement { .. }) => Err(CustError::new(
                "cannot subtract pointers to different arrays",
            )),
            (
                PointerValue::StructElement {
                    scope_id: left_scope,
                    name: left_name,
                    index: left_index,
                },
                PointerValue::StructElement {
                    scope_id: right_scope,
                    name: right_name,
                    index: right_index,
                },
            ) => {
                if left_scope != right_scope || left_name != right_name {
                    return Err(CustError::new(
                        "cannot subtract pointers to different arrays",
                    ));
                }
                self.struct_array_pointer_at(*left_scope, left_name, *left_index as i64)?;
                self.struct_array_pointer_at(*right_scope, right_name, *right_index as i64)?;
                Ok(*left_index as i64 - *right_index as i64)
            }
            (PointerValue::StructElement { .. }, _) | (_, PointerValue::StructElement { .. }) => {
                Err(CustError::new(
                    "cannot subtract pointers to different arrays",
                ))
            }
            _ => {
                let (left_array, left_index) = Self::array_pointer_index(left)?;
                let (right_array, right_index) = Self::array_pointer_index(right)?;
                if !Rc::ptr_eq(left_array, right_array) {
                    return Err(CustError::new(
                        "cannot subtract pointers to different arrays",
                    ));
                }
                Ok(left_index - right_index)
            }
        }
    }

    fn eval_truthy(&mut self, expr: &Expr) -> CustResult<bool> {
        if self.expr_is_pointer_value(expr) {
            let pointer = self.eval_pointer(expr)?;
            return Ok(Self::pointer_truthy(&pointer));
        }

        match expr {
            Expr::Comma(left, right) => {
                self.eval_discard(left)?;
                self.eval_truthy(right)
            }
            Expr::AddressOf(_)
            | Expr::AddressOfArray { .. }
            | Expr::AddressOfStructField { .. }
            | Expr::AddressOfStructElementField { .. }
            | Expr::AddressOfStructArrayField { .. }
            | Expr::AddressOfStructElementArrayField { .. }
            | Expr::AddressOfStructPtrField { .. }
            | Expr::AddressOfStructPtrArrayField { .. }
            | Expr::AddressOfScalarLiteral { .. }
            | Expr::AddressOfAggregateLiteral { .. }
            | Expr::AddressOfAggregateField { .. }
            | Expr::StringLiteral(_)
            | Expr::ArrayLiteral { .. }
            | Expr::AggregateArrayLiteral { .. }
            | Expr::PointerCast { .. } => Ok(Self::pointer_truthy(&self.eval_pointer(expr)?)),
            Expr::Assign { name, .. } => match self.find_variable(name).cloned() {
                Some(Value::Pointer { .. }) => Ok(Self::pointer_truthy(&self.eval_pointer(expr)?)),
                Some(Value::Scalar { .. }) => Ok(self.eval(expr)? != 0),
                Some(Value::Array(_)) => Err(CustError::new(format!(
                    "array '{name}' requires indexed assignment"
                ))),
                Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => Err(
                    CustError::new(format!("struct variable '{name}' used as scalar")),
                ),
                None => Err(CustError::new(format!(
                    "assignment to undeclared variable '{name}'"
                ))),
            },
            Expr::Var(name) => match self.find_variable(name).cloned() {
                Some(Value::Pointer { pointer, .. }) => Ok(Self::pointer_truthy(&pointer)),
                Some(Value::Array(array)) => Ok(!array.borrow().elements.is_empty()),
                Some(Value::Scalar { value, .. }) => Ok(value != 0),
                Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => Err(
                    CustError::new(format!("struct variable '{name}' used as scalar")),
                ),
                None => self
                    .find_enum_constant(name)
                    .map(|value| value != 0)
                    .ok_or_else(|| CustError::new(format!("undefined variable '{name}'"))),
            },
            Expr::StructGet { name, fields }
                if self.struct_field_decays_to_pointer(name, fields) =>
            {
                Ok(Self::pointer_truthy(&self.eval_pointer(expr)?))
            }
            Expr::StructElementGet { name, fields, .. }
                if self.struct_element_field_decays_to_pointer(name, fields) =>
            {
                Ok(Self::pointer_truthy(&self.eval_pointer(expr)?))
            }
            Expr::StructPtrGet { pointer, fields }
                if self.struct_pointer_field_decays_to_pointer(pointer, fields) =>
            {
                Ok(Self::pointer_truthy(&self.eval_pointer(expr)?))
            }
            Expr::Deref(_)
            | Expr::DerefSet { .. }
            | Expr::DerefCompoundSet { .. }
            | Expr::ArrayGet { .. }
            | Expr::ArraySet { .. }
            | Expr::ArrayCompoundSet { .. }
            | Expr::Array2DGet { .. }
            | Expr::StructArray2DGet { .. }
            | Expr::Array2DSet { .. }
            | Expr::Array2DCompoundSet { .. }
            | Expr::StructArray2DSet { .. }
            | Expr::StructArray2DCompoundSet { .. }
            | Expr::StructArrayGet { .. }
            | Expr::StructFieldArrayElementGet { .. }
            | Expr::StructFieldArrayElementSet { .. }
            | Expr::StructFieldArrayElementCompoundSet { .. }
            | Expr::StructArraySet { .. }
            | Expr::StructArrayCompoundSet { .. }
            | Expr::StructElementGet { .. }
            | Expr::StructElementArrayGet { .. }
            | Expr::StructPtrArrayGet { .. }
            | Expr::StructElementSet { .. }
            | Expr::StructElementArraySet { .. }
            | Expr::StructElementCompoundSet { .. }
            | Expr::StructElementArrayCompoundSet { .. }
            | Expr::StructGet { .. }
            | Expr::StructSet { .. }
            | Expr::StructCompoundSet { .. }
            | Expr::StructPtrGet { .. }
            | Expr::StructPtrSet { .. }
            | Expr::StructPtrCompoundSet { .. }
            | Expr::StringGet { .. } => Ok(self.eval(expr)? != 0),
            Expr::Call { name, .. }
                if matches!(
                    self.functions
                        .get(name)
                        .map(|function| &function.return_type),
                    Some(ReturnType::Pointer { .. } | ReturnType::Array2DPointer { .. })
                ) =>
            {
                Ok(Self::pointer_truthy(&self.eval_pointer(expr)?))
            }
            Expr::Call { .. } => Ok(self.eval(expr)? != 0),
            Expr::Number(value) => Ok(*value != 0),
            Expr::Binary(_, BinaryOp::Add | BinaryOp::Sub, _)
                if self.expr_is_pointer_value(expr) =>
            {
                match self.eval_pointer(expr) {
                    Ok(pointer) => Ok(Self::pointer_truthy(&pointer)),
                    Err(error) => Err(error),
                }
            }
            Expr::Binary(_, BinaryOp::Add | BinaryOp::Sub, _) => Ok(self.eval(expr)? != 0),
            Expr::UnaryPlus(_)
            | Expr::UnaryMinus(_)
            | Expr::BitwiseNot(_)
            | Expr::LogicalNot(_)
            | Expr::Cast { .. }
            | Expr::VoidCast(_)
            | Expr::ScalarLiteral { .. }
            | Expr::AggregateLiteral { .. }
            | Expr::AggregateFieldGet { .. }
            | Expr::AggregateFieldSet { .. }
            | Expr::AggregateFieldCompoundSet { .. }
            | Expr::SizeOfType(_)
            | Expr::SizeOfValue(_)
            | Expr::AlignOfType(_)
            | Expr::CompoundAssign { .. }
            | Expr::ScalarLiteralSet { .. }
            | Expr::ScalarLiteralCompoundSet { .. }
            | Expr::Increment { .. }
            | Expr::Conditional { .. }
            | Expr::Binary(_, _, _) => Ok(self.eval(expr)? != 0),
        }
    }

    fn expr_is_void_value(&self, expr: &Expr) -> bool {
        match expr {
            Expr::VoidCast(_) => true,
            Expr::Call { name, .. } => matches!(
                self.functions
                    .get(name)
                    .map(|function| &function.return_type),
                Some(ReturnType::Void)
            ),
            Expr::Conditional {
                then_expr,
                else_expr,
                ..
            } => self.expr_is_void_value(then_expr) && self.expr_is_void_value(else_expr),
            Expr::Comma(_, right) => self.expr_is_void_value(right),
            _ => false,
        }
    }

    fn eval_discard(&mut self, expr: &Expr) -> CustResult<()> {
        if let Expr::Call { name, args } = expr {
            self.call_function(name, args)?;
            return Ok(());
        }
        if let Expr::VoidCast(inner) = expr {
            self.eval_discard(inner)?;
            return Ok(());
        }
        if self.expr_is_void_value(expr) {
            match expr {
                Expr::Conditional {
                    cond,
                    then_expr,
                    else_expr,
                } => {
                    if self.eval_truthy(cond)? {
                        self.eval_discard(then_expr)?;
                    } else {
                        self.eval_discard(else_expr)?;
                    }
                }
                Expr::Comma(left, right) => {
                    self.eval_discard(left)?;
                    self.eval_discard(right)?;
                }
                _ => unreachable!("direct calls and void casts are handled above"),
            }
            return Ok(());
        }
        if self.expr_is_pointer_value(expr) {
            self.eval_pointer(expr)?;
            return Ok(());
        }
        match self.aggregate_expr_type_name(expr) {
            Ok(_) => {
                self.eval_struct_expr(expr)?;
                return Ok(());
            }
            Err(error)
                if error
                    .to_string()
                    .contains("conditional branches have mismatched aggregate types") =>
            {
                return Err(error);
            }
            Err(_) => {}
        }
        match self.eval(expr) {
            Ok(_) => Ok(()),
            Err(error) => Err(error),
        }
    }

    fn eval_assignment_expr(&mut self, name: &str, value: &Expr) -> CustResult<i64> {
        match self.find_variable(name).cloned() {
            Some(Value::Scalar { ty, .. }) => {
                self.ensure_variable_mutable(name)?;
                let value = self.eval_scalar_conversion(ty, value)?;
                if let Some(Value::Scalar { value: slot, .. }) = self.find_variable_mut(name) {
                    *slot = value;
                }
                Ok(value)
            }
            Some(Value::Pointer { .. }) => Err(CustError::new("pointer value used as scalar")),
            Some(Value::Array(_)) => Err(CustError::new(format!(
                "array '{name}' requires indexed assignment"
            ))),
            Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => Err(CustError::new(
                format!("struct variable '{name}' assignment is not supported"),
            )),
            None if self.find_enum_constant(name).is_some() => Err(CustError::new(format!(
                "cannot assign to enum constant '{name}'"
            ))),
            None => Err(CustError::new(format!(
                "assignment to undeclared variable '{name}'"
            ))),
        }
    }

    fn eval_compound_assignment_expr(
        &mut self,
        name: &str,
        op: CompoundOp,
        value: &Expr,
    ) -> CustResult<i64> {
        match self.find_variable(name).cloned() {
            Some(Value::Scalar {
                value: current, ty, ..
            }) => {
                self.ensure_variable_mutable(name)?;
                let rhs = self.eval(value)?;
                let result = ty.normalize(Self::apply_compound_op(current, op, rhs)?);
                if let Some(Value::Scalar { value: slot, .. }) = self.find_variable_mut(name) {
                    *slot = result;
                }
                Ok(result)
            }
            Some(Value::Pointer { .. }) => Err(Self::pointer_compound_error(op)),
            Some(Value::Array(_)) => Err(CustError::new(format!(
                "array '{name}' requires indexed assignment"
            ))),
            Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => Err(CustError::new(
                format!("struct variable '{name}' assignment is not supported"),
            )),
            None if self.find_enum_constant(name).is_some() => Err(CustError::new(format!(
                "cannot assign to enum constant '{name}'"
            ))),
            None => Err(CustError::new(format!(
                "assignment to undeclared variable '{name}'"
            ))),
        }
    }

    fn apply_compound_op(lhs: i64, op: CompoundOp, rhs: i64) -> CustResult<i64> {
        match op {
            CompoundOp::Add => Ok(lhs + rhs),
            CompoundOp::Sub => Ok(lhs - rhs),
            CompoundOp::Mul => Ok(lhs * rhs),
            CompoundOp::Div if rhs == 0 => Err(CustError::new("division by zero")),
            CompoundOp::Div => Ok(lhs / rhs),
            CompoundOp::Rem if rhs == 0 => Err(CustError::new("division by zero")),
            CompoundOp::Rem => Ok(lhs % rhs),
            CompoundOp::BitAnd => Ok(lhs & rhs),
            CompoundOp::BitOr => Ok(lhs | rhs),
            CompoundOp::BitXor => Ok(lhs ^ rhs),
            CompoundOp::ShiftLeft => Self::checked_shift_left(lhs, rhs),
            CompoundOp::ShiftRight => Self::checked_shift_right(lhs, rhs),
        }
    }

    fn pointer_compound_error(op: CompoundOp) -> CustError {
        match op {
            CompoundOp::Add
            | CompoundOp::Sub
            | CompoundOp::Mul
            | CompoundOp::Div
            | CompoundOp::Rem => CustError::new("pointer arithmetic is not supported"),
            CompoundOp::BitAnd
            | CompoundOp::BitOr
            | CompoundOp::BitXor
            | CompoundOp::ShiftLeft
            | CompoundOp::ShiftRight => {
                CustError::new("pointer bitwise operations are not supported")
            }
        }
    }

    fn apply_increment_op(current: i64, op: IncrementOp) -> i64 {
        match op {
            IncrementOp::Inc => current + 1,
            IncrementOp::Dec => current - 1,
        }
    }

    fn increment_result(current: i64, updated: i64, prefix: bool) -> i64 {
        if prefix { updated } else { current }
    }

    fn eval_aggregate_literal_field_scalar(
        &mut self,
        aggregate: &Expr,
        path: &[String],
    ) -> CustResult<(i64, CType, bool)> {
        match self.eval_struct_expr(aggregate)? {
            ReturnValue::Struct { type_name, fields } => {
                let (_, field_value) = Self::nested_field_value(&type_name, &fields, path)?;
                match field_value {
                    StructFieldValue::Scalar {
                        value,
                        ty,
                        is_const,
                    } => Ok((*value, *ty, *is_const)),
                    StructFieldValue::Array { .. }
                    | StructFieldValue::Struct { .. }
                    | StructFieldValue::StructArray { .. }
                    | StructFieldValue::Pointer { .. } => {
                        Err(CustError::new("struct field used as scalar expression"))
                    }
                }
            }
            _ => Err(CustError::new("expected struct expression")),
        }
    }

    fn eval_aggregate_literal_pointer_field_metadata(
        &mut self,
        aggregate: &Expr,
        path: &[String],
    ) -> CustResult<(PointerValue, PointeeType, bool, bool)> {
        match self.eval_struct_expr(aggregate)? {
            ReturnValue::Struct { type_name, fields } => {
                let (_, field_value) = Self::nested_field_value(&type_name, &fields, path)?;
                match field_value {
                    StructFieldValue::Pointer {
                        pointer,
                        ty,
                        is_const,
                        points_to_const,
                    } => Ok((pointer.clone(), ty.clone(), *is_const, *points_to_const)),
                    _ => Err(CustError::new("struct field is not a pointer")),
                }
            }
            _ => Err(CustError::new("expected struct expression")),
        }
    }

    fn eval_aggregate_literal_field_pointer(
        &mut self,
        aggregate: &Expr,
        path: &[String],
    ) -> CustResult<PointerValue> {
        match self.eval_struct_expr(aggregate)? {
            ReturnValue::Struct { type_name, fields } => {
                let (_, field_value) = Self::nested_field_value(&type_name, &fields, path)?;
                match field_value {
                    StructFieldValue::Pointer { pointer, .. } => Ok(pointer.clone()),
                    StructFieldValue::Array { value, .. } => {
                        let array = Rc::clone(value);
                        if array.borrow().dimensions.is_some() {
                            Ok(PointerValue::Array2DRow {
                                array,
                                source_name: None,
                                row: 0,
                                owner: None,
                            })
                        } else {
                            Ok(PointerValue::ArrayBase {
                                array,
                                source_name: None,
                                owner: None,
                            })
                        }
                    }
                    StructFieldValue::StructArray {
                        type_name,
                        elements,
                        is_const,
                    } => {
                        let scope_id = self
                            .scopes
                            .last()
                            .expect("compound literal evaluation requires a current scope")
                            .id;
                        let name = format!(
                            "__cust_compound_aggregate_field_array#{}",
                            self.next_compound_literal_id
                        );
                        self.next_compound_literal_id += 1;
                        self.current_scope_mut().insert(
                            name.clone(),
                            Value::StructArray {
                                type_name: type_name.clone(),
                                elements: elements
                                    .iter()
                                    .map(StructFieldValue::deep_clone_fields)
                                    .collect(),
                                read_only: *is_const,
                            },
                        );
                        Ok(PointerValue::StructElement {
                            scope_id,
                            name,
                            index: 0,
                        })
                    }
                    StructFieldValue::Scalar { .. } | StructFieldValue::Struct { .. } => {
                        Err(CustError::new("struct field is not a pointer"))
                    }
                }
            }
            _ => Err(CustError::new("expected struct expression")),
        }
    }

    fn checked_shift_left(lhs: i64, rhs: i64) -> CustResult<i64> {
        let shift = Self::checked_shift_count(rhs)?;
        lhs.checked_shl(shift)
            .ok_or_else(|| CustError::new("shift count too large"))
    }

    fn checked_shift_right(lhs: i64, rhs: i64) -> CustResult<i64> {
        let shift = Self::checked_shift_count(rhs)?;
        lhs.checked_shr(shift)
            .ok_or_else(|| CustError::new("shift count too large"))
    }

    fn checked_shift_count(rhs: i64) -> CustResult<u32> {
        if rhs < 0 {
            return Err(CustError::new("shift count must be non-negative"));
        }
        u32::try_from(rhs).map_err(|_| CustError::new("shift count too large"))
    }

    fn reverse_subscript_pointee_type(&self, pointer_expr: &Expr) -> CustResult<PointeeType> {
        if !self.expr_is_pointer_value(pointer_expr) {
            return Err(CustError::new(
                "subscript requires one pointer operand and one scalar operand",
            ));
        }
        self.pointer_expr_pointee_type(pointer_expr)?
            .ok_or_else(|| CustError::new("expected pointer expression"))
    }

    fn scalar_variable_reverse_subscript_pointee_type(
        &self,
        name: &str,
        pointer_expr: &Expr,
    ) -> CustResult<Option<PointeeType>> {
        match self.find_variable(name) {
            Some(Value::Scalar { .. }) => {
                self.reverse_subscript_pointee_type(pointer_expr).map(Some)
            }
            Some(_) | None => Ok(None),
        }
    }

    fn scalar_field_reverse_subscript_pointee_type(
        &self,
        name: &str,
        fields: &[String],
        pointer_expr: &Expr,
    ) -> CustResult<Option<PointeeType>> {
        let is_scalar_field = match self.find_variable(name) {
            Some(Value::Struct {
                type_name,
                fields: field_map,
            }) => matches!(
                Self::nested_field_value(type_name, field_map, fields)?.1,
                StructFieldValue::Scalar { .. }
            ),
            Some(_) | None => false,
        };
        if !is_scalar_field {
            return Ok(None);
        }
        self.reverse_subscript_pointee_type(pointer_expr).map(Some)
    }

    fn sizeof_scalar_variable_reverse_subscript(
        &self,
        name: &str,
        pointer_expr: &Expr,
    ) -> CustResult<Option<i64>> {
        self.scalar_variable_reverse_subscript_pointee_type(name, pointer_expr)?
            .map(|pointee| pointee.size(&self.struct_types))
            .transpose()
    }

    fn sizeof_scalar_field_reverse_subscript(
        &self,
        name: &str,
        fields: &[String],
        pointer_expr: &Expr,
    ) -> CustResult<Option<i64>> {
        self.scalar_field_reverse_subscript_pointee_type(name, fields, pointer_expr)?
            .map(|pointee| pointee.size(&self.struct_types))
            .transpose()
    }

    fn sizeof_reverse_subscript_field(
        &self,
        pointee: PointeeType,
        fields: &[String],
    ) -> CustResult<i64> {
        match pointee {
            PointeeType::Struct(type_name) => self.sizeof_aggregate_field_type(&type_name, fields),
            PointeeType::Scalar(_) => Err(CustError::new(
                "subscript pointer does not reference a struct",
            )),
        }
    }

    fn sizeof_scalar_variable_reverse_subscript_field(
        &self,
        name: &str,
        pointer_expr: &Expr,
        fields: &[String],
    ) -> CustResult<Option<i64>> {
        self.scalar_variable_reverse_subscript_pointee_type(name, pointer_expr)?
            .map(|pointee| self.sizeof_reverse_subscript_field(pointee, fields))
            .transpose()
    }

    fn sizeof_scalar_field_reverse_subscript_field(
        &self,
        name: &str,
        scalar_fields: &[String],
        pointer_expr: &Expr,
        selected_fields: &[String],
    ) -> CustResult<Option<i64>> {
        self.scalar_field_reverse_subscript_pointee_type(name, scalar_fields, pointer_expr)?
            .map(|pointee| self.sizeof_reverse_subscript_field(pointee, selected_fields))
            .transpose()
    }

    fn sizeof_two_dimensional_struct_field_element(
        &self,
        target: &Array2DFieldTarget,
    ) -> CustResult<i64> {
        let metadata = match target {
            Array2DFieldTarget::Direct { name, fields } => match self.find_variable(name) {
                Some(Value::Struct { type_name, .. }) => {
                    self.aggregate_type_field_metadata(type_name, fields)?
                }
                Some(_) => {
                    return Err(CustError::new(format!("variable '{name}' is not a struct")));
                }
                None => return Err(CustError::new(format!("undefined variable '{name}'"))),
            },
            Array2DFieldTarget::Element { name, fields, .. } => {
                self.struct_element_field_metadata(name, fields)?
            }
            Array2DFieldTarget::Pointer { pointer, fields } => {
                self.struct_pointer_expr_field_metadata(pointer, fields)?
            }
        };
        match metadata {
            Some((StructFieldType::Array2D(elem_type, _, _), _, _)) => Ok(elem_type.size()),
            Some(_) => Err(CustError::new("array field is not two-dimensional")),
            None => Err(CustError::new("undefined two-dimensional array field")),
        }
    }

    fn sizeof_expr(&self, expr: &Expr) -> CustResult<i64> {
        self.validate_nested_string_intrinsic_calls(expr)?;
        match expr {
            Expr::Number(_) => Ok(INT_SIZE),
            Expr::StringLiteral(values) => Ok(values.len() as i64 * CHAR_SIZE),
            Expr::ArrayLiteral {
                elem_type,
                len,
                init,
                ..
            } => {
                let len = len.unwrap_or_else(|| Self::infer_array_initializer_len(init));
                Ok(len as i64 * elem_type.size())
            }
            Expr::AggregateArrayLiteral {
                type_name,
                len,
                init,
                ..
            } => {
                let len = len.unwrap_or_else(|| Self::infer_struct_array_initializer_len(init));
                let element_size = self
                    .struct_types
                    .get(type_name)
                    .map(|struct_type| struct_type.size(&self.struct_types))
                    .transpose()?
                    .ok_or_else(|| {
                        CustError::new(format!("undefined struct type '{type_name}'"))
                    })?;
                Ok(len as i64 * element_size)
            }
            Expr::SizeOfType(_) | Expr::SizeOfValue(_) | Expr::AlignOfType(_) => Ok(INT_SIZE),
            Expr::Var(name) => self.sizeof_variable(name),
            Expr::StructGet { name, fields } => self.sizeof_struct_field(name, fields),
            Expr::StructArrayGet {
                name,
                fields,
                index,
            } => match self.sizeof_scalar_field_reverse_subscript(name, fields, index)? {
                Some(size) => Ok(size),
                None => self.sizeof_struct_array_indexed_value(name, fields),
            },
            Expr::StructFieldArrayElementGet {
                name,
                array_fields,
                index,
                fields,
            } => match self.sizeof_scalar_field_reverse_subscript_field(
                name,
                array_fields,
                index,
                fields,
            )? {
                Some(size) => Ok(size),
                None => self.sizeof_struct_field_array_element_field(name, array_fields, fields),
            },
            Expr::StructFieldArrayElementSet {
                name,
                array_fields,
                index,
                fields,
                ..
            }
            | Expr::StructFieldArrayElementCompoundSet {
                name,
                array_fields,
                index,
                fields,
                ..
            } => match self.sizeof_scalar_field_reverse_subscript_field(
                name,
                array_fields,
                index,
                fields,
            )? {
                Some(size) => Ok(size),
                None => self.sizeof_struct_field_array_element_field(name, array_fields, fields),
            },
            Expr::StructElementGet {
                name,
                index,
                fields,
            } => match self.sizeof_scalar_variable_reverse_subscript_field(name, index, fields)? {
                Some(size) => Ok(size),
                None => self.sizeof_struct_element_field(name, fields),
            },
            Expr::StructElementArrayGet { name, fields, .. } => {
                self.sizeof_struct_element_array_indexed_value(name, fields)
            }
            Expr::StructPtrGet { pointer, fields } => {
                self.sizeof_struct_pointer_field(pointer, fields)
            }
            Expr::StructPtrArrayGet {
                pointer, fields, ..
            } => {
                let pointee = self.pointer_expr_pointee_type(&Expr::StructPtrGet {
                    pointer: pointer.clone(),
                    fields: fields.clone(),
                })?;
                match pointee {
                    Some(PointeeType::Scalar(ty)) => Ok(ty.size()),
                    Some(PointeeType::Struct(type_name)) => self
                        .struct_types
                        .get(&type_name)
                        .map(|struct_type| struct_type.size(&self.struct_types))
                        .transpose()?
                        .ok_or_else(|| {
                            CustError::new(format!("undefined struct type '{type_name}'"))
                        }),
                    None => Err(CustError::new("expected pointer expression")),
                }
            }
            Expr::ArrayGet { name, index } => {
                if let Some(size) = self.sizeof_scalar_variable_reverse_subscript(name, index)? {
                    return Ok(size);
                }
                match self.find_variable(name) {
                    Some(Value::StructArray { type_name, .. }) => self
                        .struct_types
                        .get(type_name)
                        .map(|struct_type| struct_type.size(&self.struct_types))
                        .transpose()?
                        .ok_or_else(|| {
                            CustError::new(format!("undefined struct type '{type_name}'"))
                        }),
                    _ => self.sizeof_indexed_value(name),
                }
            }
            Expr::Array2DGet { name, .. }
            | Expr::Array2DSet { name, .. }
            | Expr::Array2DCompoundSet { name, .. } => self.sizeof_indexed_value(name),
            Expr::StructArray2DGet { target, .. } => {
                self.sizeof_two_dimensional_struct_field_element(target)
            }
            Expr::StructArray2DSet { target, .. }
            | Expr::StructArray2DCompoundSet { target, .. } => {
                self.sizeof_two_dimensional_struct_field_element(target)
            }
            Expr::StringGet { .. } => Ok(CHAR_SIZE),
            Expr::AddressOf(_)
            | Expr::AddressOfArray { .. }
            | Expr::AddressOfStructField { .. }
            | Expr::AddressOfStructElementField { .. }
            | Expr::AddressOfStructArrayField { .. }
            | Expr::AddressOfStructElementArrayField { .. }
            | Expr::AddressOfStructPtrField { .. }
            | Expr::AddressOfStructPtrArrayField { .. }
            | Expr::AddressOfScalarLiteral { .. }
            | Expr::AddressOfAggregateLiteral { .. }
            | Expr::AddressOfAggregateField { .. }
            | Expr::PointerCast { .. } => Ok(POINTER_SIZE),
            Expr::Deref(pointer) => self.sizeof_deref(pointer),
            Expr::Assign { name, .. } | Expr::CompoundAssign { name, .. } => {
                self.sizeof_assignment_result(name)
            }
            Expr::ArraySet { name, index, .. } | Expr::ArrayCompoundSet { name, index, .. } => {
                if let Some(size) = self.sizeof_scalar_variable_reverse_subscript(name, index)? {
                    Ok(size)
                } else {
                    self.sizeof_indexed_value(name)
                }
            }
            Expr::DerefSet { pointer, .. } | Expr::DerefCompoundSet { pointer, .. } => {
                self.sizeof_deref(pointer)
            }
            Expr::StructSet { name, fields, .. } | Expr::StructCompoundSet { name, fields, .. } => {
                self.sizeof_struct_field(name, fields)
            }
            Expr::StructArraySet {
                name,
                fields,
                index,
                ..
            }
            | Expr::StructArrayCompoundSet {
                name,
                fields,
                index,
                ..
            } => match self.sizeof_scalar_field_reverse_subscript(name, fields, index)? {
                Some(size) => Ok(size),
                None => self.sizeof_struct_array_indexed_value(name, fields),
            },
            Expr::StructElementSet {
                name,
                index,
                fields,
                ..
            }
            | Expr::StructElementCompoundSet {
                name,
                index,
                fields,
                ..
            } => match self.sizeof_scalar_variable_reverse_subscript_field(name, index, fields)? {
                Some(size) => Ok(size),
                None => self.sizeof_struct_element_field(name, fields),
            },
            Expr::StructElementArraySet { name, fields, .. }
            | Expr::StructElementArrayCompoundSet { name, fields, .. } => {
                self.sizeof_struct_element_array_indexed_value(name, fields)
            }
            Expr::StructPtrSet {
                pointer, fields, ..
            }
            | Expr::StructPtrCompoundSet {
                pointer, fields, ..
            } => self.sizeof_struct_pointer_field(pointer, fields),
            Expr::Increment { target, .. } => self.sizeof_expr(target),
            Expr::VoidCast(_) => Err(CustError::new("void expression used as scalar")),
            Expr::Cast { ty, .. }
            | Expr::ScalarLiteral { ty, .. }
            | Expr::ScalarLiteralSet { ty, .. }
            | Expr::ScalarLiteralCompoundSet { ty, .. } => Ok(ty.size()),
            Expr::AggregateLiteral { type_name, .. } => self
                .struct_types
                .get(type_name)
                .map(|struct_type| struct_type.size(&self.struct_types))
                .transpose()?
                .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
            Expr::AggregateFieldGet { aggregate, fields }
            | Expr::AggregateFieldSet {
                aggregate, fields, ..
            }
            | Expr::AggregateFieldCompoundSet {
                aggregate, fields, ..
            } => {
                let type_name = self.aggregate_expr_type_name(aggregate)?;
                self.sizeof_aggregate_field_type(&type_name, fields)
            }
            Expr::Call { name, args } => match self.functions.get(name) {
                Some(function) => function
                    .return_type
                    .size(&self.struct_types)
                    .ok_or_else(|| {
                        CustError::new(format!("void function '{name}' used as scalar expression"))
                    }),
                None if self.has_integer_absolute_value_prototype(name) => Ok(INT_SIZE),
                None if self.has_integer_string_conversion_prototype(name) => {
                    self.sizeof_integer_string_conversion_call(name, args)
                }
                None if self.has_string_comparison_prototype(name) => {
                    self.sizeof_string_comparison_call(name, args)
                }
                None if self.has_string_prefix_comparison_prototype(name) => {
                    self.sizeof_string_prefix_comparison_call(name, args)
                }
                None if self.has_string_length_prototype(name) => {
                    self.sizeof_string_length_call(name, args)
                }
                None if self.has_character_search_prototype(name) => {
                    self.sizeof_character_search_call(name, args)
                }
                None if self.has_character_set_search_prototype(name) => {
                    self.sizeof_character_set_search_call(name, args)
                }
                None if self.has_string_copy_prototype(name) => {
                    self.sizeof_string_copy_call(name, args)
                }
                None if self.has_string_span_prototype(name) => {
                    self.sizeof_string_span_call(name, args)
                }
                None if name == "strncmp" && self.prototypes.contains_key(name) => {
                    Err(CustError::new(
                        "standard library function 'strncmp' has an unsupported declaration; expected two pointer-to-const-character parameters, one integer count, and an integer return type",
                    ))
                }
                None if name == "strlen" && self.prototypes.contains_key(name) => {
                    Err(CustError::new(
                        "standard library function 'strlen' has an unsupported declaration; expected one pointer-to-const-character parameter and an integer return type",
                    ))
                }
                None if matches!(name.as_str(), "strchr" | "strrchr")
                    && self.prototypes.contains_key(name) =>
                {
                    Err(CustError::new(format!(
                        "standard library function '{name}' has an unsupported declaration; expected one pointer-to-const-character parameter, one integer search value, and a pointer-to-character return type"
                    )))
                }
                None if matches!(name.as_str(), "strpbrk" | "strstr")
                    && self.prototypes.contains_key(name) =>
                {
                    Err(CustError::new(format!(
                        "standard library function '{name}' has an unsupported declaration; expected two pointer-to-const-character parameters and a pointer-to-character return type"
                    )))
                }
                None if name == "strcpy" && self.prototypes.contains_key(name) => {
                    Err(CustError::new(
                        "standard library function 'strcpy' has an unsupported declaration; expected one pointer-to-character destination parameter, one pointer-to-const-character source parameter, and a pointer-to-character return type",
                    ))
                }
                None if matches!(name.as_str(), "strspn" | "strcspn")
                    && self.prototypes.contains_key(name) =>
                {
                    Err(CustError::new(format!(
                        "standard library function '{name}' has an unsupported declaration; expected two pointer-to-const-character parameters and an integer return type"
                    )))
                }
                None => Err(CustError::new(format!("undefined function '{name}'"))),
            },
            Expr::UnaryPlus(_)
            | Expr::UnaryMinus(_)
            | Expr::BitwiseNot(_)
            | Expr::LogicalNot(_)
            | Expr::Binary(_, _, _) => Ok(INT_SIZE),
            Expr::Conditional { .. } => self.sizeof_conditional_expr(expr),
            Expr::Comma(_, right) => self.sizeof_expr(right),
        }
    }

    fn sizeof_conditional_expr(&self, expr: &Expr) -> CustResult<i64> {
        match self.aggregate_expr_type_name(expr) {
            Ok(type_name) => self
                .struct_types
                .get(&type_name)
                .map(|struct_type| struct_type.size(&self.struct_types))
                .transpose()?
                .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
            Err(err)
                if err
                    .to_string()
                    .contains("conditional branches have mismatched aggregate types") =>
            {
                Err(err)
            }
            Err(_) => {
                if self.pointer_expr_pointee_type(expr)?.is_some() {
                    Ok(POINTER_SIZE)
                } else {
                    Ok(INT_SIZE)
                }
            }
        }
    }

    fn aggregate_expr_type_name(&self, expr: &Expr) -> CustResult<String> {
        match expr {
            Expr::AggregateLiteral { type_name, .. } => Ok(type_name.clone()),
            Expr::AggregateFieldGet { aggregate, fields } => {
                let type_name = self.aggregate_expr_type_name(aggregate)?;
                self.aggregate_field_type_name(&type_name, fields)
            }
            Expr::Var(name) | Expr::Assign { name, .. } => match self.find_variable(name) {
                Some(Value::Struct { type_name, .. }) => Ok(type_name.clone()),
                Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
                None => Err(CustError::new(format!("undefined variable '{name}'"))),
            },
            Expr::ArraySet { name, .. } => match self.find_variable(name) {
                Some(Value::StructArray { type_name, .. }) => Ok(type_name.clone()),
                Some(Value::Pointer {
                    ty: PointeeType::Struct(type_name),
                    ..
                }) => Ok(type_name.clone()),
                _ => Err(CustError::new("expected struct expression")),
            },
            Expr::StructArraySet { name, fields, .. } => {
                if let Some(type_name) =
                    self.direct_struct_aggregate_array_field_type(name, fields)?
                {
                    return Ok(type_name);
                }
                match self.find_variable(name) {
                    Some(Value::Struct { type_name, .. }) => {
                        self.aggregate_field_type_name(type_name, fields)
                    }
                    Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
                    None => Err(CustError::new(format!("undefined variable '{name}'"))),
                }
            }
            Expr::StructElementArrayGet { name, fields, .. }
            | Expr::StructElementArraySet { name, fields, .. } => {
                match self.struct_element_field_metadata(name, fields)? {
                    Some((StructFieldType::Pointer(PointeeType::Struct(type_name)), _, _)) => {
                        Ok(type_name)
                    }
                    Some((StructFieldType::StructArray(type_name, _), _, _)) => Ok(type_name),
                    _ => Err(CustError::new("expected struct expression")),
                }
            }
            Expr::StructGet { name, fields } | Expr::StructSet { name, fields, .. } => {
                match self.find_variable(name) {
                    Some(Value::Struct { type_name, .. }) => {
                        self.aggregate_field_type_name(type_name, fields)
                    }
                    Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
                    None => Err(CustError::new(format!("undefined variable '{name}'"))),
                }
            }
            Expr::StructPtrSet {
                pointer, fields, ..
            } => match self.pointer_expr_pointee_type(pointer)? {
                Some(PointeeType::Struct(type_name)) => {
                    self.aggregate_field_type_name(&type_name, fields)
                }
                _ => Err(CustError::new("expected struct expression")),
            },
            Expr::ArrayGet { name, .. } => match self.find_variable(name) {
                Some(Value::StructArray { type_name, .. }) => Ok(type_name.clone()),
                Some(Value::Pointer {
                    ty: PointeeType::Struct(type_name),
                    ..
                }) => Ok(type_name.clone()),
                _ => Err(CustError::new("expected struct expression")),
            },
            Expr::Deref(pointer) | Expr::DerefSet { pointer, .. } => {
                match self.pointer_expr_pointee_type(pointer)? {
                    Some(PointeeType::Struct(type_name)) => Ok(type_name),
                    _ => Err(CustError::new("expected struct expression")),
                }
            }
            Expr::Call { name, .. } => match self.functions.get(name) {
                Some(function) => match &function.return_type {
                    ReturnType::Struct(type_name) => Ok(type_name.clone()),
                    ReturnType::Scalar(_) => Err(CustError::new(format!(
                        "scalar function '{name}' used as struct expression"
                    ))),
                    ReturnType::Pointer { .. } | ReturnType::Array2DPointer { .. } => {
                        Err(CustError::new(format!(
                            "pointer function '{name}' used as struct expression"
                        )))
                    }
                    ReturnType::Void => Err(CustError::new(format!(
                        "void function '{name}' used as struct expression"
                    ))),
                },
                None => Err(CustError::new(format!("undefined function '{name}'"))),
            },
            Expr::Conditional {
                then_expr,
                else_expr,
                ..
            } => {
                let then_type = self.aggregate_expr_type_name(then_expr)?;
                let else_type = self.aggregate_expr_type_name(else_expr)?;
                if then_type == else_type {
                    Ok(then_type)
                } else {
                    Err(CustError::new(format!(
                        "conditional branches have mismatched aggregate types: {} vs {}",
                        self.aggregate_label(&then_type),
                        self.aggregate_label(&else_type)
                    )))
                }
            }
            Expr::Comma(_, right) => self.aggregate_expr_type_name(right),
            _ => Err(CustError::new("expected struct expression")),
        }
    }

    fn aggregate_field_type_name(&self, type_name: &str, path: &[String]) -> CustResult<String> {
        let mut current_type_name = type_name.to_string();
        for (index, field_name) in path.iter().enumerate() {
            let struct_type = self.struct_types.get(&current_type_name).ok_or_else(|| {
                CustError::new(format!("undefined struct type '{current_type_name}'"))
            })?;
            let field = struct_type
                .fields
                .iter()
                .find(|field| field.name == *field_name)
                .ok_or_else(|| {
                    CustError::new(format!(
                        "struct '{current_type_name}' has no field '{field_name}'"
                    ))
                })?;
            let is_last = index + 1 == path.len();
            match &field.ty {
                StructFieldType::Struct(nested_type) if is_last => return Ok(nested_type.clone()),
                StructFieldType::Struct(nested_type) => current_type_name = nested_type.clone(),
                _ => return Err(CustError::new("expected struct expression")),
            }
        }
        Ok(current_type_name)
    }

    fn sizeof_aggregate_field_type(&self, type_name: &str, path: &[String]) -> CustResult<i64> {
        let mut current_type_name = type_name.to_string();
        for (index, field_name) in path.iter().enumerate() {
            let struct_type = self.struct_types.get(&current_type_name).ok_or_else(|| {
                CustError::new(format!("undefined struct type '{current_type_name}'"))
            })?;
            let field = struct_type
                .fields
                .iter()
                .find(|field| field.name == *field_name)
                .ok_or_else(|| {
                    CustError::new(format!(
                        "struct '{current_type_name}' has no field '{field_name}'"
                    ))
                })?;
            let is_last = index + 1 == path.len();
            match &field.ty {
                StructFieldType::Scalar(ty) if is_last => return Ok(ty.size()),
                StructFieldType::Array(elem_type, len) if is_last => {
                    return Ok(*len as i64 * elem_type.size());
                }
                StructFieldType::Array2D(elem_type, rows, columns) if is_last => {
                    return Ok(*rows as i64 * *columns as i64 * elem_type.size());
                }
                StructFieldType::Struct(nested_type) if is_last => {
                    return self
                        .struct_types
                        .get(nested_type)
                        .map(|struct_type| struct_type.size(&self.struct_types))
                        .transpose()?
                        .ok_or_else(|| {
                            CustError::new(format!("undefined struct type '{nested_type}'"))
                        });
                }
                StructFieldType::Struct(nested_type) => current_type_name = nested_type.clone(),
                StructFieldType::Pointer(_) if is_last => return Ok(POINTER_SIZE),
                StructFieldType::StructArray(element_type, len) if is_last => {
                    let element_size = self
                        .struct_types
                        .get(element_type)
                        .map(|struct_type| struct_type.size(&self.struct_types))
                        .transpose()?
                        .ok_or_else(|| {
                            CustError::new(format!("undefined struct type '{element_type}'"))
                        })?;
                    return Ok(element_size * *len as i64);
                }
                _ => return Err(CustError::new("expected struct expression")),
            }
        }
        self.struct_types
            .get(type_name)
            .map(|struct_type| struct_type.size(&self.struct_types))
            .transpose()?
            .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'")))
    }

    fn struct_field_value_size(&self, field_value: &StructFieldValue) -> CustResult<i64> {
        match field_value {
            StructFieldValue::Scalar { ty, .. } => Ok(ty.size()),
            StructFieldValue::Array { value, .. } => {
                let array = value.borrow();
                Ok(array.elements.len() as i64 * array.elem_type.size())
            }
            StructFieldValue::Struct { type_name, .. } => self
                .struct_types
                .get(type_name)
                .map(|struct_type| struct_type.size(&self.struct_types))
                .transpose()?
                .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
            StructFieldValue::StructArray {
                type_name,
                elements,
                ..
            } => self
                .struct_types
                .get(type_name)
                .map(|struct_type| {
                    struct_type
                        .size(&self.struct_types)
                        .map(|size| size * elements.len() as i64)
                })
                .transpose()?
                .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
            StructFieldValue::Pointer { .. } => Ok(POINTER_SIZE),
        }
    }

    fn sizeof_variable(&self, name: &str) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::Scalar { ty, .. }) => Ok(ty.size()),
            Some(Value::Array(array)) => {
                let array = array.borrow();
                Ok(array.elements.len() as i64 * array.elem_type.size())
            }
            Some(Value::Pointer { .. }) => Ok(POINTER_SIZE),
            Some(Value::Struct { type_name, .. }) => self
                .struct_types
                .get(type_name)
                .map(|struct_type| struct_type.size(&self.struct_types))
                .transpose()?
                .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
            Some(Value::StructArray {
                type_name,
                elements,
                ..
            }) => self
                .struct_types
                .get(type_name)
                .map(|struct_type| struct_type.size(&self.struct_types))
                .transpose()?
                .map(|element_size| element_size * elements.len() as i64)
                .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn sizeof_struct_field(&self, name: &str, path: &[String]) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::Struct { type_name, fields }) => {
                let (_, field_value) = Self::nested_field_value(type_name, fields, path)?;
                self.struct_field_value_size(field_value)
            }
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn sizeof_struct_pointer_field(&self, pointer: &Expr, path: &[String]) -> CustResult<i64> {
        let Some(PointeeType::Struct(type_name)) = self.pointer_expr_pointee_type(pointer)? else {
            return Err(CustError::new("expected pointer expression"));
        };
        self.sizeof_aggregate_field_type(&type_name, path)
    }

    fn sizeof_struct_array_indexed_value(&self, name: &str, path: &[String]) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::Struct { type_name, fields }) => {
                let (_, field_value) = Self::nested_field_value(type_name, fields, path)?;
                match field_value {
                    StructFieldValue::Array { value, .. } => Ok(value.borrow().elem_type.size()),
                    StructFieldValue::StructArray { type_name, .. } => self
                        .struct_types
                        .get(type_name)
                        .map(|struct_type| struct_type.size(&self.struct_types))
                        .transpose()?
                        .ok_or_else(|| {
                            CustError::new(format!("undefined struct type '{type_name}'"))
                        }),
                    StructFieldValue::Scalar { .. } | StructFieldValue::Pointer { .. } => {
                        Err(CustError::new(format!(
                            "struct field '{}' is not an array",
                            Self::field_path_label(path)
                        )))
                    }
                    StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct '{type_name}'",
                        Self::field_path_label(path)
                    ))),
                }
            }
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn sizeof_struct_element_field(&self, name: &str, path: &[String]) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::StructArray {
                type_name,
                elements,
                ..
            }) => {
                let Some(first_element) = elements.first() else {
                    return Err(CustError::new(format!(
                        "struct array '{name}' has no elements"
                    )));
                };
                let (_, field_value) = Self::nested_field_value(type_name, first_element, path)?;
                self.struct_field_value_size(field_value)
            }
            Some(Value::Pointer {
                ty: PointeeType::Struct(type_name),
                ..
            }) => self.sizeof_aggregate_field_type(type_name, path),
            Some(_) => Err(CustError::new(format!(
                "variable '{name}' is not a struct array"
            ))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn sizeof_struct_element_array_indexed_value(
        &self,
        name: &str,
        path: &[String],
    ) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::StructArray {
                type_name,
                elements,
                ..
            }) => {
                let Some(first_element) = elements.first() else {
                    return Err(CustError::new(format!(
                        "struct array '{name}' has no elements"
                    )));
                };
                let (_, field_value) = Self::nested_field_value(type_name, first_element, path)?;
                match field_value {
                    StructFieldValue::Array { value, .. } => Ok(value.borrow().elem_type.size()),
                    StructFieldValue::StructArray { type_name, .. } => self
                        .struct_types
                        .get(type_name)
                        .map(|struct_type| struct_type.size(&self.struct_types))
                        .transpose()?
                        .ok_or_else(|| {
                            CustError::new(format!("undefined struct type '{type_name}'"))
                        }),
                    StructFieldValue::Pointer { ty, .. } => ty.size(&self.struct_types),
                    StructFieldValue::Scalar { .. } => Err(CustError::new(format!(
                        "struct field '{}' is not an array",
                        Self::field_path_label(path)
                    ))),
                    StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct '{type_name}'",
                        Self::field_path_label(path)
                    ))),
                }
            }
            Some(Value::Pointer {
                ty: PointeeType::Struct(type_name),
                ..
            }) => match self.aggregate_type_field_metadata(type_name, path)? {
                Some((StructFieldType::Array(elem_type, _), _, _)) => Ok(elem_type.size()),
                Some((StructFieldType::Array2D(_, _, _), _, _)) => Err(CustError::new(format!(
                    "two-dimensional array field '{}' requires a second index",
                    Self::field_path_label(path)
                ))),
                Some((StructFieldType::StructArray(type_name, _), _, _)) => self
                    .struct_types
                    .get(&type_name)
                    .map(|struct_type| struct_type.size(&self.struct_types))
                    .transpose()?
                    .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
                Some((StructFieldType::Pointer(ty), _, _)) => ty.size(&self.struct_types),
                Some((StructFieldType::Scalar(_), _, _)) => Err(CustError::new(format!(
                    "struct field '{}' is not an array",
                    Self::field_path_label(path)
                ))),
                Some((StructFieldType::Struct(type_name), _, _)) => Err(CustError::new(format!(
                    "struct field '{}' is a struct '{type_name}'",
                    Self::field_path_label(path)
                ))),
                None => Err(CustError::new(format!(
                    "undefined struct field '{}'",
                    Self::field_path_label(path)
                ))),
            },
            Some(_) => Err(CustError::new(format!(
                "variable '{name}' is not a struct array"
            ))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn sizeof_struct_field_array_element_field(
        &self,
        name: &str,
        array_path: &[String],
        field_path: &[String],
    ) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::Struct { type_name, fields }) => {
                let (_, field_value) = Self::nested_field_value(type_name, fields, array_path)?;
                match field_value {
                    StructFieldValue::StructArray { type_name, .. } => {
                        if field_path.is_empty() {
                            return self
                                .struct_types
                                .get(type_name)
                                .map(|struct_type| struct_type.size(&self.struct_types))
                                .transpose()?
                                .ok_or_else(|| {
                                    CustError::new(format!("undefined struct type '{type_name}'"))
                                });
                        }
                        self.sizeof_aggregate_field_type(type_name, field_path)
                    }
                    StructFieldValue::Array { .. } => Err(CustError::new(format!(
                        "struct field '{}' is not a struct array",
                        Self::field_path_label(array_path)
                    ))),
                    StructFieldValue::Scalar { .. } | StructFieldValue::Pointer { .. } => {
                        Err(CustError::new(format!(
                            "struct field '{}' is not an array",
                            Self::field_path_label(array_path)
                        )))
                    }
                    StructFieldValue::Struct { type_name, .. } => Err(CustError::new(format!(
                        "struct field '{}' is a struct '{type_name}'",
                        Self::field_path_label(array_path)
                    ))),
                }
            }
            Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn sizeof_assignment_result(&self, name: &str) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::Scalar { ty, .. }) => Ok(ty.size()),
            Some(Value::Pointer { .. }) => Ok(POINTER_SIZE),
            Some(Value::Array(_)) => Err(CustError::new(format!(
                "array '{name}' requires indexed assignment"
            ))),
            Some(Value::Struct { type_name, .. }) => self
                .struct_types
                .get(type_name)
                .map(|struct_type| struct_type.size(&self.struct_types))
                .transpose()?
                .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
            Some(Value::StructArray { .. }) => Err(CustError::new(format!(
                "struct variable '{name}' assignment is not supported"
            ))),
            None if self.find_enum_constant(name).is_some() => Err(CustError::new(format!(
                "cannot assign to enum constant '{name}'"
            ))),
            None => Err(CustError::new(format!(
                "assignment to undeclared variable '{name}'"
            ))),
        }
    }

    fn sizeof_indexed_value(&self, name: &str) -> CustResult<i64> {
        match self.find_variable(name) {
            Some(Value::Array(array)) => Ok(array.borrow().elem_type.size()),
            Some(Value::Pointer { ty, .. }) => Ok(ty.size(&self.struct_types)?),
            Some(Value::StructArray { type_name, .. }) => self
                .struct_types
                .get(type_name)
                .map(|struct_type| struct_type.size(&self.struct_types))
                .transpose()?
                .ok_or_else(|| CustError::new(format!("undefined struct type '{type_name}'"))),
            Some(Value::Scalar { .. }) => {
                Err(CustError::new(format!("variable '{name}' is not an array")))
            }
            Some(Value::Struct { .. }) => Err(CustError::new(format!(
                "struct variable '{name}' is not an array"
            ))),
            None => Err(CustError::new(format!("undefined variable '{name}'"))),
        }
    }

    fn sizeof_deref(&self, pointer: &Expr) -> CustResult<i64> {
        if let Some(ty) = self.pointer_expr_pointee_type(pointer)? {
            return ty.size(&self.struct_types);
        }
        match pointer {
            Expr::Var(name) => match self.find_variable(name) {
                Some(Value::Scalar { .. }) => Err(CustError::new(format!(
                    "variable '{name}' is not a pointer"
                ))),
                Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => Err(
                    CustError::new(format!("struct variable '{name}' used as pointer")),
                ),
                None => Err(CustError::new(format!("undefined variable '{name}'"))),
                Some(Value::Pointer { .. } | Value::Array(_)) => {
                    unreachable!("pointer-like variables should have returned a pointee type")
                }
            },
            _ => Ok(INT_SIZE),
        }
    }

    fn eval_increment_expr(
        &mut self,
        target: &Expr,
        op: IncrementOp,
        prefix: bool,
    ) -> CustResult<i64> {
        match target {
            Expr::Var(name) => match self.find_variable(name).cloned() {
                Some(Value::Scalar {
                    value: current, ty, ..
                }) => {
                    self.ensure_variable_mutable(name)?;
                    let updated = ty.normalize(Self::apply_increment_op(current, op));
                    if let Some(Value::Scalar { value: slot, .. }) = self.find_variable_mut(name) {
                        *slot = updated;
                    }
                    Ok(Self::increment_result(current, updated, prefix))
                }
                Some(Value::Pointer { .. }) => {
                    Err(CustError::new("pointer arithmetic is not supported"))
                }
                Some(Value::Array(_)) => Err(CustError::new(format!(
                    "array '{name}' requires indexed assignment"
                ))),
                Some(Value::Struct { .. }) | Some(Value::StructArray { .. }) => {
                    Err(CustError::new(format!(
                        "struct variable '{name}' assignment is not supported"
                    )))
                }
                None => Err(CustError::new(format!("undefined variable '{name}'"))),
            },
            Expr::ArrayGet { name, index } => {
                if let Some(pointer) =
                    self.scalar_variable_reverse_subscript_pointer(name, index)?
                {
                    let current = self.deref_pointer(&pointer)?;
                    let updated = Self::apply_increment_op(current, op);
                    self.ensure_reverse_subscript_pointee_mutable(index)?;
                    self.assign_deref_pointer(&pointer, updated)?;
                    return Ok(Self::increment_result(current, updated, prefix));
                }
                let (array, index) = match self.find_variable(name).cloned() {
                    Some(Value::Pointer { pointer, .. }) => {
                        self.ensure_pointer_variable_pointee_mutable(name)?;
                        let index_value = self.eval(index)?;
                        let (array, _, index, _) =
                            self.checked_pointer_value_index(&pointer, index_value)?;
                        (array, index)
                    }
                    Some(_) | None => self.checked_array_index(name, index)?,
                };
                let current = array.borrow().elements[index];
                let updated = array
                    .borrow()
                    .elem_type
                    .normalize(Self::apply_increment_op(current, op));
                let mut array = array.borrow_mut();
                if array.read_only {
                    return Err(CustError::new(format!(
                        "cannot modify read-only array '{name}'"
                    )));
                }
                array.elements[index] = updated;
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::Array2DGet { name, row, column } => {
                let (array, index) = self.checked_two_dimensional_array_index(name, row, column)?;
                self.ensure_two_dimensional_array_mutable(name)?;
                let current = array.borrow().elements[index];
                let updated = array
                    .borrow()
                    .elem_type
                    .normalize(Self::apply_increment_op(current, op));
                let mut array = array.borrow_mut();
                if array.read_only {
                    return Err(CustError::new(format!(
                        "cannot modify read-only array '{name}'"
                    )));
                }
                array.elements[index] = updated;
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::StructArray2DGet {
                target,
                row,
                column,
            } => {
                self.ensure_two_dimensional_struct_field_target_mutable(target)?;
                let (array, index) =
                    self.checked_two_dimensional_struct_field_index(target, row, column)?;
                let current = array.borrow().elements[index];
                let updated = array
                    .borrow()
                    .elem_type
                    .normalize(Self::apply_increment_op(current, op));
                let mut array = array.borrow_mut();
                if array.read_only {
                    return Err(CustError::new("cannot modify read-only array field"));
                }
                array.elements[index] = updated;
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::StructArrayGet {
                name,
                fields,
                index,
            } => {
                if let Some(pointer) =
                    self.scalar_field_reverse_subscript_pointer(name, fields, index)?
                {
                    let current = self.deref_pointer(&pointer)?;
                    let updated = Self::apply_increment_op(current, op);
                    self.ensure_reverse_subscript_pointee_mutable(index)?;
                    self.assign_deref_pointer(&pointer, updated)?;
                    return Ok(Self::increment_result(current, updated, prefix));
                }
                self.ensure_variable_mutable(name)?;
                let (array, index) = self.checked_struct_array_index(name, fields, index)?;
                let current = array.borrow().elements[index];
                let updated = array
                    .borrow()
                    .elem_type
                    .normalize(Self::apply_increment_op(current, op));
                let mut array = array.borrow_mut();
                if array.read_only {
                    return Err(CustError::new(format!(
                        "cannot modify read-only array '{}'",
                        Self::field_path_label(fields)
                    )));
                }
                array.elements[index] = updated;
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::StructFieldArrayElementGet {
                name,
                array_fields,
                index,
                fields,
            } => {
                let pointer =
                    self.struct_field_array_element_assignment_pointer(name, array_fields, index)?;
                let current = self.read_struct_pointer_field(&pointer, fields)?;
                let updated = Self::apply_increment_op(current, op);
                self.assign_struct_pointer_field(&pointer, fields, updated)?;
                let updated = self.read_struct_pointer_field(&pointer, fields)?;
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::StructElementGet {
                name,
                index,
                fields,
            } => {
                let current = self.read_struct_element_field(name, index, fields)?;
                let updated = Self::apply_increment_op(current, op);
                self.assign_struct_element_field(name, index, fields, updated)?;
                let updated = self.read_struct_element_field(name, index, fields)?;
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::StructElementArrayGet {
                name,
                index,
                fields,
                array_index,
            } => {
                if let Some((StructFieldType::Pointer(_), _, points_to_const)) =
                    self.struct_element_field_metadata(name, fields)?
                {
                    if points_to_const {
                        return Err(CustError::new("cannot assign through pointer to const"));
                    }
                    let element_pointer = self.indexed_struct_element_pointer(name, index)?;
                    let field_element_pointer = self.struct_pointer_pointer_field_index_pointer(
                        &element_pointer,
                        fields,
                        array_index,
                    )?;
                    let current = self.deref_pointer(&field_element_pointer)?;
                    let updated = Self::apply_increment_op(current, op);
                    self.assign_deref_pointer(&field_element_pointer, updated)?;
                    Ok(Self::increment_result(current, updated, prefix))
                } else {
                    self.ensure_struct_element_array_field_mutable(name, fields)?;
                    let (array, index) =
                        self.checked_struct_element_array_index(name, index, fields, array_index)?;
                    let current = array.borrow().elements[index];
                    let updated = Self::apply_increment_op(current, op);
                    let mut array = array.borrow_mut();
                    if array.read_only {
                        return Err(CustError::new(format!(
                            "cannot modify read-only array '{}'",
                            Self::field_path_label(fields)
                        )));
                    }
                    array.elements[index] = updated;
                    Ok(Self::increment_result(current, updated, prefix))
                }
            }
            Expr::StructGet { name, fields } => {
                let current = self.read_struct_field(name, fields)?;
                let updated = Self::apply_increment_op(current, op);
                self.assign_struct_field(name, fields, updated)?;
                let updated = self.read_struct_field(name, fields)?;
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::StructPtrGet { pointer, fields } => {
                self.ensure_pointer_expr_pointee_mutable(pointer)?;
                let pointer = self.eval_pointer(pointer)?;
                let current = self.read_struct_pointer_field(&pointer, fields)?;
                let updated = Self::apply_increment_op(current, op);
                self.assign_struct_pointer_field(&pointer, fields, updated)?;
                let updated = self.read_struct_pointer_field(&pointer, fields)?;
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::Deref(pointer) => {
                self.ensure_pointer_expr_pointee_mutable(pointer)?;
                let pointer = self.eval_pointer(pointer)?;
                let current = self.deref_pointer(&pointer)?;
                let updated = Self::apply_increment_op(current, op);
                self.assign_deref_pointer(&pointer, updated)?;
                let updated = self.deref_pointer(&pointer)?;
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::ScalarLiteral { ty, init } => {
                let current = self.eval_scalar_conversion(*ty, init)?;
                let updated = ty.normalize(Self::apply_increment_op(current, op));
                Ok(Self::increment_result(current, updated, prefix))
            }
            Expr::AggregateFieldGet { aggregate, fields } => {
                let (current, ty, is_const) =
                    self.eval_aggregate_literal_field_scalar(aggregate, fields)?;
                if is_const {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(fields)
                    )));
                }
                let updated = ty.normalize(Self::apply_increment_op(current, op));
                Ok(Self::increment_result(current, updated, prefix))
            }
            _ => Err(CustError::new("invalid increment/decrement target")),
        }
    }

    fn eval_array_compound_set(
        &mut self,
        name: &str,
        index: &Expr,
        op: CompoundOp,
        value: &Expr,
    ) -> CustResult<i64> {
        if let Some(pointer) = self.scalar_variable_reverse_subscript_pointer(name, index)? {
            self.ensure_reverse_subscript_pointee_mutable(index)?;
            let current = self.deref_pointer(&pointer)?;
            let rhs = self.eval(value)?;
            let result = Self::apply_compound_op(current, op, rhs)?;
            self.assign_deref_pointer(&pointer, result)?;
            return Ok(result);
        }
        let (array, index) = match self.find_variable(name).cloned() {
            Some(Value::Pointer { pointer, .. }) => {
                self.ensure_pointer_variable_pointee_mutable(name)?;
                let index_value = self.eval(index)?;
                let (array, _, index, _) =
                    self.checked_pointer_value_index(&pointer, index_value)?;
                (array, index)
            }
            Some(_) | None => self.checked_array_index(name, index)?,
        };
        let current = array.borrow().elements[index];
        let rhs = self.eval(value)?;
        let elem_type = array.borrow().elem_type;
        let result = elem_type.normalize(Self::apply_compound_op(current, op, rhs)?);
        let mut array = array.borrow_mut();
        if array.read_only {
            return Err(CustError::new(format!(
                "cannot modify read-only array '{name}'"
            )));
        }
        array.elements[index] = result;
        Ok(result)
    }

    fn eval_deref_compound_set(
        &mut self,
        pointer: &Expr,
        op: CompoundOp,
        value: &Expr,
    ) -> CustResult<i64> {
        self.ensure_pointer_expr_pointee_mutable(pointer)?;
        let pointer = self.eval_pointer(pointer)?;
        let current = self.deref_pointer(&pointer)?;
        let rhs = self.eval(value)?;
        let result = Self::apply_compound_op(current, op, rhs)?;
        self.assign_deref_pointer(&pointer, result)?;
        self.deref_pointer(&pointer)
    }

    fn eval_equality(&mut self, left: &Expr, op: &BinaryOp, right: &Expr) -> CustResult<i64> {
        let left_is_pointer = self.expr_is_pointer_value(left);
        let right_is_pointer = self.expr_is_pointer_value(right);

        let equal = match (left_is_pointer, right_is_pointer) {
            (false, false) => self.eval(left)? == self.eval(right)?,
            (true, true) => {
                let left_pointer = self.eval_pointer(left)?;
                let right_pointer = self.eval_pointer(right)?;
                Self::pointer_eq(&left_pointer, &right_pointer)
            }
            (true, false) => {
                let pointer = self.eval_pointer(left)?;
                let value = self.eval(right)?;
                if value != 0 {
                    return Err(CustError::new(
                        "cannot compare pointer with nonzero integer",
                    ));
                }
                Self::pointer_eq(&pointer, &PointerValue::Null)
            }
            (false, true) => {
                let value = self.eval(left)?;
                let pointer = self.eval_pointer(right)?;
                if value != 0 {
                    return Err(CustError::new(
                        "cannot compare pointer with nonzero integer",
                    ));
                }
                Self::pointer_eq(&PointerValue::Null, &pointer)
            }
        };

        match op {
            BinaryOp::Eq => Ok(equal as i64),
            BinaryOp::Ne => Ok((!equal) as i64),
            _ => unreachable!("only equality operators use eval_equality"),
        }
    }

    fn eval_struct_expr(&mut self, expr: &Expr) -> CustResult<ReturnValue> {
        match expr {
            Expr::Conditional {
                cond,
                then_expr,
                else_expr,
            } => {
                if self.eval_truthy(cond)? {
                    self.eval_struct_expr(then_expr)
                } else {
                    self.eval_struct_expr(else_expr)
                }
            }
            Expr::Comma(left, right) => {
                self.eval_discard(left)?;
                self.eval_struct_expr(right)
            }
            Expr::Assign { name, value } => self.eval_struct_assignment_expr(name, value),
            Expr::StructSet {
                name,
                fields,
                value,
            } => self.eval_struct_field_assignment_expr(name, fields, value),
            Expr::StructPtrSet {
                pointer,
                fields,
                value,
            } => self.eval_struct_pointer_field_assignment_expr(pointer, fields, value),
            Expr::ArraySet { name, index, value } => {
                self.eval_struct_index_assignment_expr(name, index, value)
            }
            Expr::StructArraySet {
                name,
                fields,
                index,
                value,
            } if self
                .direct_struct_aggregate_array_field_type(name, fields)?
                .is_some() =>
            {
                self.eval_struct_field_array_element_assignment_expr(name, fields, index, value)
            }
            Expr::StructElementArraySet {
                name,
                index,
                fields,
                array_index,
                value,
            } if matches!(
                self.struct_element_field_metadata(name, fields)?,
                Some((
                    StructFieldType::Pointer(PointeeType::Struct(_))
                        | StructFieldType::StructArray(_, _),
                    _,
                    _
                ))
            ) =>
            {
                if matches!(
                    self.struct_element_field_metadata(name, fields)?,
                    Some((StructFieldType::StructArray(_, _), true, _))
                ) {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(fields)
                    )));
                }
                let pointer = Expr::AddressOfStructElementArrayField {
                    name: name.clone(),
                    index: index.clone(),
                    fields: fields.clone(),
                    array_index: array_index.clone(),
                };
                self.eval_struct_pointer_assignment_expr(&pointer, value)
            }
            Expr::DerefSet { pointer, value } => {
                self.eval_struct_pointer_assignment_expr(pointer, value)
            }
            Expr::AggregateLiteral {
                type_name, init, ..
            } => Ok(ReturnValue::Struct {
                type_name: type_name.clone(),
                fields: self.make_struct_fields(type_name, init)?,
            }),
            Expr::AggregateFieldGet {
                aggregate,
                fields: path,
            } => match self.eval_struct_expr(aggregate)? {
                ReturnValue::Struct { type_name, fields } => {
                    let (_, field_value) = Self::nested_field_value(&type_name, &fields, path)?;
                    match field_value {
                        StructFieldValue::Struct {
                            type_name, fields, ..
                        } => Ok(ReturnValue::Struct {
                            type_name: type_name.clone(),
                            fields: StructFieldValue::deep_clone_fields(fields),
                        }),
                        StructFieldValue::Scalar { .. }
                        | StructFieldValue::Array { .. }
                        | StructFieldValue::StructArray { .. }
                        | StructFieldValue::Pointer { .. } => {
                            Err(CustError::new("expected struct expression"))
                        }
                    }
                }
                _ => Err(CustError::new("expected struct expression")),
            },
            Expr::Var(name) => match self.find_variable(name).cloned() {
                Some(Value::Struct { type_name, fields }) => Ok(ReturnValue::Struct {
                    type_name,
                    fields: StructFieldValue::deep_clone_fields(&fields),
                }),
                Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
                None => Err(CustError::new(format!("undefined variable '{name}'"))),
            },
            Expr::StructGet { name, fields: path } => match self.find_variable(name).cloned() {
                Some(Value::Struct { type_name, fields }) => {
                    let (_, field_value) = Self::nested_field_value(&type_name, &fields, path)?;
                    match field_value {
                        StructFieldValue::Struct {
                            type_name, fields, ..
                        } => Ok(ReturnValue::Struct {
                            type_name: type_name.clone(),
                            fields: StructFieldValue::deep_clone_fields(fields),
                        }),
                        StructFieldValue::Scalar { .. }
                        | StructFieldValue::Array { .. }
                        | StructFieldValue::StructArray { .. }
                        | StructFieldValue::Pointer { .. } => {
                            Err(CustError::new("expected struct expression"))
                        }
                    }
                }
                Some(_) => Err(CustError::new(format!("variable '{name}' is not a struct"))),
                None => Err(CustError::new(format!("undefined variable '{name}'"))),
            },
            Expr::ArrayGet { name, index } => {
                if let Some((type_name, fields)) = self.indexed_struct_pointer_value(name, index)? {
                    Ok(ReturnValue::Struct { type_name, fields })
                } else {
                    let index = self.checked_struct_element_index(name, index)?;
                    match self.find_variable(name).cloned() {
                        Some(Value::StructArray {
                            type_name,
                            elements,
                            ..
                        }) => Ok(ReturnValue::Struct {
                            type_name,
                            fields: StructFieldValue::deep_clone_fields(&elements[index]),
                        }),
                        Some(_) => Err(CustError::new(format!(
                            "variable '{name}' is not a struct array"
                        ))),
                        None => Err(CustError::new(format!("undefined variable '{name}'"))),
                    }
                }
            }
            Expr::StructElementArrayGet { .. } => {
                let pointer = self.eval_pointer(expr)?;
                let (type_name, fields) = self.find_struct_pointer_fields(&pointer)?;
                Ok(ReturnValue::Struct {
                    type_name,
                    fields: StructFieldValue::deep_clone_fields(fields),
                })
            }
            Expr::Deref(pointer) => {
                let pointer = self.eval_pointer(pointer)?;
                let (type_name, fields) = self.find_struct_pointer_fields(&pointer)?;
                Ok(ReturnValue::Struct {
                    type_name,
                    fields: StructFieldValue::deep_clone_fields(fields),
                })
            }
            Expr::Call { name, args } => match self.call_function(name, args)? {
                Some(ReturnValue::Struct { type_name, fields }) => {
                    Ok(ReturnValue::Struct { type_name, fields })
                }
                Some(ReturnValue::Scalar(_)) => Err(CustError::new(format!(
                    "scalar function '{name}' used as struct expression"
                ))),
                Some(ReturnValue::Pointer { .. }) => Err(CustError::new(format!(
                    "pointer function '{name}' used as struct expression"
                ))),
                None => Err(CustError::new(format!(
                    "void function '{name}' used as struct expression"
                ))),
            },
            _ => Err(CustError::new("expected struct expression")),
        }
    }

    fn eval_return_value(&mut self, expr: Option<&Expr>) -> CustResult<Option<ReturnValue>> {
        let Some(expr) = expr else {
            return Ok(None);
        };
        let return_type = self.return_type_stack.last().cloned();
        if matches!(return_type, Some(ReturnType::Void)) {
            self.eval_discard(expr)?;
            return Ok(Some(ReturnValue::Scalar(0)));
        }
        match return_type {
            Some(ReturnType::Struct(_)) => Ok(Some(self.eval_struct_expr(expr)?)),
            Some(ReturnType::Pointer {
                ty,
                points_to_const,
            }) => {
                self.ensure_pointer_conversion_preserves_const(points_to_const, expr)?;
                let pointer = self.eval_pointer(expr)?;
                let pointer = self.attach_array_pointer_owner(pointer);
                self.ensure_pointer_type_matches(&ty, &pointer)?;
                Ok(Some(ReturnValue::Pointer {
                    pointer,
                    ty,
                    points_to_const,
                }))
            }
            Some(ReturnType::Array2DPointer {
                elem_type,
                columns,
                points_to_const,
            }) => {
                self.ensure_pointer_conversion_preserves_const(points_to_const, expr)?;
                let pointer = self.eval_pointer(expr)?;
                let pointer = self.attach_array_pointer_owner(pointer);
                self.ensure_two_dimensional_row_pointer_type_matches(elem_type, columns, &pointer)?;
                Ok(Some(ReturnValue::Pointer {
                    pointer,
                    ty: PointeeType::Scalar(elem_type),
                    points_to_const,
                }))
            }
            Some(ReturnType::Scalar(ty)) => Ok(Some(ReturnValue::Scalar(
                self.eval_scalar_conversion(ty, expr)?,
            ))),
            Some(ReturnType::Void) => {
                unreachable!("void returns are handled before classification")
            }
            None => Ok(Some(ReturnValue::Scalar(self.eval(expr)?))),
        }
    }

    fn static_local_name_and_const(decl: &Stmt) -> CustResult<(&str, bool)> {
        match decl {
            Stmt::VarDecl { name, is_const, .. }
            | Stmt::PointerDecl { name, is_const, .. }
            | Stmt::Array2DPointerDecl { name, is_const, .. }
            | Stmt::ArrayDecl { name, is_const, .. }
            | Stmt::Array2DDecl { name, is_const, .. }
            | Stmt::StructVarDecl { name, is_const, .. }
            | Stmt::StructArrayDecl { name, is_const, .. } => Ok((name, *is_const)),
            _ => Err(CustError::new(
                "static local declarations must declare variables",
            )),
        }
    }

    fn initialize_static_local(&mut self, decl: &Stmt) -> CustResult<Value> {
        match decl {
            Stmt::VarDecl { ty, expr, .. } => Ok(Value::Scalar {
                value: self.eval_scalar_conversion(*ty, expr)?,
                ty: *ty,
            }),
            Stmt::PointerDecl {
                ty,
                expr,
                points_to_const,
                ..
            } => {
                self.ensure_pointer_conversion_preserves_const(*points_to_const, expr)?;
                let pointer = self.eval_pointer(expr)?;
                self.ensure_pointer_type_matches(ty, &pointer)?;
                Ok(Value::Pointer {
                    pointer,
                    ty: ty.clone(),
                    points_to_const: *points_to_const,
                })
            }
            Stmt::Array2DPointerDecl {
                elem_type,
                columns,
                expr,
                points_to_const,
                ..
            } => {
                self.ensure_pointer_conversion_preserves_const(*points_to_const, expr)?;
                let pointer = self.eval_pointer(expr)?;
                self.ensure_two_dimensional_row_pointer_type_matches(
                    *elem_type, *columns, &pointer,
                )?;
                Ok(Value::Pointer {
                    pointer,
                    ty: PointeeType::Scalar(*elem_type),
                    points_to_const: *points_to_const,
                })
            }
            Stmt::ArrayDecl {
                elem_type,
                len,
                init,
                is_const,
                ..
            } => self.make_array_value(*len, *elem_type, init, *is_const),
            Stmt::Array2DDecl {
                elem_type,
                rows,
                columns,
                init,
                is_const,
                ..
            } => {
                self.make_two_dimensional_array_value(*rows, *columns, *elem_type, init, *is_const)
            }
            Stmt::StructVarDecl {
                type_name, init, ..
            } => self.make_struct_value(type_name, init.as_ref()),
            Stmt::StructArrayDecl {
                type_name,
                len,
                init,
                is_const,
                ..
            } => self.make_struct_array_value(type_name, *len, init, *is_const),
            _ => Err(CustError::new(
                "static local declarations must declare variables",
            )),
        }
    }

    fn exec_static_local(&mut self, id: usize, decl: &Stmt) -> CustResult<ExecFlow> {
        let (name, is_const) = Self::static_local_name_and_const(decl)?;
        if self.current_scope_has_identifier(name) {
            return Err(CustError::new(format!(
                "variable '{name}' already declared in this scope"
            )));
        }
        if !self.static_locals.contains_key(&id) {
            let value = self.initialize_static_local(decl)?;
            let scope_id = self.next_scope_id;
            self.next_scope_id += 1;
            self.live_scope_ids.insert(scope_id);
            self.static_locals.insert(
                id,
                StaticLocalStorage {
                    scope_id,
                    name: name.to_string(),
                    value,
                    is_const,
                },
            );
        }
        self.scopes
            .last_mut()
            .expect("exec_block always creates a current scope")
            .static_local_ids
            .insert(name.to_string(), id);
        if let Stmt::Array2DPointerDecl {
            elem_type, columns, ..
        } = decl
        {
            self.mark_current_array2d_pointer_type(name, *elem_type, *columns);
        }
        Ok(ExecFlow::None)
    }

    fn exec_stmt(&mut self, stmt: &Stmt) -> CustResult<ExecFlow> {
        match stmt {
            Stmt::Empty => Ok(ExecFlow::None),
            Stmt::Many(statements) => {
                for statement in statements {
                    match self.exec_stmt(statement)? {
                        ExecFlow::None => {}
                        flow => return Ok(flow),
                    }
                }
                Ok(ExecFlow::None)
            }
            Stmt::StaticLocal { id, decl } => self.exec_static_local(*id, decl),
            Stmt::VarDecl {
                name,
                ty,
                expr,
                is_const,
            } => {
                let value = self.eval_scalar_conversion(*ty, expr)?;
                if self.current_scope_has_identifier(name) {
                    return Err(CustError::new(format!(
                        "variable '{name}' already declared in this scope"
                    )));
                }
                let scope = self.current_scope_mut();
                scope.insert(name.clone(), Value::Scalar { value, ty: *ty });
                if *is_const {
                    self.mark_current_variable_const(name);
                }
                Ok(ExecFlow::None)
            }
            Stmt::PointerDecl {
                name,
                ty,
                expr,
                is_const,
                points_to_const,
            } => {
                self.ensure_pointer_conversion_preserves_const(*points_to_const, expr)?;
                let pointer = self.eval_pointer(expr)?;
                self.ensure_pointer_type_matches(ty, &pointer)?;
                if self.current_scope_has_identifier(name) {
                    return Err(CustError::new(format!(
                        "variable '{name}' already declared in this scope"
                    )));
                }
                let scope = self.current_scope_mut();
                scope.insert(
                    name.clone(),
                    Value::Pointer {
                        pointer,
                        ty: ty.clone(),
                        points_to_const: *points_to_const,
                    },
                );
                if *is_const {
                    self.mark_current_variable_const(name);
                }
                Ok(ExecFlow::None)
            }
            Stmt::Array2DPointerDecl {
                name,
                elem_type,
                columns,
                expr,
                is_const,
                points_to_const,
            } => {
                self.ensure_pointer_conversion_preserves_const(*points_to_const, expr)?;
                let pointer = self.eval_pointer(expr)?;
                self.ensure_two_dimensional_row_pointer_type_matches(
                    *elem_type, *columns, &pointer,
                )?;
                if self.current_scope_has_identifier(name) {
                    return Err(CustError::new(format!(
                        "variable '{name}' already declared in this scope"
                    )));
                }
                self.current_scope_mut().insert(
                    name.clone(),
                    Value::Pointer {
                        pointer,
                        ty: PointeeType::Scalar(*elem_type),
                        points_to_const: *points_to_const,
                    },
                );
                self.mark_current_array2d_pointer_type(name, *elem_type, *columns);
                if *is_const {
                    self.mark_current_variable_const(name);
                }
                Ok(ExecFlow::None)
            }
            Stmt::ArrayDecl {
                name,
                elem_type,
                len,
                init,
                is_const,
            } => {
                if self.current_scope_has_identifier(name) {
                    return Err(CustError::new(format!(
                        "variable '{name}' already declared in this scope"
                    )));
                }
                let value = self.make_array_value(*len, *elem_type, init, *is_const)?;
                self.current_scope_mut().insert(name.clone(), value);
                if *is_const {
                    self.mark_current_variable_const(name);
                }
                Ok(ExecFlow::None)
            }
            Stmt::Array2DDecl {
                name,
                elem_type,
                rows,
                columns,
                init,
                is_const,
            } => {
                if self.current_scope_has_identifier(name) {
                    return Err(CustError::new(format!(
                        "variable '{name}' already declared in this scope"
                    )));
                }
                let value = self.make_two_dimensional_array_value(
                    *rows, *columns, *elem_type, init, *is_const,
                )?;
                self.current_scope_mut().insert(name.clone(), value);
                if *is_const {
                    self.mark_current_variable_const(name);
                }
                Ok(ExecFlow::None)
            }
            Stmt::StructVarDecl {
                type_name,
                name,
                init,
                is_const,
            } => {
                if self.current_scope_has_identifier(name) {
                    return Err(CustError::new(format!(
                        "variable '{name}' already declared in this scope"
                    )));
                }
                let value = self.make_struct_value(type_name, init.as_ref())?;
                self.current_scope_mut().insert(name.clone(), value);
                if *is_const {
                    self.mark_current_variable_const(name);
                }
                Ok(ExecFlow::None)
            }
            Stmt::StructArrayDecl {
                type_name,
                name,
                len,
                init,
                is_const,
            } => {
                if self.current_scope_has_identifier(name) {
                    return Err(CustError::new(format!(
                        "variable '{name}' already declared in this scope"
                    )));
                }
                let value = self.make_struct_array_value(type_name, *len, init, *is_const)?;
                self.current_scope_mut().insert(name.clone(), value);
                if *is_const {
                    self.mark_current_variable_const(name);
                }
                Ok(ExecFlow::None)
            }
            Stmt::EnumDecl { constants } => {
                for constant in constants {
                    self.insert_enum_constant(constant.name.clone(), constant.value)?;
                }
                Ok(ExecFlow::None)
            }
            Stmt::StaticAssert { condition, message } => {
                if self.eval(condition)? != 0 {
                    Ok(ExecFlow::None)
                } else {
                    Err(CustError::new(format!(
                        "static assertion failed: {message}"
                    )))
                }
            }
            Stmt::Assign(name, expr) => {
                let existing = self.find_variable(name).cloned();
                match existing {
                    Some(Value::Scalar { ty, .. }) => {
                        self.ensure_variable_mutable(name)?;
                        let value = self.eval_scalar_conversion(ty, expr)?;
                        if let Some(Value::Scalar { value: slot, .. }) =
                            self.find_variable_mut(name)
                        {
                            *slot = value;
                        }
                        Ok(ExecFlow::None)
                    }
                    Some(Value::Pointer {
                        pointer: current_pointer,
                        ty,
                        points_to_const,
                    }) => {
                        self.ensure_variable_mutable(name)?;
                        self.ensure_pointer_conversion_preserves_const(points_to_const, expr)?;
                        let pointer = self.eval_pointer(expr)?;
                        let pointer = self.attach_array_pointer_owner(pointer);
                        if let PointerValue::Array2DRow { array, .. } = &current_pointer {
                            let array = array.borrow();
                            let Some((_, columns)) = array.dimensions else {
                                return Err(CustError::new(
                                    "internal two-dimensional row pointer storage mismatch",
                                ));
                            };
                            self.ensure_two_dimensional_row_pointer_type_matches(
                                array.elem_type,
                                columns,
                                &pointer,
                            )?;
                        } else {
                            self.ensure_pointer_type_matches(&ty, &pointer)?;
                        }
                        if let Some(Value::Pointer { pointer: slot, .. }) =
                            self.find_variable_mut(name)
                        {
                            *slot = pointer;
                        }
                        Ok(ExecFlow::None)
                    }
                    Some(Value::Array(_)) => Err(CustError::new(format!(
                        "array '{name}' requires indexed assignment"
                    ))),
                    Some(Value::Struct { .. }) => {
                        self.assign_struct_copy(name, expr)?;
                        Ok(ExecFlow::None)
                    }
                    Some(Value::StructArray { .. }) => Err(CustError::new(format!(
                        "struct array '{name}' assignment is not supported"
                    ))),
                    None if self.find_enum_constant(name).is_some() => Err(CustError::new(
                        format!("cannot assign to enum constant '{name}'"),
                    )),
                    None => Err(CustError::new(format!(
                        "assignment to undeclared variable '{name}'"
                    ))),
                }
            }
            Stmt::DerefAssign { pointer, value } => {
                if match pointer {
                    Expr::Var(name) => matches!(
                        self.find_variable(name),
                        Some(Value::Pointer {
                            ty: PointeeType::Struct(_),
                            ..
                        })
                    ),
                    _ => false,
                } {
                    self.assign_struct_pointer_copy(pointer, value)?;
                    return Ok(ExecFlow::None);
                }
                self.ensure_pointer_expr_pointee_mutable(pointer)?;
                let pointee_type = self.pointer_expr_pointee_type(pointer)?;
                let pointer = self.eval_pointer(pointer)?;
                let value = match pointee_type {
                    Some(PointeeType::Scalar(ty)) => self.eval_scalar_conversion(ty, value)?,
                    _ => self.eval(value)?,
                };
                self.assign_deref_pointer(&pointer, value)?;
                Ok(ExecFlow::None)
            }
            Stmt::ArrayAssign { name, index, value } => {
                if let Some(pointer) =
                    self.scalar_variable_reverse_subscript_pointer(name, index)?
                {
                    self.ensure_reverse_subscript_pointee_mutable(index)?;
                    let value = self.eval(value)?;
                    self.assign_deref_pointer(&pointer, value)?;
                    return Ok(ExecFlow::None);
                }
                if matches!(
                    self.find_variable(name),
                    Some(Value::StructArray { .. })
                        | Some(Value::Pointer {
                            ty: PointeeType::Struct(_),
                            ..
                        })
                ) {
                    self.eval_struct_index_assignment_expr(name, index, value)?;
                    return Ok(ExecFlow::None);
                }
                let elem_type = self.scalar_array_element_type(name).ok_or_else(|| {
                    CustError::new(format!(
                        "variable '{name}' is not a scalar array or pointer"
                    ))
                })?;
                let value = self.eval_scalar_conversion(elem_type, value)?;
                match self.find_variable(name).cloned() {
                    Some(Value::Pointer { pointer, .. }) => {
                        self.ensure_pointer_variable_pointee_mutable(name)?;
                        let index_value = self.eval(index)?;
                        self.assign_pointer_index(&pointer, index_value, value)?;
                    }
                    Some(_) | None => {
                        let (array, index) = self.checked_array_index(name, index)?;
                        let mut array = array.borrow_mut();
                        if array.read_only {
                            return Err(CustError::new(format!(
                                "cannot modify read-only array '{name}'"
                            )));
                        }
                        array.elements[index] = value;
                    }
                }
                Ok(ExecFlow::None)
            }
            Stmt::StructAssign {
                name,
                fields,
                value,
            } => {
                if self.struct_field_is_pointer(name, fields) {
                    self.ensure_pointer_conversion_preserves_const(
                        self.struct_pointer_field_points_to_const(name, fields),
                        value,
                    )?;
                    let pointer = self.eval_pointer(value)?;
                    self.assign_direct_struct_pointer_field(name, fields, pointer)?;
                } else {
                    let ty = match self.find_variable(name) {
                        Some(Value::Struct { type_name, .. }) => self
                            .aggregate_type_field_metadata(type_name, fields)?
                            .and_then(|(field_type, _, _)| match field_type {
                                StructFieldType::Scalar(ty) => Some(ty),
                                _ => None,
                            }),
                        _ => None,
                    };
                    let value = match ty {
                        Some(ty) => self.eval_scalar_conversion(ty, value)?,
                        None => self.eval(value)?,
                    };
                    self.assign_struct_field(name, fields, value)?;
                }
                Ok(ExecFlow::None)
            }
            Stmt::Expr(expr) => {
                self.eval_discard(expr)?;
                Ok(ExecFlow::None)
            }
            Stmt::Return(expr) => Ok(ExecFlow::Return(self.eval_return_value(expr.as_ref())?)),
            Stmt::Break(token) => Ok(ExecFlow::Break((**token).clone())),
            Stmt::Continue(token) => Ok(ExecFlow::Continue((**token).clone())),
            Stmt::Block(statements) => self.exec_block(statements),
            Stmt::If {
                cond,
                then_branch,
                else_branch,
            } => {
                if self.eval_truthy(cond)? {
                    self.exec_control_body(then_branch)
                } else {
                    self.exec_control_body(else_branch)
                }
            }
            Stmt::While { cond, body } => {
                let mut iterations = 0usize;
                while self.eval_truthy(cond)? {
                    self.consume_loop_iteration()?;
                    iterations += 1;
                    if iterations > 1_000_000 {
                        return Err(CustError::new("loop iteration limit exceeded"));
                    }
                    match self.exec_control_body(body)? {
                        ExecFlow::None | ExecFlow::Continue(_) => {}
                        ExecFlow::Break(_) => break,
                        ExecFlow::Return(value) => return Ok(ExecFlow::Return(value)),
                    }
                }
                Ok(ExecFlow::None)
            }
            Stmt::DoWhile { body, cond } => self.exec_do_while(body, cond),
            Stmt::For {
                init,
                cond,
                increment,
                body,
            } => self.exec_for(init.as_deref(), cond.as_ref(), increment.as_deref(), body),
            Stmt::Switch { expr, sections } => self.exec_switch(expr, sections),
        }
    }

    fn exec_switch(&mut self, expr: &Expr, sections: &[SwitchSection]) -> CustResult<ExecFlow> {
        let value = self.eval(expr)?;
        let default_index = sections
            .iter()
            .position(|section| matches!(section.label, SwitchLabel::Default));
        let start_index = sections
            .iter()
            .position(|section| matches!(section.label, SwitchLabel::Case(case_value) if case_value == value))
            .or(default_index);

        let Some(start_index) = start_index else {
            return Ok(ExecFlow::None);
        };

        self.push_scope();
        for section in &sections[start_index..] {
            for stmt in &section.statements {
                match self.exec_stmt(stmt) {
                    Ok(ExecFlow::None) => {}
                    Ok(ExecFlow::Break(_)) => {
                        self.pop_scope();
                        return Ok(ExecFlow::None);
                    }
                    Ok(flow) => {
                        self.pop_scope();
                        return Ok(flow);
                    }
                    Err(error) => {
                        self.pop_scope();
                        return Err(error);
                    }
                }
            }
        }
        self.pop_scope();
        Ok(ExecFlow::None)
    }

    fn exec_for(
        &mut self,
        init: Option<&Stmt>,
        cond: Option<&Expr>,
        increment: Option<&Stmt>,
        body: &[Stmt],
    ) -> CustResult<ExecFlow> {
        self.push_scope();
        let result = self.exec_for_in_current_scope(init, cond, increment, body);
        self.pop_scope();
        result
    }

    fn exec_do_while(&mut self, body: &[Stmt], cond: &Expr) -> CustResult<ExecFlow> {
        let mut iterations = 0usize;
        loop {
            self.consume_loop_iteration()?;
            iterations += 1;
            if iterations > 1_000_000 {
                return Err(CustError::new("loop iteration limit exceeded"));
            }

            match self.exec_control_body(body)? {
                ExecFlow::None | ExecFlow::Continue(_) => {}
                ExecFlow::Break(_) => break,
                ExecFlow::Return(value) => return Ok(ExecFlow::Return(value)),
            }

            if !self.eval_truthy(cond)? {
                break;
            }
        }

        Ok(ExecFlow::None)
    }

    fn exec_for_in_current_scope(
        &mut self,
        init: Option<&Stmt>,
        cond: Option<&Expr>,
        increment: Option<&Stmt>,
        body: &[Stmt],
    ) -> CustResult<ExecFlow> {
        if let Some(init) = init {
            match self.exec_stmt(init)? {
                ExecFlow::None => {}
                ExecFlow::Return(value) => return Ok(ExecFlow::Return(value)),
                ExecFlow::Break(token) => {
                    return Err(Self::break_outside_loop_or_switch_error(&token));
                }
                ExecFlow::Continue(token) => return Err(Self::continue_outside_loop_error(&token)),
            }
        }

        let mut iterations = 0usize;
        loop {
            match cond {
                Some(cond) if !self.eval_truthy(cond)? => break,
                Some(_) | None => {}
            }

            self.consume_loop_iteration()?;
            iterations += 1;
            if iterations > 1_000_000 {
                return Err(CustError::new("loop iteration limit exceeded"));
            }

            match self.exec_control_body(body)? {
                ExecFlow::None | ExecFlow::Continue(_) => {}
                ExecFlow::Break(_) => break,
                ExecFlow::Return(value) => return Ok(ExecFlow::Return(value)),
            }

            if let Some(increment) = increment {
                match self.exec_stmt(increment)? {
                    ExecFlow::None => {}
                    ExecFlow::Return(value) => return Ok(ExecFlow::Return(value)),
                    ExecFlow::Break(token) => {
                        return Err(Self::break_outside_loop_or_switch_error(&token));
                    }
                    ExecFlow::Continue(token) => {
                        return Err(Self::continue_outside_loop_error(&token));
                    }
                }
            }
        }

        Ok(ExecFlow::None)
    }

    fn eval(&mut self, expr: &Expr) -> CustResult<i64> {
        match expr {
            Expr::Number(value) => Ok(*value),
            Expr::StringLiteral(_) => Err(CustError::new("string literal used as scalar")),
            Expr::ArrayLiteral { .. }
            | Expr::AggregateArrayLiteral { .. }
            | Expr::PointerCast { .. } => Err(CustError::new("pointer value used as scalar")),
            Expr::StructGet { name, fields } => self.read_struct_field(name, fields),
            Expr::StructArrayGet {
                name,
                fields,
                index,
            } => {
                if let Some(pointer) =
                    self.scalar_field_reverse_subscript_pointer(name, fields, index)?
                {
                    self.deref_pointer(&pointer)
                } else if self.struct_field_is_pointer(name, fields) {
                    let pointer =
                        self.direct_struct_pointer_field_index_pointer(name, fields, index)?;
                    self.deref_pointer(&pointer)
                } else {
                    let (array, index) = self.checked_struct_array_index(name, fields, index)?;
                    Ok(array.borrow().elements[index])
                }
            }
            Expr::StructFieldArrayElementGet {
                name,
                array_fields,
                index,
                fields,
            } => self.read_struct_field_array_element_field(name, array_fields, index, fields),
            Expr::StructFieldArrayElementSet {
                name,
                array_fields,
                index,
                fields,
                value,
            } => {
                let pointer =
                    self.struct_field_array_element_assignment_pointer(name, array_fields, index)?;
                let value = match self.struct_pointer_scalar_field_type(&pointer, fields)? {
                    Some(ty) => self.eval_scalar_conversion(ty, value)?,
                    None => self.eval(value)?,
                };
                self.assign_struct_pointer_field(&pointer, fields, value)?;
                self.read_struct_pointer_field(&pointer, fields)
            }
            Expr::StructFieldArrayElementCompoundSet {
                name,
                array_fields,
                index,
                fields,
                op,
                value,
            } => {
                let pointer =
                    self.struct_field_array_element_assignment_pointer(name, array_fields, index)?;
                let current = self.read_struct_pointer_field(&pointer, fields)?;
                let rhs = self.eval(value)?;
                let result = Self::apply_compound_op(current, *op, rhs)?;
                self.assign_struct_pointer_field(&pointer, fields, result)?;
                self.read_struct_pointer_field(&pointer, fields)
            }
            Expr::StructElementGet {
                name,
                index,
                fields,
            } => self.read_struct_element_field(name, index, fields),
            Expr::StructElementArrayGet {
                name,
                index,
                fields,
                array_index,
            } => {
                if matches!(
                    self.struct_element_field_metadata(name, fields)?,
                    Some((StructFieldType::Pointer(_), _, _))
                ) {
                    let element_pointer = self.indexed_struct_element_pointer(name, index)?;
                    let field_element_pointer = self.struct_pointer_pointer_field_index_pointer(
                        &element_pointer,
                        fields,
                        array_index,
                    )?;
                    self.deref_pointer(&field_element_pointer)
                } else {
                    let (array, index) =
                        self.checked_struct_element_array_index(name, index, fields, array_index)?;
                    Ok(array.borrow().elements[index])
                }
            }
            Expr::StructPtrArrayGet {
                pointer,
                fields,
                index,
            } => {
                let pointer = self.eval_pointer(pointer)?;
                if self
                    .struct_pointer_pointer_field_type(&pointer, fields)?
                    .is_some()
                {
                    let pointer =
                        self.struct_pointer_pointer_field_index_pointer(&pointer, fields, index)?;
                    self.deref_pointer(&pointer)
                } else {
                    let (array, index) =
                        self.checked_struct_pointer_array_index(&pointer, fields, index)?;
                    Ok(array.borrow().elements[index])
                }
            }
            Expr::StructPtrGet { pointer, fields } => {
                let pointer = self.eval_pointer(pointer)?;
                self.read_struct_pointer_field(&pointer, fields)
            }
            Expr::SizeOfType(sizeof_type) => Ok(sizeof_type.size(&self.struct_types)?),
            Expr::SizeOfValue(expr) => self.sizeof_expr(expr),
            Expr::AlignOfType(alignof_type) => Ok(alignof_type.alignment(&self.struct_types)?),
            Expr::Var(name) => self.find_scalar(name),
            Expr::AddressOf(_)
            | Expr::AddressOfArray { .. }
            | Expr::AddressOfStructField { .. }
            | Expr::AddressOfStructElementField { .. }
            | Expr::AddressOfStructArrayField { .. }
            | Expr::AddressOfStructElementArrayField { .. }
            | Expr::AddressOfStructPtrField { .. }
            | Expr::AddressOfStructPtrArrayField { .. }
            | Expr::AddressOfScalarLiteral { .. }
            | Expr::AddressOfAggregateLiteral { .. }
            | Expr::AddressOfAggregateField { .. } => {
                Err(CustError::new("pointer value used as scalar"))
            }
            Expr::Assign { name, value } => self.eval_assignment_expr(name, value),
            Expr::CompoundAssign { name, op, value } => {
                self.eval_compound_assignment_expr(name, *op, value)
            }
            Expr::ScalarLiteralSet { ty, init, value } => {
                self.eval_scalar_conversion(*ty, init)?;
                self.eval_scalar_conversion(*ty, value)
            }
            Expr::ScalarLiteralCompoundSet {
                ty,
                init,
                op,
                value,
            } => {
                let current = self.eval_scalar_conversion(*ty, init)?;
                let rhs = self.eval(value)?;
                Ok(ty.normalize(Self::apply_compound_op(current, *op, rhs)?))
            }
            Expr::AggregateFieldSet {
                aggregate,
                fields,
                value,
            } => {
                let (_, ty, is_const) =
                    self.eval_aggregate_literal_field_scalar(aggregate, fields)?;
                if is_const {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(fields)
                    )));
                }
                self.eval_scalar_conversion(ty, value)
            }
            Expr::AggregateFieldCompoundSet {
                aggregate,
                fields,
                op,
                value,
            } => {
                let (current, ty, is_const) =
                    self.eval_aggregate_literal_field_scalar(aggregate, fields)?;
                if is_const {
                    return Err(CustError::new(format!(
                        "cannot assign to const struct field '{}'",
                        Self::field_path_label(fields)
                    )));
                }
                let rhs = self.eval(value)?;
                Ok(ty.normalize(Self::apply_compound_op(current, *op, rhs)?))
            }
            Expr::Increment { target, op, prefix } => {
                self.eval_increment_expr(target, *op, *prefix)
            }
            Expr::ArraySet { name, index, value } => {
                if let Some(pointer) =
                    self.scalar_variable_reverse_subscript_pointer(name, index)?
                {
                    self.ensure_reverse_subscript_pointee_mutable(index)?;
                    let value = self.eval(value)?;
                    self.assign_deref_pointer(&pointer, value)?;
                    return Ok(value);
                }
                if matches!(
                    self.find_variable(name),
                    Some(Value::StructArray { .. })
                        | Some(Value::Pointer {
                            ty: PointeeType::Struct(_),
                            ..
                        })
                ) {
                    return Err(CustError::new("struct value used as scalar expression"));
                }
                let elem_type = self.scalar_array_element_type(name).ok_or_else(|| {
                    CustError::new(format!(
                        "variable '{name}' is not a scalar array or pointer"
                    ))
                })?;
                let value = self.eval_scalar_conversion(elem_type, value)?;
                match self.find_variable(name).cloned() {
                    Some(Value::Pointer { pointer, .. }) => {
                        self.ensure_pointer_variable_pointee_mutable(name)?;
                        let index_value = self.eval(index)?;
                        self.assign_pointer_index(&pointer, index_value, value)?;
                    }
                    Some(_) | None => {
                        let (array, index) = self.checked_array_index(name, index)?;
                        let mut array = array.borrow_mut();
                        if array.read_only {
                            return Err(CustError::new(format!(
                                "cannot modify read-only array '{name}'"
                            )));
                        }
                        array.elements[index] = value;
                    }
                }
                Ok(value)
            }
            Expr::ArrayCompoundSet {
                name,
                index,
                op,
                value,
            } => self.eval_array_compound_set(name, index, *op, value),
            Expr::Array2DSet {
                name,
                row,
                column,
                value,
            } => {
                let (array, index) = self.checked_two_dimensional_array_index(name, row, column)?;
                self.ensure_two_dimensional_array_mutable(name)?;
                let elem_type = array.borrow().elem_type;
                let value = self.eval_scalar_conversion(elem_type, value)?;
                let mut array = array.borrow_mut();
                if array.read_only {
                    return Err(CustError::new(format!(
                        "cannot modify read-only array '{name}'"
                    )));
                }
                array.elements[index] = value;
                Ok(value)
            }
            Expr::Array2DCompoundSet {
                name,
                row,
                column,
                op,
                value,
            } => {
                let (array, index) = self.checked_two_dimensional_array_index(name, row, column)?;
                self.ensure_two_dimensional_array_mutable(name)?;
                let current = array.borrow().elements[index];
                let elem_type = array.borrow().elem_type;
                let rhs = self.eval(value)?;
                let result = elem_type.normalize(Self::apply_compound_op(current, *op, rhs)?);
                let mut array = array.borrow_mut();
                if array.read_only {
                    return Err(CustError::new(format!(
                        "cannot modify read-only array '{name}'"
                    )));
                }
                array.elements[index] = result;
                Ok(result)
            }
            Expr::StructArray2DSet {
                target,
                row,
                column,
                value,
            } => {
                self.ensure_two_dimensional_struct_field_target_mutable(target)?;
                let (array, index) =
                    self.checked_two_dimensional_struct_field_index(target, row, column)?;
                let elem_type = array.borrow().elem_type;
                let value = self.eval_scalar_conversion(elem_type, value)?;
                let mut array = array.borrow_mut();
                if array.read_only {
                    return Err(CustError::new("cannot modify read-only array field"));
                }
                array.elements[index] = value;
                Ok(value)
            }
            Expr::StructArray2DCompoundSet {
                target,
                row,
                column,
                op,
                value,
            } => {
                self.ensure_two_dimensional_struct_field_target_mutable(target)?;
                let (array, index) =
                    self.checked_two_dimensional_struct_field_index(target, row, column)?;
                let current = array.borrow().elements[index];
                let elem_type = array.borrow().elem_type;
                let rhs = self.eval(value)?;
                let result = elem_type.normalize(Self::apply_compound_op(current, *op, rhs)?);
                let mut array = array.borrow_mut();
                if array.read_only {
                    return Err(CustError::new("cannot modify read-only array field"));
                }
                array.elements[index] = result;
                Ok(result)
            }
            Expr::StructArraySet {
                name,
                fields,
                index,
                value,
            } => self.eval_struct_array_set(name, fields, index, value),
            Expr::StructElementSet {
                name,
                index,
                fields,
                value,
            } => {
                let ty = self.struct_element_field_metadata(name, fields)?.and_then(
                    |(field_type, _, _)| match field_type {
                        StructFieldType::Scalar(ty) => Some(ty),
                        _ => None,
                    },
                );
                let value = match ty {
                    Some(ty) => self.eval_scalar_conversion(ty, value)?,
                    None => self.eval(value)?,
                };
                self.assign_struct_element_field(name, index, fields, value)?;
                self.read_struct_element_field(name, index, fields)
            }
            Expr::StructElementArraySet {
                name,
                index,
                fields,
                array_index,
                value,
            } => {
                if let Some((StructFieldType::Pointer(pointee_type), _, points_to_const)) =
                    self.struct_element_field_metadata(name, fields)?
                {
                    if points_to_const {
                        return Err(CustError::new("cannot assign through pointer to const"));
                    }
                    let value = match pointee_type {
                        PointeeType::Scalar(ty) => self.eval_scalar_conversion(ty, value)?,
                        PointeeType::Struct(_) => self.eval(value)?,
                    };
                    let element_pointer = self.indexed_struct_element_pointer(name, index)?;
                    let field_element_pointer = self.struct_pointer_pointer_field_index_pointer(
                        &element_pointer,
                        fields,
                        array_index,
                    )?;
                    self.assign_deref_pointer(&field_element_pointer, value)?;
                    self.deref_pointer(&field_element_pointer)
                } else {
                    self.ensure_struct_element_array_field_mutable(name, fields)?;
                    let (array, index) =
                        self.checked_struct_element_array_index(name, index, fields, array_index)?;
                    let elem_type = array.borrow().elem_type;
                    let value = self.eval_scalar_conversion(elem_type, value)?;
                    let mut array = array.borrow_mut();
                    if array.read_only {
                        return Err(CustError::new(format!(
                            "cannot modify read-only array '{}'",
                            Self::field_path_label(fields)
                        )));
                    }
                    array.elements[index] = value;
                    Ok(value)
                }
            }
            Expr::StructArrayCompoundSet {
                name,
                fields,
                index,
                op,
                value,
            } => self.eval_struct_array_compound_set(name, fields, index, *op, value),
            Expr::StructElementCompoundSet {
                name,
                index,
                fields,
                op,
                value,
            } => {
                let current = self.read_struct_element_field(name, index, fields)?;
                let rhs = self.eval(value)?;
                let result = Self::apply_compound_op(current, *op, rhs)?;
                self.assign_struct_element_field(name, index, fields, result)?;
                self.read_struct_element_field(name, index, fields)
            }
            Expr::StructElementArrayCompoundSet {
                name,
                index,
                fields,
                array_index,
                op,
                value,
            } => {
                if let Some((StructFieldType::Pointer(_), _, points_to_const)) =
                    self.struct_element_field_metadata(name, fields)?
                {
                    if points_to_const {
                        return Err(CustError::new("cannot assign through pointer to const"));
                    }
                    let element_pointer = self.indexed_struct_element_pointer(name, index)?;
                    let field_element_pointer = self.struct_pointer_pointer_field_index_pointer(
                        &element_pointer,
                        fields,
                        array_index,
                    )?;
                    let current = self.deref_pointer(&field_element_pointer)?;
                    let rhs = self.eval(value)?;
                    let result = Self::apply_compound_op(current, *op, rhs)?;
                    self.assign_deref_pointer(&field_element_pointer, result)?;
                    self.deref_pointer(&field_element_pointer)
                } else {
                    self.ensure_struct_element_array_field_mutable(name, fields)?;
                    let (array, index) =
                        self.checked_struct_element_array_index(name, index, fields, array_index)?;
                    let current = array.borrow().elements[index];
                    let rhs = self.eval(value)?;
                    let elem_type = array.borrow().elem_type;
                    let result = elem_type.normalize(Self::apply_compound_op(current, *op, rhs)?);
                    let mut array = array.borrow_mut();
                    if array.read_only {
                        return Err(CustError::new(format!(
                            "cannot modify read-only array '{}'",
                            Self::field_path_label(fields)
                        )));
                    }
                    array.elements[index] = result;
                    Ok(result)
                }
            }
            Expr::DerefSet { pointer, value } => {
                self.ensure_pointer_expr_pointee_mutable(pointer)?;
                let pointee_type = self.pointer_expr_pointee_type(pointer)?;
                let pointer = self.eval_pointer(pointer)?;
                let value = match pointee_type {
                    Some(PointeeType::Scalar(ty)) => self.eval_scalar_conversion(ty, value)?,
                    _ => self.eval(value)?,
                };
                self.assign_deref_pointer(&pointer, value)?;
                self.deref_pointer(&pointer)
            }
            Expr::DerefCompoundSet { pointer, op, value } => {
                self.eval_deref_compound_set(pointer, *op, value)
            }
            Expr::StructSet {
                name,
                fields,
                value,
            } => self.eval_struct_set(name, fields, value),
            Expr::StructPtrSet {
                pointer,
                fields,
                value,
            } => self.eval_struct_ptr_set(pointer, fields, value),
            Expr::StructCompoundSet {
                name,
                fields,
                op,
                value,
            } => self.eval_struct_compound_set(name, fields, *op, value),
            Expr::StructPtrCompoundSet {
                pointer,
                fields,
                op,
                value,
            } => self.eval_struct_ptr_compound_set(pointer, fields, *op, value),
            Expr::Deref(pointer) => {
                let pointer = self.eval_pointer(pointer)?;
                self.deref_pointer(&pointer)
            }
            Expr::ArrayGet { name, index } => {
                if let Some(pointer) =
                    self.scalar_variable_reverse_subscript_pointer(name, index)?
                {
                    self.deref_pointer(&pointer)
                } else {
                    match self.find_variable(name).cloned() {
                        Some(Value::Pointer { .. }) => {
                            let (array, _, index) = self.checked_pointer_index(name, index)?;
                            Ok(array.borrow().elements[index])
                        }
                        Some(_) | None => {
                            let (array, index) = self.checked_array_index(name, index)?;
                            Ok(array.borrow().elements[index])
                        }
                    }
                }
            }
            Expr::Array2DGet { name, row, column } => {
                let (array, index) = self.checked_two_dimensional_array_index(name, row, column)?;
                Ok(array.borrow().elements[index])
            }
            Expr::StructArray2DGet {
                target,
                row,
                column,
            } => {
                let (array, index) =
                    self.checked_two_dimensional_struct_field_index(target, row, column)?;
                Ok(array.borrow().elements[index])
            }
            Expr::StringGet { values, index } => {
                let index_value = self.eval(index)?;
                let Ok(index) = usize::try_from(index_value) else {
                    return Err(CustError::new(format!(
                        "string literal index {index_value} out of bounds for length {}",
                        values.len()
                    )));
                };
                values.get(index).copied().ok_or_else(|| {
                    CustError::new(format!(
                        "string literal index {index_value} out of bounds for length {}",
                        values.len()
                    ))
                })
            }
            Expr::Call { name, args } => match self.call_function(name, args)? {
                Some(ReturnValue::Scalar(value)) => Ok(value),
                Some(ReturnValue::Pointer { .. }) => Err(CustError::new(format!(
                    "pointer function '{name}' used as scalar expression"
                ))),
                Some(ReturnValue::Struct { type_name, .. }) => {
                    let aggregate_kind = self.aggregate_kind_label(&type_name);
                    Err(CustError::new(format!(
                        "{aggregate_kind} function '{name}' used as scalar expression"
                    )))
                }
                None => Err(CustError::new(format!(
                    "void function '{name}' used as scalar expression"
                ))),
            },
            Expr::Cast { ty, expr } => self.eval_scalar_conversion(*ty, expr),
            Expr::VoidCast(expr) => {
                self.eval_discard(expr)?;
                Err(CustError::new("void expression used as scalar"))
            }
            Expr::ScalarLiteral { ty, init } => self.eval_scalar_conversion(*ty, init),
            Expr::AggregateLiteral { type_name, .. } => {
                let aggregate_kind = self.aggregate_kind_label(type_name);
                Err(CustError::new(format!(
                    "{aggregate_kind} value used as scalar"
                )))
            }
            Expr::AggregateFieldGet {
                aggregate,
                fields: path,
            } => self
                .eval_aggregate_literal_field_scalar(aggregate, path)
                .map(|(value, _, _)| value),
            Expr::UnaryPlus(inner) => self.eval(inner),
            Expr::UnaryMinus(inner) => Ok(-self.eval(inner)?),
            Expr::BitwiseNot(inner) => Ok(!self.eval(inner)?),
            Expr::LogicalNot(inner) => Ok((!self.eval_truthy(inner)?) as i64),
            Expr::Conditional {
                cond,
                then_expr,
                else_expr,
            } => {
                if self.eval_truthy(cond)? {
                    self.eval(then_expr)
                } else {
                    self.eval(else_expr)
                }
            }
            Expr::Comma(left, right) => {
                self.eval_discard(left)?;
                self.eval(right)
            }
            Expr::Binary(left, op, right) => match op {
                BinaryOp::LogicalAnd => {
                    if !self.eval_truthy(left)? {
                        Ok(0)
                    } else {
                        Ok(self.eval_truthy(right)? as i64)
                    }
                }
                BinaryOp::LogicalOr => {
                    if self.eval_truthy(left)? {
                        Ok(1)
                    } else {
                        Ok(self.eval_truthy(right)? as i64)
                    }
                }
                BinaryOp::Eq | BinaryOp::Ne => self.eval_equality(left, op, right),
                BinaryOp::Add | BinaryOp::Sub => {
                    if self.expr_is_pointer_value(left) || self.expr_is_pointer_value(right) {
                        match (self.eval_pointer(left), self.eval_pointer(right)) {
                            (Ok(left_pointer), Ok(right_pointer)) if *op == BinaryOp::Sub => {
                                return self.pointer_difference(&left_pointer, &right_pointer);
                            }
                            (Ok(_), Ok(_)) if *op == BinaryOp::Add => {
                                return Err(CustError::new("cannot add two pointers"));
                            }
                            (Ok(_), Err(_)) | (Err(_), Ok(_)) => {
                                return Err(CustError::new("pointer value used as scalar"));
                            }
                            (Err(error), Err(_)) => return Err(error),
                            (Ok(_), Ok(_)) => {}
                        }
                    }
                    let lhs = self.eval(left)?;
                    let rhs = self.eval(right)?;
                    match op {
                        BinaryOp::Add => Ok(lhs + rhs),
                        BinaryOp::Sub => Ok(lhs - rhs),
                        _ => unreachable!("only addition/subtraction handled in this branch"),
                    }
                }
                BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge => {
                    self.eval_ordering(left, op, right)
                }
                BinaryOp::ShiftLeft
                | BinaryOp::ShiftRight
                | BinaryOp::BitAnd
                | BinaryOp::BitXor
                | BinaryOp::BitOr => {
                    if self.expr_is_pointer_value(left) || self.expr_is_pointer_value(right) {
                        return Err(CustError::new(
                            "pointer bitwise operations are not supported",
                        ));
                    }
                    let lhs = self.eval(left)?;
                    let rhs = self.eval(right)?;
                    match op {
                        BinaryOp::BitAnd => Ok(lhs & rhs),
                        BinaryOp::BitXor => Ok(lhs ^ rhs),
                        BinaryOp::BitOr => Ok(lhs | rhs),
                        BinaryOp::ShiftLeft => Self::checked_shift_left(lhs, rhs),
                        BinaryOp::ShiftRight => Self::checked_shift_right(lhs, rhs),
                        _ => unreachable!("only bitwise operators handled in this branch"),
                    }
                }
                BinaryOp::Mul | BinaryOp::Div | BinaryOp::Rem => {
                    let lhs = self.eval(left)?;
                    let rhs = self.eval(right)?;
                    match op {
                        BinaryOp::Mul => Ok(lhs * rhs),
                        BinaryOp::Div if rhs == 0 => Err(CustError::new("division by zero")),
                        BinaryOp::Div => Ok(lhs / rhs),
                        BinaryOp::Rem if rhs == 0 => Err(CustError::new("division by zero")),
                        BinaryOp::Rem => Ok(lhs % rhs),
                        _ => unreachable!("only multiplicative operators handled in this branch"),
                    }
                }
            },
        }
    }
}
